/// Publishes each visited root into a checked type store.
const CheckedTypeRootPublisher = struct {
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    source_schemes: *collections.DenseMap(Var, CheckedTypeSchemeId),
    local_type_declarations: *const LocalTypeDeclarationIndex,

    /// Publish one root.
    pub fn visit(self: *const CheckedTypeRootPublisher, var_: Var) Allocator.Error!void {
        _ = try appendCheckedTypeRoot(self.allocator, self.module, self.store, self.active, var_);
    }

    /// Publish a root checking must have recorded.
    pub fn visitRequired(self: *const CheckedTypeRootPublisher, maybe_var: ?Var, comptime missing: []const u8) Allocator.Error!void {
        try self.visit(maybe_var orelse checkedArtifactInvariant(missing, .{}));
    }

    /// Publish one root and the source scheme it owns.
    pub fn visitScheme(self: *const CheckedTypeRootPublisher, var_: Var) Allocator.Error!void {
        const root = try appendCheckedTypeRoot(self.allocator, self.module, self.store, self.active, var_);
        try self.store.publishSourceScheme(self.allocator, self.module, self.source_schemes, var_, root);
    }

    /// Publish a local nominal declaration and the roots its annotation names.
    pub fn visitNominalDeclaration(self: *const CheckedTypeRootPublisher, statement_idx: CIR.Statement.Idx, nominal: NominalDeclStatement) Allocator.Error!void {
        try appendCheckedNominalDeclarationFromStatement(
            self.allocator,
            self.module,
            self.names,
            self.imports,
            self.store,
            self.active,
            self.local_type_declarations,
            statement_idx,
            nominal.header,
            nominal.anno,
            nominal.is_opaque,
        );
    }
};

/// The payload of a nominal declaration statement.
pub const NominalDeclStatement = @FieldType(CIR.Statement, "s_nominal_decl");

/// The source inputs that select a module's checked source type roots.
pub const CheckedSourceTypeRootInputs = struct {
    module_index: *const ModuleIndex,
    selected_hoisted_roots: []const hoist_roots.SelectedHoistedRoot,
    promoted_local_procedures: []const hoist_roots.PromotedLocalProcedure,
};

/// Every source type root of a module's checked type publication, in
/// publication order. Type publication and the sealed type view
/// (`sealed_type_view.zig`) both enumerate roots here, so the two cannot
/// disagree on the root set. A visitor provides `visit(Var)`,
/// `visitRequired(?Var, comptime []const u8)` (as `output_type_roots`
/// visitors do), `visitScheme(Var)` for a root that owns a source scheme, and
/// `visitNominalDeclaration(CIR.Statement.Idx, NominalDeclStatement)` for a
/// local nominal declaration statement.
pub fn forEachCheckedSourceTypeRoot(
    module: TypedCIR.Module,
    inputs: CheckedSourceTypeRootInputs,
    visitor: anytype,
) Allocator.Error!void {
    const module_index = inputs.module_index;
    const module_env = module.moduleEnvConst();

    var node_idx: u32 = 0;
    while (node_idx < module.nodeCount()) : (node_idx += 1) {
        // Every reached expr/pattern node gets a published type root,
        // because the body reader reports each one's type. That includes
        // nodes checking rewrote to runtime errors (tag `.malformed`, e.g.
        // via ambiguity poisoning): their type vars are real, and the body
        // reader still reports them so the user-facing diagnostics survive
        // to reporting.
        switch (module_index.nodeKind(node_idx)) {
            .expr => {
                const expr_idx: CIR.Expr.Idx = @fromBackingInt(@intCast(node_idx));
                try visitor.visit(module.exprType(expr_idx));
                try output_type_roots.forEachCallTypeRoot(module_env, expr_idx, visitor);
            },
            .pattern => {
                const pattern_idx: CIR.Pattern.Idx = @fromBackingInt(@intCast(node_idx));
                try visitor.visit(if (module_index.topLevelDef(pattern_idx)) |def| module.defType(def) else module.patternType(pattern_idx));
            },
            .statement, .unreached => {},
        }
    }

    // Static-dispatch evidence resolves constrained scheme instantiations
    // after type publication. Publish each recorded fresh variable now so
    // evidence nodes can name the exact concrete dispatcher type by a
    // checked type id rather than retaining checker-only variables.
    // Explicit scheme requirements may be absent from the public callable.
    // Publish their roots before the evidence schema names them.
    try output_type_roots.forEachRecordedTypeRoot(module_env, visitor);
    for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
        if (!module_index.reachesStatement(statement_idx)) continue;
        switch (module.getStatement(statement_idx)) {
            .s_alias_decl => try visitor.visit(ModuleEnv.varFrom(statement_idx)),
            .s_nominal_decl => |nominal| try visitor.visitNominalDeclaration(statement_idx, nominal),
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => {},
        }
    }

    for (module.requiresTypes()) |required_type| {
        try visitor.visitScheme(ModuleEnv.varFrom(required_type.type_anno));

        const aliases = module_env.for_clause_aliases.sliceRange(required_type.type_aliases);
        for (aliases) |alias| {
            const alias_statement = module_env.store.getStatement(alias.alias_stmt_idx);
            if (alias_statement != .s_alias_decl) {
                checkedArtifactInvariant("platform for-clause alias metadata referenced a non-alias statement", .{});
            }
            try visitor.visit(ModuleEnv.varFrom(alias.alias_stmt_idx));
            try visitor.visit(ModuleEnv.varFrom(alias_statement.s_alias_decl.anno));
        }
    }

    try forEachStaticDispatchTypeRoot(module, module_index, visitor);

    // Evidence nodes retain exact checked callable instantiations. Publish
    // every fresh type participating in a recorded scheme use, including
    // the constraint function that identifies a selected dispatch target
    // or a per-use where-method callable.
    try output_type_roots.forEachSchemeUseTypeRoot(module_env, visitor);

    // A row-coerced result's coercion node has its widening copy's type;
    // the expression's own node keeps its own type
    // (`ModuleEnv.RowCoercedResult`).
    for (module_env.row_coerced_results.items.items) |result| {
        try visitor.visit(@fromBackingInt(result.wide_var));
    }

    for (module_env.store.sliceDefs(module_env.global_value_defs)) |def_idx| {
        try visitor.visitScheme(module.defType(def_idx));
    }

    // Selected roots own source schemes just like ordinary top-level
    // values. Publish them explicitly so const and callable templates can
    // name the exact scheme without relying on an unrelated definition
    // having the same canonical key.
    for (inputs.selected_hoisted_roots) |selected| {
        try visitor.visitScheme(if (selected.pattern) |pattern|
            ModuleEnv.varFrom(pattern)
        else
            module.exprType(selected.expr));
    }

    // A promoted local function is a procedure of its own, published
    // under its binding's generalized scheme like a top-level function.
    for (inputs.promoted_local_procedures) |promoted| {
        try visitor.visitScheme(ModuleEnv.varFrom(promoted.pattern));
    }
}

/// Public `ModuleEnvStorage` declaration.
pub const ModuleEnvStorage = union(enum) {
    checked_source: *ModuleEnv,
    static_builtin: *ModuleEnv,
    /// An environment relocated in place inside a loaded cache entry, which
    /// also backs the module's artifact. The storage owns the entry and the
    /// source; `release_entry` releases the entry with the env's allocator.
    cached_entry: struct {
        env: *ModuleEnv,
        entry: []align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8,
        release_entry: *const fn ([]align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8, Allocator) void,
        source: []const u8,
    },

    pub fn env(self: *const ModuleEnvStorage) *ModuleEnv {
        return switch (self.*) {
            .checked_source => |module_env| module_env,
            .static_builtin => |module_env| module_env,
            .cached_entry => |cached| cached.env,
        };
    }

    pub fn envConst(self: *const ModuleEnvStorage) *const ModuleEnv {
        return self.env();
    }

    pub fn deinit(self: *ModuleEnvStorage) void {
        switch (self.*) {
            .checked_source => |module_env| {
                const env_alloc = module_env.gpa;
                const source = module_env.common.source;
                module_env.deinit();
                if (source.len > 0) env_alloc.free(@constCast(source));
                env_alloc.destroy(module_env);
            },
            .static_builtin => |module_env| {
                module_env.common.idents.deinitTextRanks();
                module_env.gpa.destroy(module_env);
            },
            .cached_entry => |cached| {
                const env_alloc = cached.env.gpa;
                cached.env.deinitCachedModule();
                if (cached.source.len > 0) env_alloc.free(@constCast(cached.source));
                env_alloc.destroy(cached.env);
                cached.release_entry(cached.entry, env_alloc);
            },
        }
        self.* = undefined;
    }
};

/// Public `CheckedModuleArtifactKey` declaration: the checked module's
/// identity hash and nothing else, so its bits are its identity and every
/// keyed container agrees with `eql`. The hash inputs live on the artifact
/// (`CheckedModuleArtifact.source_hash`, `module_identity`,
/// `checking_context_identity`, `direct_import_module_keys`). `extern` so it
/// can be a POD inline field of `CheckedModuleArtifact.Serialized`.
pub const CheckedModuleArtifactKey = extern struct {
    bytes: [32]u8 = @as([32]u8, @splat(0)),

    /// Integer equality over the key's identity bytes: a single 256-bit
    /// compare, never a byte-wise comparison.
    pub fn eql(a: CheckedModuleArtifactKey, b: CheckedModuleArtifactKey) bool {
        return @as(u256, @bitCast(a.bytes)) == @as(u256, @bitCast(b.bytes));
    }

    /// The digest that references to this artifact carry. The constituent
    /// hashes live once, on the artifact's own key.
    pub fn digest(self: CheckedModuleArtifactKey) CheckedModuleDigest {
        return .{ .bytes = self.bytes };
    }

    pub fn compute(
        source: []const u8,
        module_identity: ModuleIdentity,
        checking_context_identity: CheckingContextIdentity,
        direct_import_module_keys: []const CheckedModuleArtifactKey,
    ) CheckedModuleArtifactKey {
        return computeFromSourceHash(
            hashBytes(source),
            module_identity,
            checking_context_identity,
            direct_import_module_keys,
        );
    }

    pub fn computeFromSourceHash(
        source_hash: [32]u8,
        module_identity: ModuleIdentity,
        checking_context_identity: CheckingContextIdentity,
        direct_import_module_keys: []const CheckedModuleArtifactKey,
    ) CheckedModuleArtifactKey {
        return computeFromIdentityHash(source_hash, hashModuleIdentity(module_identity), checking_context_identity, direct_import_module_keys);
    }

    pub fn computeFromIdentityHash(
        source_hash: [32]u8,
        module_identity_hash: [32]u8,
        checking_context_identity: CheckingContextIdentity,
        direct_import_module_keys: []const CheckedModuleArtifactKey,
    ) CheckedModuleArtifactKey {
        return .{ .bytes = computeCheckedArtifactKeyBytes(
            source_hash,
            module_identity_hash,
            hashCheckingContextIdentity(checking_context_identity),
            hashDirectImportArtifactKeys(direct_import_module_keys),
        ) };
    }
};

/// Stable identifier for a checked module: its artifact's identity digest.
pub const ModuleId = CheckedModuleDigest;

fn computeCheckedArtifactKeyBytes(
    source_hash: [32]u8,
    module_identity_hash: [32]u8,
    checking_context_identity_hash: [32]u8,
    direct_import_module_keys_hash: [32]u8,
) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hasher.update(&source_hash);
    hasher.update(&module_identity_hash);
    hasher.update(&checking_context_identity_hash);
    hasher.update(&direct_import_module_keys_hash);
    return hasher.finalResult();
}

test "checked artifact key is a function of the program alone" {
    const source_hash = @as([32]u8, @splat(1));
    const module_identity_hash = @as([32]u8, @splat(2));
    const import_key = CheckedModuleArtifactKey{ .bytes = @as([32]u8, @splat(3)) };
    const checking_context = CheckingContextIdentity{};

    var expected = base.Sha256.init(.{});
    expected.update(&source_hash);
    expected.update(&module_identity_hash);
    expected.update(&hashCheckingContextIdentity(checking_context));
    expected.update(&hashDirectImportArtifactKeys(&.{import_key}));

    const key = CheckedModuleArtifactKey.computeFromIdentityHash(
        source_hash,
        module_identity_hash,
        checking_context,
        &.{import_key},
    );
    try std.testing.expectEqualSlices(u8, &expected.finalResult(), &key.bytes);
}

/// Public `ModuleIdentity` declaration.
pub const ModuleIdentity = struct {
    stable_hash: [32]u8 = @as([32]u8, @splat(0)),
    module_idx: u32,
    module_name: canonical.ModuleNameId,
    display_module_name: canonical.ModuleNameId,
    kind: ModuleEnv.ModuleKind,
};

/// Public `ImportIdentity` declaration.
pub const ImportIdentity = struct {
    import_name_hash: [32]u8 = @as([32]u8, @splat(0)),
    artifact_key: ?CheckedModuleArtifactKey = null,
};

fn hashBytes(bytes: []const u8) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hasher.update(bytes);
    return hasher.finalResult();
}

fn hashU32(hasher: anytype, value: u32) void {
    hasher.update(&.{
        @as(u8, @truncate(value)),
        @as(u8, @truncate(value >> 8)),
        @as(u8, @truncate(value >> 16)),
        @as(u8, @truncate(value >> 24)),
    });
}

fn hashByteSlice(hasher: anytype, bytes: []const u8) void {
    hashU32(hasher, @intCast(bytes.len));
    hasher.update(bytes);
}

fn hashModuleSourceInputs(module_env: *const ModuleEnv) [32]u8 {
    const deps = module_env.file_dependencies.items.items;
    if (deps.len == 0) {
        return hashBytes(module_env.getSourceAll());
    }

    var hasher = base.Sha256.init(.{});
    hashByteSlice(&hasher, "roc-module-source-inputs-v2");
    hashByteSlice(&hasher, module_env.getSourceAll());
    hashU32(&hasher, @intCast(deps.len));
    for (deps) |dep| {
        hashByteSlice(&hasher, module_env.fileDependencyRelativePath(dep));
        hasher.update(&.{@backingInt(dep.state)});
        switch (dep.state) {
            .present => hasher.update(&dep.content_hash),
            .missing, .unreadable => {},
            .pending => unreachable, // the canonicalize task settles every file dependency before source inputs are hashed
        }
    }
    return hasher.finalResult();
}

fn hashModuleIdentity(identity: ModuleIdentity) [32]u8 {
    return identity.stable_hash;
}

/// A module's identity hash IS its deep content identity: a pure function of
/// the transitive closure's module names and source bytes (see
/// `base.module_identity`). No coordinator-assigned display strings, package
/// names, or paths participate—cache keys and serialized identities are
/// bit-identical no matter which pipeline built the artifact or what
/// directory the build ran in.
fn computeStableModuleIdentityHash(module_env: *const ModuleEnv) [32]u8 {
    const hash = module_env.contentIdentityHash() orelse {
        base.invariant(
            "checked artifact identity requested before module content identity was finalized for module '{s}'",
            .{module_env.module_name},
        );
    };
    return hash.*;
}

fn hashCheckingContextIdentity(identity: CheckingContextIdentity) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hashCheckingContextPolicy(&hasher, identity, true);
    return hasher.finalResult();
}

/// The digest of the checking inputs of a module that its imports' and its
/// app pairing's implementations do not reach: its imports' names, explicit
/// root requests, validation mode and platform requirement context.
pub fn checkingContextPolicyHash(identity: CheckingContextIdentity) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hashCheckingContextPolicy(&hasher, identity, false);
    return hasher.finalResult();
}

fn hashCheckingContextPolicy(hasher: *base.Sha256, identity: CheckingContextIdentity, include_keys: bool) void {
    if (identity.platform_requirement_context) |context| {
        hasher.update(&[_]u8{1});
        hasher.update(&context.bytes);
    } else {
        hasher.update(&[_]u8{0});
    }
    if (include_keys) {
        if (identity.platform_app_relation) |relation| {
            hasher.update(&[_]u8{1});
            hasher.update(&relation.bytes);
        } else {
            hasher.update(&[_]u8{0});
        }
    }
    hashU32(hasher, @intCast(identity.imports.len));
    for (identity.imports) |import_identity| {
        hasher.update(&import_identity.import_name_hash);
        if (!include_keys) continue;
        if (import_identity.artifact_key) |key| {
            hasher.update(&[_]u8{1});
            hasher.update(&key.bytes);
        } else {
            hasher.update(&[_]u8{0});
        }
    }
    hashU32(hasher, @intCast(identity.explicit_roots.len));
    for (identity.explicit_roots) |root| {
        hashExplicitRootRequestInput(hasher, root);
    }
    hashByteSlice(hasher, @tagName(identity.validation));
}

fn hashExplicitRootRequestInput(
    hasher: *base.Sha256,
    root: ExplicitRootRequestInput,
) void {
    hashByteSlice(hasher, @tagName(root.kind));
    hashRootSource(hasher, root.source);
    hashByteSlice(hasher, @tagName(root.abi));
    hashByteSlice(hasher, @tagName(root.exposure));
}

fn hashRootSource(hasher: *base.Sha256, source: RootSource) void {
    hashByteSlice(hasher, @tagName(source));
    switch (source) {
        inline .def, .expr, .statement => |idx| hashU32(hasher, @backingInt(idx)),
        .required_binding => |idx| hashU32(hasher, idx),
        .hoisted => |hoisted| {
            hashU32(hasher, hoisted.index);
            hashU32(hasher, @backingInt(hoisted.expr));
        },
        .literal => |literal| {
            hashByteSlice(hasher, @tagName(literal));
            hashU32(hasher, literal.node());
        },
    }
}

fn hashDirectImportArtifactKeys(keys: []const CheckedModuleArtifactKey) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hashU32(&hasher, @intCast(keys.len));
    for (keys) |key| hasher.update(&key.bytes);
    return hasher.finalResult();
}

/// Public `PlatformRequirementContextKey` declaration.
pub const PlatformRequirementContextKey = struct {
    bytes: [32]u8 = @as([32]u8, @splat(0)),

    pub fn compute(
        platform_identity: ModuleIdentity,
        platform_required_declarations_hash: [32]u8,
    ) PlatformRequirementContextKey {
        return computeFromParts(
            hashModuleIdentity(platform_identity),
            platform_required_declarations_hash,
        );
    }

    /// Compute the requirement context directly from the platform module's stable
    /// content-identity hash and the identity hash of its required declarations.
    /// `compute` folds these same two inputs through a `ModuleIdentity`, so the two
    /// entry points always agree byte-for-byte.
    pub fn computeFromParts(
        platform_content_identity_hash: [32]u8,
        platform_required_declarations_hash: [32]u8,
    ) PlatformRequirementContextKey {
        var hasher = base.Sha256.init(.{});
        hasher.update(&platform_content_identity_hash);
        hasher.update(&platform_required_declarations_hash);
        return .{ .bytes = hasher.finalResult() };
    }
};

/// Public `CheckingContextIdentity` declaration.
pub const CheckingContextIdentity = struct {
    imports: []ImportIdentity = &.{},
    platform_requirement_context: ?PlatformRequirementContextKey = null,
    platform_app_relation: ?PlatformAppRelationKey = null,
    explicit_roots: []const ExplicitRootRequestInput = &.{},
    /// How the module's compile-time roots were established. An app root
    /// checked without its entrypoint contract reports no problem for a
    /// platform requirement it does not supply, so two compilations of the
    /// same source that disagree here produce different checked output and
    /// must not share a cache entry.
    validation: can.Can.Validation = .checking,

    pub const Serialized = extern struct {
        imports: SerializedSlice(ImportIdentity) = .{},
        explicit_roots: SerializedSlice(ExplicitRootRequestInput) = .{},
        platform_requirement_context: artifact_serialize.SerializedOptional(PlatformRequirementContextKey) = .{},
        platform_app_relation: artifact_serialize.SerializedOptional(PlatformAppRelationKey) = .{},
        validation: artifact_serialize.SerializedScalar(can.Can.Validation, .checking) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(CheckingContextIdentity, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        module_env: *const ModuleEnv,
        publish_imports: []const PublishImportArtifact,
        platform_requirement_context: ?PlatformRequirementContextKey,
        platform_app_relation: ?PlatformAppRelationKey,
        explicit_roots: []const ExplicitRootRequestInput,
        validation: can.Can.Validation,
    ) Allocator.Error!CheckingContextIdentity {
        const imported_names = module_env.imports.imports.items.items;
        const imports = try allocator.alloc(ImportIdentity, imported_names.len);
        errdefer allocator.free(imports);
        const roots = try allocator.dupe(ExplicitRootRequestInput, explicit_roots);
        errdefer allocator.free(roots);

        for (imported_names, 0..) |str_idx, i| {
            const import_idx: CIR.Import.Idx = @fromBackingInt(@intCast(@as(u32, @intCast(i))));
            const resolved_module_idx = module_env.imports.getResolvedModule(import_idx);
            imports[i] = .{
                .import_name_hash = hashBytes(module_env.getString(str_idx)),
                .artifact_key = if (resolved_module_idx) |resolved|
                    publishImportKeyForModule(publish_imports, resolved)
                else
                    null,
            };
        }

        return .{
            .imports = imports,
            .platform_requirement_context = platform_requirement_context,
            .platform_app_relation = platform_app_relation,
            .explicit_roots = roots,
            .validation = validation,
        };
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;
};

/// Public `PublishImportArtifact` declaration.
pub const PublishImportArtifact = struct {
    module_idx: u32,
    key: CheckedModuleArtifactKey,
    view: ImportedModuleView,
};

/// The checked artifacts a module's publication resolves named types against.
pub const CheckedImportViews = struct {
    current_owner: ModuleId,
    direct: []const PublishImportArtifact,
    available: []const ImportedModuleView = &.{},
    /// Platform relation modules: registry-visible for dispatch resolution
    /// even though they are neither imported nor in `available`.
    relations: []const ImportedModuleView = &.{},

    fn viewForKey(self: CheckedImportViews, key: ModuleId) ?ImportedModuleView {
        const view = dependencyViewByKey(key, self.direct, self.available, self.relations) orelse return null;
        return view.*;
    }

    /// A resolver over these views.
    pub fn resolver(self: *const CheckedImportViews) ModuleResolver {
        return .{ .context = self, .resolve_fn = resolveImportView };
    }

    fn resolveImportView(context: *const anyopaque, key: ModuleId) ?ImportedModuleView {
        const self: *const CheckedImportViews = @ptrCast(@alignCast(context));
        return self.viewForKey(key);
    }
};

/// Finds the checked module a module id names, for an analysis that reads
/// modules other than its own. A resolver resolves every module of the build.
pub const ModuleResolver = struct {
    context: *const anyopaque,
    resolve_fn: *const fn (context: *const anyopaque, key: ModuleId) ?ImportedModuleView,

    pub fn resolve(self: ModuleResolver, key: ModuleId) ?ImportedModuleView {
        return self.resolve_fn(self.context, key);
    }

    /// The module `key` names, which the resolver must resolve.
    fn require(self: ModuleResolver, key: ModuleId) ImportedModuleView {
        return self.resolve(key) orelse checkedArtifactInvariant("a module analysis named a module its resolver does not resolve", .{});
    }
};

/// Checked artifacts that must be available to consume this module's public API.
/// This is semantic visibility, not lexical import visibility. A per-module
/// analysis (`ModuleAnalyses.publicApiDependencies`).
pub const PublicApiDependencies = struct {
    artifacts: []const ModuleId = &.{},
    type_owner_artifacts: []const ModuleId = &.{},

    pub fn deinit(self: *PublicApiDependencies, allocator: Allocator) void {
        allocator.free(self.artifacts);
        allocator.free(self.type_owner_artifacts);
        self.* = .{};
    }
};

/// Checked artifacts that must be materialized for post-check lowering of this
/// artifact's roots. A per-module analysis (`ModuleAnalyses.loweringVisibility`).
pub const LoweringVisibility = struct {
    module_ids: []const ModuleId = &.{},

    pub fn deinit(self: *LoweringVisibility, allocator: Allocator) void {
        allocator.free(self.module_ids);
        self.* = .{};
    }
};

/// Ordered checked-module registries visible to method lookup after the
/// current module's local registry. Checking owns this ordering, and later
/// stages consume the published scope directly.
/// The import views method-target lookup searches after the local registry,
/// in search order: the available views a platform relation or direct import
/// does not supersede, the platform-relation views, then the direct-import
/// views. (Snapshot-style compiles pass the builtin module only as a direct
/// import, so searching `available` alone misses every builtin-owned method.)
fn methodLookupViews(allocator: Allocator, import_views: CheckedImportViews) Allocator.Error![]const *const ImportedModuleView {
    var views = try std.ArrayList(*const ImportedModuleView).initCapacity(
        allocator,
        import_views.available.len + import_views.relations.len + import_views.direct.len,
    );
    errdefer views.deinit(allocator);
    for (import_views.available) |*available| {
        if (moduleViewIsSuperseded(available, import_views.relations, import_views.direct)) continue;
        views.appendAssumeCapacity(available);
    }
    for (import_views.relations) |*relation| views.appendAssumeCapacity(relation);
    for (import_views.direct) |*import| views.appendAssumeCapacity(&import.view);
    return try views.toOwnedSlice(allocator);
}

/// Give `analyses` the modules its dispatch resolution searches, in
/// method-lookup order, and return their keys
/// (`CheckedModuleArtifact.dispatch_view_keys`).
fn dispatchViewKeys(allocator: Allocator, analyses: *ModuleAnalyses, import_views: CheckedImportViews) Allocator.Error![]ModuleId {
    const lookup_views = try methodLookupViews(allocator, import_views);
    defer allocator.free(lookup_views);
    const views = try allocator.alloc(ImportedModuleView, lookup_views.len);
    defer allocator.free(views);
    const keys = try allocator.alloc(ModuleId, lookup_views.len);
    errdefer allocator.free(keys);
    for (lookup_views, views, keys) |view, *copy, *key| {
        copy.* = view.*;
        key.* = view.key.digest();
    }
    try analyses.setDispatchImports(views);
    return keys;
}

/// Give a loaded artifact's analyses the modules its dispatch resolution
/// searches: the modules its `dispatch_view_keys` name, which `resolver`
/// resolves.
pub fn attachDispatchImports(analyses: *ModuleAnalyses, dispatch_view_keys: []const ModuleId, resolver: ModuleResolver) Allocator.Error!void {
    const allocator = analyses.allocator;
    const views = try allocator.alloc(ImportedModuleView, dispatch_view_keys.len);
    defer allocator.free(views);
    for (dispatch_view_keys, views) |key, *view| view.* = resolver.require(key);
    try analyses.setDispatchImports(views);
}

fn moduleViewIsSuperseded(
    view: *const ImportedModuleView,
    relation_artifacts: []const ImportedModuleView,
    direct_imports: []const PublishImportArtifact,
) bool {
    for (relation_artifacts) |*relation| {
        if (base.ModuleIdentity.eql(&view.module_identity.stable_hash, &relation.module_identity.stable_hash) and
            !CheckedModuleArtifactKey.eql(view.key, relation.key)) return true;
    }
    for (direct_imports) |*direct| {
        if (base.ModuleIdentity.eql(&view.module_identity.stable_hash, &direct.view.module_identity.stable_hash) and
            !CheckedModuleArtifactKey.eql(view.key, direct.key)) return true;
    }
    return false;
}

/// Public `PublishInputs` declaration.
pub const PublishInputs = struct {
    module_env_storage: ModuleEnvStorage,
    /// Waits on the module's key slots when another thread is computing a key.
    io: std.Io,
    imports: []const PublishImportArtifact = &.{},
    available_artifacts: []const ImportedModuleView = &.{},
    relation_artifacts: []const ImportedModuleView = &.{},
    platform_requirement_context: ?PlatformRequirementContextKey = null,
    platform_app_relation: ?PlatformAppRelation = null,
    explicit_roots: []const ExplicitRootRequestInput = &.{},
    /// Which of the compile-time roots checking selected
    /// (`ModuleEnv.selected_hoisted_roots`) the artifact evaluates.
    hoisted_roots: HoistedRootSelection = .selected,
    compile_time_finalizer: CompileTimeFinalizer,
    /// Prepared metadata may serve frontend imports; evaluation and cache publication wait.
    evaluation_phase: enum { immediate, post_frontend } = .immediate,
    problem_store: ?*problem.Store = null,
    validation: can.Can.Validation = .checking,
};

/// Which of a module's checker-selected compile-time roots its artifact
/// evaluates.
pub const HoistedRootSelection = enum {
    /// Every root checking selected.
    selected,
    /// Only the roots that materialize a top-level binding.
    top_level,
    none,
};

/// The checker-selected compile-time roots `selection` keeps, in selection
/// order. The caller owns the returned slice.
fn selectHoistedRoots(
    allocator: Allocator,
    module_env: *const ModuleEnv,
    selection: HoistedRootSelection,
) Allocator.Error![]hoist_roots.SelectedHoistedRoot {
    const selected = module_env.selected_hoisted_roots.items.items;
    var kept = try std.ArrayList(hoist_roots.SelectedHoistedRoot).initCapacity(allocator, selected.len);
    errdefer kept.deinit(allocator);
    for (selected) |root| {
        const keep = switch (selection) {
            .selected => true,
            .top_level => root.top_level,
            .none => false,
        };
        if (keep) kept.appendAssumeCapacity(root);
    }
    return try kept.toOwnedSlice(allocator);
}

/// Public `CompileTimeFinalizer` declaration.
pub const CompileTimeFinalizer = struct {
    pub const Error = Allocator.Error || std.Thread.SpawnError || error{
        RuntimeError,
        /// The embedder abandoned the compilation (see `Options.cancel_request`
        /// in compile-time finalization).
        Canceled,
        EmptyCode,
        MmapFailed,
        MprotectFailed,
        UnsupportedPlatform,
        UnwindRegistrationFailed,
        VirtualAllocFailed,
        VirtualProtectFailed,
    };

    context: ?*anyopaque = null,
    finalize: *const fn (
        context: ?*anyopaque,
        allocator: Allocator,
        artifact: *CheckedModuleArtifact,
        imports: []const PublishImportArtifact,
        available_artifacts: []const ImportedModuleView,
        relation_artifacts: []const ImportedModuleView,
        problem_store: ?*problem.Store,
    ) Error!void,

    pub fn run(
        self: CompileTimeFinalizer,
        allocator: Allocator,
        artifact: *CheckedModuleArtifact,
        imports: []const PublishImportArtifact,
        available_artifacts: []const ImportedModuleView,
        relation_artifacts: []const ImportedModuleView,
        problem_store: ?*problem.Store,
    ) Error!void {
        try self.finalize(self.context, allocator, artifact, imports, available_artifacts, relation_artifacts, problem_store);
    }
};

