/// Public `RootRequest` declaration.
pub const RootRequest = struct {
    order: u32,
    /// Producer-selected root withheld until the platform has its app bindings.
    requires_pairing: bool = false,
    /// This session borrows a previously evaluated root from its platform.
    evaluation_complete: bool = false,
    /// Full same-module evaluation order, including withheld roots.
    evaluation_order: ?u32 = null,
    module_idx: u32,
    kind: RootRequestKind,
    source: RootSource,
    /// Exact `provides` declaration for a published procedure root.
    provided_export: OptionalId(ProvidedExportId) = .none,
    /// Exact checked root selected for this request. Compile-time roots can
    /// share a source expression, so source and broad request kind are not an
    /// identity.
    compile_time_root: ?ComptimeRootId = null,
    checked_type: CheckedTypeId,
    abi: RootAbi,
    exposure: RootExposure,
    procedure_template: ?canonical.ProcedureTemplateRef = null,
    procedure_binding: ?TopLevelProcedureBindingRef = null,
    procedure_use: ?ProcedureUseTemplate = null,
    root_evidence: ?CheckedEvidenceSpan = null,
};

/// Public `RootRequestTable` declaration.
pub const RootRequestTable = struct {
    requests: []RootRequest = &.{},
    runtime_requests: []RootRequest = &.{},
    /// Compile-time requests sorted by same-module stored-constant
    /// dependencies. This slice is the durable same-module compile-time
    /// evaluation schedule consumed by checking finalization; temporary
    /// dependency edges used to compute it are not stored.
    compile_time_requests: []RootRequest = &.{},

    pub const Serialized = extern struct {
        requests: SerializedSlice(RootRequest) = .{},
        runtime_requests: SerializedSlice(RootRequest) = .{},
        compile_time_requests: SerializedSlice(RootRequest) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(RootRequestTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;
};

/// The root requests of `owner` (`ModuleAnalyses.rootRequests`): its explicit
/// roots, its provided and exposed entrypoints, its platform-required
/// bindings, and its eligible compile-time roots (the root table's rows, then
/// each unit's literal conversion roots, then each literal component's
/// argument roots), with the compile-time requests in evaluation order. A
/// platform/app pairing's are its platform's (`platform_requests`), read at
/// the pairing's types, with the pairing's bindings added.
pub fn computeRootRequests(allocator: Allocator, owner: ImportedModuleView, platform_requests: ?*const RootRequestTable) Allocator.Error!*RootRequestTable {
    const result = try allocator.create(RootRequestTable);
    errdefer allocator.destroy(result);
    result.* = if (platform_requests) |platform|
        try pairingRootRequests(allocator, owner, platform)
    else
        try moduleRootRequests(allocator, owner);
    return result;
}

fn moduleRootRequests(allocator: Allocator, owner: ImportedModuleView) Allocator.Error!RootRequestTable {
    const env = owner.module_env;
    const module_idx = owner.module_identity.module_idx;
    const dispatch = owner.dispatch();
    const bodies = owner.checked_bodies;
    const context = owner.checking_context_identity;
    const compile_time_roots = owner.compile_time_roots;
    const procedure_templates = owner.checked_procedure_templates;
    const entry_wrappers = owner.entry_wrappers;
    var requests = std.ArrayList(RootRequest).empty;
    errdefer requests.deinit(allocator);

    for (context.explicit_roots) |root| {
        if (!explicitRootMatchesCheckedRootKind(procedure_templates, compile_time_roots, root)) continue;
        if (!explicitCompileTimeRootRequestIsEligible(compile_time_roots, root)) continue;
        const source_checked_type = checkedTypeIdForRootSource(env, bodies, root.source);
        const backing = explicitRootBackingProcedure(
            procedure_templates,
            compile_time_roots,
            entry_wrappers,
            root.source,
            root.kind,
            source_checked_type,
        );
        try appendRoot(&requests, allocator, .{
            .module_idx = module_idx,
            .kind = root.kind,
            .source = root.source,
            .compile_time_root = backing.compile_time_root,
            .checked_type = backing.checked_type,
            .abi = root.abi,
            .exposure = root.exposure,
            .procedure_template = backing.template,
        });
    }

    try appendPublishedEntrypointRoots(
        &requests,
        allocator,
        module_idx,
        env,
        bodies,
        owner.provided_exports,
        owner.top_level_values,
        owner.top_level_procedure_bindings,
        context.platform_app_relation,
        owner.platform_required_declarations,
        context.validation,
    );

    for (owner.platform_required_bindings.bindings, 0..) |binding, i| {
        switch (binding.value_use) {
            .procedure_value => |procedure_use| try appendRoot(&requests, allocator, .{
                .module_idx = module_idx,
                .kind = .platform_required_binding,
                .source = .{ .required_binding = @intCast(i) },
                .checked_type = platformRequiredBindingCheckedType(binding),
                .abi = .platform,
                .exposure = .platform_required,
                .procedure_use = procedure_use.procedure,
                .root_evidence = procedure_use.root_evidence,
            }),
            .const_value => {},
        }
    }

    for (compile_time_roots.roots) |root| {
        if (!compileTimeRootRequestIsEligible(root)) continue;
        if (compileTimeCallableRootIsProcedureReference(bodies, owner.resolved_value_refs, root)) continue;
        if (compileTimeRootHasRootRequest(requests.items, root)) continue;
        try appendRoot(&requests, allocator, .{
            .module_idx = root.module_idx,
            .kind = switch (root.kind) {
                .constant, .hoisted_constant, .hoisted_validation, .numeral_conversion, .quote_conversion, .literal_argument => .compile_time_constant,
                .callable_binding => .compile_time_callable,
                .expect => .test_expect,
                .repl_expr => .repl_expr,
            },
            .source = root.source,
            .compile_time_root = root.id,
            .checked_type = entryWrapperForRoot(entry_wrappers, root.id).checked_fn_root,
            .abi = switch (root.kind) {
                .expect => .test_expect,
                .constant, .hoisted_constant, .hoisted_validation, .callable_binding, .numeral_conversion, .quote_conversion, .repl_expr, .literal_argument => .compile_time,
            },
            .exposure = .private,
            .procedure_template = templateForEntryWrapperRoot(entry_wrappers, root.id),
        });
    }

    // The literal roots: each unit's conversion roots, then each literal
    // component's argument roots.
    const literal_proc_base = procedure_templates.literal_root_proc_base;
    for (0..dispatch.source.module_index.units.len) |unit| {
        const conversions = try dispatch.source.analyses.unitLiteralConversions(dispatch, @fromBackingInt(@intCast(unit)));
        for (conversions.records) |*record| try appendLiteralRootRequest(&requests, allocator, owner.key.digest(), literal_proc_base, record);
    }
    {
        const graph = try dispatch.literalGraph();
        for (0..graph.components.count()) |component| {
            const done = try dispatch.source.analyses.literalComponent(dispatch, graph, @intCast(component));
            for (done.roots) |*record| try appendLiteralRootRequest(&requests, allocator, owner.key.digest(), literal_proc_base, record);
        }
    }

    for (requests.items) |*request| {
        if (request.root_evidence != null) continue;
        const template_ref = request.procedure_template orelse
            aliasRootWrapperTemplate(request.*, owner.top_level_procedure_bindings, owner.callable_eval_templates, entry_wrappers) orelse
            continue;
        if (!template_ref.artifact.eql(owner.key.digest())) {
            checkedArtifactInvariant("root procedure template belonged to a different checked artifact", .{});
        }
        request.root_evidence = .{
            .checked_module = owner.key.digest(),
            .span = (try dispatch.templateRootEvidenceSpan(template_ref.template)) orelse
                checkedArtifactInvariant("uninstantiated generic codec procedure was selected as a root", .{}),
        };
    }

    const all_requests = try requests.toOwnedSlice(allocator);
    errdefer allocator.free(all_requests);

    if (!env.topLevelDemandDependenciesReady()) {
        checkedArtifactInvariant("checked module had no top-level demand dependencies", .{});
    }
    const full_schedule = try collectCompileTimeRootRequests(
        allocator,
        all_requests,
        owner.platform_required_declarations.declarations.len != 0,
        module_idx,
        owner.key,
        env.topLevelDemandDependencies(),
        compile_time_roots,
        procedure_templates,
        dispatch,
        owner.resolved_value_refs,
        owner.top_level_procedure_bindings,
        owner.platform_required_bindings,
        owner.callable_eval_templates,
        owner.hoisted_constants,
        owner.const_templates,
    );
    defer allocator.free(full_schedule);
    try verifyCompileTimeRequestsScheduled(full_schedule, dispatch);
    var active_schedule = std.ArrayList(RootRequest).empty;
    errdefer active_schedule.deinit(allocator);
    var evaluation_order: u32 = 0;
    for (full_schedule) |request| {
        all_requests[request.order].requires_pairing = request.requires_pairing;
        if (request.abi != .compile_time) continue;
        all_requests[request.order].evaluation_order = evaluation_order;
        evaluation_order += 1;
        if (!request.requires_pairing) try active_schedule.append(allocator, all_requests[request.order]);
    }
    const compile_time_requests = try active_schedule.toOwnedSlice(allocator);
    errdefer allocator.free(compile_time_requests);

    const runtime_requests = try collectRuntimeRootRequests(allocator, all_requests);

    return .{
        .requests = all_requests,
        .runtime_requests = runtime_requests,
        .compile_time_requests = compile_time_requests,
    };
}

/// A literal root's request, when it may be one.
fn appendLiteralRootRequest(
    requests: *std.ArrayList(RootRequest),
    allocator: Allocator,
    owner: canonical.ArtifactRef,
    proc_base: canonical.ProcBaseKeyRef,
    record: *const LiteralRootRecord,
) Allocator.Error!void {
    if (!compileTimeRootRequestIsEligible(record.root)) return;
    try appendRoot(requests, allocator, .{
        .module_idx = record.root.module_idx,
        .kind = .compile_time_constant,
        .source = record.root.source,
        .compile_time_root = record.root.id,
        .checked_type = record.checked_fn_root,
        .abi = .compile_time,
        .exposure = .private,
        .procedure_template = .{
            .artifact = owner,
            .proc_base = proc_base,
            .template = literalRootWrapperTemplate(record.root.id),
        },
    });
}

/// A platform/app pairing's root requests: its platform's, at the
/// pairing's types, without the callable roots its bindings make exact
/// procedure references, and with its platform-required bindings' roots. A
/// request the platform evaluated without the app is complete.
fn pairingRootRequests(allocator: Allocator, owner: ImportedModuleView, platform: *const RootRequestTable) Allocator.Error!RootRequestTable {
    const bodies = owner.checked_bodies;
    var roots = std.ArrayList(RootRequest).empty;
    errdefer roots.deinit(allocator);
    for (platform.requests) |request| {
        // Once a required procedure is bound, an exact callable alias uses
        // the same forwarding rule as a module with resolved imports.
        // Runtime demand consumes its checked lookup; no evaluator is needed.
        if (request.requires_pairing and request.compile_time_root != null) {
            if (request.compile_time_root.?.rowIndex() != null and
                compileTimeCallableRootIsProcedureReference(bodies, owner.resolved_value_refs, owner.compile_time_roots.root(request.compile_time_root.?))) continue;
        }
        var selected = request;
        selected.order = @intCast(roots.items.len);
        selected.evaluation_complete = request.abi == .compile_time and !request.requires_pairing;
        selected.requires_pairing = false;
        selected.checked_type = pairingRootRequestType(owner, request);
        try roots.append(allocator, selected);
    }
    for (owner.platform_required_bindings.bindings, 0..) |binding, i| switch (binding.value_use) {
        .procedure_value => |procedure| try appendRoot(&roots, allocator, .{
            .module_idx = owner.module_identity.module_idx,
            .kind = .platform_required_binding,
            .source = .{ .required_binding = @intCast(i) },
            .checked_type = platformRequiredBindingCheckedType(binding),
            .abi = .platform,
            .exposure = .platform_required,
            .procedure_use = procedure.procedure,
            .root_evidence = procedure.root_evidence,
        }),
        .const_value => {},
    };
    const requests = try roots.toOwnedSlice(allocator);
    errdefer allocator.free(requests);
    const runtime_requests = try collectRuntimeRootRequests(allocator, requests);
    errdefer allocator.free(runtime_requests);
    var schedule = std.ArrayList(RootRequest).empty;
    errdefer schedule.deinit(allocator);
    for (requests) |request| {
        if (request.evaluation_order != null and !request.evaluation_complete) try schedule.append(allocator, request);
    }
    std.mem.sort(RootRequest, schedule.items, {}, struct {
        fn lessThan(_: void, a: RootRequest, b: RootRequest) bool {
            return a.evaluation_order.? < b.evaluation_order.?;
        }
    }.lessThan);
    return .{
        .requests = requests,
        .runtime_requests = runtime_requests,
        .compile_time_requests = try schedule.toOwnedSlice(allocator),
    };
}

/// A platform root request's type under a pairing: the pairing's entry
/// wrapper or provided export type, or the pairing's image of its source's
/// type. A literal root is closed and keeps its wrapper's type.
fn pairingRootRequestType(owner: ImportedModuleView, request: RootRequest) CheckedTypeId {
    if (request.compile_time_root) |root| {
        if (root.rowIndex() == null) return request.checked_type;
        return entryWrapperForRoot(owner.entry_wrappers, root).checked_fn_root;
    }
    if (request.provided_export.get()) |provided| return switch (owner.provided_exports.exports[@backingInt(provided)]) {
        inline .procedure, .data => |value| value.checked_type,
    };
    return switch (request.source) {
        .def, .expr, .statement => checkedTypeIdForRootSource(owner.module_env, owner.checked_bodies, request.source),
        .required_binding, .hoisted, .literal => request.checked_type,
    };
}

fn explicitRootMatchesCheckedRootKind(
    procedure_templates: *const CheckedProcedureTemplateTable,
    compile_time_roots: *const CompileTimeRootTable,
    root: ExplicitRootRequestInput,
) bool {
    if (procedureTemplateForRootSource(procedure_templates, root.source) != null) {
        return root.kind != .compile_time_constant and root.kind != .compile_time_callable;
    }

    return compileTimeRootIdForSourceAndRequestKind(compile_time_roots, root.source, root.kind) != null;
}

fn explicitCompileTimeRootRequestIsEligible(
    compile_time_roots: *const CompileTimeRootTable,
    root: ExplicitRootRequestInput,
) bool {
    const root_id = compileTimeRootIdForSourceAndRequestKind(compile_time_roots, root.source, root.kind) orelse return true;
    const compile_time_root = compile_time_roots.root(root_id);
    return compileTimeRootRequestIsEligible(compile_time_root);
}

fn compileTimeRootIdForSourceAndRequestKind(
    compile_time_roots: *const CompileTimeRootTable,
    source: RootSource,
    request_kind: RootRequestKind,
) ?ComptimeRootId {
    for (compile_time_roots.roots) |root| {
        if (!rootSourceMatches(root.source, source)) continue;
        if (!compileTimeRootKindMatchesRequest(root.kind, request_kind)) continue;
        return root.id;
    }
    return null;
}

fn collectRuntimeRootRequests(
    allocator: Allocator,
    requests: []const RootRequest,
) Allocator.Error![]RootRequest {
    var runtime_requests = std.ArrayList(RootRequest).empty;
    errdefer runtime_requests.deinit(allocator);

    for (requests) |request| {
        if (request.abi == .compile_time or request.requires_pairing) continue;
        try runtime_requests.append(allocator, request);
    }

    return try runtime_requests.toOwnedSlice(allocator);
}

const CompileTimeRequestScheduleEntry = struct {
    request: RootRequest,
    root_id: ComptimeRootId,
    original_order: u32,
};

/// Every compile-time request in evaluation order. In a module that declares
/// platform requirements (`include_expects`) each `expect` root is among them:
/// an expect evaluates at runtime and no root depends on one, so it changes no
/// other root's place, and scheduling it lets binding dependence reach it, as
/// an expect that reads a requirement cannot run until the platform has its app.
fn collectCompileTimeRootRequests(
    allocator: Allocator,
    requests: []const RootRequest,
    include_expects: bool,
    module_idx: u32,
    artifact_key: CheckedModuleArtifactKey,
    top_level_demand_dependencies: []const TopLevelDemandDependency,
    compile_time_roots: *const CompileTimeRootTable,
    procedure_templates: *const CheckedProcedureTemplateTable,
    dispatch: CheckedDispatch,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    callable_eval_templates: CallableEvalTemplateTableView,
    hoisted_constants: *const HoistedConstTable,
    const_templates: *const ConstTemplateTable,
) Allocator.Error![]RootRequest {
    var entries = std.ArrayList(CompileTimeRequestScheduleEntry).empty;
    defer entries.deinit(allocator);

    for (requests) |request| {
        if (request.abi != .compile_time and !(include_expects and request.abi == .test_expect)) continue;
        const root_id = try compileTimeRootIdForRequest(dispatch, request);
        try entries.append(allocator, .{
            .request = request,
            .root_id = root_id,
            .original_order = @intCast(entries.items.len),
        });
    }

    var scheduler = try CompileTimeRequestScheduler.init(
        allocator,
        module_idx,
        artifact_key,
        top_level_demand_dependencies,
        compile_time_roots,
        procedure_templates,
        dispatch,
        resolved_value_refs,
        top_level_procedure_bindings,
        platform_required_bindings,
        callable_eval_templates,
        hoisted_constants,
        const_templates,
        entries.items,
    );
    defer scheduler.deinit();

    return try scheduler.sortedRequests();
}

const CompileTimeRequestScheduler = struct {
    allocator: Allocator,
    module_idx: u32,
    artifact_key: CheckedModuleArtifactKey,
    top_level_demand_dependencies: []const TopLevelDemandDependency,
    compile_time_roots: *const CompileTimeRootTable,
    procedure_templates: *const CheckedProcedureTemplateTable,
    dispatch: CheckedDispatch,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    callable_eval_templates: CallableEvalTemplateTableView,
    hoisted_constants: *const HoistedConstTable,
    const_templates: *const ConstTemplateTable,
    entries: []CompileTimeRequestScheduleEntry,
    root_to_request_index: std.AutoHashMapUnmanaged(ComptimeRootId, usize) = .empty,
    dependents: []std.ArrayList(usize),
    pairing_dependents: []std.ArrayList(usize),
    indegrees: []u32,
    emitted: []bool,
    visited_templates: []u32,
    /// The visit stamp of each literal root's entry wrapper the walk entered.
    visited_literal_wrappers: std.AutoHashMapUnmanaged(ComptimeRootId, u32) = .empty,
    literal_demand: std.ArrayList(ComptimeRootId) = .empty,
    seen_edges: std.AutoHashMap(u64, void),
    visit: u32 = 0,
    current_request_index: usize = 0,
    current_root_id: ComptimeRootId = undefined, // Set before dependency collection for each scheduled root.

    fn init(
        allocator: Allocator,
        module_idx: u32,
        artifact_key: CheckedModuleArtifactKey,
        top_level_demand_dependencies: []const TopLevelDemandDependency,
        compile_time_roots: *const CompileTimeRootTable,
        procedure_templates: *const CheckedProcedureTemplateTable,
        dispatch: CheckedDispatch,
        resolved_value_refs: *const ResolvedValueRefTable,
        top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        callable_eval_templates: CallableEvalTemplateTableView,
        hoisted_constants: *const HoistedConstTable,
        const_templates: *const ConstTemplateTable,
        entries: []CompileTimeRequestScheduleEntry,
    ) Allocator.Error!CompileTimeRequestScheduler {
        var root_to_request_index: std.AutoHashMapUnmanaged(ComptimeRootId, usize) = .empty;
        errdefer root_to_request_index.deinit(allocator);

        const dependents = try allocator.alloc(std.ArrayList(usize), entries.len);
        errdefer allocator.free(dependents);
        for (dependents) |*list| list.* = .empty;

        const pairing_dependents = try allocator.alloc(std.ArrayList(usize), entries.len);
        errdefer allocator.free(pairing_dependents);
        for (pairing_dependents) |*list| list.* = .empty;

        const indegrees = try allocator.alloc(u32, entries.len);
        errdefer allocator.free(indegrees);
        @memset(indegrees, 0);

        const emitted = try allocator.alloc(bool, entries.len);
        errdefer allocator.free(emitted);
        @memset(emitted, false);

        const visited_templates = try allocator.alloc(u32, procedure_templates.templates.items.len);
        errdefer allocator.free(visited_templates);
        @memset(visited_templates, 0);

        for (entries, 0..) |entry, i| {
            const slot = try root_to_request_index.getOrPut(allocator, entry.root_id);
            if (slot.found_existing) checkedArtifactInvariant("compile-time root was requested more than once", .{});
            slot.value_ptr.* = i;
        }

        return .{
            .allocator = allocator,
            .module_idx = module_idx,
            .artifact_key = artifact_key,
            .top_level_demand_dependencies = top_level_demand_dependencies,
            .compile_time_roots = compile_time_roots,
            .procedure_templates = procedure_templates,
            .dispatch = dispatch,
            .resolved_value_refs = resolved_value_refs,
            .top_level_procedure_bindings = top_level_procedure_bindings,
            .platform_required_bindings = platform_required_bindings,
            .callable_eval_templates = callable_eval_templates,
            .hoisted_constants = hoisted_constants,
            .const_templates = const_templates,
            .entries = entries,
            .root_to_request_index = root_to_request_index,
            .dependents = dependents,
            .pairing_dependents = pairing_dependents,
            .indegrees = indegrees,
            .emitted = emitted,
            .visited_templates = visited_templates,
            .seen_edges = std.AutoHashMap(u64, void).init(allocator),
        };
    }

    fn deinit(self: *CompileTimeRequestScheduler) void {
        self.seen_edges.deinit();
        self.visited_literal_wrappers.deinit(self.allocator);
        self.literal_demand.deinit(self.allocator);
        self.allocator.free(self.visited_templates);
        self.allocator.free(self.emitted);
        self.allocator.free(self.indegrees);
        for (self.pairing_dependents) |*list| list.deinit(self.allocator);
        self.allocator.free(self.pairing_dependents);
        for (self.dependents) |*list| list.deinit(self.allocator);
        self.allocator.free(self.dependents);
        self.root_to_request_index.deinit(self.allocator);
        self.* = undefined;
    }

    fn sortedRequests(self: *CompileTimeRequestScheduler) Allocator.Error![]RootRequest {
        try self.buildEdges();
        // Binding dependence includes captured values as well as strict demand
        // edges. Propagate it separately from the acyclic evaluation schedule.
        var pending = std.ArrayList(usize).empty;
        defer pending.deinit(self.allocator);
        for (self.entries, 0..) |entry, i| {
            if (entry.request.requires_pairing) try pending.append(self.allocator, i);
        }
        var pending_index: usize = 0;
        while (pending_index < pending.items.len) : (pending_index += 1) {
            for (self.pairing_dependents[pending.items[pending_index]].items) |dependent| {
                if (self.entries[dependent].request.requires_pairing) continue;
                self.entries[dependent].request.requires_pairing = true;
                try pending.append(self.allocator, dependent);
            }
        }

        var sorted = std.ArrayList(RootRequest).empty;
        errdefer sorted.deinit(self.allocator);

        while (sorted.items.len < self.entries.len) {
            // Hoisted roots can read each other ("Dependency-Ordered
            // Compile-Time Evaluation"): with none ready, the next is a
            // member of a group that depends on no other unemitted root.
            const next = self.nextReadyRequestIndex() orelse try self.nextGroupRequestIndex();
            self.emitted[next] = true;
            try sorted.append(self.allocator, self.entries[next].request);

            for (self.dependents[next].items) |dependent| {
                if (self.indegrees[dependent] == 0) {
                    checkedArtifactInvariant("compile-time root dependency edge underflowed during scheduling", .{});
                }
                self.indegrees[dependent] -= 1;
            }
        }

        return try sorted.toOwnedSlice(self.allocator);
    }

    fn nextReadyRequestIndex(self: *const CompileTimeRequestScheduler) ?usize {
        for (self.entries, 0..) |_, i| {
            if (self.emitted[i]) continue;
            if (self.indegrees[i] != 0) continue;
            return i;
        }
        return null;
    }

    /// The first unemitted request of a group of roots that read each other
    /// and depend on no root outside the group: a request with the fewest
    /// unemitted requests reaching it, itself included. Any other request
    /// is reached from such a group and so by strictly more.
    fn nextGroupRequestIndex(self: *CompileTimeRequestScheduler) Allocator.Error!usize {
        const dependencies = try self.allocator.alloc(std.ArrayList(u32), self.entries.len);
        defer self.allocator.free(dependencies);
        @memset(dependencies, .empty);
        defer for (dependencies) |*list| list.deinit(self.allocator);
        for (self.dependents, 0..) |list, dependency| {
            if (self.emitted[dependency]) continue;
            for (list.items) |dependent| try dependencies[dependent].append(self.allocator, @intCast(dependency));
        }
        const reached = try self.allocator.alloc(bool, self.entries.len);
        defer self.allocator.free(reached);
        var pending = std.ArrayList(u32).empty;
        defer pending.deinit(self.allocator);
        var best: ?usize = null;
        var best_count: usize = std.math.maxInt(usize);
        for (self.emitted, 0..) |emitted, start| {
            if (emitted) continue;
            @memset(reached, false);
            reached[start] = true;
            var count: usize = 1;
            try pending.append(self.allocator, @intCast(start));
            while (pending.pop()) |request| {
                for (dependencies[request].items) |dependency| {
                    if (reached[dependency]) continue;
                    reached[dependency] = true;
                    count += 1;
                    try pending.append(self.allocator, dependency);
                }
            }
            if (count < best_count) {
                best = start;
                best_count = count;
            }
        }
        return best orelse checkedArtifactInvariant("request scheduling looked for a group with every request emitted", .{});
    }

    fn buildEdges(self: *CompileTimeRequestScheduler) Allocator.Error!void {
        for (self.entries, 0..) |entry, i| {
            self.current_request_index = i;
            self.current_root_id = entry.root_id;

            self.beginDependencyVisit();
            const template_ref = entry.request.procedure_template orelse {
                checkedArtifactInvariant("compile-time root request had no entry wrapper template", .{});
            };
            try self.collectTemplateDependencies(template_ref);
            // A literal argument root converts in the scheme its edge
            // instantiates (design.md "Literal Arguments").
            if ((try self.dispatch.compileTimeRoot(entry.root_id)).literal_argument) |argument| try self.collectLiteralEdgeDependencies(argument.edge);
        }
    }

    /// Walk the scheme a literal argument root's edge instantiates.
    fn collectLiteralEdgeDependencies(self: *CompileTimeRequestScheduler, edge: LiteralEdge) Allocator.Error!void {
        switch (edge) {
            .literal => {},
            .node => |id| switch ((try self.dispatch.evidenceNode(id)).target.kind) {
                .procedure => |procedure| try self.collectTemplateDependencies(procedure.template),
                .local_proc, .structural => {},
            },
            .use => |expr| {
                const ref_id = self.resolved_value_refs.lookupIdByExpr(expr) orelse return;
                const template_ref = (try self.collectResolvedRefDependency(self.resolved_value_refs.records[@backingInt(ref_id)].ref)) orelse return;
                try self.collectTemplateDependencies(template_ref);
            },
        }
    }

    fn beginDependencyVisit(self: *CompileTimeRequestScheduler) void {
        self.visit +%= 1;
        if (self.visit != 0) return;
        @memset(self.visited_templates, 0);
        self.visit = 1;
    }

    /// Walk every local procedure template reachable from `root`, adding the
    /// dependency edges each one's resolved refs name. Entered templates are
    /// explicit frames, so a long call chain never becomes native call depth.
    fn collectTemplateDependencies(
        self: *CompileTimeRequestScheduler,
        root: canonical.ProcedureTemplateRef,
    ) Allocator.Error!void {
        var frames: std.ArrayListUnmanaged(TemplateDependencyFrame) = .empty;
        defer frames.deinit(self.allocator);
        if (try self.enterTemplateDependencies(root)) |refs| try frames.append(self.allocator, .{ .refs = refs });
        while (frames.items.len > 0) {
            const frame = &frames.items[frames.items.len - 1];
            if (frame.next == frame.refs.len) {
                _ = frames.pop();
                continue;
            }
            const ref_id = frame.refs[frame.next];
            frame.next += 1;
            const raw = @backingInt(ref_id);
            if (raw >= self.resolved_value_refs.records.len) {
                checkedArtifactInvariant("compile-time request dependency ref id was outside the checked table", .{});
            }
            const template_ref = (try self.collectResolvedRefDependency(self.resolved_value_refs.records[raw].ref)) orelse continue;
            if (try self.enterTemplateDependencies(template_ref)) |refs| try frames.append(self.allocator, .{ .refs = refs });
        }
    }

    const TemplateDependencyFrame = struct {
        refs: []const ResolvedValueRefId,
        next: usize = 0,
    };

    /// The resolved refs of a local template not yet visited in this pass,
    /// whose literal argument demand the current root then depends on
    /// (design.md "Literal Arguments").
    fn enterTemplateDependencies(
        self: *CompileTimeRequestScheduler,
        template_ref: canonical.ProcedureTemplateRef,
    ) Allocator.Error!?[]const ResolvedValueRefId {
        if (!template_ref.artifact.eql(self.artifact_key.digest())) return null;
        if (templateLiteralRoot(template_ref.template)) |root| {
            const stamp = try self.visited_literal_wrappers.getOrPut(self.allocator, root);
            if (stamp.found_existing and stamp.value_ptr.* == self.visit) return null;
            stamp.value_ptr.* = self.visit;
            try self.addLiteralArgumentDemand(template_ref.template);
            return &.{};
        }
        const index = template_ref.template.index();
        if (index >= self.visited_templates.len) {
            checkedArtifactInvariant("compile-time request dependency referenced an unknown local procedure template", .{});
        }
        if (self.visited_templates[index] == self.visit) return null;
        self.visited_templates[index] = self.visit;

        const template = self.procedure_templates.get(template_ref.template);
        try self.addLiteralArgumentDemand(template_ref.template);
        const refs = template.resolved_value_refs;
        const end = refs.start + refs.len;
        if (end > self.resolved_value_refs.template_refs.len) {
            checkedArtifactInvariant("compile-time request dependency ref span was outside the checked table", .{});
        }
        return self.resolved_value_refs.template_refs[refs.start..end];
    }

    /// Add the dependency one resolved ref names; returns the procedure
    /// template the ref calls into, for the caller to walk.
    fn collectResolvedRefDependency(
        self: *CompileTimeRequestScheduler,
        ref: ResolvedValueRef,
    ) Allocator.Error!?canonical.ProcedureTemplateRef {
        switch (ref) {
            .platform_required_declaration => self.entries[self.current_request_index].request.requires_pairing = true,
            .top_level_const => |const_use| try self.addConstUseDependency(const_use),
            .selected_hoisted_const => |selected| try self.addConstUseDependency(selected.const_use),
            .top_level_proc,
            .promoted_top_level_proc,
            => |procedure| return try self.collectProcedureUseDependencies(procedure),
            .platform_required_const => |required| try self.addConstUseDependency(required.const_use),
            .platform_required_proc => |required| return try self.collectProcedureUseDependencies(required.procedure),
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .imported_const,
            .imported_proc,
            .hosted_proc,
            .platform_required_checked_error,
            => {},
        }
        return null;
    }

    /// Follow a procedure use through any chain of platform-required
    /// bindings and exact procedure aliases to the template it calls, adding
    /// the dependencies it passes.
    fn collectProcedureUseDependencies(
        self: *CompileTimeRequestScheduler,
        first: ProcedureUseTemplate,
    ) Allocator.Error!?canonical.ProcedureTemplateRef {
        var procedure = first;
        while (true) {
            switch (procedure.binding) {
                .top_level => |top_level| {
                    if (!top_level.artifact.eql(self.artifact_key.digest())) return null;
                    const binding = self.top_level_procedure_bindings.get(top_level.binding);
                    const template_id = switch (binding.body) {
                        .callable_eval_template => |id| id,
                        .direct_template, .checked_error => return try self.collectProcedureBindingDependencies(binding.body),
                    };
                    const template = self.callable_eval_templates.get(template_id);
                    try self.addRootDependency(template.root);
                    // A call of an exact procedure alias is a call of the
                    // procedure its lookup forwards to.
                    const lookup = template.forwarded_lookup orelse return null;
                    const ref_id = self.resolved_value_refs.lookupIdByExpr(lookup) orelse
                        checkedArtifactInvariant("an exact procedure alias's forwarded lookup had no resolved value reference", .{});
                    const ref = self.resolved_value_refs.records[@backingInt(ref_id)].ref;
                    switch (ref) {
                        .top_level_proc, .promoted_top_level_proc => |next| procedure = next,
                        .platform_required_proc => |required| procedure = required.procedure,
                        .imported_proc,
                        .hosted_proc,
                        .top_level_const,
                        .imported_const,
                        .selected_hoisted_const,
                        .platform_required_const,
                        .local_param,
                        .local_value,
                        .local_mutable_version,
                        .pattern_binder,
                        .local_proc,
                        .platform_required_declaration,
                        .platform_required_checked_error,
                        => return try self.collectResolvedRefDependency(ref),
                    }
                },
                .platform_required => |required| {
                    if (!required.artifact.eql(self.artifact_key.digest())) return null;
                    const binding = self.platform_required_bindings.lookupByBindingId(@backingInt(required.procedure_binding)) orelse {
                        checkedArtifactInvariant("platform-required procedure dependency referenced a missing binding", .{});
                    };
                    switch (binding.value_use) {
                        .procedure_value => |value| procedure = value.procedure,
                        .const_value => |const_value| {
                            try self.addConstUseDependency(const_value.const_use);
                            return null;
                        },
                    }
                },
                .imported,
                .hosted,
                => return null,
            }
        }
    }

    fn collectProcedureBindingDependencies(
        self: *CompileTimeRequestScheduler,
        body: ProcedureBindingBody,
    ) Allocator.Error!?canonical.ProcedureTemplateRef {
        switch (body) {
            .direct_template => |direct| return collectCallableTemplateDependencies(direct.template),
            .checked_error => return null,
            .callable_eval_template => |template_id| {
                const template = self.callable_eval_templates.get(template_id);
                try self.addRootDependency(template.root);
                return null;
            },
        }
    }

    fn collectCallableTemplateDependencies(
        template: canonical.CallableProcedureTemplateRef,
    ) canonical.ProcedureTemplateRef {
        return switch (template) {
            .checked => |checked_template| checked_template,
            .lifted,
            .synthetic,
            => checkedArtifactInvariant("checked compile-time dependency referenced a post-check template", .{}),
        };
    }

    fn addConstUseDependency(
        self: *CompileTimeRequestScheduler,
        const_use: ConstUseTemplate,
    ) Allocator.Error!void {
        // A declaration with no implementation evaluates nothing, so it
        // publishes no compile-time root and contributes no dependency edge.
        if (self.constUseIsUnimplemented(const_use.const_ref)) return;
        const root_id = self.rootForConstRef(const_use.const_ref) orelse return;
        const own_hoisted_root = switch (const_use.const_ref.owner) {
            .hoisted_root => true,
            .top_level_binding => false,
        };
        if (root_id == self.current_root_id and own_hoisted_root) return;
        try self.addRootDependency(root_id);
    }

    fn constUseIsUnimplemented(self: *CompileTimeRequestScheduler, const_ref: ConstRef) bool {
        if (!const_ref.artifact.eql(self.artifact_key.digest())) return false;
        return self.const_templates.get(const_ref).state == .unimplemented;
    }

    fn rootForConstRef(
        self: *CompileTimeRequestScheduler,
        const_ref: ConstRef,
    ) ?ComptimeRootId {
        if (!const_ref.artifact.eql(self.artifact_key.digest())) return null;
        return switch (const_ref.owner) {
            .top_level_binding => |top_level| blk: {
                if (top_level.module_idx != self.module_idx) {
                    checkedArtifactInvariant("local top-level const dependency had mismatched module index", .{});
                }
                break :blk self.compile_time_roots.lookupIdByPattern(top_level.pattern) orelse
                    checkedArtifactInvariant("local const dependency had no compile-time root", .{});
            },
            .hoisted_root => |hoisted| blk: {
                if (hoisted.module_idx != self.module_idx) {
                    checkedArtifactInvariant("local hoisted const dependency had mismatched module index", .{});
                }
                const entry = self.hoisted_constants.lookupByRoot(hoisted.root) orelse
                    checkedArtifactInvariant("local hoisted const dependency had no hoisted const entry", .{});
                break :blk entry.root;
            },
        };
    }

    /// Depend on the literal argument roots template `template`'s edges read.
    fn addLiteralArgumentDemand(self: *CompileTimeRequestScheduler, template: canonical.CheckedProcedureTemplateId) Allocator.Error!void {
        self.literal_demand.clearRetainingCapacity();
        try self.dispatch.appendLiteralArgumentDemand(self.allocator, template, &self.literal_demand);
        for (self.literal_demand.items) |root| try self.addRootDependency(root);
    }

    fn addRootDependency(
        self: *CompileTimeRequestScheduler,
        dependency_root: ComptimeRootId,
    ) Allocator.Error!void {
        if (dependency_root == self.current_root_id) return;
        if (self.root_to_request_index.get(dependency_root)) |dependency_index| {
            try self.pairing_dependents[dependency_index].append(self.allocator, self.current_request_index);
        }
        if (!try self.rootDependencyIsStrict(dependency_root)) return;
        try self.addUnconditionalRootDependency(dependency_root);
    }

    fn addUnconditionalRootDependency(
        self: *CompileTimeRequestScheduler,
        dependency_root: ComptimeRootId,
    ) Allocator.Error!void {
        if (dependency_root == self.current_root_id) return;
        const dependency_index = self.root_to_request_index.get(dependency_root) orelse return;
        const edge_key = dependencyEdgeKey(dependency_index, self.current_request_index);
        const edge = try self.seen_edges.getOrPut(edge_key);
        if (edge.found_existing) return;
        edge.value_ptr.* = {};
        try self.dependents[dependency_index].append(self.allocator, self.current_request_index);
        self.indegrees[self.current_request_index] += 1;
    }

    fn rootDependencyIsStrict(
        self: *const CompileTimeRequestScheduler,
        dependency_root: ComptimeRootId,
    ) Allocator.Error!bool {
        const dependent = try self.dispatch.compileTimeRoot(self.current_root_id);
        const dependency = try self.dispatch.compileTimeRoot(dependency_root);
        return switch (dependent.source) {
            .def => |dependent_def| switch (dependency.source) {
                .def => |dependency_def| can.DependencyGraph.hasDependency(
                    self.top_level_demand_dependencies,
                    dependent_def,
                    dependency_def,
                ),
                .expr, .statement, .required_binding, .hoisted, .literal => true,
            },
            .expr, .statement, .required_binding, .hoisted, .literal => true,
        };
    }

    fn dependencyEdgeKey(
        dependency_index: usize,
        dependent_index: usize,
    ) u64 {
        if (dependency_index > std.math.maxInt(u32) or dependent_index > std.math.maxInt(u32)) {
            checkedArtifactInvariant("compile-time dependency edge index exceeded scheduler key capacity", .{});
        }
        return (@as(u64, @intCast(dependency_index)) << 32) | @as(u64, @intCast(dependent_index));
    }
};

fn compileTimeRootIdForRequest(
    dispatch: CheckedDispatch,
    request: RootRequest,
) Allocator.Error!ComptimeRootId {
    const root_id = request.compile_time_root orelse {
        checkedArtifactInvariant("compile-time request had no exact compile-time root identity", .{});
    };
    const root = try dispatch.compileTimeRoot(root_id);
    if (root.id != root_id or
        !compileTimeRootKindMatchesRequest(root.kind, request.kind) or
        !rootSourceMatches(root.source, request.source))
    {
        checkedArtifactInvariant("compile-time request identity did not match its checked root", .{});
    }
    return root_id;
}

fn verifyCompileTimeRequestsScheduled(
    requests: []const RootRequest,
    dispatch: CheckedDispatch,
) Allocator.Error!void {
    if (builtin.mode != .debug) return;
    for (requests, 0..) |request, i| {
        if (request.abi != .compile_time and request.abi != .test_expect) {
            base.invariant("checked artifact invariant violated: scheduled compile-time requests contained a request that is neither compile-time nor an expect", .{});
        }
        const root_id = try compileTimeRootIdForRequest(dispatch, request);
        for (requests[0..i]) |previous| {
            const previous_id = try compileTimeRootIdForRequest(dispatch, previous);
            if (previous_id == root_id) {
                base.invariant("checked artifact invariant violated: compile-time root was scheduled more than once", .{});
            }
        }
    }
}

/// Which graph the concreteness walk is inspecting: the value graph (type
/// variables are NOT concrete) or a nominal declaration's backing template
/// (rigids there are the declaration's formals, standing for args the walk
/// already checked at the application, so they count as concrete).
const ConcreteRootWalk = enum { value_graph, decl_template };

fn checkedTypeIsConcreteCompileTimeRoot(
    allocator: Allocator,
    module: ModuleId,
    checked_types: CheckedTypeStoreView,
    resolver: ModuleResolver,
    root: CheckedTypeId,
) Allocator.Error!bool {
    var active = std.AutoHashMap(u64, void).init(allocator);
    defer active.deinit();
    var modules = try WalkModules.init(allocator, module, checked_types, resolver);
    defer modules.deinit(allocator);
    var scan = ConcreteRootScan{ .allocator = allocator, .modules = &modules, .active = &active };
    return ConcreteRootScan.Eval.run(allocator, &scan, .{ .ty = .{ .walk = .value_graph, .module = 0, .id = root } });
}

/// Whether a checked type is concrete enough to be a compile-time root. A
/// type reached again while it is still being walked (a recursive type)
/// counts as concrete.
const ConcreteRootScan = struct {
    allocator: Allocator,
    /// The modules the walk has entered; a nominal's backing is walked in
    /// its declaring module.
    modules: *WalkModules,
    /// The types on the path currently being walked (`WalkModules.key`).
    active: *std.AutoHashMap(u64, void),

    const Leaf = union(enum) {
        ty: struct { walk: ConcreteRootWalk, module: u32, id: CheckedTypeId },
        decided: bool,
    };
    const Eval = collections.AnyAll.Evaluation(Leaf, ConcreteRootScan);

    fn addSpan(items: Eval.Items, walk: ConcreteRootWalk, module: u32, ids: []const CheckedTypeId) Allocator.Error!void {
        for (ids) |id| try items.add(.{ .ty = .{ .walk = walk, .module = module, .id = id } });
    }

    pub fn enter(scan: *ConcreteRootScan, items: Eval.Items, leaf: Leaf) Allocator.Error!Eval.Expansion {
        const ty = switch (leaf) {
            .decided => |value| return .{ .value = value },
            .ty => |ty| ty,
        };
        const walk = ty.walk;
        const module = ty.module;
        if (scan.active.contains(WalkModules.key(module, ty.id))) return .{ .value = true };

        switch (scan.modules.typesOf(module).payload(ty.id)) {
            .pending => checkedArtifactInvariant("compile-time root checked type was pending", .{}),
            .field_kind, .err => return .{ .value = false },
            .flex => return .{ .value = false },
            .rigid => return .{ .value = walk == .decl_template },
            .empty_record,
            .empty_tag_union,
            => return .{ .value = true },
            .alias => |alias| {
                try addSpan(items, walk, module, alias.args);
                try items.add(.{ .ty = .{ .walk = walk, .module = module, .id = alias.backing } });
            },
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    if (field.kind.tag == .undetermined) {
                        try items.add(.{ .decided = false });
                        break;
                    }
                    try items.add(.{ .ty = .{ .walk = walk, .module = module, .id = field.ty } });
                } else try items.add(.{ .ty = .{ .walk = walk, .module = module, .id = record.ext } });
            },
            .tuple => |items_ids| try addSpan(items, walk, module, items_ids),
            .nominal => |nominal| {
                try addSpan(items, walk, module, nominal.args);
                const needs_backing = switch (nominal.representation) {
                    .builtin => |builtin_type| switch (builtinRuntimeEncoding(builtin_type)) {
                        .primitive,
                        .list,
                        .box,
                        .dict,
                        .set,
                        .parse_tag_union_spec,
                        .fields,
                        .field,
                        => false,
                        .bool_tag_union,
                        .try_nominal,
                        .iterator,
                        .crypto_sha256_digest,
                        .crypto_sha256_hasher,
                        .crypto_blake3_digest,
                        .crypto_blake3_hasher,
                        => true,
                    },
                    .opaque_without_backing => false,
                    .local_declaration,
                    .imported_declaration,
                    .local_box_payload_capability,
                    .imported_box_payload_capability,
                    => true,
                };
                if (needs_backing) {
                    // Declaration formals stand for the args checked above, so they
                    // count as concrete while walking the backing template.
                    if (try scan.modules.declaration(scan.allocator, module, nominal)) |site| {
                        try items.add(.{ .ty = .{ .walk = .decl_template, .module = site.module, .id = site.declaration.backing } });
                    }
                }
            },
            // A function scheme is a concrete compile-time root exactly when its
            // args and return contain no identity variables.
            .function => |function| {
                try addSpan(items, walk, module, function.args);
                try items.add(.{ .ty = .{ .walk = walk, .module = module, .id = function.ret } });
            },
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    try addSpan(items, walk, module, tag.args);
                }
                try items.add(.{ .ty = .{ .walk = walk, .module = module, .id = tag_union.ext } });
            },
        }
        try scan.active.put(WalkModules.key(module, ty.id), {});
        return .{ .group = .all };
    }

    pub fn exit(scan: *ConcreteRootScan, leaf: Leaf, _: ?bool) Allocator.Error!void {
        _ = scan.active.remove(WalkModules.key(leaf.ty.module, leaf.ty.id));
    }
};

test "compile-time roots reject undetermined record field kinds" {
    const allocator = std.testing.allocator;
    var store = CheckedTypeStore{};
    defer store.deinit(allocator);

    const leaf: CheckedTypeId = type_ids.fromSynthesized(store.payloads.items().len);
    try store.payloads.append(allocator, try store.commitPayload(allocator, .empty_record));

    const root: CheckedTypeId = type_ids.fromSynthesized(store.payloads.items().len);
    const fields = try allocator.alloc(CheckedRecordField, 1);
    fields[0] = .{
        .name = testIndexId(canonical.RecordFieldLabelId, 7),
        .ty = leaf,
        .kind = .undetermined(leaf),
    };
    try store.payloads.append(allocator, try store.commitPayload(allocator, .{ .record = .{ .fields = fields, .ext = leaf } }));

    const imports = CheckedImportViews{ .current_owner = testCheckedModuleKey(1).digest(), .direct = &.{} };
    try std.testing.expect(!try checkedTypeIsConcreteCompileTimeRoot(allocator, imports.current_owner, store.view(), imports.resolver(), root));
}

test "compile-time data roots with reachable callables require producer type evidence" {
    const allocator = std.testing.allocator;
    var store = CheckedTypeStore{};
    defer store.deinit(allocator);

    const leaf: CheckedTypeId = type_ids.fromSynthesized(store.payloads.items().len);
    try store.payloads.append(allocator, try store.commitPayload(allocator, .empty_record));

    const callable: CheckedTypeId = type_ids.fromSynthesized(store.payloads.items().len);
    try store.payloads.append(allocator, try store.commitPayload(allocator, .{ .function = .{
        .kind = .pure,
        .ret = leaf,
    } }));

    const root: CheckedTypeId = type_ids.fromSynthesized(store.payloads.items().len);
    const fields = try allocator.alloc(CheckedRecordField, 1);
    fields[0] = .{
        .name = testIndexId(canonical.RecordFieldLabelId, 7),
        .ty = callable,
        .kind = .required,
    };
    try store.payloads.append(allocator, try store.commitPayload(allocator, .{ .record = .{
        .fields = fields,
        .ext = leaf,
    } }));

    const imports = CheckedImportViews{ .current_owner = testCheckedModuleKey(1).digest(), .direct = &.{} };
    try std.testing.expect(!try checkedTypeIsContextFreeCompileTimeRoot(allocator, imports.current_owner, store.view(), imports.resolver(), false, root));
    try std.testing.expect(try checkedTypeIsContextFreeCompileTimeRoot(allocator, imports.current_owner, store.view(), imports.resolver(), true, root));
}

fn compileTimeRootRequestIsEligible(root: CompileTimeRoot) bool {
    return switch (root.request_eligibility) {
        .pending => checkedArtifactInvariant("compile-time root request eligibility was pending", .{}),
        .eligible => true,
        .ineligible => false,
    };
}

fn compileTimeRootHasRootRequest(
    requests: []const RootRequest,
    root: CompileTimeRoot,
) bool {
    for (requests) |request| {
        if (request.abi != .compile_time) continue;
        if (request.compile_time_root == root.id) return true;
    }
    return false;
}

/// An exact checked procedure lookup already carries the callable identity
/// that compile-time evaluation would rediscover. Keep its callable binding
/// pending for runtime demand instead of scheduling an evaluator wrapper.
fn compileTimeCallableRootIsProcedureReference(
    bodies: CheckedBodies,
    resolved_value_refs: *const ResolvedValueRefTable,
    root: CompileTimeRoot,
) bool {
    if (root.kind != .callable_binding) return false;
    const evaluated = root.evaluatedExpr() orelse return false;
    const root_expr = bodies.exprData(evaluated);
    if (root_expr != .lookup_local and root_expr != .lookup_external and root_expr != .lookup_required) return false;
    const ref_id = resolved_value_refs.lookupIdByExpr(evaluated) orelse
        checkedArtifactInvariant("checked callable lookup root had no resolved value reference", .{});
    const raw = @backingInt(ref_id);
    if (raw >= resolved_value_refs.records.len) {
        checkedArtifactInvariant("checked callable lookup root resolved reference was outside the checked table", .{});
    }
    return switch (resolved_value_refs.records[raw].ref) {
        .top_level_proc,
        .imported_proc,
        .hosted_proc,
        .platform_required_proc,
        .promoted_top_level_proc,
        => true,
        .local_param,
        .local_value,
        .local_mutable_version,
        .pattern_binder,
        .local_proc,
        .selected_hoisted_const,
        .top_level_const,
        .imported_const,
        .platform_required_declaration,
        .platform_required_checked_error,
        .platform_required_const,
        => false,
    };
}

fn compileTimeRootKindMatchesRequest(
    root_kind: CompileTimeRootKind,
    request_kind: RootRequestKind,
) bool {
    return switch (root_kind) {
        .constant, .hoisted_constant, .hoisted_validation => request_kind == .compile_time_constant,
        .callable_binding => request_kind == .compile_time_callable,
        .expect => request_kind == .test_expect,
        .repl_expr => request_kind == .repl_expr,
        .numeral_conversion, .quote_conversion, .literal_argument => request_kind == .compile_time_constant,
    };
}

fn verifyRootRequestSubsets(root_requests: RootRequestTable) void {
    if (builtin.mode != .debug) return;

    var runtime_index: usize = 0;
    var compile_time_count: usize = 0;

    for (root_requests.requests) |request| {
        if (request.requires_pairing) continue;
        if (request.abi == .compile_time) {
            if (!request.evaluation_complete) compile_time_count += 1;
        } else {
            if (runtime_index >= root_requests.runtime_requests.len) {
                base.invariant("checked artifact invariant violated: runtime root request subset is missing an entry", .{});
            }
            if (!std.meta.eql(root_requests.runtime_requests[runtime_index], request)) {
                base.invariant("checked artifact invariant violated: runtime root request subset is out of order", .{});
            }
            runtime_index += 1;
        }
    }

    if (runtime_index != root_requests.runtime_requests.len) {
        base.invariant("checked artifact invariant violated: runtime root request subset has extra entries", .{});
    }
    if (compile_time_count != root_requests.compile_time_requests.len) {
        base.invariant("checked artifact invariant violated: compile-time root request subset has extra entries", .{});
    }
    for (root_requests.compile_time_requests) |request| {
        if (request.abi != .compile_time) {
            base.invariant("checked artifact invariant violated: compile-time root request subset contains a runtime request", .{});
        }
        if (!rootRequestSliceContains(root_requests.requests, request)) {
            base.invariant("checked artifact invariant violated: compile-time root request subset contains an unknown request", .{});
        }
    }
}

fn rootRequestSliceContains(requests: []const RootRequest, needle: RootRequest) bool {
    for (requests) |request| {
        if (std.meta.eql(request, needle)) return true;
    }
    return false;
}

fn rootSourceMatches(a: RootSource, b: RootSource) bool {
    if (std.meta.activeTag(a) != std.meta.activeTag(b)) return false;
    return switch (a) {
        .def => |def| def == b.def,
        .expr => |expr| expr == b.expr,
        .statement => |statement| statement == b.statement,
        .required_binding => |binding| binding == b.required_binding,
        .hoisted => |hoisted| hoisted.index == b.hoisted.index and hoisted.expr == b.hoisted.expr,
        .literal => |literal| std.meta.eql(literal, b.literal),
    };
}

fn appendPublishedEntrypointRoots(
    requests: *std.ArrayList(RootRequest),
    allocator: Allocator,
    module_idx: u32,
    module_env: *const ModuleEnv,
    bodies: CheckedBodies,
    provided_exports: *const ProvidedExportTable,
    top_level_values: *const TopLevelValueTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    platform_app_relation: ?PlatformAppRelationKey,
    platform_required_declarations: *const PlatformRequiredDeclarationTable,
    validation: can.Can.Validation,
) Allocator.Error!void {
    const provided_runtime_roots_ready = module_env.module_kind != .platform or
        platform_required_declarations.declarations.len == 0 or
        platform_app_relation != null;
    {
        for (provided_exports.exports, 0..) |provided, export_index| {
            switch (provided) {
                .procedure => |procedure| {
                    try appendRoot(requests, allocator, .{
                        .module_idx = module_idx,
                        .kind = .provided_export,
                        .requires_pairing = !provided_runtime_roots_ready,
                        .provided_export = @fromBackingInt(@intCast(export_index)),
                        .source = .{ .def = procedure.def },
                        .checked_type = procedure.checked_type,
                        .abi = .platform,
                        .exposure = .exported,
                        .procedure_template = procedureTemplateForTopLevelBinding(top_level_procedure_bindings, procedure.binding),
                        .procedure_binding = procedure.binding,
                    });
                },
                .data => {},
            }
        }
    }

    switch (module_env.module_kind) {
        .default_app, .app => if (validation == .checking) {
            try appendExposedAppProcedureRoots(
                requests,
                allocator,
                module_idx,
                module_env,
                bodies,
                top_level_values,
                top_level_procedure_bindings,
            );
        },
        .type_module,
        .package,
        .platform,
        .hosted,
        .module,
        .malformed,
        => {},
    }
}

fn appendExposedAppProcedureRoots(
    requests: *std.ArrayList(RootRequest),
    allocator: Allocator,
    module_idx: u32,
    module_env: *const ModuleEnv,
    bodies: CheckedBodies,
    top_level_values: *const TopLevelValueTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
) Allocator.Error!void {
    // `exports` is canonicalization's exact app-header `provides` inventory.
    // `common.exposed_items` is broader: it also publishes associated methods
    // for module imports, including compiler-owned generated-method markers.
    // Those methods are public API, but they are not app entrypoints.
    for (module_env.store.sliceDefs(module_env.exports)) |def_idx| {
        const top_level = top_level_values.lookupByDef(def_idx) orelse {
            checkedArtifactInvariant(
                "app-provided definition {d} had no top-level value entry",
                .{@backingInt(def_idx)},
            );
        };
        const procedure_binding = switch (top_level.value) {
            .procedure_binding => |binding| binding,
            .const_ref => continue,
        };
        try appendRoot(requests, allocator, .{
            .module_idx = module_idx,
            .kind = .runtime_entrypoint,
            .source = .{ .def = def_idx },
            .checked_type = checkedTypeIdForRootSource(module_env, bodies, .{ .def = def_idx }),
            .abi = .roc,
            .exposure = .exported,
            .procedure_template = procedureTemplateForTopLevelBinding(top_level_procedure_bindings, procedure_binding),
            .procedure_binding = procedure_binding,
        });
    }
}

fn procedureTemplateForRootSource(
    procedure_templates: *const CheckedProcedureTemplateTable,
    source: RootSource,
) ?canonical.ProcedureTemplateRef {
    return switch (source) {
        .def => |def_idx| procedure_templates.lookupByDef(def_idx),
        .expr,
        .statement,
        .required_binding,
        .hoisted,
        .literal,
        => null,
    };
}

/// Root requests for every exported top-level procedure binding of a checked
/// artifact, in export order, each at its template's own checked scheme
/// root. These are the roots of the module's pack program; the caller keeps
/// the ones whose types are closed.
pub fn exportedProcedureRoots(
    allocator: Allocator,
    artifact: *const CheckedModuleArtifact,
) Allocator.Error![]RootRequest {
    var requests = std.ArrayList(RootRequest).empty;
    errdefer requests.deinit(allocator);
    for (artifact.exports.defs) |def_idx| {
        const top_level = artifact.top_level_values.lookupByDef(def_idx) orelse continue;
        const procedure_binding = switch (top_level.value) {
            .procedure_binding => |binding| binding,
            .const_ref => continue,
        };
        const template = procedureTemplateForTopLevelBinding(&artifact.top_level_procedure_bindings, procedure_binding) orelse continue;
        const checked_template = artifact.checked_procedure_templates.get(template.template);
        // Intrinsic and entry wrappers lower only at their call sites; a
        // pack root must have a checked body of its own.
        switch (checked_template.body) {
            .checked_body => {},
            .intrinsic_wrapper, .entry_wrapper, .literal_root, .unimplemented => continue,
        }
        // Only a Roc procedure has code of its own to cache: a hosted
        // function's callers reach the host directly, and the other targets
        // never lower as procedures of the exporting module.
        switch (checked_template.target) {
            .roc => {},
            .hosted, .intrinsic, .entry, .comptime_only => continue,
        }
        const checked_fn_root = checked_template.checked_fn_root;
        try appendRoot(&requests, allocator, .{
            .module_idx = artifact.module_identity.module_idx,
            .kind = .runtime_entrypoint,
            .source = .{ .def = def_idx },
            .checked_type = checked_fn_root,
            .abi = .roc,
            .exposure = .exported,
            .procedure_template = template,
            .procedure_binding = procedure_binding,
        });
    }
    return try requests.toOwnedSlice(allocator);
}

fn procedureTemplateForTopLevelBinding(
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    binding_ref: TopLevelProcedureBindingRef,
) ?canonical.ProcedureTemplateRef {
    const binding = top_level_procedure_bindings.get(binding_ref);
    return switch (binding.body) {
        .direct_template => |direct| switch (direct.template) {
            .checked => |template| template,
            .synthetic => |synthetic| synthetic.template,
            .lifted => checkedArtifactInvariant("checked root binding referenced lifted procedure before post-check lowering", .{}),
        },
        .callable_eval_template, .checked_error => null,
    };
}

/// The entry wrapper template of a root bound to an exact procedure alias. The
/// root enters the alias's scope, which is that wrapper's, so the wrapper's
/// template root evidence is the root's.
fn aliasRootWrapperTemplate(
    request: RootRequest,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    callable_eval_templates: CallableEvalTemplateTableView,
    entry_wrappers: *const EntryWrapperTable,
) ?canonical.ProcedureTemplateRef {
    const binding_ref = request.procedure_binding orelse return null;
    return switch (top_level_procedure_bindings.get(binding_ref).body) {
        .callable_eval_template => |template_id| blk: {
            const template = callable_eval_templates.templates[@backingInt(template_id)];
            if (template.forwarded_lookup == null) break :blk null;
            break :blk templateForEntryWrapperRoot(entry_wrappers, template.root);
        },
        .direct_template, .checked_error => null,
    };
}

const RootBackingProcedure = struct {
    checked_type: CheckedTypeId,
    template: canonical.ProcedureTemplateRef,
    compile_time_root: ?ComptimeRootId,
};

fn explicitRootBackingProcedure(
    procedure_templates: *const CheckedProcedureTemplateTable,
    compile_time_roots: *const CompileTimeRootTable,
    entry_wrappers: *const EntryWrapperTable,
    source: RootSource,
    request_kind: RootRequestKind,
    source_checked_type: CheckedTypeId,
) RootBackingProcedure {
    if (procedureTemplateForRootSource(procedure_templates, source)) |template| {
        return .{ .checked_type = source_checked_type, .template = template, .compile_time_root = null };
    }

    const root_id = compileTimeRootIdForSourceAndRequestKind(compile_time_roots, source, request_kind) orelse {
        checkedArtifactInvariant("explicit root has no checked procedure template or entry wrapper", .{});
    };
    const wrapper = entryWrapperForRoot(entry_wrappers, root_id);
    return .{ .checked_type = wrapper.checked_fn_root, .template = wrapper.template, .compile_time_root = root_id };
}

fn checkedTypeIdForRootSource(
    env: *const ModuleEnv,
    bodies: CheckedBodies,
    source: RootSource,
) CheckedTypeId {
    const var_ = switch (source) {
        .def => |def_idx| ModuleEnv.varFrom(def_idx),
        .expr => |expr_idx| ModuleEnv.varFrom(expr_idx),
        .statement => |statement_idx| ModuleEnv.varFrom(statement_idx),
        .hoisted => checkedArtifactInvariant("internal hoisted root source reached external root source type lookup", .{}),
        .literal => checkedArtifactInvariant("internal literal conversion root source reached external root source type lookup", .{}),
        .required_binding => |binding_idx| blk: {
            if (binding_idx >= env.requires_types.items.items.len) {
                base.invariant(
                    "checked artifact invariant violated: explicit required-binding root {d} is out of range",
                    .{binding_idx},
                );
            }
            break :blk ModuleEnv.varFrom(env.requires_types.items.items[binding_idx].type_anno);
        },
    };
    return bodies.typeOf(var_);
}

fn platformRequiredBindingCheckedType(binding: PlatformRequiredBinding) CheckedTypeId {
    return switch (binding.value_use) {
        .const_value => |const_use| const_use.const_use.requested_source_ty_payload orelse {
            checkedArtifactInvariant("platform-required const binding missing relation-owned requested payload", .{});
        },
        .procedure_value => |procedure_use| procedure_use.procedure.source_fn_ty_payload orelse {
            checkedArtifactInvariant("platform-required procedure binding missing relation-owned requested payload", .{});
        },
    };
}

fn checkedTypeIdForVar(
    _: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedTypePublication,
    var_: Var,
) Allocator.Error!CheckedTypeId {
    return checked_types.rootForSourceVar(module, var_) orelse {
        base.invariant("checked artifact invariant violated: root request type was not published", .{});
    };
}

const RootRequestWithoutOrder = struct {
    requires_pairing: bool = false,
    module_idx: u32,
    kind: RootRequestKind,
    source: RootSource,
    /// Exact `provides` declaration for a published procedure root.
    provided_export: ?ProvidedExportId = null,
    compile_time_root: ?ComptimeRootId = null,
    checked_type: CheckedTypeId,
    abi: RootAbi,
    exposure: RootExposure,
    procedure_template: ?canonical.ProcedureTemplateRef = null,
    procedure_binding: ?TopLevelProcedureBindingRef = null,
    procedure_use: ?ProcedureUseTemplate = null,
    root_evidence: ?CheckedEvidenceSpan = null,
};

fn appendRoot(
    requests: *std.ArrayList(RootRequest),
    allocator: Allocator,
    request: RootRequestWithoutOrder,
) Allocator.Error!void {
    try requests.append(allocator, .{
        .order = @intCast(requests.items.len),
        .requires_pairing = request.requires_pairing,
        .module_idx = request.module_idx,
        .kind = request.kind,
        .source = request.source,
        .provided_export = if (request.provided_export) |id| .some(id) else .none,
        .compile_time_root = request.compile_time_root,
        .checked_type = request.checked_type,
        .abi = request.abi,
        .exposure = request.exposure,
        .procedure_template = request.procedure_template,
        .procedure_binding = request.procedure_binding,
        .procedure_use = request.procedure_use,
        .root_evidence = request.root_evidence,
    });
}

fn templateForEntryWrapperRoot(
    entry_wrappers: *const EntryWrapperTable,
    root: ComptimeRootId,
) canonical.ProcedureTemplateRef {
    return entryWrapperForRoot(entry_wrappers, root).template;
}

fn entryWrapperForRoot(
    entry_wrappers: *const EntryWrapperTable,
    root: ComptimeRootId,
) EntryWrapper {
    const wrapper = entry_wrappers.lookupByRoot(root) orelse {
        base.invariant("checked artifact invariant violated: compile-time/test root has no entry wrapper", .{});
    };
    return wrapper;
}

fn topLevelExprIsAlreadyProcedure(module: TypedCIR.Module, def_idx: CIR.Def.Idx, expr: CIR.Expr) bool {
    if (expr == .e_lambda or expr == .e_closure or expr == .e_hosted_lambda) return true;
    if (expr != .e_anno_only) return false;
    // A compiler-owned intrinsic is a procedure whatever it declares, because
    // its body comes from the intrinsic wrapper rather than the declaration.
    if (intrinsicForProcedureDef(module, def_idx) != null) return true;
    // Every other annotation-only declaration is a procedure only when the
    // type it declares is a function. Annotation-only values are published
    // through the const path, which records the missing value the same way.
    return sourceTypeIsFunction(module, module.defType(def_idx));
}

fn sourceTypeIsFunction(module: TypedCIR.Module, var_: Var) bool {
    return module.typeStoreConst().varResolvesToFunction(var_);
}

/// Whether `pattern = expr` binds an exact procedure alias, local or top
/// level (design.md "Procedure Aliases"). Generalization is checker-owned
/// binding metadata; the right-hand lookup supplies the forward, and calls
/// and other computations keep their ordinary evaluation site.
fn bindsProcedureAlias(module: TypedCIR.Module, pattern: CIR.Pattern.Idx, expr: CIR.Expr.Idx) bool {
    const rhs = module.expr(expr).data;
    const is_lookup = rhs == .e_lookup_local or rhs == .e_lookup_external or
        rhs == .e_lookup_required or rhs == .e_lookup_associated_resolved;
    return is_lookup and module.pattern(pattern).data == .assign and
        module.moduleEnvConst().nodeIsBindingScheme(ModuleEnv.nodeIdxFrom(pattern)) and
        sourceTypeIsFunction(module, module.patternType(pattern));
}

fn isHostedProcedureExpr(expr: CIR.Expr) bool {
    return expr == .e_hosted_lambda;
}

fn intrinsicForProcedureDef(module: TypedCIR.Module, def_idx: CIR.Def.Idx) ?IntrinsicId {
    return static_dispatch.intrinsicForProcedureDef(module, def_idx);
}

fn iteratorProcedureForDef(module: TypedCIR.Module, def_idx: CIR.Def.Idx) ?IteratorProcedureId {
    return static_dispatch.iteratorProcedureForDef(module, def_idx);
}

/// Record the reachability semantics introduced by the canonical
/// BuiltinLowLevel transform while the explicit CIR low-level node is still
/// available. Post-check stages consume this field directly from procedure
/// uses.
fn runtimeResultProvenanceForProcedureDef(
    module: TypedCIR.Module,
    def_idx: CIR.Def.Idx,
) ?RuntimeResultProvenance {
    const op = module.moduleEnvConst().providedLowLevelForDef(def_idx) orelse return null;
    return if (op == .list_get_unsafe) .list_element_read else null;
}

