/// The defaulting oracle (src/types/literal_defaulting.zig), re-exported for
/// consumers reached through the checked artifact (monotype solving/lowering).
pub const literal_defaulting = types.literal_defaulting;

/// The exact-numeral value authority (src/types/numeral.zig), re-exported for
/// consumers reached through the checked artifact (monotype lowering).
pub const exact_numeral = types.numeral;

/// Public `NumericDefaultPhase` declaration; the defaulting oracle owns the
/// enum and the target each phase materializes.
pub const NumericDefaultPhase = literal_defaulting.NumericDefaultPhase;

/// Public `RowDefault` declaration.
pub const RowDefault = enum {
    empty_record,
    empty_tag_union,
};

/// Public `CheckedTypeVariable` declaration (read form).
pub const CheckedTypeVariable = CheckedTypeVariableOf(CheckedConstraints);

/// The build form of `CheckedTypeVariable`, whose constraints are a slice it
/// owns.
pub const CheckedTypeVariableBuild = CheckedTypeVariableOf([]const CheckedStaticDispatchConstraint);

fn CheckedTypeVariableOf(comptime Constraints: type) type {
    return struct {
        const Self = @This();

        name: ?[]const u8 = null,
        constraints: Constraints = if (Constraints == CheckedConstraints) .empty else &.{},
        numeric_default_phase: ?NumericDefaultPhase = null,
        row_default: ?RowDefault = null,
        /// A variable whose every constraint is an `is_eq` or `to_hash`: the
        /// obligations deriving those methods over an open row give its tail.
        /// Closing the row satisfies them, so a flex tail still seals to its row
        /// default (design.md "Derived Equality And Hashing Over Open Rows"), and
        /// a result row ending in the variable may still be determined by its
        /// request (design.md "Closed Result Rows At Template Boundaries").
        row_default_discharges_constraints: bool = false,
        /// An implicitly opened row of an annotated definition that the
        /// annotation bounds (design.md "Polarity"): the definition's body can
        /// never add a tag to the row, only an instantiation of the definition
        /// can. `.boxy` seals such a scheme variable to the empty row (design.md
        /// "Sealed Result Rows").
        bounded_row_ext: bool = false,

        /// A build form owning a copy of this read form's constraints.
        pub fn toBuild(self: Self, allocator: Allocator) Allocator.Error!CheckedTypeVariableBuild {
            return .{
                .name = if (self.name) |name| try allocator.dupe(u8, name) else null,
                .constraints = try self.constraints.dupe(allocator),
                .numeric_default_phase = self.numeric_default_phase,
                .row_default = self.row_default,
                .row_default_discharges_constraints = self.row_default_discharges_constraints,
                .bounded_row_ext = self.bounded_row_ext,
            };
        }
    };
}

/// Artifact-stable identity of a `??` default in its declaring module; see
/// design.md "Defaulted Fields".
pub const CheckedFieldDefault = extern struct {
    origin_module: OptionalModuleIdentityId = .none,
    expr_node: u32 = 0,

    // Inline element of the serialized `record_field_pool`: the optional
    // wrapper must not disturb the 8-byte row layout.
    comptime {
        std.debug.assert(@sizeOf(CheckedFieldDefault) == 8);
        std.debug.assert(@alignOf(CheckedFieldDefault) == 4);
    }

    pub const none: CheckedFieldDefault = .{};

    pub fn fromParts(origin_module: canonical.ModuleIdentityId, expr_node: u32) CheckedFieldDefault {
        return .{ .origin_module = .some(origin_module), .expr_node = expr_node };
    }

    pub fn origin(self: CheckedFieldDefault) ?canonical.ModuleIdentityId {
        return self.origin_module.get();
    }
};

/// Exact checker-selected default for a field omitted at one record
/// construction site. This remains separate from the record's final checked
/// type because ordinary value unification may normalize that shared field to
/// `required` after the construction decision has already been made.
pub const CheckedRecordOmittedDefault = extern struct {
    expr: CIR.Expr.Idx,
    field_name: canonical.RecordFieldLabelId,
    default: CheckedFieldDefault,
};

/// A field kind a quantified kind variable was instantiated at, by storage: a
/// `defaulted` field is stored as a `required` one.
pub const CheckedCommittedKind = enum(u8) { required, optional };

/// Published field-kind axis. `required` and `defaulted` use inline slots;
/// `optional` uses the tagged slot defined in design.md "Field Kinds".
pub const CheckedFieldKind = extern struct {
    tag: Tag = .required,
    default: CheckedFieldDefault = .none,
    variable: OptionalCheckedTypeId = .none,

    pub const Tag = enum(u32) { required, optional, defaulted, undetermined, err };

    // Inline element of the serialized `record_field_pool`: tag word plus the
    // 8-byte default identity.
    comptime {
        std.debug.assert(@sizeOf(CheckedFieldKind) == 16);
        std.debug.assert(@alignOf(CheckedFieldKind) == 4);
    }

    pub const required: CheckedFieldKind = .{};
    pub const optional: CheckedFieldKind = .{ .tag = .optional };
    pub const err: CheckedFieldKind = .{ .tag = .err };

    pub fn undetermined(variable: CheckedTypeId) CheckedFieldKind {
        return .{ .tag = .undetermined, .variable = .some(variable) };
    }

    pub fn defaultedFromParts(origin_module: canonical.ModuleIdentityId, expr_node: u32) CheckedFieldKind {
        return .{ .tag = .defaulted, .default = CheckedFieldDefault.fromParts(origin_module, expr_node) };
    }

    /// The default identity carried by a `.defaulted` kind, else null.
    pub fn defaultIdentity(self: CheckedFieldKind) ?CheckedFieldDefault {
        return if (self.tag == .defaulted) self.default else null;
    }

    pub fn undeterminedVariable(self: CheckedFieldKind) ?CheckedTypeId {
        return if (self.tag == .undetermined) self.variable.get() else null;
    }
};

