/// Build form of `CheckedTagUnionType`: tags carry their own arg slices.
pub const CheckedTagUnionTypeBuild = struct {
    tags: []const CheckedTag,
    ext: CheckedTypeId,
};

/// Public `CheckedFunctionKind` declaration.
