test "published closed roots compose three deep and a closed cyclic root does not" {
    const testing = std.testing;
    const TestEnv = @import("test/TestEnv.zig");
    const allocator = testing.allocator;

    var test_env = try TestEnv.initOpen("Main", "value = {}");
    defer test_env.deinit();
    try test_env.assertNoErrors();

    const types_store = &test_env.module_env.types;
    const inner_name = try test_env.module_env.insertIdent(Ident.for_text("inner"));
    const middle_name = try test_env.module_env.insertIdent(Ident.for_text("middle"));
    const outer_name = try test_env.module_env.insertIdent(Ident.for_text("outer"));
    const Build = struct {
        fn record(store: *types.Store, name: Ident.Idx, field: Var) Allocator.Error!Var {
            return try store.freshFromContent(.{ .structure = .{ .record = .{
                .fields = try store.appendRecordFields(&.{.{ .name = name, .presence = .required(field) }}),
                .ext = try store.freshFromContent(.{ .structure = .empty_record }),
            } } });
        }
    };
    const leaf = try types_store.freshFromContent(.{ .structure = .empty_record });
    const inner = try Build.record(types_store, inner_name, leaf);
    const middle = try Build.record(types_store, middle_name, inner);
    const outer = try Build.record(types_store, outer_name, middle);
    // A closed recursive tuple and a parent that holds it beside `inner`.
    const cyclic = try types_store.fresh();
    try types_store.setVarContent(cyclic, .{ .structure = .{ .tuple = .{ .elems = try types_store.appendVars(&.{ cyclic, leaf }) } } });
    const holder = try types_store.freshFromContent(.{ .structure = .{ .tuple = .{ .elems = try types_store.appendVars(&.{ cyclic, inner }) } } });

    try test_env.module_env.types.canonicalizeAndSeal(test_env.module_env.getIdentStoreConst());
    const source_modules = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = test_env.module_env },
    };
    var modules = try TypedCIR.Modules.init(allocator, &source_modules);
    defer modules.deinit();
    const module = modules.module(0);
    const imports = CheckedImportViews{ .current_owner = testCheckedModuleKey(1).digest(), .direct = &.{} };

    const fresh_outer = try canonical_type_keys.fromVarInfo(allocator, module.typeStoreConst(), module.moduleEnvConst(), outer);
    const fresh_holder = try canonical_type_keys.fromVarInfo(allocator, module.typeStoreConst(), module.moduleEnvConst(), holder);
    const fresh_cyclic = try canonical_type_keys.fromVarInfo(allocator, module.typeStoreConst(), module.moduleEnvConst(), cyclic);
    try testing.expect(fresh_outer.composable);
    // The cyclic root's own encoding writes a cycle reference, so it is not
    // composable; its parent refers to it by key and is.
    try testing.expect(!fresh_cyclic.composable);
    try testing.expect(!fresh_cyclic.contains_identity_variables);
    try testing.expect(fresh_holder.composable);

    // Publish children first, so each parent's key is composed from its
    // children's stored keys, and then publish only the outermost roots.
    for ([_]bool{ true, false }) |children_first| {
        var names = canonical.CanonicalNameStore.init(allocator);
        defer names.deinit();
        var store = CheckedTypeStore{};
        defer store.deinit(allocator);
        var active = try CheckedSourceTypeRoots.init(allocator, module);
        defer active.deinit();
        const test_keys = try attachTestSealedTypes(allocator, module, &names, imports, &store);
        defer test_keys.destroy();

        if (children_first) {
            for ([_]Var{ leaf, inner, middle, cyclic }) |child| {
                _ = try appendCheckedTypeRoot(allocator, module, &store, &active, child);
            }
        }
        const checked_outer = try appendCheckedTypeRoot(allocator, module, &store, &active, outer);
        const checked_holder = try appendCheckedTypeRoot(allocator, module, &store, &active, holder);
        const checked_cyclic = try appendCheckedTypeRoot(allocator, module, &store, &active, cyclic);

        try testing.expectEqualSlices(u8, &fresh_outer.key.bytes, &(try store.rootKey(checked_outer)).bytes);
        try testing.expectEqualSlices(u8, &fresh_holder.key.bytes, &(try store.rootKey(checked_holder)).bytes);
        try testing.expectEqualSlices(u8, &fresh_cyclic.key.bytes, &(try store.rootKey(checked_cyclic)).bytes);
        try testing.expect(try store.rootIsComposable(checked_outer));
        try testing.expect(!try store.rootIsComposable(checked_cyclic));
        try testing.expect(try store.rootIsComposable(checked_holder));
        for ([_]CheckedTypeId{ checked_outer, checked_holder, checked_cyclic }, [_]canonical.CanonicalTypeKey{ fresh_outer.key, fresh_holder.key, fresh_cyclic.key }) |root, expected| {
            const substituted = try testFreshCheckedKeyInfo(allocator, &names, &store, root);
            try testing.expectEqualSlices(u8, &expected.bytes, &substituted.key.bytes);
        }
    }
}

test "a synthetic function over composed roots has the source function key" {
    const allocator = std.testing.allocator;

    var env = try ModuleEnv.init(allocator, "");
    defer env.deinit();
    var source_store = try types.Store.initCapacity(allocator, 16, 8);
    defer source_store.deinit();
    const source_empty = try source_store.freshFromContent(.{ .structure = .empty_record });
    const source_fn = try source_store.freshFromContent(.{ .structure = .{ .fn_pure = .{
        .args = try source_store.appendVars(&.{source_empty}),
        .ret = source_empty,
    } } });
    const source_info = try canonical_type_keys.fromVarInfo(allocator, &source_store, &env, source_fn);
    try std.testing.expect(source_info.composable);

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    var checked_store = CheckedTypeStore{};
    defer checked_store.deinit(allocator);
    try attachTestSynthesizedKeys(allocator, &checked_store, &names);
    const checked_empty = try appendExplicitCheckedTypePayload(allocator, &checked_store, .empty_record);
    try std.testing.expect(try checked_store.rootIsComposable(checked_empty));

    // A function root keyed from its payload.
    const published = try checked_store.reserveSyntheticTypeRoot(allocator);
    try checked_store.fillSyntheticTypeRoot(allocator, published, .{ .function = .{
        .kind = .pure,
        .args = try allocator.dupe(CheckedTypeId, &.{checked_empty}),
        .ret = checked_empty,
    } });
    try std.testing.expectEqualSlices(u8, &source_info.key.bytes, &(try checked_store.rootKey(published)).bytes);

    const synthetic = try checked_store.appendSyntheticFunctionRoot(allocator, .pure, &.{checked_empty}, checked_empty);
    try std.testing.expectEqualSlices(u8, &source_info.key.bytes, &(try checked_store.rootKey(synthetic)).bytes);
    try std.testing.expect(try checked_store.view().sameType(published, synthetic));
}

test "defaulted record canonical keys agree across solver and checked representations" {
    const allocator = std.testing.allocator;

    var env = try ModuleEnv.init(allocator, "");
    defer env.deinit();
    try env.setContentIdentity(@as([32]u8, @splat(0xAB)));
    const count_name = try env.insertIdent(Ident.for_text("count"));

    var source_store = try types.Store.initCapacity(allocator, 32, 16);
    defer source_store.deinit();
    const field_var = try source_store.freshFromContent(.{ .structure = .empty_record });
    const ext_var = try source_store.freshFromContent(.{ .structure = .empty_record });
    const default_id = types.DefaultId{ .origin_module = env.selfModuleIdentity(), .expr_node = 7 };
    const presence_var = try source_store.freshFromContent(.{ .field_presence = .{ .defaulted = default_id } });
    const source_fields = try source_store.appendRecordFields(&.{.{
        .name = count_name,
        .presence = .unknown(presence_var, field_var),
    }});
    const source_record = try source_store.freshFromContent(.{ .structure = .{ .record = .{
        .fields = source_fields,
        .ext = ext_var,
    } } });
    const source_key = try canonical_type_keys.fromVar(allocator, &source_store, &env, source_record);

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    const checked_count_name = try names.internRecordFieldLabel("count");
    const canonical_origin = try names.internModuleIdentity(env.moduleIdentityHash(env.selfModuleIdentity()));

    var checked_store = CheckedTypeStore{};
    defer checked_store.deinit(allocator);

    try attachTestSynthesizedKeys(allocator, &checked_store, &names);
    const checked_empty = try appendExplicitCheckedTypePayload(allocator, &checked_store, .empty_record);
    const checked_fields = try allocator.alloc(CheckedRecordField, 1);
    checked_fields[0] = .{
        .name = checked_count_name,
        .ty = checked_empty,
        .kind = .defaultedFromParts(canonical_origin, 7),
    };
    const checked_record = try appendExplicitCheckedTypePayload(allocator, &checked_store, .{ .record = .{
        .fields = checked_fields,
        .ext = checked_empty,
    } });
    const checked_key = (try checked_store.rootKey(checked_record));

    // The same default identity keys identically across representations.
    try std.testing.expectEqualSlices(u8, &source_key.bytes, &checked_key.bytes);

    // A DIFFERENT default (another expr node) is a different type.
    const other_fields = try allocator.alloc(CheckedRecordField, 1);
    other_fields[0] = .{
        .name = checked_count_name,
        .ty = checked_empty,
        .kind = .defaultedFromParts(canonical_origin, 8),
    };
    const other_record = try appendExplicitCheckedTypePayload(allocator, &checked_store, .{ .record = .{
        .fields = other_fields,
        .ext = checked_empty,
    } });
    const other_key = (try checked_store.rootKey(other_record));
    try std.testing.expect(!std.meta.eql(checked_key.bytes, other_key.bytes));

    // And a plain required field is a different type from a defaulted one.
    const required_fields = try allocator.alloc(CheckedRecordField, 1);
    required_fields[0] = .{ .name = checked_count_name, .ty = checked_empty };
    const required_record = try appendExplicitCheckedTypePayload(allocator, &checked_store, .{ .record = .{
        .fields = required_fields,
        .ext = checked_empty,
    } });
    const required_key = (try checked_store.rootKey(required_record));
    try std.testing.expect(!std.meta.eql(checked_key.bytes, required_key.bytes));
}

