test "body analyses read state merges, divergence and inspect elision from the canonical bodies" {
    const testing = std.testing;
    const TestEnv = @import("test/TestEnv.zig");
    const allocator = testing.allocator;

    var test_env = try TestEnv.init("Main",
        \\pick = |tag| {
        \\    var $state = {}
        \\    match tag {
        \\        A => {
        \\            $state = {}
        \\            $state
        \\        }
        \\        B => $state
        \\    }
        \\}
    );
    defer test_env.deinit();
    try testing.expectEqual(@as(usize, 0), test_env.checker.problems.problems.items.len);

    const source_modules = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = test_env.module_env },
    };
    var modules = try TypedCIR.Modules.init(allocator, &source_modules);
    defer modules.deinit();
    const module = modules.module(0);

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    try internLoweringVisibleNames(module.moduleEnvConst(), &names);

    const analyses = try BodyAnalyses.create(allocator, std.testing.io, module.moduleEnvConst(), &.{});
    defer analyses.destroy();
    analyses.markPublished();
    const publication_keys = try SealedTypeKeys.create(allocator, std.testing.io, module.moduleEnvConst());
    defer publication_keys.destroy();
    var checked_type_publication = try CheckedTypeStore.fromModule(
        allocator,
        module,
        &names,
        ModuleId{},
        &.{},
        &.{},
        &analyses.index,
        &.{},
        &.{},
        publication_keys,
    );
    defer checked_type_publication.deinit(allocator);
    const plans = static_dispatch.StaticDispatchPlanTable{};
    const bodies = CheckedBodies{
        .env = module.moduleEnvConst(),
        .names = &names,
        .types = checked_type_publication.store.view(),
        .analyses = analyses,
        .tables = .{ .plans = &plans },
    };

    var saw_match = false;
    var saw_lambda = false;
    for (bodies.index().node_kinds, 0..) |kind, raw| switch (kind) {
        .expr => {
            const expr: CIR.Expr.Idx = @fromBackingInt(@intCast(raw));
            switch (bodies.exprData(expr)) {
                .match_ => {
                    const binders = try bodies.stateMergeBinders(expr);
                    try testing.expectEqual(@as(usize, 1), binders.len);
                    try testing.expect(bodies.binder(binders[0]).reassignable);
                    try testing.expect(!try bodies.exprDiverges(expr, .run));
                    saw_match = true;
                },
                .lambda => {
                    try testing.expect(!try bodies.exprDiverges(expr, .run));
                    try testing.expect(try bodies.exprEvaluationMayBeElidedForInspect(expr));
                    saw_lambda = true;
                },
                .numeral, .str_segment, .str, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .binop, .unary_minus, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .runtime_error, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => {},
            }
        },
        .pattern, .statement, .unreached => {},
    };
    try testing.expect(saw_match);
    try testing.expect(saw_lambda);
}

test "checked binder mutability comes from the CIR var tag, not identifier spelling" {
    const testing = std.testing;
    const TestEnv = @import("test/TestEnv.zig");
    const allocator = testing.allocator;

    var test_env = try TestEnv.init("Main",
        \\main = |_| {
        \\    var $mutable = {}
        \\    $immutable = {}
        \\    $mutable = {}
        \\    ($mutable, $immutable)
        \\}
    );
    defer test_env.deinit();
    try testing.expectEqual(@as(usize, 0), test_env.checker.problems.problems.items.len);

    const mutable_ident = try test_env.module_env.insertIdent(Ident.for_text("$mutable"));
    const immutable_ident = try test_env.module_env.insertIdent(Ident.for_text("$immutable"));

    const source_modules = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = test_env.module_env },
    };
    var modules = try TypedCIR.Modules.init(allocator, &source_modules);
    defer modules.deinit();
    const module = modules.module(0);

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    try internLoweringVisibleNames(module.moduleEnvConst(), &names);

    const analyses = try BodyAnalyses.create(allocator, std.testing.io, module.moduleEnvConst(), &.{});
    defer analyses.destroy();
    analyses.markPublished();
    const publication_keys = try SealedTypeKeys.create(allocator, std.testing.io, module.moduleEnvConst());
    defer publication_keys.destroy();
    var checked_type_publication = try CheckedTypeStore.fromModule(
        allocator,
        module,
        &names,
        ModuleId{},
        &.{},
        &.{},
        &analyses.index,
        &.{},
        &.{},
        publication_keys,
    );
    defer checked_type_publication.deinit(allocator);
    const bodies = CheckedBodies{
        .env = module.moduleEnvConst(),
        .names = &names,
        .types = checked_type_publication.store.view(),
        .analyses = analyses,
    };

    var saw_mutable = false;
    var saw_immutable = false;
    var raw_node: u32 = 0;
    while (raw_node < module.nodeCount()) : (raw_node += 1) {
        const source_pattern: CIR.Pattern.Idx = @fromBackingInt(@intCast(raw_node));
        const tag = module.moduleEnvConst().store.nodes.get(@fromBackingInt(@intCast(raw_node))).tag;
        if (tag != .pattern_identifier and tag != .pattern_var_identifier) continue;
        const pattern = module.pattern(source_pattern).data;
        const ident = if (pattern == .assign) pattern.assign.ident else pattern.var_assign.ident;
        if (ident != mutable_ident and ident != immutable_ident) continue;

        if (!bodies.index().reachesPattern(source_pattern)) return error.TestUnexpectedResult;
        const binder = bodies.binder(source_pattern);
        if (ident == mutable_ident) {
            try testing.expect(binder.reassignable);
            saw_mutable = true;
        } else {
            try testing.expect(!binder.reassignable);
            saw_immutable = true;
        }
    }

    try testing.expect(saw_mutable);
    try testing.expect(saw_immutable);
}

test "poisoned record field presence preserves its value type and canonical key" {
    const testing = std.testing;
    const TestEnv = @import("test/TestEnv.zig");
    const allocator = testing.allocator;

    var test_env = try TestEnv.initOpen("Main", "value = {}");
    defer test_env.deinit();
    try test_env.assertNoErrors();

    // This is the solver state produced after a required-field destructure is
    // unified with an optional annotation: the field-presence axis is poisoned,
    // while the independent value-type axis remains valid.
    const field_name = try test_env.module_env.insertIdent(Ident.for_text("a"));
    const value_var = try test_env.module_env.types.freshFromContent(.{ .structure = .empty_tag_union });
    const presence_var = try test_env.module_env.types.freshFromContent(.err);
    const ext_var = try test_env.module_env.types.freshFromContent(.{ .structure = .empty_record });
    const source_fields = try test_env.module_env.types.appendRecordFields(&.{.{
        .name = field_name,
        .presence = .unknown(presence_var, value_var),
    }});
    const record_var = try test_env.module_env.types.freshFromContent(.{ .structure = .{ .record = .{
        .fields = source_fields,
        .ext = ext_var,
    } } });

    try test_env.module_env.types.canonicalizeAndSeal(test_env.module_env.getIdentStoreConst());
    const source_modules = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = test_env.module_env },
    };
    var modules = try TypedCIR.Modules.init(allocator, &source_modules);
    defer modules.deinit();
    const module = modules.module(0);

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    var store = CheckedTypeStore{};
    defer store.deinit(allocator);
    const imports = CheckedImportViews{ .current_owner = testCheckedModuleKey(1).digest(), .direct = &.{} };
    var active = try CheckedSourceTypeRoots.init(allocator, module);
    defer active.deinit();
    const test_keys = try attachTestSealedTypes(allocator, module, &names, imports, &store);
    defer test_keys.destroy();

    const checked_record = try appendCheckedTypeRoot(allocator, module, &store, &active, record_var);
    const checked_value = try appendCheckedTypeRoot(allocator, module, &store, &active, value_var);
    const fields = switch (store.payload(checked_record)) {
        .record => |record| record.fields,
        .pending, .field_kind, .err, .flex, .rigid, .alias, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => return error.TestUnexpectedResult,
    };
    try testing.expectEqual(@as(usize, 1), fields.len());
    try testing.expectEqual(checked_value, fields.get(0).ty);

    const source_key = try canonical_type_keys.fromVar(allocator, module.typeStoreConst(), module.moduleEnvConst(), record_var);
    const checked_key_info = try testFreshCheckedKeyInfo(allocator, &names, &store, checked_record);
    try testing.expectEqualSlices(u8, &source_key.bytes, &checked_key_info.key.bytes);
}

test "checked and source keys agree on recursive types however they are unrolled" {
    const testing = std.testing;
    const TestEnv = @import("test/TestEnv.zig");
    const allocator = testing.allocator;

    var test_env = try TestEnv.initOpen("Main", "value = {}");
    defer test_env.deinit();
    try test_env.assertNoErrors();

    const types_store = &test_env.module_env.types;
    const nil_name = try test_env.module_env.insertIdent(Ident.for_text("Nil"));
    const cons_name = try test_env.module_env.insertIdent(Ident.for_text("Cons"));
    const elem = try types_store.freshFromContent(.{ .flex = types.Flex.init() });
    const Build = struct {
        fn tagUnion(store: *types.Store, nil: Ident.Idx, cons: Ident.Idx, cons_args: []const Var) Allocator.Error!types.Content {
            return .{ .structure = .{ .tag_union = .{
                .tags = try store.appendTags(&.{
                    .{ .name = nil, .args = try store.appendVars(&.{}) },
                    .{ .name = cons, .args = try store.appendVars(cons_args) },
                }),
                .ext = try store.freshFromContent(.{ .structure = .empty_tag_union }),
            } } };
        }
    };
    // rolled = [Nil, Cons(a, rolled)], and the same type unrolled once.
    const rolled = try types_store.fresh();
    try types_store.setVarContent(rolled, try Build.tagUnion(types_store, nil_name, cons_name, &.{ elem, rolled }));
    const once = try types_store.freshFromContent(try Build.tagUnion(types_store, nil_name, cons_name, &.{ elem, rolled }));

    try test_env.module_env.types.canonicalizeAndSeal(test_env.module_env.getIdentStoreConst());
    const source_modules = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = test_env.module_env },
    };
    var modules = try TypedCIR.Modules.init(allocator, &source_modules);
    defer modules.deinit();
    const module = modules.module(0);

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    var store = CheckedTypeStore{};
    defer store.deinit(allocator);
    const imports = CheckedImportViews{ .current_owner = testCheckedModuleKey(1).digest(), .direct = &.{} };
    var active = try CheckedSourceTypeRoots.init(allocator, module);
    defer active.deinit();
    const test_keys = try attachTestSealedTypes(allocator, module, &names, imports, &store);
    defer test_keys.destroy();

    const checked_rolled = try appendCheckedTypeRoot(allocator, module, &store, &active, rolled);
    const checked_once = try appendCheckedTypeRoot(allocator, module, &store, &active, once);

    const source_key = try canonical_type_keys.fromVar(allocator, module.typeStoreConst(), module.moduleEnvConst(), rolled);
    const source_once_key = try canonical_type_keys.fromVar(allocator, module.typeStoreConst(), module.moduleEnvConst(), once);
    try testing.expectEqualSlices(u8, &source_key.bytes, &source_once_key.bytes);
    for ([_]CheckedTypeId{ checked_rolled, checked_once }) |root| {
        const checked_key_info = try testFreshCheckedKeyInfo(allocator, &names, &store, root);
        try testing.expectEqualSlices(u8, &source_key.bytes, &checked_key_info.key.bytes);
        try testing.expect(checked_key_info.contains_identity_variables);
    }
}

test "optional record fields publish through the declaration annotation path" {
    const testing = std.testing;
    const TestEnv = @import("test/TestEnv.zig");
    const allocator = testing.allocator;

    var test_env = try TestEnv.init("Main",
        \\Thing : { world ?: {}, req : {} }
        \\
        \\mk! : Thing
        \\mk! = { req: {} }
    );
    defer test_env.deinit();
    try test_env.assertNoErrors();

    const source_modules = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = test_env.module_env },
    };
    var modules = try TypedCIR.Modules.init(allocator, &source_modules);
    defer modules.deinit();
    const module = modules.module(0);
    const module_env = module.moduleEnvConst();

    // Find `Thing`'s alias declaration and its record annotation.
    const record_anno = blk: {
        for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
            const statement = module_env.store.getStatement(statement_idx);
            if (statement != .s_alias_decl) continue;
            const anno = module_env.store.getTypeAnno(statement.s_alias_decl.anno);
            if (anno != .record) continue;
            break :blk statement.s_alias_decl.anno;
        }
        return error.TestUnexpectedResult;
    };

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    var store = CheckedTypeStore{};
    defer store.deinit(allocator);
    const imports = CheckedImportViews{ .current_owner = testCheckedModuleKey(1).digest(), .direct = &.{} };
    var active = try CheckedSourceTypeRoots.init(allocator, module);
    defer active.deinit();
    const test_keys = try attachTestSealedTypes(allocator, module, &names, imports, &store);
    defer test_keys.destroy();
    var module_index = try ModuleIndex.build(allocator, module.moduleEnvConst(), &.{});
    defer module_index.deinit(allocator);
    var local_type_declarations = try LocalTypeDeclarationIndex.init(allocator, module, &module_index);
    defer local_type_declarations.deinit();

    const record_root = try appendCheckedTypeRootFromDeclarationAnno(
        allocator,
        module,
        &names,
        imports,
        &store,
        &active,
        &local_type_declarations,
        &.{},
        record_anno,
    );
    const fields = store.payload(record_root).record.fields;

    // The published row is in lexicographic label order, not source order.
    try testing.expectEqual(@as(usize, 2), fields.len());
    try testing.expectEqualStrings("req", names.recordFieldLabelText(fields.get(0).name));
    try testing.expectEqual(CheckedFieldKind.Tag.required, fields.get(0).kind.tag);
    try testing.expectEqualStrings("world", names.recordFieldLabelText(fields.get(1).name));
    try testing.expectEqual(CheckedFieldKind.Tag.optional, fields.get(1).kind.tag);
}

/// A nominal declaration backing published by declaration output, with the
/// state the walk published it into.
const PublishedNominalBacking = struct {
    store: *const CheckedTypeStore,
    names: *const canonical.CanonicalNameStore,
    active: *const CheckedSourceTypeRoots,
    root: CheckedTypeId,
};

const PublishedNominalBackingCheckError = error{ TestUnexpectedResult, TestExpectedEqual };

const PublishedNominalBackingTestError = @import("test/TestEnv.zig").TestEnvError || PublishedNominalBackingCheckError;

/// Check `source`, publish the backing of its nominal declaration named
/// `nominal_name` through declaration output, and hand the result to `check`.
fn checkPublishedNominalBacking(
    source: []const u8,
    nominal_name: []const u8,
    comptime check: fn (published: PublishedNominalBacking) PublishedNominalBackingCheckError!void,
) PublishedNominalBackingTestError!void {
    const testing = std.testing;
    const TestEnv = @import("test/TestEnv.zig");
    const allocator = testing.allocator;

    var test_env = try TestEnv.init("Main", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();

    const source_modules = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = test_env.module_env },
    };
    var modules = try TypedCIR.Modules.init(allocator, &source_modules);
    defer modules.deinit();
    const module = modules.module(0);
    const module_env = module.moduleEnvConst();

    const nominal_ident = module_env.getIdentStoreConst().lookup(Ident.for_text(nominal_name)) orelse return error.TestUnexpectedResult;
    const backing_anno = blk: {
        for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
            const statement = module_env.store.getStatement(statement_idx);
            if (statement != .s_nominal_decl) continue;
            const header = module_env.store.getTypeHeader(statement.s_nominal_decl.header);
            if (header.relative_name != nominal_ident) continue;
            break :blk statement.s_nominal_decl.anno;
        }
        return error.TestUnexpectedResult;
    };

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    var store = CheckedTypeStore{};
    defer store.deinit(allocator);
    const imports = CheckedImportViews{ .current_owner = testCheckedModuleKey(1).digest(), .direct = &.{} };
    var active = try CheckedSourceTypeRoots.init(allocator, module);
    defer active.deinit();
    const test_keys = try attachTestSealedTypes(allocator, module, &names, imports, &store);
    defer test_keys.destroy();
    var module_index = try ModuleIndex.build(allocator, module.moduleEnvConst(), &.{});
    defer module_index.deinit(allocator);
    var local_type_declarations = try LocalTypeDeclarationIndex.init(allocator, module, &module_index);
    defer local_type_declarations.deinit();

    const backing_root = try appendCheckedTypeRootFromDeclarationAnno(
        allocator,
        module,
        &names,
        imports,
        &store,
        &active,
        &local_type_declarations,
        &.{},
        backing_anno,
    );
    try check(.{ .store = &store, .names = &names, .active = &active, .root = backing_root });
}

test "nominal declaration backing row is in label order regardless of source order" {
    // The declaration lists `n` before `m`; the checked backing row is sorted
    // by label (design.md "Nominal Record Field Order"), so a consumer of a
    // single checked row may rely on its order without re-sorting.
    try checkPublishedNominalBacking(
        \\Px := { n : {}, m ?: {} }
    , "Px", struct {
        fn check(published: PublishedNominalBacking) PublishedNominalBackingCheckError!void {
            const testing = std.testing;
            const fields = published.store.payload(published.root).record.fields;
            try testing.expectEqual(@as(usize, 2), fields.len());
            try testing.expectEqualStrings("m", published.names.recordFieldLabelText(fields.get(0).name));
            try testing.expectEqual(CheckedFieldKind.Tag.optional, fields.get(0).kind.tag);
            try testing.expectEqualStrings("n", published.names.recordFieldLabelText(fields.get(1).name));
            try testing.expectEqual(CheckedFieldKind.Tag.required, fields.get(1).kind.tag);
        }
    }.check);
}

test "nominal declaration backing tag row is in label order regardless of source order" {
    try checkPublishedNominalBacking(
        \\Dir := [Up, Down, Left({})]
    , "Dir", struct {
        fn check(published: PublishedNominalBacking) PublishedNominalBackingCheckError!void {
            const testing = std.testing;
            const tags = published.store.payload(published.root).tag_union.tags;
            try testing.expectEqual(@as(usize, 3), tags.len());
            try testing.expectEqualStrings("Down", published.names.tagLabelText(tags.get(0).name));
            try testing.expectEqualStrings("Left", published.names.tagLabelText(tags.get(1).name));
            try testing.expectEqual(@as(usize, 1), tags.get(1).args.len);
            try testing.expectEqualStrings("Up", published.names.tagLabelText(tags.get(2).name));
        }
    }.check);
}

test "nominal declaration backing closes a referenced alias's tag union row" {
    // repro for https://github.com/roc-lang/roc/issues/12033
    // A nominal declaration body has no use-site polarity, so the `[POST]`
    // reached through `Method` closes as written in `Endpoint`'s published
    // backing, exactly like a `[POST]` written inline.
    try checkPublishedNominalBacking(
        \\Method : [POST]
        \\
        \\Endpoint :: { method : Method }
        \\
        \\books : Endpoint
        \\books = { method: POST }
    , "Endpoint", struct {
        fn check(published: PublishedNominalBacking) PublishedNominalBackingCheckError!void {
            const testing = std.testing;
            const store = published.store;
            const fields = store.payload(published.root).record.fields;
            try testing.expectEqual(@as(usize, 1), fields.len());
            try testing.expectEqualStrings("method", published.names.recordFieldLabelText(fields.get(0).name));

            const method = store.payload(fields.get(0).ty);
            try testing.expect(method == .alias);
            const row = store.payload(method.alias.backing);
            try testing.expect(row == .tag_union);
            try testing.expectEqual(@as(usize, 1), row.tag_union.tags.len());
            try testing.expectEqual(std.meta.Tag(CheckedTypePayload).empty_tag_union, std.meta.activeTag(store.payload(row.tag_union.ext)));
        }
    }.check);
}

test "nominal declaration backing publishes each alias expansion once" {
    // Every level references the one below twice, so walking each reference
    // would be exponential in the chain. Each alias is expanded once and every
    // later reference shares that root.
    try checkPublishedNominalBacking(
        \\A0 : [X, Y]
        \\A1 : (A0, A0)
        \\A2 : (A1, A1)
        \\A3 : (A2, A2)
        \\A4 : (A3, A3)
        \\
        \\Thing :: { a : A4, b : A4 }
    , "Thing", struct {
        fn check(published: PublishedNominalBacking) PublishedNominalBackingCheckError!void {
            const testing = std.testing;
            const store = published.store;
            try testing.expectEqual(@as(u32, 5), published.active.scratch.?.alias_expansions.count());
            const fields = store.payload(published.root).record.fields;
            try testing.expectEqual(fields.get(0).ty, fields.get(1).ty);
            var current = store.payload(fields.get(0).ty);
            var depth: usize = 4;
            while (depth > 0) : (depth -= 1) {
                try testing.expect(current == .alias);
                const elems = store.payload(current.alias.backing).tuple;
                try testing.expectEqual(elems[0], elems[1]);
                current = store.payload(elems[0]);
            }
            try testing.expect(current == .alias);
            try testing.expectEqual(std.meta.Tag(CheckedTypePayload).empty_tag_union, std.meta.activeTag(store.payload(store.payload(current.alias.backing).tag_union.ext)));
        }
    }.check);
}

/// Attach `module`'s sealed types to `store` as publication does, for a test
/// that reads source types without publishing the module. The caller
/// destroys the returned key slots.
fn attachTestSealedTypes(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
) Allocator.Error!*sealed_type_keys.SealedTypeKeys {
    try sealed_type_view.buildColumns(allocator, module.moduleEnvConst(), names, imports, store.sealedColumns());
    const keys = try sealed_type_keys.SealedTypeKeys.create(allocator, std.testing.io, module.moduleEnvConst());
    errdefer keys.destroy();
    store.attachSealedTypes(module.moduleEnvConst(), keys, try SynthesizedTypeKeys.create(allocator, std.testing.io, store.roots.items().len));
    store.key_names = names;
    return keys;
}

/// Give a test store holding only synthesized types key slots and the name
/// store its keys read, when the test computes keys.
fn attachTestSynthesizedKeys(allocator: Allocator, store: *CheckedTypeStore, names: ?*const canonical.CanonicalNameStore) Allocator.Error!void {
    if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this
    store.attachSynthesizedKeys(try SynthesizedTypeKeys.create(allocator, std.testing.io, store.roots.items().len));
    store.key_names = names;
}

/// A checked type's key computed by a fresh key writer, independent of the
/// store's key slots.
fn testFreshCheckedKeyInfo(allocator: Allocator, names: *const canonical.CanonicalNameStore, store: *const CheckedTypeStore, root: CheckedTypeId) Allocator.Error!canonical_type_keys.TypeKeyInfo {
    if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this
    var digester = CheckedTypeKeyDigester.init(allocator, names, store.view());
    defer digester.deinit();
    return try digester.keyInfo(root);
}

const EmptyTagCheckedOutputTestError = @import("test/TestEnv.zig").TestEnvError || error{
    ExpectedFlexIdentity,
    ExpectedFunctionPayload,
};

test "checked row defaults apply only to unconstrained type variables" {
    const no_constraints = types.StaticDispatchConstraint.SafeList.Range.empty();
    const one_constraint = types.StaticDispatchConstraint.SafeList.Range{
        // The helper inspects only the range count, so no backing-list index is read.
        .start = undefined,
        .count = 1,
    };

    try std.testing.expectEqual(
        RowDefault.empty_record,
        checkedTypeVariableRowDefault(.{ .flex = .{ .name = null, .constraints = no_constraints } }, .empty_record, false).?,
    );
    try std.testing.expectEqual(
        RowDefault.empty_tag_union,
        checkedTypeVariableRowDefault(.{ .rigid = .{ .name = Ident.Idx.NONE, .constraints = no_constraints } }, .empty_tag_union, false).?,
    );
    try std.testing.expectEqual(
        null,
        checkedTypeVariableRowDefault(.{ .flex = .{ .name = null, .constraints = one_constraint } }, .empty_record, false),
    );
    try std.testing.expectEqual(
        null,
        checkedTypeVariableRowDefault(.{ .rigid = .{ .name = Ident.Idx.NONE, .constraints = one_constraint } }, .empty_tag_union, false),
    );
}

