test "independent closed function graphs share one key and add no synthesized roots" {
    const allocator = std.testing.allocator;
    try withEmptyTagCheckedOutputForTest(allocator, struct {
        fn inspect(module: TypedCIR.Module, names: *canonical.CanonicalNameStore, imports: CheckedImportViews, store: *CheckedTypeStore, type_store: *types.Store, _: Var) EmptyTagCheckedOutputTestError!void {
            const first_arg = try type_store.freshFromContent(.{ .structure = .empty_record });
            const first_ret = try type_store.freshFromContent(.{ .structure = .empty_tag_union });
            const first_fn = try type_store.freshFromContent(try type_store.mkFuncPure(&.{first_arg}, first_ret));

            const second_arg = try type_store.freshFromContent(.{ .structure = .empty_record });
            const second_ret = try type_store.freshFromContent(.{ .structure = .empty_tag_union });
            const second_fn = try type_store.freshFromContent(try type_store.mkFuncPure(&.{second_arg}, second_ret));

            try type_store.canonicalizeAndSeal(module.identStoreConst());
            var active = try CheckedSourceTypeRoots.init(allocator, module);
            defer active.deinit();
            const test_keys = try attachTestSealedTypes(allocator, module, names, imports, store);
            defer test_keys.destroy();
            const root_count = store.roots.items().len;
            const first = try appendCheckedTypeRoot(allocator, module, store, &active, first_fn);
            const second = try appendCheckedTypeRoot(allocator, module, store, &active, second_fn);

            try std.testing.expectEqualSlices(u8, &(try store.rootKey(first)).bytes, &(try store.rootKey(second)).bytes);
            try std.testing.expectEqual(root_count, store.roots.items().len);
        }
    }.inspect);
}

test "checker marks exhaustiveness-defaulted empty payload provenance" {
    const TestEnv = @import("test/TestEnv.zig");
    const source =
        \\x : Try(I64, _)
        \\x = Ok(42)
        \\
        \\result : I64
        \\result = match x {
        \\    Ok(value) => value
        \\}
    ;
    var test_env = try TestEnv.init("Main", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();

    const defs = test_env.module_env.store.sliceDefs(test_env.module_env.all_defs);
    if (defs.len == 0) return error.TestUnexpectedResult;
    const x_var = ModuleEnv.varFrom(defs[0]);

    const x_content = test_env.module_env.types.resolveVar(x_var).desc.content;
    if (x_content != .structure or x_content.structure != .nominal_type) return error.TestUnexpectedResult;
    const nominal = x_content.structure.nominal_type;
    const args = test_env.module_env.types.sliceVars(nominal.args);
    try std.testing.expectEqual(@as(usize, 2), args.len);
    const err_desc = test_env.module_env.types.resolveVar(args[1]).desc;
    try std.testing.expectEqual(types.Content{ .structure = .empty_tag_union }, err_desc.content);
    try std.testing.expect(err_desc.flags.empty_tag_union_is_default);
}

test "checked output retains defaulted identity inside parent function digest" {
    const allocator = std.testing.allocator;
    try withEmptyTagCheckedOutputForTest(allocator, struct {
        fn inspect(module: TypedCIR.Module, names: *canonical.CanonicalNameStore, imports: CheckedImportViews, store: *CheckedTypeStore, type_store: *types.Store, _: Var) EmptyTagCheckedOutputTestError!void {
            const identity = try type_store.fresh();
            try type_store.setVarToEmptyTagUnionDefault(identity);
            const function_content = try type_store.mkFuncPure(&.{identity}, identity);
            const function_var = try type_store.freshFromContent(function_content);
            try type_store.canonicalizeAndSeal(module.identStoreConst());
            var active = try CheckedSourceTypeRoots.init(allocator, module);
            defer active.deinit();
            const test_keys = try attachTestSealedTypes(allocator, module, names, imports, store);
            defer test_keys.destroy();
            const root = try appendCheckedTypeRoot(allocator, module, store, &active, function_var);
            const root_payload = store.payload(root);
            if (root_payload != .function) return error.ExpectedFunctionPayload;
            const function = root_payload.function;
            try std.testing.expectEqual(@as(usize, 1), function.args.len);
            try std.testing.expectEqual(function.args[0], function.ret);
            const return_payload = store.payload(function.ret);
            if (return_payload != .flex) return error.ExpectedFlexIdentity;
            const variable = return_payload.flex;
            try std.testing.expectEqual(RowDefault.empty_tag_union, variable.row_default.?);
        }
    }.inspect);
}

/// Empty per-artifact tables for building `ImportedModuleView`s in tests.
const TestImportViewTables = struct {
    /// The store a view's dispatch resolution would synthesize types in;
    /// these views resolve no dispatch, so it stays empty.
    checked_type_store: CheckedTypeStore = .{},
    checked_const_bodies: CheckedConstBodyTable = .{},
    checked_procedure_templates: CheckedProcedureTemplateTable = .{},
    compile_time_roots: CompileTimeRootTable = .{},
    entry_wrappers: EntryWrapperTable = .{},
    intrinsic_wrappers: IntrinsicWrapperTable = .{},
    resolved_value_refs: ResolvedValueRefTable = .{},
    static_dispatch_plans: static_dispatch.StaticDispatchPlanTable = .{},
    hosted_procs: HostedProcTable = .{},
    hosted_bindings: HostedBindingTable = .{},
    exported_procedure_templates: ExportedProcedureTemplateTable = .{},
    exported_procedure_bindings: ExportedProcedureBindingTable = .{},
    exported_const_templates: ExportedConstTemplateTable = .{},
    provided_exports: ProvidedExportTable = .{},
    top_level_procedure_bindings: TopLevelProcedureBindingTable = .{},
    platform_required_declarations: PlatformRequiredDeclarationTable = .{},
    platform_required_bindings: PlatformRequiredBindingTable = .{},
    callable_eval_templates: CallableEvalTemplateTable = .{},
    hoisted_constants: HoistedConstTable = .{},
    const_templates: ConstTemplateTable = .{},
    method_registry: static_dispatch.MethodRegistry = .{},
    const_store: ConstStore,
    analyses: std.ArrayList(*BodyAnalyses) = .empty,
    allocator: Allocator,

    fn init(allocator: Allocator) TestImportViewTables {
        if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this
        return .{ .const_store = ConstStore.init(allocator), .allocator = allocator };
    }

    fn deinit(self: *TestImportViewTables) void {
        for (self.analyses.items) |analyses| analyses.destroy();
        self.analyses.deinit(self.allocator);
        self.const_store.deinit();
        self.checked_type_store.deinit(self.allocator);
    }

    fn view(
        self: *TestImportViewTables,
        key: CheckedModuleArtifactKey,
        module_env: *const ModuleEnv,
        names: *const canonical.CanonicalNameStore,
        identity: ModuleIdentity,
        store: *const CheckedTypeStore,
    ) Allocator.Error!ImportedModuleView {
        const checked_types = store.view();
        const analyses = try BodyAnalyses.create(self.allocator, std.testing.io, module_env, &.{});
        analyses.markPublished();
        {
            errdefer analyses.destroy();
            try self.analyses.append(self.allocator, analyses);
        }
        return .{
            .key = key,
            .module_env = module_env,
            .canonical_names = names,
            .module_identity = identity,
            .exports = .{},
            .checked_types = checked_types,
            .checked_bodies = .{
                .env = module_env,
                .names = names,
                .types = checked_types,
                .analyses = analyses,
            },
            .checked_const_bodies = &self.checked_const_bodies,
            .checked_procedure_templates = &self.checked_procedure_templates,
            .compile_time_roots = &self.compile_time_roots,
            .entry_wrappers = &self.entry_wrappers,
            .intrinsic_wrappers = &self.intrinsic_wrappers,
            .resolved_value_refs = &self.resolved_value_refs,
            .static_dispatch_plans = &self.static_dispatch_plans,
            .hosted_procs = &self.hosted_procs,
            .hosted_bindings = &self.hosted_bindings,
            .exported_procedure_templates = self.exported_procedure_templates.view(),
            .exported_procedure_bindings = self.exported_procedure_bindings.view(),
            .exported_const_templates = self.exported_const_templates.view(),
            .provided_exports = &self.provided_exports,
            .top_level_procedure_bindings = &self.top_level_procedure_bindings,
            .platform_required_declarations = &self.platform_required_declarations,
            .platform_required_bindings = &self.platform_required_bindings,
            .callable_eval_templates = self.callable_eval_templates.view(),
            .hoisted_constants = &self.hoisted_constants,
            .const_templates = &self.const_templates,
            .method_registry = &self.method_registry,
            .const_store = &self.const_store,
        };
    }
};

test "checked artifact builtin nominal categorization requires explicit builtin origin" {
    const testing = std.testing;
    const TestEnv = @import("test/TestEnv.zig");
    const allocator = testing.allocator;

    var test_env = try TestEnv.init("Main", "x = 1");
    defer test_env.deinit();
    try test_env.assertNoErrors();

    const source_modules = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = test_env.module_env },
    };
    var modules = try TypedCIR.Modules.init(allocator, &source_modules);
    defer modules.deinit();

    const module = modules.module(0);
    const builtin_env = test_env.builtin_module.env;
    var builtin_names = canonical.CanonicalNameStore.init(allocator);
    defer builtin_names.deinit();
    try internLoweringVisibleNames(builtin_env, &builtin_names);

    const builtin_module_name = try builtin_names.internModuleName(builtin_env.module_name);
    const builtin_identity = ModuleIdentity{
        .stable_hash = @as([32]u8, @splat(0)),
        .module_idx = 1,
        .module_name = builtin_module_name,
        .display_module_name = builtin_module_name,
        .kind = builtin_env.module_kind,
    };

    var tables = TestImportViewTables.init(allocator);
    defer tables.deinit();
    const builtin_view = try tables.view(.{}, builtin_env, &builtin_names, builtin_identity, &tables.checked_type_store);
    const imports = [_]PublishImportArtifact{.{
        .module_idx = 1,
        .key = .{},
        .view = builtin_view,
    }};

    const bool_source_decl = try testTypeDeclSourceDeclForIdent(builtin_env, builtin_env.idents.bool_type);
    const builtin_hash = builtin_env.contentIdentityHash() orelse return error.TestUnexpectedResult;
    const nominal = types.NominalType{
        .ident = .{ .ident_idx = module.commonIdents().bool_type },
        .args = types.Var.SafeList.Range.empty(),
        .origin_module = try @constCast(module.moduleEnvConst()).internModuleIdentity(builtin_hash, base.Ident.Idx.NONE),
        .source = try types.NominalType.Source.initChecked(try types.types.SourceDecl.fromStatementChecked(bool_source_decl), false, false),
    };

    try testing.expect(categorizeBuiltinNominal(module, .{ .current_owner = testCheckedModuleKey(1).digest(), .direct = &imports }, nominal) == null);
}

test "imported origin resolution visits each import view and owner declaration once" {
    const testing = std.testing;
    const TestEnv = @import("test/TestEnv.zig");
    const allocator = testing.allocator;

    var test_env = try TestEnv.init("Main", "x = 1");
    defer test_env.deinit();
    const module_env = test_env.module_env;

    var tables = TestImportViewTables.init(allocator);
    defer tables.deinit();
    var owner_names = canonical.CanonicalNameStore.init(allocator);
    defer owner_names.deinit();
    const owner_module_name = try owner_names.internModuleName("Owner");

    // One owner module declares many nominals; the importing module also
    // sees many unrelated views. Publishing a reference to every declaration
    // used to rescan every view and every owner declaration per reference.
    const view_count = 64;
    const declaration_count = 256;
    const owner_view_index = view_count / 2;
    var owner_hash: [32]u8 = @splat(0);
    owner_hash[0] = owner_view_index;
    const owner_identity_id = try owner_names.internModuleIdentity(&owner_hash);

    var declarations: [declaration_count]CheckedNominalDeclaration = undefined;
    for (&declarations, 0..) |*declaration, index| {
        declaration.* = .{
            .id = @fromBackingInt(@intCast(index)),
            .nominal = .{ .module = owner_identity_id, .source_decl = @intCast(index) },
            .source_statement = @intCast(index),
            // Origin resolution reads only the id, nominal key and statement.
            .declaration_root = undefined,
            .backing = undefined,
        };
    }

    var owner_store = CheckedTypeStore{ .nominal_declarations = .borrowing(&declarations) };
    defer owner_store.deinit(allocator);
    var views: [view_count]ImportedModuleView = undefined;
    for (&views, 0..) |*view, index| {
        var hash: [32]u8 = @splat(0);
        hash[0] = @intCast(index);
        view.* = try tables.view(testCheckedModuleKey(@intCast(index)), module_env, &owner_names, .{
            .stable_hash = hash,
            .module_idx = @intCast(index),
            .module_name = owner_module_name,
            .display_module_name = owner_module_name,
            .kind = module_env.module_kind,
        }, if (index == owner_view_index) &owner_store else &tables.checked_type_store);
    }
    const imports = CheckedImportViews{
        .current_owner = testCheckedModuleKey(255).digest(),
        .direct = &.{},
        .available = &views,
    };
    const origin = try module_env.internModuleIdentity(&owner_hash, base.Ident.Idx.NONE);

    var index = ImportedOriginIndex.init(allocator);
    defer index.deinit();
    for (0..declaration_count) |statement| {
        try testing.expect(testCheckedModuleKey(owner_view_index).digest().eql(try index.owner(module_env, imports, origin)));
        const found = try index.nominalDeclaration(module_env, imports, origin, @intCast(statement));
        try testing.expect(testCheckedModuleKey(owner_view_index).digest().eql(found.artifact));
        try testing.expectEqual(declarations[statement].id, found.declaration);
    }
    try testing.expectEqual(@as(u64, view_count), index.view_visits);
    try testing.expectEqual(@as(u64, declaration_count), index.declaration_visits);
}

fn moduleEnvIdentityMatches(module_env: *const ModuleEnv, origin_hash: *const [32]u8) bool {
    const env_hash = module_env.contentIdentityHash() orelse return false;
    return base.ModuleIdentity.eql(env_hash, origin_hash);
}

/// A nominal application's opacity is its declaration's: checked type keys
/// identify a nominal by its declaration alone, so applications that disagree
/// would share one key while lowering to different types.
pub fn debugAssertNominalOpacityMatchesDeclaration(type_store: *const types.Store, nominal: types.NominalType) void {
    if (builtin.mode != .debug) return;
    const decl_idx = type_store.lookupNominalDecl(nominal) orelse return;
    if (type_store.getNominalDecl(decl_idx).source.isOpaque() != nominal.isOpaque()) {
        checkedArtifactInvariant("nominal application opacity disagrees with its declaration", .{});
    }
}

/// The checked representation of a source nominal application.
pub fn checkedNominalRepresentationForSourceNominal(
    module: TypedCIR.Module,
    imports: CheckedImportViews,
    origins: *ImportedOriginIndex,
    local_nominal_declarations: *const LocalNominalDeclarationIds,
    nominal: types.NominalType,
    builtin_nominal: ?CheckedBuiltinNominal,
) Allocator.Error!CheckedNominalRepresentationRef {
    if (builtin_nominal) |builtin_id| return .{ .builtin = builtin_id };

    const module_env = module.moduleEnvConst();
    if (nominal.origin_module == module_env.selfModuleIdentity()) {
        return .{ .local_declaration = local_nominal_declarations.get(@fromBackingInt(@intCast(nominal.statement()))) };
    }

    return .{ .imported_declaration = try origins.nominalDeclaration(
        module_env,
        imports,
        nominal.origin_module,
        nominal.statement(),
    ) };
}

/// `checkedNominalRepresentationForSourceNominal`, or null when the
/// declaration's owner is not available to the module: a local declaration
/// checking rejected, or an imported one no import view carries.
pub fn checkedNominalRepresentationIfAvailable(
    module_env: *const ModuleEnv,
    imports: CheckedImportViews,
    origins: *ImportedOriginIndex,
    local_nominal_declarations: *const LocalNominalDeclarationIds,
    nominal: types.NominalType,
    builtin_nominal: ?CheckedBuiltinNominal,
) Allocator.Error!?CheckedNominalRepresentationRef {
    if (builtin_nominal) |builtin_id| return .{ .builtin = builtin_id };
    if (nominal.origin_module == module_env.selfModuleIdentity()) {
        const id = local_nominal_declarations.ids.get(@fromBackingInt(@intCast(nominal.statement()))) orelse return null;
        return .{ .local_declaration = id };
    }
    const declaration = (try origins.nominalDeclarationIfAvailable(module_env, imports, nominal.origin_module, nominal.statement())) orelse return null;
    return .{ .imported_declaration = declaration };
}

/// The checked declaration id of every published local nominal declaration,
/// keyed by its statement. Ids are dense in statement order over exactly the
/// declarations `appendCheckedNominalDeclarationFromStatement` publishes.
pub const LocalNominalDeclarationIds = struct {
    ids: std.AutoHashMap(CIR.Statement.Idx, CheckedNominalDeclarationId),

    pub fn init(allocator: Allocator, module: TypedCIR.Module) Allocator.Error!LocalNominalDeclarationIds {
        return initFromEnv(allocator, module.moduleEnvConst());
    }

    pub fn initFromEnv(allocator: Allocator, module_env: *const ModuleEnv) Allocator.Error!LocalNominalDeclarationIds {
        var ids = std.AutoHashMap(CIR.Statement.Idx, CheckedNominalDeclarationId).init(allocator);
        errdefer ids.deinit();
        var next_id: u32 = 0;
        for (module_env.store.sliceStatements(module_env.all_statements)) |candidate| {
            const statement = module_env.store.getStatement(candidate);
            if (statement != .s_nominal_decl) continue;
            if (statement.s_nominal_decl.anno == .placeholder) continue;
            if (!localNominalDeclarationIsValid(module_env, candidate)) continue;
            try ids.put(candidate, @fromBackingInt(@intCast(next_id)));
            next_id += 1;
        }
        return .{ .ids = ids };
    }

    pub fn deinit(self: *LocalNominalDeclarationIds) void {
        self.ids.deinit();
    }

    pub fn get(self: *const LocalNominalDeclarationIds, statement_idx: CIR.Statement.Idx) CheckedNominalDeclarationId {
        return self.ids.get(statement_idx) orelse
            checkedArtifactInvariant("checked nominal declaration statement had no declaration id", .{});
    }
};

/// Whether checking accepted the local nominal declaration at `statement_idx`.
pub fn localNominalDeclarationIsValid(
    module_env: *const ModuleEnv,
    statement_idx: CIR.Statement.Idx,
) bool {
    const types_store = &module_env.types;
    const decl_idx = types_store.lookupNominalDeclByKey(
        module_env.selfModuleIdentity(),
        @backingInt(statement_idx),
    ) orelse checkedArtifactInvariant("checked local nominal declaration had no checker declaration entry", .{});
    return types_store.getNominalDecl(decl_idx).isValid();
}

/// An owned copy of a variable's optional name text.
pub fn copyOptionalIdentText(
    allocator: Allocator,
    module: TypedCIR.Module,
    ident: ?Ident.Idx,
) Allocator.Error!?[]const u8 {
    const idx = ident orelse return null;
    return try copyIdentText(allocator, module, idx);
}

/// An owned copy of a variable name's text.
pub fn copyIdentText(
    allocator: Allocator,
    module: TypedCIR.Module,
    idx: Ident.Idx,
) Allocator.Error![]const u8 {
    return try allocator.dupe(u8, checkedVariableNameText(module.moduleEnvConst(), idx));
}

/// The text a checked type variable named `idx` publishes as its name.
pub fn checkedVariableNameText(module_env: *const ModuleEnv, idx: Ident.Idx) []const u8 {
    return module_env.getIdent(idx);
}

/// The published access operation of one record-field path segment
/// (design.md "Field Kinds (All-Dynamic Optional Fields)"): `required` is a
/// plain inline-slot projection; `optional` is a `.?` access whose lowering
/// tests the field's tagged slot at runtime.
pub const CheckedFieldAccessMode = enum(u8) {
    required,
    optional,
};

/// Kinds of checked sites that can be evaluated for comptime exhaustiveness.
pub const CheckedComptimeSiteKind = enum {
    match,
    destructure,
};

/// Describes whether an exhaustiveness site remains pending, can run at runtime, or is handled at compile time.
pub const ExhaustivenessResolutionPolicy = union(enum) {
    compile_time_replaced_by_root: ComptimeRootId,
    compile_time_only,
    runtime_reachable,
    /// No checked body reaches the site, so no evaluation decides it and its
    /// checking mode does.
    not_pending,
};

/// Checked owner that establishes the diagnostic and dependency context for an exhaustiveness site.
pub const CheckedExhaustivenessSiteOwner = union(enum) {
    procedure_template: canonical.ProcedureTemplateRef,
    root: ComptimeRootId,
};

/// Checked exhaustiveness metadata preserved for comptime evaluation and diagnostics.
pub const CheckedExhaustivenessSite = struct {
    id: CheckedExhaustivenessSiteId,
    kind: CheckedComptimeSiteKind,
    region: base.Region,
    owner: ?CheckedExhaustivenessSiteOwner = null,
    checked_expr: ?CIR.Expr.Idx = null,
    checked_pattern: ?CIR.Pattern.Idx = null,
    policy: ExhaustivenessResolutionPolicy,
    requires_pairing: bool = false,
};

/// Every exhaustiveness check of a module, by site id, with the owner and
/// policy that decide it (`ModuleAnalyses.exhaustivenessSites`).
pub const CheckedExhaustivenessSiteTable = struct {
    sites: []CheckedExhaustivenessSite = &.{},

    pub fn get(self: *const CheckedExhaustivenessSiteTable, id: CheckedExhaustivenessSiteId) CheckedExhaustivenessSite {
        const raw = @backingInt(id);
        if (raw >= self.sites.len) checkedArtifactInvariant("checked exhaustiveness site id out of range", .{});
        return self.sites[raw];
    }

    pub fn destroy(self: *CheckedExhaustivenessSiteTable, allocator: Allocator) void {
        allocator.free(self.sites);
        allocator.destroy(self);
    }
};

/// Public `CheckedCapture` declaration.
pub const CheckedCapture = struct {
    pattern: CIR.Pattern.Idx,
    scope_depth: u32,
    /// Canonical identity of the captured binding, carried immutably through
    /// every post-check IR. Derived from the capture's binder, so it is a pure
    /// function of (module name, source bytes) and cache-safe to serialize.
    capture_id: CaptureId,
};

/// Public `CheckedListRestPattern` declaration.
pub const CheckedListRestPattern = struct {
    index: u32,
    pattern: ?CIR.Pattern.Idx,
};

/// End behavior for a checked string interpolation pattern.
pub const CheckedStrPatternEnd = enum {
    exact,
    tail,
};

/// Public `CheckedReturnContext` declaration.
pub const CheckedReturnContext = enum {
    return_expr,
    try_suffix,
};

/// A candidate binder of a non-degenerate alternative pattern and the binder
/// of the same name in its branch's first pattern.
pub const AlternativeBinderRemap = struct {
    candidate_binder: CIR.Pattern.Idx,
    representative_binder: CIR.Pattern.Idx,
};

/// A platform's checked types under one platform/app pairing (or under the
/// platform/app relation a module was published with): the image of each
/// of the module's own source types that the pairing substitutes, by own
/// type, ascending. A type absent from the column is its own image.
pub const PairingTypeColumn = struct {
    images: []const PairingTypeImage = &.{},

    pub fn image(self: *const PairingTypeColumn, own: CheckedTypeId) CheckedTypeId {
        const found = artifact_serialize.binarySearchByKey(PairingTypeImage, CheckedTypeId, self.images, own, PairingTypeImage.order) orelse return own;
        return found.image;
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;

    pub const Serialized = extern struct {
        images: SerializedSlice(PairingTypeImage) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(PairingTypeColumn, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };
};

/// One entry of a `PairingTypeColumn`.
pub const PairingTypeImage = extern struct {
    own: CheckedTypeId,
    image: CheckedTypeId,

    fn order(entry: PairingTypeImage, key: CheckedTypeId) std.math.Order {
        return std.math.order(@backingInt(entry.own), @backingInt(key));
    }

    fn lessThan(_: void, a: PairingTypeImage, b: PairingTypeImage) bool {
        return @backingInt(a.own) < @backingInt(b.own);
    }
};

/// Whether inline expects run when lowering evaluates a body.
pub const InlineExpectMode = body_analyses.InlineExpectMode;
/// Divergence of a module's nodes under one specialization's evidence.
pub const DispatchDivergence = body_analyses.DispatchDivergence;
/// See `body_analyses.dispatchDivergenceForEvidence`.
pub const dispatchDivergenceForEvidence = body_analyses.dispatchDivergenceForEvidence;
/// The kind of a normalized body expression.
pub const ExprKind = body_analyses.ExprKind;
/// How an expression of one kind can come to be marked divergent.
pub const ExprDivergence = body_analyses.ExprDivergence;
/// See `body_analyses.exprDivergence`.
pub const exprDivergence = body_analyses.exprDivergence;
/// See `body_analyses.assertExprNeverDiverges`.
pub const assertExprNeverDiverges = body_analyses.assertExprNeverDiverges;
/// The body facts a checked module owns (`body_analyses.BodyAnalyses`).
pub const BodyAnalyses = body_analyses.BodyAnalyses;
/// The CIR-only index of a checked module's bodies.
pub const ModuleIndex = body_analyses.ModuleIndex;
/// The reader over a checked module's bodies (`checked_bodies.CheckedBodies`).
pub const CheckedBodies = checked_bodies_mod.CheckedBodies;

/// The one `*_pool` field of `Owner` (a checked type store or its view)
/// whose elements are `T`.
fn poolField(comptime Owner: type, comptime T: type) []const u8 {
    comptime {
        var found: ?[]const u8 = null;
        const owner = @typeInfo(Owner).@"struct";
        for (owner.field_names, owner.field_types) |name, FT| {
            if (name.len < 5 or !artifact_serialize.comptimeStrEq(name[name.len - 5 ..], "_pool")) continue;
            if (FT != collections.PublishedList(T) and FT != std.ArrayList(T) and FT != []const T) continue;
            if (found != null) @compileError("two pools of " ++ @typeName(Owner) ++ " hold " ++ @typeName(T));
            found = name;
        }
        return found orelse @compileError("no pool of " ++ @typeName(Owner) ++ " holds " ++ @typeName(T));
    }
}

/// The pool of `T` elements in a checked type store or its view.
fn storePool(pool_owner: anytype, comptime T: type) []const T {
    const Owner = @TypeOf(pool_owner);
    const Base = if (@typeInfo(Owner) == .pointer) @typeInfo(Owner).pointer.child else Owner;
    if (Base == CheckedTypeStoreView) {
        const store = pool_owner.store orelse return &.{};
        return storePool(store, T);
    }
    const pool = &@field(pool_owner, poolField(Base, T));
    const Pool = @TypeOf(pool.*);
    if (Pool == collections.PublishedList(T)) return pool.items();
    if (Pool == std.ArrayList(T)) return pool.items;
    return pool.*;
}

/// Whether a value of `T` can own a slice: one held directly or through a
/// struct, union, or optional, or by a slice element.
fn ownsSlice(comptime T: type) bool {
    comptime {
        const info = @typeInfo(T);
        if (info == .pointer) {
            if (info.pointer.size != .slice) @compileError("owned checked data holds a non-slice pointer: " ++ @typeName(T));
            return true;
        }
        if (info == .optional) return ownsSlice(info.optional.child);
        const field_types = if (info == .@"struct") info.@"struct".field_types else if (info == .@"union") info.@"union".field_types else return false;
        for (field_types) |field_type| {
            if (ownsSlice(field_type)) return true;
        }
        return false;
    }
}

/// Free every slice `value` owns, recursively through struct and union
/// payloads, optionals, and slice elements.
fn freeOwned(allocator: Allocator, value: anytype) void {
    const T = @TypeOf(value);
    const info = @typeInfo(T);
    if (comptime !ownsSlice(T)) {
        return;
    } else if (comptime info == .pointer) {
        if (comptime ownsSlice(info.pointer.child)) {
            for (value) |item| freeOwned(allocator, item);
        }
        allocator.free(value);
    } else if (comptime info == .optional) {
        if (value) |payload| freeOwned(allocator, payload);
    } else if (comptime info == .@"struct") {
        inline for (info.@"struct".field_names) |name| freeOwned(allocator, @field(value, name));
    } else {
        inline for (comptime std.enums.values(std.meta.Tag(T))) |tag| {
            if (value == tag) return freeOwned(allocator, @field(value, @tagName(tag)));
        }
        unreachable; // the loop covers every tag of T
    }
}

/// Copy every slice `value` references into memory owned by the result,
/// recursively through struct and union payloads and optionals. Slice
/// elements are copied as they are. Release the result with `freeOwned`.
fn dupeOwned(allocator: Allocator, value: anytype) Allocator.Error!@TypeOf(value) {
    const T = @TypeOf(value);
    const info = @typeInfo(T);
    if (comptime !ownsSlice(T)) {
        return value;
    } else if (comptime info == .pointer) {
        return allocator.dupe(info.pointer.child, value);
    } else if (comptime info == .optional) {
        return if (value) |payload| try dupeOwned(allocator, payload) else null;
    } else if (comptime info == .@"struct") {
        var owned: T = value;
        inline for (info.@"struct".field_names, 0..) |name, i| {
            @field(owned, name) = dupeOwned(allocator, @field(value, name)) catch |err| {
                inline for (info.@"struct".field_names[0..i]) |copied| freeOwned(allocator, @field(owned, copied));
                return err;
            };
        }
        return owned;
    } else {
        inline for (comptime std.enums.values(std.meta.Tag(T))) |tag| {
            if (value == tag) return @unionInit(T, @tagName(tag), try dupeOwned(allocator, @field(value, @tagName(tag))));
        }
        unreachable; // the loop covers every tag of T
    }
}

fn directProcedureTargetForCall(
    refs: *const ResolvedValueRefTable,
    callee: CIR.Expr.Idx,
    local_module: CheckedModuleArtifactKey,
    local_procedure_bindings: *const TopLevelProcedureBindingTable,
    local_callable_eval_templates: *const CallableEvalTemplateTable,
    imports: []const PublishImportArtifact,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) ?ResolvedValueId {
    const ref_id = refs.lookupIdByExpr(callee) orelse return null;
    const raw = @backingInt(ref_id);
    if (raw >= refs.records.len) {
        checkedArtifactInvariant("checked direct call target referenced a missing resolved value", .{});
    }
    return if (resolvedValueCanBeCalledDirectly(
        refs,
        refs.records[raw].ref,
        local_module,
        local_procedure_bindings,
        local_callable_eval_templates,
        imports,
        available_modules,
        relation_modules,
    )) ref_id else null;
}

/// A call through an exact procedure alias, local or top-level, is direct when
/// the alias reaches a directly callable procedure: it forwards to the
/// alias's lookup inside the alias's evidence scope.
fn resolvedValueCanBeCalledDirectly(
    refs: *const ResolvedValueRefTable,
    ref: ResolvedValueRef,
    local_module: CheckedModuleArtifactKey,
    local_procedure_bindings: *const TopLevelProcedureBindingTable,
    local_callable_eval_templates: *const CallableEvalTemplateTable,
    imports: []const PublishImportArtifact,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) bool {
    return switch (ref) {
        .local_proc => |local| if (local.is_alias) blk: {
            const final = local.alias_target orelse
                checkedArtifactInvariant("callable alias has no published target", .{});
            break :blk resolvedValueCanBeCalledDirectly(
                refs,
                refs.records[@backingInt(final)].ref,
                local_module,
                local_procedure_bindings,
                local_callable_eval_templates,
                imports,
                available_modules,
                relation_modules,
            );
        } else true,
        .hosted_proc => true,
        .top_level_proc, .promoted_top_level_proc => |proc| procedureUseCanBeCalledDirectly(
            proc,
            local_module,
            local_procedure_bindings,
            local_callable_eval_templates,
            imports,
            available_modules,
            relation_modules,
        ),
        .imported_proc => |proc| procedureUseCanBeCalledDirectly(
            proc,
            local_module,
            local_procedure_bindings,
            local_callable_eval_templates,
            imports,
            available_modules,
            relation_modules,
        ),
        .platform_required_proc => |required| procedureUseCanBeCalledDirectly(
            required.procedure,
            local_module,
            local_procedure_bindings,
            local_callable_eval_templates,
            imports,
            available_modules,
            relation_modules,
        ),
        .local_param,
        .local_value,
        .local_mutable_version,
        .pattern_binder,
        .selected_hoisted_const,
        .top_level_const,
        .imported_const,
        .platform_required_declaration,
        .platform_required_checked_error,
        .platform_required_const,
        => false,
    };
}

fn procedureUseCanBeCalledDirectly(
    proc: ProcedureUseTemplate,
    local_module: CheckedModuleArtifactKey,
    local_procedure_bindings: *const TopLevelProcedureBindingTable,
    local_callable_eval_templates: *const CallableEvalTemplateTable,
    imports: []const PublishImportArtifact,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) bool {
    const body = procedureUseBody(proc, local_module, local_procedure_bindings, imports, available_modules, relation_modules) orelse return true;
    return switch (body.body) {
        .direct_template => true,
        .checked_error => false,
        .callable_eval_template => |template| (if (body.view) |view|
            view.callable_eval_templates.templates[@backingInt(template)]
        else
            local_callable_eval_templates.get(template)).forwarded_lookup != null,
    };
}

/// The binding body of a procedure use and the checked module view that owns
/// it, or null for the local module. Hosted procedures have no binding body.
const ProcedureUseBody = struct {
    body: ProcedureBindingBody,
    view: ?ImportedModuleView,
};

fn procedureUseBody(
    proc: ProcedureUseTemplate,
    local_module: CheckedModuleArtifactKey,
    local_procedure_bindings: *const TopLevelProcedureBindingTable,
    imports: []const PublishImportArtifact,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) ?ProcedureUseBody {
    const top_level: ArtifactTopLevelProcedureBindingRef = switch (proc.binding) {
        .top_level => |top_level| top_level,
        .platform_required => |required| .{ .artifact = required.artifact, .binding = required.procedure_binding },
        .hosted => return null,
        .imported => |imported| {
            const view = dependencyViewByKey(imported.artifact, imports, available_modules, relation_modules) orelse
                checkedArtifactInvariant("imported direct-call target referenced an unavailable checked module", .{});
            for (view.exported_procedure_bindings.bindings) |binding| {
                if (binding.binding.def == imported.def and binding.binding.pattern == imported.pattern) {
                    return .{ .view = view.*, .body = switch (binding.body) {
                        .direct_template => |direct| .{ .direct_template = direct },
                        .callable_eval_template => |template| .{ .callable_eval_template = template },
                        .checked_error => |expr| .{ .checked_error = expr },
                    } };
                }
            }
            checkedArtifactInvariant("imported direct-call target was not exported by its checked module", .{});
        },
    };
    if (top_level.artifact.eql(local_module.digest())) {
        return .{ .view = null, .body = local_procedure_bindings.get(top_level.binding).body };
    }
    const view = dependencyViewByKey(top_level.artifact, imports, available_modules, relation_modules) orelse
        checkedArtifactInvariant("direct-call target referenced an unavailable checked module", .{});
    return .{ .view = view.*, .body = view.top_level_procedure_bindings.get(top_level.binding).body };
}

fn procedureUseKind(
    proc: ProcedureUseTemplate,
    local_module: CheckedModuleArtifactKey,
    local_procedure_bindings: *const TopLevelProcedureBindingTable,
    imports: []const PublishImportArtifact,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) std.meta.Tag(ProcedureBindingBody) {
    return switch (proc.binding) {
        .top_level => |top_level| topLevelProcedureKind(
            top_level,
            local_module,
            local_procedure_bindings,
            imports,
            available_modules,
            relation_modules,
        ),
        .imported => |imported| importedProcedureKind(imported, imports, available_modules, relation_modules),
        .hosted => .direct_template,
        .platform_required => |required| topLevelProcedureKind(
            .{ .artifact = required.artifact, .binding = required.procedure_binding },
            local_module,
            local_procedure_bindings,
            imports,
            available_modules,
            relation_modules,
        ),
    };
}

fn topLevelProcedureKind(
    top_level: ArtifactTopLevelProcedureBindingRef,
    local_module: CheckedModuleArtifactKey,
    local_procedure_bindings: *const TopLevelProcedureBindingTable,
    imports: []const PublishImportArtifact,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) std.meta.Tag(ProcedureBindingBody) {
    const body = if (top_level.artifact.eql(local_module.digest()))
        local_procedure_bindings.get(top_level.binding).body
    else blk: {
        const view = dependencyViewByKey(top_level.artifact, imports, available_modules, relation_modules) orelse
            checkedArtifactInvariant("direct-call target referenced an unavailable checked module", .{});
        break :blk view.top_level_procedure_bindings.get(top_level.binding).body;
    };
    return std.meta.activeTag(body);
}

fn importedProcedureKind(
    imported: ImportedProcedureBindingRef,
    imports: []const PublishImportArtifact,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) std.meta.Tag(ProcedureBindingBody) {
    const view = dependencyViewByKey(imported.artifact, imports, available_modules, relation_modules) orelse
        checkedArtifactInvariant("imported direct-call target referenced an unavailable checked module", .{});
    for (view.exported_procedure_bindings.bindings) |binding| {
        if (binding.binding.def == imported.def and binding.binding.pattern == imported.pattern) {
            return switch (binding.body) {
                .direct_template => .direct_template,
                .callable_eval_template => .callable_eval_template,
                .checked_error => .checked_error,
            };
        }
    }
    checkedArtifactInvariant("imported direct-call target was not exported by its checked module", .{});
}

/// The alias-chased builtin nominal of a literal's target type, treating a
/// still-open flex/rigid variable as not builtin: an open variable's
/// instantiations are not known yet.
pub fn checkedConcreteBuiltinForLiteralTarget(view: CheckedTypeStoreView, root: CheckedTypeId) ?CheckedBuiltinNominal {
    var current = root;
    while (true) {
        switch (view.payload(current)) {
            .alias => |alias| current = alias.backing,
            .nominal => |nominal| return nominal.builtin,
            .flex, .rigid => return null,
            .pending => checkedArtifactInvariant("checked builtin lookup reached a pending type payload", .{}),
            .field_kind,
            .err,
            .record,
            .tuple,
            .function,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => return null,
        }
    }
}

fn isStatementNodeTag(tag: CIR.Node.Tag) bool {
    return Ident.textStartsWith(@tagName(tag), "statement_");
}

/// A declaration that carries a type annotation and no implementation. The
/// checker keeps the declared type intact so uses of the declaration still
/// check against it, which is why this is published as an executable fact
/// rather than an erroneous type: reaching the declaration crashes.
pub const UnimplementedDeclaration = struct {
    /// Source region of the declaration, used as the crash's location.
    region: base.Region,
};

/// Public `CheckedProcedureBody` declaration.
pub const CheckedProcedureBody = union(enum) {
    /// The template's root expression in its module's CIR.
    checked_body: CIR.Expr.Idx,
    intrinsic_wrapper: canonical.IntrinsicWrapperId,
    entry_wrapper: canonical.EntryWrapperId,
    /// The entry wrapper of a literal root, which no table row holds: its
    /// body converts the root's literal (`CheckedDispatch.procedureTemplate`).
    literal_root: ComptimeRootId,
    /// This procedure was declared with a type annotation and never given an
    /// implementation. It lowers to a crash body carrying the declared arity,
    /// so every call site still links and arguments still evaluate.
    unimplemented: UnimplementedDeclaration,
};

