/// Public `CallableEvalTemplateTable` declaration.
pub const CallableEvalTemplateTable = struct {
    templates: std.ArrayList(CallableEvalTemplate) = .empty,

    pub const Serialized = extern struct {
        templates: SerializedSlice(CallableEvalTemplate) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(CallableEvalTemplateTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn append(
        self: *CallableEvalTemplateTable,
        allocator: Allocator,
        module_idx: u32,
        pattern: CIR.Pattern.Idx,
        root: ComptimeRootId,
        source_scheme: CheckedTypeSchemeId,
        checked_fn_root: CheckedTypeId,
    ) Allocator.Error!CallableEvalTemplateId {
        const id: CallableEvalTemplateId = @fromBackingInt(@intCast(@as(u32, @intCast(self.templates.items.len))));
        try self.templates.append(allocator, .{
            .id = id,
            .module_idx = module_idx,
            .pattern = pattern,
            .root = root,
            .source_scheme = source_scheme,
            .checked_fn_root = checked_fn_root,
        });
        return id;
    }

    pub fn get(self: *const CallableEvalTemplateTable, id: CallableEvalTemplateId) CallableEvalTemplate {
        return self.templates.items[@backingInt(id)];
    }

    pub fn view(self: *const CallableEvalTemplateTable) CallableEvalTemplateTableView {
        return .{ .templates = self.templates.items };
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;
};

/// Record every callable-eval binding that is an exact procedure alias of a
/// directly callable procedure. Its root is a lookup that resolves to such a
/// procedure, so calls through it forward to that lookup instead of calling
/// an evaluated function value. An alias of another alias forwards once that
/// alias does, so this runs to a fixed point over alias chains.
fn publishCallableEvalForwarding(
    templates: *CallableEvalTemplateTable,
    bodies: CheckedBodies,
    resolved_value_refs: *const ResolvedValueRefTable,
    roots: *const CompileTimeRootTable,
    local_module: CheckedModuleArtifactKey,
    local_procedure_bindings: *const TopLevelProcedureBindingTable,
    imports: []const PublishImportArtifact,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) void {
    for (templates.templates.items) |*template| template.forwarded_lookup = null;
    var changed = true;
    while (changed) {
        changed = false;
        for (templates.templates.items) |*template| {
            if (template.forwarded_lookup != null) continue;
            const root = roots.root(template.root);
            if (!compileTimeCallableRootIsProcedureReference(bodies, resolved_value_refs, root)) continue;
            const ref_id = resolved_value_refs.lookupIdByExpr(root.rootExpr()) orelse
                checkedArtifactInvariant("checked callable lookup root had no resolved value reference", .{});
            if (!resolvedValueCanBeCalledDirectly(
                resolved_value_refs,
                resolved_value_refs.records[@backingInt(ref_id)].ref,
                local_module,
                local_procedure_bindings,
                templates,
                imports,
                available_modules,
                relation_modules,
            )) continue;
            template.forwarded_lookup = root.expr;
            changed = true;
        }
    }
}

/// Publication-only index for callable values produced by selected pattern
/// extraction roots. The durable identity lives in the compile-time root,
/// callable-eval template, and top-level procedure binding tables; this index
/// only connects source lookups to those identities while resolved refs are
/// being published.
const SelectedHoistedCallableTable = struct {
    by_pattern: []?TopLevelProcedureBindingRef = &.{},
    /// Procedure bindings of promoted local functions, by binding pattern.
    promoted_by_pattern: []?TopLevelProcedureBindingRef = &.{},

    fn fromRoots(
        allocator: Allocator,
        module: TypedCIR.Module,
        roots: *const CompileTimeRootTable,
        callable_eval_templates: *CallableEvalTemplateTable,
        procedure_bindings: *TopLevelProcedureBindingTable,
        checked_type_publication: *const CheckedTypePublication,
        promoted_templates: []const PromotedProcedureTemplateEntry,
    ) Allocator.Error!SelectedHoistedCallableTable {
        const by_pattern = try allocator.alloc(?TopLevelProcedureBindingRef, module.nodeCount());
        errdefer allocator.free(by_pattern);
        @memset(by_pattern, null);
        const promoted_by_pattern = try allocator.alloc(?TopLevelProcedureBindingRef, module.nodeCount());
        errdefer allocator.free(promoted_by_pattern);
        @memset(promoted_by_pattern, null);

        for (promoted_templates) |promoted| {
            const checked_pattern = promoted.pattern;
            const binding = try procedure_bindings.appendDirect(
                allocator,
                checked_type_publication.schemeForSourceVar(module, ModuleEnv.varFrom(promoted.pattern)),
                .{ .artifact = promoted.template.artifact, .proc_base = promoted.template.proc_base },
                promoted.template,
            );
            const slot = &promoted_by_pattern[@backingInt(checked_pattern)];
            if (slot.* != null) checkedArtifactInvariant("promoted local procedure was published more than once", .{});
            slot.* = binding;
        }

        for (roots.roots) |root| {
            if (root.kind != .callable_binding) continue;
            switch (root.source) {
                .hoisted => {},
                .def, .expr, .statement, .required_binding, .literal => continue,
            }

            const source_pattern = root.source_pattern orelse
                checkedArtifactInvariant("selected callable root had no source pattern", .{});
            if (!sourceTypeIsFunction(module, ModuleEnv.varFrom(source_pattern))) {
                checkedArtifactInvariant("selected callable root source pattern was not function-typed", .{});
            }
            const checked_pattern = root.pattern orelse
                checkedArtifactInvariant("selected callable root had no checked pattern", .{});
            const source_scheme = checked_type_publication.schemeForSourceVar(module, ModuleEnv.varFrom(source_pattern));
            const callable_template = try callable_eval_templates.append(
                allocator,
                module.moduleIndex(),
                checked_pattern,
                root.id,
                source_scheme,
                root.checked_type,
            );
            const binding = try procedure_bindings.appendCallableEval(
                allocator,
                source_scheme,
                callable_template,
            );
            const slot = &by_pattern[@backingInt(checked_pattern)];
            if (slot.* != null) {
                checkedArtifactInvariant("selected callable pattern was published more than once", .{});
            }
            slot.* = binding;
        }

        return .{ .by_pattern = by_pattern, .promoted_by_pattern = promoted_by_pattern };
    }

    fn lookupByPattern(self: *const SelectedHoistedCallableTable, pattern: CIR.Pattern.Idx) ?TopLevelProcedureBindingRef {
        const raw = @backingInt(pattern);
        if (raw >= self.by_pattern.len) return null;
        return self.by_pattern[raw];
    }

    /// The procedure binding of the promoted local function a binding pattern
    /// declares.
    fn lookupPromotedByPattern(self: *const SelectedHoistedCallableTable, pattern: CIR.Pattern.Idx) ?TopLevelProcedureBindingRef {
        const raw = @backingInt(pattern);
        if (raw >= self.promoted_by_pattern.len) return null;
        return self.promoted_by_pattern[raw];
    }

    fn deinit(self: *SelectedHoistedCallableTable, allocator: Allocator) void {
        allocator.free(self.by_pattern);
        allocator.free(self.promoted_by_pattern);
        self.* = .{};
    }
};

/// Public `ImportedProcedureBindingRef` declaration.
pub const ImportedProcedureBindingRef = struct {
    artifact: CheckedModuleDigest,
    def: CIR.Def.Idx,
    pattern: CIR.Pattern.Idx,
};

/// Public `ProcedureUseTemplate` declaration.
pub const ProcedureUseTemplate = struct {
    binding: ProcedureBindingRef,
    source_fn_ty_payload: ?CheckedTypeId = null,
    /// Producer-recorded intrinsic identity for this exact procedure use.
    /// Post-check consumers must not derive this by walking binding bodies or
    /// exported template closures.
    intrinsic: ?IntrinsicId = null,
    /// Producer-recorded semantic role for compiler-owned iterator procedures.
    iterator_procedure: ?IteratorProcedureId = null,
    /// Producer-owned reachability fact for a compiler-provided result.
    runtime_result_provenance: ?RuntimeResultProvenance,
};

/// An immutable checked-evidence vector owned by one checked module.
pub const CheckedEvidenceSpan = struct {
    checked_module: CheckedModuleDigest,
    span: static_dispatch.EvidenceSpan,
};

/// Public `LocalProcedureBinding` declaration.
pub const LocalProcedureBinding = struct {
    /// An alias owns an instantiation scope, but forwards an existing callable
    /// instead of introducing a checked function body.
    is_alias: bool = false,
    /// Final callable lookup reached through the alias's explicit RHS edges.
    /// Publication compresses these identity edges once; type substitutions
    /// remain owned by the individual checked scheme scopes.
    alias_target: ?ResolvedValueRefId = null,
    binder: CIR.Pattern.Idx,
    expr: CIR.Expr.Idx,
    /// Exact generalized-local dispatch scope owned by this procedure, if it
    /// has one. Consumers use this producer-recorded identity directly; they
    /// must not rediscover scope ownership by scanning checked expressions.
    dispatch_scope: ?DispatchScopeId = null,
};

/// Return the checked module id that owns a top-level procedure binding.
pub fn topLevelProcedureModuleId(ref: ArtifactTopLevelProcedureBindingRef) ModuleId {
    return ref.artifact;
}

/// Return the checked module id that owns an imported procedure binding.
pub fn importedProcedureModuleId(ref: ImportedProcedureBindingRef) ModuleId {
    return ref.artifact;
}

/// Return the checked module id that owns a hosted procedure template.
pub fn hostedProcedureTemplateModuleId(ref: HostedProcRef) ModuleId {
    return .{ .bytes = canonical.procTemplateModuleDigest(ref.template).bytes };
}

/// Return the checked module id that owns a required application procedure.
pub fn requiredProcedureModuleId(ref: RequiredAppProcedureRef) ModuleId {
    return ref.artifact;
}

/// Public `PlatformRequiredConstResolvedRef` declaration.
pub const PlatformRequiredConstResolvedRef = struct {
    binding: PlatformRequiredBindingId,
    const_use: ConstUseTemplate,
};

/// Public `PlatformRequiredProcedureResolvedRef` declaration.
pub const PlatformRequiredProcedureResolvedRef = struct {
    binding: PlatformRequiredBindingId,
    procedure: ProcedureUseTemplate,
    root_evidence: ?CheckedEvidenceSpan = null,
};

/// Public `SelectedHoistedConstUse` declaration.
pub const SelectedHoistedConstUse = struct {
    local: LocalBindingRef,
    const_use: ConstUseTemplate,
};

/// Public `ResolvedValueRef` declaration.
pub const ResolvedValueRef = union(enum) {
    local_param: LocalBindingRef,
    local_value: LocalBindingRef,
    local_mutable_version: LocalBindingRef,
    pattern_binder: LocalBindingRef,
    local_proc: LocalProcedureBinding,
    selected_hoisted_const: SelectedHoistedConstUse,

    top_level_const: ConstUseTemplate,
    imported_const: ConstUseTemplate,

    top_level_proc: ProcedureUseTemplate,
    imported_proc: ProcedureUseTemplate,
    hosted_proc: ProcedureUseTemplate,
    platform_required_declaration: PlatformRequiredDeclarationId,
    /// The app-side check for this platform requirement failed. This is an
    /// executable checked fact and lowers to a crash if the lookup is reached.
    platform_required_checked_error,
    platform_required_const: PlatformRequiredConstResolvedRef,
    platform_required_proc: PlatformRequiredProcedureResolvedRef,
    promoted_top_level_proc: ProcedureUseTemplate,
};

/// Public `ResolvedValueRefRecord` declaration.
pub const ResolvedValueRefRecord = struct {
    expr: CIR.Expr.Idx,
    ref: ResolvedValueRef,
    checked_ty: CheckedTypeId,
    scope_depth: u32,
    /// Checking proved that this lookup targets a member of an on-stack
    /// recursive binding group. Monotype may join it to that procedure's
    /// in-progress specialization only when its recorded scheme substitution
    /// is the active specialization's substitution.
    recursive_reference: bool = false,
};

/// One call's direct procedure target (`ResolvedValueRefTable.call_direct_targets`).
pub const CallDirectTarget = extern struct {
    call: CIR.Expr.Idx,
    target: ResolvedValueId,

    fn order(entry: CallDirectTarget, key: CIR.Expr.Idx) std.math.Order {
        return std.math.order(@backingInt(entry.call), @backingInt(key));
    }
};

/// The resolved value references of a checked module's lookups, and the
/// by-node facts reference resolution decides for its expressions.
pub const ResolvedValueRefTable = struct {
    /// One record per reached lookup expression, ascending by expression.
    records: []ResolvedValueRefRecord = &.{},
    template_refs: []ResolvedValueRefId = &.{},
    /// Expressions lowering evaluates as runtime errors because reference
    /// resolution rejected them: uses of rejected bindings, calls of a
    /// callee lowering evaluates as a runtime error, and the uses and calls
    /// those rejections propagate to through callable bindings. One bit per
    /// node of the module, 64 nodes per word.
    retired_exprs: []u64 = &.{},
    /// Each call that targets a directly callable procedure, with that
    /// procedure's reference, ascending by call.
    call_direct_targets: []CallDirectTarget = &.{},

    pub const Serialized = extern struct {
        records: SerializedSlice(ResolvedValueRefRecord) = .{},
        template_refs: SerializedSlice(ResolvedValueRefId) = .{},
        retired_exprs: SerializedSlice(u64) = .{},
        call_direct_targets: SerializedSlice(CallDirectTarget) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(ResolvedValueRefTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        modules: *const TypedCIR.Modules,
        module_idx: u32,
        artifact_key: CheckedModuleArtifactKey,
        imports: []const PublishImportArtifact,
        available_artifacts: []const ImportedModuleView,
        templates: *const CheckedProcedureTemplateTable,
        hosted_procs: *const HostedProcTable,
        platform_required_declarations: *const PlatformRequiredDeclarationTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        top_level_values: *const TopLevelValueTable,
        selected_hoisted_callables: *const SelectedHoistedCallableTable,
        hoisted_constants: *const HoistedConstTable,
        checked_types: *const CheckedTypePublication,
        module_index: *const ModuleIndex,
    ) Allocator.Error!ResolvedValueRefTable {
        const module = modules.module(module_idx);
        var records = std.ArrayList(ResolvedValueRefRecord).empty;
        errdefer records.deinit(allocator);
        var callable_aliases = std.ArrayList(ResolvedValueRefId).empty;
        defer callable_aliases.deinit(allocator);

        var local_pattern_roles = try LocalPatternRoleIndex.init(allocator, module, module_index);
        defer local_pattern_roles.deinit(allocator);

        var recursive_reference_nodes = collections.DenseMap(u32, void).init(allocator);
        defer recursive_reference_nodes.deinit();
        for (module.moduleEnvConst().scheme_uses.items.items) |record| {
            if (record.slot_kind != @backingInt(ModuleEnv.SchemeUseRecord.Slot.recursive_reference)) continue;
            try recursive_reference_nodes.put(record.node_idx, {});
        }

        var node_idx: u32 = 0;
        while (node_idx < module.nodeCount()) : (node_idx += 1) {
            const tag = module.nodeTag(@fromBackingInt(@intCast(node_idx)));
            // Unreached source nodes can still contain unresolved lookups
            // and need no value reference.
            if (tag != .expr_var and
                tag != .expr_external_lookup and
                tag != .expr_associated_lookup_resolved and
                tag != .expr_required_lookup) continue;

            const expr_idx: CIR.Expr.Idx = @fromBackingInt(@intCast(node_idx));
            if (!module_index.reachesExpr(expr_idx)) continue;
            var resolved_ref = try categorizeValueRef(
                allocator,
                module,
                artifact_key,
                expr_idx,
                imports,
                available_artifacts,
                templates,
                hosted_procs,
                platform_required_declarations,
                platform_required_bindings,
                top_level_values,
                selected_hoisted_callables,
                hoisted_constants,
                &local_pattern_roles,
            );
            const checked_ty = checked_types.rootForSourceVar(module, module.exprType(expr_idx)) orelse {
                base.invariant("checked artifact invariant violated: resolved value ref type root was not published", .{});
            };
            try attachUseTypePayload(&resolved_ref, checked_ty);

            const id: ResolvedValueRefId = @fromBackingInt(@intCast(@as(u32, @intCast(records.items.len))));
            try records.append(allocator, .{
                .expr = expr_idx,
                .ref = resolved_ref,
                .checked_ty = checked_ty,
                .scope_depth = 0,
                .recursive_reference = recursive_reference_nodes.contains(node_idx),
            });
            if (resolved_ref == .local_proc and resolved_ref.local_proc.is_alias) {
                try callable_aliases.append(allocator, id);
            }
        }

        var table = ResolvedValueRefTable{ .records = try records.toOwnedSlice(allocator) };
        errdefer table.deinit(allocator);
        table.retired_exprs = try retiredWords(allocator, module.nodeCount());
        try publishCallableAliasTargets(allocator, &table, callable_aliases.items);
        return table;
    }

    /// The reference of a lookup expression.
    pub fn lookupIdByExpr(self: *const ResolvedValueRefTable, expr: CIR.Expr.Idx) ?ResolvedValueRefId {
        const index = artifact_serialize.binarySearchIndexByKey(ResolvedValueRefRecord, CIR.Expr.Idx, self.records, expr, struct {
            fn order(record: ResolvedValueRefRecord, key: CIR.Expr.Idx) std.math.Order {
                return std.math.order(@backingInt(record.expr), @backingInt(key));
            }
        }.order) orelse return null;
        return @fromBackingInt(@intCast(@as(u32, @intCast(index))));
    }

    /// Whether lowering evaluates `expr` as a runtime error because reference
    /// resolution rejected it.
    pub fn exprIsRetired(self: *const ResolvedValueRefTable, expr: CIR.Expr.Idx) bool {
        const raw: u32 = @backingInt(expr);
        std.debug.assert(raw >> 6 < self.retired_exprs.len);
        return self.retired_exprs[raw >> 6] & (@as(u64, 1) << @intCast(raw & 63)) != 0;
    }

    /// The bit-packed node words of a module with `node_count` nodes.
    pub fn retiredWords(allocator: Allocator, node_count: usize) Allocator.Error![]u64 {
        const words = try allocator.alloc(u64, (node_count + 63) / 64);
        @memset(words, 0);
        return words;
    }

    pub fn setRetired(words: []u64, expr: CIR.Expr.Idx) void {
        const raw: u32 = @backingInt(expr);
        words[raw >> 6] |= @as(u64, 1) << @intCast(raw & 63);
    }

    /// The direct procedure target of a call, if it has one.
    pub fn callDirectTarget(self: *const ResolvedValueRefTable, call: CIR.Expr.Idx) ?ResolvedValueId {
        const found = artifact_serialize.binarySearchByKey(CallDirectTarget, CIR.Expr.Idx, self.call_direct_targets, call, CallDirectTarget.order) orelse return null;
        return found.target;
    }

    /// The original callable identity of a procedure reference. Alias use
    /// types and substitutions still belong to the requesting record.
    pub fn callableTarget(self: *const ResolvedValueRefTable, id: ResolvedValueRefId) ResolvedValueRefRecord {
        const record = self.records[@backingInt(id)];
        if (record.ref == .local_proc and record.ref.local_proc.is_alias) {
            const target = record.ref.local_proc.alias_target orelse
                checkedArtifactInvariant("callable alias has no published target", .{});
            return self.records[@backingInt(target)];
        }
        return record;
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;
};
/// Short name for the resolved checked value table.
pub const ResolvedValueTable = ResolvedValueRefTable;

fn publishCallableAliasTargets(
    allocator: Allocator,
    table: *ResolvedValueRefTable,
    aliases: []const ResolvedValueRefId,
) Allocator.Error!void {
    const records = table.records;
    var path = std.ArrayList(ResolvedValueRefId).empty;
    defer path.deinit(allocator);
    for (aliases) |alias| {
        if (records[@backingInt(alias)].ref.local_proc.alias_target != null) continue;
        path.clearRetainingCapacity();
        var target = alias;
        while (true) {
            const ref = records[@backingInt(target)].ref;
            if (ref != .local_proc or !ref.local_proc.is_alias) break;
            if (ref.local_proc.alias_target) |completed| {
                target = completed;
                break;
            }
            if (path.items.len == aliases.len) checkedArtifactInvariant("cyclic callable alias declarations", .{});
            try path.append(allocator, target);
            target = table.lookupIdByExpr(ref.local_proc.expr) orelse
                checkedArtifactInvariant("callable alias RHS has no resolved lookup", .{});
        }
        for (path.items) |id| records[@backingInt(id)].ref.local_proc.alias_target = target;
    }
}

/// Decide which expressions lowering evaluates as runtime errors because
/// reference resolution rejected them, and each remaining call's direct
/// procedure target (`ResolvedValueRefTable.retired_exprs`,
/// `call_direct_targets`). A use of a rejected binding is retired, and so is
/// a call whose callee lowering evaluates as a runtime error; a rejection
/// then propagates through call-to-callee edges and through each callable
/// binding's root, and a callable binding whose root is retired becomes a
/// checked error.
fn publishRetiredExprs(
    allocator: Allocator,
    env: *const ModuleEnv,
    module_index: *const ModuleIndex,
    refs: *ResolvedValueRefTable,
    local_module: CheckedModuleArtifactKey,
    bindings: *TopLevelProcedureBindingTable,
    templates: *const CallableEvalTemplateTable,
    roots: *const CompileTimeRootTable,
    imports: []const PublishImportArtifact,
    available_modules: []const ImportedModuleView,
    relation_modules: []const ImportedModuleView,
) Allocator.Error!void {
    const store = &env.store;
    var retired = try std.DynamicBitSetUnmanaged.initEmpty(allocator, module_index.node_kinds.len);
    defer retired.deinit(allocator);
    const Runtime = struct {
        fn isError(node_store: *const can.NodeStore, set: *const std.DynamicBitSetUnmanaged, expr: CIR.Expr.Idx) bool {
            return set.isSet(@backingInt(expr)) or node_store.getExpr(expr) == .e_runtime_error;
        }
    };

    var rejected_binding = false;
    for (refs.records) |record| {
        if (record.ref == .platform_required_checked_error) {
            retired.set(@backingInt(record.expr));
            rejected_binding = true;
            continue;
        }
        const procedure: ?ProcedureUseTemplate = switch (record.ref) {
            .top_level_proc, .imported_proc, .promoted_top_level_proc => |proc| proc,
            .platform_required_proc => |required| required.procedure,
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            => null,
        };
        if (procedure) |proc| {
            if (procedureUseKind(proc, local_module, bindings, imports, available_modules, relation_modules) == .checked_error) {
                // The type remains available for diagnostics. Evaluating this
                // exact value use has no callable target or type relation.
                retired.set(@backingInt(record.expr));
                rejected_binding = true;
            }
        }
    }

    var direct_targets = std.ArrayList(CallDirectTarget).empty;
    defer direct_targets.deinit(allocator);
    for (module_index.node_kinds, 0..) |kind, raw| {
        if (kind != .expr) continue;
        const expr: CIR.Expr.Idx = @fromBackingInt(@intCast(raw));
        const data = store.getExpr(expr);
        if (data != .e_call) continue;
        // Evaluating the callee happens before any argument. A checked
        // error produces neither a callable nor a result type relation.
        if (Runtime.isError(store, &retired, data.e_call.func)) {
            retired.set(raw);
            rejected_binding = true;
            continue;
        }
        const target = directProcedureTargetForCall(refs, data.e_call.func, local_module, bindings, templates, imports, available_modules, relation_modules) orelse continue;
        try direct_targets.append(allocator, .{ .call = expr, .target = target });
    }

    if (rejected_binding) {
        // Propagate terminal callee errors and callable-binding aliases
        // through explicit edges. Each node becomes an error at most once.
        var dependents = collections.DenseMap(u32, std.ArrayList(CIR.Expr.Idx)).init(allocator);
        defer {
            var lists = dependents.valueIterator();
            while (lists.next()) |list| list.deinit(allocator);
            dependents.deinit();
        }
        var work = std.ArrayList(CIR.Expr.Idx).empty;
        defer work.deinit(allocator);
        for (module_index.node_kinds, 0..) |kind, raw| {
            if (kind != .expr) continue;
            const expr: CIR.Expr.Idx = @fromBackingInt(@intCast(raw));
            if (Runtime.isError(store, &retired, expr)) {
                try work.append(allocator, expr);
                continue;
            }
            const data = store.getExpr(expr);
            if (data == .e_call) {
                const entry = try dependents.getOrPut(@backingInt(data.e_call.func));
                if (!entry.found_existing) entry.value_ptr.* = .empty;
                try entry.value_ptr.append(allocator, expr);
            }
        }
        for (refs.records) |record| {
            const procedure = switch (record.ref) {
                .top_level_proc, .promoted_top_level_proc => |proc| proc,
                .local_param,
                .local_value,
                .local_mutable_version,
                .pattern_binder,
                .local_proc,
                .selected_hoisted_const,
                .top_level_const,
                .imported_const,
                .imported_proc,
                .hosted_proc,
                .platform_required_declaration,
                .platform_required_checked_error,
                .platform_required_const,
                .platform_required_proc,
                => continue,
            };
            const target = switch (procedure.binding) {
                .top_level => |target| target,
                .imported, .hosted, .platform_required => continue,
            };
            if (!target.artifact.eql(local_module.digest())) continue;
            const binding = bindings.get(target.binding);
            if (binding.body != .callable_eval_template) continue;
            const root = roots.root(templates.get(binding.body.callable_eval_template).root);
            const evaluated = root.evaluatedExpr() orelse continue;
            const entry = try dependents.getOrPut(@backingInt(evaluated));
            if (!entry.found_existing) entry.value_ptr.* = .empty;
            try entry.value_ptr.append(allocator, record.expr);
        }
        while (work.pop()) |failed| {
            const waiting = dependents.get(@backingInt(failed)) orelse continue;
            for (waiting.items) |dependent| {
                if (Runtime.isError(store, &retired, dependent)) continue;
                retired.set(@backingInt(dependent));
                try work.append(allocator, dependent);
            }
        }
        for (bindings.bindings.items) |*binding| {
            if (binding.body != .callable_eval_template) continue;
            const root = roots.root(templates.get(binding.body.callable_eval_template).root);
            const evaluated = root.evaluatedExpr() orelse continue;
            if (Runtime.isError(store, &retired, evaluated)) {
                binding.body = .{ .checked_error = evaluated };
            }
        }
    }

    const retired_exprs = try ResolvedValueRefTable.retiredWords(allocator, module_index.node_kinds.len);
    errdefer allocator.free(retired_exprs);
    var retired_iterator = retired.iterator(.{});
    while (retired_iterator.next()) |raw| ResolvedValueRefTable.setRetired(retired_exprs, @fromBackingInt(@intCast(raw)));
    var kept_targets = std.ArrayList(CallDirectTarget).empty;
    errdefer kept_targets.deinit(allocator);
    for (direct_targets.items) |entry| {
        if (!retired.isSet(@backingInt(entry.call))) try kept_targets.append(allocator, entry);
    }
    const call_direct_targets = try kept_targets.toOwnedSlice(allocator);
    allocator.free(refs.retired_exprs);
    refs.retired_exprs = retired_exprs;
    allocator.free(refs.call_direct_targets);
    refs.call_direct_targets = call_direct_targets;
}

fn categorizeValueRef(
    _: Allocator,
    module: TypedCIR.Module,
    artifact_key: CheckedModuleArtifactKey,
    expr_idx: CIR.Expr.Idx,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    _: *const CheckedProcedureTemplateTable,
    hosted_procs: *const HostedProcTable,
    platform_required_declarations: *const PlatformRequiredDeclarationTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    top_level_values: *const TopLevelValueTable,
    selected_hoisted_callables: *const SelectedHoistedCallableTable,
    hoisted_constants: *const HoistedConstTable,
    local_pattern_roles: *const LocalPatternRoleIndex,
) Allocator.Error!ResolvedValueRef {
    const expr = module.expr(expr_idx);
    return switch (expr.data) {
        .e_lookup_local => |local| categorizeLocalValueRef(
            module,
            artifact_key,
            local.pattern_idx,
            hosted_procs,
            top_level_values,
            selected_hoisted_callables,
            hoisted_constants,
            local_pattern_roles,
        ),
        .e_lookup_external => |external| categorizeImportedValueRef(
            module,
            external.module_idx,
            external.target_node_idx,
            imports,
        ),
        .e_lookup_associated_resolved => |resolved| categorizeResolvedAssociatedValueRef(
            module,
            artifact_key,
            resolved.module_identity,
            resolved.target_def_idx,
            imports,
            available_artifacts,
            hosted_procs,
            top_level_values,
        ),
        .e_lookup_associated_local, .e_lookup_associated => checkedArtifactInvariant("unresolved associated lookup reached value-ref categorization", .{}),
        .e_lookup_required => |required| categorizeRequiredValueRef(
            required.requires_idx.toU32(),
            platform_required_declarations,
            platform_required_bindings,
        ),
        .e_num,
        .e_frac_f32,
        .e_frac_f64,
        .e_dec,
        .e_dec_small,
        .e_num_from_numeral,
        .e_typed_int,
        .e_typed_frac,
        .e_typed_num_from_numeral,
        .e_str_segment,
        .e_str,
        .e_bytes_literal,
        .e_list,
        .e_empty_list,
        .e_tuple,
        .e_match,
        .e_if,
        .e_call,
        .e_record,
        .e_empty_record,
        .e_block,
        .e_tag,
        .e_nominal,
        .e_nominal_external,
        .e_zero_argument_tag,
        .e_closure,
        .e_lambda,
        .e_binop,
        .e_unary_minus,
        .e_field_access,
        .e_method_call,
        .e_dispatch_call,
        .e_interpolation,
        .e_structural_eq,
        .e_structural_hash,
        .e_method_eq,
        .e_type_method_call,
        .e_type_dispatch_call,
        .e_tuple_access,
        .e_runtime_error,
        .e_crash,
        .e_dbg,
        .e_expect_err,
        .e_expect,
        .e_ellipsis,
        .e_anno_only,
        .e_derived_method,
        .e_break,
        .e_return,
        .e_for,
        .e_hosted_lambda,
        .e_run_low_level,
        => {
            base.invariant(
                "checked artifact invariant violated: expression {d} is not a value reference",
                .{@backingInt(expr_idx)},
            );
        },
        .e_deferred_import_ref => checkedArtifactInvariant("deferred import reference reached checked artifact publication", .{}),
    };
}

fn attachUseTypePayload(
    ref: *ResolvedValueRef,
    checked_ty: CheckedTypeId,
) Allocator.Error!void {
    switch (ref.*) {
        inline .top_level_const, .imported_const => |*use| {
            use.requested_source_ty_payload = checked_ty;
        },
        .selected_hoisted_const => |*selected| {
            selected.const_use.requested_source_ty_payload = checked_ty;
        },
        .platform_required_const => |*required| {
            if (required.const_use.requested_source_ty_payload == null) {
                checkedArtifactInvariant("platform-required const use missing relation-owned requested payload", .{});
            }
        },
        inline .top_level_proc, .imported_proc, .hosted_proc => |*use| {
            use.source_fn_ty_payload = checked_ty;
        },
        .platform_required_proc => |*required| {
            if (required.procedure.source_fn_ty_payload == null) {
                checkedArtifactInvariant("platform-required procedure use missing relation-owned requested payload", .{});
            }
        },
        .promoted_top_level_proc => |*use| {
            use.source_fn_ty_payload = checked_ty;
        },
        .local_param,
        .local_value,
        .local_mutable_version,
        .pattern_binder,
        .local_proc,
        .platform_required_declaration,
        .platform_required_checked_error,
        => {},
    }
}

fn categorizeLocalValueRef(
    module: TypedCIR.Module,
    artifact_key: CheckedModuleArtifactKey,
    pattern: CIR.Pattern.Idx,
    hosted_procs: *const HostedProcTable,
    top_level_values: *const TopLevelValueTable,
    selected_hoisted_callables: *const SelectedHoistedCallableTable,
    hoisted_constants: *const HoistedConstTable,
    local_pattern_roles: *const LocalPatternRoleIndex,
) ResolvedValueRef {
    if (!local_pattern_roles.module_index.reachesPattern(pattern)) {
        base.invariant(
            "checked artifact invariant violated: local lookup pattern {d} is not reached by the checked bodies",
            .{@backingInt(pattern)},
        );
    }

    if (top_level_values.lookupByPattern(pattern)) |entry| {
        if (entry.pattern != pattern) {
            base.invariant(
                "checked artifact invariant violated: top-level pattern index {d} resolved to mismatched entry",
                .{@backingInt(pattern)},
            );
        }

        return categorizeTopLevelValueRef(module, artifact_key, entry, hosted_procs);
    }

    const binder = pattern;

    if (selected_hoisted_callables.lookupByPattern(pattern)) |binding| {
        return .{ .top_level_proc = .{
            .binding = .{ .top_level = .{
                .artifact = artifact_key.digest(),
                .binding = binding,
            } },
            .runtime_result_provenance = null,
        } };
    }

    if (selected_hoisted_callables.lookupPromotedByPattern(pattern)) |binding| {
        return .{ .promoted_top_level_proc = .{
            .binding = .{ .top_level = .{
                .artifact = artifact_key.digest(),
                .binding = binding,
            } },
            .runtime_result_provenance = null,
        } };
    }

    if (hoisted_constants.lookupByPattern(pattern)) |hoisted| {
        return selectedHoistedConstUse(hoisted, .{ .binder = binder });
    }

    if (local_pattern_roles.isLambdaArg(pattern)) {
        return .{ .local_param = .{ .binder = binder } };
    }

    if (local_pattern_roles.statementRole(pattern)) |role| {
        switch (role) {
            .mutable_version => return .{ .local_mutable_version = .{ .binder = binder } },
            .local_proc => |proc| return .{ .local_proc = .{ .binder = binder, .expr = proc.expr, .is_alias = proc.is_alias } },
            .local_value => return .{ .local_value = .{ .binder = binder } },
        }
    }

    if (patternIsBinder(module, pattern)) {
        return .{ .pattern_binder = .{ .binder = binder } };
    }

    base.invariant(
        "checked artifact invariant violated: local lookup pattern {d} has no categorized binding",
        .{@backingInt(pattern)},
    );
}

fn categorizeTopLevelValueRef(
    module: TypedCIR.Module,
    artifact_key: CheckedModuleArtifactKey,
    entry: TopLevelValueEntry,
    hosted_procs: *const HostedProcTable,
) ResolvedValueRef {
    return switch (entry.value) {
        .const_ref => |const_ref| .{ .top_level_const = .{
            .const_ref = const_ref,
        } },
        .procedure_binding => |binding| if (hostedProcForDef(hosted_procs, entry.def)) |hosted|
            .{ .hosted_proc = .{
                .binding = .{ .hosted = .{
                    .module_idx = hosted.module_idx,
                    .def = hosted.def_idx,
                    .proc = hosted.proc,
                    .template = hosted.template,
                } },
                .intrinsic = null,
                .iterator_procedure = null,
                .runtime_result_provenance = null,
            } }
        else
            .{ .top_level_proc = .{
                .binding = .{ .top_level = .{
                    .artifact = artifact_key.digest(),
                    .binding = binding,
                } },
                .intrinsic = intrinsicForProcedureDef(module, entry.def),
                .iterator_procedure = iteratorProcedureForDef(module, entry.def),
                .runtime_result_provenance = runtimeResultProvenanceForProcedureDef(module, entry.def),
            } },
    };
}

fn selectedHoistedConstUse(
    entry: HoistedConstEntry,
    local: LocalBindingRef,
) ResolvedValueRef {
    return .{ .selected_hoisted_const = .{
        .local = local,
        .const_use = .{
            .const_ref = entry.const_ref,
        },
    } };
}

fn categorizeImportedValueRef(
    module: TypedCIR.Module,
    import_idx: CIR.Import.Idx,
    target_node_idx: u32,
    imports: []const PublishImportArtifact,
) ResolvedValueRef {
    const resolved_module_idx = module.resolvedImportModule(import_idx) orelse {
        base.invariant(
            "checked artifact invariant violated: external lookup import {d} has no resolved module",
            .{@backingInt(import_idx)},
        );
    };
    const import_artifact = publishImportForModule(imports, resolved_module_idx) orelse {
        base.invariant(
            "checked artifact invariant violated: external lookup import {d} resolved to module {d} without a published artifact key",
            .{ @backingInt(import_idx), resolved_module_idx },
        );
    };

    const target_def: CIR.Def.Idx = @fromBackingInt(@intCast(@as(u32, @intCast(target_node_idx))));
    if (importedProcedureBindingForDef(import_artifact.view, target_def)) |binding| {
        return .{ .imported_proc = .{
            .binding = .{ .imported = binding.binding },
            .intrinsic = binding.intrinsic,
            .iterator_procedure = binding.iterator_procedure,
            .runtime_result_provenance = binding.runtime_result_provenance,
        } };
    }

    if (importedConstTemplateForDef(import_artifact.view, target_def)) |const_template| {
        return .{ .imported_const = .{
            .const_ref = const_template.const_ref,
        } };
    }

    base.invariant(
        "checked artifact invariant violated: external lookup target {d} in module {d} was not exported by the imported checked artifact",
        .{ target_node_idx, resolved_module_idx },
    );
}

fn categorizeResolvedAssociatedValueRef(
    module: TypedCIR.Module,
    artifact_key: CheckedModuleArtifactKey,
    module_identity: base.ModuleIdentity.Idx,
    target_def: CIR.Def.Idx,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    hosted_procs: *const HostedProcTable,
    top_level_values: *const TopLevelValueTable,
) ResolvedValueRef {
    if (module_identity == module.moduleEnvConst().selfModuleIdentity()) {
        const entry = top_level_values.lookupByDef(target_def) orelse
            return checkedArtifactInvariant("resolved local associated lookup target is not a top-level value", .{});
        return categorizeTopLevelValueRef(module, artifact_key, entry, hosted_procs);
    }

    const origin_hash = module.moduleEnvConst().moduleIdentityHash(module_identity);
    const target_view = importedViewForOriginHash(imports, available_artifacts, origin_hash) orelse
        checkedArtifactInvariant("resolved associated lookup target has no available checked artifact", .{});

    if (importedProcedureBindingForDef(target_view, target_def)) |binding| {
        return .{ .imported_proc = .{
            .binding = .{ .imported = binding.binding },
            .intrinsic = binding.intrinsic,
            .iterator_procedure = binding.iterator_procedure,
            .runtime_result_provenance = binding.runtime_result_provenance,
        } };
    }

    if (importedConstTemplateForDef(target_view, target_def)) |const_template| {
        return .{ .imported_const = .{
            .const_ref = const_template.const_ref,
        } };
    }

    return checkedArtifactInvariant("resolved associated lookup target was not exported by its checked artifact", .{});
}

fn importedViewForOriginHash(
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    origin_hash: *const base.ModuleIdentity.Hash,
) ?ImportedModuleView {
    var found: ?ImportedModuleView = null;
    for (imports) |*import| {
        if (!importedViewIdentityMatches(&import.view, origin_hash)) continue;
        found = uniqueImportedView(found, import.view);
    }
    for (available_artifacts) |*view| {
        if (!importedViewIdentityMatches(view, origin_hash)) continue;
        found = uniqueImportedView(found, view.*);
    }
    return found;
}

fn uniqueImportedView(existing: ?ImportedModuleView, next: ImportedModuleView) ImportedModuleView {
    if (existing) |found| {
        if (!CheckedModuleArtifactKey.eql(found.key, next.key)) {
            checkedArtifactInvariant("module identity resolved to multiple checked artifacts", .{});
        }
        return found;
    }
    return next;
}

fn importedProcedureBindingForDef(view: ImportedModuleView, def: CIR.Def.Idx) ?ImportedProcedureBindingView {
    for (view.exported_procedure_bindings.bindings) |binding| {
        if (binding.binding.def == def) return binding;
    }
    return null;
}

fn importedConstTemplateForDef(view: ImportedModuleView, def: CIR.Def.Idx) ?ImportedConstTemplateView {
    for (view.exported_const_templates.templates) |template| {
        if (template.def == def) return template;
    }
    return null;
}

fn collectPublishedExportDefs(
    allocator: Allocator,
    module: TypedCIR.Module,
) Allocator.Error![]CIR.Def.Idx {
    const module_env = module.moduleEnvConst();
    var defs = std.ArrayList(CIR.Def.Idx).empty;
    errdefer defs.deinit(allocator);

    const node_count = module.nodeCount();
    const seen = try allocator.alloc(bool, node_count);
    defer allocator.free(seen);
    @memset(seen, false);

    for (module_env.store.sliceDefs(module_env.exports)) |def_idx| {
        try appendPublishedExportDef(allocator, &defs, seen, def_idx);
    }

    var exposed_iter = module_env.common.exposed_items.iterator();
    while (exposed_iter.next()) |entry| {
        const raw_node_idx: u32 = entry.target.valueDefNode() orelse continue;
        if (raw_node_idx >= node_count) {
            base.invariant(
                "checked artifact invariant violated: exposed item {s} points at out-of-range node {d}",
                .{ module_env.getIdent(@bitCast(entry.ident_idx)), raw_node_idx },
            );
        }

        const node_idx: CIR.Node.Idx = @fromBackingInt(@intCast(raw_node_idx));
        if (module.nodeTag(node_idx) != .def) continue;
        try appendPublishedExportDef(allocator, &defs, seen, @fromBackingInt(@intCast(raw_node_idx)));
    }

    return try defs.toOwnedSlice(allocator);
}

fn appendPublishedExportDef(
    allocator: Allocator,
    defs: *std.ArrayList(CIR.Def.Idx),
    seen: []bool,
    def_idx: CIR.Def.Idx,
) Allocator.Error!void {
    const raw = @backingInt(def_idx);
    if (raw >= seen.len) {
        base.invariant(
            "checked artifact invariant violated: published export def {d} is outside the module node store",
            .{raw},
        );
    }
    if (seen[raw]) return;
    seen[raw] = true;
    try defs.append(allocator, def_idx);
}

/// The binder patterns of names bound by top-level destructures that the
/// module exposes. An importer reaches such a name through its binder node
/// (see `Can.populateExports`), so the export tables key its row by that node.
fn collectPublishedExportBinders(
    allocator: Allocator,
    module: TypedCIR.Module,
) Allocator.Error![]CIR.Pattern.Idx {
    const module_env = module.moduleEnvConst();
    var binders = std.ArrayList(CIR.Pattern.Idx).empty;
    errdefer binders.deinit(allocator);

    const node_count = module.nodeCount();
    var exposed_iter = module_env.common.exposed_items.iterator();
    while (exposed_iter.next()) |entry| {
        const raw_node_idx: u32 = entry.target.valueDefNode() orelse continue;
        if (raw_node_idx >= node_count) continue;
        const node_idx: CIR.Node.Idx = @fromBackingInt(@intCast(raw_node_idx));
        const tag = module.nodeTag(node_idx);
        if (tag != .pattern_identifier and tag != .pattern_var_identifier and tag != .pattern_as) continue;
        const binder: CIR.Pattern.Idx = @fromBackingInt(@intCast(raw_node_idx));
        for (binders.items) |seen| {
            if (seen == binder) break;
        } else {
            try binders.append(allocator, binder);
        }
    }

    return try binders.toOwnedSlice(allocator);
}

fn publishImportForModule(imports: []const PublishImportArtifact, module_idx: u32) ?PublishImportArtifact {
    for (imports) |import_artifact| {
        if (import_artifact.module_idx == module_idx) return import_artifact;
    }
    return null;
}

fn categorizeRequiredValueRef(
    requires_idx: u32,
    platform_required_declarations: *const PlatformRequiredDeclarationTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
) ResolvedValueRef {
    const binding = platformBindingForRequiredIndex(platform_required_bindings, requires_idx) orelse {
        if (platform_required_bindings.isCheckedError(requires_idx)) {
            return .platform_required_checked_error;
        }
        const declaration = platform_required_declarations.lookupByRequiredIndex(requires_idx) orelse {
            base.invariant(
                "checked artifact invariant violated: required lookup {d} has no platform declaration",
                .{requires_idx},
            );
        };
        return .{ .platform_required_declaration = declaration.id };
    };

    return switch (binding.value_use) {
        .const_value => |const_use| .{ .platform_required_const = .{
            .binding = binding.id,
            .const_use = const_use.const_use,
        } },
        .procedure_value => |procedure_use| .{ .platform_required_proc = .{
            .binding = binding.id,
            .procedure = procedure_use.procedure,
            .root_evidence = procedure_use.root_evidence,
        } },
    };
}

fn hostedProcForDef(table: *const HostedProcTable, def_idx: CIR.Def.Idx) ?HostedProc {
    for (table.procs) |proc| {
        if (proc.def_idx == def_idx) return proc;
    }
    return null;
}

fn platformBindingForRequiredIndex(table: *const PlatformRequiredBindingTable, requires_idx: u32) ?PlatformRequiredBinding {
    return table.lookupByRequiredIndex(requires_idx);
}

const LocalPatternStatementRole = union(enum) {
    mutable_version,
    local_proc: struct { expr: CIR.Expr.Idx, is_alias: bool },
    local_value,
};

const LocalPatternRoleIndex = struct {
    module_index: *const ModuleIndex,
    lambda_args: []bool = &.{},
    statement_roles: []?LocalPatternStatementRole = &.{},

    fn init(
        allocator: Allocator,
        module: TypedCIR.Module,
        module_index: *const ModuleIndex,
    ) Allocator.Error!LocalPatternRoleIndex {
        const node_count = module.nodeCount();
        const lambda_args = try allocator.alloc(bool, node_count);
        errdefer allocator.free(lambda_args);
        const statement_roles = try allocator.alloc(?LocalPatternStatementRole, node_count);
        errdefer allocator.free(statement_roles);
        @memset(lambda_args, false);
        @memset(statement_roles, null);

        var node_idx: u32 = 0;
        while (node_idx < node_count) : (node_idx += 1) {
            const node: CIR.Node.Idx = @fromBackingInt(@intCast(node_idx));
            const node_tag = module.nodeTag(node);
            if (node_tag == .statement_decl) {
                const statement: CIR.Statement.Idx = @fromBackingInt(@intCast(node_idx));
                if (!module_index.reachesStatement(statement)) continue;
                const statement_data = module.getStatement(statement);
                if (statement_data != .s_decl) unreachable; // getStatement decodes a statement_decl node as s_decl
                const decl = statement_data.s_decl;
                const is_alias = module_index.isSchemeAlias(decl.pattern);
                const role: LocalPatternStatementRole = if (is_alias or isLocalProcExpr(module, decl.expr))
                    .{ .local_proc = .{
                        .expr = decl.expr,
                        .is_alias = is_alias,
                    } }
                else
                    .local_value;
                putStatementRole(statement_roles, node_count, decl.pattern, role);
            } else if (node_tag == .statement_var) {
                const statement: CIR.Statement.Idx = @fromBackingInt(@intCast(node_idx));
                if (!module_index.reachesStatement(statement)) continue;
                const statement_data = module.getStatement(statement);
                if (statement_data != .s_var) unreachable; // getStatement decodes a statement_var node as s_var
                putStatementRole(statement_roles, node_count, statement_data.s_var.pattern_idx, .mutable_version);
            } else if (node_tag == .statement_var_uninitialized) {
                const statement: CIR.Statement.Idx = @fromBackingInt(@intCast(node_idx));
                if (!module_index.reachesStatement(statement)) continue;
                const statement_data = module.getStatement(statement);
                if (statement_data != .s_var_uninitialized) unreachable; // getStatement decodes a statement_var_uninitialized node as s_var_uninitialized
                putStatementRole(statement_roles, node_count, statement_data.s_var_uninitialized.pattern_idx, .mutable_version);
            } else if (node_tag == .expr_lambda) {
                const expr_idx: CIR.Expr.Idx = @fromBackingInt(@intCast(node_idx));
                if (!module_index.reachesExpr(expr_idx)) continue;
                const expr = module.expr(@fromBackingInt(@intCast(node_idx)));
                if (expr.data != .e_lambda) unreachable; // module.expr decodes an expr_lambda node as e_lambda
                for (module.slicePatterns(expr.data.e_lambda.args)) |arg| {
                    const raw_pattern = @backingInt(arg);
                    if (raw_pattern >= node_count) {
                        checkedArtifactInvariant("checked artifact invariant violated: lambda argument pattern is out of range", .{});
                    }
                    lambda_args[raw_pattern] = true;
                }
            }
        }

        verifyLocalPatternRoles(lambda_args, statement_roles);

        return .{
            .module_index = module_index,
            .lambda_args = lambda_args,
            .statement_roles = statement_roles,
        };
    }

    fn putStatementRole(
        statement_roles: []?LocalPatternStatementRole,
        node_count: usize,
        pattern: CIR.Pattern.Idx,
        role: LocalPatternStatementRole,
    ) void {
        const raw_pattern = @backingInt(pattern);
        if (raw_pattern >= node_count) {
            checkedArtifactInvariant("checked artifact invariant violated: local statement pattern is out of range", .{});
        }
        if (statement_roles[raw_pattern]) |existing| {
            if (!localPatternStatementRoleEql(existing, role)) {
                checkedArtifactInvariant("checked artifact invariant violated: local statement pattern has conflicting roles", .{});
            }
            return;
        }
        statement_roles[raw_pattern] = role;
    }

    fn localPatternStatementRoleEql(a: LocalPatternStatementRole, b: LocalPatternStatementRole) bool {
        if (std.meta.activeTag(a) != std.meta.activeTag(b)) return false;
        return switch (a) {
            .mutable_version,
            .local_value,
            => true,
            .local_proc => |a_proc| std.meta.eql(a_proc, b.local_proc),
        };
    }

    fn verifyLocalPatternRoles(
        lambda_args: []const bool,
        statement_roles: []const ?LocalPatternStatementRole,
    ) void {
        if (builtin.mode != .debug) return;

        for (lambda_args, statement_roles, 0..) |is_lambda_arg, maybe_statement_role, raw_pattern| {
            if (is_lambda_arg and maybe_statement_role != null) {
                base.invariant(
                    "checked artifact invariant violated: local pattern {d} is both a lambda argument and statement binding",
                    .{raw_pattern},
                );
            }
        }
    }

    fn isLambdaArg(self: *const LocalPatternRoleIndex, pattern: CIR.Pattern.Idx) bool {
        const raw = @backingInt(pattern);
        if (raw >= self.lambda_args.len) {
            checkedArtifactInvariant("checked artifact invariant violated: lambda argument lookup pattern is out of range", .{});
        }
        return self.lambda_args[raw];
    }

    fn statementRole(self: *const LocalPatternRoleIndex, pattern: CIR.Pattern.Idx) ?LocalPatternStatementRole {
        const raw = @backingInt(pattern);
        if (raw >= self.statement_roles.len) {
            checkedArtifactInvariant("checked artifact invariant violated: local statement lookup pattern is out of range", .{});
        }
        return self.statement_roles[raw];
    }

    fn deinit(self: *LocalPatternRoleIndex, allocator: Allocator) void {
        allocator.free(self.statement_roles);
        allocator.free(self.lambda_args);
    }
};

fn patternIsBinder(module: TypedCIR.Module, pattern: CIR.Pattern.Idx) bool {
    const raw = @backingInt(pattern);
    if (raw >= module.nodeCount()) {
        checkedArtifactInvariant("checked artifact invariant violated: binder lookup pattern is out of range", .{});
    }
    const tag = module.nodeTag(@fromBackingInt(@intCast(raw)));
    return tag == .pattern_identifier or
        tag == .pattern_var_identifier or
        tag == .pattern_as or
        tag == .pattern_applied_tag or
        tag == .pattern_nominal or
        tag == .pattern_nominal_external or
        tag == .pattern_record_destructure or
        tag == .pattern_list or
        tag == .pattern_tuple;
}

/// Whether a pattern introduces a name: an assign, var-assign, or as pattern.
fn patternBindsName(env: *const ModuleEnv, pattern: CIR.Pattern.Idx) bool {
    return switch (env.store.getPattern(pattern)) {
        .assign, .var_assign, .as => true,
        .applied_tag, .nominal, .nominal_external, .record_destructure, .list, .tuple, .num_literal, .num_from_numeral_literal, .small_dec_literal, .dec_literal, .frac_f32_literal, .frac_f64_literal, .str_literal, .str_interpolation, .underscore, .runtime_error, .deferred_import_ref => false,
    };
}

fn isLocalProcExpr(module: TypedCIR.Module, expr_idx: CIR.Expr.Idx) bool {
    const expr = module.expr(expr_idx);
    return expr.data == .e_lambda or expr.data == .e_closure;
}

/// A generalized local function scope collected while walking template
/// bodies: `constraint(depth, k)` resolutions index the innermost enclosing
/// scope's canonical evidence params at depth 0, walking outward to the
/// template's own params.
pub const DispatchRefScope = struct {
    /// Enclosing generalized-local scope, or `null` for the template itself.
    parent: ?DispatchScopeId,
    /// The local function's scheme root var (its decl pattern var).
    scheme_var: Var,
    /// Published checked root of `scheme_var`; specialization evidence paths
    /// are authored relative to this exact callable shape.
    scheme_root: CheckedTypeId,
    /// Checked local-function expression that owns this scope.
    checked_expr: CIR.Expr.Idx,
};

/// Stable identity of a generalized-local dispatch scope within a checked
/// module artifact.
pub const DispatchScopeId = checked_ids.DispatchScopeId;

/// Scope owning a checked dispatch reference. The template root is a real
/// variant, never an integer value that can be mistaken for a local scope id.
pub const DispatchScope = union(enum) {
    root,
    generalized: DispatchScopeId,
};

/// Checked relation shape Monotype must instantiate before specializing the
/// scope that owns a dispatch reference.
pub const DispatchRelationKind = enum(u8) {
    callable_result,
    conversion,
};

/// A checker-authored type relation needed to close a procedure interface
/// before Monotype chooses a specialization identity. These records contain
/// no executable-body semantics: they preserve checked equalities, procedure
/// results, ordinary call edges, and generalized local-procedure
/// instantiations.
pub const SpecializationInterfaceRelation = struct {
    scope: DispatchScope,
    data: Data,

    pub const Data = union(enum) {
        type_equality: struct {
            left: CheckedTypeId,
            right: CheckedTypeId,
        },
        procedure: struct {
            fn_ty: CheckedTypeId,
            /// The type the body delivers at the function's return: the
            /// body's own type, or the composed `Try` when a `?` return
            /// composes the result and the body's value crosses the explicit
            /// return boundary into it (design.md "Inferred Try Return-Row
            /// Composition").
            body_ret_ty: CheckedTypeId,
            owns_scope: bool,
        },
        call: struct {
            callable_ty: CheckedTypeId,
            callee_ty: CheckedTypeId,
            ret_ty: CheckedTypeId,
            args: artifact_serialize.Span,
            direct_target: ?ResolvedValueRefId,
        },
        local_proc_use: ResolvedValueRefId,
    };
};

const CollectedSchemeUseSite = struct {
    record_idx: u32,
    checked_expr: CIR.Expr.Idx,
};

const CollectedScopeConstructionSite = struct {
    scope: DispatchScopeId,
    checked_expr: CIR.Expr.Idx,
};

/// Nested functions that own a callable-derived dispatch scope, keyed by
/// checked expression, each mapped to its own type variable.
///
/// A function no construction edge generalized (a lambda that supplies a
/// conditional's, match's, or block's value inside a stored value) shares its
/// variables with the value holding it. When checking left such a variable
/// unquantified and constrained, nothing in this module pins it, yet every
/// importing use copies the value's type and requests the function at a
/// concrete one. The function's own callable type is then the path to that
/// receiver, exactly as a generalized nested function's scheme is, so its
/// scope publishes those requirements as callable-derived parameters instead
/// of letting the unpinned-dispatch rule commit them to `unreachable`. Only a
/// function whose type reaches the receiver of a dispatch plan checking left
/// unquantified owns one; a module with no such plan walks no types.
fn collectCallableDerivedSchemes(
    allocator: Allocator,
    module: TypedCIR.Module,
    module_index: *const ModuleIndex,
    plans: *const static_dispatch.StaticDispatchPlanTable,
    local_schemes: *const collections.DenseMap(u32, Var),
    out: *collections.DenseMap(u32, Var),
) Allocator.Error!void {
    const types_store = module.typeStoreConst();
    var unquantified = collections.DenseMap(Var, void).init(allocator);
    defer unquantified.deinit();
    for (plans.plan_sources) |source| {
        try noteUnquantifiedReceiver(types_store, source.dispatcher_var, &unquantified);
    }
    for (plans.iterator_plan_sources) |source| {
        try noteUnquantifiedReceiver(types_store, source.iter_dispatcher_var, &unquantified);
        try noteUnquantifiedReceiver(types_store, source.next_dispatcher_var, &unquantified);
    }
    if (unquantified.count() == 0) return;

    // A closure's scope belongs to the closure, never to the lambda it wraps.
    var closure_lambdas = collections.DenseMap(CIR.Expr.Idx, void).init(allocator);
    defer closure_lambdas.deinit();
    var raw_node: u32 = 0;
    while (raw_node < module.nodeCount()) : (raw_node += 1) {
        if (module.nodeTag(@fromBackingInt(@intCast(raw_node))) != .expr_closure) continue;
        const closure_expr: CIR.Expr.Idx = @fromBackingInt(@intCast(raw_node));
        try closure_lambdas.put(module.expr(closure_expr).data.e_closure.lambda_idx, {});
    }

    var scratch = dispatch_evidence.Scratch{};
    defer scratch.deinit(allocator);
    var params = std.ArrayListUnmanaged(dispatch_evidence.EvidenceParam).empty;
    defer params.deinit(allocator);
    raw_node = 0;
    while (raw_node < module.nodeCount()) : (raw_node += 1) {
        const tag = module.nodeTag(@fromBackingInt(@intCast(raw_node)));
        if (tag != .expr_lambda and tag != .expr_closure) continue;
        const source_expr: CIR.Expr.Idx = @fromBackingInt(@intCast(raw_node));
        if (closure_lambdas.contains(source_expr)) continue;
        if (!module_index.reachesExpr(source_expr)) continue;
        const checked_expr = source_expr;
        if (local_schemes.contains(@backingInt(checked_expr))) continue;
        const fn_var = ModuleEnv.varFrom(source_expr);
        params.clearRetainingCapacity();
        try dispatch_evidence.enumerateEvidenceParams(allocator, types_store, fn_var, &scratch, &params);
        for (params.items) |param| {
            if (param.path_len == 0) continue;
            if (!unquantified.contains(types_store.resolveVar(param.dispatcher_var).var_)) continue;
            try out.put(@backingInt(checked_expr), fn_var);
            break;
        }
    }
}

fn noteUnquantifiedReceiver(
    types_store: *const types.Store,
    receiver: Var,
    out: *collections.DenseMap(Var, void),
) Allocator.Error!void {
    const resolved = types_store.resolveVar(receiver);
    if (resolved.desc.rank == .generalized) return;
    switch (resolved.desc.content) {
        .flex => try out.put(resolved.var_, {}),
        .rigid, .alias, .structure, .field_presence, .err => {},
    }
}

fn sealCheckedProcedureTemplateRefs(
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedTypePublication,
    bodies: CheckedBodies,
    diagnostics: *const body_analyses.NodeBits,
    default_exprs: []const CIR.Expr.Idx,
    compile_time_roots: *const CompileTimeRootTable,
    entry_wrappers: *const EntryWrapperTable,
    templates: *CheckedProcedureTemplateTable,
    static_dispatch_plans: *static_dispatch.StaticDispatchPlanTable,
    method_registry: *static_dispatch.MethodRegistry,
    resolved_value_refs: *ResolvedValueRefTable,
) Allocator.Error!void {
    // Local functions with dispatch obligations: entering one while collecting
    // pushes an evidence scope. Declarations map to their pattern scheme;
    // expression-position functions stored in a containing value map to the
    // pristine scheme instantiated at that construction edge.
    var local_schemes = collections.DenseMap(u32, Var).init(allocator);
    defer local_schemes.deinit();
    var nested_function_uses = collections.DenseMap(u32, u32).init(allocator);
    defer nested_function_uses.deinit();
    var callable_derived_schemes = collections.DenseMap(u32, Var).init(allocator);
    defer callable_derived_schemes.deinit();
    {
        const types_store = module.typeStoreConst();

        // Every reference that instantiated a scheme is a record checking
        // wrote, naming the exact scheme root it instantiated. A local
        // definition named that way owns an evidence scope: its uses carry the
        // evidence vector that scope schedules. Reading the records is what
        // decides this, because the pattern var's rank answers a different
        // question—whether let-generalization ran—and a definition whose body
        // defers a dispatch to its caller is instantiated at its uses while
        // that rank settles at `.outermost`.
        var instantiated_scheme_roots = collections.DenseMap(Var, void).init(allocator);
        defer instantiated_scheme_roots.deinit();
        for (module.moduleEnvConst().scheme_uses.items.items) |record| {
            switch (@as(ModuleEnv.SchemeUseRecord.Slot, @fromBackingInt(@intCast(record.slot_kind)))) {
                .value_use, .shared_value_use => try instantiated_scheme_roots.put(
                    @fromBackingInt(@intCast(record.scheme_root)),
                    {},
                ),
                .nested_function_use, .dispatch_target, .recursive_dispatch_target, .recursive_reference, .recursive_value_reference, .where_method_use => {},
            }
        }

        // A promoted local function is the root of its own template, whose
        // scheme is the template's; it opens no generalized-local scope.
        var promoted_patterns = collections.DenseMap(CIR.Pattern.Idx, void).init(allocator);
        defer promoted_patterns.deinit();
        for (templates.promoted) |promoted| try promoted_patterns.put(promoted.pattern, {});

        var raw_node: u32 = 0;
        while (raw_node < module.nodeCount()) : (raw_node += 1) {
            if (module.nodeTag(@fromBackingInt(@intCast(raw_node))) != .statement_decl) continue;
            const statement: CIR.Statement.Idx = @fromBackingInt(@intCast(raw_node));
            const statement_data = module.getStatement(statement);
            if (statement_data != .s_decl) continue;
            const decl = statement_data.s_decl;
            if (promoted_patterns.contains(decl.pattern)) continue;
            const expr_data = module.expr(decl.expr).data;
            const is_alias = bodies.index().isSchemeAlias(decl.pattern);
            if (!is_alias and expr_data != .e_lambda and expr_data != .e_closure) continue;
            const pattern_var = ModuleEnv.varFrom(decl.pattern);
            const generalized = types_store.resolveVar(pattern_var).desc.rank == .generalized;
            if (!is_alias and !generalized and !instantiated_scheme_roots.contains(pattern_var)) continue;
            if (!bodies.index().reachesExpr(decl.expr)) continue;
            try local_schemes.put(@backingInt(decl.expr), pattern_var);
        }

        for (module.moduleEnvConst().scheme_uses.items.items, 0..) |record, record_idx| {
            if (record.slot_kind != @backingInt(ModuleEnv.SchemeUseRecord.Slot.nested_function_use)) continue;
            if (bodies.index().nodeKind(record.node_idx) != .expr) continue;
            try local_schemes.put(record.node_idx, @fromBackingInt(@intCast(record.scheme_root)));
            try nested_function_uses.put(record.node_idx, @intCast(record_idx));
        }

        try collectCallableDerivedSchemes(allocator, module, bodies.index(), static_dispatch_plans, &local_schemes, &callable_derived_schemes);
    }

    var collector = CheckedTemplateRefCollector.init(
        allocator,
        module,
        checked_types,
        bodies,
        diagnostics,
        static_dispatch_plans,
        &local_schemes,
        &nested_function_uses,
        &callable_derived_schemes,
    );
    defer collector.deinit();

    // Flatten each template's collected refs into the two shared per-table pools,
    // recording each template's sub-range. Growing the pools as lists keeps the pass
    // amortized-O(1) per template; both tables then take ownership of the finished
    // pool as a single slice.
    var value_ref_pool = std.ArrayList(ResolvedValueRefId).empty;
    errdefer value_ref_pool.deinit(allocator);
    var dispatch_ref_pool = std.ArrayList(static_dispatch.StaticDispatchPlanId).empty;
    errdefer dispatch_ref_pool.deinit(allocator);
    var iterator_ref_pool = std.ArrayList(static_dispatch.IteratorForPlanId).empty;
    errdefer iterator_ref_pool.deinit(allocator);
    var value_ref_scope_pool = std.ArrayList(DispatchScope).empty;
    errdefer value_ref_scope_pool.deinit(allocator);
    var dispatch_ref_scope_pool = std.ArrayList(DispatchScope).empty;
    errdefer dispatch_ref_scope_pool.deinit(allocator);
    var dispatch_relation_kind_pool = std.ArrayList(DispatchRelationKind).empty;
    errdefer dispatch_relation_kind_pool.deinit(allocator);
    var iterator_scope_pool = std.ArrayList(DispatchScope).empty;
    errdefer iterator_scope_pool.deinit(allocator);
    var scheme_use_pool = std.ArrayList(CollectedSchemeUseSite).empty;
    errdefer scheme_use_pool.deinit(allocator);
    var scheme_use_scope_pool = std.ArrayList(DispatchScope).empty;
    errdefer scheme_use_scope_pool.deinit(allocator);
    var scope_site_pool = std.ArrayList(CollectedScopeConstructionSite).empty;
    errdefer scope_site_pool.deinit(allocator);
    var specialization_relation_pool = std.ArrayList(SpecializationInterfaceRelation).empty;
    errdefer specialization_relation_pool.deinit(allocator);
    var specialization_type_pool = std.ArrayList(CheckedTypeId).empty;
    errdefer specialization_type_pool.deinit(allocator);
    // One entry per template, then the defaulted-field expressions'.
    const iterator_spans = try allocator.alloc(artifact_serialize.Span, templates.templates.items.len + 1);
    errdefer allocator.free(iterator_spans);
    const scheme_use_spans = try allocator.alloc(artifact_serialize.Span, templates.templates.items.len + 1);
    errdefer allocator.free(scheme_use_spans);
    const scope_site_spans = try allocator.alloc(artifact_serialize.Span, templates.templates.items.len + 1);
    errdefer allocator.free(scope_site_spans);

    for (templates.templates.items, 0..) |*template, template_index| {
        collector.clear();

        switch (template.body) {
            .checked_body => |root_expr| {
                collector.template_root_expr = root_expr;
                try collector.collectExpr(root_expr);
            },
            .entry_wrapper => |wrapper_id| {
                const wrapper = entry_wrappers.get(wrapper_id);
                const root = compile_time_roots.root(wrapper.root);
                const parts = root.bodyParts();
                // A literal root's entry wrapper is no row of the table.
                if (parts.literal != null) checkedArtifactInvariant("a literal conversion root's wrapper is a row of the template table", .{});
                if (parts.expr) |expr| try collector.collectExpr(expr);
                if (parts.pattern) |pattern| try collector.collectPattern(pattern);
                if (!rootBodyContainsDiagnosticError(diagnostics, root)) try collector.specialization_relations.append(allocator, .{
                    .scope = collector.currentScope(),
                    .data = .{ .procedure = .{
                        .fn_ty = template.checked_fn_root,
                        .body_ret_ty = if (root.evaluatedExpr()) |evaluated| bodies.exprType(evaluated) else root.checked_type,
                        .owns_scope = true,
                    } },
                });
            },
            .literal_root => checkedArtifactInvariant("a literal root's entry wrapper is a row of the template table", .{}),
            // Neither an intrinsic wrapper nor an unimplemented declaration
            // has a checked body to collect plans from.
            .intrinsic_wrapper, .unimplemented => {},
        }

        var seen_local_uses = collections.DenseMap(ResolvedValueRefId, void).init(allocator);
        defer seen_local_uses.deinit();
        for (collector.value_refs.items, collector.value_ref_scopes.items) |ref_id, use_scope| {
            const seen = try seen_local_uses.getOrPut(ref_id);
            if (seen.found_existing) continue;
            const record = resolved_value_refs.records[@backingInt(ref_id)];
            if (diagnostics.isSet(@backingInt(record.expr))) continue;
            try collector.specialization_relations.append(allocator, .{
                .scope = use_scope,
                .data = .{ .type_equality = .{
                    .left = record.checked_ty,
                    .right = bodies.exprType(record.expr),
                } },
            });
            const local = switch (record.ref) {
                .local_param,
                .local_value,
                .local_mutable_version,
                .pattern_binder,
                => |binding| {
                    try collector.specialization_relations.append(allocator, .{
                        .scope = use_scope,
                        .data = .{ .type_equality = .{
                            .left = record.checked_ty,
                            .right = bodies.patternType(binding.binder),
                        } },
                    });
                    continue;
                },
                .local_proc => |local| local,
                .selected_hoisted_const,
                .top_level_const,
                .imported_const,
                .top_level_proc,
                .imported_proc,
                .hosted_proc,
                .platform_required_declaration,
                .platform_required_checked_error,
                .platform_required_const,
                .platform_required_proc,
                .promoted_top_level_proc,
                => continue,
            };
            if (collector.scope_by_checked_expr.get(local.expr) == null) {
                try collector.specialization_relations.append(allocator, .{
                    .scope = use_scope,
                    .data = .{ .type_equality = .{
                        .left = record.checked_ty,
                        .right = bodies.exprType(local.expr),
                    } },
                });
                continue;
            }
            try collector.specialization_relations.append(allocator, .{
                .scope = use_scope,
                .data = .{ .local_proc_use = ref_id },
            });
        }

        template.resolved_value_refs = try artifact_serialize.appendSpan(ResolvedValueRefTableRef, ResolvedValueRefId, &value_ref_pool, allocator, collector.value_refs.items);
        template.static_dispatch_plans = try artifact_serialize.appendSpan(@TypeOf(template.static_dispatch_plans), static_dispatch.StaticDispatchPlanId, &dispatch_ref_pool, allocator, collector.dispatch_refs.items);
        const specialization_type_base: u32 = @intCast(specialization_type_pool.items.len);
        try specialization_type_pool.appendSlice(allocator, collector.specialization_types.items);
        const specialization_relation_start: u32 = @intCast(specialization_relation_pool.items.len);
        try specialization_relation_pool.ensureUnusedCapacity(allocator, collector.specialization_relations.items.len);
        for (collector.specialization_relations.items) |raw_relation| {
            var relation = raw_relation;
            switch (relation.data) {
                .call => |*call| call.args.start += specialization_type_base,
                .type_equality, .procedure, .local_proc_use => {},
            }
            specialization_relation_pool.appendAssumeCapacity(relation);
        }
        template.specialization_interface_relations = .{
            .start = specialization_relation_start,
            .len = @intCast(collector.specialization_relations.items.len),
        };
        for (collector.dispatch_refs.items) |plan_id| {
            const plan = static_dispatch_plans.plans[@backingInt(plan_id)];
            var kind: DispatchRelationKind = .callable_result;
            for (plan.argsSlice(static_dispatch_plans)) |operand| switch (operand) {
                .generated_numeral, .generated_quote => kind = .conversion,
                .checked_expr, .generated_interpolation_segments, .literal_pattern_value, .literal_pattern_conversion => {},
            };
            try dispatch_relation_kind_pool.append(allocator, kind);
        }
        iterator_spans[template_index] = try artifact_serialize.appendSpan(artifact_serialize.Span, static_dispatch.IteratorForPlanId, &iterator_ref_pool, allocator, collector.iterator_refs.items);
        scheme_use_spans[template_index] = try artifact_serialize.appendSpan(artifact_serialize.Span, CollectedSchemeUseSite, &scheme_use_pool, allocator, collector.scheme_use_sites.items);
        scope_site_spans[template_index] = try artifact_serialize.appendSpan(artifact_serialize.Span, CollectedScopeConstructionSite, &scope_site_pool, allocator, collector.scope_sites.items);
        try value_ref_scope_pool.appendSlice(allocator, collector.value_ref_scopes.items);
        try dispatch_ref_scope_pool.appendSlice(allocator, collector.dispatch_ref_scopes.items);
        try iterator_scope_pool.appendSlice(allocator, collector.iterator_ref_scopes.items);
        try scheme_use_scope_pool.appendSlice(allocator, collector.scheme_use_scopes.items);
    }

    // Defaulted-field expressions (design.md "Defaulted Fields") are value
    // expressions no template body reaches: each is lowered standalone at
    // every construction site that omits its field. Collect their refs
    // exactly like a template body so the evidence pass publishes site
    // evidence for the calls and scheme instantiations inside them—
    // without this, a default calling a generic procedure reaches lowering
    // with no checked evidence vector for the callee's requirements.
    const default_ref_spans = try allocator.alloc(artifact_serialize.Span, 2);
    errdefer allocator.free(default_ref_spans);
    const defaults = templates.templates.items.len;
    {
        collector.clear();
        for (default_exprs) |default| {
            try collector.collectExpr(default);
        }
        default_ref_spans[TemplateDispatchSites.default_plan_refs] = try artifact_serialize.appendSpan(artifact_serialize.Span, static_dispatch.StaticDispatchPlanId, &dispatch_ref_pool, allocator, collector.dispatch_refs.items);
        default_ref_spans[TemplateDispatchSites.default_value_refs] = try artifact_serialize.appendSpan(artifact_serialize.Span, ResolvedValueRefId, &value_ref_pool, allocator, collector.value_refs.items);
        iterator_spans[defaults] = try artifact_serialize.appendSpan(artifact_serialize.Span, static_dispatch.IteratorForPlanId, &iterator_ref_pool, allocator, collector.iterator_refs.items);
        scheme_use_spans[defaults] = try artifact_serialize.appendSpan(artifact_serialize.Span, CollectedSchemeUseSite, &scheme_use_pool, allocator, collector.scheme_use_sites.items);
        scope_site_spans[defaults] = try artifact_serialize.appendSpan(artifact_serialize.Span, CollectedScopeConstructionSite, &scope_site_pool, allocator, collector.scope_sites.items);
        // `dispatch_relation_kind_pool` stays parallel to the plan-ref pool.
        for (collector.dispatch_refs.items) |plan_id| {
            const plan = static_dispatch_plans.plans[@backingInt(plan_id)];
            var kind: DispatchRelationKind = .callable_result;
            for (plan.argsSlice(static_dispatch_plans)) |operand| switch (operand) {
                .generated_numeral, .generated_quote => kind = .conversion,
                .checked_expr, .generated_interpolation_segments, .literal_pattern_value, .literal_pattern_conversion => {},
            };
            try dispatch_relation_kind_pool.append(allocator, kind);
        }
        try value_ref_scope_pool.appendSlice(allocator, collector.value_ref_scopes.items);
        try dispatch_ref_scope_pool.appendSlice(allocator, collector.dispatch_ref_scopes.items);
        try iterator_scope_pool.appendSlice(allocator, collector.iterator_ref_scopes.items);
        try scheme_use_scope_pool.appendSlice(allocator, collector.scheme_use_scopes.items);
    }

    resolved_value_refs.template_refs = try value_ref_pool.toOwnedSlice(allocator);
    templates.dispatch_plan_refs = try dispatch_ref_pool.toOwnedSlice(allocator);
    templates.dispatch_ref_scopes = try dispatch_ref_scope_pool.toOwnedSlice(allocator);
    templates.dispatch_relation_kinds = try dispatch_relation_kind_pool.toOwnedSlice(allocator);
    templates.dispatch_scopes = try allocator.dupe(DispatchRefScope, collector.scopes.items);
    templates.specialization_interface_relations = try specialization_relation_pool.toOwnedSlice(allocator);
    templates.specialization_interface_types = try specialization_type_pool.toOwnedSlice(allocator);
    publishLocalProcedureDispatchScopes(resolved_value_refs, &collector.scope_by_checked_expr);
    publishLocalMethodDispatchScopes(method_registry, &collector.scope_by_checked_expr);
    templates.dispatch_sites = .{
        .iterator_spans = iterator_spans,
        .iterator_refs = try iterator_ref_pool.toOwnedSlice(allocator),
        .iterator_scopes = try iterator_scope_pool.toOwnedSlice(allocator),
        .value_ref_scopes = try value_ref_scope_pool.toOwnedSlice(allocator),
        .scheme_use_spans = scheme_use_spans,
        .scheme_use_sites = try scheme_use_pool.toOwnedSlice(allocator),
        .scheme_use_scopes = try scheme_use_scope_pool.toOwnedSlice(allocator),
        .scope_site_spans = scope_site_spans,
        .scope_sites = try scope_site_pool.toOwnedSlice(allocator),
        .default_ref_spans = default_ref_spans,
    };
}

/// Attach the producer-owned dispatch scope identity to every use of a local
/// procedure. A generalized local procedure may own a scope even when its
/// checker-ordered evidence list is empty, so presence is determined by the checked
/// scope table rather than by evidence count.
fn publishLocalProcedureDispatchScopes(
    resolved_value_refs: *ResolvedValueRefTable,
    scope_by_checked_expr: *const collections.DenseMap(CIR.Expr.Idx, DispatchScopeId),
) void {
    for (resolved_value_refs.records) |*record| {
        if (record.ref != .local_proc) continue;
        const local = &record.ref.local_proc;

        local.dispatch_scope = scope_by_checked_expr.get(local.expr);
    }
}

fn publishLocalMethodDispatchScopes(
    method_registry: *static_dispatch.MethodRegistry,
    scope_by_checked_expr: *const collections.DenseMap(CIR.Expr.Idx, DispatchScopeId),
) void {
    for (method_registry.entries) |*entry| {
        const target = if (entry.target) |*target| target else continue;
        if (target.alias) |*alias| switch (alias.*) {
            .local => |*local| local.dispatch_scope = scope_by_checked_expr.get(local.lookup),
            .top_level => {},
        };
        if (target.kind != .local_proc) continue;
        const local = &target.kind.local_proc;

        local.dispatch_scope = scope_by_checked_expr.get(local.expr);
    }
}

/// The sites each procedure template's body reaches, collected by
/// `sealCheckedProcedureTemplateRefs` from the template's checked body: its
/// iterator plans, the scope of each collected value reference and iterator
/// plan, its expression-position scheme instantiation sites, and its
/// generalized nested-procedure construction sites. Each per-template span
/// array has one entry per template the collection walked, then one for the
/// module's defaulted-field expressions (`defaults`). Dispatch resolution
/// reads these sites; they are a pure function of each body.
pub const TemplateDispatchSites = struct {
    /// Per template, a range of `iterator_refs`.
    iterator_spans: []artifact_serialize.Span = &.{},
    iterator_refs: []static_dispatch.IteratorForPlanId = &.{},
    /// Scope of each `iterator_refs` entry.
    iterator_scopes: []DispatchScope = &.{},
    /// Scope of each `ResolvedValueRefTable.template_refs` entry.
    value_ref_scopes: []DispatchScope = &.{},
    /// Per template, a range of `scheme_use_sites`.
    scheme_use_spans: []artifact_serialize.Span = &.{},
    scheme_use_sites: []CollectedSchemeUseSite = &.{},
    /// Scope of each `scheme_use_sites` entry.
    scheme_use_scopes: []DispatchScope = &.{},
    /// Per template, a range of `scope_sites`.
    scope_site_spans: []artifact_serialize.Span = &.{},
    scope_sites: []CollectedScopeConstructionSite = &.{},
    /// The defaulted-field expressions' ranges of the plan-ref pool
    /// (`CheckedProcedureTemplateTable.dispatch_plan_refs`) and of the
    /// value-ref pool (`ResolvedValueRefTable.template_refs`).
    default_ref_spans: []artifact_serialize.Span = &.{},

    pub const default_plan_refs = 0;
    pub const default_value_refs = 1;

    pub const Serialized = extern struct {
        iterator_spans: SerializedSlice(artifact_serialize.Span) = .{},
        iterator_refs: SerializedSlice(static_dispatch.IteratorForPlanId) = .{},
        iterator_scopes: SerializedSlice(DispatchScope) = .{},
        value_ref_scopes: SerializedSlice(DispatchScope) = .{},
        scheme_use_spans: SerializedSlice(artifact_serialize.Span) = .{},
        scheme_use_sites: SerializedSlice(CollectedSchemeUseSite) = .{},
        scheme_use_scopes: SerializedSlice(DispatchScope) = .{},
        scope_site_spans: SerializedSlice(artifact_serialize.Span) = .{},
        scope_sites: SerializedSlice(CollectedScopeConstructionSite) = .{},
        default_ref_spans: SerializedSlice(artifact_serialize.Span) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(TemplateDispatchSites, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;

    /// The number of templates the collection walked; templates appended
    /// after it reach no sites.
    pub fn walkedTemplateCount(self: *const TemplateDispatchSites) usize {
        return if (self.iterator_spans.len == 0) 0 else self.iterator_spans.len - 1;
    }

    /// The index of the defaulted-field expressions' entries.
    pub fn defaultsIndex(self: *const TemplateDispatchSites) usize {
        return self.walkedTemplateCount();
    }

    pub fn iteratorSpan(self: *const TemplateDispatchSites, index: usize) artifact_serialize.Span {
        return if (index < self.iterator_spans.len) self.iterator_spans[index] else .{};
    }

    pub fn schemeUseSpan(self: *const TemplateDispatchSites, index: usize) artifact_serialize.Span {
        return if (index < self.scheme_use_spans.len) self.scheme_use_spans[index] else .{};
    }

    pub fn scopeSiteSpan(self: *const TemplateDispatchSites, index: usize) artifact_serialize.Span {
        return if (index < self.scope_site_spans.len) self.scope_site_spans[index] else .{};
    }

    pub fn defaultRefs(self: *const TemplateDispatchSites, which: usize) artifact_serialize.Span {
        return if (self.default_ref_spans.len == 0) .{} else self.default_ref_spans[which];
    }
};

/// The checked types a dispatch analysis reads source variables at: the
/// module's own types, under its platform/app pairing's images when it was
/// published with one.
const DispatchTypes = struct {
    store: *CheckedTypeStore,
    pairing: ?*const PairingTypeColumn,

    fn rootForSourceVar(self: DispatchTypes, module: TypedCIR.Module, var_: Var) ?CheckedTypeId {
        const resolved = module.typeStoreConst().resolveVar(var_).var_;
        if (!self.store.sealed_var_facts.items[@backingInt(resolved)].reached) return null;
        const own = type_ids.fromVar(resolved);
        return if (self.pairing) |pairing| pairing.image(own) else own;
    }
};

/// What a consumer reads of one scheme's dispatch requirements: its
/// quantified variables in canonical identity order, its evidence
/// parameters in canonical order, the path nodes the parameters' paths name
/// and their independent callable types.
pub const SchemaView = struct {
    /// The scheme's owning solver variable, which `SchemeParamRef.scheme`
    /// names; null for a template without an evidence scheme.
    scheme: ?u32 = null,
    vars: []const CheckedTypeId = &.{},
    params: []const static_dispatch.EvidenceParamRecord = &.{},
    path_nodes: []const static_dispatch.EvidencePathNode = &.{},
    param_callables: []const CheckedTypeId = &.{},
    /// See `TemplateSchema.callable_determines_scheme`.
    callable_determines_scheme: bool = true,

    pub fn paramCallables(self: SchemaView, param: static_dispatch.EvidenceParamRecord) []const CheckedTypeId {
        return self.param_callables[param.callable_contracts.start..][0..param.callable_contracts.len];
    }

    /// Replace `out`'s contents with the param's dispatcher path over the
    /// scheme callable, root first (empty = pathless).
    pub fn paramPath(
        self: SchemaView,
        allocator: Allocator,
        param: static_dispatch.EvidenceParamRecord,
        out: *std.ArrayListUnmanaged(static_dispatch.EvidencePathStep),
    ) Allocator.Error![]const static_dispatch.EvidencePathStep {
        out.clearRetainingCapacity();
        try dispatch_evidence.appendPathSteps(allocator, self.path_nodes, param.path.last, param.path.len, out);
        return out.items;
    }
};

/// One scheme's requirements as dispatch resolution matches obligations
/// against them: the enumerated parameters, indexed by dispatcher root, and
/// their published records.
const ChainScheme = struct {
    owner: u32,
    params: []const dispatch_evidence.EvidenceParam,
    by_dispatcher: EvidencePass.DispatcherParams,
    published: []const static_dispatch.EvidenceParamRecord,
};

/// The schema of one template or one generalized local scope
/// (`ModuleAnalyses` template and scope schema slots). Allocated in its own
/// arena.
pub const SchemeAnalysis = struct {
    arena: std.heap.ArenaAllocator.State = .{},
    view: SchemaView,
    /// The scheme whose parameters bind the template's or scope's
    /// obligations; null when the template binds none.
    chain: ?ChainScheme,

    pub fn destroy(self: *SchemeAnalysis, allocator: Allocator) void {
        var arena = self.arena.promote(allocator);
        arena.deinit();
        allocator.destroy(self);
    }
};

/// A template's or the module's evidence for one instantiation site.
const DeferredUseSite = struct { record_idx: u32, site_key: u32 };

/// The dispatch resolution of one procedure template
/// (`ModuleAnalyses.templateDispatch`): the plans, iterator plans and sites
/// its body reaches that its scheme chain binds, its root evidence, and the
/// evidence pool all of them name.
pub const TemplateDispatch = struct {
    pool: static_dispatch.EvidencePool,
    /// Sorted by key.
    site_evidence: []static_dispatch.SiteEvidenceEntry,
    /// Sorted by plan.
    plans: []PlanResolutionEntry,
    /// Sorted by plan.
    iterator_plans: []IteratorPlanResolutionEntry,
    /// The template's chain-free root evidence; null for a scheme-only
    /// procedure that requires instantiation evidence.
    root_evidence: ?static_dispatch.EvidenceSpan,
    /// Use sites the template's chain did not bind; the module resolves them
    /// chain-free when no template binds them.
    deferred_sites: []DeferredUseSite,

    pub fn destroy(self: *TemplateDispatch, allocator: Allocator) void {
        self.pool.deinit(allocator);
        allocator.free(self.site_evidence);
        allocator.free(self.plans);
        allocator.free(self.iterator_plans);
        allocator.free(self.deferred_sites);
        allocator.destroy(self);
    }

    pub fn plan(self: *const TemplateDispatch, id: static_dispatch.StaticDispatchPlanId) ?static_dispatch.PlanResolution {
        return lookupPlanResolution(self.plans, id);
    }

    pub fn iteratorPlan(self: *const TemplateDispatch, id: static_dispatch.IteratorForPlanId) ?static_dispatch.IteratorPlanResolution {
        return lookupIteratorPlanResolution(self.iterator_plans, id);
    }

    pub fn site(self: *const TemplateDispatch, key: u32) ?*const static_dispatch.SiteEvidenceEntry {
        return lookupSiteEvidence(self.site_evidence, key);
    }
};

fn lookupPlanResolution(entries: []const PlanResolutionEntry, id: static_dispatch.StaticDispatchPlanId) ?static_dispatch.PlanResolution {
    const found = artifact_serialize.binarySearchByKey(PlanResolutionEntry, u32, entries, @backingInt(id), PlanResolutionEntry.order) orelse return null;
    return found.resolution;
}

fn lookupIteratorPlanResolution(entries: []const IteratorPlanResolutionEntry, id: static_dispatch.IteratorForPlanId) ?static_dispatch.IteratorPlanResolution {
    const found = artifact_serialize.binarySearchByKey(IteratorPlanResolutionEntry, u32, entries, @backingInt(id), IteratorPlanResolutionEntry.order) orelse return null;
    return found.resolution;
}

fn lookupSiteEvidence(entries: []const static_dispatch.SiteEvidenceEntry, key: u32) ?*const static_dispatch.SiteEvidenceEntry {
    return artifact_serialize.binarySearchByKey(static_dispatch.SiteEvidenceEntry, u32, entries, key, static_dispatch.siteEvidenceOrder);
}

/// The evidence of one use site and the analysis whose pool holds it.
pub const SiteEvidenceLookup = struct {
    entry: static_dispatch.SiteEvidenceEntry,
    owner: static_dispatch.EvidenceOwner,
};

/// One plan's resolution within an analysis's result, keyed by plan.
pub const PlanResolutionEntry = struct {
    plan: u32,
    resolution: static_dispatch.PlanResolution,

    fn order(entry: PlanResolutionEntry, key: u32) std.math.Order {
        return std.math.order(entry.plan, key);
    }

    fn lessThan(_: void, a: PlanResolutionEntry, b: PlanResolutionEntry) bool {
        return a.plan < b.plan;
    }
};

/// One iterator plan's resolution within an analysis's result, keyed by plan.
pub const IteratorPlanResolutionEntry = struct {
    plan: u32,
    resolution: static_dispatch.IteratorPlanResolution,

    fn order(entry: IteratorPlanResolutionEntry, key: u32) std.math.Order {
        return std.math.order(entry.plan, key);
    }

    fn lessThan(_: void, a: IteratorPlanResolutionEntry, b: IteratorPlanResolutionEntry) bool {
        return a.plan < b.plan;
    }
};

/// How a template's dispatch plans relate to its specialization
/// (`ModuleAnalyses.templateDispatchRelations`): the plans whose resolution
/// is a direct call, and the plans that need a relation (evidence-dependent
/// or representation-sensitive), each with its scope and relation kind.
pub const TemplateDispatchRelations = struct {
    direct: []static_dispatch.StaticDispatchPlanId,
    relations: []static_dispatch.StaticDispatchPlanId,
    relation_scopes: []DispatchScope,
    relation_kinds: []DispatchRelationKind,

    pub fn destroy(self: *TemplateDispatchRelations, allocator: Allocator) void {
        allocator.free(self.direct);
        allocator.free(self.relations);
        allocator.free(self.relation_scopes);
        allocator.free(self.relation_kinds);
        allocator.destroy(self);
    }
};

/// The module's dispatch resolution of what no template resolves
/// (`ModuleAnalyses.moduleDispatch`): the defaulted-field expressions' plans
/// and sites, plans and sites no template's chain binds (resolved
/// chain-free), and the generated-codec
/// contracts with their calls linked.
pub const ModuleDispatch = struct {
    pool: static_dispatch.EvidencePool,
    /// Sorted by key.
    site_evidence: []static_dispatch.SiteEvidenceEntry,
    /// Sorted by plan.
    plans: []PlanResolutionEntry,
    /// Sorted by plan.
    iterator_plans: []IteratorPlanResolutionEntry,
    codec_derivations: []static_dispatch.GeneratedCodecDerivation,
    codec_calls: []static_dispatch.GeneratedCodecCall,

    pub fn destroy(self: *ModuleDispatch, allocator: Allocator) void {
        self.pool.deinit(allocator);
        allocator.free(self.site_evidence);
        allocator.free(self.plans);
        allocator.free(self.iterator_plans);
        allocator.free(self.codec_derivations);
        allocator.free(self.codec_calls);
        allocator.destroy(self);
    }

    pub fn plan(self: *const ModuleDispatch, id: static_dispatch.StaticDispatchPlanId) ?static_dispatch.PlanResolution {
        return lookupPlanResolution(self.plans, id);
    }

    pub fn iteratorPlan(self: *const ModuleDispatch, id: static_dispatch.IteratorForPlanId) ?static_dispatch.IteratorPlanResolution {
        return lookupIteratorPlanResolution(self.iterator_plans, id);
    }

    pub fn site(self: *const ModuleDispatch, key: u32) ?*const static_dispatch.SiteEvidenceEntry {
        return lookupSiteEvidence(self.site_evidence, key);
    }

    pub fn codecTable(self: *const ModuleDispatch) static_dispatch.GeneratedCodecTable {
        return .{
            .generated_codec_derivations = self.codec_derivations,
            .generated_codec_calls = self.codec_calls,
            .evidence_nodes = self.pool.nodes,
            .evidence_refs = self.pool.refs,
            .site_substitutions = self.pool.substitutions,
        };
    }
};

/// An app's root evidence for each of its platform requirement solutions
/// (`ModuleAnalyses.platformRequirementRootEvidence`), parallel to the
/// module's solutions: the chain-free evidence of the app procedure each
/// function requirement invokes. The platform's pairing reads it.
pub const PlatformRequirementRootEvidence = struct {
    pool: static_dispatch.EvidencePool,
    spans: []static_dispatch.EvidenceSpan,

    pub fn destroy(self: *PlatformRequirementRootEvidence, allocator: Allocator) void {
        self.pool.deinit(allocator);
        allocator.free(self.spans);
        allocator.destroy(self);
    }
};

/// The module-wide indexes dispatch resolution reads
/// (`ModuleAnalyses.dispatchIndex`): checker records by source identity,
/// and which templates reach each plan, iterator plan and use site, in
/// template order.
pub const DispatchIndex = struct {
    allocator: Allocator,
    /// Each source-defined template's scheme root: its definition's type or
    /// its promoted binding pattern's.
    template_scheme_vars: collections.DenseMap(u32, Var),
    value_use_by_node: collections.DenseMap(u32, u32),
    target_by_fn_var: collections.DenseMap(u32, u32),
    generated_codec_by_source: collections.DenseMap(Var, EvidencePass.GeneratedCodecsByKind),
    where_method_use_by_fn_var: collections.DenseMap(u32, u32),
    where_method_use_by_fn_root: collections.DenseMap(Var, u32),
    local_value_scheme_by_var: collections.DenseMap(u32, u32),
    value_use_record_by_pattern: collections.DenseMap(u32, u32),
    codec_instance_by_template: collections.DenseMap(Var, Var),
    fresh_by_pair_root: std.AutoHashMapUnmanaged(EvidencePass.PairRootKey, Var) = .empty,
    /// Per plan, a range of `plan_sites`.
    plan_reach: []artifact_serialize.Span = &.{},
    /// Per iterator plan, a range of `iterator_sites`.
    iterator_reach: []artifact_serialize.Span = &.{},
    /// Every reference to a plan from a template's body or a defaulted-field
    /// expression, grouped by plan, in template order with the defaults
    /// last.
    plan_sites: []PlanReach = &.{},
    iterator_sites: []PlanReach = &.{},
    /// Use sites, sorted by key then template order.
    site_reach: []SiteReach = &.{},

    /// One reference to a plan: the template whose body reaches it (null for
    /// a defaulted-field expression) and the scope it occurs in.
    pub const PlanReach = struct {
        template: ?u32,
        scope: DispatchScope,
    };

    pub const SiteReach = struct {
        site: u32,
        template: u32,

        fn lessThan(_: void, a: SiteReach, b: SiteReach) bool {
            if (a.site != b.site) return a.site < b.site;
            return a.template < b.template;
        }
    };

    pub fn destroy(self: *DispatchIndex) void {
        const allocator = self.allocator;
        self.template_scheme_vars.deinit();
        self.value_use_by_node.deinit();
        self.target_by_fn_var.deinit();
        self.generated_codec_by_source.deinit();
        self.where_method_use_by_fn_var.deinit();
        self.where_method_use_by_fn_root.deinit();
        self.local_value_scheme_by_var.deinit();
        self.value_use_record_by_pattern.deinit();
        self.codec_instance_by_template.deinit();
        self.fresh_by_pair_root.deinit(allocator);
        allocator.free(self.plan_reach);
        allocator.free(self.iterator_reach);
        allocator.free(self.plan_sites);
        allocator.free(self.iterator_sites);
        allocator.free(self.site_reach);
        allocator.destroy(self);
    }

    pub fn planSites(self: *const DispatchIndex, plan: static_dispatch.StaticDispatchPlanId) []const PlanReach {
        const span = self.plan_reach[@backingInt(plan)];
        return self.plan_sites[span.start..][0..span.len];
    }

    pub fn iteratorSites(self: *const DispatchIndex, plan: static_dispatch.IteratorForPlanId) []const PlanReach {
        const span = self.iterator_reach[@backingInt(plan)];
        return self.iterator_sites[span.start..][0..span.len];
    }

    pub fn siteTemplates(self: *const DispatchIndex, site: u32) []const SiteReach {
        var low: usize = 0;
        var high: usize = self.site_reach.len;
        while (low < high) {
            const mid = low + (high - low) / 2;
            if (self.site_reach[mid].site < site) low = mid + 1 else high = mid;
        }
        var end = low;
        while (end < self.site_reach.len and self.site_reach[end].site == site) end += 1;
        return self.site_reach[low..end];
    }
};

/// The checked data of one module its dispatch analyses read.
pub const DispatchSource = struct {
    env: *const ModuleEnv,
    module_idx: u32,
    key: CheckedModuleArtifactKey,
    /// The module's names, which dispatch resolution interns the method
    /// names of the obligations it resolves into.
    names: *canonical.CanonicalNameStore,
    types: DispatchTypes,
    module_index: *const ModuleIndex,
    /// The module's body analyses, whose index `module_index` is.
    body_analyses: *BodyAnalyses,
    method_registry: *const static_dispatch.MethodRegistry,
    templates: *const CheckedProcedureTemplateTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    plans: *const static_dispatch.StaticDispatchPlanTable,
    refs: *const ResolvedValueRefTable,
    entry_wrappers: *const EntryWrapperTable,
    callable_eval_templates: CallableEvalTemplateTableView,
    compile_time_roots: *const CompileTimeRootTable,
    analyses: *ModuleAnalyses,
};

/// The reader over a module's dispatch resolution and dispatch schemas,
/// each computed on first demand into the module's slots.
pub const CheckedDispatch = struct {
    source: DispatchSource,

    pub const Error = Allocator.Error;

    fn analyses(self: CheckedDispatch) *ModuleAnalyses {
        return self.source.analyses;
    }

    /// The schema of procedure template `template`.
    pub fn templateSchema(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error!SchemaView {
        return (try self.analyses().templateSchema(self, template)).view;
    }

    /// The schema of generalized local scope `scope`.
    pub fn scopeSchema(self: CheckedDispatch, scope: DispatchScopeId) Error!SchemaView {
        return (try self.analyses().scopeSchema(self, scope)).view;
    }

    /// The template's quantified variables (`SchemaView.vars`).
    pub fn templateSchemeVars(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error![]const CheckedTypeId {
        return (try self.templateSchema(template)).vars;
    }

    /// The template's evidence parameters (`SchemaView.params`).
    pub fn evidenceParams(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error![]const static_dispatch.EvidenceParamRecord {
        return (try self.templateSchema(template)).params;
    }

    /// The evidence pool of `owner`.
    pub fn pool(self: CheckedDispatch, owner: static_dispatch.EvidenceOwner) Error!*const static_dispatch.EvidencePool {
        return switch (owner) {
            .module => &(try self.analyses().moduleDispatch(self)).pool,
            .platform_requirements => &(try self.analyses().platformRequirementRootEvidence(self)).pool,
            _ => &(try self.analyses().templateDispatch(self, owner.template().?)).pool,
        };
    }

    pub fn evidenceNode(self: CheckedDispatch, id: static_dispatch.EvidenceNodeId) Error!static_dispatch.EvidenceNode {
        return (try self.pool(id.owner)).node(id);
    }

    pub fn evidenceEntries(self: CheckedDispatch, span: static_dispatch.EvidenceSpan) Error![]const static_dispatch.CheckedEvidence {
        if (span.len == 0) return &.{};
        return (try self.pool(span.owner)).entries(span);
    }

    pub fn substitution(self: CheckedDispatch, span: static_dispatch.EvidenceSpan) Error![]const CheckedTypeId {
        if (span.len == 0) return &.{};
        return (try self.pool(span.owner)).types(span);
    }

    /// The evidence node's nested evidence, in the target scheme's
    /// canonical evidence-param order.
    pub fn nestedEvidence(self: CheckedDispatch, node: static_dispatch.EvidenceNode) Error![]const static_dispatch.CheckedEvidence {
        return switch (node.nested) {
            .resolved => |span| self.evidenceEntries(span),
            .from_callable => checkedArtifactInvariant("callable-derived target evidence has no resolved checked-evidence span", .{}),
            .through_alias => checkedArtifactInvariant("alias-scope evidence was read as its target's own evidence", .{}),
        };
    }

    /// The evidence an edge that instantiated a procedure alias's scheme
    /// resolved for that alias's own obligations.
    pub fn aliasScopeEvidence(self: CheckedDispatch, node: static_dispatch.EvidenceNode) Error![]const static_dispatch.CheckedEvidence {
        return switch (node.nested) {
            .through_alias => |span| self.evidenceEntries(span),
            .resolved, .from_callable => checkedArtifactInvariant("target evidence was read as an alias scope's evidence", .{}),
        };
    }

    /// Plan `id` with its total resolution.
    pub fn plan(self: CheckedDispatch, id: static_dispatch.StaticDispatchPlanId) Error!static_dispatch.StaticDispatchCallPlan {
        const recorded = self.source.plans.plans[@backingInt(id)];
        return static_dispatch.StaticDispatchCallPlan.fromRecorded(recorded, try self.analyses().planResolution(self, id));
    }

    /// Iterator plan `id` with its calls' total resolutions.
    pub fn iteratorPlan(self: CheckedDispatch, id: static_dispatch.IteratorForPlanId) Error!static_dispatch.ResolvedIteratorForPlan {
        const recorded = self.source.plans.iterator_for_plans[@backingInt(id)];
        return static_dispatch.ResolvedIteratorForPlan.fromRecorded(recorded, try self.analyses().iteratorPlanResolution(self, id));
    }

    fn siteEntry(self: CheckedDispatch, expr: CIR.Expr.Idx) Error!?SiteEvidenceLookup {
        return self.analyses().siteEvidence(self, @backingInt(expr));
    }

    /// Evidence for the scheme instantiated at `expr` (a constrained
    /// definition reference or an expression-position function construction
    /// edge), in the scheme's canonical evidence-param order; null when no
    /// checked instantiation edge was recorded for the expression.
    pub fn siteEvidence(self: CheckedDispatch, expr: CIR.Expr.Idx) Error!?[]const static_dispatch.CheckedEvidence {
        const found = (try self.siteEntry(expr)) orelse return null;
        return try self.evidenceEntries(.{ .owner = found.owner, .start = found.entry.start, .len = found.entry.len });
    }

    /// The range `siteEvidence` reads.
    pub fn siteEvidenceSpan(self: CheckedDispatch, expr: CIR.Expr.Idx) Error!?static_dispatch.EvidenceSpan {
        const found = (try self.siteEntry(expr)) orelse return null;
        return .{ .owner = found.owner, .start = found.entry.start, .len = found.entry.len };
    }

    /// The substitution recorded for the scheme used at `expr`: one checked
    /// type per quantified variable of that scheme, in the scheme's
    /// `scheme_vars` order. Null when the expression has no site entry at
    /// all; empty when its entry recorded no instantiation.
    pub fn siteSubstitution(self: CheckedDispatch, expr: CIR.Expr.Idx) Error!?[]const CheckedTypeId {
        const found = (try self.siteEntry(expr)) orelse return null;
        return try self.substitution(.{ .owner = found.owner, .start = found.entry.subst_start, .len = found.entry.subst_len });
    }

    /// The checked type of the instance a stored nested-function use at
    /// `expr` places into its containing value.
    pub fn siteInstanceType(self: CheckedDispatch, expr: CIR.Expr.Idx) Error!?CheckedTypeId {
        const found = (try self.siteEntry(expr)) orelse return null;
        if (found.entry.instance_ty == static_dispatch.SiteEvidenceEntry.no_site_instance) return null;
        return @fromBackingInt(@intCast(found.entry.instance_ty));
    }

    /// The chain-free root evidence of a procedure template: its own
    /// requirements resolved without a caller. Null explicitly marks a
    /// scheme-only procedure that requires instantiation evidence and
    /// cannot be invoked as a bare root.
    pub fn templateRootEvidenceSpan(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error!?static_dispatch.EvidenceSpan {
        return (try self.analyses().templateDispatch(self, template)).root_evidence;
    }

    /// The entries of `templateRootEvidenceSpan`.
    pub fn templateRootEvidence(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error![]const static_dispatch.CheckedEvidence {
        const span = (try self.templateRootEvidenceSpan(template)) orelse
            checkedArtifactInvariant("a scheme-only procedure's root evidence was read", .{});
        return self.evidenceEntries(span);
    }

    /// How the template's plans relate to its specialization.
    pub fn templateRelations(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error!*const TemplateDispatchRelations {
        return self.analyses().templateDispatchRelations(self, template);
    }

    /// The module's generated-codec contracts with every call linked.
    pub fn generatedCodecs(self: CheckedDispatch) Error!static_dispatch.GeneratedCodecTable {
        return (try self.analyses().moduleDispatch(self)).codecTable();
    }

    /// The app's root evidence for its platform requirement solution
    /// `solution` (an index into the module's solutions).
    pub fn platformRequirementRootEvidence(self: CheckedDispatch, solution: usize) Error!static_dispatch.EvidenceSpan {
        return (try self.analyses().platformRequirementRootEvidence(self)).spans[solution];
    }

    /// The module `key` names among the modules dispatch resolution reads.
    pub fn importedView(self: CheckedDispatch, key: ModuleId) ?ImportedModuleView {
        const imports = CheckedImportViews{ .current_owner = self.source.key.digest(), .direct = &.{}, .available = self.source.analyses.dispatch_imports };
        return imports.viewForKey(key);
    }

    /// The module's literal call graph.
    pub fn literalGraph(self: CheckedDispatch) Error!*LiteralGraph {
        return self.analyses().literalGraph(self);
    }

    /// The literal requirements of procedure template `template`'s scheme. A
    /// literal root's entry wrapper converts closed literals only and has
    /// none.
    pub fn templateLiteralRequirements(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error![]const LiteralRequirement {
        const row = template.rowIndex() orelse return &.{};
        const graph = try self.literalGraph();
        const component = try self.analyses().literalComponent(self, graph, graph.components.component_of[row]);
        return component.requirementsOf(.{ .template = row, .scope = null });
    }

    /// The literal requirements of generalized local scope `scope`'s scheme.
    pub fn scopeLiteralRequirements(self: CheckedDispatch, scope: DispatchScopeId) Error![]const LiteralRequirement {
        const graph = try self.literalGraph();
        const key: LiteralScopeKey = .{ .template = graph.scope_owners[@backingInt(scope)], .scope = @backingInt(scope) };
        const component = try self.analyses().literalComponent(self, graph, graph.components.component_of[graph.nodeOfScope(key)]);
        return component.requirementsOf(key);
    }

    /// The literal arguments of `edge`, one per literal requirement of the
    /// scheme it instantiates, in requirement order; empty when the scheme
    /// has none.
    pub fn literalEdgeArgs(self: CheckedDispatch, edge: LiteralEdge) Error![]const LiteralArgSource {
        const graph = try self.literalGraph();
        const index = graph.edgeIndex(edge) orelse return &.{};
        const component = try self.analyses().literalComponent(self, graph, graph.components.component_of[graph.edges[index].holder]);
        return component.edgeArgs(index);
    }

    /// Append the literal argument roots template `template`'s edges read to
    /// `out`, ascending: a row's, or a literal conversion root's entry
    /// wrapper's, whose edges are its conversion's.
    pub fn appendLiteralArgumentDemand(self: CheckedDispatch, allocator: Allocator, template: canonical.CheckedProcedureTemplateId, out: *std.ArrayList(ComptimeRootId)) Error!void {
        if (template.rowIndex()) |row| {
            try out.appendSlice(allocator, try self.analyses().templateLiteralArgumentDemand(self, row));
            return;
        }
        const record = try self.literalRoot(templateLiteralRoot(template).?);
        const plan_id = record.plan orelse return;
        var walker: LiteralEdgeWalker = .{ .allocator = allocator, .dispatch = self };
        defer walker.deinit();
        var found: std.ArrayListUnmanaged(LiteralEdgeWalker.Found) = .empty;
        defer found.deinit(allocator);
        try walker.plan(try self.plan(plan_id), &found);
        const first = out.items.len;
        for (found.items) |item| {
            for (try self.literalEdgeArgs(.{ .node = item.id })) |arg| switch (arg) {
                .root => |id| try out.append(allocator, id),
                .forwarded, .unbound => {},
            };
        }
        const added = out.items[first..];
        std.mem.sort(ComptimeRootId, added, {}, comptimeRootIdLessThan);
        var kept: usize = 0;
        for (added, 0..) |id, index| {
            if (index != 0 and added[index - 1] == id) continue;
            added[kept] = id;
            kept += 1;
        }
        out.shrinkRetainingCapacity(first + kept);
    }

    /// Append every literal root of the module to `out`: each top-level
    /// unit's literal conversion roots in unit order, then each literal
    /// component's argument roots in component order.
    pub fn appendLiteralRoots(self: CheckedDispatch, allocator: Allocator, out: *std.ArrayList(ComptimeRootId)) Error!void {
        for (0..self.source.module_index.units.len) |unit| {
            const conversions = try self.analyses().unitLiteralConversions(self, @fromBackingInt(@intCast(unit)));
            for (conversions.records) |record| try out.append(allocator, record.root.id);
        }
        const graph = try self.literalGraph();
        for (0..graph.components.count()) |component| {
            const done = try self.analyses().literalComponent(self, graph, @intCast(component));
            for (done.roots) |record| try out.append(allocator, record.root.id);
        }
    }

    /// The conversion root of the literal at `raw_node`, or null.
    pub fn literalConversionRoot(self: CheckedDispatch, raw_node: u32) Error!?ComptimeRootId {
        const candidate = (try literalConversionCandidate(dispatchSourceBodies(self.source), self, raw_node)) orelse return null;
        return literalConversionRootId(candidate.literal);
    }

    /// Literal root `id` with its entry wrapper.
    pub fn literalRoot(self: CheckedDispatch, id: ComptimeRootId) Error!*const LiteralRootRecord {
        const name = literalRootName(id) orelse checkedArtifactInvariant("a root of the root table was read as a literal root", .{});
        switch (name) {
            .conversion => |literal| {
                const unit = self.source.module_index.unitOf(literal.node());
                const conversions = try self.analyses().unitLiteralConversions(self, unit);
                return conversions.record(literal.node()) orelse checkedArtifactInvariant("a literal conversion root names a literal without one", .{});
            },
            .argument => |argument| {
                const graph = try self.literalGraph();
                const index = graph.edgeIndex(argument.edge) orelse checkedArtifactInvariant("a literal argument root names an edge no body holds", .{});
                const component = try self.analyses().literalComponent(self, graph, graph.components.component_of[graph.edges[index].holder]);
                return component.root(id) orelse checkedArtifactInvariant("a literal argument root names an argument its edge does not root", .{});
            },
        }
    }

    /// Procedure template `template`: a row of the template table, or a
    /// literal root's entry wrapper, whose body converts its root's literal.
    pub fn procedureTemplate(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error!CheckedProcedureTemplate {
        const root = templateLiteralRoot(template) orelse return self.source.templates.get(template);
        const record = try self.literalRoot(root);
        return .{
            .proc_base = self.source.templates.literal_root_proc_base,
            .template_id = template,
            .body = .{ .literal_root = root },
            .checked_fn_scheme = record.checked_fn_scheme,
            .checked_fn_root = record.checked_fn_root,
            .static_dispatch_plans = .{},
            .resolved_value_refs = .{},
            .top_level_value_uses = .{},
            .target = .comptime_only,
        };
    }

    /// The relations of template `template`'s interface to its
    /// specialization.
    pub fn specializationRelations(self: CheckedDispatch, template: *const CheckedProcedureTemplate) Error![]const SpecializationInterfaceRelation {
        if (templateLiteralRoot(template.template_id)) |root| return &(try self.literalRoot(root)).relation;
        return self.source.templates.specializationRelations(template);
    }

    /// Compile-time root `id`: a row of the root table, or a literal root.
    /// A literal root's payload is the evaluation output's
    /// (`CheckedModuleArtifact.compileTimeRoot`).
    pub fn compileTimeRoot(self: CheckedDispatch, id: ComptimeRootId) Error!CompileTimeRoot {
        if (id.rowIndex() != null) return self.source.compile_time_roots.root(id);
        return (try self.literalRoot(id)).root;
    }

    /// How much of each of template `template`'s quantified variables
    /// (`SchemaView.vars`) its body demands, in slot order. Monotype
    /// specializes the template over only this much of each variable's
    /// substitution (design.md "Specialization By Demand").
    pub fn templateDemands(self: CheckedDispatch, template: canonical.CheckedProcedureTemplateId) Error![]const SchemeVarDemand {
        return self.analyses().templateDemands(self, template);
    }
};
/// Resolve every static-dispatch plan and instantiation-site obligation to an
/// explicit `direct` / `constraint(k)` / `structural` / `checked_error`
/// resolution, and publish each template's evidence params.
///
/// Runs after `sealCheckedProcedureTemplateRefs` so plans and value refs are
/// grouped per template: `constraint(k)` indexes the enclosing template's
/// canonical evidence-param list. Concrete dispatchers resolve through the
/// checked registry; where-var dispatchers resolve to their param index;
/// evidence for call edges comes from the checker's persisted
/// `SchemeUseRecord`s, whose fresh vars are resolved against the
/// settled type store.
const EvidencePass = struct {
    pub const PairRootKey = struct {
        pairs_start: u32,
        pairs_len: u32,
        old_root: Var,
    };
    const PublishedScheme = struct {
        vars: artifact_serialize.Span,
        params: artifact_serialize.Span,
    };
    /// Each dispatcher root's params within one schema, in param order.
    /// Composite scheme requirements are matched by their exact relation
    /// instead, so they are not indexed.
    pub const DispatcherParams = struct {
        /// Sorted by dispatcher root, then by param index.
        rows: []const Row = &.{},

        const Row = struct {
            root: Var,
            param: u32,

            fn lessThan(_: void, left: Row, right: Row) bool {
                if (left.root != right.root) return @backingInt(left.root) < @backingInt(right.root);
                return left.param < right.param;
            }

            fn orderRoot(root: Var, row: Row) std.math.Order {
                return std.math.order(@backingInt(root), @backingInt(row.root));
            }
        };

        /// The rows of `root`'s params, in param order.
        fn forRoot(self: DispatcherParams, root: Var) []const Row {
            const start, const end = std.sort.equalRange(Row, self.rows, root, Row.orderRoot);
            return self.rows[start..end];
        }
    };
    /// One level of an evidence chain: a schema's params, their index, and
    /// the published scheme whose parameters they are.
    const ChainLevel = struct {
        params: []const EvidenceParam,
        by_dispatcher: DispatcherParams,
        scheme: ?u32,
        published: []const static_dispatch.EvidenceParamRecord,

        const empty: ChainLevel = .{ .params = &.{}, .by_dispatcher = .{}, .scheme = null, .published = &.{} };

        fn fromScheme(chain: ?ChainScheme) ChainLevel {
            const scheme = chain orelse return .empty;
            return .{ .params = scheme.params, .by_dispatcher = scheme.by_dispatcher, .scheme = scheme.owner, .published = scheme.published };
        }
    };
    const SchemeSchema = struct {
        params: []EvidenceParam,
        by_dispatcher: DispatcherParams,
        /// The nodes `params` name their paths by.
        path_nodes: []const static_dispatch.EvidencePathNode,
        identity_vars: []const Var,
        published: ?PublishedScheme = null,
    };

    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    checked_types: DispatchTypes,
    module_index: *const ModuleIndex,
    local_method_registry: *const static_dispatch.MethodRegistry,
    import_views: CheckedImportViews,
    /// The import views method-target lookup searches after the local
    /// registry, in search order.
    method_lookup_views: []const *const ImportedModuleView = &.{},
    plan_table: *const static_dispatch.StaticDispatchPlanTable,
    templates: *const CheckedProcedureTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    sites: *const TemplateDispatchSites,
    entry_wrappers: *const EntryWrapperTable,
    compile_time_roots: *const CompileTimeRootTable,
    /// The module's dispatch reader, through which the pass reads the
    /// schemas of templates and scopes and other modules' dispatch.
    dispatch: CheckedDispatch,
    /// The analysis whose pool this pass fills.
    owner: static_dispatch.EvidenceOwner,
    /// The module's checker-record indexes; the index under construction
    /// while `buildIndexes` runs.
    index: *const DispatchIndex,

    types: *const types.Store,

    /// Schemas enumerated by this pass, by scheme owner.
    schemas_by_root: collections.DenseMap(Var, SchemeSchema),
    /// Reuse traversal capacity while giving each schema fresh identity slots.
    identity_writer: canonical_type_keys.TypeWriter,
    /// Memoized evidence node per dispatch_target record.
    node_by_record: collections.DenseMap(u32, static_dispatch.EvidenceNodeId),
    /// Hash buckets and collision chains for structurally interned evidence
    /// nodes. Every `EvidenceNodeId` of the pool is therefore an exact
    /// evidence identity, independent of which checker record requested it.
    evidence_node_buckets: std.AutoHashMap(u64, u32),
    evidence_node_next: std.ArrayList(?u32),
    record_in_progress: collections.DenseMap(u32, void),
    /// Site-evidence dedupe (a checked expr can be reachable from two scopes
    /// of the walk).
    site_seen: collections.DenseMap(u32, void),

    evidence_nodes: std.ArrayList(static_dispatch.EvidenceNode),
    evidence_refs: std.ArrayList(static_dispatch.CheckedEvidence),
    /// Hash buckets and collision chains for interned callable contract
    /// vectors: each bucket names its newest row in `callable_contracts`.
    callable_contract_buckets: std.AutoHashMapUnmanaged(u64, u32) = .empty,
    callable_contracts: std.ArrayListUnmanaged(CallableContractRow) = .empty,
    site_evidence: std.ArrayList(static_dispatch.SiteEvidenceEntry),
    evidence_params_pool: std.ArrayList(static_dispatch.EvidenceParamRecord),
    evidence_path_nodes: std.ArrayList(static_dispatch.EvidencePathNode),
    /// Scheme path node -> published path node, for the scheme being published.
    published_path_nodes: std.ArrayList(u32),
    published_path_chain: std.ArrayList(u32),
    evidence_param_callables: std.ArrayList(CheckedTypeId),
    scheme_vars_pool: std.ArrayList(CheckedTypeId),
    site_substitutions: std.ArrayList(CheckedTypeId),
    /// Solver variables of the scheme whose params are being appended, in
    /// slot order, so each param resolves to its slot.
    scheme_var_scratch: std.ArrayListUnmanaged(Var) = .empty,
    /// Traversal scratch for `schemeExtendsLabeledTagRow`.
    labeled_row_visited: collections.DenseMapUnmanaged(Var, void) = .empty,
    labeled_row_pending: std.ArrayList(Var) = .empty,

    enum_scratch: dispatch_evidence.Scratch,
    /// Stable copies of enumerated semantic paths. Evidence resolution may
    /// recursively enumerate another scheme before finishing the current
    /// vector, so consumers cannot retain aliases into `enum_scratch`.
    enumerated_path_arena: base.SingleThreadArena,
    /// Scratch backing for the chain currently being resolved against.
    chain_scratch: std.ArrayList(ChainLevel),
    /// The plans and iterator plans this pass resolved: a plan reachable from
    /// two scopes of one walk resolves once.
    plan_results: std.ArrayListUnmanaged(PlanResolutionEntry) = .empty,
    iterator_results: std.ArrayListUnmanaged(IteratorPlanResolutionEntry) = .empty,
    plan_resolved: collections.DenseMapUnmanaged(u32, void) = .empty,
    iterator_plan_resolved: collections.DenseMapUnmanaged(u32, void) = .empty,
    /// Explicit shared-var use records deferred during template walks because
    /// the current chain did not bind every obligation.
    deferred_use_sites: std.ArrayListUnmanaged(DeferredUseSite) = .empty,
    /// Evidence already resolved for a scheme-use substitution: records
    /// naming the same substitution range of the same scheme (uses replayed
    /// from one source) resolve it once.
    record_spans_by_substitution: std.AutoHashMapUnmanaged(RecordSubstitutionKey, RecordSiteSpans) = .empty,
    /// The param chain in scope while resolving a site's evidence entries, so
    /// a fresh var that settled onto an enclosing where-var forwards as
    /// `constraint(depth, k)`. Index 0 is the innermost generalized callable.
    current_chain: []const ChainLevel = &.{},
    /// Whether the obligations being resolved are those of a template running
    /// as a root (`rootDefaultObligation`).
    at_template_root: bool = false,

    const EvidenceParam = dispatch_evidence.EvidenceParam;
    /// The generated-codec derivation each kind selected for one
    /// checker-authored source constraint.
    pub const GeneratedCodecsByKind = std.EnumArray(static_dispatch.GeneratedCodecDerivationKind, ?static_dispatch.GeneratedCodecDerivationId);
    const CallableContractRow = struct {
        span: static_dispatch.EvidenceSpan,
        /// The next older row in the same bucket.
        next: u32,

        const none = std.math.maxInt(u32);
    };

    /// A pass over `dispatch`'s module that fills `owner`'s pool.
    fn init(
        allocator: Allocator,
        dispatch: CheckedDispatch,
        module_data: *TypedCIR.ModuleData,
        owner: static_dispatch.EvidenceOwner,
        index: *const DispatchIndex,
    ) Allocator.Error!EvidencePass {
        const source = dispatch.source;
        const module = TypedCIR.Module.readOnly(allocator, source.module_idx, module_data);
        const import_views = CheckedImportViews{
            .current_owner = source.key.digest(),
            .direct = &.{},
            .available = source.analyses.dispatch_imports,
        };
        return .{
            .allocator = allocator,
            .module = module,
            .names = source.names,
            .checked_types = source.types,
            .module_index = source.module_index,
            .local_method_registry = source.method_registry,
            .import_views = import_views,
            .method_lookup_views = try methodLookupViews(allocator, import_views),
            .plan_table = source.plans,
            .templates = source.templates,
            .resolved_value_refs = source.refs,
            .sites = &source.templates.dispatch_sites,
            .entry_wrappers = source.entry_wrappers,
            .compile_time_roots = source.compile_time_roots,
            .dispatch = dispatch,
            .owner = owner,
            .index = index,
            .types = module.typeStoreConst(),
            .schemas_by_root = collections.DenseMap(Var, SchemeSchema).init(allocator),
            .identity_writer = canonical_type_keys.TypeWriter.init(allocator, module.typeStoreConst(), module.moduleEnvConst()),
            .node_by_record = collections.DenseMap(u32, static_dispatch.EvidenceNodeId).init(allocator),
            .evidence_node_buckets = std.AutoHashMap(u64, u32).init(allocator),
            .evidence_node_next = .empty,
            .record_in_progress = collections.DenseMap(u32, void).init(allocator),
            .site_seen = collections.DenseMap(u32, void).init(allocator),
            .evidence_nodes = .empty,
            .evidence_refs = .empty,
            .site_evidence = .empty,
            .evidence_params_pool = .empty,
            .evidence_path_nodes = .empty,
            .published_path_nodes = .empty,
            .published_path_chain = .empty,
            .evidence_param_callables = .empty,
            .scheme_vars_pool = .empty,
            .site_substitutions = .empty,
            .enum_scratch = .{},
            .enumerated_path_arena = base.SingleThreadArena.init(allocator),
            .chain_scratch = .empty,
        };
    }

    fn deinit(self: *EvidencePass) void {
        self.allocator.free(self.method_lookup_views);
        self.plan_results.deinit(self.allocator);
        self.iterator_results.deinit(self.allocator);
        self.plan_resolved.deinit(self.allocator);
        self.iterator_plan_resolved.deinit(self.allocator);
        self.deferred_use_sites.deinit(self.allocator);
        var schemas = self.schemas_by_root.valueIterator();
        while (schemas.next()) |schema| self.allocator.free(schema.identity_vars);
        self.schemas_by_root.deinit();
        self.identity_writer.deinit();
        self.node_by_record.deinit();
        self.evidence_node_buckets.deinit();
        self.evidence_node_next.deinit(self.allocator);
        self.record_in_progress.deinit();
        self.site_seen.deinit();
        self.evidence_nodes.deinit(self.allocator);
        self.evidence_refs.deinit(self.allocator);
        self.callable_contract_buckets.deinit(self.allocator);
        self.callable_contracts.deinit(self.allocator);
        self.site_evidence.deinit(self.allocator);
        self.record_spans_by_substitution.deinit(self.allocator);
        self.evidence_params_pool.deinit(self.allocator);
        self.evidence_path_nodes.deinit(self.allocator);
        self.published_path_nodes.deinit(self.allocator);
        self.published_path_chain.deinit(self.allocator);
        self.evidence_param_callables.deinit(self.allocator);
        self.scheme_vars_pool.deinit(self.allocator);
        self.site_substitutions.deinit(self.allocator);
        self.scheme_var_scratch.deinit(self.allocator);
        self.labeled_row_visited.deinit(self.allocator);
        self.labeled_row_pending.deinit(self.allocator);
        self.enum_scratch.deinit(self.allocator);
        self.enumerated_path_arena.deinit();
        self.chain_scratch.deinit(self.allocator);
    }

    /// The pool this pass filled, handed to its owner's result.
    fn takePool(self: *EvidencePass) Allocator.Error!static_dispatch.EvidencePool {
        const nodes = try self.evidence_nodes.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(nodes);
        const refs = try self.evidence_refs.toOwnedSlice(self.allocator);
        errdefer self.allocator.free(refs);
        return .{
            .owner = self.owner,
            .nodes = nodes,
            .refs = refs,
            .substitutions = try self.site_substitutions.toOwnedSlice(self.allocator),
        };
    }

    fn takeSiteEvidence(self: *EvidencePass) Allocator.Error![]static_dispatch.SiteEvidenceEntry {
        std.mem.sort(static_dispatch.SiteEvidenceEntry, self.site_evidence.items, {}, siteEvidenceLessThan);
        return self.site_evidence.toOwnedSlice(self.allocator);
    }

    fn takePlanResults(self: *EvidencePass) Allocator.Error![]PlanResolutionEntry {
        std.mem.sort(PlanResolutionEntry, self.plan_results.items, {}, PlanResolutionEntry.lessThan);
        return self.plan_results.toOwnedSlice(self.allocator);
    }

    fn takeIteratorResults(self: *EvidencePass) Allocator.Error![]IteratorPlanResolutionEntry {
        std.mem.sort(IteratorPlanResolutionEntry, self.iterator_results.items, {}, IteratorPlanResolutionEntry.lessThan);
        return self.iterator_results.toOwnedSlice(self.allocator);
    }

    /// The template-or-scope schema of `scheme_var`, published into this
    /// pass's pools: its quantified variables, and, unless it has none, its
    /// evidence parameters.
    fn publishTemplateSchema(self: *EvidencePass, template: CheckedProcedureTemplate) Allocator.Error!struct { vars: artifact_serialize.Span, params: artifact_serialize.Span, callable_determines_scheme: bool, chain_root: ?Var } {
        if (self.templateEvidenceSchemeVar(template)) |scheme_var| {
            const schema = try self.publishScheme(scheme_var);
            const params = if (self.isCallableBindingWrapper(template))
                try self.appendReturnedCallableEvidenceParams(schema.params)
            else
                schema.params;
            const template_params = self.evidence_params_pool.items[params.start..][0..params.len];
            var callable_determines_scheme = true;
            if (try self.schemeExtendsLabeledTagRow(scheme_var)) {
                callable_determines_scheme = false;
            } else if (static_dispatch.procedureEvidenceSchema(template_params) == .from_callable) {
                // Only a callable-derived schema consults whether its
                // signature reaches every variable; every other schema
                // already requires checked per-use evidence.
                const signature_vars = try self.identity_writer.identityVarsFromVarIgnoringConstraints(scheme_var);
                defer self.allocator.free(signature_vars);
                callable_determines_scheme = signature_vars.len == schema.vars.len;
            }
            return .{ .vars = schema.vars, .params = params, .callable_determines_scheme = callable_determines_scheme, .chain_root = scheme_var };
        }
        // Constant-evaluation wrappers retain the value's type variables,
        // but have no caller-supplied dispatch parameters of their own.
        return .{ .vars = try self.appendSchemeVars(self.templateSchemeVar(template)), .params = .{}, .callable_determines_scheme = true, .chain_root = null };
    }

    /// Resolve one template's plans, iterator plans, value-reference sites,
    /// scheme-use sites and scope construction sites against its scheme
    /// chain, then its chain-free root evidence.
    fn resolveTemplate(self: *EvidencePass, template_id: canonical.CheckedProcedureTemplateId) Allocator.Error!?static_dispatch.EvidenceSpan {
        const template_index: usize = template_id.index();
        const template = self.templates.templates.items[template_index];
        const template_level = ChainLevel.fromScheme((try self.dispatch.analyses().templateSchema(self.dispatch, template_id)).chain);

        const plan_start = template.static_dispatch_plans.start;
        const plan_refs = self.templates.dispatch_plan_refs[plan_start .. plan_start + template.static_dispatch_plans.len];
        for (plan_refs, 0..) |plan_id, i| {
            const chain = try self.chainFor(self.templates.dispatch_ref_scopes[plan_start + i], template_level);
            try self.resolvePlan(plan_id, chain, false);
        }

        const iter_span = self.sites.iteratorSpan(template_index);
        for (self.sites.iterator_refs[iter_span.start .. iter_span.start + iter_span.len], 0..) |iter_plan_id, i| {
            const chain = try self.chainFor(self.sites.iterator_scopes[iter_span.start + i], template_level);
            try self.resolveIteratorPlan(iter_plan_id, chain, false);
        }

        if (template_index < self.sites.walkedTemplateCount()) {
            const value_ref_start = template.resolved_value_refs.start;
            const value_refs = self.resolved_value_refs.template_refs[value_ref_start .. value_ref_start + template.resolved_value_refs.len];
            for (value_refs, 0..) |ref_id, i| {
                const chain = try self.chainFor(self.sites.value_ref_scopes[value_ref_start + i], template_level);
                try self.emitSiteEvidence(ref_id, chain);
            }
        }

        const scheme_use_span = self.sites.schemeUseSpan(template_index);
        const scheme_use_sites = self.sites.scheme_use_sites[scheme_use_span.start .. scheme_use_span.start + scheme_use_span.len];
        for (scheme_use_sites, 0..) |site, i| {
            const chain = try self.chainFor(self.sites.scheme_use_scopes[scheme_use_span.start + i], template_level);
            try self.emitSchemeUseSiteEvidence(site.record_idx, @backingInt(site.checked_expr), chain);
        }

        const scope_site_span = self.sites.scopeSiteSpan(template_index);
        for (self.sites.scope_sites[scope_site_span.start .. scope_site_span.start + scope_site_span.len]) |site| {
            try self.emitScopeConstructionEvidence(site, template_level);
        }

        var params = std.ArrayListUnmanaged(EvidenceParam).empty;
        defer params.deinit(self.allocator);
        try self.enumerateTemplateParams(template, &params);
        for (params.items) |param| {
            if (param.requires_instantiation) return null;
        }
        return try self.rootEvidence(params.items);
    }

    /// The chain-free evidence of a root edge that invokes a procedure with
    /// `params` and no caller.
    fn rootEvidence(self: *EvidencePass, params: []const EvidenceParam) Allocator.Error!static_dispatch.EvidenceSpan {
        var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
        defer entries.deinit(self.allocator);
        try entries.ensureTotalCapacity(self.allocator, params.len);
        self.current_chain = &.{};
        self.at_template_root = true;
        defer self.at_template_root = false;
        for (params) |param| {
            const evidence = (try self.evidenceForVar(
                param,
                param.dispatcher_var,
                param.constraint.fn_var,
                true,
            )) orelse checkedArtifactInvariant(
                "procedure template root evidence remained unresolved after checking",
                .{},
            );
            entries.appendAssumeCapacity(evidence);
        }
        return try self.appendEvidenceRefs(entries.items);
    }

    /// The evidence of each platform requirement the app's checking solved:
    /// a platform requirement invokes an app procedure without a source
    /// expression use site in the platform module, so its root edge
    /// resolves against the app's solved requirement variable and exact
    /// target records.
    fn resolvePlatformRequirementRoots(self: *EvidencePass) Allocator.Error![]static_dispatch.EvidenceSpan {
        const module_env = self.module.moduleEnvConst();
        const solutions = module_env.platform_requirement_solutions.items.items;
        const spans = try self.allocator.alloc(static_dispatch.EvidenceSpan, solutions.len);
        errdefer self.allocator.free(spans);
        var params = std.ArrayListUnmanaged(EvidenceParam).empty;
        defer params.deinit(self.allocator);
        for (solutions, spans) |solution, *out| {
            out.* = .{ .owner = self.owner };
            switch (solution.outcome) {
                .checked_error => continue,
                .success => {},
            }
            if (!solution.is_function) continue;
            params.clearRetainingCapacity();
            // The app definition owns the complete scheme, including captured
            // codec requirements absent from the platform's copied type root.
            try self.enumerateParams(ModuleEnv.varFrom(solution.def), &params);
            self.current_chain = &.{};
            var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
            defer entries.deinit(self.allocator);
            try entries.ensureTotalCapacity(self.allocator, params.items.len);
            for (params.items) |param| {
                const evidence = (try self.evidenceForVar(
                    param,
                    param.dispatcher_var,
                    param.constraint.fn_var,
                    true,
                )) orelse checkedArtifactInvariant(
                    "platform requirement root evidence remained unresolved after checking",
                    .{},
                );
                entries.appendAssumeCapacity(evidence);
            }
            out.* = try self.appendEvidenceRefs(entries.items);
        }
        return spans;
    }

    /// Resolve what no template resolves: the defaulted-field expressions'
    /// plans and sites (`defaults`), use
    /// sites no template's chain bound (`deferred`), plans and iterator
    /// plans no template's chain bound, and the generated-codec calls.
    fn resolveModule(
        self: *EvidencePass,
        bound_by_template: *const ModuleBoundSet,
        deferred: []const DeferredUseSite,
        codec_calls: []static_dispatch.GeneratedCodecCall,
    ) Allocator.Error!void {
        try self.linkGeneratedCodecCalls(codec_calls);

        // Defaulted-field expression roots (design.md "Defaulted Fields"),
        // collected outside every template: resolve their plans and publish
        // their use-site evidence with no enclosing template params. A
        // default may constrain no declaration type parameter, so every
        // obligation resolves concretely; a generalized local function
        // inside the default still contributes its own scope chain segments.
        const defaults = self.sites.defaultsIndex();
        {
            const plan_span = self.sites.defaultRefs(TemplateDispatchSites.default_plan_refs);
            for (self.templates.dispatch_plan_refs[plan_span.start .. plan_span.start + plan_span.len], 0..) |plan_id, i| {
                if (bound_by_template.plans.contains(@backingInt(plan_id))) continue;
                const chain = try self.chainFor(self.templates.dispatch_ref_scopes[plan_span.start + i], .empty);
                try self.resolvePlan(plan_id, chain, false);
            }

            const iter_span = self.sites.iteratorSpan(defaults);
            for (self.sites.iterator_refs[iter_span.start .. iter_span.start + iter_span.len], 0..) |iter_plan_id, i| {
                if (bound_by_template.iterator_plans.contains(@backingInt(iter_plan_id))) continue;
                const chain = try self.chainFor(self.sites.iterator_scopes[iter_span.start + i], .empty);
                try self.resolveIteratorPlan(iter_plan_id, chain, false);
            }

            const value_span = self.sites.defaultRefs(TemplateDispatchSites.default_value_refs);
            for (self.resolved_value_refs.template_refs[value_span.start .. value_span.start + value_span.len], 0..) |ref_id, i| {
                const site_key = @backingInt(self.resolved_value_refs.records[@backingInt(ref_id)].expr);
                if (bound_by_template.sites.contains(site_key)) continue;
                const chain = try self.chainFor(self.sites.value_ref_scopes[value_span.start + i], .empty);
                try self.emitSiteEvidence(ref_id, chain);
            }

            const scheme_span = self.sites.schemeUseSpan(defaults);
            for (self.sites.scheme_use_sites[scheme_span.start .. scheme_span.start + scheme_span.len], 0..) |site, i| {
                if (bound_by_template.sites.contains(@backingInt(site.checked_expr))) continue;
                const chain = try self.chainFor(self.sites.scheme_use_scopes[scheme_span.start + i], .empty);
                try self.emitSchemeUseSiteEvidence(site.record_idx, @backingInt(site.checked_expr), chain);
            }

            const scope_span = self.sites.scopeSiteSpan(defaults);
            for (self.sites.scope_sites[scope_span.start .. scope_span.start + scope_span.len]) |site| {
                if (bound_by_template.sites.contains(@backingInt(site.checked_expr))) continue;
                try self.emitScopeConstructionEvidence(site, .empty);
            }
        }

        // Explicit shared-var use sites no chain fully bound resolve
        // chain-free here. A site a template or a default already emitted is
        // skipped.
        for (deferred) |site| {
            if (bound_by_template.sites.contains(site.site_key)) continue;
            try self.deferUseSite(site);
        }
        {
            var i: usize = 0;
            while (i < self.deferred_use_sites.items.len) : (i += 1) {
                const site = self.deferred_use_sites.items[i];
                if (self.site_seen.contains(site.site_key)) continue;
                self.current_chain = &.{};
                const spans = (try self.evidenceRefsForRecord(site.record_idx, .commit)).?;
                if (spans.refs.len == 0 and spans.subst.len == 0) continue;
                try self.site_seen.put(site.site_key, {});
                try self.site_evidence.append(self.allocator, .{
                    .key = site.site_key,
                    .start = spans.refs.start,
                    .len = spans.refs.len,
                    .subst_start = spans.subst.start,
                    .subst_len = spans.subst.len,
                    .instance_ty = self.siteInstanceType(site.record_idx),
                });
            }
        }

        // Plans no template's chain bound (dead code, expressions outside
        // any template, obligations no enclosing scheme binds) still have a
        // definitive resolution: resolve them chain-free, exactly like root
        // edges.
        for (0..self.plan_table.plans.len) |raw| {
            if (bound_by_template.plans.contains(@intCast(raw))) continue;
            try self.resolvePlan(@fromBackingInt(@intCast(raw)), &.{}, true);
        }
        for (0..self.plan_table.iterator_for_plans.len) |raw| {
            if (bound_by_template.iterator_plans.contains(@intCast(raw))) continue;
            try self.resolveIteratorPlan(@fromBackingInt(@intCast(raw)), &.{}, true);
        }
    }

    fn deferUseSite(self: *EvidencePass, site: DeferredUseSite) Allocator.Error!void {
        try self.deferred_use_sites.append(self.allocator, site);
    }
    /// A generated body records one checked edge per source occurrence.
    /// Repeated fields whose subjects denote one type share a role, and so one
    /// prepared target, which is sound only when every edge in the role agrees
    /// on its complete callable relation and proof. Runs once the evidence
    /// graph is complete, since that proof spans the module's pool.
    fn debugVerifyGeneratedCodecRoleAgreement(self: *EvidencePass, table: *const static_dispatch.GeneratedCodecTable) Allocator.Error!void {
        if (builtin.mode != .debug) return;
        const type_view = self.checked_types.store.view();
        for (table.generated_codec_derivations) |derivation| {
            const calls = derivation.callsSlice(table);
            for (calls, 0..) |call, index| {
                for (calls[0..index]) |previous| {
                    if (previous.method != call.method or previous.method_role != call.method_role) continue;
                    if (!try @import("codec_identity.zig").callsEquivalent(self.allocator, type_view, table, previous, call)) {
                        checkedArtifactInvariant(
                            "checked generated codec method role contained ambiguous calls",
                            .{},
                        );
                    }
                    // Every call in a role agrees with its first, so the rest
                    // of the role needs no further comparison.
                    break;
                }
            }
        }
    }

    /// The solver root of the scheme a compile-time root evaluates: the
    /// hoisted root's source pattern or the constant's definition. Expression
    /// roots, expect bodies and platform-required bindings have no scheme.
    fn rootSchemeVar(root: CompileTimeRoot) ?Var {
        if (root.source_pattern) |source_pattern| return ModuleEnv.varFrom(source_pattern);
        return switch (root.source) {
            .def => |def_idx| ModuleEnv.varFrom(def_idx),
            .expr, .statement, .required_binding, .hoisted, .literal => null,
        };
    }

    /// The solver root of a template's scheme: its definition's type, or the
    /// scheme of the compile-time root an entry wrapper evaluates. Intrinsic
    /// and hosted wrappers and expression roots have no scheme.
    fn templateSchemeVar(
        self: *EvidencePass,
        template: CheckedProcedureTemplate,
    ) ?Var {
        if (self.index.template_scheme_vars.get(template.template_id.index())) |scheme_var| return scheme_var;
        return switch (template.body) {
            .entry_wrapper => |wrapper_id| rootSchemeVar(self.compile_time_roots.root(self.entry_wrappers.get(wrapper_id).root)),
            .checked_body, .intrinsic_wrapper, .literal_root, .unimplemented => null,
        };
    }

    /// Append a scheme's quantified variables in identity order and retain
    /// their solver roots in `scheme_var_scratch` for slot lookup by the
    /// params appended next.
    fn appendSchemeVars(self: *EvidencePass, scheme_var: ?Var) Allocator.Error!artifact_serialize.Span {
        self.scheme_var_scratch.clearRetainingCapacity();
        const start: u32 = @intCast(self.scheme_vars_pool.items.len);
        const root = scheme_var orelse return .{ .start = start, .len = 0 };
        const identity_vars = try self.identityVarsForSchemeRoot(root);
        try self.scheme_var_scratch.ensureTotalCapacity(self.allocator, identity_vars.len);
        try self.scheme_vars_pool.ensureUnusedCapacity(self.allocator, identity_vars.len);
        for (identity_vars) |identity_var| {
            const resolved = self.types.resolveVar(identity_var).var_;
            self.scheme_var_scratch.appendAssumeCapacity(resolved);
            self.scheme_vars_pool.appendAssumeCapacity(self.checked_types.rootForSourceVar(self.module, resolved) orelse
                checkedArtifactInvariant("scheme quantified variable type was not published", .{}));
        }
        return .{ .start = start, .len = @intCast(identity_vars.len) };
    }

    /// The identity variables of `scheme_root`, enumerated once per resolved
    /// root and shared by every scheme-var and substitution append.
    fn identityVarsForSchemeRoot(self: *EvidencePass, scheme_root: Var) Allocator.Error![]const Var {
        return (try self.schemeSchema(scheme_root)).identity_vars;
    }

    fn publishScheme(self: *EvidencePass, root: ?Var) Allocator.Error!PublishedScheme {
        const scheme_root = root orelse return .{ .vars = .{}, .params = .{} };
        const schema = try self.schemeSchema(scheme_root);
        if (schema.published) |published| return published;
        const published = PublishedScheme{
            .vars = try self.appendSchemeVars(scheme_root),
            .params = try self.appendEvidenceParams(schema.params, schema.path_nodes),
        };
        for (schema.params, 0..) |*param, index| param.published_index = @intCast(index);
        self.schemas_by_root.getPtr(self.schemeOwner(scheme_root)).?.published = published;
        return published;
    }

    fn schemeOwner(self: *EvidencePass, root: Var) Var {
        const requirements = self.module.moduleEnvConst().bindingSchemeCodecRequirementsForNode(@fromBackingInt(@intCast(@backingInt(root))));
        return if (requirements.len > 0) @fromBackingInt(@intCast(requirements[0].scheme_root)) else self.types.resolveVar(root).var_;
    }

    /// The slot of `dispatcher_var` in the scheme whose variables
    /// `appendSchemeVars` retained last.
    fn schemeVarSlot(self: *EvidencePass, dispatcher_var: Var) u32 {
        const root = self.types.resolveVar(dispatcher_var).var_;
        for (self.scheme_var_scratch.items, 0..) |scheme_var, slot| {
            if (scheme_var == root) return @intCast(slot);
        }
        checkedArtifactInvariant("evidence parameter dispatcher was not a quantified variable of its scheme", .{});
    }

    /// The substitution one instantiation record applied to a scheme: for
    /// each quantified variable of `scheme_root` (in slot order) the checked
    /// type of its copy at that edge, or of the variable itself when the edge
    /// shared it. A type `renamings` renames is replaced by its copy.
    fn appendSiteSubstitution(
        self: *EvidencePass,
        scheme_root: Var,
        pairs: []const ModuleEnv.SchemeUsePair,
        renamings: []const ModuleEnv.GeneratedCodecRenaming,
    ) Allocator.Error!static_dispatch.EvidenceSpan {
        const identity_vars = try self.identityVarsForSchemeRoot(scheme_root);
        const start: u32 = @intCast(self.site_substitutions.items.len);
        try self.site_substitutions.ensureUnusedCapacity(self.allocator, identity_vars.len);
        for (identity_vars) |identity_var| {
            const root = self.types.resolveVar(identity_var).var_;
            const edge_var = self.renamedVar(renamings, self.pairForResolved(pairs, root) orelse root);
            self.site_substitutions.appendAssumeCapacity(self.checked_types.rootForSourceVar(self.module, edge_var) orelse
                checkedArtifactInvariant("instantiated scheme variable type was not published", .{}));
        }
        return .{ .owner = self.owner, .start = start, .len = @intCast(identity_vars.len) };
    }

    /// The copy `renamings` makes of `var_`'s type, or `var_` itself when it
    /// renames none.
    fn renamedVar(self: *EvidencePass, renamings: []const ModuleEnv.GeneratedCodecRenaming, var_: Var) Var {
        if (renamings.len == 0) return var_;
        const root = self.types.resolveVar(var_).var_;
        for (renamings) |renaming| {
            if (self.types.resolveVar(@fromBackingInt(@intCast(renaming.source_var))).var_ == root) {
                return @fromBackingInt(@intCast(renaming.copy_var));
            }
        }
        return var_;
    }

    /// Whether a variable of the scheme at `scheme_var` extends a tag row that
    /// has labels of its own (`[Closed, ..errs]`). Such a row normalizes to
    /// the same row whether the variable holds those labels or not, so a
    /// dispatch's normalized callable does not determine the variable's
    /// instantiation.
    fn schemeExtendsLabeledTagRow(self: *EvidencePass, scheme_var: Var) Allocator.Error!bool {
        const visited = &self.labeled_row_visited;
        visited.clearRetainingCapacity();
        const pending = &self.labeled_row_pending;
        pending.clearRetainingCapacity();
        try pending.append(self.allocator, scheme_var);
        while (pending.pop()) |raw| {
            const resolved = self.types.resolveVar(raw);
            if ((try visited.getOrPut(self.allocator, resolved.var_)).found_existing) continue;
            switch (resolved.desc.content) {
                .flex, .rigid, .field_presence, .err => {},
                .alias => |alias| {
                    try pending.append(self.allocator, self.types.getAliasBackingVar(alias));
                    var args = self.types.iterAliasArgs(alias);
                    while (args.next()) |arg| try pending.append(self.allocator, arg);
                },
                .structure => |flat| switch (flat) {
                    .tag_union => |row| {
                        const tags = self.types.getTagsSlice(row.tags);
                        if (tags.len != 0 and self.tagRowTailIsVariable(row.ext)) return true;
                        for (tags.items(.args)) |args| try pending.appendSlice(self.allocator, self.types.sliceVars(args));
                        try pending.append(self.allocator, row.ext);
                    },
                    .record => |record| {
                        try pending.append(self.allocator, record.ext);
                        const fields = self.types.getRecordFieldsSlice(record.fields);
                        for (fields.items(.presence)) |presence| try pending.append(self.allocator, presence.typeVar());
                    },
                    .tuple => |tuple| try pending.appendSlice(self.allocator, self.types.sliceVars(tuple.elems)),
                    .nominal_type => |nominal| {
                        var args = self.types.iterNominalArgs(nominal);
                        while (args.next()) |arg| try pending.append(self.allocator, arg);
                    },
                    .fn_pure, .fn_effectful, .fn_unbound => |func| {
                        try pending.appendSlice(self.allocator, self.types.sliceVars(func.args));
                        try pending.append(self.allocator, func.ret);
                    },
                    .empty_record, .empty_tag_union => {},
                },
            }
        }
        return false;
    }

    /// Whether a tag row's extension chain ends in a variable.
    fn tagRowTailIsVariable(self: *EvidencePass, ext: Var) bool {
        var tail = ext;
        while (true) {
            const content = self.types.resolveVar(tail).desc.content;
            switch (content) {
                .flex, .rigid => return true,
                .alias => |alias| tail = self.types.getAliasBackingVar(alias),
                .structure => |flat| switch (flat) {
                    .tag_union => |row| tail = row.ext,
                    .empty_tag_union => return false,
                    .record, .tuple, .nominal_type, .fn_pure, .fn_effectful, .fn_unbound, .empty_record => checkedArtifactInvariant("tag row extension was not a row", .{}),
                },
                .field_presence, .err => return false,
            }
        }
    }

    fn isCallableBindingWrapper(self: *EvidencePass, template: CheckedProcedureTemplate) bool {
        return switch (template.body) {
            .entry_wrapper => |wrapper_id| blk: {
                const root = self.compile_time_roots.root(self.entry_wrappers.get(wrapper_id).root);
                break :blk root.kind == .callable_binding and root.source_pattern == null;
            },
            .checked_body, .intrinsic_wrapper, .literal_root, .unimplemented => false,
        };
    }

    /// A callable binding's wrapper takes no arguments and returns the
    /// binding's callable, so a dispatcher at a path over that callable is at
    /// the same path below the wrapper's return. The parameters keep the
    /// binding's scheme order, which a use's evidence follows.
    fn appendReturnedCallableEvidenceParams(self: *EvidencePass, params: artifact_serialize.Span) Allocator.Error!artifact_serialize.Span {
        const start: u32 = @intCast(self.evidence_params_pool.items.len);
        for (params.start..params.start + params.len) |index| {
            var param = self.evidence_params_pool.items[index];
            switch (param.source) {
                .scheme_callable => if (param.path.len != 0) {
                    var chain: std.ArrayList(static_dispatch.EvidencePathStep) = .empty;
                    defer chain.deinit(self.allocator);
                    var node = param.path.last;
                    while (node != static_dispatch.no_evidence_path_node) {
                        const path_node = self.evidence_path_nodes.items[node];
                        try chain.append(self.allocator, path_node.step);
                        node = path_node.parent;
                    }
                    var parent: u32 = @intCast(self.evidence_path_nodes.items.len);
                    try self.evidence_path_nodes.append(self.allocator, .{ .parent = static_dispatch.no_evidence_path_node, .step = .{ .kind = @backingInt(static_dispatch.EvidencePathStep.Kind.fn_ret), .data = 0 } });
                    var step_index = chain.items.len;
                    while (step_index > 0) {
                        step_index -= 1;
                        const next_node: u32 = @intCast(self.evidence_path_nodes.items.len);
                        try self.evidence_path_nodes.append(self.allocator, .{ .parent = parent, .step = chain.items[step_index] });
                        parent = next_node;
                    }
                    param.path = .{ .last = parent, .len = param.path.len + 1 };
                },
                .scheme_requirement, .constraint_callable, .use_site_only, .explicit_default, .erased_row_remainder => {},
            }
            try self.evidence_params_pool.append(self.allocator, param);
        }
        return .{ .start = start, .len = params.len };
    }

    /// Only procedure definitions, hoisted source-pattern roots, and callable
    /// bindings bind an evidence chain. A callable binding's wrapper produces
    /// the binding's callable for a use, which supplies the binding's
    /// dispatch parameters exactly as a use of a procedure does. Constant and
    /// expression entry wrappers evaluate their values without receiving the
    /// value's dispatch parameters as arguments.
    fn templateEvidenceSchemeVar(
        self: *EvidencePass,
        template: CheckedProcedureTemplate,
    ) ?Var {
        if (self.index.template_scheme_vars.get(template.template_id.index())) |scheme_var| return scheme_var;
        return switch (template.body) {
            .entry_wrapper => |wrapper_id| blk: {
                const root = self.compile_time_roots.root(self.entry_wrappers.get(wrapper_id).root);
                if (root.source_pattern) |pattern| break :blk ModuleEnv.varFrom(pattern);
                break :blk if (root.kind == .callable_binding) rootSchemeVar(root) else null;
            },
            .checked_body, .intrinsic_wrapper, .literal_root, .unimplemented => null,
        };
    }

    fn enumerateTemplateParams(
        self: *EvidencePass,
        template: CheckedProcedureTemplate,
        params: *std.ArrayListUnmanaged(EvidenceParam),
    ) Allocator.Error!void {
        params.clearRetainingCapacity();
        if (self.templateEvidenceSchemeVar(template)) |scheme_var| {
            try self.enumerateParams(scheme_var, params);
        }
    }

    /// Fill `out`, the index this pass reads as `index`, from the module's
    /// checker records.
    fn buildIndexes(self: *EvidencePass, out: *DispatchIndex) Allocator.Error!void {
        const module_env = self.module.moduleEnvConst();
        // Each source-defined procedure template publishes its source
        // binding's scheme: a top-level def's, or a promoted local function
        // binding pattern's.
        for (self.templates.by_def) |entry| {
            try out.template_scheme_vars.put(entry.template.template.index(), ModuleEnv.varFrom(entry.def));
        }
        for (self.templates.promoted) |entry| {
            try out.template_scheme_vars.put(entry.template.template.index(), ModuleEnv.varFrom(entry.pattern));
        }
        for (module_env.generated_codec_derivations.items.items, 0..) |derivation, index| {
            const kind: static_dispatch.GeneratedCodecDerivationKind = switch (@as(ModuleEnv.GeneratedCodecDerivation.Kind, @fromBackingInt(@intCast(derivation.kind)))) {
                .parser => .parser,
                .encoder => .encoder,
            };
            const source: Var = @fromBackingInt(@intCast(derivation.source_constraint_fn_var));
            const entry = try out.generated_codec_by_source.getOrPutValue(source, .initFill(null));
            const slot = entry.value_ptr.getPtr(kind);
            if (slot.* != null) {
                checkedArtifactInvariant("duplicate generated codec source constraint identity", .{});
            }
            slot.* = @fromBackingInt(@intCast(@as(u32, @intCast(index))));
            if (derivation.template_constraint_fn_var != derivation.source_constraint_fn_var) {
                const template: Var = @fromBackingInt(@intCast(derivation.template_constraint_fn_var));
                try out.codec_instance_by_template.put(self.types.resolveVar(template).var_, source);
            }
        }
        // Records replayed from one source name the same substitution range,
        // whose pairs are indexed once.
        var indexed_ranges = std.AutoHashMap(struct { start: u32, len: u32 }, void).init(self.allocator);
        defer indexed_ranges.deinit();
        for (module_env.scheme_uses.items.items, 0..) |record, i| {
            const pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len];
            const range_seen = (try indexed_ranges.getOrPut(.{ .start = record.pairs_start, .len = record.pairs_len })).found_existing;
            if (!range_seen) for (pairs) |pair| {
                const entry = try out.fresh_by_pair_root.getOrPut(self.allocator, .{
                    .pairs_start = record.pairs_start,
                    .pairs_len = record.pairs_len,
                    .old_root = self.types.resolveVar(@fromBackingInt(@intCast(pair.old_var))).var_,
                });
                if (!entry.found_existing) entry.value_ptr.* = @fromBackingInt(@intCast(pair.fresh_var));
            };
            switch (@as(ModuleEnv.SchemeUseRecord.Slot, @fromBackingInt(@intCast(record.slot_kind)))) {
                .value_use, .shared_value_use => {
                    // Re-checks can record the same binding use twice. A
                    // different scheme at this site is a producer bug, not
                    // another candidate from which publication may choose.
                    const entry = try out.value_use_by_node.getOrPut(record.node_idx);
                    if (entry.found_existing) {
                        const previous = module_env.scheme_uses.items.items[entry.value_ptr.*];
                        std.debug.assert(self.types.resolveVar(@fromBackingInt(@intCast(previous.scheme_root))).var_ ==
                            self.types.resolveVar(@fromBackingInt(@intCast(record.scheme_root))).var_);
                    } else {
                        entry.value_ptr.* = @intCast(i);
                    }
                },
                .dispatch_target, .recursive_dispatch_target => {
                    // `slot_data` is the raw constraint-function var: checking
                    // guarantees exactly one selected-target instantiation per
                    // logical edge. Resolving it through union-find would
                    // collapse distinct evidence records whose callable
                    // signatures later unify.
                    const entry = try out.target_by_fn_var.getOrPut(record.slot_data);
                    if (entry.found_existing) {
                        checkedArtifactInvariant("duplicate raw dispatch-target evidence identity", .{});
                    }
                    entry.value_ptr.* = @intCast(i);
                },
                .where_method_use => {
                    // `slot_data` is the raw body constraint callable. It is
                    // deliberately not resolved through union-find: two body
                    // uses may settle to the same callable shape while still
                    // owning distinct per-use signature copies.
                    const entry = try out.where_method_use_by_fn_var.getOrPut(record.slot_data);
                    if (entry.found_existing) {
                        checkedArtifactInvariant("duplicate raw where-method-use callable identity", .{});
                    }
                    entry.value_ptr.* = @intCast(i);
                    const root = self.types.resolveVar(@as(Var, @fromBackingInt(@intCast(record.slot_data)))).var_;
                    const root_entry = try out.where_method_use_by_fn_root.getOrPut(root);
                    if (!root_entry.found_existing) root_entry.value_ptr.* = @intCast(i);
                },
                .nested_function_use, .recursive_reference, .recursive_value_reference => {},
            }
        }
        // A relation checking folded into a retained same-name relation
        // dispatches through that relation's target instantiation.
        for (module_env.dispatch_relation_merges.items.items) |merge| {
            const record_idx = out.target_by_fn_var.get(merge.retained_fn_var) orelse continue;
            const entry = try out.target_by_fn_var.getOrPut(merge.dropped_fn_var);
            if (entry.found_existing) {
                checkedArtifactInvariant("folded static-dispatch relation had its own dispatch-target evidence", .{});
            }
            entry.value_ptr.* = record_idx;
        }

        const global_value_defs = module_env.store.sliceDefs(module_env.global_value_defs);

        // Generalized local VALUE decls and one representative use record per
        // looked-up pattern (see `local_value_scheme_by_var`).
        for (module_env.scheme_uses.items.items, 0..) |record, i| {
            if (record.slot_kind != @backingInt(ModuleEnv.SchemeUseRecord.Slot.value_use)) continue;
            if (self.module.nodeTag(@fromBackingInt(@intCast(record.node_idx))) != .expr_var) continue;
            const lookup = self.module.expr(@fromBackingInt(@intCast(record.node_idx))).data.e_lookup_local;
            const entry = try out.value_use_record_by_pattern.getOrPut(@backingInt(lookup.pattern_idx));
            if (!entry.found_existing) entry.value_ptr.* = @intCast(i);
        }
        {
            var scheme_params = std.ArrayListUnmanaged(EvidenceParam).empty;
            defer scheme_params.deinit(self.allocator);
            var raw_node: u32 = 0;
            while (raw_node < self.module.nodeCount()) : (raw_node += 1) {
                if (self.module.nodeTag(@fromBackingInt(@intCast(raw_node))) != .statement_decl) continue;
                const statement: CIR.Statement.Idx = @fromBackingInt(@intCast(raw_node));
                const statement_data = self.module.getStatement(statement);
                if (statement_data != .s_decl) continue;
                try self.mapValueSchemeParams(out, statement_data.s_decl.pattern, statement_data.s_decl.expr, &scheme_params);
            }
            // Top-level generalized VALUE defs (e.g. an `if` choosing between
            // closures) lower inline at their single use type exactly like
            // local value decls; their body plans resolve through use records
            // the same way.
            for (global_value_defs) |def_idx| {
                const def = module_env.store.getDef(def_idx);
                try self.mapValueSchemeParams(out, def.pattern, def.expr, &scheme_params);
            }
        }
    }

    fn linkGeneratedCodecCalls(self: *EvidencePass, calls: []static_dispatch.GeneratedCodecCall) Allocator.Error!void {
        const module_env = self.module.moduleEnvConst();
        const source_derivations = module_env.generated_codec_derivations.items.items;
        if (source_derivations.len != self.plan_table.recorded_codec_derivations.len) {
            checkedArtifactInvariant("generated codec source and artifact derivation counts differed", .{});
        }
        for (source_derivations, self.plan_table.recorded_codec_derivations) |source_derivation, derivation| {
            const source_calls = module_env.generated_codec_calls.items.items[source_derivation.calls_start..][0..source_derivation.calls_len];
            const artifact_calls = calls[derivation.calls.start..][0..derivation.calls.len];
            if (source_calls.len != artifact_calls.len) {
                checkedArtifactInvariant("generated codec source and artifact derivation call counts differed", .{});
            }
            for (artifact_calls, source_calls) |*call, source_call| {
                const owner = (try self.methodOwnerForSourceContent(@fromBackingInt(@intCast(source_call.dispatcher_var)))) orelse {
                    call.resolution = .checked_error;
                    continue;
                };
                const target = switch (self.lookupMethodTargetAcrossViews(owner, call.method) orelse {
                    call.resolution = .checked_error;
                    continue;
                }) {
                    // The declaration this codec contract names was rejected;
                    // its diagnostic is reported and nothing lowers it.
                    .rejected => {
                        call.resolution = .checked_error;
                        continue;
                    },
                    .target => |target| target,
                };
                const evidence_var: Var = @fromBackingInt(@intCast(source_call.evidence_var));
                switch (target.kind) {
                    .procedure, .local_proc => {
                        const node_id = try self.evidenceNodeForTarget(
                            target,
                            call.dispatcher_ty,
                            evidence_var,
                            .{
                                .callable_ty = call.callable_ty,
                                .renamings = module_env.generated_codec_renamings.items.items[source_derivation.renamings_start..][0..source_derivation.renamings_len],
                            },
                            .derivation,
                        );
                        switch (self.evidence_nodes.items[node_id.index].nested) {
                            .resolved => {},
                            .from_callable, .through_alias => checkedArtifactInvariant(
                                "generated codec method evidence was not resolved at its checked call edge",
                                .{},
                            ),
                        }
                        call.resolution = .{ .callable = node_id };
                    },
                    .structural => |kind| {
                        const expected_kind: static_dispatch.GeneratedCodecDerivationKind = switch (kind) {
                            .parser => .parser,
                            .encoder => .encoder,
                            .equality, .hash, .map, .map_effectful => checkedArtifactInvariant("non-codec structural method reached a generated codec contract", .{}),
                        };
                        call.resolution = .{ .structural = self.generatedCodecDerivationForSourceConstraint(
                            @fromBackingInt(@intCast(source_call.evidence_var)),
                            expected_kind,
                        ) orelse
                            checkedArtifactInvariant("structural generated codec call had no checked nested derivation", .{}) };
                    },
                }
            }
        }
        if (builtin.mode == .debug) try self.debugVerifyGeneratedCodecContracts(calls);
    }

    fn debugVerifyGeneratedCodecContracts(self: *EvidencePass, all_calls: []const static_dispatch.GeneratedCodecCall) Allocator.Error!void {
        if (builtin.mode != .debug) return;
        const type_view = self.checked_types.store.view();
        var scratch = CheckedTypeStoreView.EqualityScratch.init(self.allocator);
        defer scratch.deinit();
        for (self.plan_table.recorded_codec_derivations) |derivation| {
            const calls = all_calls[derivation.calls.start..][0..derivation.calls.len];
            for (calls, 0..) |call, index| {
                switch (call.resolution) {
                    .pending => checkedArtifactInvariant(
                        "checked generated codec contract retained an unlinked call",
                        .{},
                    ),
                    .checked_error => {},
                    .callable => |node_id| {
                        // Generated codec calls are linked before the evidence
                        // builder transfers its nodes into the published plan
                        // table, so audit the builder-owned node directly.
                        const raw_node = node_id.index;
                        if (raw_node >= self.evidence_nodes.items.len) {
                            checkedArtifactInvariant(
                                "checked generated codec contract referenced a missing callable evidence node",
                                .{},
                            );
                        }
                        const node = self.evidence_nodes.items[raw_node];
                        switch (node.target.kind) {
                            .procedure, .local_proc => {},
                            .structural => checkedArtifactInvariant(
                                "checked generated codec callable resolution named a structural target",
                                .{},
                            ),
                        }
                        switch (node.nested) {
                            .resolved => {},
                            .from_callable, .through_alias => checkedArtifactInvariant(
                                "checked generated codec callable retained unresolved nested evidence",
                                .{},
                            ),
                        }
                        if (node.dispatcher_ty == null or
                            !try type_view.rootExactEql(&scratch, node.dispatcher_ty.?, call.dispatcher_ty))
                        {
                            checkedArtifactInvariant(
                                "checked generated codec callable evidence had a different dispatcher type",
                                .{},
                            );
                        }
                        const instantiated_callable = switch (node.instantiation) {
                            .callable, .alias, .derived_from_callable => |callable| callable,
                            .monomorphic => checkedArtifactInvariant(
                                "checked generated codec callable evidence had no exact instantiation",
                                .{},
                            ),
                        };
                        if (!try type_view.rootExactEql(&scratch, instantiated_callable, call.callable_ty)) {
                            checkedArtifactInvariant(
                                "checked generated codec callable evidence had a different callable type",
                                .{},
                            );
                        }
                    },
                    .structural => |nested_id| {
                        const raw_nested = @backingInt(nested_id);
                        if (raw_nested >= self.plan_table.recorded_codec_derivations.len) {
                            checkedArtifactInvariant(
                                "checked generated codec contract referenced a missing nested derivation",
                                .{},
                            );
                        }
                        if (self.plan_table.recorded_codec_derivations[raw_nested].kind != derivation.kind) {
                            checkedArtifactInvariant(
                                "checked generated codec contract referenced a nested derivation of the wrong kind",
                                .{},
                            );
                        }
                        const nested = self.plan_table.recorded_codec_derivations[raw_nested];
                        // The nested and parent contracts snapshot the same
                        // checked edge independently. Their open identities
                        // are therefore renamed copies, while every sharing
                        // relation and constraint must remain exact.
                        if (!try type_view.rootsAlphaExactEql(
                            &scratch,
                            &.{ nested.constructor_ty, nested.shape_ty },
                            &.{ call.callable_ty, call.dispatcher_ty },
                        )) {
                            checkedArtifactInvariant(
                                "checked generated codec structural call disagreed with its nested derivation types",
                                .{},
                            );
                        }
                    },
                }

                if (call.subject_ty == null and call.method_role != 0) {
                    checkedArtifactInvariant(
                        "checked generated codec shape-independent call had a nonzero method role",
                        .{},
                    );
                }
                var has_previous_role = call.method_role == 0;
                for (calls[0..index]) |previous| {
                    if (previous.method != call.method) continue;
                    if (call.method_role > 0 and previous.method_role == call.method_role - 1) has_previous_role = true;
                    if (previous.method_role != call.method_role) continue;
                    if ((previous.subject_ty == null) != (call.subject_ty == null)) {
                        checkedArtifactInvariant(
                            "checked generated codec method role mixed subject-bearing and shape-independent calls",
                            .{},
                        );
                    }
                    if (call.subject_ty) |subject_ty| {
                        if (!try type_view.rootAliasTransparentEql(&scratch, previous.subject_ty.?, subject_ty)) {
                            checkedArtifactInvariant(
                                "checked generated codec method role named different subject types",
                                .{},
                            );
                        }
                    }
                }
                if (!has_previous_role) {
                    checkedArtifactInvariant(
                        "checked generated codec method roles were not dense in producer order",
                        .{},
                    );
                }
            }
        }
    }

    fn schemeSchema(self: *EvidencePass, root: Var) Allocator.Error!SchemeSchema {
        const owner = self.schemeOwner(root);
        if (self.schemas_by_root.get(owner)) |schema| return schema;
        const env = self.module.moduleEnvConst();
        const requirements = env.bindingSchemeCodecRequirementsForNode(@fromBackingInt(@intCast(@backingInt(root))));
        var explicit = std.ArrayListUnmanaged(dispatch_evidence.SchemeRequirement).empty;
        defer explicit.deinit(self.allocator);
        var relation_roots = std.ArrayListUnmanaged(Var).empty;
        defer relation_roots.deinit(self.allocator);
        try explicit.ensureTotalCapacity(self.allocator, requirements.len);
        try relation_roots.ensureTotalCapacity(self.allocator, requirements.len * 2);
        for (requirements) |requirement| {
            const receiver: Var = @fromBackingInt(@intCast(requirement.receiver_var));
            const constraint = self.types.getStaticDispatchConstraintAt(requirement.constraint_index);
            explicit.appendAssumeCapacity(.{
                .receiver = receiver,
                .constraint = constraint,
                .requires_instantiation = requirement.requires_instantiation != 0,
            });
            relation_roots.appendAssumeCapacity(receiver);
            relation_roots.appendAssumeCapacity(constraint.fn_var);
        }
        var params = std.ArrayListUnmanaged(EvidenceParam).empty;
        defer params.deinit(self.allocator);
        try dispatch_evidence.enumerateEvidenceParamsWithRequirements(self.allocator, self.types, root, explicit.items, &self.enum_scratch, &params);
        const arena = self.enumerated_path_arena.allocator();
        for (params.items) |*param| {
            param.callable_contracts = try arena.dupe(types.StaticDispatchConstraint, param.callable_contracts);
        }
        const identity_vars = try self.identity_writer.identityVarsFromScheme(root, relation_roots.items);
        errdefer self.allocator.free(identity_vars);
        var dispatcher_row_count: usize = 0;
        for (params.items) |param| {
            if (param.source != .scheme_requirement) dispatcher_row_count += 1;
        }
        const dispatcher_rows = try arena.alloc(DispatcherParams.Row, dispatcher_row_count);
        var dispatcher_row_len: usize = 0;
        for (params.items, 0..) |param, index| {
            if (param.source == .scheme_requirement) continue;
            dispatcher_rows[dispatcher_row_len] = .{
                .root = self.types.resolveVar(param.dispatcher_var).var_,
                .param = std.math.cast(u32, index) orelse return error.OutOfMemory,
            };
            dispatcher_row_len += 1;
        }
        std.sort.pdq(DispatcherParams.Row, dispatcher_rows, {}, DispatcherParams.Row.lessThan);
        const schema = SchemeSchema{
            .params = try arena.dupe(EvidenceParam, params.items),
            .by_dispatcher = .{ .rows = dispatcher_rows },
            .path_nodes = try arena.dupe(static_dispatch.EvidencePathNode, self.enum_scratch.paramPathNodes()),
            .identity_vars = identity_vars,
        };
        try self.schemas_by_root.put(owner, schema);
        return schema;
    }

    fn enumerateParams(self: *EvidencePass, root: Var, out: *std.ArrayListUnmanaged(EvidenceParam)) Allocator.Error!void {
        try out.appendSlice(self.allocator, (try self.schemeSchema(root)).params);
    }

    /// The param chain at `scope_id`: the scope's own params first (depth 0),
    /// each enclosing local scope outward, then the template's params. The
    /// returned slice aliases `chain_scratch` and is valid until the next call.
    fn chainFor(self: *EvidencePass, scope_ref: DispatchScope, template_level: ChainLevel) Allocator.Error![]const ChainLevel {
        self.chain_scratch.clearRetainingCapacity();
        var current: ?DispatchScopeId = switch (scope_ref) {
            .root => null,
            .generalized => |id| id,
        };
        while (current) |id| {
            const scope = self.templates.dispatch_scopes[@backingInt(id)];
            const schema = try self.dispatch.analyses().scopeSchema(self.dispatch, id);
            try self.chain_scratch.append(self.allocator, ChainLevel.fromScheme(schema.chain));
            current = scope.parent;
        }
        try self.chain_scratch.append(self.allocator, template_level);
        return self.chain_scratch.items;
    }

    fn paramsForScope(self: *EvidencePass, _: DispatchScopeId, scheme_var: Var) Allocator.Error![]const EvidenceParam {
        return (try self.schemeSchema(scheme_var)).params;
    }

    fn appendEvidenceParams(
        self: *EvidencePass,
        params: []const EvidenceParam,
        path_nodes: []const static_dispatch.EvidencePathNode,
    ) Allocator.Error!artifact_serialize.Span {
        const idents = self.module.identStoreConst();
        const pool_start: u32 = @intCast(self.evidence_params_pool.items.len);
        self.published_path_nodes.clearRetainingCapacity();
        try self.published_path_nodes.appendNTimes(self.allocator, static_dispatch.no_evidence_path_node, path_nodes.len);
        for (params) |param| {
            const source: static_dispatch.EvidenceParamSource = switch (param.source) {
                .scheme_callable => if (param.path_len == 0) explicit: {
                    if (self.pathlessDefaultPhaseForParam(param)) |phase| break :explicit .{ .explicit_default = phase };
                    break :explicit .scheme_callable;
                } else .scheme_callable,
                .constraint_callable => |constraint_callable| constraint: {
                    if (!self.constraintCallableHasSpecializationDefault(param)) break :constraint .use_site_only;
                    // A default-field root always instantiates its local
                    // procedures with checked use-site evidence, so such a
                    // literal dispatcher is read from that evidence rather
                    // than from a runtime dictionary.
                    if (constraint_callable.intro_expr) |intro_expr| {
                        if (self.plan_table.lookupByExpr(@fromBackingInt(@intCast(intro_expr)))) |plan| {
                            if (self.planIsDefaultRoot(plan)) break :constraint .use_site_only;
                        }
                    }
                    break :constraint .{ .constraint_callable = .{
                        .callable_ty = self.checked_types.rootForSourceVar(self.module, constraint_callable.callable_var) orelse
                            checkedArtifactInvariant("constraint-callable evidence source type was not published", .{}),
                    } };
                },
                .erased_row_remainder => .erased_row_remainder,
                .scheme_requirement => .scheme_requirement,
            };
            const published_path: static_dispatch.EvidencePath = switch (source) {
                .scheme_callable, .constraint_callable => .{
                    .last = try self.publishPathNode(path_nodes, param.path_node),
                    .len = param.path_len,
                },
                .scheme_requirement, .use_site_only, .explicit_default, .erased_row_remainder => .{},
            };
            const contract_start: u32 = @intCast(self.evidence_param_callables.items.len);
            for (param.callable_contracts) |contract| {
                try self.evidence_param_callables.append(self.allocator, self.checked_types.rootForSourceVar(self.module, contract.fn_var) orelse
                    checkedArtifactInvariant("callable contract type was not published", .{}));
            }
            try self.evidence_params_pool.append(self.allocator, .{
                .callable_contracts = .{ .start = contract_start, .len = @intCast(param.callable_contracts.len) },
                .method = try self.names.internMethodIdent(idents, param.constraint.fn_name),
                .dispatcher_ty = self.checked_types.rootForSourceVar(self.module, param.dispatcher_var) orelse
                    checkedArtifactInvariant("checked evidence parameter dispatcher type was not published", .{}),
                .callable_ty = self.checked_types.rootForSourceVar(self.module, param.constraint.fn_var) orelse
                    checkedArtifactInvariant("checked evidence parameter callable type was not published", .{}),
                .slot = if (source == .scheme_requirement) null else self.schemeVarSlot(param.dispatcher_var),
                .structural = self.structuralKindForMethodIdent(param.constraint.fn_name),
                .source = source,
                .path = published_path,
            });
        }
        return .{ .start = pool_start, .len = @intCast(params.len) };
    }

    /// Publish the scheme path ending at `scheme_node` in canonical names,
    /// sharing the prefixes this scheme already published, and return its
    /// published last node.
    fn publishPathNode(
        self: *EvidencePass,
        path_nodes: []const static_dispatch.EvidencePathNode,
        scheme_node: u32,
    ) Allocator.Error!u32 {
        const no_node = static_dispatch.no_evidence_path_node;
        if (scheme_node == no_node) return no_node;
        const idents = self.module.identStoreConst();
        const published = self.published_path_nodes.items;
        self.published_path_chain.clearRetainingCapacity();
        var node = scheme_node;
        while (node != no_node and published[node] == no_node) {
            try self.published_path_chain.append(self.allocator, node);
            node = path_nodes[node].parent;
        }
        var parent = if (node == no_node) no_node else published[node];
        var i = self.published_path_chain.items.len;
        while (i > 0) {
            i -= 1;
            const next = self.published_path_chain.items[i];
            var converted = path_nodes[next].step;
            switch (converted.stepKind()) {
                .record_field => converted.data = @backingInt(self.names.lookupRecordFieldIdent(idents, @bitCast(converted.data)) orelse
                    checkedArtifactInvariant("an evidence path's field name was not interned with the module's names", .{})),
                .tag_payload_tag => converted.data = @backingInt(self.names.lookupTagIdent(idents, @bitCast(converted.data)) orelse
                    checkedArtifactInvariant("an evidence path's tag name was not interned with the module's names", .{})),
                .fn_arg,
                .fn_ret,
                .alias_arg,
                .alias_backing,
                .nominal_arg,
                .nominal_backing,
                .tuple_elem,
                .tag_payload_index,
                => {},
            }
            const published_node: u32 = @intCast(self.evidence_path_nodes.items.len);
            try self.evidence_path_nodes.append(self.allocator, .{ .parent = parent, .step = converted });
            published[next] = published_node;
            parent = published_node;
        }
        return published[scheme_node];
    }

    fn pathlessDefaultPhaseForParam(self: *EvidencePass, param: EvidenceParam) ?NumericDefaultPhase {
        const resolved = self.types.resolveVar(param.dispatcher_var);
        const constraints = switch (resolved.desc.content) {
            .flex => |flex| flex.constraints,
            .rigid => |rigid| rigid.constraints,
            .alias, .field_presence, .structure, .err => return null,
        };
        return numericDefaultPhaseForConstraints(self.module.moduleEnvConst(), constraints);
    }

    fn planIsDefaultRoot(self: *const EvidencePass, plan_id: static_dispatch.StaticDispatchPlanId) bool {
        const span = self.sites.defaultRefs(TemplateDispatchSites.default_plan_refs);
        for (self.templates.dispatch_plan_refs[span.start .. span.start + span.len]) |default_plan_id| {
            if (default_plan_id == plan_id) return true;
        }
        return false;
    }

    /// Whether a dispatcher reachable only through a constraint callable has a
    /// checked specialization default. Only such parameters can be synthesized
    /// at compiler-generated edges, where no checked instantiation pins them.
    fn constraintCallableHasSpecializationDefault(self: *EvidencePass, param: EvidenceParam) bool {
        if (self.pathlessDefaultPhaseForParam(param) == null) return false;
        const method = param.constraint.fn_name;
        const idents = self.module.commonIdents();
        return method == idents.plus or
            method == idents.minus or
            method == idents.times or
            method == idents.div_by or
            method == idents.div_trunc_by or
            method == idents.rem_by or
            method == idents.negate or
            method == idents.from_numeral or
            method == idents.from_quote or
            method == idents.from_interpolation;
    }

    /// How a checked plan's callable relates to the evidence slot it resolves
    /// through. Only `exact` shares the slot's callable identity; the other two
    /// own an independent callable instantiation and differ in where their
    /// nested evidence comes from.
    const CallableRelation = enum {
        exact,
        independent_per_use,
        independent_reuse_slot_nested,
    };

    /// The canonical `(depth, index)` of one method target in the chain,
    /// searching innermost-out. Independent same-name callable relations share
    /// the target slot, while their checked plans retain the per-call shape.
    fn chainParamIndex(
        self: *EvidencePass,
        chain: []const ChainLevel,
        dispatcher_root: Var,
        method: canonical.MethodNameId,
        constraint_fn_var: ?Var,
    ) Allocator.Error!?struct {
        index: static_dispatch.EvidenceChainIndex,
        callable_relation: CallableRelation,
        callable_contract: ?u32 = null,
    } {
        for (chain, 0..) |level, depth| {
            if (try self.paramIndexFor(level, dispatcher_root, method, constraint_fn_var)) |match| {
                return .{
                    .index = .{ .depth = @intCast(depth), .index = @intCast(match.index) },
                    .callable_relation = match.callable_relation,
                    .callable_contract = match.callable_contract,
                };
            }
        }
        return null;
    }

    /// Exact method-target lookup across every registry this publication can
    /// see: the local registry, then `method_lookup_views`.
    fn lookupMethodTargetAcrossViews(self: *EvidencePass, owner: static_dispatch.MethodOwner, method: canonical.MethodNameId) ?static_dispatch.CheckedMethodLookup {
        return static_dispatch.lookupCheckedMethodTarget(self.names, self.local_method_registry, self.method_lookup_views, owner, method);
    }

    /// Map a generalized VALUE decl's scheme param roots to its pattern for
    /// use-record obligation resolution (lambda-form decls are evidence
    /// scopes instead).
    fn mapValueSchemeParams(
        self: *EvidencePass,
        out: *DispatchIndex,
        pattern: CIR.Pattern.Idx,
        expr: CIR.Expr.Idx,
        scheme_params: *std.ArrayListUnmanaged(EvidenceParam),
    ) Allocator.Error!void {
        const expr_data = self.module.expr(expr).data;
        if (expr_data == .e_lambda or expr_data == .e_closure) return;
        // A procedure alias owns an exact evidence scope. Its right-hand
        // side's requirements belong to that scope, not to a representative
        // use.
        if (bindsProcedureAlias(self.module, pattern, expr)) return;
        // Resolution reaches a pattern only through one of its value-use
        // records. A decl nobody instantiated (for example a local inside a
        // generalized definition, whose variables are generalized only as
        // part of that definition's scheme) has none, so it owns nothing here.
        if (!out.value_use_record_by_pattern.contains(@backingInt(pattern))) return;
        const pattern_var = ModuleEnv.varFrom(pattern);
        if (self.types.resolveVar(pattern_var).desc.rank != .generalized) return;
        scheme_params.clearRetainingCapacity();
        try self.enumerateParams(pattern_var, scheme_params);
        for (scheme_params.items) |param| {
            const root = self.types.resolveVar(param.dispatcher_var).var_;
            const entry = try out.local_value_scheme_by_var.getOrPut(@backingInt(root));
            if (!entry.found_existing) entry.value_ptr.* = @backingInt(pattern);
        }
    }

    /// The canonical param index of one dispatch obligation.
    fn paramIndexFor(
        self: *EvidencePass,
        level: ChainLevel,
        dispatcher_root: Var,
        method: canonical.MethodNameId,
        constraint_fn_var: ?Var,
    ) Allocator.Error!?struct {
        index: u32,
        callable_relation: CallableRelation,
        callable_contract: ?u32 = null,
    } {
        const idents = self.module.identStoreConst();
        const constraint_fn_root = if (constraint_fn_var) |fn_var|
            self.types.resolveVar(fn_var).var_
        else
            null;
        const params = level.params;
        // Composite requirements are matched by their exact scheme relation
        // before structural dispatch, so the index omits them. A shared
        // receiver/method is insufficient.
        var same_method_fallback: ?u32 = null;
        for (level.by_dispatcher.forRoot(dispatcher_root)) |candidate| {
            const k = candidate.param;
            const param = params[k];
            if (try self.names.internMethodIdent(idents, param.constraint.fn_name) != method) continue;
            if (same_method_fallback == null) same_method_fallback = @intCast(k);
            if (constraint_fn_root) |fn_root| {
                if (self.types.resolveVar(param.constraint.fn_var).var_ != fn_root) {
                    for (param.callable_contracts, 0..) |contract, contract_index| {
                        if (self.types.resolveVar(contract.fn_var).var_ == fn_root) return .{
                            .index = @intCast(k),
                            .callable_relation = .independent_per_use,
                            .callable_contract = @intCast(contract_index),
                        };
                    }
                    continue;
                }
            }
            return .{ .index = @intCast(k), .callable_relation = .exact };
        }
        return if (same_method_fallback) |index|
            .{ .index = index, .callable_relation = self.fallbackCallableRelation(params[index], constraint_fn_var) }
        else
            null;
    }

    /// A same-name candidate names an independent callable. When that callable
    /// is (in one settled class with) a per-use where-method signature copy
    /// (`SchemeUseRecord.where_method_use`) whose pristine signature is the
    /// slot's own callable, the plan may reuse the slot's checked
    /// nested-evidence vector: every non-marker leaf of the copy is the
    /// signature's own variable (`Instantiator.share_leaves`). Otherwise the
    /// plan synthesizes nested evidence from its own callable.
    fn fallbackCallableRelation(self: *EvidencePass, candidate: EvidenceParam, constraint_fn_var: ?Var) CallableRelation {
        const fn_var = constraint_fn_var orelse return .independent_per_use;
        const fn_root = self.types.resolveVar(fn_var).var_;
        const record_idx = self.index.where_method_use_by_fn_var.get(@backingInt(fn_var)) orelse
            self.index.where_method_use_by_fn_root.get(fn_root) orelse
            return .independent_per_use;
        const module_env = self.module.moduleEnvConst();
        const record = module_env.scheme_uses.items.items[record_idx];
        if (record.slot_kind != @backingInt(ModuleEnv.SchemeUseRecord.Slot.where_method_use) or
            self.types.resolveVar(@as(Var, @fromBackingInt(@intCast(record.slot_data)))).var_ != fn_root)
        {
            checkedArtifactInvariant("where-method-use index named the wrong scheme-use record", .{});
        }
        const signature_root = self.types.resolveVar(@as(Var, @fromBackingInt(@intCast(record.scheme_root)))).var_;
        const pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len];
        const copied_callable = self.pairForResolved(pairs, signature_root) orelse
            checkedArtifactInvariant("where-method-use record omitted its signature callable copy", .{});
        // Either callable may be written through a transparent alias, whose
        // backing, not the alias view, is what the use relation unified.
        if (self.types.resolveThroughAliases(copied_callable).var_ != self.types.resolveThroughAliases(fn_var).var_) {
            checkedArtifactInvariant("where-method-use callable copy did not resolve to its body constraint", .{});
        }
        if (self.types.resolveVar(candidate.constraint.fn_var).var_ == signature_root) return .independent_reuse_slot_nested;
        return .independent_per_use;
    }

    fn resolvePlan(self: *EvidencePass, plan_id: static_dispatch.StaticDispatchPlanId, chain: []const ChainLevel, commit_unpinned: bool) Allocator.Error!void {
        const raw = @backingInt(plan_id);
        const plan = &self.plan_table.plans[raw];
        if (self.plan_resolved.contains(raw)) return;

        const src = self.plan_table.plan_sources[raw];
        const structural_kind: ?static_dispatch.StructuralKind = switch (plan.result_mode) {
            .value => null,
            .equality => |eq| if (eq.structural_allowed) .equality else null,
            .hash => |hash| if (hash.structural_allowed) .hash else null,
            .parser_for => |parser_for| if (parser_for.structural_allowed) .parser else null,
            .encoder_for => |encoder_for| if (encoder_for.structural_allowed) .encoder else null,
            .map => |map| if (map.structural_allowed) .map else null,
            .map_effectful => |map| if (map.structural_allowed) .map_effectful else null,
        };
        // Nested evidence built for this plan's target forwards enclosing
        // where-vars against the same chain.
        self.current_chain = chain;
        defer self.current_chain = &.{};
        const resolution: static_dispatch.CheckedCallResolution = switch (try self.resolveObligationStep(
            src.dispatcher_var,
            plan.dispatcher_ty,
            plan.method,
            structural_kind,
            src.constraint_fn_var,
            src.literal_kind,
            chain,
            commit_unpinned,
        )) {
            .resolved => |resolution| resolution orelse return,
            .node => |request| .{ .direct_pending = try self.evidenceNodeForTarget(
                request.target,
                request.dispatcher_ty,
                request.constraint_fn_var,
                null,
                if (src.target_selected_by_checking) request.selection else .publication,
            ) },
        };
        const generated_codec_derivation: ?static_dispatch.GeneratedCodecDerivationId = switch (resolution) {
            .structural => |derivation| switch (derivation.kind()) {
                .parser => self.generatedCodecDerivationForSourceConstraint(
                    src.constraint_fn_var orelse
                        checkedArtifactInvariant("structural parser plan had no source constraint", .{}),
                    .parser,
                ) orelse
                    checkedArtifactInvariant("structural parser plan had no checked generated-codec contract", .{}),
                .encoder => self.generatedCodecDerivationForSourceConstraint(
                    src.constraint_fn_var orelse
                        checkedArtifactInvariant("structural encoder plan had no source constraint", .{}),
                    .encoder,
                ) orelse
                    checkedArtifactInvariant("structural encoder plan had no checked generated-codec contract", .{}),
                .equality, .hash, .map, .map_effectful => null,
            },
            .direct_pending, .direct_closed, .direct_parametric, .evidence_dependent, .checked_error, .@"unreachable" => null,
        };
        if (builtin.mode == .debug) switch (resolution) {
            .direct_pending => |node_id| try self.verifyDirectPlanSubstitution(node_id),
            .structural, .direct_closed, .direct_parametric, .evidence_dependent, .checked_error, .@"unreachable" => {},
        };
        try self.plan_resolved.put(self.allocator, raw, {});
        try self.plan_results.append(self.allocator, .{ .plan = raw, .resolution = .{
            .resolution = resolution,
            .callable_ty = plan.callable_ty,
            .generated_codec_derivation = generated_codec_derivation,
        } });
    }

    /// A direct dispatch specializes its target under the evidence node's
    /// substitution, so that substitution must cover every quantified
    /// variable of the target's scheme, unless the node says the
    /// substitution derives from its callable.
    fn verifyDirectPlanSubstitution(self: *EvidencePass, node_id: static_dispatch.EvidenceNodeId) Allocator.Error!void {
        const node = self.evidence_nodes.items[node_id.index];
        if (node.target.kind != .procedure) return;
        const expected_len = switch (node.instantiation) {
            .derived_from_callable => 0,
            // The substitution covers the alias scope's variables, whose
            // count Monotype checks against that scope when it composes.
            .alias => return,
            .monomorphic, .callable => (try self.procedureEvidenceView(node.target)).vars.len,
        };
        if (node.subst.len != expected_len) {
            checkedArtifactInvariant("direct dispatch plan's checked substitution did not match its target's scheme", .{});
        }
    }

    fn resolveIteratorPlan(self: *EvidencePass, plan_id: static_dispatch.IteratorForPlanId, chain: []const ChainLevel, commit_unpinned: bool) Allocator.Error!void {
        const raw = @backingInt(plan_id);
        const plan = &self.plan_table.iterator_for_plans[raw];
        if (self.iterator_plan_resolved.contains(raw)) return;

        const src = self.plan_table.iterator_plan_sources[raw];
        self.current_chain = chain;
        defer self.current_chain = &.{};
        const iter = (try self.resolveObligation(
            src.iter_dispatcher_var,
            plan.iter.dispatcher_ty,
            plan.iter.method,
            null,
            src.iter_fn_var,
            null,
            chain,
            commit_unpinned,
        )) orelse return;
        const next = (try self.resolveObligation(
            src.next_dispatcher_var,
            plan.next.dispatcher_ty,
            plan.next.method,
            null,
            src.next_fn_var,
            null,
            chain,
            commit_unpinned,
        )) orelse return;
        try self.iterator_plan_resolved.put(self.allocator, raw, {});
        try self.iterator_results.append(self.allocator, .{ .plan = raw, .resolution = .{
            .iter = iter,
            .iter_callable_ty = plan.iter.callable_ty,
            .next = next,
            .next_callable_ty = plan.next.callable_ty,
        } });
    }

    /// Resolve one dispatch obligation: `method` dispatched on
    /// `dispatcher_var`, with `constraint_fn_var` keying the discharge record
    /// that carries the chosen target's own nested obligations.
    /// Resolve one dispatch obligation. With `commit_unpinned = false`
    /// (template walks), an obligation the given chain does not bind returns
    /// null so a template whose scheme DOES bind it (template plan-ref spans
    /// can overlap) or the final chain-free sweep resolves it instead. With
    /// `commit_unpinned = true` the result is total.
    fn resolveObligation(
        self: *EvidencePass,
        dispatcher_var: Var,
        dispatcher_ty: CheckedTypeId,
        method: canonical.MethodNameId,
        structural_kind: ?static_dispatch.StructuralKind,
        constraint_fn_var: ?Var,
        literal_kind: ?LiteralKind,
        chain: []const ChainLevel,
        commit_unpinned: bool,
    ) Allocator.Error!?static_dispatch.CheckedCallResolution {
        return switch (try self.resolveObligationStep(dispatcher_var, dispatcher_ty, method, structural_kind, constraint_fn_var, literal_kind, chain, commit_unpinned)) {
            .resolved => |resolution| resolution,
            .node => |request| .{ .direct_pending = try self.evidenceNodeForTarget(request.target, request.dispatcher_ty, request.constraint_fn_var, null, request.selection) },
        };
    }

    /// A procedure target whose evidence node the obligation resolves to.
    const EvidenceNodeRequest = struct {
        target: static_dispatch.MethodTarget,
        dispatcher_ty: ?CheckedTypeId,
        constraint_fn_var: ?Var,
        selection: MethodTargetSelection,
    };

    /// An obligation's resolution, or the procedure target whose evidence
    /// node is its direct resolution. The node is built by the caller, so a
    /// target's nested evidence never nests native calls.
    const ObligationStep = union(enum) {
        resolved: ?static_dispatch.CheckedCallResolution,
        node: EvidenceNodeRequest,
    };

    fn resolveObligationStep(
        self: *EvidencePass,
        dispatcher_var_in: Var,
        dispatcher_ty_in: CheckedTypeId,
        method: canonical.MethodNameId,
        structural_kind: ?static_dispatch.StructuralKind,
        constraint_fn_var_in: ?Var,
        literal_kind: ?LiteralKind,
        chain: []const ChainLevel,
        commit_unpinned_in: bool,
    ) Allocator.Error!ObligationStep {
        var dispatcher_var = dispatcher_var_in;
        var dispatcher_ty = dispatcher_ty_in;
        var constraint_fn_var = constraint_fn_var_in;
        var commit_unpinned = commit_unpinned_in;
        // A generalized value's use redirects resolution to the type that use
        // instantiated, which can itself redirect.
        redirect: while (true) {
            if (constraint_fn_var) |fn_var| {
                if (self.types.varStaticDispatchRejected(fn_var)) return .{ .resolved = .checked_error };
            }

            const resolved = self.types.resolveVar(dispatcher_var);
            // A structural receiver may still own a generic codec requirement.
            // Its exact scheme relation takes precedence over its current shape.
            if (structural_kind == .parser or structural_kind == .encoder) if (constraint_fn_var) |fn_var| {
                for (chain, 0..) |level, depth| {
                    for (level.params, 0..) |param, index| {
                        if (param.source != .scheme_requirement) continue;
                        if (self.types.resolveVar(param.constraint.fn_var).var_ != self.types.resolveVar(fn_var).var_) continue;
                        if (try self.names.internMethodIdent(self.module.identStoreConst(), param.constraint.fn_name) != method) continue;
                        return .{ .resolved = .{ .evidence_dependent = .{
                            .scheme_param = .{
                                .scheme = level.scheme orelse checkedArtifactInvariant("forwarded scheme requirement was not published", .{}),
                                .index = param.published_index orelse checkedArtifactInvariant("forwarded scheme requirement was not published", .{}),
                            },
                            .index = .{ .depth = @intCast(depth), .index = @intCast(index) },
                            .independent_callable = false,
                        } } };
                    }
                }
            };

            // Builtin containers have ordinary registry methods for parser_for and
            // encoder_for, but checking can deliberately discharge an obligation
            // through the generated structural codec path instead. Preserve that
            // exact producer decision: the derivation records the original
            // constraint-function variable that selected it.
            if (structural_kind) |kind| {
                const derivation_kind: ?static_dispatch.GeneratedCodecDerivationKind = switch (kind) {
                    .parser => .parser,
                    .encoder => .encoder,
                    .equality, .hash, .map, .map_effectful => null,
                };
                if (derivation_kind) |expected_kind| {
                    if (constraint_fn_var) |fn_var| {
                        if (self.generatedCodecDerivationForSourceConstraint(fn_var, expected_kind) != null) {
                            return .{ .resolved = .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) } };
                        }
                    }
                }
            }

            // A generalized VALUE decl's scheme param may LOOK concrete here:
            // compile-time finalization defaults the pristine var (e.g. to Dec)
            // after uses were instantiated. The uses are the truth—they carry
            // the type each inline lowering actually runs at—so resolve through
            // a representative use record before trusting the var's content.
            if (self.index.local_value_scheme_by_var.get(@backingInt(resolved.var_))) |pattern_raw| {
                if (self.index.value_use_record_by_pattern.get(pattern_raw)) |record_idx| {
                    const module_env = self.module.moduleEnvConst();
                    const record = module_env.scheme_uses.items.items[record_idx];
                    const pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len];
                    if (self.pairForResolved(pairs, resolved.var_)) |fresh| {
                        if (self.types.resolveVar(fresh).var_ != resolved.var_) {
                            const fresh_fn: ?Var = if (constraint_fn_var) |fn_var| self.pairForResolved(pairs, self.types.resolveVar(fn_var).var_) else null;
                            const fresh_dispatcher_ty = self.checked_types.rootForSourceVar(self.module, fresh) orelse
                                checkedArtifactInvariant("checked dispatch use instantiation type was not published", .{});
                            dispatcher_var = fresh;
                            dispatcher_ty = fresh_dispatcher_ty;
                            constraint_fn_var = fresh_fn orelse constraint_fn_var;
                            commit_unpinned = true;
                            continue :redirect;
                        }
                    }
                }
            }

            switch (resolved.desc.content) {
                // A different checker diagnostic can poison the value that owns
                // this receiver after the dispatch itself checked successfully.
                // The explicit rejection map above remains the sole authority for
                // dispatch-specific failures; `.err` is the separate value-error
                // fence and must never be inferred from the callable or its return.
                // A presence variable is not a dispatch target and carries no
                // obligations—treat it as inert like `.err`.
                .err, .field_presence => return .{ .resolved = .checked_error },
                .flex => |flex| {
                    if (self.at_template_root) {
                        if (try self.rootDefaultObligation(flex.constraints, dispatcher_ty, method, structural_kind, constraint_fn_var)) |step| return step;
                    }
                    return self.resolveVarObligation(resolved.var_, method, structural_kind, constraint_fn_var, chain, commit_unpinned);
                },
                .rigid => return self.resolveVarObligation(resolved.var_, method, structural_kind, constraint_fn_var, chain, commit_unpinned),
                // A transparent alias dispatches exactly as its backing does
                // (design.md "Type Alias Invariant"), including a backing that
                // is a where-constrained variable. `dispatcher_ty` stays the
                // alias root, which is a transparent view of that backing.
                .alias => |alias| {
                    dispatcher_var = self.types.getAliasBackingVar(alias);
                    continue :redirect;
                },
                .structure => {
                    if (try self.methodOwnerForSourceContent(resolved.var_)) |owner| {
                        if (self.lookupMethodTargetAcrossViews(owner, method)) |found| {
                            return switch (found) {
                                // The method is declared, but canonicalization or
                                // checking rejected its declaration and already
                                // reported why. The dispatch itself needs no second
                                // diagnostic; it just must never lower.
                                .rejected => .{ .resolved = .checked_error },
                                .target => |target| try self.resolutionForMethodTarget(
                                    target,
                                    structural_kind,
                                    dispatcher_ty,
                                    constraint_fn_var,
                                    if (literal_kind != null and isBuiltinLiteralConversion(literal_kind.?, owner)) .builtin_literal else .dispatch_edge,
                                ),
                            };
                        }
                        // The dispatcher has an owner, checking passed, and no
                        // registry-visible view declares the method: the checker
                        // discharged the obligation with the derived structural
                        // implementation. Value dispatches cannot discharge
                        // structurally, so a miss there is a publication bug
                        // (every view the checker resolved against is searched
                        // above).
                        if (structural_kind) |kind| return .{ .resolved = .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) } };
                        base.invariant("publication could not resolve a checked dispatch target for an owned method", .{});
                    }
                    // No owner head: a genuinely structural shape.
                    if (structural_kind) |kind| return .{ .resolved = .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) } };
                    checkedArtifactInvariant("ownerless non-structural dispatch reached publication without an explicit rejection", .{});
                },
            }
        }
    }

    /// The callable a generated codec relation's derivation was validated at.
    fn codecRelationCallable(self: *EvidencePass, constraint_fn_var: Var) Var {
        return self.index.codec_instance_by_template.get(self.types.resolveVar(constraint_fn_var).var_) orelse constraint_fn_var;
    }

    fn generatedCodecDerivationForSourceConstraint(
        self: *EvidencePass,
        constraint_fn_var: Var,
        expected_kind: static_dispatch.GeneratedCodecDerivationKind,
    ) ?static_dispatch.GeneratedCodecDerivationId {
        const by_kind = self.index.generated_codec_by_source.getPtrConst(self.codecRelationCallable(constraint_fn_var)) orelse return null;
        return by_kind.get(expected_kind);
    }

    /// A template running as a root has no caller to pin the variables of its
    /// scheme, so a dispatcher its literals constrain takes those literals'
    /// default owner: Dec for numerals and defaultable arithmetic, Str for
    /// quotes and interpolations.
    fn rootDefaultObligation(
        self: *EvidencePass,
        constraints: types.StaticDispatchConstraint.SafeList.Range,
        dispatcher_ty: CheckedTypeId,
        method: canonical.MethodNameId,
        structural_kind: ?static_dispatch.StructuralKind,
        constraint_fn_var: ?Var,
    ) Allocator.Error!?ObligationStep {
        const owner: static_dispatch.MethodOwner = switch (numericDefaultPhaseForConstraints(self.module.moduleEnvConst(), constraints) orelse return null) {
            .mono_specialization => .{ .builtin = .dec },
            .mono_specialization_str => .{ .builtin = .str },
            // `checking_finalized` is stamped only on vars checking already
            // resolved; an unresolved one cannot carry it.
            .checking_finalized => return .{ .resolved = .checked_error },
        };
        return switch (self.lookupMethodTargetAcrossViews(owner, method) orelse return null) {
            .rejected => .{ .resolved = .checked_error },
            .target => |target| try self.resolutionForMethodTarget(target, structural_kind, dispatcher_ty, constraint_fn_var, .publication),
        };
    }

    fn resolveVarObligation(
        self: *EvidencePass,
        dispatcher_root: Var,
        method: canonical.MethodNameId,
        structural_kind: ?static_dispatch.StructuralKind,
        constraint_fn_var: ?Var,
        chain: []const ChainLevel,
        commit_unpinned: bool,
    ) Allocator.Error!ObligationStep {
        if (try self.chainParamIndex(chain, dispatcher_root, method, constraint_fn_var)) |match| {
            const independent_callable = match.callable_relation != .exact;
            const level = chain[match.index.depth];
            const owner = level.params[match.index.index].published_index orelse
                checkedArtifactInvariant("forwarded evidence owner was not published", .{});
            const schema = level.published[owner];
            return .{ .resolved = .{ .evidence_dependent = .{
                .scheme_param = if (match.callable_contract != null or
                    schema.source != .scheme_callable) .{
                    .scheme = level.scheme orelse checkedArtifactInvariant("forwarded evidence owner was not published", .{}),
                    .index = owner,
                } else null,
                .index = match.index,
                .independent_callable = independent_callable,
                .reuse_slot_nested_evidence = match.callable_relation == .independent_reuse_slot_nested,
                .callable_contract = match.callable_contract,
            } } };
        }

        // Not bound by this chain. During template walks another template's
        // scheme may bind it (plan-ref spans can overlap); only the final
        // sweep commits unpinned classifications.
        if (!commit_unpinned) return .{ .resolved = null };

        // Not an evidence param of any enclosing callable, so no edge pins
        // it, and checking resolved no default for it: a dispatcher checking
        // defaults is unified with its default owner before publication
        // (`flexConstraintCompatibility`), after validating the owner's
        // method against the dispatch's callable. A still-flex dispatcher
        // here is one no value ever reaches (a parameter of a function value
        // nothing calls), so its dispatch is unreachable rather than a call
        // of a default owner's method, whose signature nothing validated
        // against the callable: such a call would lower with operands the
        // method does not take.
        // Generated codecs require the explicit checker snapshot handled
        // above; without one, the unpinned-dispatch rule decides.
        return .{ .resolved = switch (static_dispatch.unpinnedDispatchResolution(structural_kind)) {
            .structural => .{ .structural = try self.structuralDerivation(structural_kind.?, constraint_fn_var) },
            .unreachable_value => .@"unreachable",
        } };
    }

    fn structuralDerivation(
        self: *EvidencePass,
        kind: static_dispatch.StructuralKind,
        constraint_fn_var: ?Var,
    ) Allocator.Error!static_dispatch.StructuralDerivation {
        return switch (kind) {
            .equality => .equality,
            .hash => .hash,
            .parser => .parser,
            .encoder => .encoder,
            .map, .map_effectful => blk: {
                const fn_var = constraint_fn_var orelse checkedArtifactInvariant("derived map evidence had no constraint function", .{});
                const plan = self.types.derivedMapPlan(fn_var) orelse checkedArtifactInvariant("derived map evidence had no checked payload selection", .{});
                const canonical_plan = static_dispatch.DerivedMapPlan{
                    .tag = self.names.lookupTagIdent(self.module.identStoreConst(), plan.tag_name) orelse checkedArtifactInvariant("a structural tag name was not interned with the module names", .{}),
                    .payload_index = plan.payload_index,
                };
                break :blk if (kind == .map)
                    .{ .map = canonical_plan }
                else
                    .{ .map_effectful = canonical_plan };
            },
        };
    }

    /// The method owner of a settled source var, walking alias content
    /// transparently (the source-var analog of monotype lowering's
    /// dispatch-head read of published type identity).
    fn methodOwnerForSourceContent(self: *EvidencePass, var_: Var) Allocator.Error!?static_dispatch.MethodOwner {
        var current = var_;
        var remaining: u64 = self.types.len();
        while (true) {
            const resolved = self.types.resolveVar(current);
            switch (resolved.desc.content) {
                .alias => |alias| {
                    if (remaining == 0) {
                        checkedArtifactInvariant("checked evidence source alias chain was cyclic", .{});
                    }
                    remaining -= 1;
                    current = self.types.getAliasBackingVar(alias);
                },
                .structure => |flat_type| switch (flat_type) {
                    .nominal_type => |nominal| {
                        if (categorizeBuiltinNominal(self.module, self.import_views, nominal)) |builtin_nominal| {
                            if (builtin_nominal == .try_) {
                                const module_identity_id = self.names.lookupModuleIdentity(self.module.moduleEnvConst().moduleIdentityHash(nominal.origin_module)) orelse checkedArtifactInvariant("a dispatcher origin module was not interned with the module names", .{});
                                return .{ .nominal = .{
                                    .module = module_identity_id,
                                    .source_decl = nominal.statement(),
                                } };
                            }
                            return .{ .builtin = static_dispatch.builtinOwnerForCheckedBuiltin(builtin_nominal) };
                        }
                        const module_identity_id = self.names.lookupModuleIdentity(self.module.moduleEnvConst().moduleIdentityHash(nominal.origin_module)) orelse checkedArtifactInvariant("a dispatcher origin module was not interned with the module names", .{});
                        return .{ .nominal = .{
                            .module = module_identity_id,
                            .source_decl = nominal.statement(),
                        } };
                    },
                    .record,
                    .tuple,
                    .fn_pure,
                    .fn_effectful,
                    .fn_unbound,
                    .empty_record,
                    .tag_union,
                    .empty_tag_union,
                    => return null,
                },
                .flex, .rigid, .field_presence, .err => return null,
            }
        }
    }

    /// Inspection's use of each override is a dispatch-target edge whose
    /// instantiation checking recorded (design.md "Inspect Overrides"). The
    /// edge's evidence supplies the method's requirements at `T -> Str`.
    /// Preserve the checked registry's semantic resolution. Compiler-derived
    /// structural declarations are evidence themselves and must never enter a
    /// callable target's evidence-node graph.
    fn resolutionForMethodTarget(
        self: *EvidencePass,
        target: static_dispatch.MethodTarget,
        structural_kind: ?static_dispatch.StructuralKind,
        dispatcher_ty: ?CheckedTypeId,
        constraint_fn_var: ?Var,
        selection: MethodTargetSelection,
    ) Allocator.Error!ObligationStep {
        return switch (target.kind) {
            .structural => |kind| blk: {
                if (structural_kind == null or structural_kind.? != kind) {
                    checkedArtifactInvariant("structural method registry result did not match the checked dispatch result mode", .{});
                }
                break :blk .{ .resolved = .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) } };
            },
            .procedure, .local_proc => .{ .node = .{
                .target = target,
                .dispatcher_ty = dispatcher_ty,
                .constraint_fn_var = constraint_fn_var,
                .selection = selection,
            } },
        };
    }

    const ProcedureEvidenceSchema = static_dispatch.ProcedureEvidenceSchema;

    /// The schema of a procedure target's template, in the module that
    /// declares it.
    fn procedureEvidenceView(self: *EvidencePass, target: static_dispatch.MethodTarget) Allocator.Error!SchemaView {
        const procedure = switch (target.kind) {
            .procedure => |procedure| procedure,
            .local_proc, .structural => checkedArtifactInvariant("procedure evidence view requested for a non-procedure target", .{}),
        };
        const target_key = procedure.template.artifact;
        if (target_key.eql(self.import_views.current_owner)) {
            return try self.dispatch.templateSchema(procedure.template.template);
        }
        const view = self.import_views.viewForKey(target_key) orelse
            checkedArtifactInvariant("procedure evidence target module was not among the modules dispatch resolution reads", .{});
        return try view.dispatch().templateSchema(procedure.template.template);
    }

    /// Whether every evidence parameter of a procedure target is fixed by its
    /// concrete callable relation: either projected from the callable or
    /// reached through the callable of another requirement, which Monotype's
    /// substitution-derived fixpoint binds once that requirement's target is
    /// selected.
    fn procedureEvidenceDerivesFromCallable(self: *EvidencePass, target: static_dispatch.MethodTarget) Allocator.Error!bool {
        for ((try self.procedureEvidenceView(target)).params) |param| {
            switch (param.source) {
                .scheme_callable => if (param.path.len == 0) return false,
                .constraint_callable, .use_site_only => {},
                .scheme_requirement, .explicit_default, .erased_row_remainder => return false,
            }
        }
        return true;
    }

    fn procedureEvidenceSchema(self: *EvidencePass, target: static_dispatch.MethodTarget) Allocator.Error!ProcedureEvidenceSchema {
        return static_dispatch.procedureEvidenceSchema((try self.procedureEvidenceView(target)).params);
    }

    /// Build the evidence node for `target`. A checker-recorded dispatch-target
    /// record is the exact evidence selected at the discharge edge; compiler-
    /// generated edges that have no record derive evidence from the target
    /// schema and concrete callable relation. Generated codec publication
    /// supplies the frozen contract callable identity explicitly; its source
    /// variable remains only the durable key for any recorded nested evidence.
    /// How a method target was selected, which decides whether a checked
    /// instantiation record must exist for it. A `dispatch_edge` target was
    /// chosen by resolving a static-dispatch constraint, and that resolution
    /// records the instantiation it performed. A `derivation` target was
    /// chosen by a generated codec deriving over a type's fields: there is no
    /// dispatch edge behind it, so no such record was ever written. A
    /// `publication` target was chosen by publication rather than checking:
    /// the numeric default owner of a dispatcher no edge pins, or the target
    /// of a literal conversion checking left to each specialization.
    /// A `builtin_literal` target converts a source literal on a builtin
    /// number or `Str`, which checking discharges as a primitive with no
    /// callable instantiation.
    const MethodTargetSelection = enum { dispatch_edge, derivation, publication, builtin_literal };

    const LiteralKind = types.StaticDispatchConstraint.LiteralKind;

    /// Checking's primitive literal rule: a numeral converts natively to a
    /// builtin number, and a quote or interpolation to `Str`.
    fn isBuiltinLiteralConversion(kind: LiteralKind, owner: static_dispatch.MethodOwner) bool {
        const builtin_owner = switch (owner) {
            .builtin => |builtin_owner| builtin_owner,
            .nominal => return false,
        };
        return switch (kind) {
            .numeral => switch (builtin_owner) {
                .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => true,
                .list,
                .box,
                .dict,
                .set,
                .fields,
                .field,
                .bool,
                .str,
                .u8x16,
                .i8x16,
                .u16x8,
                .i16x8,
                .u32x4,
                .i32x4,
                .u64x2,
                .i64x2,
                .parse_tag_union_spec,
                .crypto_sha256_digest,
                .crypto_sha256_hasher,
                .crypto_blake3_digest,
                .crypto_blake3_hasher,
                .iter,
                .stream,
                => false,
            },
            .quote, .interpolation => builtin_owner == .str,
        };
    }

    fn evidenceNodeForTarget(
        self: *EvidencePass,
        target: static_dispatch.MethodTarget,
        dispatcher_ty: ?CheckedTypeId,
        constraint_fn_var: ?Var,
        contract: ?ContractCallable,
        selection: MethodTargetSelection,
    ) Allocator.Error!static_dispatch.EvidenceNodeId {
        var frames = std.ArrayList(EvidenceRecordFrame).empty;
        defer {
            for (frames.items) |*frame| {
                _ = self.record_in_progress.remove(frame.record_idx);
                frame.deinit(self.allocator);
            }
            frames.deinit(self.allocator);
        }
        switch (try self.beginEvidenceNode(target, dispatcher_ty, constraint_fn_var, contract, selection)) {
            .done => |node_id| return node_id,
            .record => |frame| try frames.append(self.allocator, frame),
        }
        // The node of a nested target that just finished, for the pending
        // parameter of the frame below it.
        var delivered: ?static_dispatch.EvidenceNodeId = null;
        while (true) {
            const top = frames.items.len - 1;
            const frame = &frames.items[top];
            if (delivered) |node_id| {
                frame.entries.appendAssumeCapacity(self.evidenceFromResolution(frame.pending, .{ .direct_pending = node_id }));
                delivered = null;
            }
            if (frame.next < frame.params.items.len) {
                const param = frame.params.items[frame.next];
                frame.next += 1;
                const context = try self.evidenceContextForRecordParam(frame.pairs, param);
                switch (try self.resolveObligationStep(context.var_, context.dispatcher_ty, context.method, context.structural_kind, context.fresh_fn_var, context.literal_kind, self.current_chain, true)) {
                    .resolved => |resolution| frame.entries.appendAssumeCapacity(self.evidenceFromResolution(context, resolution orelse
                        checkedArtifactInvariant("committed evidence resolution was not total", .{}))),
                    .node => |request| switch (try self.beginEvidenceNode(request.target, request.dispatcher_ty, request.constraint_fn_var, null, request.selection)) {
                        .done => |node_id| frame.entries.appendAssumeCapacity(self.evidenceFromResolution(context, .{ .direct_pending = node_id })),
                        .record => |nested| {
                            frame.pending = context;
                            try frames.append(self.allocator, nested);
                        },
                    },
                }
                continue;
            }
            var finished = frames.pop().?;
            defer finished.deinit(self.allocator);
            const node_id = self.finishEvidenceNode(&finished) catch |err| {
                _ = self.record_in_progress.remove(finished.record_idx);
                return err;
            };
            if (frames.items.len == 0) return node_id;
            delivered = node_id;
        }
    }

    /// A target's evidence node whose recorded nested evidence is still being
    /// resolved, one parameter of the scheme-use record at a time. The record
    /// stays in progress until the node is interned.
    const EvidenceRecordFrame = struct {
        record_idx: u32,
        target: static_dispatch.MethodTarget,
        dispatcher_ty: ?CheckedTypeId,
        callable_ty: CheckedTypeId,
        procedure_schema: ?ProcedureEvidenceSchema,
        scheme_root: Var,
        pairs: []const ModuleEnv.SchemeUsePair,
        /// The renaming a generated codec contract's callable carries.
        renamings: []const ModuleEnv.GeneratedCodecRenaming,
        params: std.ArrayListUnmanaged(EvidenceParam) = .empty,
        entries: std.ArrayListUnmanaged(static_dispatch.CheckedEvidence) = .empty,
        next: usize = 0,
        /// The parameter whose target node the frame above is building.
        pending: EvidenceContext = undefined,

        fn deinit(frame: *EvidenceRecordFrame, allocator: Allocator) void {
            frame.params.deinit(allocator);
            frame.entries.deinit(allocator);
        }
    };

    /// The callable a generated codec contract names for one of its calls,
    /// with the renaming the contract's snapshot applied. The call's recorded
    /// substitution names the originals of the types the snapshot renamed.
    const ContractCallable = struct {
        callable_ty: CheckedTypeId,
        renamings: []const ModuleEnv.GeneratedCodecRenaming,
    };

    const EvidenceNodeStart = union(enum) {
        done: static_dispatch.EvidenceNodeId,
        /// The target's recorded nested evidence must be resolved first.
        record: EvidenceRecordFrame,
    };

    fn finishEvidenceNode(self: *EvidencePass, frame: *const EvidenceRecordFrame) Allocator.Error!static_dispatch.EvidenceNodeId {
        const nested: RecordSiteSpans = .{
            .refs = try self.appendEvidenceRefs(frame.entries.items),
            .subst = try self.appendSiteSubstitution(frame.scheme_root, frame.pairs, frame.renamings),
        };
        const through_alias = frame.target.alias != null;
        if (!through_alias and (frame.procedure_schema == .requires_record or frame.procedure_schema == .from_target)) {
            if (nested.refs.len != (try self.procedureEvidenceView(frame.target)).params.len) {
                checkedArtifactInvariant("recorded procedure target evidence length differed from its declared params", .{});
            }
        }
        const node_id = try self.internEvidenceNode(.{
            .target = frame.target,
            .dispatcher_ty = frame.dispatcher_ty,
            .generated_codec_derivation = null,
            .instantiation = if (through_alias) .{ .alias = frame.callable_ty } else .{ .callable = frame.callable_ty },
            .nested = if (through_alias) .{ .through_alias = nested.refs } else .{ .resolved = nested.refs },
            .subst = nested.subst,
        });
        try self.node_by_record.put(frame.record_idx, node_id);
        _ = self.record_in_progress.remove(frame.record_idx);
        return node_id;
    }

    fn beginEvidenceNode(
        self: *EvidencePass,
        target: static_dispatch.MethodTarget,
        dispatcher_ty: ?CheckedTypeId,
        constraint_fn_var: ?Var,
        contract: ?ContractCallable,
        selection: MethodTargetSelection,
    ) Allocator.Error!EvidenceNodeStart {
        if (target.kind == .structural) {
            checkedArtifactInvariant("structural method registry result reached the callable evidence-node graph", .{});
        }
        const renamings: []const ModuleEnv.GeneratedCodecRenaming = if (contract) |named| named.renamings else &.{};
        const callable_ty = if (contract) |named| named.callable_ty else if (constraint_fn_var) |fn_var|
            self.checked_types.rootForSourceVar(self.module, fn_var) orelse
                checkedArtifactInvariant("checked direct evidence callable type was not published", .{})
        else
            null;
        const record_idx: ?u32 = if (constraint_fn_var) |fn_var|
            self.index.target_by_fn_var.get(@backingInt(fn_var))
        else
            null;
        const generated_codec_derivation: ?static_dispatch.GeneratedCodecDerivationId = null;

        const procedure_schema: ?ProcedureEvidenceSchema = switch (target.kind) {
            .procedure => try self.procedureEvidenceSchema(target),
            .local_proc, .structural => null,
        };
        if (target.alias != null) {
            // The dispatch edge instantiated the alias's scheme, whose
            // requirements are not the target's. Its record substitutes the
            // alias scope's variables and resolves the alias's obligations;
            // the target's substitution and evidence compose through the
            // alias's forwarded lookup. An edge with no record instantiated
            // an alias scheme with no variables, and so no obligations.
            const callable = callable_ty orelse
                checkedArtifactInvariant("method target reached through an alias had no checked callable", .{});
            if (record_idx == null) {
                return .{ .done = try self.internEvidenceNode(.{
                    .target = target,
                    .dispatcher_ty = dispatcher_ty,
                    .generated_codec_derivation = generated_codec_derivation,
                    .instantiation = .{ .alias = callable },
                    .nested = .{ .through_alias = .{} },
                }) };
            }
        }
        if (record_idx) |idx| {
            const record = self.module.moduleEnvConst().scheme_uses.items.items[idx];
            if (target.alias == null and record.slot_kind == @backingInt(ModuleEnv.SchemeUseRecord.Slot.recursive_dispatch_target)) {
                // The checker closed an exact concrete backedge and proved
                // every requirement is determined by the target's callable,
                // directly or through the callables of determined
                // requirements. Publish its finite recipe instead of
                // expanding it again.
                if (target.kind == .procedure and !try self.procedureEvidenceDerivesFromCallable(target)) {
                    checkedArtifactInvariant("recursive dispatch target did not have callable-derived evidence", .{});
                }
                return .{ .done = try self.internEvidenceNode(.{
                    .target = target,
                    .dispatcher_ty = dispatcher_ty,
                    .generated_codec_derivation = generated_codec_derivation,
                    .instantiation = .{ .callable = callable_ty.? },
                    .nested = if (procedure_schema == .none) .{ .resolved = .{} } else .from_callable,
                }) };
            }
            if (self.node_by_record.get(idx)) |memoized| {
                const existing = self.evidence_nodes.items[memoized.index];
                const checked_view = self.checked_types.store.view();
                const callable_matches = switch (existing.instantiation) {
                    .monomorphic, .derived_from_callable => false,
                    .callable => |existing_callable| target.alias == null and try checked_view.sameType(existing_callable, callable_ty.?),
                    .alias => |existing_callable| target.alias != null and try checked_view.sameType(existing_callable, callable_ty.?),
                };
                const dispatcher_matches = if (existing.dispatcher_ty) |existing_dispatcher|
                    if (dispatcher_ty) |requested| try checked_view.sameType(existing_dispatcher, requested) else false
                else
                    dispatcher_ty == null;
                if (!dispatcher_matches or
                    existing.generated_codec_derivation != generated_codec_derivation or
                    !callable_matches)
                {
                    checkedArtifactInvariant("one checked dispatch evidence record resolved at two checked call identities", .{});
                }
                return .{ .done = memoized };
            }
            if ((try self.record_in_progress.getOrPut(idx)).found_existing) {
                checkedArtifactInvariant("checked dispatch evidence chain was cyclic", .{});
            }
            errdefer _ = self.record_in_progress.remove(idx);

            const module_env = self.module.moduleEnvConst();
            if (record.slot_kind == @backingInt(ModuleEnv.SchemeUseRecord.Slot.where_method_use)) {
                checkedArtifactInvariant("where-method callable relation reached scheme-use evidence emission", .{});
            }
            var frame: EvidenceRecordFrame = .{
                .record_idx = idx,
                .target = target,
                .dispatcher_ty = dispatcher_ty,
                .callable_ty = callable_ty.?,
                .procedure_schema = procedure_schema,
                .scheme_root = @fromBackingInt(@intCast(record.scheme_root)),
                .pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len],
                .renamings = renamings,
            };
            errdefer frame.deinit(self.allocator);
            try self.enumerateParams(frame.scheme_root, &frame.params);
            try frame.entries.ensureTotalCapacity(self.allocator, frame.params.items.len);
            return .{ .record = frame };
        }

        // Without a record this node carries no substitution. A dispatch edge
        // the checker discharged records one whenever the target's scheme has
        // variables; a target publication selected was never instantiated by
        // checking, so its node says the substitution derives from the
        // callable.
        if (target.kind == .procedure and constraint_fn_var != null and selection == .dispatch_edge and
            (try self.procedureEvidenceView(target)).vars.len != 0)
        {
            checkedArtifactInvariant("polymorphic procedure target evidence had no checked instantiation record", .{});
        }
        const instantiation: static_dispatch.EvidenceTargetInstantiation = switch (selection) {
            .publication, .builtin_literal => .{ .derived_from_callable = callable_ty orelse
                checkedArtifactInvariant("target evidence checking never instantiated had no checked callable", .{}) },
            .dispatch_edge, .derivation => if (callable_ty) |callable| .{ .callable = callable } else .monomorphic,
        };

        if (procedure_schema == .from_callable) {
            if (constraint_fn_var == null) {
                checkedArtifactInvariant("callable-derived procedure evidence had no checked callable relation", .{});
            }
            return .{ .done = try self.internEvidenceNode(.{
                .target = target,
                .dispatcher_ty = dispatcher_ty,
                .generated_codec_derivation = generated_codec_derivation,
                .instantiation = instantiation,
                .nested = .from_callable,
            }) };
        }

        if (procedure_schema == .requires_record or procedure_schema == .from_target) {
            checkedArtifactInvariant("pathless procedure target evidence had no checked instantiation record", .{});
        }
        if (target.kind == .local_proc and constraint_fn_var != null and selection == .dispatch_edge) {
            checkedArtifactInvariant("constrained local-procedure target evidence had no checked instantiation record", .{});
        }

        return .{ .done = try self.internEvidenceNode(.{
            .target = target,
            .dispatcher_ty = dispatcher_ty,
            .generated_codec_derivation = generated_codec_derivation,
            .instantiation = instantiation,
            .nested = .{ .resolved = .{} },
        }) };
    }

    fn internEvidenceNode(
        self: *EvidencePass,
        candidate: static_dispatch.EvidenceNode,
    ) Allocator.Error!static_dispatch.EvidenceNodeId {
        // Bucket selector only; `evidenceNodesEql` decides identity, so a
        // collision costs one extra chain step.
        var hasher = std.hash.Wyhash.init(0);
        std.hash.autoHash(&hasher, candidate.target);
        std.hash.autoHash(&hasher, candidate.dispatcher_ty);
        std.hash.autoHash(&hasher, candidate.generated_codec_derivation);
        std.hash.autoHash(&hasher, candidate.instantiation);
        for (self.site_substitutions.items[candidate.subst.start .. candidate.subst.start + candidate.subst.len]) |ty| {
            std.hash.autoHash(&hasher, ty);
        }
        switch (candidate.nested) {
            .from_callable => std.hash.autoHash(&hasher, @as(u8, 0)),
            .resolved, .through_alias => |span| {
                std.hash.autoHash(&hasher, @as(u8, if (candidate.nested == .resolved) 1 else 2));
                const refs = self.evidence_refs.items[span.start .. span.start + span.len];
                std.hash.autoHash(&hasher, refs.len);
                for (refs) |ref| std.hash.autoHash(&hasher, ref);
            },
        }
        const hash = hasher.final();
        var existing = self.evidence_node_buckets.get(hash);
        while (existing) |index| {
            if (self.evidenceNodesEql(self.evidence_nodes.items[index], candidate)) {
                return .{ .index = index, .owner = self.owner };
            }
            existing = self.evidence_node_next.items[index];
        }

        const index: u32 = @intCast(self.evidence_nodes.items.len);
        const node_id: static_dispatch.EvidenceNodeId = .{ .index = index, .owner = self.owner };
        try self.evidence_nodes.append(self.allocator, candidate);
        try self.evidence_node_next.append(self.allocator, self.evidence_node_buckets.get(hash));
        try self.evidence_node_buckets.put(hash, index);
        return node_id;
    }

    fn evidenceNodesEql(
        self: *const EvidencePass,
        left: static_dispatch.EvidenceNode,
        right: static_dispatch.EvidenceNode,
    ) bool {
        if (!std.meta.eql(left.target, right.target) or
            left.dispatcher_ty != right.dispatcher_ty or
            left.generated_codec_derivation != right.generated_codec_derivation or
            !std.meta.eql(left.instantiation, right.instantiation)) return false;
        const left_subst = self.site_substitutions.items[left.subst.start .. left.subst.start + left.subst.len];
        const right_subst = self.site_substitutions.items[right.subst.start .. right.subst.start + right.subst.len];
        if (left_subst.len != right_subst.len) return false;
        for (left_subst, right_subst) |left_ty, right_ty| {
            if (left_ty != right_ty) return false;
        }
        if (std.meta.activeTag(left.nested) != std.meta.activeTag(right.nested)) return false;
        return switch (left.nested) {
            .from_callable => true,
            .resolved, .through_alias => |left_span| blk: {
                const right_span = switch (right.nested) {
                    .resolved, .through_alias => |span| span,
                    .from_callable => unreachable, // the tags were compared equal above
                };
                const left_refs = self.evidence_refs.items[left_span.start .. left_span.start + left_span.len];
                const right_refs = self.evidence_refs.items[right_span.start .. right_span.start + right_span.len];
                if (left_refs.len != right_refs.len) break :blk false;
                for (left_refs, right_refs) |left_ref, right_ref| {
                    if (!std.meta.eql(left_ref, right_ref)) break :blk false;
                }
                break :blk true;
            },
        };
    }

    const RecordSiteSpans = struct {
        refs: static_dispatch.EvidenceSpan,
        subst: static_dispatch.EvidenceSpan,
    };

    /// Whether an evidence chain has no parameters in any of its frames, so
    /// no resolution against it can depend on it.
    fn evidenceChainIsEmpty(chain: []const ChainLevel) bool {
        for (chain) |level| {
            if (level.params.len != 0) return false;
        }
        return true;
    }

    const RecordSubstitutionKey = struct {
        scheme_root: u32,
        pairs_start: u32,
        pairs_len: u32,
        unpinned: UnpinnedRecordEvidence,
    };

    /// How a scheme-use record publishes an obligation that neither the
    /// record's substitution nor the current chain pins.
    const UnpinnedRecordEvidence = enum {
        /// Publish nothing yet: a later walk may bind it.
        defer_resolution,
        /// Commit it by the unpinned-dispatch rule.
        commit,
        /// The record places a function into a value as data. A containing
        /// record, tuple, list, tag, or nominal can cross a module boundary
        /// before that function is requested at a concrete type, so an
        /// obligation reachable through the function's own callable type
        /// resolves from that eventual request instead of committing to
        /// `unreachable`.
        from_callable,
    };

    /// Resolve one scheme-use record's obligations (in the scheme's canonical
    /// order) into a contiguous `evidence_refs` range, and record the
    /// substitution the instantiation applied to the scheme.
    fn evidenceRefsForRecord(self: *EvidencePass, record_idx: u32, unpinned: UnpinnedRecordEvidence) Allocator.Error!?RecordSiteSpans {
        const module_env = self.module.moduleEnvConst();
        const record = module_env.scheme_uses.items.items[record_idx];
        if (record.slot_kind == @backingInt(ModuleEnv.SchemeUseRecord.Slot.where_method_use)) {
            checkedArtifactInvariant("where-method callable relation reached scheme-use evidence emission", .{});
        }
        const pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len];
        // Resolution against an enclosing evidence chain depends on that
        // chain, so only chain-free resolutions are shared.
        const key: ?RecordSubstitutionKey = if (evidenceChainIsEmpty(self.current_chain)) .{
            .scheme_root = record.scheme_root,
            .pairs_start = record.pairs_start,
            .pairs_len = record.pairs_len,
            .unpinned = unpinned,
        } else null;
        if (key) |shared| if (self.record_spans_by_substitution.get(shared)) |spans| return spans;

        var params = std.ArrayListUnmanaged(EvidenceParam).empty;
        defer params.deinit(self.allocator);
        try self.enumerateParams(@fromBackingInt(@intCast(record.scheme_root)), &params);

        var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
        defer entries.deinit(self.allocator);
        try entries.ensureTotalCapacity(self.allocator, params.items.len);

        for (params.items) |param| {
            const evidence = switch (unpinned) {
                .defer_resolution => (try self.evidenceForRecordParam(pairs, param, false)) orelse return null,
                .commit => (try self.evidenceForRecordParam(pairs, param, true)).?,
                .from_callable => try self.storedFunctionEvidenceForRecordParam(pairs, param),
            };
            entries.appendAssumeCapacity(evidence);
        }

        // A value use instantiates the referenced scheme; a nested-function use
        // instantiates the stored expression's own scheme for the value that
        // stores it. Either way the pairs name each quantified variable's copy.
        const spans: RecordSiteSpans = .{
            .refs = try self.appendEvidenceRefs(entries.items),
            .subst = try self.appendSiteSubstitution(@fromBackingInt(@intCast(record.scheme_root)), pairs, &.{}),
        };
        if (key) |shared| try self.record_spans_by_substitution.put(self.allocator, shared, spans);
        return spans;
    }

    fn evidenceForRecordParam(
        self: *EvidencePass,
        pairs: []const ModuleEnv.SchemeUsePair,
        param: EvidenceParam,
        commit_unpinned: bool,
    ) Allocator.Error!?static_dispatch.CheckedEvidence {
        const context = try self.evidenceContextForRecordParam(pairs, param);
        const resolution = (try self.resolveObligation(context.var_, context.dispatcher_ty, context.method, context.structural_kind, context.fresh_fn_var, context.literal_kind, self.current_chain, commit_unpinned)) orelse return null;
        var evidence = self.evidenceFromResolution(context, resolution);
        if (param.callable_contracts.len != 0) {
            // A non-structural method on one settled receiver has one target.
            // Its schema proves when every independent callable can derive its
            // own nested evidence. Preserve any exact per-call rejection even
            // on that path, using the same rejection authority as resolveObligation.
            if (!try self.evidenceNeedsCallableContract(evidence) and self.structuralKindForMethodIdent(param.constraint.fn_name) == null) {
                var rejected = false;
                for (param.callable_contracts) |constraint| {
                    const root = self.types.resolveVar(constraint.fn_var).var_;
                    const fresh = self.pairForResolved(pairs, root) orelse root;
                    if (self.types.varStaticDispatchRejected(fresh)) {
                        rejected = true;
                        break;
                    }
                }
                if (!rejected) return evidence;
            }
            // A contract parameter carries no contracts of its own, so this
            // descends one level.
            var contracts = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
            defer contracts.deinit(self.allocator);
            for (param.callable_contracts) |constraint| {
                var contract_param = param;
                contract_param.constraint = constraint;
                contract_param.callable_contracts = &.{};
                const contract = (try self.evidenceForRecordParam(pairs, contract_param, commit_unpinned)) orelse return null;
                try contracts.append(self.allocator, contract);
            }
            var needs_contract = try self.evidenceNeedsCallableContract(evidence);
            for (contracts.items) |contract| needs_contract = needs_contract or try self.evidenceNeedsCallableContract(contract);
            if (needs_contract) evidence.callable_contracts = try self.internCallableContracts(contracts.items);
        }
        return evidence;
    }

    fn evidenceContextForRecordParam(
        self: *EvidencePass,
        pairs: []const ModuleEnv.SchemeUsePair,
        param: EvidenceParam,
    ) Allocator.Error!EvidenceContext {
        const dispatcher_root = self.types.resolveVar(param.dispatcher_var).var_;
        const fresh_dispatcher = self.pairForResolved(pairs, dispatcher_root) orelse param.dispatcher_var;
        const fn_root = self.types.resolveVar(param.constraint.fn_var).var_;
        // A monomorphic receiver can share its root while the callable's
        // encoding or result parameters are copied. Consume both recorded
        // sides of the relation independently. The instantiator pairs every
        // callable it copies, so an unpaired callable is shared with the use,
        // exactly like an unpaired receiver.
        const fresh_fn = self.pairForResolved(pairs, fn_root) orelse param.constraint.fn_var;
        return try self.evidenceContext(param, fresh_dispatcher, fresh_fn);
    }

    /// One obligation of an instantiated scheme, ready to resolve.
    const EvidenceContext = struct {
        param: EvidenceParam,
        var_: Var,
        fresh_fn_var: ?Var,
        /// The kind of source literal the obligation converts, if any.
        literal_kind: ?LiteralKind,
        method: canonical.MethodNameId,
        structural_kind: ?static_dispatch.StructuralKind,
        dispatcher_ty: CheckedTypeId,
    };

    fn evidenceContext(self: *EvidencePass, param: EvidenceParam, var_: Var, fresh_fn_var: ?Var) Allocator.Error!EvidenceContext {
        const idents = self.module.identStoreConst();
        return .{
            .param = param,
            .var_ = var_,
            .fresh_fn_var = fresh_fn_var,
            .literal_kind = param.constraint.origin.literalKind(),
            .method = try self.names.internMethodIdent(idents, param.constraint.fn_name),
            .structural_kind = self.structuralKindForMethodIdent(param.constraint.fn_name),
            .dispatcher_ty = self.checked_types.rootForSourceVar(self.module, var_) orelse
                checkedArtifactInvariant("checked scheme evidence dispatcher type was not published", .{}),
        };
    }

    /// Callable-only target schemas need no per-use payload. Forwarded,
    /// structural, rejected and unreachable entries retain their exact proof.
    fn evidenceNeedsCallableContract(self: *EvidencePass, evidence: static_dispatch.CheckedEvidence) Allocator.Error!bool {
        return switch (evidence.resolution) {
            .direct => |id| switch (self.evidence_nodes.items[id.index].target.kind) {
                .procedure => blk: {
                    const target = self.evidence_nodes.items[id.index].target;
                    const schema = try self.procedureEvidenceView(target);
                    break :blk switch (static_dispatch.procedureEvidenceSchema(schema.params)) {
                        .none => !schema.callable_determines_scheme,
                        .from_callable => procedureHasCodecEvidenceParam(schema) or !schema.callable_determines_scheme,
                        .from_target, .requires_record => true,
                    };
                },
                .local_proc, .structural => true,
            },
            .constraint, .structural, .from_callable, .from_scheme, .checked_error, .unreachable_value => true,
        };
    }

    /// A callable-derived codec requirement resolves to a structural parser or
    /// encoder only through a checked generated-codec derivation, which a
    /// per-use callable cannot derive after checking.
    fn procedureHasCodecEvidenceParam(schema: SchemaView) bool {
        for (schema.params) |param| {
            const structural = param.structural orelse continue;
            switch (structural) {
                .parser, .encoder => return true,
                .equality, .hash, .map, .map_effectful => {},
            }
        }
        return false;
    }

    /// Intern only sparse side vectors. Children have already been interned,
    /// so their spans are canonical and equality needs no recursive traversal.
    fn internCallableContracts(self: *EvidencePass, entries: []const static_dispatch.CheckedEvidence) Allocator.Error!static_dispatch.EvidenceSpan {
        var hasher = std.hash.Wyhash.init(0);
        for (entries) |entry| std.hash.autoHash(&hasher, entry);
        const bucket_key = hasher.final();
        const row_index = std.math.cast(u32, self.callable_contracts.items.len) orelse return error.OutOfMemory;
        if (row_index == CallableContractRow.none) return error.OutOfMemory;
        try self.callable_contracts.ensureUnusedCapacity(self.allocator, 1);
        const bucket = try self.callable_contract_buckets.getOrPut(self.allocator, bucket_key);
        const newest = if (bucket.found_existing) bucket.value_ptr.* else CallableContractRow.none;
        var cursor = newest;
        while (cursor != CallableContractRow.none) {
            const row = self.callable_contracts.items[cursor];
            cursor = row.next;
            if (row.span.len != entries.len) continue;
            const existing = self.evidence_refs.items[row.span.start..][0..row.span.len];
            var equal = true;
            for (existing, entries) |left, right| {
                if (!std.meta.eql(left, right)) {
                    equal = false;
                    break;
                }
            }
            if (equal) return row.span;
        }
        const span = self.appendEvidenceRefs(entries) catch |err| {
            if (!bucket.found_existing) _ = self.callable_contract_buckets.remove(bucket_key);
            return err;
        };
        self.callable_contracts.appendAssumeCapacity(.{ .span = span, .next = newest });
        bucket.value_ptr.* = row_index;
        return span;
    }

    /// Resolve one obligation of an instantiated scheme: the fresh dispatcher
    /// var either settled to a concrete type (direct or structural evidence),
    /// or is one of the *enclosing* callable's params (forwarded). The
    /// enclosing params here are the ones of the template whose body contains
    /// the instantiation site; the caller of `siteEvidence`/nested-node
    /// construction passes them contextually via `current_site_params`.
    fn evidenceForVar(
        self: *EvidencePass,
        param: EvidenceParam,
        var_: Var,
        fresh_fn_var: ?Var,
        commit_unpinned: bool,
    ) Allocator.Error!?static_dispatch.CheckedEvidence {
        const context = try self.evidenceContext(param, var_, fresh_fn_var);
        const resolution = (try self.resolveObligation(var_, context.dispatcher_ty, context.method, context.structural_kind, fresh_fn_var, context.literal_kind, self.current_chain, commit_unpinned)) orelse return null;
        return self.evidenceFromResolution(context, resolution);
    }

    fn evidenceFromResolution(
        self: *EvidencePass,
        context: EvidenceContext,
        resolution: static_dispatch.CheckedCallResolution,
    ) static_dispatch.CheckedEvidence {
        const param = context.param;
        const var_ = context.var_;
        const fresh_fn_var = context.fresh_fn_var;
        const dispatcher_ty = context.dispatcher_ty;
        return .{
            .dispatcher_ty = dispatcher_ty,
            .resolution = switch (resolution) {
                .direct_pending => |node| .{ .direct = node },
                .direct_closed, .direct_parametric => checkedArtifactInvariant("call resolution was finalized before evidence publication completed", .{}),
                .evidence_dependent => |dependent| .{ .constraint = .{
                    .scheme_param = dependent.scheme_param,
                    .index = dependent.index,
                    .independent_callable = dependent.independent_callable,
                    .reuse_slot_nested_evidence = dependent.reuse_slot_nested_evidence,
                    .callable_contract = dependent.callable_contract,
                } },
                .structural => |kind| blk: {
                    const callable_var = self.codecRelationCallable(fresh_fn_var orelse param.constraint.fn_var);
                    const callable_ty = self.checked_types.rootForSourceVar(self.module, callable_var) orelse
                        checkedArtifactInvariant("checked structural evidence callable type was not published", .{});
                    break :blk .{ .structural = .{
                        .derivation = kind,
                        .dispatcher_ty = dispatcher_ty,
                        .callable_ty = callable_ty,
                        .generated_codec_derivation = switch (kind) {
                            .parser => self.generatedCodecDerivationForSourceConstraint(
                                callable_var,
                                .parser,
                            ) orelse checkedArtifactInvariant(
                                "structural parser evidence had no generated derivation for its checked constraint",
                                .{},
                            ),
                            .encoder => self.generatedCodecDerivationForSourceConstraint(
                                callable_var,
                                .encoder,
                            ) orelse checkedArtifactInvariant(
                                "structural encoder evidence had no generated derivation for its checked constraint",
                                .{},
                            ),
                            .equality, .hash, .map, .map_effectful => null,
                        },
                    } };
                },
                .checked_error => blk: {
                    if (@import("builtin").mode == .debug) {
                        std.log.scoped(.checked_evidence).debug("evidence entry checked_error: method={s} content={s}", .{
                            self.module.identStoreConst().getText(param.constraint.fn_name),
                            @tagName(self.types.resolveVar(var_).desc.content),
                        });
                    }
                    break :blk .checked_error;
                },
                .@"unreachable" => .unreachable_value,
            },
        };
    }

    /// The derived-structural kind a constraint method admits, if any.
    /// Ident-keyed view of `static_dispatch.structural_method_kinds`: each
    /// table entry's name doubles as the matching `CommonIdents` field.
    fn structuralKindForMethodIdent(self: *EvidencePass, fn_name: anytype) ?static_dispatch.StructuralKind {
        const common = self.module.commonIdents();
        inline for (static_dispatch.structural_method_kinds) |entry| {
            if (fn_name.eql(@field(common, entry.common_ident))) return entry.kind;
        }
        return null;
    }

    fn appendEvidenceRefs(self: *EvidencePass, entries: []const static_dispatch.CheckedEvidence) Allocator.Error!static_dispatch.EvidenceSpan {
        const start: u32 = @intCast(self.evidence_refs.items.len);
        try self.evidence_refs.appendSlice(self.allocator, entries);
        return .{ .owner = self.owner, .start = start, .len = @intCast(entries.len) };
    }

    /// Publish site evidence for one value reference within the current
    /// template: how each of the referenced scheme's obligations was
    /// satisfied at that use.
    fn emitSiteEvidence(self: *EvidencePass, ref_id: ResolvedValueRefId, chain: []const ChainLevel) Allocator.Error!void {
        const rec = self.resolved_value_refs.records[@backingInt(ref_id)];
        const site_key = @backingInt(rec.expr);
        if (self.site_seen.contains(site_key)) return;

        if (self.module_index.nodeKind(site_key) != .expr) return;
        const source_node = site_key;

        if (self.index.value_use_by_node.get(source_node)) |record_idx| {
            const procedure_value = switch (rec.ref) {
                .top_level_proc,
                .imported_proc,
                .hosted_proc,
                .promoted_top_level_proc,
                .platform_required_proc,
                => true,
                .local_param,
                .local_value,
                .local_mutable_version,
                .pattern_binder,
                .local_proc,
                .selected_hoisted_const,
                .top_level_const,
                .imported_const,
                .platform_required_declaration,
                .platform_required_checked_error,
                .platform_required_const,
                => false,
            };
            if (procedure_value) {
                try self.emitProcedureValueSiteEvidence(record_idx, site_key, chain);
                return;
            }
            try self.emitSchemeUseSiteEvidence(record_idx, site_key, chain);
            return;
        }

        // A monomorphic local procedure use does not instantiate a scheme, so
        // checking has no SchemeUseRecord for it. Its declaration scope still
        // owns an explicit evidence schema; publish that schema's finished
        // vector from the settled source variables now.
        if (rec.ref == .local_proc) {
            const local = rec.ref.local_proc;
            const scope_id = local.dispatch_scope orelse return;
            const raw_scope = @backingInt(scope_id);
            if (raw_scope >= self.templates.dispatch_scopes.len) {
                checkedArtifactInvariant("local procedure use named an evidence scope outside the checked template table", .{});
            }
            const scope = self.templates.dispatch_scopes[raw_scope];
            if (scope.checked_expr != local.expr) {
                checkedArtifactInvariant("local procedure use evidence scope belonged to a different checked expression", .{});
            }
            const params = try self.paramsForScope(scope_id, scope.scheme_var);
            if (params.len == 0) return;

            self.current_chain = chain;
            defer self.current_chain = &.{};
            var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
            defer entries.deinit(self.allocator);
            try entries.ensureTotalCapacity(self.allocator, params.len);
            for (params) |param| {
                const evidence = (try self.evidenceForVar(
                    param,
                    param.dispatcher_var,
                    param.constraint.fn_var,
                    true,
                )) orelse checkedArtifactInvariant(
                    "monomorphic local procedure evidence remained unresolved after checking",
                    .{},
                );
                entries.appendAssumeCapacity(evidence);
            }
            const span = try self.appendEvidenceRefs(entries.items);
            const subst = try self.appendSiteSubstitution(scope.scheme_var, &.{}, &.{});
            try self.site_seen.put(site_key, {});
            try self.site_evidence.append(self.allocator, .{
                .key = site_key,
                .start = span.start,
                .len = span.len,
                .subst_start = subst.start,
                .subst_len = subst.len,
            });
        }

        // References that do not become specialization edges intentionally
        // have no site evidence. Shared recursive uses are explicit records
        // and therefore returned through the branch above.
        return;
    }

    /// One obligation of a function stored as data (`UnpinnedRecordEvidence.from_callable`).
    fn storedFunctionEvidenceForRecordParam(
        self: *EvidencePass,
        pairs: []const ModuleEnv.SchemeUsePair,
        param: EvidenceParam,
    ) Allocator.Error!static_dispatch.CheckedEvidence {
        if (try self.evidenceForRecordParam(pairs, param, false)) |evidence| return evidence;
        if (param.path_len == 0 or param.source == .constraint_callable or param.source == .erased_row_remainder) {
            return (try self.evidenceForRecordParam(pairs, param, true)).?;
        }
        const dispatcher_root = self.types.resolveVar(param.dispatcher_var).var_;
        const dispatcher_var = self.pairForResolved(pairs, dispatcher_root) orelse param.dispatcher_var;
        const dispatcher_ty = self.checked_types.rootForSourceVar(self.module, dispatcher_var) orelse
            checkedArtifactInvariant("checked stored-function dispatcher type was not published", .{});
        return .{
            .dispatcher_ty = dispatcher_ty,
            .resolution = .from_callable,
        };
    }

    /// Publish a procedure value's evidence. The value is a function used as
    /// data, so its unpinned callable components resolve from its eventual
    /// request.
    fn emitProcedureValueSiteEvidence(
        self: *EvidencePass,
        record_idx: u32,
        site_key: u32,
        chain: []const ChainLevel,
    ) Allocator.Error!void {
        if (self.site_seen.contains(site_key)) return;

        self.current_chain = chain;
        defer self.current_chain = &.{};
        const spans = (try self.evidenceRefsForRecord(record_idx, .from_callable)).?;
        try self.site_seen.put(site_key, {});
        try self.site_evidence.append(self.allocator, .{
            .key = site_key,
            .start = spans.refs.start,
            .len = spans.refs.len,
            .subst_start = spans.subst.start,
            .subst_len = spans.subst.len,
        });
    }

    fn emitSchemeUseSiteEvidence(
        self: *EvidencePass,
        record_idx: u32,
        site_key: u32,
        chain: []const ChainLevel,
    ) Allocator.Error!void {
        if (self.site_seen.contains(site_key)) return;

        const record = self.module.moduleEnvConst().scheme_uses.items.items[record_idx];
        if (record.slot_kind == @backingInt(ModuleEnv.SchemeUseRecord.Slot.where_method_use)) {
            checkedArtifactInvariant("where-method callable relation reached a scheme-use evidence site", .{});
        }
        // A value use and a nested-function use can share one node (a
        // referenced value stored in expression position); the value use
        // owns the site's evidence regardless of which record checking
        // appended first.
        if (record.slot_kind == @backingInt(ModuleEnv.SchemeUseRecord.Slot.nested_function_use)) {
            if (self.module_index.nodeKind(site_key) == .expr and self.index.value_use_by_node.contains(site_key)) return;
        }

        self.current_chain = chain;
        defer self.current_chain = &.{};
        // A nested-function use stores the function it constructs into its
        // containing value as data.
        const unpinned: UnpinnedRecordEvidence = switch (@as(ModuleEnv.SchemeUseRecord.Slot, @fromBackingInt(@intCast(record.slot_kind)))) {
            .shared_value_use => .defer_resolution,
            .nested_function_use => .from_callable,
            .value_use, .dispatch_target, .recursive_dispatch_target, .recursive_reference, .recursive_value_reference => .commit,
            .where_method_use => unreachable, // rejected above
        };
        const spans = (try self.evidenceRefsForRecord(record_idx, unpinned)) orelse {
            try self.deferred_use_sites.append(self.allocator, .{ .record_idx = record_idx, .site_key = site_key });
            return;
        };
        try self.site_seen.put(site_key, {});
        try self.site_evidence.append(self.allocator, .{
            .key = site_key,
            .start = spans.refs.start,
            .len = spans.refs.len,
            .subst_start = spans.subst.start,
            .subst_len = spans.subst.len,
            .instance_ty = self.siteInstanceType(record_idx),
        });
    }

    /// The instance a stored nested-function use places into its containing
    /// value, as a `SiteEvidenceEntry.instance_ty`.
    fn siteInstanceType(self: *EvidencePass, record_idx: u32) u32 {
        const record = self.module.moduleEnvConst().scheme_uses.items.items[record_idx];
        if (record.slot_kind != @backingInt(ModuleEnv.SchemeUseRecord.Slot.nested_function_use)) {
            return static_dispatch.SiteEvidenceEntry.no_site_instance;
        }
        const instance = self.checked_types.rootForSourceVar(self.module, @fromBackingInt(@intCast(record.slot_data))) orelse
            checkedArtifactInvariant("stored nested function instance type was not published", .{});
        return @backingInt(instance);
    }

    /// Publish the complete construction recipe for a generalized nested
    /// procedure that checking did not instantiate through a SchemeUseRecord.
    /// Path-bearing parameters explicitly project from the eventual callable;
    /// pathless parameters are resolved now against the enclosing checked
    /// evidence chain.
    fn emitScopeConstructionEvidence(
        self: *EvidencePass,
        site: CollectedScopeConstructionSite,
        template_level: ChainLevel,
    ) Allocator.Error!void {
        const site_key = @backingInt(site.checked_expr);
        if (self.site_seen.contains(site_key)) return;

        const raw_scope = @backingInt(site.scope);
        if (raw_scope >= self.templates.dispatch_scopes.len) {
            checkedArtifactInvariant("nested procedure construction named an unknown checked scope", .{});
        }
        const scope = self.templates.dispatch_scopes[raw_scope];
        if (scope.checked_expr != site.checked_expr) {
            checkedArtifactInvariant("nested procedure construction scope belonged to a different checked expression", .{});
        }

        const parent_scope: DispatchScope = if (scope.parent) |parent|
            .{ .generalized = parent }
        else
            .root;
        self.current_chain = try self.chainFor(parent_scope, template_level);
        defer self.current_chain = &.{};

        const scope_params = try self.paramsForScope(site.scope, scope.scheme_var);
        var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
        defer entries.deinit(self.allocator);
        try entries.ensureTotalCapacity(self.allocator, scope_params.len);
        for (scope_params) |param| {
            if ((param.path_len > 0 and param.source != .constraint_callable) or param.source == .scheme_requirement) {
                // A callable-derived scope's type can also reach a receiver
                // an enclosing scope binds, which forwards to that scope.
                if (param.source != .scheme_requirement) {
                    if (try self.evidenceForVar(param, param.dispatcher_var, param.constraint.fn_var, false)) |evidence| {
                        entries.appendAssumeCapacity(evidence);
                        continue;
                    }
                }
                const dispatcher_ty = self.checked_types.rootForSourceVar(self.module, param.dispatcher_var) orelse
                    checkedArtifactInvariant("checked nested-procedure evidence dispatcher type was not published", .{});
                entries.appendAssumeCapacity(.{
                    .dispatcher_ty = dispatcher_ty,
                    .resolution = if (param.source == .scheme_requirement) .from_scheme else .from_callable,
                });
                continue;
            }
            const evidence = (try self.evidenceForVar(
                param,
                param.dispatcher_var,
                param.constraint.fn_var,
                true,
            )) orelse checkedArtifactInvariant(
                "pathless nested procedure evidence remained unresolved after checking",
                .{},
            );
            entries.appendAssumeCapacity(evidence);
        }

        const span = try self.appendEvidenceRefs(entries.items);
        try self.site_seen.put(site_key, {});
        try self.site_evidence.append(self.allocator, .{ .key = site_key, .start = span.start, .len = span.len });
    }

    /// The fresh var one scheme-use record's substitution pairs with
    /// `old_root`, comparing RESOLVED roots on both sides: finalization after
    /// record time can move the pristine var's root. `pairs` is that record's
    /// range of `scheme_use_pairs`.
    fn pairForResolved(self: *EvidencePass, pairs: []const ModuleEnv.SchemeUsePair, old_root: Var) ?Var {
        if (pairs.len == 0) return null;
        const all_pairs = self.module.moduleEnvConst().scheme_use_pairs.items.items;
        const offset = @intFromPtr(pairs.ptr) - @intFromPtr(all_pairs.ptr);
        std.debug.assert(offset % @sizeOf(ModuleEnv.SchemeUsePair) == 0);
        const pairs_start: u32 = @intCast(offset / @sizeOf(ModuleEnv.SchemeUsePair));
        std.debug.assert(pairs_start + pairs.len <= all_pairs.len);
        return self.index.fresh_by_pair_root.get(.{
            .pairs_start = pairs_start,
            .pairs_len = @intCast(pairs.len),
            .old_root = old_root,
        });
    }
};

test "procedure evidence schema positively classifies callable paths and pathless requirements" {
    var params = [_]static_dispatch.EvidenceParamRecord{
        .{ .method = @fromBackingInt(@intCast(1)), .dispatcher_ty = @fromBackingInt(@intCast(1)), .callable_ty = @fromBackingInt(@intCast(3)), .slot = 0, .structural = .encoder, .path = .{ .last = 0, .len = 1 } },
        .{ .method = @fromBackingInt(@intCast(2)), .dispatcher_ty = @fromBackingInt(@intCast(2)), .callable_ty = @fromBackingInt(@intCast(4)), .slot = 1, .path = .{ .last = 1, .len = 1 } },
    };
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.from_callable,
        static_dispatch.procedureEvidenceSchema(&params),
    );

    var pathless_params = params;
    pathless_params[1].path = .{};
    pathless_params[1].source = .erased_row_remainder;
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.requires_record,
        static_dispatch.procedureEvidenceSchema(&pathless_params),
    );

    var target_params = [_]static_dispatch.EvidenceParamRecord{params[0]};
    target_params[0].source = .scheme_requirement;
    target_params[0].path = .{};
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.from_target,
        static_dispatch.procedureEvidenceSchema(&target_params),
    );

    target_params[0].path = .{ .last = 0, .len = 1 };
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.requires_record,
        static_dispatch.procedureEvidenceSchema(&target_params),
    );

    var mixed_params = [_]static_dispatch.EvidenceParamRecord{ params[0], params[1] };
    mixed_params[1].source = .scheme_requirement;
    mixed_params[1].path = .{};
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.requires_record,
        static_dispatch.procedureEvidenceSchema(&mixed_params),
    );

    var defaulted_pathless_params = pathless_params;
    defaulted_pathless_params[1].source = .{ .explicit_default = .mono_specialization };
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.from_callable,
        static_dispatch.procedureEvidenceSchema(&defaulted_pathless_params),
    );

    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.none,
        static_dispatch.procedureEvidenceSchema(&.{}),
    );
}

fn siteEvidenceLessThan(_: void, a: static_dispatch.SiteEvidenceEntry, b: static_dispatch.SiteEvidenceEntry) bool {
    return a.key < b.key;
}

/// A template schema with no scheme: the schema of a template appended
/// after the module's dispatch sites were collected.
pub const empty_scheme_analysis: SchemeAnalysis = .{
    .view = .{},
    .chain = null,
};

/// The dispatch resolution of a template whose body reaches no dispatch
/// site: one appended after the module's dispatch sites were collected.
pub const empty_template_dispatch: TemplateDispatch = .{
    .pool = .{ .owner = .module },
    .site_evidence = &.{},
    .plans = &.{},
    .iterator_plans = &.{},
    .root_evidence = .{},
    .deferred_sites = &.{},
};

/// The relations of a template whose body reaches no dispatch plan.
pub const empty_template_relations: TemplateDispatchRelations = .{
    .direct = &.{},
    .relations = &.{},
    .relation_scopes = &.{},
    .relation_kinds = &.{},
};

/// The module-wide indexes dispatch resolution reads.
pub fn computeDispatchIndex(allocator: Allocator, dispatch: CheckedDispatch) Allocator.Error!*DispatchIndex {
    const source = dispatch.source;
    const index = try allocator.create(DispatchIndex);
    index.* = .{
        .allocator = allocator,
        .template_scheme_vars = collections.DenseMap(u32, Var).init(allocator),
        .value_use_by_node = collections.DenseMap(u32, u32).init(allocator),
        .target_by_fn_var = collections.DenseMap(u32, u32).init(allocator),
        .generated_codec_by_source = collections.DenseMap(Var, EvidencePass.GeneratedCodecsByKind).init(allocator),
        .where_method_use_by_fn_var = collections.DenseMap(u32, u32).init(allocator),
        .where_method_use_by_fn_root = collections.DenseMap(Var, u32).init(allocator),
        .local_value_scheme_by_var = collections.DenseMap(u32, u32).init(allocator),
        .value_use_record_by_pattern = collections.DenseMap(u32, u32).init(allocator),
        .codec_instance_by_template = collections.DenseMap(Var, Var).init(allocator),
    };
    errdefer index.destroy();
    var module_data = TypedCIR.ModuleData.readOnly(source.env);
    {
        var pass = try EvidencePass.init(allocator, dispatch, &module_data, .module, index);
        defer pass.deinit();
        try pass.buildIndexes(index);
    }
    try fillDispatchReach(allocator, source, index);
    return index;
}

/// Record which templates reach each plan, iterator plan and use site.
fn fillDispatchReach(allocator: Allocator, source: DispatchSource, index: *DispatchIndex) Allocator.Error!void {
    const templates = source.templates;
    const sites = &templates.dispatch_sites;
    const walked = sites.walkedTemplateCount();

    const plan_reach = try allocator.alloc(artifact_serialize.Span, source.plans.plans.len);
    index.plan_reach = plan_reach;
    @memset(plan_reach, .{});
    const iterator_reach = try allocator.alloc(artifact_serialize.Span, source.plans.iterator_for_plans.len);
    index.iterator_reach = iterator_reach;
    @memset(iterator_reach, .{});

    // Count each plan's references, then place them in template order with
    // the defaulted-field expressions last.
    for (0..walked + 1) |t| {
        const plan_span = if (t < walked) dispatchPlanSpan(templates, t) else sites.defaultRefs(TemplateDispatchSites.default_plan_refs);
        for (templates.dispatch_plan_refs[plan_span.start..][0..plan_span.len]) |plan| plan_reach[@backingInt(plan)].len += 1;
        const iterator_span = sites.iteratorSpan(t);
        for (sites.iterator_refs[iterator_span.start..][0..iterator_span.len]) |plan| iterator_reach[@backingInt(plan)].len += 1;
    }
    index.plan_sites = try allocator.alloc(DispatchIndex.PlanReach, assignReachStarts(plan_reach));
    index.iterator_sites = try allocator.alloc(DispatchIndex.PlanReach, assignReachStarts(iterator_reach));
    for (plan_reach) |*span| span.len = 0;
    for (iterator_reach) |*span| span.len = 0;
    for (0..walked + 1) |t| {
        const template: ?u32 = if (t < walked) @intCast(t) else null;
        const plan_span = if (t < walked) dispatchPlanSpan(templates, t) else sites.defaultRefs(TemplateDispatchSites.default_plan_refs);
        for (templates.dispatch_plan_refs[plan_span.start..][0..plan_span.len], templates.dispatch_ref_scopes[plan_span.start..][0..plan_span.len]) |plan, scope| {
            const span = &plan_reach[@backingInt(plan)];
            index.plan_sites[span.start + span.len] = .{ .template = template, .scope = scope };
            span.len += 1;
        }
        const iterator_span = sites.iteratorSpan(t);
        for (sites.iterator_refs[iterator_span.start..][0..iterator_span.len], sites.iterator_scopes[iterator_span.start..][0..iterator_span.len]) |plan, scope| {
            const span = &iterator_reach[@backingInt(plan)];
            index.iterator_sites[span.start + span.len] = .{ .template = template, .scope = scope };
            span.len += 1;
        }
    }

    var site_reach = std.ArrayList(DispatchIndex.SiteReach).empty;
    defer site_reach.deinit(allocator);
    for (0..walked) |t| {
        const template = templates.templates.items[t];
        const template_raw: u32 = @intCast(t);
        const value_refs = source.refs.template_refs[template.resolved_value_refs.start..][0..template.resolved_value_refs.len];
        for (value_refs) |ref_id| {
            try site_reach.append(allocator, .{ .site = @backingInt(source.refs.records[@backingInt(ref_id)].expr), .template = template_raw });
        }
        const scheme_span = sites.schemeUseSpan(t);
        for (sites.scheme_use_sites[scheme_span.start..][0..scheme_span.len]) |site| {
            try site_reach.append(allocator, .{ .site = @backingInt(site.checked_expr), .template = template_raw });
        }
        const scope_span = sites.scopeSiteSpan(t);
        for (sites.scope_sites[scope_span.start..][0..scope_span.len]) |site| {
            try site_reach.append(allocator, .{ .site = @backingInt(site.checked_expr), .template = template_raw });
        }
    }
    std.mem.sort(DispatchIndex.SiteReach, site_reach.items, {}, DispatchIndex.SiteReach.lessThan);
    var len: usize = 0;
    for (site_reach.items) |entry| {
        if (len > 0 and std.meta.eql(site_reach.items[len - 1], entry)) continue;
        site_reach.items[len] = entry;
        len += 1;
    }
    site_reach.shrinkRetainingCapacity(len);
    index.site_reach = try site_reach.toOwnedSlice(allocator);
}

fn dispatchPlanSpan(templates: *const CheckedProcedureTemplateTable, template: usize) artifact_serialize.Span {
    const span = templates.templates.items[template].static_dispatch_plans;
    return .{ .start = span.start, .len = span.len };
}

/// Turn per-item counts into consecutive ranges; returns the total.
fn assignReachStarts(spans: []artifact_serialize.Span) usize {
    var next: u32 = 0;
    for (spans) |*span| {
        span.start = next;
        next += span.len;
    }
    return next;
}

/// The schema of procedure template `template`.
pub fn computeTemplateSchema(allocator: Allocator, dispatch: CheckedDispatch, template_id: canonical.CheckedProcedureTemplateId) Allocator.Error!*SchemeAnalysis {
    const source = dispatch.source;
    const index = try source.analyses.dispatchIndex(dispatch);
    var module_data = TypedCIR.ModuleData.readOnly(source.env);
    var pass = try EvidencePass.init(allocator, dispatch, &module_data, .module, index);
    defer pass.deinit();
    const published = try pass.publishTemplateSchema(source.templates.templates.items[template_id.index()]);
    return try schemeAnalysisFromPass(allocator, &pass, published.vars, published.params, published.callable_determines_scheme, published.chain_root);
}

/// The schema of generalized local scope `scope`.
pub fn computeScopeSchema(allocator: Allocator, dispatch: CheckedDispatch, scope: DispatchScopeId) Allocator.Error!*SchemeAnalysis {
    const source = dispatch.source;
    const index = try source.analyses.dispatchIndex(dispatch);
    var module_data = TypedCIR.ModuleData.readOnly(source.env);
    var pass = try EvidencePass.init(allocator, dispatch, &module_data, .module, index);
    defer pass.deinit();
    const scheme_var = source.templates.dispatch_scopes[@backingInt(scope)].scheme_var;
    const published = try pass.publishScheme(scheme_var);
    return try schemeAnalysisFromPass(allocator, &pass, published.vars, published.params, true, scheme_var);
}

/// Copy what `pass` published for one schema into a self-contained result.
fn schemeAnalysisFromPass(
    allocator: Allocator,
    pass: *EvidencePass,
    vars: artifact_serialize.Span,
    params: artifact_serialize.Span,
    callable_determines_scheme: bool,
    chain_root: ?Var,
) Allocator.Error!*SchemeAnalysis {
    const result = try allocator.create(SchemeAnalysis);
    errdefer allocator.destroy(result);
    var arena_allocator = std.heap.ArenaAllocator.init(allocator);
    errdefer arena_allocator.deinit();
    const arena = arena_allocator.allocator();
    result.* = .{ .view = .{}, .chain = null };
    result.view = .{
        .vars = try arena.dupe(CheckedTypeId, pass.scheme_vars_pool.items[vars.start..][0..vars.len]),
        .params = try arena.dupe(static_dispatch.EvidenceParamRecord, pass.evidence_params_pool.items[params.start..][0..params.len]),
        .path_nodes = try arena.dupe(static_dispatch.EvidencePathNode, pass.evidence_path_nodes.items),
        .param_callables = try arena.dupe(CheckedTypeId, pass.evidence_param_callables.items),
        .callable_determines_scheme = callable_determines_scheme,
    };
    if (chain_root) |root| {
        const owner = pass.schemeOwner(root);
        result.view.scheme = @backingInt(owner);
        const schema = try pass.schemeSchema(root);
        const enumerated = try arena.alloc(dispatch_evidence.EvidenceParam, schema.params.len);
        for (enumerated, schema.params) |*copy, param| {
            copy.* = param;
            copy.callable_contracts = try arena.dupe(types.StaticDispatchConstraint, param.callable_contracts);
        }
        const published = schema.published orelse checkedArtifactInvariant("a chain scheme was enumerated without being published", .{});
        result.chain = .{
            .owner = @backingInt(owner),
            .params = enumerated,
            .by_dispatcher = .{ .rows = try arena.dupe(EvidencePass.DispatcherParams.Row, schema.by_dispatcher.rows) },
            .published = try arena.dupe(static_dispatch.EvidenceParamRecord, pass.evidence_params_pool.items[published.params.start..][0..published.params.len]),
        };
    }
    result.arena = arena_allocator.state;
    return result;
}

/// The dispatch resolution of procedure template `template`.
pub fn computeTemplateDispatch(allocator: Allocator, dispatch: CheckedDispatch, template_id: canonical.CheckedProcedureTemplateId) Allocator.Error!*TemplateDispatch {
    const source = dispatch.source;
    const index = try source.analyses.dispatchIndex(dispatch);
    var module_data = TypedCIR.ModuleData.readOnly(source.env);
    var pass = try EvidencePass.init(allocator, dispatch, &module_data, static_dispatch.EvidenceOwner.forTemplate(template_id), index);
    defer pass.deinit();
    const root_evidence = try pass.resolveTemplate(template_id);
    try specializeResolvedPlans(allocator, &pass, index);

    const result = try allocator.create(TemplateDispatch);
    errdefer allocator.destroy(result);
    var pool = try pass.takePool();
    errdefer pool.deinit(allocator);
    const site_evidence = try pass.takeSiteEvidence();
    errdefer allocator.free(site_evidence);
    const plans = try pass.takePlanResults();
    errdefer allocator.free(plans);
    const iterator_plans = try pass.takeIteratorResults();
    errdefer allocator.free(iterator_plans);
    var deferred = std.ArrayList(DeferredUseSite).empty;
    defer deferred.deinit(allocator);
    for (pass.deferred_use_sites.items) |site| {
        if (pass.site_seen.contains(site.site_key)) continue;
        try deferred.append(allocator, site);
    }
    result.* = .{
        .pool = pool,
        .site_evidence = site_evidence,
        .plans = plans,
        .iterator_plans = iterator_plans,
        .root_evidence = root_evidence,
        .deferred_sites = try deferred.toOwnedSlice(allocator),
    };
    return result;
}

/// The plans, iterator plans and use sites some template resolved.
const ModuleBoundSet = struct {
    plans: collections.DenseMap(u32, void),
    iterator_plans: collections.DenseMap(u32, void),
    sites: collections.DenseMap(u32, void),

    fn deinit(self: *ModuleBoundSet) void {
        self.plans.deinit();
        self.iterator_plans.deinit();
        self.sites.deinit();
    }
};

/// The module's dispatch resolution of what no template resolves.
pub fn computeModuleDispatch(allocator: Allocator, dispatch: CheckedDispatch) Allocator.Error!*ModuleDispatch {
    const source = dispatch.source;
    const analyses = source.analyses;
    const index = try analyses.dispatchIndex(dispatch);

    var bound = ModuleBoundSet{
        .plans = collections.DenseMap(u32, void).init(allocator),
        .iterator_plans = collections.DenseMap(u32, void).init(allocator),
        .sites = collections.DenseMap(u32, void).init(allocator),
    };
    defer bound.deinit();
    var deferred = std.ArrayList(DeferredUseSite).empty;
    defer deferred.deinit(allocator);
    for (0..source.templates.dispatch_sites.walkedTemplateCount()) |raw| {
        const resolved = try analyses.templateDispatch(dispatch, @fromBackingInt(@intCast(raw)));
        for (resolved.plans) |entry| try bound.plans.put(entry.plan, {});
        for (resolved.iterator_plans) |entry| try bound.iterator_plans.put(entry.plan, {});
        for (resolved.site_evidence) |entry| try bound.sites.put(entry.key, {});
        try deferred.appendSlice(allocator, resolved.deferred_sites);
    }

    const codec_derivations = try allocator.dupe(static_dispatch.GeneratedCodecDerivation, source.plans.recorded_codec_derivations);
    errdefer allocator.free(codec_derivations);
    const codec_calls = try allocator.dupe(static_dispatch.GeneratedCodecCall, source.plans.recorded_codec_calls);
    errdefer allocator.free(codec_calls);

    var module_data = TypedCIR.ModuleData.readOnly(source.env);
    var pass = try EvidencePass.init(allocator, dispatch, &module_data, .module, index);
    defer pass.deinit();
    try pass.resolveModule(&bound, deferred.items, codec_calls);
    try specializeResolvedPlans(allocator, &pass, index);

    const result = try allocator.create(ModuleDispatch);
    errdefer allocator.destroy(result);
    var pool = try pass.takePool();
    errdefer pool.deinit(allocator);
    const site_evidence = try pass.takeSiteEvidence();
    errdefer allocator.free(site_evidence);
    const plans = try pass.takePlanResults();
    errdefer allocator.free(plans);
    const iterator_plans = try pass.takeIteratorResults();
    errdefer allocator.free(iterator_plans);
    result.* = .{
        .pool = pool,
        .site_evidence = site_evidence,
        .plans = plans,
        .iterator_plans = iterator_plans,
        .codec_derivations = codec_derivations,
        .codec_calls = codec_calls,
    };
    var table = result.codecTable();
    try @import("codec_identity.zig").intern(allocator, source.types.store.view(), &table);
    try @import("codec_identity.zig").digestContents(allocator, source.key.digest(), source.types.store, source.names, &table);
    if (builtin.mode == .debug) try pass.debugVerifyGeneratedCodecRoleAgreement(&table);
    return result;
}

/// An app's root evidence for each of its platform requirement solutions.
pub fn computePlatformRequirementRootEvidence(allocator: Allocator, dispatch: CheckedDispatch) Allocator.Error!*PlatformRequirementRootEvidence {
    const source = dispatch.source;
    const index = try source.analyses.dispatchIndex(dispatch);
    var module_data = TypedCIR.ModuleData.readOnly(source.env);
    var pass = try EvidencePass.init(allocator, dispatch, &module_data, .platform_requirements, index);
    defer pass.deinit();
    const spans = try pass.resolvePlatformRequirementRoots();
    errdefer allocator.free(spans);
    const result = try allocator.create(PlatformRequirementRootEvidence);
    errdefer allocator.destroy(result);
    result.* = .{ .pool = try pass.takePool(), .spans = spans };
    return result;
}

/// How a template's plans relate to its specialization: a plan whose
/// resolution needs a relation (`checkedDispatchPlanNeedsRelation`) keeps
/// its scope and relation kind; every other plan is a direct call.
pub fn computeTemplateDispatchRelations(allocator: Allocator, dispatch: CheckedDispatch, template_id: canonical.CheckedProcedureTemplateId) Allocator.Error!*TemplateDispatchRelations {
    const templates = dispatch.source.templates;
    const span = dispatchPlanSpan(templates, template_id.index());
    var direct = std.ArrayList(static_dispatch.StaticDispatchPlanId).empty;
    defer direct.deinit(allocator);
    var relations = std.ArrayList(static_dispatch.StaticDispatchPlanId).empty;
    defer relations.deinit(allocator);
    var relation_scopes = std.ArrayList(DispatchScope).empty;
    defer relation_scopes.deinit(allocator);
    var relation_kinds = std.ArrayList(DispatchRelationKind).empty;
    defer relation_kinds.deinit(allocator);
    const refs = templates.dispatch_plan_refs[span.start..][0..span.len];
    const scopes = templates.dispatch_ref_scopes[span.start..][0..span.len];
    const kinds = templates.dispatch_relation_kinds[span.start..][0..span.len];
    for (refs, scopes, kinds) |plan_id, scope, kind| {
        const plan = try dispatch.plan(plan_id);
        if (try checkedDispatchPlanNeedsRelation(dispatch, plan)) {
            try relations.append(allocator, plan_id);
            try relation_scopes.append(allocator, scope);
            try relation_kinds.append(allocator, kind);
        } else {
            try direct.append(allocator, plan_id);
        }
    }
    const result = try allocator.create(TemplateDispatchRelations);
    errdefer allocator.destroy(result);
    const direct_slice = try direct.toOwnedSlice(allocator);
    errdefer allocator.free(direct_slice);
    const relations_slice = try relations.toOwnedSlice(allocator);
    errdefer allocator.free(relations_slice);
    const scopes_slice = try relation_scopes.toOwnedSlice(allocator);
    errdefer allocator.free(scopes_slice);
    result.* = .{
        .direct = direct_slice,
        .relations = relations_slice,
        .relation_scopes = scopes_slice,
        .relation_kinds = try relation_kinds.toOwnedSlice(allocator),
    };
    return result;
}

/// Specialize each direct call the pass resolved against its target and
/// classify it `direct_closed` or `direct_parametric`, against every
/// scheme context that references the plan.
///
/// Specialization creates types in the module's store, which other threads
/// read once the module is published, so it runs under the store's creation
/// lock (`CheckedTypeStore.beginCreation`). It reads the nominal
/// representations of the module's own types and of the types it projects
/// from each target's module, so their interface capabilities are demanded
/// before the lock is taken; classification reads only complete types and
/// runs after the lock is released.
fn specializeResolvedPlans(allocator: Allocator, pass: *EvidencePass, index: *const DispatchIndex) Allocator.Error!void {
    const source = pass.dispatch.source;
    const store = source.types.store;
    // A store gets its capability source when its module is published;
    // before that, nothing has the module's capabilities to read.
    if (store.capability_source != null) _ = try store.view().interfaceCapabilities(pass.import_views.resolver());
    const owner = source.key.digest();
    for (pass.plan_results.items) |entry| switch (entry.resolution.resolution) {
        .direct_pending => |node_id| try demandTargetCapabilities(pass, owner, node_id),
        .direct_closed, .direct_parametric => checkedArtifactInvariant("static dispatch plan was finalized more than once", .{}),
        .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
    };
    for (pass.iterator_results.items) |entry| {
        inline for (.{ entry.resolution.iter, entry.resolution.next }) |call| switch (call) {
            .direct_pending => |node_id| try demandTargetCapabilities(pass, owner, node_id),
            .direct_closed, .direct_parametric => checkedArtifactInvariant("iterator dispatch plan was finalized more than once", .{}),
            .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
        };
    }

    const evidence_closure = try allocator.alloc(DirectEvidenceClosure, pass.evidence_nodes.items.len);
    defer allocator.free(evidence_closure);
    @memset(evidence_closure, .unknown);
    var specializer = ResolvedDispatchCallableSpecializer{
        .allocator = allocator,
        .names = source.names,
        .store = source.types.store,
        .owner = source.key.digest(),
        .imports = pass.import_views,
        .evidence_nodes = pass.evidence_nodes.items,
        .evidence_refs = pass.evidence_refs.items,
        .evidence_closure = evidence_closure,
        .identity_index = EnclosingIdentityIndex.init(allocator, source.names, source.types.store),
    };
    defer specializer.deinit();
    {
        store.beginCreation(source.analyses.io);
        defer store.endCreation(source.analyses.io);
        for (pass.plan_results.items) |*entry| try specializer.specializePlan(&entry.resolution);
        for (pass.iterator_results.items) |*entry| try specializer.specializeIteratorPlan(&entry.resolution);
    }
    var sites = std.ArrayList(EnclosingDispatchSite).empty;
    defer sites.deinit(allocator);
    for (pass.plan_results.items) |*entry| {
        try enclosingSitesFor(allocator, source.templates, index.planSites(@fromBackingInt(entry.plan)), &sites);
        try specializer.classifyPlan(&entry.resolution, .{
            .index = &specializer.identity_index,
            .sites = sites.items,
            .scopes = source.templates.dispatch_scopes,
        });
    }
    for (pass.iterator_results.items) |*entry| {
        try enclosingSitesFor(allocator, source.templates, index.iteratorSites(@fromBackingInt(entry.plan)), &sites);
        try specializer.classifyIteratorPlan(&entry.resolution, .{
            .index = &specializer.identity_index,
            .sites = sites.items,
            .scopes = source.templates.dispatch_scopes,
        });
    }
}

/// Demand the interface capabilities of the module whose callable the
/// resolved target `node_id` names, when that module is not `owner`.
fn demandTargetCapabilities(pass: *EvidencePass, owner: ModuleId, node_id: static_dispatch.EvidenceNodeId) Allocator.Error!void {
    const target = pass.evidence_nodes.items[node_id.index].target;
    const target_key = switch (target.kind) {
        .local_proc => return,
        .structural => checkedArtifactInvariant("structural method registry result was published as a direct callable target", .{}),
        .procedure => |procedure| procedure.template.artifact,
    };
    if (target_key.eql(owner)) return;
    const imported = pass.import_views.viewForKey(target_key) orelse
        checkedArtifactInvariant("resolved dispatch target module was not among the modules dispatch resolution reads", .{});
    _ = try imported.checked_types.interfaceCapabilities(pass.import_views.resolver());
}

fn enclosingSitesFor(
    allocator: Allocator,
    templates: *const CheckedProcedureTemplateTable,
    reach: []const DispatchIndex.PlanReach,
    out: *std.ArrayList(EnclosingDispatchSite),
) Allocator.Error!void {
    out.clearRetainingCapacity();
    for (reach) |entry| {
        try out.append(allocator, .{
            .template_root = if (entry.template) |template| templates.templates.items[template].checked_fn_root else null,
            .scope = entry.scope,
        });
    }
}
fn sealConstEvalTemplatesForRoots(
    const_templates: *ConstTemplateTable,
    compile_time_roots: *const CompileTimeRootTable,
    checked_const_bodies: *const CheckedConstBodyTable,
    entry_wrappers: *const EntryWrapperTable,
    checked_procedure_templates: *const CheckedProcedureTemplateTable,
    top_level_values: *const TopLevelValueTable,
    hoisted_constants: *const HoistedConstTable,
) void {
    for (compile_time_roots.roots) |root| {
        if (!compileTimeRootHasConstBody(root.kind)) continue;
        const const_ref = switch (root.kind) {
            .constant => blk: {
                const def_idx = switch (root.source) {
                    .def => |def| def,
                    .expr, .statement, .required_binding, .hoisted, .literal => checkedArtifactInvariant("constant root source is not a top-level definition", .{}),
                };
                const top_level = top_level_values.lookupByDef(def_idx) orelse {
                    checkedArtifactInvariant("constant root has no top-level value entry", .{});
                };
                break :blk switch (top_level.value) {
                    .const_ref => |ref| ref,
                    .procedure_binding => checkedArtifactInvariant("constant root top-level value is not a ConstRef", .{}),
                };
            },
            .hoisted_constant => blk: {
                const hoisted = hoisted_constants.lookupByRoot(root.id) orelse {
                    checkedArtifactInvariant("hoisted constant root has no hoisted const entry", .{});
                };
                break :blk hoisted.const_ref;
            },
            .hoisted_validation,
            .callable_binding,
            .expect,
            .numeral_conversion,
            .quote_conversion,
            .repl_expr,
            .literal_argument,
            => checkedArtifactInvariant("non-constant root reached const eval template sealing", .{}),
        };
        const body = checked_const_bodies.bodyForRoot(root.id) orelse {
            checkedArtifactInvariant("constant root has no checked const body", .{});
        };
        const wrapper = entryWrapperForRoot(entry_wrappers, root.id);
        const template = checked_procedure_templates.get(wrapper.template.template);
        const_templates.fillEval(const_ref, .{
            .body = body,
            .entry_template = wrapper.template,
            .source_scheme = const_ref.source_scheme,
            .resolved_value_refs = template.resolved_value_refs,
            .static_dispatch_plans = template.static_dispatch_plans,
        });
    }
}

const CheckedTemplateRefCollector = struct {
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedTypePublication,
    bodies: CheckedBodies,
    /// Diagnostic errors as publication knows them before total dispatch
    /// resolution (`body_analyses.DiagnosticMode.ordinary`).
    diagnostics: *const body_analyses.NodeBits,
    static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
    /// Generalized-with-obligations local function decls (checked lambda expr
    /// id -> decl pattern var), prebuilt by the seal pass; entering one pushes
    /// an evidence scope.
    local_schemes: *const collections.DenseMap(u32, Var),
    /// Checked nested function expr -> `SchemeUseRecord` index for the
    /// construction edge that instantiated it.
    nested_function_uses: *const collections.DenseMap(u32, u32),
    /// Checked nested function expr -> its own type variable, for each
    /// function that owns a callable-derived scope
    /// (`collectCallableDerivedSchemes`). A template's root function is never
    /// one: its template's own parameters already answer for its callable.
    callable_derived_schemes: *const collections.DenseMap(u32, Var),
    value_refs: std.ArrayList(ResolvedValueRefId),
    dispatch_refs: std.ArrayList(static_dispatch.StaticDispatchPlanId),
    iterator_refs: std.ArrayList(static_dispatch.IteratorForPlanId),
    /// Scope of each collected ref, parallel to the three ref lists.
    value_ref_scopes: std.ArrayList(DispatchScope),
    dispatch_ref_scopes: std.ArrayList(DispatchScope),
    iterator_ref_scopes: std.ArrayList(DispatchScope),
    scheme_use_sites: std.ArrayList(CollectedSchemeUseSite),
    scheme_use_scopes: std.ArrayList(DispatchScope),
    scope_sites: std.ArrayList(CollectedScopeConstructionSite),
    specialization_relations: std.ArrayList(SpecializationInterfaceRelation),
    specialization_types: std.ArrayList(CheckedTypeId),
    template_root_expr: ?CIR.Expr.Idx = null,
    /// Pooled across templates (ids are global); the stack resets per template.
    scopes: std.ArrayList(DispatchRefScope),
    scope_by_checked_expr: collections.DenseMap(CIR.Expr.Idx, DispatchScopeId),
    scope_stack: std.ArrayList(DispatchScopeId),
    visited_exprs: collections.DenseMap(CIR.Expr.Idx, void),
    visited_patterns: collections.DenseMap(CIR.Pattern.Idx, void),
    visited_statements: collections.DenseMap(CIR.Statement.Idx, void),
    work: std.ArrayList(Work) = .empty,

    fn init(
        allocator: Allocator,
        module: TypedCIR.Module,
        checked_types: *const CheckedTypePublication,
        bodies: CheckedBodies,
        diagnostics: *const body_analyses.NodeBits,
        static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
        local_schemes: *const collections.DenseMap(u32, Var),
        nested_function_uses: *const collections.DenseMap(u32, u32),
        callable_derived_schemes: *const collections.DenseMap(u32, Var),
    ) CheckedTemplateRefCollector {
        return .{
            .allocator = allocator,
            .module = module,
            .checked_types = checked_types,
            .bodies = bodies,
            .diagnostics = diagnostics,
            .static_dispatch_plans = static_dispatch_plans,
            .local_schemes = local_schemes,
            .nested_function_uses = nested_function_uses,
            .callable_derived_schemes = callable_derived_schemes,
            .value_refs = .empty,
            .dispatch_refs = .empty,
            .iterator_refs = .empty,
            .value_ref_scopes = .empty,
            .dispatch_ref_scopes = .empty,
            .iterator_ref_scopes = .empty,
            .scheme_use_sites = .empty,
            .scheme_use_scopes = .empty,
            .scope_sites = .empty,
            .specialization_relations = .empty,
            .specialization_types = .empty,
            .scopes = .empty,
            .scope_by_checked_expr = collections.DenseMap(CIR.Expr.Idx, DispatchScopeId).init(allocator),
            .scope_stack = .empty,
            .visited_exprs = collections.DenseMap(CIR.Expr.Idx, void).init(allocator),
            .visited_patterns = collections.DenseMap(CIR.Pattern.Idx, void).init(allocator),
            .visited_statements = collections.DenseMap(CIR.Statement.Idx, void).init(allocator),
        };
    }

    fn deinit(self: *CheckedTemplateRefCollector) void {
        self.work.deinit(self.allocator);
        self.visited_statements.deinit();
        self.visited_patterns.deinit();
        self.visited_exprs.deinit();
        self.dispatch_refs.deinit(self.allocator);
        self.iterator_refs.deinit(self.allocator);
        self.value_refs.deinit(self.allocator);
        self.value_ref_scopes.deinit(self.allocator);
        self.dispatch_ref_scopes.deinit(self.allocator);
        self.iterator_ref_scopes.deinit(self.allocator);
        self.scheme_use_sites.deinit(self.allocator);
        self.scheme_use_scopes.deinit(self.allocator);
        self.scope_sites.deinit(self.allocator);
        self.specialization_relations.deinit(self.allocator);
        self.specialization_types.deinit(self.allocator);
        self.scopes.deinit(self.allocator);
        self.scope_by_checked_expr.deinit();
        self.scope_stack.deinit(self.allocator);
    }

    fn clear(self: *CheckedTemplateRefCollector) void {
        self.value_refs.clearRetainingCapacity();
        self.dispatch_refs.clearRetainingCapacity();
        self.iterator_refs.clearRetainingCapacity();
        self.value_ref_scopes.clearRetainingCapacity();
        self.dispatch_ref_scopes.clearRetainingCapacity();
        self.iterator_ref_scopes.clearRetainingCapacity();
        self.scheme_use_sites.clearRetainingCapacity();
        self.scheme_use_scopes.clearRetainingCapacity();
        self.scope_sites.clearRetainingCapacity();
        self.specialization_relations.clearRetainingCapacity();
        self.specialization_types.clearRetainingCapacity();
        self.template_root_expr = null;
        // `scopes` pools across templates; only the stack resets.
        self.scope_stack.clearRetainingCapacity();
        self.visited_exprs.clearRetainingCapacity();
        self.visited_patterns.clearRetainingCapacity();
        self.visited_statements.clearRetainingCapacity();
    }

    fn currentScopeId(self: *const CheckedTemplateRefCollector) ?DispatchScopeId {
        if (self.scope_stack.items.len == 0) return null;
        return self.scope_stack.items[self.scope_stack.items.len - 1];
    }

    fn currentScope(self: *const CheckedTemplateRefCollector) DispatchScope {
        return if (self.currentScopeId()) |id| .{ .generalized = id } else .root;
    }

    fn appendValueRef(self: *CheckedTemplateRefCollector, ref_id: ResolvedValueRefId) Allocator.Error!void {
        try self.value_refs.append(self.allocator, ref_id);
        try self.value_ref_scopes.append(self.allocator, self.currentScope());
    }

    fn appendDispatchRef(self: *CheckedTemplateRefCollector, plan_id: static_dispatch.StaticDispatchPlanId) Allocator.Error!void {
        try self.dispatch_refs.append(self.allocator, plan_id);
        try self.dispatch_ref_scopes.append(self.allocator, self.currentScope());
    }

    /// The type a lambda's body delivers at its function's return. A body
    /// whose type is the function's result delivers it directly. A body whose
    /// type differs is a composed `?` result: its value crosses the explicit
    /// return boundary into the function's `Try`, so what reaches the return
    /// is that `Try`, never the body's narrower row.
    fn lambdaDeliveredReturnType(
        self: *const CheckedTemplateRefCollector,
        fn_ty: CheckedTypeId,
        body: CIR.Expr.Idx,
    ) CheckedTypeId {
        const body_ty = self.bodies.valueType(body);
        const ret_ty = checkedFunctionPayload(&self.checked_types.store, fn_ty, "checked lambda specialization relation").ret;
        return if (body_ty == ret_ty) body_ty else ret_ty;
    }

    fn appendProcedureRelation(
        self: *CheckedTemplateRefCollector,
        expr_id: CIR.Expr.Idx,
        fn_ty: CheckedTypeId,
        body_ret_ty: CheckedTypeId,
        owns_scope: bool,
    ) Allocator.Error!void {
        if (self.diagnostics.isSet(@backingInt(expr_id))) return;
        try self.specialization_relations.append(self.allocator, .{
            .scope = self.currentScope(),
            .data = .{ .procedure = .{
                .fn_ty = fn_ty,
                .body_ret_ty = body_ret_ty,
                .owns_scope = owns_scope,
            } },
        });
    }

    fn appendCallRelation(
        self: *CheckedTemplateRefCollector,
        expr_id: CIR.Expr.Idx,
    ) Allocator.Error!void {
        if (self.diagnostics.isSet(@backingInt(expr_id))) return;
        const call = self.bodies.exprData(expr_id).call;
        const start: u32 = @intCast(self.specialization_types.items.len);
        try self.specialization_types.ensureUnusedCapacity(self.allocator, call.args.len);
        for (call.args) |arg| {
            self.specialization_types.appendAssumeCapacity(self.bodies.valueType(arg));
        }
        try self.specialization_relations.append(self.allocator, .{
            .scope = self.currentScope(),
            .data = .{ .call = .{
                .callable_ty = self.bodies.callFnType(expr_id),
                .callee_ty = self.bodies.valueType(call.func),
                .ret_ty = self.bodies.exprType(expr_id),
                .args = .{ .start = start, .len = @intCast(call.args.len) },
                .direct_target = self.bodies.callDirectTarget(expr_id),
            } },
        });
    }

    /// Collect the references reachable from a checked expression. The walk
    /// keeps its own work stack, so body nesting depth never becomes native
    /// call depth; children are pushed in reverse so they are collected in
    /// source order, and post-actions are pushed before them so they run once
    /// every child is collected.
    fn collectExpr(self: *CheckedTemplateRefCollector, expr_id: CIR.Expr.Idx) Allocator.Error!void {
        const base_len = self.work.items.len;
        try self.work.append(self.allocator, .{ .expr = expr_id });
        while (self.work.items.len > base_len) {
            switch (self.work.pop().?) {
                .expr => |id| try self.visitExpr(id),
                .pattern => |id| try self.visitPattern(id),
                .statement => |id| try self.visitStatement(id),
                .generated_interpolation_segments => |id| try self.visitInterpolationChildren(id),
                .literal_pattern => |id| try self.visitLiteralPattern(id),
                .call_relation => |id| try self.appendCallRelation(id),
                .pop_scope => _ = self.scope_stack.pop(),
            }
        }
    }

    const Work = union(enum) {
        expr: CIR.Expr.Idx,
        pattern: CIR.Pattern.Idx,
        statement: CIR.Statement.Idx,
        generated_interpolation_segments: CIR.Expr.Idx,
        /// A custom literal pattern's equality and conversion plans.
        literal_pattern: CIR.Pattern.Idx,
        /// Append a call's relation once its callee and arguments are collected.
        call_relation: CIR.Expr.Idx,
        /// Leave a generalized local function's evidence scope.
        pop_scope,
    };

    /// Children are pushed in source order between `beginChildren` and
    /// `endChildren`, which reverses them on the work stack.
    fn beginChildren(self: *const CheckedTemplateRefCollector) usize {
        return self.work.items.len;
    }

    fn endChildren(self: *CheckedTemplateRefCollector, start: usize) void {
        std.mem.reverse(Work, self.work.items[start..]);
    }

    fn pushChild(self: *CheckedTemplateRefCollector, work: Work) Allocator.Error!void {
        try self.work.append(self.allocator, work);
    }

    fn visitExpr(self: *CheckedTemplateRefCollector, expr_id: CIR.Expr.Idx) Allocator.Error!void {
        const entry = try self.visited_exprs.getOrPut(expr_id);
        if (entry.found_existing) return;

        const raw_expr = @backingInt(expr_id);
        if (self.nested_function_uses.get(raw_expr)) |record_idx| {
            try self.scheme_use_sites.append(self.allocator, .{
                .record_idx = record_idx,
                .checked_expr = expr_id,
            });
            // The construction edge lives in the enclosing scope; the nested
            // function's own evidence scope begins below.
            try self.scheme_use_scopes.append(self.allocator, self.currentScope());
        }

        const local_scheme = self.local_schemes.get(raw_expr) orelse
            if (self.template_root_expr != expr_id) self.callable_derived_schemes.get(raw_expr) else null;
        if (local_scheme) |scheme_var| {
            const parent = self.currentScopeId();
            const scheme_root = self.checked_types.rootForSourceVar(self.module, scheme_var) orelse
                checkedArtifactInvariant("generalized local dispatch scope had no published checked scheme root", .{});
            const scope_entry = try self.scope_by_checked_expr.getOrPut(expr_id);
            const scope_id = if (scope_entry.found_existing) blk: {
                const existing = self.scopes.items[@backingInt(scope_entry.value_ptr.*)];
                if (existing.parent != parent or existing.scheme_var != scheme_var or existing.scheme_root != scheme_root) {
                    checkedArtifactInvariant("generalized local dispatch scope has inconsistent checked ownership", .{});
                }
                break :blk scope_entry.value_ptr.*;
            } else blk: {
                const id: DispatchScopeId = @fromBackingInt(@intCast(@as(u32, @intCast(self.scopes.items.len))));
                scope_entry.value_ptr.* = id;
                try self.scopes.append(self.allocator, .{
                    .parent = parent,
                    .scheme_var = scheme_var,
                    .scheme_root = scheme_root,
                    .checked_expr = expr_id,
                });
                break :blk id;
            };
            try self.scope_sites.append(self.allocator, .{
                .scope = scope_id,
                .checked_expr = expr_id,
            });
            try self.scope_stack.append(self.allocator, scope_id);
        }
        // The scope stays pushed until every child has been collected.
        if (local_scheme != null) try self.work.append(self.allocator, .pop_scope);

        const bodies = self.bodies;
        const data = bodies.exprData(expr_id);
        const expr_ty = bodies.exprType(expr_id);
        // An erroneous callable publishes no procedure relation, and its type
        // need not be a function.
        const publishes_procedure = !self.diagnostics.isSet(@backingInt(expr_id));
        if (data == .lambda) {
            if (publishes_procedure) try self.appendProcedureRelation(
                expr_id,
                expr_ty,
                self.lambdaDeliveredReturnType(expr_ty, data.lambda.body),
                self.template_root_expr == expr_id or local_scheme != null,
            );
        } else if (data == .closure) {
            const closure = data.closure;
            const lambda_data = bodies.exprData(closure.lambda);
            if (lambda_data != .lambda) {
                checkedArtifactInvariant("checked closure specialization relation did not reference a lambda", .{});
            }
            if (publishes_procedure) try self.appendProcedureRelation(
                expr_id,
                expr_ty,
                self.lambdaDeliveredReturnType(expr_ty, lambda_data.lambda.body),
                self.template_root_expr == expr_id or local_scheme != null,
            );
        }
        const raw = @backingInt(expr_id);
        switch (data) {
            .lookup_local, .lookup_external, .lookup_required => {
                if (bodies.resolvedRef(expr_id)) |ref_id| try self.appendValueRef(ref_id);
            },
            .dispatch_call,
            .method_eq,
            .type_dispatch_call,
            => {
                const id = bodies.dispatchPlan(raw) orelse checkedArtifactInvariant("checked dispatch expression reached template closure collection without a static-dispatch plan", .{});
                try self.appendDispatchRef(id);
                try self.pushStaticDispatchPlanArgs(id);
            },
            .interpolation => |interpolation| if (bodies.interpolationIsBuiltinStr(expr_id)) {
                const children = self.beginChildren();
                try self.pushChild(.{ .expr = interpolation.first });
                for (interpolation.parts) |part| try self.pushChild(.{ .expr = part });
                self.endChildren(children);
            } else {
                const id = bodies.dispatchPlan(raw) orelse checkedArtifactInvariant("checked interpolation expression reached template closure collection without a static-dispatch plan", .{});
                try self.appendDispatchRef(id);
                try self.pushStaticDispatchPlanArgs(id);
            },
            .numeral => {
                // Builtin-targeted literals carry no plan (their bits are
                // produced at monotype lowering); only custom conversions do.
                if (bodies.numeralPlan(raw)) |id| {
                    try self.appendDispatchRef(id);
                    try self.pushStaticDispatchPlanArgs(id);
                }
            },
            .str => |segments| if (bodies.quoteIsCustom(raw)) {
                const id = bodies.quotePlan(raw) orelse checkedArtifactInvariant("checked from_quote expression reached template closure collection without a dispatch plan", .{});
                try self.appendDispatchRef(id);
                try self.pushStaticDispatchPlanArgs(id);
            } else {
                const children = self.beginChildren();
                for (segments) |segment| try self.pushChild(.{ .expr = segment });
                self.endChildren(children);
            },
            .list,
            .tuple,
            => |items| {
                const children = self.beginChildren();
                for (items) |item| try self.pushChild(.{ .expr = item });
                self.endChildren(children);
            },
            .match_ => |match| {
                const children = self.beginChildren();
                try self.pushChild(.{ .expr = match.cond });
                for (match.branches) |branch_idx| {
                    const branch = bodies.matchBranch(branch_idx);
                    for (branch.patterns) |branch_pattern| try self.pushChild(.{ .pattern = bodies.matchBranchPattern(branch_pattern).pattern });
                    if (branch.guard) |guard| try self.pushChild(.{ .expr = guard });
                    try self.pushChild(.{ .expr = branch.value });
                }
                self.endChildren(children);
            },
            .if_ => |if_| {
                const children = self.beginChildren();
                for (if_.branches) |branch_idx| {
                    const branch = bodies.ifBranch(branch_idx);
                    try self.pushChild(.{ .expr = branch.cond });
                    try self.pushChild(.{ .expr = branch.body });
                }
                try self.pushChild(.{ .expr = if_.final_else });
                self.endChildren(children);
            },
            .call => |call| {
                if (bodies.callDirectTarget(expr_id)) |target| try self.appendValueRef(target);
                try self.work.append(self.allocator, .{ .call_relation = expr_id });
                const children = self.beginChildren();
                try self.pushChild(.{ .expr = call.func });
                for (call.args) |arg| try self.pushChild(.{ .expr = arg });
                self.endChildren(children);
            },
            .record => |record| {
                const children = self.beginChildren();
                if (record.ext) |ext| try self.pushChild(.{ .expr = ext });
                for (record.fields) |field| try self.pushChild(.{ .expr = bodies.recordFieldValue(field) });
                self.endChildren(children);
            },
            .block => |block| {
                const children = self.beginChildren();
                for (block.statements) |statement| try self.pushChild(.{ .statement = statement });
                try self.pushChild(.{ .expr = block.final_expr });
                self.endChildren(children);
            },
            .tag => |tag| {
                const children = self.beginChildren();
                for (tag.args) |arg| try self.pushChild(.{ .expr = arg });
                self.endChildren(children);
            },
            .nominal => |nominal| try self.pushChild(.{ .expr = nominal.backing_expr }),
            .closure => |closure| try self.pushChild(.{ .expr = closure.lambda }),
            .lambda => |lambda| {
                const children = self.beginChildren();
                for (lambda.args) |arg| try self.pushChild(.{ .pattern = arg });
                try self.pushChild(.{ .expr = lambda.body });
                self.endChildren(children);
            },
            .binop => |binop| {
                const children = self.beginChildren();
                try self.pushChild(.{ .expr = binop.lhs });
                try self.pushChild(.{ .expr = binop.rhs });
                self.endChildren(children);
            },
            .unary_minus => |child| try self.pushChild(.{ .expr = child }),
            .field_access => |field| try self.pushChild(.{ .expr = field.receiver }),
            .structural_eq => |eq| {
                const children = self.beginChildren();
                try self.pushChild(.{ .expr = eq.lhs });
                try self.pushChild(.{ .expr = eq.rhs });
                self.endChildren(children);
            },
            .structural_hash => |h| {
                const children = self.beginChildren();
                try self.pushChild(.{ .expr = h.value });
                try self.pushChild(.{ .expr = h.hasher });
                self.endChildren(children);
            },
            .tuple_access => |access| try self.pushChild(.{ .expr = access.tuple }),
            .dbg => |child| try self.pushChild(.{ .expr = child }),
            .expect_err => |expect_err| try self.pushChild(.{ .expr = expect_err.expr }),
            .expect => |child| try self.pushChild(.{ .expr = child }),
            .break_ => {},
            .return_ => |ret| {
                // `ret.lambda` is the enclosing lambda context for early-return
                // lowering, not an owned child expression.
                try self.pushChild(.{ .expr = ret.expr });
            },
            .for_ => |for_| {
                const plan_id = bodies.iteratorForPlan(raw) orelse checkedArtifactInvariant("checked for expression reached template closure collection without an iterator-for plan", .{});
                const children = self.beginChildren();
                try self.pushIteratorForPlan(plan_id);
                try self.pushChild(.{ .pattern = for_.pattern });
                try self.pushChild(.{ .expr = for_.expr });
                try self.pushChild(.{ .expr = for_.body });
                self.endChildren(children);
            },
            .hosted_lambda => |hosted| {
                const children = self.beginChildren();
                for (hosted.args) |arg| try self.pushChild(.{ .pattern = arg });
                self.endChildren(children);
            },
            .run_low_level => |run| {
                const children = self.beginChildren();
                for (run.args) |arg| try self.pushChild(.{ .expr = arg });
                self.endChildren(children);
            },
            .str_segment,
            .bytes_literal,
            .empty_list,
            .empty_record,
            .zero_argument_tag,
            .runtime_error,
            .crash,
            .ellipsis,
            .anno_only,
            => {},
        }
    }

    fn pushStaticDispatchPlanArgs(
        self: *CheckedTemplateRefCollector,
        plan_id: static_dispatch.StaticDispatchPlanId,
    ) Allocator.Error!void {
        const raw = @backingInt(plan_id);
        if (raw >= self.static_dispatch_plans.plans.len) {
            checkedArtifactInvariant("checked template static-dispatch plan id was outside the plan table", .{});
        }
        const plan = self.static_dispatch_plans.plans[raw];
        const children = self.beginChildren();
        for (plan.argsSlice(self.static_dispatch_plans)) |arg| switch (arg) {
            .checked_expr => |expr| try self.pushChild(.{ .expr = expr }),
            .generated_interpolation_segments => |expr| try self.pushChild(.{ .generated_interpolation_segments = expr }),
            .generated_numeral, .generated_quote, .literal_pattern_value, .literal_pattern_conversion => {},
        };
        self.endChildren(children);
    }

    fn visitInterpolationChildren(self: *CheckedTemplateRefCollector, expr_id: CIR.Expr.Idx) Allocator.Error!void {
        const data = self.bodies.exprData(expr_id);
        if (data != .interpolation) {
            checkedArtifactInvariant("generated interpolation segments operand pointed at non-interpolation expression", .{});
        }
        const interpolation = data.interpolation;
        const children = self.beginChildren();
        try self.pushChild(.{ .expr = interpolation.first });
        for (interpolation.parts) |part| try self.pushChild(.{ .expr = part });
        self.endChildren(children);
    }

    /// A custom literal pattern compares the matched value with its literal
    /// converted at the pattern's type: its equality plan, then the
    /// conversion's plan.
    fn visitLiteralPattern(self: *CheckedTemplateRefCollector, pattern_id: CIR.Pattern.Idx) Allocator.Error!void {
        const guard = self.bodies.literalPatternGuard(pattern_id) orelse
            checkedArtifactInvariant("a literal pattern guard was collected for a pattern compared directly", .{});
        const equality = guard.equality_plan orelse checkedArtifactInvariant("a custom literal pattern reached template closure collection without an equality plan", .{});
        try self.appendDispatchRef(equality);
        if (guard.conversion.plan) |conversion| try self.appendDispatchRef(conversion);
    }

    /// Record an iterator-for plan and push its dispatch-call operands, in
    /// source order, among the children currently being pushed.
    fn pushIteratorForPlan(
        self: *CheckedTemplateRefCollector,
        plan_id: static_dispatch.IteratorForPlanId,
    ) Allocator.Error!void {
        const raw = @backingInt(plan_id);
        if (raw >= self.static_dispatch_plans.iterator_for_plans.len) {
            checkedArtifactInvariant("checked template iterator-for plan id was outside the plan table", .{});
        }
        try self.iterator_refs.append(self.allocator, plan_id);
        try self.iterator_ref_scopes.append(self.allocator, self.currentScope());
        const plan = self.static_dispatch_plans.iterator_for_plans[raw];
        try self.pushIteratorDispatchCall(plan.iter);
        try self.pushIteratorDispatchCall(plan.next);
    }

    fn pushIteratorDispatchCall(
        self: *CheckedTemplateRefCollector,
        call: static_dispatch.IteratorDispatchCall,
    ) Allocator.Error!void {
        for (call.argsSlice(self.static_dispatch_plans)) |arg| switch (arg) {
            .checked_expr => |expr| try self.pushChild(.{ .expr = expr }),
            .loop_iterator_state => {},
        };
    }

    /// Collect the references reachable from a checked pattern.
    fn collectPattern(self: *CheckedTemplateRefCollector, pattern_id: CIR.Pattern.Idx) Allocator.Error!void {
        const base_len = self.work.items.len;
        try self.work.append(self.allocator, .{ .pattern = pattern_id });
        while (self.work.items.len > base_len) {
            switch (self.work.pop().?) {
                .expr => |id| try self.visitExpr(id),
                .pattern => |id| try self.visitPattern(id),
                .statement => |id| try self.visitStatement(id),
                .generated_interpolation_segments => |id| try self.visitInterpolationChildren(id),
                .literal_pattern => |id| try self.visitLiteralPattern(id),
                .call_relation => |id| try self.appendCallRelation(id),
                .pop_scope => _ = self.scope_stack.pop(),
            }
        }
    }

    fn visitPattern(self: *CheckedTemplateRefCollector, pattern_id: CIR.Pattern.Idx) Allocator.Error!void {
        const entry = try self.visited_patterns.getOrPut(pattern_id);
        if (entry.found_existing) return;

        const bodies = self.bodies;
        const children = self.beginChildren();
        switch (bodies.patternData(pattern_id)) {
            .as => |as| try self.pushChild(.{ .pattern = as.pattern }),
            .applied_tag => |tag| {
                for (tag.args) |arg| try self.pushChild(.{ .pattern = arg });
            },
            .nominal => |nominal| try self.pushChild(.{ .pattern = nominal.backing_pattern }),
            .record_destructure => |destructs| {
                for (destructs) |destruct| try self.pushChild(.{ .pattern = bodies.recordDestructPattern(destruct) });
            },
            .list => |list| {
                for (list.patterns) |child| try self.pushChild(.{ .pattern = child });
                if (list.rest) |rest| {
                    if (rest.pattern) |child| try self.pushChild(.{ .pattern = child });
                }
            },
            .tuple => |items| {
                for (items) |child| try self.pushChild(.{ .pattern = child });
            },
            .str_interpolation => |str| {
                var offset: u32 = 0;
                while (offset < str.steps.span.len) : (offset += 1) {
                    if (bodies.strPatternStep(str.steps, offset).capture) |capture| try self.pushChild(.{ .pattern = capture });
                }
            },
            .numeral_literal, .str_literal => if (bodies.literalPatternIsCustom(pattern_id)) try self.pushChild(.{ .literal_pattern = pattern_id }),
            .assign,
            .underscore,
            .runtime_error,
            => {},
        }
        self.endChildren(children);
    }

    fn visitStatement(self: *CheckedTemplateRefCollector, statement_id: CIR.Statement.Idx) Allocator.Error!void {
        const entry = try self.visited_statements.getOrPut(statement_id);
        if (entry.found_existing) return;

        const children = self.beginChildren();
        switch (self.bodies.statementData(statement_id)) {
            .decl => |decl| {
                try self.pushChild(.{ .pattern = decl.pattern });
                try self.pushChild(.{ .expr = decl.expr });
            },
            // The promoted procedure is collected as its own template.
            .promoted_proc => {},
            .var_ => |var_| {
                try self.pushChild(.{ .pattern = var_.pattern });
                try self.pushChild(.{ .expr = var_.expr });
            },
            .var_uninitialized => |var_| {
                try self.pushChild(.{ .pattern = var_.pattern });
            },
            .reassign => |reassign| {
                try self.pushChild(.{ .pattern = reassign.pattern });
                try self.pushChild(.{ .expr = reassign.expr });
            },
            inline .dbg, .expr, .expect => |child| try self.pushChild(.{ .expr = child }),
            .return_ => |ret| {
                // `ret.lambda` is the enclosing lambda context for early-return
                // lowering, not an owned child expression.
                try self.pushChild(.{ .expr = ret.expr });
            },
            .for_ => |for_| {
                const plan_id = self.bodies.iteratorForPlan(@backingInt(statement_id)) orelse checkedArtifactInvariant("checked for statement reached template closure collection without an iterator-for plan", .{});
                try self.pushIteratorForPlan(plan_id);
                try self.pushChild(.{ .pattern = for_.pattern });
                try self.pushChild(.{ .expr = for_.expr });
                try self.pushChild(.{ .expr = for_.body });
            },
            inline .while_, .infinite_loop, .breakable_loop => |while_| {
                try self.pushChild(.{ .expr = while_.cond });
                try self.pushChild(.{ .expr = while_.body });
            },
            .crash,
            .break_,
            .rejected_method_decl,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => {},
        }
        self.endChildren(children);
    }
};

/// Public `TopLevelUseSummaryRef` declaration.
pub const TopLevelUseSummaryRef = struct {
    start: u32 = 0,
    len: u32 = 0,
};

/// Public `NestedProcKind` declaration.
pub const NestedProcKind = enum {
    local_function,
    closure,
    desugared_closure,
};

/// Producer-authored source of a nested procedure's evidence vector.
pub const NestedProcEvidenceSource = enum {
    /// The site does not introduce a dispatch scope and inherits its lexical
    /// evidence unchanged.
    inherited,
    /// Checking recorded an exact scheme-instantiation edge for the site.
    checked_site,
};

/// Root that lexically owns a nested procedure site. Almost every site sits
/// inside a checked procedure template's body (or an entry wrapper's generated
/// body, which borrows its template's identity). Defaulted-field expressions
/// (design.md "Defaulted Fields") are the exception: they belong to no
/// template—each is lowered standalone at every construction site that omits
/// its field—so each default expression owns the sites inside it.
pub const NestedProcSiteOwner = union(enum) {
    template: canonical.ProcedureTemplateRef,
    /// The defaulted-field expression that owns the site.
    default_root: CIR.Expr.Idx,
};

/// The id of a nested procedure site within its owner: the node id of the
/// lambda, closure or hosted lambda expression it constructs a procedure at.
pub fn nestedProcSiteId(expr: CIR.Expr.Idx) canonical.NestedProcSiteId {
    return @fromBackingInt(@backingInt(expr));
}

/// The expression a nested procedure site constructs its procedure at.
pub fn nestedProcSiteExpr(site: canonical.NestedProcSiteId) CIR.Expr.Idx {
    return @fromBackingInt(@backingInt(site));
}

/// One lambda, closure or hosted lambda an owner's body constructs a
/// procedure at. Its id is its expression's (`nestedProcSiteId`).
pub const NestedProcSite = struct {
    /// Exact generalized-local scope lexically owning this site, or the
    /// template root when the site is outside every generalized local.
    lexical_scope: DispatchScope,
    evidence_source: NestedProcEvidenceSource,
    /// The construction site's checked evidence when
    /// `evidence_source == .checked_site`; empty otherwise.
    evidence: static_dispatch.EvidenceSpan,
    kind: NestedProcKind,
    checked_expr: CIR.Expr.Idx,

    pub fn id(self: NestedProcSite) canonical.NestedProcSiteId {
        return nestedProcSiteId(self.checked_expr);
    }
};

/// The nested procedure sites of one owner's body, in scan order, and the
/// lexical facts of the same scan that the module's runtime captures read
/// (`ModuleNestedProcSites`). Computed on first demand per owner
/// (`ModuleAnalyses.nestedProcSites`).
pub const OwnerNestedProcSites = struct {
    sites: []const NestedProcSite = &.{},
    /// Positions in `sites`, ordered by expression.
    by_expr: []const u32 = &.{},
    /// Per site: the position of the site whose body lexically encloses it.
    parents: []const ?u32 = &.{},
    /// Every binder the owner's body binds, with the position of the
    /// innermost site whose body binds it; null for the owner's own body.
    binders: []const BinderSite = &.{},
    /// Each local procedure a site's own body selects.
    selections: []const SiteSelection = &.{},

    pub const BinderSite = struct {
        binder: CIR.Pattern.Idx,
        site: ?u32,
    };

    pub const SiteSelection = struct {
        site: u32,
        proc_expr: CIR.Expr.Idx,
    };

    /// The position of the site at `expr`.
    pub fn position(self: *const OwnerNestedProcSites, expr: CIR.Expr.Idx) ?u32 {
        var low: usize = 0;
        var high: usize = self.by_expr.len;
        while (low < high) {
            const mid = low + (high - low) / 2;
            const candidate = self.sites[self.by_expr[mid]].checked_expr;
            if (@backingInt(candidate) == @backingInt(expr)) return self.by_expr[mid];
            if (@backingInt(candidate) < @backingInt(expr)) low = mid + 1 else high = mid;
        }
        return null;
    }

    /// The site `site`, when this owner constructs one there.
    pub fn find(self: *const OwnerNestedProcSites, site: canonical.NestedProcSiteId) ?NestedProcSite {
        const found = self.position(nestedProcSiteExpr(site)) orelse return null;
        return self.sites[found];
    }

    pub fn destroy(self: *OwnerNestedProcSites, allocator: Allocator) void {
        allocator.free(self.sites);
        allocator.free(self.by_expr);
        allocator.free(self.parents);
        allocator.free(self.binders);
        allocator.free(self.selections);
        allocator.destroy(self);
    }
};

/// The nested procedure sites of a module's owners, keyed by expression:
/// which owners construct a procedure at each site expression and the
/// binders of enclosing frames whose values that procedure needs at runtime
/// (its runtime captures). A closure's own captures come first, in their
/// checked order; after them come the binders that constructing the local
/// procedures this procedure (or a procedure nested in it) selects requires,
/// ordered by binder id. Computed on first demand per module
/// (`ModuleAnalyses.moduleNestedProcSites`).
pub const ModuleNestedProcSites = struct {
    /// Every site expression of every owner, ascending.
    exprs: []const CIR.Expr.Idx = &.{},
    /// Per expression: the first template, in template order, whose body
    /// constructs a procedure there; null when only defaults do.
    first_templates: []const ?canonical.CheckedProcedureTemplateId = &.{},
    /// Per expression: how many owners construct a procedure there.
    owner_counts: []const u32 = &.{},
    /// Per expression: its runtime captures, a range of `captures`.
    capture_spans: []const artifact_serialize.Span = &.{},
    captures: []const CheckedCapture = &.{},
    /// Each closure site's lambda with its closure's expression, ordered by
    /// lambda: a closure's lambda names the closure's site.
    closure_lambdas: []const ClosureLambda = &.{},

    pub const ClosureLambda = struct {
        lambda: CIR.Expr.Idx,
        closure: CIR.Expr.Idx,
    };

    /// The position of site expression `expr`, or of the closure whose
    /// lambda `expr` is.
    pub fn position(self: *const ModuleNestedProcSites, expr: CIR.Expr.Idx) ?usize {
        if (exprPosition(self.exprs, expr)) |found| return found;
        var low: usize = 0;
        var high: usize = self.closure_lambdas.len;
        while (low < high) {
            const mid = low + (high - low) / 2;
            const candidate = self.closure_lambdas[mid].lambda;
            if (@backingInt(candidate) == @backingInt(expr)) return exprPosition(self.exprs, self.closure_lambdas[mid].closure);
            if (@backingInt(candidate) < @backingInt(expr)) low = mid + 1 else high = mid;
        }
        return null;
    }

    /// The runtime captures of the procedure constructed at `expr` (a site
    /// expression or a closure site's lambda).
    pub fn runtimeCaptures(self: *const ModuleNestedProcSites, expr: CIR.Expr.Idx) ?[]const CheckedCapture {
        const found = self.position(expr) orelse return null;
        const span = self.capture_spans[found];
        return self.captures[span.start..][0..span.len];
    }

    pub fn destroy(self: *ModuleNestedProcSites, allocator: Allocator) void {
        allocator.free(self.exprs);
        allocator.free(self.first_templates);
        allocator.free(self.owner_counts);
        allocator.free(self.capture_spans);
        allocator.free(self.captures);
        allocator.free(self.closure_lambdas);
        allocator.destroy(self);
    }

    fn exprPosition(exprs: []const CIR.Expr.Idx, expr: CIR.Expr.Idx) ?usize {
        var low: usize = 0;
        var high: usize = exprs.len;
        while (low < high) {
            const mid = low + (high - low) / 2;
            if (@backingInt(exprs[mid]) == @backingInt(expr)) return mid;
            if (@backingInt(exprs[mid]) < @backingInt(expr)) low = mid + 1 else high = mid;
        }
        return null;
    }
};

/// Public `ProcTarget` declaration.
pub const ProcTarget = union(enum) {
    roc,
    hosted,
    intrinsic,
    entry,
    comptime_only,
};

/// Public `CheckedProcedureTemplate` declaration.
pub const CheckedProcedureTemplate = struct {
    proc_base: canonical.ProcBaseKeyRef,
    template_id: canonical.CheckedProcedureTemplateId,
    body: CheckedProcedureBody,
    checked_fn_scheme: CheckedTypeSchemeId,
    checked_fn_root: CheckedTypeId,
    /// Every call plan the template's body reaches: a range of
    /// `CheckedProcedureTemplateTable.dispatch_plan_refs`. Dispatch
    /// resolution classifies them (`CheckedDispatch.templateRelations`).
    static_dispatch_plans: StaticDispatchPlanTableRef,
    /// Range into
    /// `CheckedProcedureTemplateTable.specialization_interface_relations`.
    specialization_interface_relations: artifact_serialize.Span = .{},
    resolved_value_refs: ResolvedValueRefTableRef,
    top_level_value_uses: TopLevelUseSummaryRef,
    target: ProcTarget,
    /// The low-level operation this template's body runs over its parameters,
    /// for a Builtin definition the Builtin low-level transform produced.
    /// Post-check stages read the operation from here; they never recognize a
    /// low-level wrapper from its body.
    provided_low_level: ?base.LowLevel = null,
};

fn checkedTypeIsClosedTagRow(
    checked_types: *const CheckedTypeStore,
    root: CheckedTypeId,
) bool {
    var remaining = checked_types.typeCount();
    var current = root;
    while (true) {
        switch (checked_types.payload(current)) {
            .alias => |alias| current = alias.backing,
            .tag_union => |tag_union| current = tag_union.ext,
            .empty_tag_union => return true,
            .flex, .rigid => |variable| return variable.row_default == .empty_tag_union,
            .pending,
            .field_kind,
            .err,
            .record,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            => return false,
        }
        if (remaining == 0) {
            checkedArtifactInvariant("hosted Try error row chain was cyclic", .{});
        }
        remaining -= 1;
    }
}

test "hosted Try adapter capability recognizes only closed structural error rows" {
    const allocator = std.testing.allocator;

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();

    var store = CheckedTypeStore{};
    defer store.deinit(allocator);

    try attachTestSynthesizedKeys(allocator, &store, &names);

    const empty_row = try store.appendSyntheticPayloadRoot(allocator, .empty_tag_union);
    const non_row = try store.appendSyntheticPayloadRoot(allocator, .empty_record);
    const open_tail = try store.reserveSyntheticTypeRoot(allocator);
    try testFillSyntheticVariableRoot(allocator, &store, open_tail, .{ .flex = .{} });
    const defaulted_tail = try store.reserveSyntheticTypeRoot(allocator);
    try testFillSyntheticVariableRoot(allocator, &store, defaulted_tail, .{ .flex = .{ .row_default = .empty_tag_union } });

    const error_tag = try names.internTagLabel("HostErr");
    const closed_tags = try allocator.alloc(CheckedTag, 1);
    closed_tags[0] = .{ .name = error_tag };
    const closed_row = try store.appendSyntheticPayloadRoot(allocator, .{ .tag_union = .{
        .tags = closed_tags,
        .ext = empty_row,
    } });

    const open_tags = try allocator.alloc(CheckedTag, 1);
    open_tags[0] = .{ .name = error_tag };
    const open_row = try store.appendSyntheticPayloadRoot(allocator, .{ .tag_union = .{
        .tags = open_tags,
        .ext = open_tail,
    } });

    const defaulted_tags = try allocator.alloc(CheckedTag, 1);
    defaulted_tags[0] = .{ .name = error_tag };
    const defaulted_row = try store.appendSyntheticPayloadRoot(allocator, .{ .tag_union = .{
        .tags = defaulted_tags,
        .ext = defaulted_tail,
    } });

    const alias_name = try names.internTypeName("HostErrors");
    const module_identity = try names.internModuleIdentity(&(@as([32]u8, @splat(0x69))));
    const aliased_row = try store.appendSyntheticPayloadRoot(allocator, .{ .alias = .{
        .name = alias_name,
        .origin_module = module_identity,
        .owner_module = testCheckedModuleKey(105).digest(),
        .backing = closed_row,
    } });

    try std.testing.expect(checkedTypeIsClosedTagRow(&store, empty_row));
    try std.testing.expect(checkedTypeIsClosedTagRow(&store, closed_row));
    try std.testing.expect(checkedTypeIsClosedTagRow(&store, defaulted_row));
    try std.testing.expect(checkedTypeIsClosedTagRow(&store, aliased_row));
    try std.testing.expect(!checkedTypeIsClosedTagRow(&store, open_row));
    try std.testing.expect(!checkedTypeIsClosedTagRow(&store, non_row));
}

/// Public `CheckedProcedureTemplateTable` declaration.
pub const CheckedProcedureTemplateTable = struct {
    templates: std.ArrayList(CheckedProcedureTemplate) = .empty,
    by_def: []static_dispatch.ProcedureTemplateLookupEntry = &.{},
    /// The templates of local functions checking promoted to procedures of
    /// their own, in promotion order, with each one's binding pattern.
    promoted: []PromotedProcedureTemplateEntry = &.{},
    /// Every template's call plans (`CheckedProcedureTemplate.static_dispatch_plans`),
    /// then the defaulted-field expressions' (`TemplateDispatchSites`).
    dispatch_plan_refs: []static_dispatch.StaticDispatchPlanId = &.{},
    /// Scope of each `dispatch_plan_refs` entry.
    dispatch_ref_scopes: []DispatchScope = &.{},
    /// The other sites each template's body reaches.
    dispatch_sites: TemplateDispatchSites = .{},
    /// The procedure base every literal root's entry wrapper shares; a
    /// wrapper's template id, its root's identity, tells them apart.
    literal_root_proc_base: canonical.ProcBaseKeyRef = @fromBackingInt(0),
    /// Relation semantics of each `dispatch_plan_refs` entry.
    dispatch_relation_kinds: []DispatchRelationKind = &.{},
    /// Generalized-local scopes referenced by `dispatch_ref_scopes`.
    dispatch_scopes: []DispatchRefScope = &.{},
    /// Flat pool of checker-authored relations that complete callable
    /// interfaces before specialization keys are sealed.
    specialization_interface_relations: []SpecializationInterfaceRelation = &.{},
    /// Checked argument types backing call-relation spans.
    specialization_interface_types: []CheckedTypeId = &.{},

    pub const Serialized = extern struct {
        templates: SerializedSlice(CheckedProcedureTemplate) = .{},
        by_def: SerializedSlice(static_dispatch.ProcedureTemplateLookupEntry) = .{},
        promoted: SerializedSlice(PromotedProcedureTemplateEntry) = .{},
        dispatch_plan_refs: SerializedSlice(static_dispatch.StaticDispatchPlanId) = .{},
        dispatch_ref_scopes: SerializedSlice(DispatchScope) = .{},
        dispatch_sites: TemplateDispatchSites.Serialized = .{},
        literal_root_proc_base: artifact_serialize.SerializedScalar(canonical.ProcBaseKeyRef, @fromBackingInt(0)) = .{},
        dispatch_relation_kinds: SerializedSlice(DispatchRelationKind) = .{},
        dispatch_scopes: SerializedSlice(DispatchRefScope) = .{},
        specialization_interface_relations: SerializedSlice(SpecializationInterfaceRelation) = .{},
        specialization_interface_types: SerializedSlice(CheckedTypeId) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(CheckedProcedureTemplateTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        value_binding_defs: []const CIR.Def.Idx,
        names: *canonical.CanonicalNameStore,
        owner_artifact: canonical.ArtifactRef,
        checked_type_publication: *CheckedTypePublication,
        module_index: *const ModuleIndex,
        intrinsic_wrappers: *IntrinsicWrapperTable,
    ) Allocator.Error!CheckedProcedureTemplateTable {
        var templates = std.ArrayList(CheckedProcedureTemplate).empty;
        errdefer templates.deinit(allocator);
        var by_def = std.ArrayList(static_dispatch.ProcedureTemplateLookupEntry).empty;
        errdefer by_def.deinit(allocator);

        const module_name = try names.internModuleName(module.moduleEnvConst().module_name);

        for (value_binding_defs) |def_idx| {
            const def = module.def(def_idx);
            if (def.expr.data == .e_derived_method) {
                checkedArtifactInvariant("generated method marker reached procedure-template publication", .{});
            }
            if (!topLevelExprIsAlreadyProcedure(module, def_idx, def.expr.data)) continue;

            const export_name = if (def.patternName()) |name|
                try names.internExportIdent(module.identStoreConst(), name)
            else
                null;
            const intrinsic = intrinsicForProcedureDef(module, def_idx);
            const proc_base = try names.internProcBase(.{
                .module_name = module_name,
                .export_name = export_name,
                .kind = if (intrinsic != null) .intrinsic_wrapper else if (isHostedProcedureExpr(def.expr.data)) .hosted_wrapper else .checked_source,
                .ordinal = @backingInt(def_idx),
                .source_def_idx = @backingInt(def_idx),
            });
            const template_id: canonical.CheckedProcedureTemplateId = @fromBackingInt(@intCast(@as(u32, @intCast(templates.items.len))));
            const template_ref = canonical.ProcedureTemplateRef{
                .artifact = owner_artifact,
                .proc_base = proc_base,
                .template = template_id,
            };
            try by_def.append(allocator, .{
                .def = def_idx,
                .template = template_ref,
                .kind = if (intrinsic) |intrinsic_id| switch (intrinsic_id) {
                    .structural_eq => .{ .structural = .equality },
                    .str_inspect,
                    .parse_tag_union,
                    .field_names_rename_fields,
                    .field_names_shortest_name,
                    .field_names_longest_name,
                    .field_names_iter,
                    .field_names_for_size,
                    .field_name,
                    => .callable,
                } else .callable,
            });
            const checked_fn_root = checked_type_publication.rootForSourceVar(module, module.defType(def_idx)) orelse {
                base.invariant("checked artifact invariant violated: checked procedure function root was not published", .{});
            };
            const checked_fn_scheme = checked_type_publication.schemeForSourceVar(module, module.defType(def_idx));
            const body: CheckedProcedureBody = if (intrinsic) |intrinsic_id| blk: {
                const wrapper_id = try intrinsic_wrappers.append(allocator, template_ref, checked_fn_root, intrinsic_id);
                break :blk .{ .intrinsic_wrapper = wrapper_id };
            } else if (def.expr.data == .e_anno_only) .{ .unimplemented = .{
                .region = module.regionAt(ModuleEnv.nodeIdxFrom(def.expr.idx)),
            } } else blk: {
                if (!module_index.reachesExpr(def.expr.idx)) {
                    base.invariant("checked artifact invariant violated: checked procedure body root expression was not published", .{});
                }
                break :blk .{ .checked_body = def.expr.idx };
            };

            try templates.append(allocator, .{
                .proc_base = proc_base,
                .template_id = template_id,
                .body = body,
                .checked_fn_scheme = checked_fn_scheme,
                .checked_fn_root = checked_fn_root,
                .static_dispatch_plans = .{},
                .resolved_value_refs = .{},
                .top_level_value_uses = .{},
                .target = if (intrinsic != null)
                    .intrinsic
                else if (isHostedProcedureExpr(def.expr.data))
                    .hosted
                else
                    .roc,
                .provided_low_level = module.moduleEnvConst().providedLowLevelForDef(def_idx),
            });
        }

        std.mem.sort(static_dispatch.ProcedureTemplateLookupEntry, by_def.items, {}, static_dispatch.ProcedureTemplateLookupEntry.lessThan);
        const by_def_slice = try by_def.toOwnedSlice(allocator);
        errdefer allocator.free(by_def_slice);
        return .{
            .templates = templates,
            .by_def = by_def_slice,
            .literal_root_proc_base = try names.internProcBase(.{
                .module_name = module_name,
                .export_name = null,
                .kind = .literal_root_wrapper,
                .ordinal = 0,
            }),
        };
    }

    /// Give each promoted local function its own procedure template, rooted at
    /// its lambda and published under its binding's generalized scheme. A
    /// promoted closure's captures name other promoted procedures, so its
    /// template root is the closure's lambda.
    pub fn appendPromotedLocalProcedures(
        self: *CheckedProcedureTemplateTable,
        allocator: Allocator,
        module: TypedCIR.Module,
        names: *canonical.CanonicalNameStore,
        owner_artifact: canonical.ArtifactRef,
        checked_type_publication: *CheckedTypePublication,
        module_index: *const ModuleIndex,
        promoted_local_procedures: []const hoist_roots.PromotedLocalProcedure,
    ) Allocator.Error!void {
        if (promoted_local_procedures.len == 0) return;
        const module_name = try names.internModuleName(module.moduleEnvConst().module_name);
        const entries = try allocator.alloc(PromotedProcedureTemplateEntry, promoted_local_procedures.len);
        errdefer allocator.free(entries);
        try self.templates.ensureUnusedCapacity(allocator, promoted_local_procedures.len);
        for (promoted_local_procedures, entries) |promoted, *entry| {
            const source_data = module.expr(promoted.expr).data;
            const lambda_source = if (source_data == .e_lambda)
                promoted.expr
            else if (source_data == .e_closure)
                source_data.e_closure.lambda_idx
            else
                checkedArtifactInvariant("promoted local procedure was not a lambda or closure", .{});
            if (!module_index.reachesExpr(lambda_source)) checkedArtifactInvariant("promoted local procedure lambda was not published", .{});
            const root_expr = lambda_source;
            const proc_base = try names.internProcBase(.{
                .module_name = module_name,
                .export_name = null,
                .kind = .promoted_local,
                .ordinal = @backingInt(lambda_source),
                .source_def_idx = null,
            });
            const template_id: canonical.CheckedProcedureTemplateId = @fromBackingInt(@intCast(@as(u32, @intCast(self.templates.items.len))));
            const template_ref = canonical.ProcedureTemplateRef{
                .artifact = owner_artifact,
                .proc_base = proc_base,
                .template = template_id,
            };
            const checked_fn_root = checked_type_publication.rootForSourceVar(module, module.exprType(root_expr)) orelse
                checkedArtifactInvariant("promoted local procedure lambda type was not published", .{});
            self.templates.appendAssumeCapacity(.{
                .proc_base = proc_base,
                .template_id = template_id,
                .body = .{ .checked_body = root_expr },
                .checked_fn_scheme = checked_type_publication.schemeForSourceVar(module, ModuleEnv.varFrom(promoted.pattern)),
                .checked_fn_root = checked_fn_root,
                .static_dispatch_plans = .{},
                .resolved_value_refs = .{},
                .top_level_value_uses = .{},
                .target = .roc,
            });
            entry.* = .{ .pattern = promoted.pattern, .template = template_ref };
        }
        allocator.free(self.promoted);
        self.promoted = entries;
    }

    pub fn lookupByDef(self: *const CheckedProcedureTemplateTable, def_idx: CIR.Def.Idx) ?canonical.ProcedureTemplateRef {
        var lo: usize = 0;
        var hi: usize = self.by_def.len;
        const target = @backingInt(def_idx);
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const candidate = @backingInt(self.by_def[mid].def);
            if (candidate < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= self.by_def.len or self.by_def[lo].def != def_idx) return null;
        return self.by_def[lo].template;
    }

    pub fn appendEntryWrappersForRoots(
        self: *CheckedProcedureTemplateTable,
        allocator: Allocator,
        module: TypedCIR.Module,
        names: *canonical.CanonicalNameStore,
        owner_artifact: canonical.ArtifactRef,
        checked_types: *CheckedTypeStore,
        entry_wrappers: *EntryWrapperTable,
        roots: []const CompileTimeRoot,
    ) Allocator.Error!void {
        // Every selected root produces exactly one entry wrapper and template.
        try self.templates.ensureTotalCapacityPrecise(allocator, self.templates.items.len + roots.len);
        try entry_wrappers.wrappers.ensureTotalCapacityPrecise(allocator, entry_wrappers.wrappers.items.len + roots.len);

        const module_name = try names.internModuleName(module.moduleEnvConst().module_name);

        for (roots) |root| {
            const checked_fn_root = try checked_types.appendSyntheticFunctionRoot(
                allocator,
                .pure,
                &.{},
                root.checked_type,
            );
            const checked_fn_scheme = try checked_types.ensureSchemeForRoot(allocator, checked_fn_root);
            const proc_base = try names.internProcBase(.{
                .module_name = module_name,
                .export_name = null,
                .kind = .entry_wrapper,
                .ordinal = root.id.index(),
                .source_def_idx = null,
            });
            const template_id: canonical.CheckedProcedureTemplateId = @fromBackingInt(@intCast(@as(u32, @intCast(self.templates.items.len))));
            const template_ref = canonical.ProcedureTemplateRef{
                .artifact = owner_artifact,
                .proc_base = proc_base,
                .template = template_id,
            };
            const wrapper_id = try entry_wrappers.append(allocator, root.id, template_ref, checked_fn_root);
            try self.appendTemplate(allocator, .{
                .proc_base = proc_base,
                .template_id = template_id,
                .body = .{ .entry_wrapper = wrapper_id },
                .checked_fn_scheme = checked_fn_scheme,
                .checked_fn_root = checked_fn_root,
                .static_dispatch_plans = .{},
                .resolved_value_refs = .{},
                .top_level_value_uses = .{},
                .target = switch (root.kind) {
                    .expect => .entry,
                    .constant, .hoisted_constant, .hoisted_validation, .callable_binding, .numeral_conversion, .quote_conversion, .repl_expr, .literal_argument => .comptime_only,
                },
            });
        }
    }

    fn appendTemplate(
        self: *CheckedProcedureTemplateTable,
        allocator: Allocator,
        template: CheckedProcedureTemplate,
    ) Allocator.Error!void {
        try self.templates.append(allocator, template);
    }

    /// Template `id` of the table. A literal root's entry wrapper is no row
    /// (`CheckedDispatch.procedureTemplate`).
    pub fn get(self: *const CheckedProcedureTemplateTable, id: canonical.CheckedProcedureTemplateId) CheckedProcedureTemplate {
        return self.templates.items[id.index()];
    }

    pub fn view(self: *const CheckedProcedureTemplateTable) CheckedProcedureTemplateTableView {
        return .{ .templates = self.templates.items };
    }

    pub fn asLookup(self: *const CheckedProcedureTemplateTable, module_idx: u32) static_dispatch.ProcedureTemplateLookup {
        return .{
            .module_idx = module_idx,
            .by_def = self.by_def,
            .promoted = self.promoted,
        };
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;

    pub fn specializationRelations(self: *const CheckedProcedureTemplateTable, template: *const CheckedProcedureTemplate) []const SpecializationInterfaceRelation {
        const span = template.specialization_interface_relations;
        return self.specialization_interface_relations[span.start .. span.start + span.len];
    }

    pub fn specializationRelationTypes(self: *const CheckedProcedureTemplateTable, span: artifact_serialize.Span) []const CheckedTypeId {
        return self.specialization_interface_types[span.start .. span.start + span.len];
    }
};

/// A promoted local procedure's template and the binding pattern whose
/// generalized scheme it publishes.
pub const PromotedProcedureTemplateEntry = static_dispatch.PromotedProcedureTemplateEntry;

/// Public `CheckedProcedureTemplateTableView` declaration.
pub const CheckedProcedureTemplateTableView = struct {
    templates: []const CheckedProcedureTemplate = &.{},
};

test "issue 11128 procedure template extension stays amortized" {
    const count: usize = 4096;
    var bytes = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    const gpa = bytes.allocator();
    var table = CheckedProcedureTemplateTable{};
    defer table.deinit(gpa);
    for (0..count) |i| {
        try table.appendTemplate(gpa, .{
            .proc_base = @fromBackingInt(@intCast(i)),
            .template_id = @fromBackingInt(@intCast(i)),
            .body = .{ .entry_wrapper = @fromBackingInt(@intCast(i)) },
            .checked_fn_scheme = @fromBackingInt(@intCast(i)),
            .checked_fn_root = @fromBackingInt(@intCast(i)),
            .static_dispatch_plans = .{},
            .resolved_value_refs = .{},
            .top_level_value_uses = .{},
            .target = .comptime_only,
        });
    }
    for (0..count) |i| {
        const row = table.get(@fromBackingInt(@intCast(i)));
        try std.testing.expectEqual(i, @backingInt(row.template_id));
        try std.testing.expectEqual(i, @backingInt(row.body.entry_wrapper));
    }
    try std.testing.expect(bytes.allocated_bytes <= 8 * count * @sizeOf(CheckedProcedureTemplate));
}

/// Each generalized local scope of `scopes` by the expression it is checked
/// at.
pub fn nestedProcScopeMap(
    allocator: Allocator,
    scopes: []const DispatchRefScope,
) Allocator.Error!collections.DenseMap(CIR.Expr.Idx, DispatchScopeId) {
    var by_checked_expr = collections.DenseMap(CIR.Expr.Idx, DispatchScopeId).init(allocator);
    errdefer by_checked_expr.deinit();
    try by_checked_expr.ensureTotalCapacity(@intCast(scopes.len));
    for (scopes, 0..) |scope, raw_scope| {
        const entry = by_checked_expr.getOrPutAssumeCapacity(scope.checked_expr);
        if (entry.found_existing) {
            checkedArtifactInvariant("checked expression owned more than one generalized dispatch scope", .{});
        }
        entry.value_ptr.* = @fromBackingInt(@intCast(@as(u32, @intCast(raw_scope))));
    }
    return by_checked_expr;
}

fn nestedProcLexicalScope(
    current: DispatchScope,
    expr: CIR.Expr.Idx,
    by_checked_expr: *const collections.DenseMap(CIR.Expr.Idx, DispatchScopeId),
    scopes: []const DispatchRefScope,
) DispatchScope {
    const scope_id = by_checked_expr.get(expr) orelse return current;
    const raw_scope = @backingInt(scope_id);
    if (raw_scope >= scopes.len or scopes[raw_scope].checked_expr != expr) {
        checkedArtifactInvariant("nested procedure lexical scope map disagreed with the checked scope table", .{});
    }
    const expected_parent: DispatchScope = if (scopes[raw_scope].parent) |parent|
        .{ .generalized = parent }
    else
        .root;
    if (!std.meta.eql(current, expected_parent)) {
        checkedArtifactInvariant("generalized nested procedure site had the wrong lexical parent scope", .{});
    }
    return .{ .generalized = scope_id };
}

/// The scan of one owner's body for its nested procedure sites
/// (`computeOwnerNestedProcSites`).
const NestedProcSiteScan = struct {
    allocator: Allocator,
    bodies: CheckedBodies,
    dispatch: CheckedDispatch,
    static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
    method_registry: *const static_dispatch.MethodRegistry,
    resolved_value_refs: *const ResolvedValueRefTable,
    dispatch_scopes: []const DispatchRefScope,
    scope_by_checked_expr: *const collections.DenseMap(CIR.Expr.Idx, DispatchScopeId),
    current_scope: DispatchScope = .root,
    sites: std.ArrayList(NestedProcSite) = .empty,
    /// Per site, by position: the site lexically enclosing it, if any.
    parents: std.ArrayList(?u32) = .empty,
    binders: std.ArrayList(OwnerNestedProcSites.BinderSite) = .empty,
    selections: std.ArrayList(OwnerNestedProcSites.SiteSelection) = .empty,
    work: std.ArrayList(ScanWork) = .empty,
    /// The positions of the sites whose bodies the walk is inside, innermost
    /// last.
    open_sites: std.ArrayList(u32) = .empty,
    /// Every expression the scan has constructed a site at.
    constructed: collections.DenseMap(CIR.Expr.Idx, void),

    fn deinit(self: *NestedProcSiteScan) void {
        self.sites.deinit(self.allocator);
        self.parents.deinit(self.allocator);
        self.binders.deinit(self.allocator);
        self.selections.deinit(self.allocator);
        self.work.deinit(self.allocator);
        self.open_sites.deinit(self.allocator);
        self.constructed.deinit();
    }

    fn scanEntryWrapper(self: *NestedProcSiteScan, root: CompileTimeRoot) Allocator.Error!void {
        const parts = root.bodyParts();
        if (parts.expr) |expr| try self.scanExpr(expr, false);
        if (parts.pattern) |pattern| try self.scanPattern(pattern);
        // A literal conversion root converts its literal's value as data and
        // owns no nested procedure site.
    }

    fn addSite(self: *NestedProcSiteScan, kind: NestedProcKind, checked_expr: CIR.Expr.Idx) Allocator.Error!void {
        const evidence_source, const evidence = switch (self.current_scope) {
            .root => .{ NestedProcEvidenceSource.inherited, static_dispatch.EvidenceSpan{} },
            .generalized => |scope_id| blk: {
                const raw_scope = @backingInt(scope_id);
                if (raw_scope >= self.dispatch_scopes.len) {
                    checkedArtifactInvariant("nested procedure site owned an unknown checked dispatch scope", .{});
                }
                if (self.dispatch_scopes[raw_scope].checked_expr != checked_expr) {
                    break :blk .{ NestedProcEvidenceSource.inherited, static_dispatch.EvidenceSpan{} };
                }
                const span = (try self.dispatch.siteEvidenceSpan(checked_expr)) orelse
                    checkedArtifactInvariant("nested procedure scope had no producer-authored construction evidence", .{});
                break :blk .{ NestedProcEvidenceSource.checked_site, span };
            },
        };

        try self.parents.append(self.allocator, self.innermostOpenSite());
        try self.sites.append(self.allocator, .{
            .lexical_scope = self.current_scope,
            .evidence_source = evidence_source,
            .evidence = evidence,
            .kind = kind,
            .checked_expr = checked_expr,
        });
    }

    /// Scan a checked expression for nested procedure sites. The scan keeps
    /// its own work stack, so body nesting depth never becomes native call
    /// depth. Children are pushed in reverse so they are scanned in source
    /// order, and each expression's exit is pushed before its children so it
    /// restores the lexical state they saw once they are all scanned.
    fn scanExpr(self: *NestedProcSiteScan, expr_id: CIR.Expr.Idx, suppress_current_site: bool) Allocator.Error!void {
        try self.work.append(self.allocator, .{ .expr = .{ .id = expr_id, .suppress_current_site = suppress_current_site } });
        try self.drain();
    }

    fn scanPattern(self: *NestedProcSiteScan, pattern_id: CIR.Pattern.Idx) Allocator.Error!void {
        try self.pushPattern(pattern_id);
        try self.drain();
    }

    fn drain(self: *NestedProcSiteScan) Allocator.Error!void {
        while (self.work.pop()) |work| switch (work) {
            .expr => |item| try self.enterExpr(item.id, item.suppress_current_site),
            .exit_expr => |exit| self.exitExpr(exit),
            .pattern => |item| try self.enterPattern(item.id),
            .statement => |item| try self.enterStatement(item.id),
            .generated_interpolation_segments => |item| try self.pushInterpolationChildren(item.id),
        };
    }

    const ScanWork = union(enum) {
        expr: struct { id: CIR.Expr.Idx, suppress_current_site: bool },
        exit_expr: ExprExit,
        pattern: struct { id: CIR.Pattern.Idx },
        statement: struct { id: CIR.Statement.Idx },
        generated_interpolation_segments: struct { id: CIR.Expr.Idx },
    };

    /// The lexical state an expression restores once its children are scanned.
    const ExprExit = struct {
        previous_scope: DispatchScope,
        open_site_mark: usize,
    };

    /// Children are pushed in source order between `beginChildren` and
    /// `endChildren`, which reverses them on the work stack.
    fn beginChildren(self: *const NestedProcSiteScan) usize {
        return self.work.items.len;
    }

    fn endChildren(self: *NestedProcSiteScan, start: usize) void {
        std.mem.reverse(ScanWork, self.work.items[start..]);
    }

    fn pushWork(self: *NestedProcSiteScan, work: ScanWork) Allocator.Error!void {
        try self.work.append(self.allocator, work);
    }

    fn pushExpr(self: *NestedProcSiteScan, expr_id: CIR.Expr.Idx) Allocator.Error!void {
        try self.pushWork(.{ .expr = .{ .id = expr_id, .suppress_current_site = false } });
    }

    fn pushPattern(self: *NestedProcSiteScan, pattern_id: CIR.Pattern.Idx) Allocator.Error!void {
        try self.pushWork(.{ .pattern = .{ .id = pattern_id } });
    }

    fn enterExpr(
        self: *NestedProcSiteScan,
        expr_id: CIR.Expr.Idx,
        suppress_current_site: bool,
    ) Allocator.Error!void {
        const bodies = self.bodies;
        const data = bodies.exprData(expr_id);
        // A local procedure a type declaration attaches can also be reached
        // through the body; its site is the first occurrence the scan reaches.
        if (!suppress_current_site and (data == .closure or data == .lambda or data == .hosted_lambda)) {
            if ((try self.constructed.getOrPut(expr_id)).found_existing) return;
        }
        const previous_scope = self.current_scope;
        self.current_scope = nestedProcLexicalScope(
            previous_scope,
            expr_id,
            self.scope_by_checked_expr,
            self.dispatch_scopes,
        );
        try self.pushWork(.{ .exit_expr = .{ .previous_scope = previous_scope, .open_site_mark = self.open_sites.items.len } });
        const children = self.beginChildren();
        switch (data) {
            .closure => |closure| {
                if (!suppress_current_site) {
                    try self.addSite(.closure, expr_id);
                    try self.openSite();
                }
                try self.pushWork(.{ .expr = .{ .id = closure.lambda, .suppress_current_site = true } });
            },
            .lambda => |lambda| {
                if (!suppress_current_site) {
                    try self.addSite(.local_function, expr_id);
                    try self.openSite();
                }
                for (lambda.args) |arg| try self.pushPattern(arg);
                try self.pushExpr(lambda.body);
            },
            .str => |segments| if (bodies.quoteIsCustom(@backingInt(expr_id))) {
                try self.pushStaticDispatchPlanArgs(bodies.quotePlan(@backingInt(expr_id)) orelse checkedArtifactInvariant("checked from_quote expression reached nested procedure site collection without a dispatch plan", .{}));
            } else {
                for (segments) |segment| try self.pushExpr(segment);
            },
            .list,
            .tuple,
            => |items| {
                for (items) |item| try self.pushExpr(item);
            },
            .match_ => |match| {
                try self.pushExpr(match.cond);
                for (match.branches) |branch_idx| {
                    const branch = bodies.matchBranch(branch_idx);
                    for (branch.patterns) |branch_pattern| try self.pushPattern(bodies.matchBranchPattern(branch_pattern).pattern);
                    if (branch.guard) |guard| try self.pushExpr(guard);
                    try self.pushExpr(branch.value);
                }
            },
            .if_ => |if_| {
                for (if_.branches) |branch_idx| {
                    const branch = bodies.ifBranch(branch_idx);
                    try self.pushExpr(branch.cond);
                    try self.pushExpr(branch.body);
                }
                try self.pushExpr(if_.final_else);
            },
            .call => |call| {
                try self.pushExpr(call.func);
                for (call.args) |arg| try self.pushExpr(arg);
            },
            .record => |record| {
                if (record.ext) |ext| try self.pushExpr(ext);
                for (record.fields) |field| try self.pushExpr(bodies.recordFieldValue(field));
            },
            .block => |block| {
                for (block.statements) |statement| try self.pushWork(.{ .statement = .{ .id = statement } });
                try self.pushExpr(block.final_expr);
            },
            .tag => |tag| {
                for (tag.args) |arg| try self.pushExpr(arg);
            },
            .nominal => |nominal| try self.pushExpr(nominal.backing_expr),
            .binop => |binop| {
                try self.pushExpr(binop.lhs);
                try self.pushExpr(binop.rhs);
            },
            inline .unary_minus, .dbg => |child| try self.pushExpr(child),
            .expect_err => |expect_err| try self.pushExpr(expect_err.expr),
            .expect => |child| try self.pushExpr(child),
            .break_ => {},
            .return_ => |ret| {
                // `ret.lambda` is the enclosing lambda context for early-return
                // lowering, not an owned child expression.
                try self.pushExpr(ret.expr);
            },
            .field_access => |field| try self.pushExpr(field.receiver),
            .dispatch_call,
            .method_eq,
            .type_dispatch_call,
            => try self.pushStaticDispatchPlanArgs(bodies.dispatchPlan(@backingInt(expr_id)) orelse checkedArtifactInvariant("checked dispatch expression reached nested procedure site collection without a static-dispatch plan", .{})),
            .interpolation => |interpolation| if (bodies.interpolationIsBuiltinStr(expr_id)) {
                try self.pushExpr(interpolation.first);
                for (interpolation.parts) |part| try self.pushExpr(part);
            } else {
                try self.pushStaticDispatchPlanArgs(bodies.dispatchPlan(@backingInt(expr_id)) orelse checkedArtifactInvariant("checked interpolation expression reached nested procedure site collection without a static-dispatch plan", .{}));
            },
            .numeral => if (bodies.numeralPlan(@backingInt(expr_id))) |plan_id| try self.pushStaticDispatchPlanArgs(plan_id),
            .structural_eq => |eq| {
                try self.pushExpr(eq.lhs);
                try self.pushExpr(eq.rhs);
            },
            .structural_hash => |h| {
                try self.pushExpr(h.value);
                try self.pushExpr(h.hasher);
            },
            .tuple_access => |access| try self.pushExpr(access.tuple),
            .for_ => |for_| {
                try self.pushPattern(for_.pattern);
                try self.pushExpr(for_.expr);
                try self.pushExpr(for_.body);
            },
            .hosted_lambda => |hosted| {
                if (!suppress_current_site) {
                    try self.addSite(.local_function, expr_id);
                    try self.openSite();
                }
                for (hosted.args) |arg| try self.pushPattern(arg);
            },
            .run_low_level => |run| {
                for (run.args) |arg| try self.pushExpr(arg);
            },
            .lookup_local, .lookup_external, .lookup_required => {
                if (data == .lookup_local) try self.selectLookupTarget(expr_id);
            },
            .runtime_error => |runtime_error| {
                for (runtime_error.evaluated) |operand| try self.pushExpr(operand);
            },
            .str_segment,
            .bytes_literal,
            .empty_list,
            .empty_record,
            .zero_argument_tag,
            .crash,
            .ellipsis,
            .anno_only,
            => {},
        }
        self.endChildren(children);
    }

    fn exitExpr(self: *NestedProcSiteScan, exit: ExprExit) void {
        self.open_sites.items.len = exit.open_site_mark;
        self.current_scope = exit.previous_scope;
    }

    /// Push a static-dispatch plan's checked operands among the children
    /// currently being pushed.
    fn pushStaticDispatchPlanArgs(
        self: *NestedProcSiteScan,
        plan_id: static_dispatch.StaticDispatchPlanId,
    ) Allocator.Error!void {
        const raw = @backingInt(plan_id);
        if (raw >= self.static_dispatch_plans.plans.len) {
            checkedArtifactInvariant("checked template static-dispatch plan id was outside the plan table", .{});
        }
        const plan = self.static_dispatch_plans.plans[raw];
        for (plan.argsSlice(self.static_dispatch_plans)) |arg| switch (arg) {
            .checked_expr => |expr| try self.pushExpr(expr),
            .generated_interpolation_segments => |expr| try self.pushWork(.{ .generated_interpolation_segments = .{ .id = expr } }),
            .generated_numeral, .generated_quote, .literal_pattern_value, .literal_pattern_conversion => {},
        };
    }

    fn pushInterpolationChildren(
        self: *NestedProcSiteScan,
        expr_id: CIR.Expr.Idx,
    ) Allocator.Error!void {
        const data = self.bodies.exprData(expr_id);
        if (data != .interpolation) {
            checkedArtifactInvariant("generated interpolation segments operand pointed at non-interpolation expression", .{});
        }
        const interpolation = data.interpolation;
        const children = self.beginChildren();
        try self.pushExpr(interpolation.first);
        for (interpolation.parts) |part| try self.pushExpr(part);
        self.endChildren(children);
    }

    fn enterPattern(
        self: *NestedProcSiteScan,
        pattern_id: CIR.Pattern.Idx,
    ) Allocator.Error!void {
        const bodies = self.bodies;
        const data = bodies.patternData(pattern_id);
        switch (data) {
            .assign, .as => try self.recordBinderSite(pattern_id),
            .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => {},
        }
        const children = self.beginChildren();
        switch (data) {
            .as => |as| try self.pushPattern(as.pattern),
            .applied_tag => |tag| {
                for (tag.args) |arg| try self.pushPattern(arg);
            },
            .nominal => |nominal| try self.pushPattern(nominal.backing_pattern),
            .record_destructure => |destructs| {
                for (destructs) |destruct| try self.pushPattern(bodies.recordDestructPattern(destruct));
            },
            .list => |list| {
                for (list.patterns) |child| try self.pushPattern(child);
                if (list.rest) |rest| {
                    if (rest.pattern) |child| try self.pushPattern(child);
                }
            },
            .tuple => |items| {
                for (items) |child| try self.pushPattern(child);
            },
            .str_interpolation => |str| {
                var offset: u32 = 0;
                while (offset < str.steps.span.len) : (offset += 1) {
                    if (bodies.strPatternStep(str.steps, offset).capture) |capture| try self.pushPattern(capture);
                }
            },
            .numeral_literal,
            .str_literal,
            .assign,
            .underscore,
            .runtime_error,
            => {},
        }
        self.endChildren(children);
    }

    fn enterStatement(
        self: *NestedProcSiteScan,
        statement_id: CIR.Statement.Idx,
    ) Allocator.Error!void {
        const children = self.beginChildren();
        switch (self.bodies.statementData(statement_id)) {
            .decl => |decl| {
                try self.pushPattern(decl.pattern);
                try self.pushExpr(decl.expr);
            },
            // The promoted procedure's sites belong to its own template.
            .promoted_proc => {},
            .var_ => |var_| {
                try self.pushPattern(var_.pattern);
                try self.pushExpr(var_.expr);
            },
            .var_uninitialized => |var_| {
                try self.pushPattern(var_.pattern);
            },
            .reassign => |reassign| {
                try self.pushPattern(reassign.pattern);
                try self.pushExpr(reassign.expr);
            },
            inline .dbg, .expr, .expect => |child| try self.pushExpr(child),
            .return_ => |ret| {
                // `ret.lambda` is the enclosing lambda context for early-return
                // lowering, not an owned child expression.
                try self.pushExpr(ret.expr);
            },
            .for_ => |for_| {
                try self.pushPattern(for_.pattern);
                try self.pushExpr(for_.expr);
                try self.pushExpr(for_.body);
            },
            inline .while_, .infinite_loop, .breakable_loop => |while_| {
                try self.pushExpr(while_.cond);
                try self.pushExpr(while_.body);
            },
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            => try self.pushAttachedLocalProcedures(statement_id),
            .crash,
            .rejected_method_decl,
            .break_,
            .import_,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => {},
        }
        self.endChildren(children);
    }

    fn pushAttachedLocalProcedures(
        self: *NestedProcSiteScan,
        statement_id: CIR.Statement.Idx,
    ) Allocator.Error!void {
        for (self.method_registry.entries) |entry| {
            const target = entry.target orelse continue;
            switch (target.kind) {
                .local_proc => |local| {
                    if (local.context_anchor == statement_id) {
                        try self.pushExpr(local.expr);
                    }
                },
                .procedure, .structural => {},
            }
        }
    }

    /// Enter the body of the site `addSite` just recorded.
    fn openSite(self: *NestedProcSiteScan) Allocator.Error!void {
        try self.open_sites.append(self.allocator, @intCast(self.sites.items.len - 1));
    }

    fn innermostOpenSite(self: *const NestedProcSiteScan) ?u32 {
        return self.open_sites.getLastOrNull();
    }

    fn recordBinderSite(self: *NestedProcSiteScan, binder: CIR.Pattern.Idx) Allocator.Error!void {
        try self.binders.append(self.allocator, .{ .binder = binder, .site = self.innermostOpenSite() });
    }

    /// Record that the innermost open site's own body selects the local
    /// procedure whose lambda or closure is `proc_expr`. The owner's body
    /// holds every binder a procedure it selects needs, so a selection
    /// outside every site records nothing.
    fn selectLocalProc(self: *NestedProcSiteScan, proc_expr: CIR.Expr.Idx) Allocator.Error!void {
        const site = self.innermostOpenSite() orelse return;
        try self.selections.append(self.allocator, .{ .site = site, .proc_expr = proc_expr });
    }

    fn selectLookupTarget(self: *NestedProcSiteScan, expr_id: CIR.Expr.Idx) Allocator.Error!void {
        const refs = self.resolved_value_refs;
        const id = refs.lookupIdByExpr(expr_id) orelse return;
        switch (refs.callableTarget(id).ref) {
            .local_proc => |local| try self.selectLocalProc(local.expr),
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => {},
        }
    }

    fn finish(self: *NestedProcSiteScan) Allocator.Error!*OwnerNestedProcSites {
        const allocator = self.allocator;
        const by_expr = try allocator.alloc(u32, self.sites.items.len);
        errdefer allocator.free(by_expr);
        for (by_expr, 0..) |*position, index| position.* = @intCast(index);
        const sites = self.sites.items;
        std.mem.sort(u32, by_expr, sites, struct {
            fn lessThan(all: []const NestedProcSite, left: u32, right: u32) bool {
                return @backingInt(all[left].checked_expr) < @backingInt(all[right].checked_expr);
            }
        }.lessThan);
        for (by_expr[0..by_expr.len -| 1], by_expr[@min(1, by_expr.len)..]) |left, right| {
            if (sites[left].checked_expr == sites[right].checked_expr) {
                checkedArtifactInvariant("an owner's body constructed two nested procedures at one expression", .{});
            }
        }
        const result = try allocator.create(OwnerNestedProcSites);
        errdefer allocator.destroy(result);
        const owned_sites = try self.sites.toOwnedSlice(allocator);
        errdefer allocator.free(owned_sites);
        const parents = try self.parents.toOwnedSlice(allocator);
        errdefer allocator.free(parents);
        const binders = try self.binders.toOwnedSlice(allocator);
        errdefer allocator.free(binders);
        result.* = .{
            .sites = owned_sites,
            .by_expr = by_expr,
            .parents = parents,
            .binders = binders,
            .selections = try self.selections.toOwnedSlice(allocator),
        };
        return result;
    }
};

/// The nested procedure sites `owner`'s body constructs, scanned from
/// `bodies` (design.md "On-Demand Analyses And Write-Once Slots").
pub fn computeOwnerNestedProcSites(
    allocator: Allocator,
    bodies: CheckedBodies,
    scope_by_checked_expr: *const collections.DenseMap(CIR.Expr.Idx, DispatchScopeId),
    owner: NestedProcSiteOwner,
) Allocator.Error!*OwnerNestedProcSites {
    const dispatch = bodies.tables.dispatch orelse checkedArtifactInvariant("nested procedure sites were scanned from bodies without dispatch", .{});
    const source = dispatch.source;
    var scan = NestedProcSiteScan{
        .allocator = allocator,
        .bodies = bodies,
        .dispatch = dispatch,
        .static_dispatch_plans = source.plans,
        .method_registry = source.method_registry,
        .resolved_value_refs = source.refs,
        .dispatch_scopes = source.templates.dispatch_scopes,
        .scope_by_checked_expr = scope_by_checked_expr,
        .constructed = collections.DenseMap(CIR.Expr.Idx, void).init(allocator),
    };
    defer scan.deinit();
    switch (owner) {
        .template => |template_ref| switch (source.templates.get(template_ref.template).body) {
            .checked_body => |root_expr| try scan.scanExpr(root_expr, true),
            .entry_wrapper => |wrapper_id| {
                const wrapper = source.entry_wrappers.get(wrapper_id);
                try scan.scanEntryWrapper(source.compile_time_roots.root(wrapper.root));
            },
            .literal_root => checkedArtifactInvariant("a literal root's entry wrapper is a row of the template table", .{}),
            .intrinsic_wrapper, .unimplemented => {},
        },
        // Unlike a template body, whose root lambda is the procedure
        // itself, a default's root lambda is an ordinary nested function
        // value, so the default's root is a site.
        .default_root => |default| try scan.scanExpr(default, false),
    }
    return scan.finish();
}

/// The module's nested procedure sites by expression with their runtime
/// captures, from every owner's sites: each template's in template order,
/// then each defaulted-field default's. A procedure's runtime captures are
/// its own captures, then every binder of an enclosing frame that
/// constructing a local procedure it selects requires, directly or through
/// a site nested in it. A selected procedure needs its own runtime
/// captures, so this is the least fixpoint of that relation, with each site
/// keeping only the binders its own body does not bind. The relation is a
/// function of the site expressions alone, and it crosses owners: a
/// promoted local procedure's body selects local procedures its enclosing
/// template's body declares.
pub fn computeModuleNestedProcSites(
    allocator: Allocator,
    bodies: CheckedBodies,
    analyses: *ModuleAnalyses,
) Allocator.Error!*ModuleNestedProcSites {
    const templates = bodies.tables.templates orelse checkedArtifactInvariant("nested procedure sites were computed without the module's templates", .{});
    const defaults = bodies.index().defaults;
    const owners = try allocator.alloc(*const OwnerNestedProcSites, templates.templates.items.len + defaults.len);
    defer allocator.free(owners);
    for (templates.templates.items, owners[0..templates.templates.items.len]) |template, *owner| {
        owner.* = try analyses.nestedProcSites(bodies, .{ .template = .{ .proc_base = template.proc_base, .template = template.template_id } });
    }
    for (defaults, owners[templates.templates.items.len..]) |default, *owner| {
        owner.* = try analyses.nestedProcSites(bodies, .{ .default_root = @fromBackingInt(default) });
    }

    // Every owner's site expressions, grouped by expression in owner order.
    const Occurrence = struct {
        expr: CIR.Expr.Idx,
        template: ?canonical.CheckedProcedureTemplateId,

        fn lessThan(_: void, left: @This(), right: @This()) bool {
            return @backingInt(left.expr) < @backingInt(right.expr);
        }
    };
    var occurrences = std.ArrayList(Occurrence).empty;
    defer occurrences.deinit(allocator);
    for (owners, 0..) |owner, owner_index| {
        const template: ?canonical.CheckedProcedureTemplateId = if (owner_index < templates.templates.items.len) @fromBackingInt(@intCast(owner_index)) else null;
        for (owner.sites) |site| try occurrences.append(allocator, .{ .expr = site.checked_expr, .template = template });
    }
    std.mem.sortUnstable(Occurrence, occurrences.items, {}, Occurrence.lessThan);
    var exprs = std.ArrayList(CIR.Expr.Idx).empty;
    defer exprs.deinit(allocator);
    var first_templates = std.ArrayList(?canonical.CheckedProcedureTemplateId).empty;
    defer first_templates.deinit(allocator);
    var owner_counts = std.ArrayList(u32).empty;
    defer owner_counts.deinit(allocator);
    for (occurrences.items) |occurrence| {
        const last = exprs.items.len;
        if (last != 0 and exprs.items[last - 1] == occurrence.expr) {
            owner_counts.items[last - 1] += 1;
            if (occurrence.template) |template| {
                const first = &first_templates.items[last - 1];
                if (first.* == null or @backingInt(template) < @backingInt(first.*.?)) first.* = template;
            }
            continue;
        }
        try exprs.append(allocator, occurrence.expr);
        try first_templates.append(allocator, occurrence.template);
        try owner_counts.append(allocator, 1);
    }
    const count = exprs.items.len;
    const lookup = ModuleNestedProcSites{ .exprs = exprs.items };

    // The lexical facts of the site expressions, merged over owners: an
    // owner's scan starts below its own root, so where one owner's site has
    // no enclosing site another owner's may.
    const parents = try allocator.alloc(?u32, count);
    defer allocator.free(parents);
    @memset(parents, null);
    var binder_sites = collections.DenseMap(CIR.Pattern.Idx, ?u32).init(allocator);
    defer binder_sites.deinit();
    const Selection = struct { site: u32, proc_expr: CIR.Expr.Idx };
    var selections = std.ArrayList(Selection).empty;
    defer selections.deinit(allocator);
    for (owners) |owner| {
        for (owner.sites, owner.parents) |site, maybe_parent| {
            const parent = maybe_parent orelse continue;
            const child_position = lookup.position(site.checked_expr).?;
            const parent_position: u32 = @intCast(lookup.position(owner.sites[parent].checked_expr).?);
            if (parents[child_position]) |existing| {
                if (existing != parent_position) checkedArtifactInvariant("two owners disagreed on a nested procedure site's enclosing site", .{});
            }
            parents[child_position] = parent_position;
        }
        for (owner.binders) |bound| {
            const position: ?u32 = if (bound.site) |site| @intCast(lookup.position(owner.sites[site].checked_expr).?) else null;
            const entry = try binder_sites.getOrPut(bound.binder);
            if (!entry.found_existing or entry.value_ptr.* == null) {
                entry.value_ptr.* = position;
            } else if (position) |found| {
                if (entry.value_ptr.*.? != found) checkedArtifactInvariant("two owners disagreed on the site binding a binder", .{});
            }
        }
        for (owner.selections) |selection| {
            try selections.append(allocator, .{ .site = @intCast(lookup.position(owner.sites[selection.site].checked_expr).?), .proc_expr = selection.proc_expr });
        }
    }

    // Each closure site's lambda, through which a selection names the
    // closure's site.
    var closure_lambdas = std.ArrayList(ModuleNestedProcSites.ClosureLambda).empty;
    defer closure_lambdas.deinit(allocator);
    for (exprs.items) |expr| {
        const data = bodies.exprData(expr);
        if (data == .closure) try closure_lambdas.append(allocator, .{ .lambda = data.closure.lambda, .closure = expr });
    }
    std.mem.sortUnstable(ModuleNestedProcSites.ClosureLambda, closure_lambdas.items, {}, struct {
        fn lessThan(_: void, left: ModuleNestedProcSites.ClosureLambda, right: ModuleNestedProcSites.ClosureLambda) bool {
            return @backingInt(left.lambda) < @backingInt(right.lambda);
        }
    }.lessThan);
    const with_lambdas = ModuleNestedProcSites{ .exprs = exprs.items, .closure_lambdas = closure_lambdas.items };

    const needs = try allocator.alloc(std.ArrayList(CIR.Pattern.Idx), count);
    defer allocator.free(needs);
    for (needs) |*need| need.* = .empty;
    defer for (needs) |*need| need.deinit(allocator);
    for (exprs.items, needs) |expr, *need| {
        for (ownSiteCaptures(bodies, expr)) |capture| _ = try insertSortedBinder(allocator, need, checkedSiteCapture(bodies, capture).pattern);
    }

    const Fixpoint = struct {
        parents: []const ?u32,
        binder_sites: *const collections.DenseMap(CIR.Pattern.Idx, ?u32),

        /// Whether the body of `site`, or of a site nested in it, binds `binder`.
        fn boundWithin(self: @This(), site: u32, binder: CIR.Pattern.Idx) bool {
            var current = self.binder_sites.get(binder) orelse
                checkedArtifactInvariant("nested procedure runtime capture named a binder no scanned pattern binds", .{});
            while (current) |candidate| {
                if (candidate == site) return true;
                current = self.parents[candidate];
            }
            return false;
        }
    };
    const fixpoint = Fixpoint{ .parents = parents, .binder_sites = &binder_sites };
    var changed = true;
    while (changed) {
        changed = false;
        for (selections.items) |selection| {
            const proc_site = with_lambdas.position(selection.proc_expr) orelse continue;
            var index: usize = 0;
            while (index < needs[proc_site].items.len) : (index += 1) {
                const binder = needs[proc_site].items[index];
                if (fixpoint.boundWithin(selection.site, binder)) continue;
                if (try insertSortedBinder(allocator, &needs[selection.site], binder)) changed = true;
            }
        }
        for (parents, 0..) |maybe_parent, child| {
            const parent = maybe_parent orelse continue;
            var index: usize = 0;
            while (index < needs[child].items.len) : (index += 1) {
                const binder = needs[child].items[index];
                if (fixpoint.boundWithin(parent, binder)) continue;
                if (try insertSortedBinder(allocator, &needs[parent], binder)) changed = true;
            }
        }
    }

    var pool = std.ArrayList(CheckedCapture).empty;
    defer pool.deinit(allocator);
    const capture_spans = try allocator.alloc(artifact_serialize.Span, count);
    errdefer allocator.free(capture_spans);
    for (exprs.items, needs, capture_spans) |expr, need, *span| {
        const start: u32 = @intCast(pool.items.len);
        const own = ownSiteCaptures(bodies, expr);
        for (own) |capture| try pool.append(allocator, checkedSiteCapture(bodies, capture));
        for (need.items) |binder| {
            const already_own = for (own) |capture| {
                if (checkedSiteCapture(bodies, capture).pattern == binder) break true;
            } else false;
            if (already_own) continue;
            try pool.append(allocator, .{
                .pattern = binder,
                .scope_depth = 0,
                .capture_id = CaptureId.fromBinder(binder),
            });
        }
        span.* = .{ .start = start, .len = @as(u32, @intCast(pool.items.len)) - start };
    }

    const result = try allocator.create(ModuleNestedProcSites);
    errdefer allocator.destroy(result);
    const owned_exprs = try exprs.toOwnedSlice(allocator);
    errdefer allocator.free(owned_exprs);
    const owned_first_templates = try first_templates.toOwnedSlice(allocator);
    errdefer allocator.free(owned_first_templates);
    const owned_owner_counts = try owner_counts.toOwnedSlice(allocator);
    errdefer allocator.free(owned_owner_counts);
    const owned_captures = try pool.toOwnedSlice(allocator);
    errdefer allocator.free(owned_captures);
    result.* = .{
        .exprs = owned_exprs,
        .first_templates = owned_first_templates,
        .owner_counts = owned_owner_counts,
        .capture_spans = capture_spans,
        .captures = owned_captures,
        .closure_lambdas = try closure_lambdas.toOwnedSlice(allocator),
    };
    return result;
}

fn ownSiteCaptures(bodies: CheckedBodies, expr: CIR.Expr.Idx) []const CIR.Expr.Capture.Idx {
    const data = bodies.exprData(expr);
    return if (data == .closure) data.closure.captures else &.{};
}

fn checkedSiteCapture(bodies: CheckedBodies, capture_idx: CIR.Expr.Capture.Idx) CheckedCapture {
    const capture = bodies.capture(capture_idx);
    if (!patternBindsName(bodies.env, capture.pattern)) {
        checkedArtifactInvariant("nested procedure capture referenced a non-binding pattern", .{});
    }
    return .{ .pattern = capture.pattern, .scope_depth = capture.scope_depth, .capture_id = capture.capture_id };
}

/// Add `binder` to the sorted set `set`; whether it was absent.
fn insertSortedBinder(allocator: Allocator, set: *std.ArrayList(CIR.Pattern.Idx), binder: CIR.Pattern.Idx) Allocator.Error!bool {
    const index = std.sort.lowerBound(CIR.Pattern.Idx, set.items, binder, struct {
        fn order(key: CIR.Pattern.Idx, item: CIR.Pattern.Idx) std.math.Order {
            return std.math.order(@backingInt(key), @backingInt(item));
        }
    }.order);
    if (index < set.items.len and set.items[index] == binder) return false;
    try set.insert(allocator, index, binder);
    return true;
}

/// Public `HostedProc` declaration.
pub const HostedProc = struct {
    module_idx: u32,
    def_idx: CIR.Def.Idx,
    expr_idx: CIR.Expr.Idx,
    external_symbol_name: canonical.ExternalSymbolNameId,
    deterministic_index: u32,
    /// Range into `HostedProcTable.order_key_bytes` (transform-B side list).
    order_key_start: u32,
    order_key_len: u32,
    proc: canonical.ProcedureValueRef,
    template: canonical.ProcedureTemplateRef,

    /// The proc's deterministic ordering key bytes within its table's pool.
    pub fn orderKey(self: HostedProc, table: *const HostedProcTable) []const u8 {
        return table.order_key_bytes[self.order_key_start .. self.order_key_start + self.order_key_len];
    }
};

/// Public `HostedProcTable` declaration.
pub const HostedProcTable = struct {
    procs: []HostedProc = &.{},
    /// Flat pool of all procs' order-key bytes (transform-B side list).
    order_key_bytes: []const u8 = &.{},

    pub const Serialized = extern struct {
        procs: SerializedSlice(HostedProc) = .{},
        order_key_bytes: SerializedSlice(u8) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(HostedProcTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    const Candidate = struct {
        module_idx: u32,
        def_idx: CIR.Def.Idx,
        expr_idx: CIR.Expr.Idx,
        external_symbol_name: canonical.ExternalSymbolNameId,
        proc: canonical.ProcedureValueRef,
        template: canonical.ProcedureTemplateRef,
        sort_key: []const u8,
    };

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        hosted_defs: []const CIR.Def.Idx,
        names: *canonical.CanonicalNameStore,
        templates: *const CheckedProcedureTemplateTable,
    ) Allocator.Error!HostedProcTable {
        var candidates = std.ArrayList(Candidate).empty;
        defer {
            for (candidates.items) |candidate| allocator.free(candidate.sort_key);
            candidates.deinit(allocator);
        }

        var procs = std.ArrayList(HostedProc).empty;
        errdefer procs.deinit(allocator);
        var order_key_bytes = std.ArrayList(u8).empty;
        errdefer order_key_bytes.deinit(allocator);

        for (hosted_defs) |def_idx| {
            const def = module.def(def_idx);
            if (def.expr.data == .e_hosted_lambda) {
                const hosted = def.expr.data.e_hosted_lambda;
                const template_ref = templates.lookupByDef(def_idx) orelse {
                    base.invariant("checked artifact invariant violated: hosted procedure def has no checked template", .{});
                };

                try candidates.append(allocator, .{
                    .module_idx = module.moduleIndex(),
                    .def_idx = def_idx,
                    .expr_idx = def.expr.idx,
                    .external_symbol_name = try names.internExternalSymbolIdent(module.identStoreConst(), hosted.symbol_name),
                    .proc = .{
                        .artifact = template_ref.artifact,
                        .proc_base = template_ref.proc_base,
                    },
                    .template = template_ref,
                    .sort_key = try hostedProcSortKey(allocator, module, hosted.symbol_name),
                });
            }
        }

        const SortContext = struct {
            pub fn lessThan(_: void, a: Candidate, b: Candidate) bool {
                return switch (std.mem.order(u8, a.sort_key, b.sort_key)) {
                    .lt => true,
                    .gt => false,
                    .eq => @backingInt(a.def_idx) < @backingInt(b.def_idx),
                };
            }
        };
        std.mem.sort(Candidate, candidates.items, {}, SortContext.lessThan);

        for (candidates.items, 0..) |candidate, index| {
            const order_key_start: u32 = @intCast(order_key_bytes.items.len);
            try order_key_bytes.appendSlice(allocator, candidate.sort_key);
            try procs.append(allocator, .{
                .module_idx = candidate.module_idx,
                .def_idx = candidate.def_idx,
                .expr_idx = candidate.expr_idx,
                .external_symbol_name = candidate.external_symbol_name,
                .deterministic_index = @intCast(index),
                .order_key_start = order_key_start,
                .order_key_len = @intCast(candidate.sort_key.len),
                .proc = candidate.proc,
                .template = candidate.template,
            });
        }

        return .{
            .procs = try procs.toOwnedSlice(allocator),
            .order_key_bytes = try order_key_bytes.toOwnedSlice(allocator),
        };
    }

    fn hostedProcSortKey(
        allocator: Allocator,
        module: TypedCIR.Module,
        symbol_name: Ident.Idx,
    ) Allocator.Error![]const u8 {
        const module_env = module.moduleEnvConst();
        var module_name = module_env.module_name;
        if (Ident.textEndsWith(module_name, ".roc")) {
            module_name = module_name[0 .. module_name.len - 4];
        }

        const local_name = module.getIdent(symbol_name);
        const qualified_name = try std.fmt.allocPrint(allocator, "{s}.{s}", .{ module_name, local_name });
        if (!Ident.textEndsWith(qualified_name, "!")) return qualified_name;

        const stripped = try allocator.dupe(u8, qualified_name[0 .. qualified_name.len - 1]);
        allocator.free(qualified_name);
        return stripped;
    }

    /// Build-time-only teardown (see `StaticDispatchPlanTable.deinit`): a frozen table's
    /// slices alias the artifact buffer and are freed wholesale by the artifact, never here.
    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;
};

/// One platform-header hosted binding. Slice order is the host dispatch index.
pub const HostedBinding = struct {
    target_checked_module: CheckedModuleDigest,
    target_def: CIR.Def.Idx,
    external_symbol_name: canonical.ExternalSymbolNameId,
};

/// Exact platform-header bindings from external symbols to checked hosted defs.
pub const HostedBindingTable = struct {
    bindings: []HostedBinding = &.{},

    pub const Serialized = extern struct {
        bindings: SerializedSlice(HostedBinding) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(HostedBindingTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    /// `own_key` and `own_procs` describe the platform module being published,
    /// so an entry written without a module name binds the declaration this
    /// module makes rather than one an import makes.
    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        names: *canonical.CanonicalNameStore,
        imports: []const PublishImportArtifact,
        own_key: CheckedModuleArtifactKey,
        own_procs: *const HostedProcTable,
    ) Allocator.Error!HostedBindingTable {
        if (module.moduleEnvConst().module_kind != .platform) return .{};

        var bindings = std.ArrayList(HostedBinding).empty;
        errdefer bindings.deinit(allocator);

        const Target = struct {
            module_idx: u32,
            def: CIR.Def.Idx,
        };
        var hosted_targets = std.AutoHashMap(Target, usize).init(allocator);
        defer hosted_targets.deinit();
        var hosted_target_count: usize = 0;
        for (imports) |imported| hosted_target_count += imported.view.hosted_procs.procs.len;
        try hosted_targets.ensureTotalCapacity(@intCast(hosted_target_count));
        for (imports, 0..) |imported, import_index| {
            for (imported.view.hosted_procs.procs) |proc| {
                hosted_targets.putAssumeCapacityNoClobber(.{
                    .module_idx = imported.module_idx,
                    .def = proc.def_idx,
                }, import_index);
            }
        }

        for (module.moduleEnvConst().hosted_entries.items.items) |entry| {
            if (entry.target_status != .resolved) continue;
            const target_def = entry.target_def orelse continue;

            const target_module_key = if (entry.target_import) |import_idx| blk: {
                const resolved_module_idx = module.resolvedImportModule(import_idx) orelse continue;
                const import_index = hosted_targets.get(.{
                    .module_idx = resolved_module_idx,
                    .def = target_def,
                }) orelse continue;
                break :blk imports[import_index].key;
            } else blk: {
                // No import means the entry named this module's own
                // declaration, which is a hosted procedure only if the hosted
                // transform rewrote it.
                if (hostedProcForDef(own_procs, target_def) == null) continue;
                break :blk own_key;
            };

            try bindings.append(allocator, .{
                .target_checked_module = target_module_key.digest(),
                .target_def = target_def,
                .external_symbol_name = try names.internExternalSymbolName(module.moduleEnvConst().getString(entry.symbol)),
            });
        }

        return .{ .bindings = try bindings.toOwnedSlice(allocator) };
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;
};

/// Public `PlatformAppRelationKey` declaration.
pub const PlatformAppRelationKey = struct {
    bytes: [32]u8 = @as([32]u8, @splat(0)),

    pub fn compute(
        app_artifact: ModuleId,
        requirement_context: PlatformRequirementContextKey,
    ) PlatformAppRelationKey {
        var hasher = base.Sha256.init(.{});
        hasher.update(&app_artifact.bytes);
        hasher.update(&requirement_context.bytes);
        return .{ .bytes = hasher.finalResult() };
    }
};

/// Public `PlatformRequiredDeclarationId` declaration.
pub const PlatformRequiredDeclarationId = enum(u32) { _ };
/// Public `PlatformRequiredBindingId` declaration.
pub const PlatformRequiredBindingId = enum(u32) { _ };
/// Public `PlatformRequirementRelationId` declaration.
pub const PlatformRequirementRelationId = enum(u32) { _ };

/// Public `PlatformRequiredValueKind` declaration.
pub const PlatformRequiredValueKind = enum {
    const_value,
    procedure_value,
};

/// Public `PlatformRequiredDeclaration` declaration.
pub const PlatformRequiredDeclaration = struct {
    id: PlatformRequiredDeclarationId,
    module_idx: u32,
    requires_idx: u32,
    platform_name: canonical.ExportNameId,
    /// The declared type's annotation; its scheme key is computed when an
    /// identity needs it (`PlatformRequiredDeclarationTable.identityHash`).
    type_anno: CIR.TypeAnno.Idx,
    for_clause_aliases_hash: [32]u8,
};

/// Public `PlatformRequiredDeclarationTable` declaration.
pub const PlatformRequiredDeclarationTable = struct {
    declarations: []PlatformRequiredDeclaration = &.{},

    pub const Serialized = extern struct {
        declarations: SerializedSlice(PlatformRequiredDeclaration) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(PlatformRequiredDeclarationTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        names: *canonical.CanonicalNameStore,
    ) Allocator.Error!PlatformRequiredDeclarationTable {
        return fromEnv(allocator, module.moduleEnvConst(), names, module.moduleIndex());
    }

    /// Build the required declaration table from a platform module's checked
    /// `ModuleEnv`. `fromModule` delegates here so the artifact-derived and
    /// env-derived declaration hashes share a single implementation.
    pub fn fromEnv(
        allocator: Allocator,
        module_env: *const ModuleEnv,
        names: *canonical.CanonicalNameStore,
        module_idx: u32,
    ) Allocator.Error!PlatformRequiredDeclarationTable {
        const required_types = module_env.requires_types.items.items;
        const declarations = try allocator.alloc(PlatformRequiredDeclaration, required_types.len);
        errdefer allocator.free(declarations);
        for (required_types, 0..) |required_type, i| {
            declarations[i] = .{
                .id = @fromBackingInt(@intCast(@as(u32, @intCast(i)))),
                .module_idx = module_idx,
                .requires_idx = @intCast(i),
                .platform_name = try names.internExportIdent(module_env.getIdentStoreConst(), required_type.ident),
                .type_anno = required_type.type_anno,
                .for_clause_aliases_hash = hashRequiredTypeForClauseAliases(module_env, required_type),
            };
        }

        return .{ .declarations = declarations };
    }

    pub fn lookupByRequiredIndex(
        self: *const PlatformRequiredDeclarationTable,
        requires_idx: u32,
    ) ?PlatformRequiredDeclaration {
        for (self.declarations) |declaration| {
            if (declaration.requires_idx == requires_idx) return declaration;
        }
        return null;
    }

    pub fn lookupByDeclarationId(
        self: *const PlatformRequiredDeclarationTable,
        declaration_id: PlatformRequiredDeclarationId,
    ) ?PlatformRequiredDeclaration {
        const raw = @backingInt(declaration_id);
        if (raw >= self.declarations.len) return null;
        return self.declarations[raw];
    }

    /// The declarations' identity: each one's name, the scheme key of its
    /// declared type in `types` (the platform's checked types), and its
    /// for-clause aliases.
    pub fn identityHash(
        self: *const PlatformRequiredDeclarationTable,
        names: *const canonical.CanonicalNameStore,
        type_view: CheckedTypeStoreView,
    ) Allocator.Error![32]u8 {
        var hasher = base.Sha256.init(.{});
        hashByteSlice(&hasher, "platform_required_declarations");
        hashU32(&hasher, @intCast(self.declarations.len));
        for (self.declarations) |declaration| {
            hashU32(&hasher, declaration.requires_idx);
            hashByteSlice(&hasher, names.exportNameText(declaration.platform_name));
            const declared = type_view.sourceTypeRoot(ModuleEnv.varFrom(declaration.type_anno)) orelse
                checkedArtifactInvariant("a platform requirement's declared type was not published", .{});
            hasher.update(&canonical_type_keys.schemeKeyForType(try type_view.rootKey(declared)).bytes);
            hasher.update(&declaration.for_clause_aliases_hash);
        }
        return hasher.finalResult();
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;
};

fn hashRequiredTypeForClauseAliases(
    module_env: *const ModuleEnv,
    required_type: ModuleEnv.RequiredType,
) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hashByteSlice(&hasher, "platform_required_for_clause_aliases");
    const aliases = module_env.for_clause_aliases.sliceRange(required_type.type_aliases);
    hashU32(&hasher, @intCast(aliases.len));
    for (aliases) |alias| {
        hashByteSlice(&hasher, module_env.getIdent(alias.alias_name));
        hashByteSlice(&hasher, module_env.getIdent(alias.rigid_name));
    }
    return hasher.finalResult();
}

/// Public `PlatformRequiredProcedureUse` declaration.
pub const PlatformRequiredProcedureUse = struct {
    procedure: ProcedureUseTemplate,
    root_evidence: ?CheckedEvidenceSpan = null,
    relation_template_closure: ImportedTemplateClosureView = .{},
};

/// Public `PlatformRequiredConstUse` declaration.
pub const PlatformRequiredConstUse = struct {
    const_use: ConstUseTemplate,
    relation_template_closure: ImportedTemplateClosureView = .{},
};

/// Public `PlatformRequiredValueUse` declaration.
pub const PlatformRequiredValueUse = union(enum) {
    const_value: PlatformRequiredConstUse,
    procedure_value: PlatformRequiredProcedureUse,

    pub fn tag(self: PlatformRequiredValueUse) PlatformRequiredValueUseKind {
        return switch (self) {
            .const_value => .const_value,
            .procedure_value => .procedure_value,
        };
    }
};

/// Discriminant of `PlatformRequiredValueUse` / `StoredPlatformRequiredValueUse`.
pub const PlatformRequiredValueUseKind = enum { const_value, procedure_value };

/// Relocation-invariant (POD) mirror of `PlatformRequiredProcedureUse`.
pub const StoredPlatformRequiredProcedureUse = struct {
    procedure: ProcedureUseTemplate,
    root_evidence: ?CheckedEvidenceSpan = null,
    relation_template_closure: StoredImportedTemplateClosure = .{},
};

/// Relocation-invariant (POD) mirror of `PlatformRequiredConstUse`.
pub const StoredPlatformRequiredConstUse = struct {
    const_use: ConstUseTemplate,
    relation_template_closure: StoredImportedTemplateClosure = .{},
};

/// POD mirror of `PlatformRequiredValueUse`: closures live as ranges into the
/// owning `PlatformRequiredBindingTable`'s `ClosurePool`. Stored by value in each
/// `PlatformRequiredBinding` row. A real tagged union (not a discriminant + two fixed
/// fields), so only the active variant's bytes exist—there is no inactive field to
/// leave `undefined`, and the serializer's union-padding zeroing keeps the blob
/// byte-deterministic.
pub const StoredPlatformRequiredValueUse = union(PlatformRequiredValueUseKind) {
    const_value: StoredPlatformRequiredConstUse,
    procedure_value: StoredPlatformRequiredProcedureUse,
};

