/// Public `PlatformAppRelation` declaration.
pub const PlatformAppRelation = struct {
    key: PlatformAppRelationKey,
    requirement_context: PlatformRequirementContextKey,
    platform_module_idx: u32,
    app_artifact: CheckedModuleDigest,
    relations: []const PlatformRequirementRelationInput,
    bindings: []const PlatformRequiredBindingInput,
    /// Requires-clause indices whose app-side requirement check failed. These
    /// are explicit checked-error facts: platform required lookups at these
    /// indices lower to a runtime crash, while successful sibling bindings
    /// remain fully linked.
    checked_error_requires: []const u32,
    /// Borrowed app-store roots in the checker's canonical identity-slot order.
    /// The app artifact owns these roots and each binding's template closure;
    /// it must outlive the relation and publication that consume them.
    identity_solutions_app: []const CheckedTypeId,

    pub fn deinit(self: *PlatformAppRelation, allocator: Allocator) void {
        allocator.free(self.relations);
        allocator.free(self.bindings);
        allocator.free(self.checked_error_requires);
        self.* = .{
            .key = .{},
            .requirement_context = .{},
            .platform_module_idx = 0,
            .app_artifact = .{},
            .relations = &.{},
            .bindings = &.{},
            .checked_error_requires = &.{},
            .identity_solutions_app = &.{},
        };
    }
};

/// Checked identities used to instantiate a platform against an app. These
/// rows are produced while source-to-checked mappings are alive; pairing never
/// walks source annotations or rediscovers identity-variable order.
pub const PlatformTypeInputs = struct {
    pub const Requirement = struct {
        declaration: PlatformRequiredDeclarationId,
        root: CheckedTypeId,
        identities: artifact_serialize.Span,
        aliases: artifact_serialize.Span,
    };
    pub const Alias = struct {
        root: CheckedTypeId,
        backing: CheckedTypeId,
        identity: CheckedTypeId,
    };
    requirements: []Requirement = &.{},
    identities: []CheckedTypeId = &.{},
    aliases: []Alias = &.{},

    fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        names: *const canonical.CanonicalNameStore,
        checked_types: *const CheckedTypePublication,
        declarations: *const PlatformRequiredDeclarationTable,
    ) Allocator.Error!PlatformTypeInputs {
        const rows = try allocator.alloc(Requirement, declarations.declarations.len);
        errdefer allocator.free(rows);
        var identities = std.ArrayList(CheckedTypeId).empty;
        errdefer identities.deinit(allocator);
        var aliases = std.ArrayList(Alias).empty;
        errdefer aliases.deinit(allocator);
        const env = module.moduleEnvConst();
        var orderer = CheckedIdentityOrderer.init(allocator, names, &checked_types.store);
        defer orderer.deinit();
        for (declarations.declarations, rows) |declaration, *row| {
            const root = platformRequiredPayloadForDeclaration(module, checked_types, declaration);
            const formals = try orderer.identityRoots(root);
            const identity_start: u32 = @intCast(identities.items.len);
            try identities.appendSlice(allocator, formals);
            const alias_start: u32 = @intCast(aliases.items.len);
            const required_type = env.requires_types.items.items[declaration.requires_idx];
            for (env.for_clause_aliases.sliceRange(required_type.type_aliases)) |alias| {
                const anno = env.store.getStatement(alias.alias_stmt_idx).s_alias_decl.anno;
                const identity = checked_types.rootForSourceVar(module, ModuleEnv.varFrom(anno)) orelse
                    checkedArtifactInvariant("platform alias identity has no checked root", .{});
                const alias_root = checked_types.rootForSourceVar(module, ModuleEnv.varFrom(alias.alias_stmt_idx)) orelse
                    checkedArtifactInvariant("platform alias has no checked root", .{});
                const payload = checked_types.store.payload(alias_root);
                try aliases.append(allocator, .{
                    .root = alias_root,
                    .backing = if (payload == .alias) payload.alias.backing else alias_root,
                    .identity = identity,
                });
            }
            row.* = .{
                .declaration = declaration.id,
                .root = root,
                .identities = .{ .start = identity_start, .len = @intCast(formals.len) },
                .aliases = .{ .start = alias_start, .len = @intCast(aliases.items.len - alias_start) },
            };
        }
        const owned_identities = try identities.toOwnedSlice(allocator);
        errdefer allocator.free(owned_identities);
        return .{ .requirements = rows, .identities = owned_identities, .aliases = try aliases.toOwnedSlice(allocator) };
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;

    pub const Serialized = extern struct {
        requirements: SerializedSlice(Requirement) = .{},
        identities: SerializedSlice(CheckedTypeId) = .{},
        aliases: SerializedSlice(Alias) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(PlatformTypeInputs, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };
};

const PlatformRelationTypeSubstitutions = struct {
    formals: []CheckedTypeId = &.{},
    actuals: []CheckedTypeId = &.{},

    fn fromRelation(
        allocator: Allocator,
        module_identity: ModuleIdentity,
        names: *canonical.CanonicalNameStore,
        checked_types: *CheckedTypeStore,
        declarations: *const PlatformRequiredDeclarationTable,
        type_inputs: *const PlatformTypeInputs,
        relation_artifacts: []const ImportedModuleView,
        relation: ?PlatformAppRelation,
    ) Allocator.Error!PlatformRelationTypeSubstitutions {
        const active_relation = relation orelse return .{};
        try validatePlatformAppRelationForModule(
            module_identity,
            names,
            checked_types.view(),
            declarations,
            active_relation,
        );

        const app_view = dependencyViewByKey(active_relation.app_artifact, &.{}, relation_artifacts, &.{}) orelse {
            checkedArtifactInvariant("platform/app relation substitution missing app relation artifact", .{});
        };

        var formals = std.ArrayList(CheckedTypeId).empty;
        errdefer formals.deinit(allocator);
        var actuals = std.ArrayList(CheckedTypeId).empty;
        errdefer actuals.deinit(allocator);

        for (active_relation.relations) |input| {
            const required = type_inputs.requirements[@backingInt(input.declaration)];
            std.debug.assert(required.declaration == input.declaration);
            const identity_formals = type_inputs.identities[required.identities.start..][0..required.identities.len];
            if (identity_formals.len != input.identity_len) {
                checkedArtifactInvariant("platform/app relation substitution identity slot count disagrees with the recorded solution", .{});
            }

            const app_identity_roots = active_relation.identity_solutions_app[input.identity_start .. input.identity_start + input.identity_len];

            var projector = CheckedTypeStoreImportProjector.initPreservingSourceInstance(allocator, checked_types, names, app_view.*);
            defer projector.deinit();

            for (identity_formals, app_identity_roots) |formal, app_identity_root| {
                if (builtin.mode == .debug) {
                    std.debug.assert(checkedTypePayloadIsIdentity(checked_types.payload(formal)));
                }
                const actual = try projector.project(app_identity_root);
                try recordRelationSubstitution(allocator, checked_types, &formals, &actuals, formal, actual);
            }

            for (type_inputs.aliases[required.aliases.start..][0..required.aliases.len]) |alias| {
                const actual = relationSubstitutionActual(formals.items, actuals.items, alias.identity) orelse continue;
                try recordRelationSubstitution(allocator, checked_types, &formals, &actuals, alias.root, actual);
                try recordRelationSubstitution(allocator, checked_types, &formals, &actuals, alias.backing, actual);
                try recordRelationSubstitution(allocator, checked_types, &formals, &actuals, alias.identity, actual);
            }
        }

        return .{
            .formals = try formals.toOwnedSlice(allocator),
            .actuals = try actuals.toOwnedSlice(allocator),
        };
    }

    /// Resolve every published source root of this relation-bearing platform
    /// through the relation, before any consumer reads the publication. The
    /// requirement's identity variables stand for exactly the app's solved
    /// types (design.md "Platform/App Relation"), so platform bodies, patterns,
    /// templates, and roots all publish those types; no later stage sees a
    /// requirement formal or re-applies the relation.
    ///
    /// One clone memo is shared across the whole rewrite so each formal-bearing
    /// root has exactly one resolved image, keeping every other identity
    /// variable a single shared root. Roots that cannot reach a formal are
    /// seeded as their own image, so only formal-bearing structure is cloned.
    fn applyToPublication(
        self: *const PlatformRelationTypeSubstitutions,
        allocator: Allocator,
        publication: *CheckedTypePublication,
    ) Allocator.Error!void {
        if (self.formals.len == 0) return;
        const store = &publication.store;

        var reaches = try store.rootsReachingAny(allocator, self.formals);
        defer reaches.deinit(allocator);

        var substitution = self.substitutionIn(allocator);
        defer substitution.deinit();
        substitution.independent = &reaches;

        const source_types = &publication.source_types.?;
        for (store.sealed_var_facts.items, 0..) |var_facts, raw| {
            if (!var_facts.reached) continue;
            const var_: Var = @fromBackingInt(@intCast(raw));
            const source = type_ids.fromVar(var_);
            if (!reaches.contains(source)) continue;
            const resolved = try self.specializeRootWithMemo(allocator, store, source, &substitution);
            try source_types.substituted.put(var_, resolved);
            if (publication.source_schemes.getPtr(var_)) |scheme| {
                scheme.* = try store.ensureSchemeForRoot(allocator, resolved);
            }
        }
    }

    /// One substitution for every root this relation resolves in `store`.
    fn substitutionIn(
        self: *const PlatformRelationTypeSubstitutions,
        allocator: Allocator,
    ) CheckedTypeSubstitution {
        return CheckedTypeSubstitution.init(allocator, self.formals, self.actuals);
    }

    fn specializeRootWithMemo(
        self: *const PlatformRelationTypeSubstitutions,
        allocator: Allocator,
        store: *CheckedTypeStore,
        root: CheckedTypeId,
        substitution: *CheckedTypeSubstitution,
    ) Allocator.Error!CheckedTypeId {
        if (self.formals.len == 0) return root;
        return try store.cloneCheckedTypeRootSubstituting(allocator, root, substitution);
    }

    fn deinit(self: *PlatformRelationTypeSubstitutions, allocator: Allocator) void {
        allocator.free(self.actuals);
        allocator.free(self.formals);
        self.* = .{};
    }
};

/// Append a `formal -> actual` substitution. Repeated equivalent bindings keep
/// the first root; conflicting bindings violate the checked relation invariant.
fn recordRelationSubstitution(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    formal: CheckedTypeId,
    actual: CheckedTypeId,
) Allocator.Error!void {
    if (formal == actual) return;
    try appendUniqueCheckedTypeSubstitution(formals, actuals, allocator, store, formal, actual);
}

/// The recorded actual paired with `formal`, or null if `formal` is unbound.
fn relationSubstitutionActual(
    formals: []const CheckedTypeId,
    actuals: []const CheckedTypeId,
    formal: CheckedTypeId,
) ?CheckedTypeId {
    for (formals, actuals) |existing, actual| {
        if (existing == formal) return actual;
    }
    return null;
}

/// Public `PlatformRequirementRelation` declaration.
pub const PlatformRequirementRelation = struct {
    id: PlatformRequirementRelationId,
    relation: PlatformAppRelationKey,
    module_idx: u32,
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    requested_source_ty_payload: CheckedTypeId,
    /// Root-call dispatch evidence in `app_value.artifact`.
    root_evidence: static_dispatch.EvidenceSpan = .{},
    value_kind: PlatformRequiredValueKind,
};

/// Public `PlatformRequirementRelationTable` declaration.
pub const PlatformRequirementRelationTable = struct {
    relations: []PlatformRequirementRelation = &.{},

    pub const Serialized = extern struct {
        relations: SerializedSlice(PlatformRequirementRelation) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(PlatformRequirementRelationTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    /// `types_allocator` allocates the types the relation creates in
    /// `checked_types`, which live as long as the store; `allocator`
    /// allocates the table's rows.
    pub fn fromRelation(
        allocator: Allocator,
        types_allocator: Allocator,
        module_identity: ModuleIdentity,
        names: *canonical.CanonicalNameStore,
        checked_types: *CheckedTypeStore,
        declarations: *const PlatformRequiredDeclarationTable,
        relation_artifacts: []const ImportedModuleView,
        relation: ?PlatformAppRelation,
    ) Allocator.Error!PlatformRequirementRelationTable {
        const active_relation = relation orelse return .{};
        try validatePlatformAppRelationForModule(
            module_identity,
            names,
            checked_types.view(),
            declarations,
            active_relation,
        );
        if (active_relation.relations.len != active_relation.bindings.len) {
            base.invariant(
                "checked artifact invariant violated: platform/app relation has {d} checked relation rows for {d} bindings",
                .{ active_relation.relations.len, active_relation.bindings.len },
            );
        }

        var seen_declarations: []bool = &.{};
        if (builtin.mode == .debug) {
            seen_declarations = try allocator.alloc(bool, declarations.declarations.len);
            @memset(seen_declarations, false);
        }
        defer {
            if (builtin.mode == .debug) allocator.free(seen_declarations);
        }

        const app_view = dependencyViewByKey(active_relation.app_artifact, &.{}, relation_artifacts, &.{}) orelse {
            checkedArtifactInvariant("platform/app relation missing app relation artifact", .{});
        };

        const rows = try allocator.alloc(PlatformRequirementRelation, active_relation.relations.len);
        errdefer allocator.free(rows);

        for (active_relation.relations, 0..) |input, i| {
            const declaration = declarations.lookupByDeclarationId(input.declaration) orelse {
                base.invariant(
                    "checked artifact invariant violated: platform/app checked relation {d} references unknown requirement declaration",
                    .{i},
                );
            };
            const declaration_index: usize = @intCast(@backingInt(input.declaration));
            if (builtin.mode == .debug) {
                if (seen_declarations[declaration_index]) {
                    base.invariant(
                        "checked artifact invariant violated: platform/app checked relation binds declaration {d} more than once",
                        .{declaration_index},
                    );
                }
                seen_declarations[declaration_index] = true;
            }
            if (input.requires_idx != declaration.requires_idx) {
                base.invariant(
                    "checked artifact invariant violated: platform/app checked relation {d} maps declaration {d} to required index {d}, expected {d}",
                    .{ i, declaration_index, input.requires_idx, declaration.requires_idx },
                );
            }
            if (!std.meta.eql(input.app_value.artifact.bytes, active_relation.app_artifact.bytes)) {
                base.invariant(
                    "checked artifact invariant violated: platform/app checked relation {d} points at a value outside the app artifact",
                    .{i},
                );
            }
            // The requirement type as the checker solved it, recorded on the
            // app's artifact and projected into this publication's store.
            var projector = CheckedTypeStoreImportProjector.initPreservingSourceInstance(types_allocator, checked_types, names, app_view.*);
            defer projector.deinit();
            const payload = try projector.project(input.solved_root_app);

            rows[i] = .{
                .id = input.id,
                .relation = active_relation.key,
                .module_idx = module_identity.module_idx,
                .declaration = input.declaration,
                .requires_idx = input.requires_idx,
                .app_value = input.app_value,
                .requested_source_ty_payload = payload,
                .root_evidence = input.root_evidence,
                .value_kind = input.value_kind,
            };
        }

        return .{ .relations = rows };
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;

    pub fn lookupByRelationId(self: *const PlatformRequirementRelationTable, relation_id: PlatformRequirementRelationId) ?PlatformRequirementRelation {
        const raw = @backingInt(relation_id);
        if (raw >= self.relations.len) return null;
        return self.relations[raw];
    }
};

/// Public `PlatformRequirementSolution` declaration.
///
/// One row of the check-time platform/app correspondence carried on the APP's
/// checked artifact: the exported app value a platform requirement resolved to
/// during checking, the requirement type as solved in the app's env, and the
/// solved types of the requirement's identity variables.
pub const PlatformRequirementSolution = struct {
    /// requires-clause index; equals the platform-side
    /// `PlatformRequiredDeclarationId` by construction (both are assigned
    /// positionally over the platform's `requires_types`).
    requires_idx: u32,
    def: CIR.Def.Idx,
    pattern: CIR.Pattern.Idx,
    /// The requirement type as solved in the app env, in the app's store.
    solved_root: CheckedTypeId,
    /// The solution's index among the module's checker-recorded solutions,
    /// which `CheckedDispatch.platformRequirementRootEvidence` reads by.
    source_solution: u32,
    value_kind: PlatformRequiredValueKind,
    /// Range into the table's `identity_solutions`; the offset within the
    /// range is the canonical identity slot of the platform requirement
    /// payload (the first-encounter order the canonical key digest assigns).
    identity_start: u32,
    identity_len: u32,
};

/// Public `PlatformRequirementSolutionTable` declaration.
///
/// The relation is recorded here, where it is proven: when an app checks
/// against a platform's requirement surface, each successful unification's
/// output travels as these rows. Finalization builds the platform/app
/// relation by reading them—it never re-resolves app exports by name and
/// never re-derives identity substitutions structurally. Empty for every
/// module that is not an app root checked against a platform.
pub const PlatformRequirementSolutionTable = struct {
    solutions: []PlatformRequirementSolution = &.{},
    /// Solved app types for requirement identity variables, slot-ordered per
    /// solution row (`identity_start`/`identity_len` ranges).
    identity_solutions: []CheckedTypeId = &.{},

    pub const Serialized = extern struct {
        solutions: SerializedSlice(PlatformRequirementSolution) = .{},
        identity_solutions: SerializedSlice(CheckedTypeId) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(PlatformRequirementSolutionTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn lookupByRequiredIndex(
        self: *const PlatformRequirementSolutionTable,
        requires_idx: u32,
    ) ?PlatformRequirementSolution {
        for (self.solutions) |solution| {
            if (solution.requires_idx == requires_idx) return solution;
        }
        return null;
    }

    pub fn identitySlice(
        self: *const PlatformRequirementSolutionTable,
        solution: PlatformRequirementSolution,
    ) []const CheckedTypeId {
        return self.identity_solutions[solution.identity_start .. solution.identity_start + solution.identity_len];
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;
};

/// Materialize the checker-recorded successful requirement solutions into
/// checked type roots in the app's store. A row whose types contain an error
/// is omitted here; platform/app relation construction converts that exact
/// absent requires index into an explicit checked-error requirement outcome.
fn platformRequirementSolutionTableFromInputs(
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *CheckedTypeStore,
    top_level_values: *const TopLevelValueTable,
    exported_procedure_bindings: *const ExportedProcedureBindingTable,
    exported_const_templates: *const ExportedConstTemplateTable,
    inputs: []const ModuleEnv.PlatformRequirementSolution,
) Allocator.Error!PlatformRequirementSolutionTable {
    if (inputs.len == 0) return .{};

    var active = try CheckedSourceTypeRoots.init(allocator, module);
    defer active.deinit();

    var solutions = std.ArrayList(PlatformRequirementSolution).empty;
    errdefer solutions.deinit(allocator);
    var identity_solutions = std.ArrayList(CheckedTypeId).empty;
    errdefer identity_solutions.deinit(allocator);

    for (inputs, 0..) |input, source_solution| {
        switch (input.outcome) {
            .checked_error => continue,
            .success => {},
        }

        const top_level = top_level_values.lookupByDef(input.def) orelse {
            checkedArtifactInvariant("platform requirement solution references a def with no published top-level value", .{});
        };
        const value_kind: PlatformRequiredValueKind = if (input.is_function) .procedure_value else .const_value;
        const kind_matches = switch (top_level.value) {
            .procedure_binding => value_kind == .procedure_value,
            .const_ref => value_kind == .const_value,
        };
        if (!kind_matches) {
            checkedArtifactInvariant("platform requirement solution value kind disagrees with the published app value", .{});
        }
        if (builtin.mode == .debug) {
            const is_exported = switch (top_level.value) {
                .procedure_binding => blk: {
                    for (exported_procedure_bindings.bindings) |binding| {
                        if (binding.binding.def == top_level.def and binding.binding.pattern == top_level.pattern) break :blk true;
                    }
                    break :blk false;
                },
                .const_ref => blk: {
                    for (exported_const_templates.templates) |template| {
                        if (template.def == top_level.def and template.pattern == top_level.pattern) break :blk true;
                    }
                    break :blk false;
                },
            };
            if (!is_exported) {
                base.invariant("checked artifact invariant violated: platform requirement solution references an unexported app value", .{});
            }
        }

        const identity_start: u32 = @intCast(identity_solutions.items.len);
        const identity_vars = module.moduleEnvConst().platformRequirementIdentityVars(input);
        for (identity_vars) |identity_var| {
            const identity_root = try appendCheckedTypeRoot(allocator, module, checked_types, &active, identity_var);
            try identity_solutions.append(allocator, identity_root);
        }
        const solved_root = try appendCheckedTypeRoot(allocator, module, checked_types, &active, input.solved_var);
        try solutions.append(allocator, .{
            .requires_idx = input.requires_idx,
            .def = input.def,
            .pattern = top_level.pattern,
            .solved_root = solved_root,
            .source_solution = @intCast(source_solution),
            .value_kind = value_kind,
            .identity_start = identity_start,
            .identity_len = @intCast(identity_vars.len),
        });
    }

    return .{
        .solutions = try solutions.toOwnedSlice(allocator),
        .identity_solutions = try identity_solutions.toOwnedSlice(allocator),
    };
}

/// Public `PlatformRequiredBinding` declaration.
pub const PlatformRequiredBinding = struct {
    id: PlatformRequiredBindingId,
    relation: PlatformAppRelationKey,
    module_idx: u32,
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    checked_relation: PlatformRequirementRelationId,
    value_use: StoredPlatformRequiredValueUse,
};

/// Public `PlatformRequiredBindingTable` declaration.
pub const PlatformRequiredBindingTable = struct {
    bindings: []PlatformRequiredBinding = &.{},
    checked_error_requires: []u32 = &.{},
    closure_pool: ClosurePool = ClosurePool.empty,

    pub fn fromRelation(
        allocator: Allocator,
        module_identity: ModuleIdentity,
        names: *const canonical.CanonicalNameStore,
        type_view: CheckedTypeStoreView,
        declarations: *const PlatformRequiredDeclarationTable,
        relations: *const PlatformRequirementRelationTable,
        relation: ?PlatformAppRelation,
    ) Allocator.Error!PlatformRequiredBindingTable {
        const active_relation = relation orelse return .{};
        try validatePlatformAppRelationForModule(
            module_identity,
            names,
            type_view,
            declarations,
            active_relation,
        );
        if (active_relation.bindings.len + active_relation.checked_error_requires.len != declarations.declarations.len) {
            base.invariant(
                "checked artifact invariant violated: platform/app relation has {d} bindings and {d} checked errors for {d} platform requirements",
                .{ active_relation.bindings.len, active_relation.checked_error_requires.len, declarations.declarations.len },
            );
        }
        var seen_declarations: []bool = &.{};
        if (builtin.mode == .debug) {
            seen_declarations = try allocator.alloc(bool, declarations.declarations.len);
            @memset(seen_declarations, false);
        }
        defer {
            if (builtin.mode == .debug) allocator.free(seen_declarations);
        }

        const bindings = try allocator.alloc(PlatformRequiredBinding, active_relation.bindings.len);
        const checked_error_requires = try allocator.dupe(u32, active_relation.checked_error_requires);
        var closure_pool = ClosurePool.empty;
        errdefer {
            allocator.free(bindings);
            allocator.free(checked_error_requires);
            closure_pool.deinit(allocator);
        }

        if (builtin.mode == .debug) {
            for (checked_error_requires) |requires_idx| {
                const declaration = declarations.lookupByRequiredIndex(requires_idx) orelse {
                    base.invariant(
                        "checked artifact invariant violated: platform checked-error requirement {d} has no declaration",
                        .{requires_idx},
                    );
                };
                const declaration_index: usize = @intCast(@backingInt(declaration.id));
                if (seen_declarations[declaration_index]) {
                    base.invariant(
                        "checked artifact invariant violated: platform requirement declaration {d} has multiple outcomes",
                        .{declaration_index},
                    );
                }
                seen_declarations[declaration_index] = true;
            }
        }

        for (active_relation.bindings, 0..) |binding, i| {
            const declaration = declarations.lookupByDeclarationId(binding.declaration) orelse {
                base.invariant(
                    "checked artifact invariant violated: platform/app binding {d} references unknown requirement declaration",
                    .{i},
                );
            };
            const declaration_index: usize = @intCast(@backingInt(binding.declaration));
            if (builtin.mode == .debug) {
                if (seen_declarations[declaration_index]) {
                    base.invariant(
                        "checked artifact invariant violated: platform/app relation binds platform requirement declaration {d} more than once",
                        .{declaration_index},
                    );
                }
                seen_declarations[declaration_index] = true;
            }
            if (declaration.requires_idx != binding.requires_idx) {
                base.invariant(
                    "checked artifact invariant violated: platform/app binding {d} maps declaration {d} to required index {d}, expected {d}",
                    .{ i, declaration_index, binding.requires_idx, declaration.requires_idx },
                );
            }
            if (!std.meta.eql(binding.app_value.artifact.bytes, active_relation.app_artifact.bytes)) {
                base.invariant(
                    "checked artifact invariant violated: platform/app binding {d} points at a value outside the app artifact",
                    .{i},
                );
            }
            const checked_relation = relations.lookupByRelationId(binding.checked_relation) orelse {
                base.invariant(
                    "checked artifact invariant violated: platform/app binding {d} references missing checked relation",
                    .{i},
                );
            };
            validatePlatformBindingRelation(binding.declaration, binding.requires_idx, binding.app_value, binding.value_use.tag(), checked_relation, i);
            const value_use = platformRequiredValueUseWithRelation(binding.value_use, checked_relation);
            const stored_value_use = try copyPlatformRequiredValueUse(&closure_pool, allocator, value_use);
            bindings[i] = .{
                .id = @fromBackingInt(@intCast(@as(u32, @intCast(i)))),
                .relation = active_relation.key,
                .module_idx = module_identity.module_idx,
                .declaration = binding.declaration,
                .requires_idx = binding.requires_idx,
                .app_value = binding.app_value,
                .checked_relation = binding.checked_relation,
                .value_use = stored_value_use,
            };
        }

        return .{
            .bindings = bindings,
            .checked_error_requires = checked_error_requires,
            .closure_pool = closure_pool,
        };
    }

    pub fn deinit(self: *PlatformRequiredBindingTable, allocator: Allocator) void {
        if (!self.closure_pool.serialized) {
            allocator.free(self.bindings);
            allocator.free(self.checked_error_requires);
        }
        self.closure_pool.deinit(allocator);
        self.* = .{};
    }

    /// Materialize a binding's relation template closure from this table's pool.
    pub fn relationClosure(self: *const PlatformRequiredBindingTable, binding: PlatformRequiredBinding) ImportedTemplateClosureView {
        return self.closure_pool.reconstruct(switch (binding.value_use) {
            .const_value => |const_use| const_use.relation_template_closure,
            .procedure_value => |procedure_use| procedure_use.relation_template_closure,
        });
    }

    /// Relocatable serialized form: the POD row slice plus the closure pool.
    pub const Serialized = extern struct {
        bindings: SerializedSlice(PlatformRequiredBinding) = .{},
        checked_error_requires: SerializedSlice(u32) = .{},
        closure_pool: ClosurePool.Serialized = .{},

        comptime {
            std.debug.assert(artifact_serialize.relocatablePointerCount(Serialized) == 14);
        }

        const Serde = artifact_serialize.SliceStoreSerde(PlatformRequiredBindingTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn lookupByRequiredIndex(self: *const PlatformRequiredBindingTable, requires_idx: u32) ?PlatformRequiredBinding {
        for (self.bindings) |binding| {
            if (binding.requires_idx == requires_idx) return binding;
        }
        return null;
    }

    pub fn isCheckedError(self: *const PlatformRequiredBindingTable, requires_idx: u32) bool {
        for (self.checked_error_requires) |checked_error_requires_idx| {
            if (checked_error_requires_idx == requires_idx) return true;
        }
        return false;
    }

    pub fn lookupByBindingId(self: *const PlatformRequiredBindingTable, binding_id: u32) ?PlatformRequiredBinding {
        if (binding_id >= self.bindings.len) return null;
        return self.bindings[binding_id];
    }
};

fn validatePlatformAppRelationForModule(
    module_identity: ModuleIdentity,
    names: *const canonical.CanonicalNameStore,
    type_view: CheckedTypeStoreView,
    declarations: *const PlatformRequiredDeclarationTable,
    active_relation: PlatformAppRelation,
) Allocator.Error!void {
    if (active_relation.platform_module_idx != module_identity.module_idx) {
        base.invariant(
            "checked artifact invariant violated: platform/app relation belongs to module {d}, not platform module {d}",
            .{ active_relation.platform_module_idx, module_identity.module_idx },
        );
    }
    // Debug builds check the relation was built against these declarations.
    if (builtin.mode == .debug) {
        const expected_requirement_context = PlatformRequirementContextKey.compute(
            module_identity,
            try declarations.identityHash(names, type_view),
        );
        if (!std.meta.eql(active_relation.requirement_context.bytes, expected_requirement_context.bytes)) {
            base.invariant(
                "checked artifact invariant violated: platform/app relation requirement context does not match the current platform requirement declarations",
                .{},
            );
        }
    }
    const expected_key = PlatformAppRelationKey.compute(
        active_relation.app_artifact,
        active_relation.requirement_context,
    );
    if (!std.meta.eql(active_relation.key.bytes, expected_key.bytes)) {
        base.invariant(
            "checked artifact invariant violated: platform/app relation key does not match the current platform requirement declarations",
            .{},
        );
    }
}

fn platformRequiredPayloadForDeclaration(
    module: TypedCIR.Module,
    checked_types: *const CheckedTypePublication,
    declaration: PlatformRequiredDeclaration,
) CheckedTypeId {
    const module_env = module.moduleEnvConst();
    if (declaration.requires_idx >= module_env.requires_types.items.items.len) {
        base.invariant(
            "checked artifact invariant violated: platform requirement declaration {d} has out-of-range required index {d}",
            .{ @backingInt(declaration.id), declaration.requires_idx },
        );
    }
    const required_type = module_env.requires_types.items.items[declaration.requires_idx];
    return checked_types.rootForSourceVar(module, ModuleEnv.varFrom(required_type.type_anno)) orelse {
        base.invariant(
            "checked artifact invariant violated: platform requirement declaration {d} has no platform-owned checked payload",
            .{@backingInt(declaration.id)},
        );
    };
}

/// Per-scheme identity origins for `EnclosingDispatchIdentity`, computed on
/// first use and pooled. Each set is the key builder's own identity
/// enumeration of the scheme root (`CheckedIdentityOrderer`),
/// which reaches a where-clause signature through the constrained variable's
/// callable, normalized through `CheckedTypeStore.identityOrigin` so a
/// relation-substituted template root names a variable the way a specialized
/// plan callable does.
const EnclosingIdentityIndex = struct {
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *const CheckedTypeStore,
    /// Identity origins per scheme root; each span indexes `pool`.
    spans_by_root: collections.DenseMap(CheckedTypeId, artifact_serialize.Span),
    pool: std.ArrayList(CheckedTypeId),
    orderer: CheckedIdentityOrderer,

    fn init(
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        store: *const CheckedTypeStore,
    ) EnclosingIdentityIndex {
        return .{
            .allocator = allocator,
            .names = names,
            .store = store,
            .spans_by_root = collections.DenseMap(CheckedTypeId, artifact_serialize.Span).init(allocator),
            .pool = .empty,
            .orderer = CheckedIdentityOrderer.init(allocator, names, store),
        };
    }

    fn deinit(self: *EnclosingIdentityIndex) void {
        self.pool.deinit(self.allocator);
        self.spans_by_root.deinit();
        self.orderer.deinit();
    }

    /// Whether the scheme published at `scheme_root` quantifies the identity
    /// origin `origin`.
    fn schemeQuantifies(
        self: *EnclosingIdentityIndex,
        scheme_root: CheckedTypeId,
        origin: CheckedTypeId,
    ) Allocator.Error!bool {
        const span = try self.identityOriginsOf(scheme_root);
        for (self.pool.items[span.start .. span.start + span.len]) |quantified| {
            if (quantified == origin) return true;
        }
        return false;
    }

    fn identityOriginsOf(
        self: *EnclosingIdentityIndex,
        scheme_root: CheckedTypeId,
    ) Allocator.Error!artifact_serialize.Span {
        if (self.spans_by_root.get(scheme_root)) |span| return span;
        const start: u32 = @intCast(self.pool.items.len);
        if (try self.store.rootContainsIdentityVariables(scheme_root)) {
            const roots = try self.orderer.identityRoots(scheme_root);
            try self.pool.ensureUnusedCapacity(self.allocator, roots.len);
            for (roots) |root| self.pool.appendAssumeCapacity(self.store.identityOrigin(root));
        }
        const span: artifact_serialize.Span = .{
            .start = start,
            .len = @intCast(self.pool.items.len - start),
        };
        try self.spans_by_root.put(scheme_root, span);
        return span;
    }
};

/// One scheme context a collected span attributes to a dispatch site: the
/// enclosing template's checked function root (null for a defaulted-field
/// expression, which no template quantifies) and the generalized-local scope
/// that owns the reference.
const EnclosingDispatchSite = struct {
    template_root: ?CheckedTypeId,
    scope: DispatchScope,
};

/// The schemes enclosing one dispatch site, asked which variables they
/// quantify: for every span that references the site, the enclosing
/// template's checked function root (with the where-clause signatures its
/// variables carry) and every generalized-local scope between the template
/// and the site. A variable any referencing context quantifies is a
/// specialization input. A site no span reaches (dead code) has no enclosing
/// scheme and is classified like a root edge.
const EnclosingDispatchIdentity = struct {
    index: *EnclosingIdentityIndex,
    sites: []const EnclosingDispatchSite,
    scopes: []const DispatchRefScope,

    /// Whether any referencing context—its template, that template's
    /// where-clause signatures, or an enclosing generalized-local scope—
    /// quantifies the variable at `root`.
    fn quantifies(self: EnclosingDispatchIdentity, root: CheckedTypeId) Allocator.Error!bool {
        const origin = self.index.store.identityOrigin(root);
        for (self.sites) |site| {
            if (site.template_root) |template_root| {
                if (try self.index.schemeQuantifies(template_root, origin)) return true;
            }
            var current: ?DispatchScopeId = switch (site.scope) {
                .root => null,
                .generalized => |id| id,
            };
            while (current) |id| {
                const raw_scope = @backingInt(id);
                if (raw_scope >= self.scopes.len) {
                    checkedArtifactInvariant("dispatch site referenced a missing generalized-local scope", .{});
                }
                const scope = self.scopes[raw_scope];
                if (try self.index.schemeQuantifies(scope.scheme_root, origin)) return true;
                current = scope.parent;
            }
        }
        return false;
    }
};

/// Whether a resolved direct-dispatch callable specializes without any input
/// from the enclosing specialization (design.md "Static Dispatch In Monotype",
/// `direct_closed`). A rigid, a flex with no row default, a numeric-defaulting
/// flex, and a constrained flex each stand for a specialization input, as does
/// a defaultable row tail the enclosing schemes quantify; a defaultable,
/// unconstrained row tail nothing enclosing quantifies has exactly one
/// instantiation—its row default, which the closed path seals it to—and does
/// not. `rootContainsIdentityVariables` keeps answering the digest-identity
/// question (is any variable reachable at all); this answers the
/// specialization question.
fn callableIdentityIsSpecializationIndependent(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    callable: CheckedTypeId,
    enclosing: EnclosingDispatchIdentity,
) Allocator.Error!bool {
    if (!try store.rootContainsIdentityVariables(callable)) return true;
    var visited = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer visited.deinit();
    // The answer is the conjunction of every reachable type's own verdict;
    // types are visited once, in source order, from an explicit work list.
    var pending: std.ArrayListUnmanaged(CheckedTypeId) = .empty;
    defer pending.deinit(allocator);
    try pending.append(allocator, callable);
    while (pending.pop()) |root| {
        if ((try visited.getOrPut(root)).found_existing) continue;
        const start = pending.items.len;
        const payload = store.payload(root);
        switch (payload) {
            .pending => checkedArtifactInvariant("direct dispatch classification reached a pending checked type", .{}),
            .field_kind, .err, .empty_record, .empty_tag_union => {},
            .flex, .rigid => if (!payload.variableSealsToRowDefault() or try enclosing.quantifies(root)) return false,
            .alias => |alias| {
                try pending.appendSlice(allocator, alias.args);
                try pending.append(allocator, alias.backing);
            },
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    try pending.append(allocator, field.ty);
                    if (field.kind.undeterminedVariable()) |variable| try pending.append(allocator, variable);
                }
                try pending.append(allocator, record.ext);
            },
            .tuple => |elems| try pending.appendSlice(allocator, elems),
            .nominal => |nominal| {
                try pending.appendSlice(allocator, nominal.args);
                try pending.appendSlice(allocator, nominal.padding_field_types);
            },
            .function => |function| {
                try pending.appendSlice(allocator, function.args);
                try pending.append(allocator, function.ret);
            },
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    try pending.appendSlice(allocator, tag.args);
                }
                try pending.append(allocator, tag_union.ext);
            },
        }
        std.mem.reverse(CheckedTypeId, pending.items[start..]);
    }
    return true;
}

/// One dispatch resolution's specializer: its callable projection and
/// instantiation memo, its evidence-closure memo over the resolution's own
/// pool, and the enclosing-identity index.
const ResolvedDispatchCallableSpecializer = struct {
    allocator: Allocator,
    names: *canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    owner: ModuleId,
    imports: CheckedImportViews,
    evidence_nodes: []const static_dispatch.EvidenceNode,
    evidence_refs: []const static_dispatch.CheckedEvidence,
    instantiated_pairs: std.AutoHashMapUnmanaged(ResolvedDispatchCallablePair, CheckedTypeId) = .empty,
    evidence_closure: []DirectEvidenceClosure,
    identity_index: EnclosingIdentityIndex,

    fn deinit(self: *ResolvedDispatchCallableSpecializer) void {
        self.identity_index.deinit();
        self.instantiated_pairs.deinit(self.allocator);
    }

    /// Specialize a pending direct plan's callable. The caller holds the
    /// store's creation lock.
    fn specializePlan(self: *ResolvedDispatchCallableSpecializer, plan: *static_dispatch.PlanResolution) Allocator.Error!void {
        switch (plan.resolution) {
            .direct_pending => |node_id| plan.callable_ty = try self.specializeCallable(node_id, plan.callable_ty),
            .direct_closed, .direct_parametric => checkedArtifactInvariant("static dispatch plan was finalized more than once", .{}),
            .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
        }
    }

    /// Classify a pending direct plan over its specialized callable.
    fn classifyPlan(
        self: *ResolvedDispatchCallableSpecializer,
        plan: *static_dispatch.PlanResolution,
        enclosing: EnclosingDispatchIdentity,
    ) Allocator.Error!void {
        switch (plan.resolution) {
            .direct_pending => |node_id| plan.resolution = try self.classify(node_id, plan.callable_ty, enclosing),
            .direct_closed, .direct_parametric => checkedArtifactInvariant("static dispatch plan was finalized more than once", .{}),
            .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
        }
    }

    /// Specialize the callables of an iterator plan's pending direct calls.
    /// The caller holds the store's creation lock.
    fn specializeIteratorPlan(self: *ResolvedDispatchCallableSpecializer, iterator_plan: *static_dispatch.IteratorPlanResolution) Allocator.Error!void {
        inline for (.{ .{ &iterator_plan.iter, &iterator_plan.iter_callable_ty }, .{ &iterator_plan.next, &iterator_plan.next_callable_ty } }) |call| {
            switch (call[0].*) {
                .direct_pending => |node_id| call[1].* = try self.specializeCallable(node_id, call[1].*),
                .direct_closed, .direct_parametric => checkedArtifactInvariant("iterator dispatch plan was finalized more than once", .{}),
                .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
            }
        }
    }

    /// Classify an iterator plan's pending direct calls over their
    /// specialized callables.
    fn classifyIteratorPlan(
        self: *ResolvedDispatchCallableSpecializer,
        iterator_plan: *static_dispatch.IteratorPlanResolution,
        enclosing: EnclosingDispatchIdentity,
    ) Allocator.Error!void {
        inline for (.{ .{ &iterator_plan.iter, &iterator_plan.iter_callable_ty }, .{ &iterator_plan.next, &iterator_plan.next_callable_ty } }) |call| {
            switch (call[0].*) {
                .direct_pending => |node_id| call[0].* = try self.classify(node_id, call[1].*, enclosing),
                .direct_closed, .direct_parametric => checkedArtifactInvariant("iterator dispatch plan was finalized more than once", .{}),
                .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
            }
        }
    }

    /// Project the resolved target's callable into this store and specialize
    /// the call's recorded callable against it.
    fn specializeCallable(
        self: *ResolvedDispatchCallableSpecializer,
        node_id: static_dispatch.EvidenceNodeId,
        plan_callable: CheckedTypeId,
    ) Allocator.Error!CheckedTypeId {
        const target = self.evidence_nodes[node_id.index].target;
        const target_callable = try projectResolvedDispatchTargetCallable(
            self.allocator,
            self.names,
            self.store,
            self.owner,
            self.imports,
            target,
        );
        return try instantiateResolvedDispatchTargetCallableMemoized(
            self.allocator,
            .{ .store = self.store, .names = self.names, .module = self.owner, .resolver = self.imports.resolver() },
            target_callable,
            plan_callable,
            &self.instantiated_pairs,
        );
    }

    fn classify(
        self: *ResolvedDispatchCallableSpecializer,
        node_id: static_dispatch.EvidenceNodeId,
        callable_ty: CheckedTypeId,
        enclosing: EnclosingDispatchIdentity,
    ) Allocator.Error!static_dispatch.CheckedCallResolution {
        const direct: static_dispatch.DirectCall = .{ .evidence = node_id };
        const closed = (try callableIdentityIsSpecializationIndependent(self.allocator, self.store, callable_ty, enclosing)) and
            try directEvidenceIsClosed(self.allocator, self.evidence_nodes, self.evidence_refs, node_id, self.evidence_closure);
        return if (closed) .{ .direct_closed = direct } else .{ .direct_parametric = direct };
    }
};

const DirectEvidenceClosure = enum(u8) {
    unknown,
    visiting,
    closed,
    parametric,
};

/// Whether a concrete target's entire nested evidence tree is independent of
/// the enclosing specialization. This is the evidence half of
/// `direct_closed`: a structurally closed callable whose nested evidence still
/// forwards a constraint is parametric, not closed. Nested evidence lies in
/// the same pool as the node that names it.
fn directEvidenceIsClosed(
    allocator: Allocator,
    nodes: []const static_dispatch.EvidenceNode,
    refs: []const static_dispatch.CheckedEvidence,
    root: static_dispatch.EvidenceNodeId,
    states: []DirectEvidenceClosure,
) Allocator.Error!bool {
    // Each node being decided is a frame over its nested evidence, and each
    // entry's callable contracts are a frame of their own, so nested
    // requirement depth never becomes native call depth.
    const Frame = struct {
        /// The node this frame decides; null for a callable-contract vector,
        /// which decides only its enclosing node.
        node: ?usize,
        refs: []const static_dispatch.CheckedEvidence,
        next: usize = 0,
    };
    var frames: std.ArrayListUnmanaged(Frame) = .empty;
    defer frames.deinit(allocator);

    var result = switch (directEvidenceEnter(nodes, refs, root, states)) {
        .decided => |closed| return closed,
        .nested => |nested| blk: {
            try frames.append(allocator, .{ .node = root.index, .refs = nested });
            break :blk true;
        },
    };
    while (frames.items.len > 0) {
        const frame = &frames.items[frames.items.len - 1];
        if (!result) {
            if (frame.node) |node| states[node] = .parametric;
            _ = frames.pop();
            continue;
        }
        if (frame.next == frame.refs.len) {
            if (frame.node) |node| states[node] = .closed;
            _ = frames.pop();
            continue;
        }
        const evidence = frame.refs[frame.next];
        frame.next += 1;
        const contracts = refs[evidence.callable_contracts.start..][0..evidence.callable_contracts.len];
        if (contracts.len != 0) try frames.append(allocator, .{ .node = null, .refs = contracts });
        switch (evidence.resolution) {
            .direct => |child| switch (directEvidenceEnter(nodes, refs, child, states)) {
                .decided => |closed| result = closed,
                .nested => |nested| try frames.append(allocator, .{ .node = child.index, .refs = nested }),
            },
            .constraint, .from_callable, .from_scheme => result = false,
            .structural, .checked_error, .unreachable_value => {},
        }
    }
    return result;
}

/// A node's answer when it is already decided or decided by itself; otherwise
/// mark it visiting and return the nested evidence that decides it.
fn directEvidenceEnter(
    nodes: []const static_dispatch.EvidenceNode,
    refs: []const static_dispatch.CheckedEvidence,
    node_id: static_dispatch.EvidenceNodeId,
    states: []DirectEvidenceClosure,
) union(enum) { decided: bool, nested: []const static_dispatch.CheckedEvidence } {
    const raw_node = node_id.index;
    if (raw_node >= states.len) checkedArtifactInvariant("direct evidence closure referenced a missing node", .{});
    switch (states[raw_node]) {
        .closed => return .{ .decided = true },
        .parametric => return .{ .decided = false },
        .visiting => checkedArtifactInvariant("direct evidence closure contained a cycle", .{}),
        .unknown => states[raw_node] = .visiting,
    }
    const node = nodes[raw_node];
    switch (node.target.kind) {
        .local_proc => {
            // The declaration identity is checked data, but its capture/context
            // identity belongs to the enclosing Monotype specialization.
            states[raw_node] = .parametric;
            return .{ .decided = false };
        },
        .procedure => {},
        .structural => checkedArtifactInvariant("direct evidence closure contained a structural target", .{}),
    }
    switch (node.nested) {
        // A target reached through an alias takes its evidence from the
        // alias's forwarded lookup, which belongs to the specialization.
        .from_callable, .through_alias => {
            states[raw_node] = .parametric;
            return .{ .decided = false };
        },
        .resolved => |span| return .{ .nested = refs[span.start .. span.start + span.len] },
    }
}

/// The identity of the conversion root of `literal`: the literal itself.
pub fn literalConversionRootId(literal: LiteralNode) ComptimeRootId {
    const kind: u128 = @backingInt(ComptimeRootId.Kind.literal_conversion);
    const pattern: u128 = switch (literal) {
        .expr => 0,
        .pattern => 1,
    };
    return @fromBackingInt((kind << ComptimeRootId.kind_shift) | (pattern << 32) | literal.node());
}

/// The identity of the literal argument root converting literal requirement
/// `requirement` of the scheme `edge` instantiates at the type the edge
/// fixes.
pub fn literalArgumentRootId(edge: LiteralEdge, requirement: u32) ComptimeRootId {
    const kind: u128 = @backingInt(ComptimeRootId.Kind.literal_argument);
    const edge_bits: u128 = switch (edge) {
        .node => |id| @as(u64, @bitCast(id)),
        .use => |expr| (@as(u128, 1) << 64) | @backingInt(expr),
        .literal => checkedArtifactInvariant("a literal argument root was named by a literal requirement's own literal", .{}),
    };
    return @fromBackingInt((kind << ComptimeRootId.kind_shift) | (edge_bits << 32) | requirement);
}

/// What a literal root's identity names (`literalConversionRootId`,
/// `literalArgumentRootId`).
pub const LiteralRootName = union(enum) {
    conversion: LiteralNode,
    argument: struct { edge: LiteralEdge, requirement: u32 },
};

/// What literal root `id` names, or null for a root of the module's root
/// table.
pub fn literalRootName(id: ComptimeRootId) ?LiteralRootName {
    const raw = @backingInt(id);
    switch (id.kind()) {
        .row => return null,
        .literal_conversion => {
            const node: u32 = @truncate(raw);
            return .{ .conversion = if ((raw >> 32) & 1 == 0) .{ .expr = @fromBackingInt(node) } else .{ .pattern = @fromBackingInt(node) } };
        },
        .literal_argument => {
            const edge_bits = raw >> 32;
            const edge: LiteralEdge = if ((edge_bits >> 64) & 1 == 0)
                .{ .node = @bitCast(@as(u64, @truncate(edge_bits))) }
            else
                .{ .use = @fromBackingInt(@as(u32, @truncate(edge_bits))) };
            return .{ .argument = .{ .edge = edge, .requirement = @truncate(raw) } };
        },
    }
}

/// The entry wrapper of literal root `root`: a template named by the root's
/// identity, which no row of the template table holds.
pub fn literalRootWrapperTemplate(root: ComptimeRootId) canonical.CheckedProcedureTemplateId {
    std.debug.assert(root.kind() != .row);
    return @fromBackingInt(@backingInt(root));
}

/// The literal root whose entry wrapper `template` is, or null for a template
/// of the template table.
pub fn templateLiteralRoot(template: canonical.CheckedProcedureTemplateId) ?ComptimeRootId {
    if (template.rowIndex() != null) return null;
    return @fromBackingInt(@backingInt(template));
}

/// A literal whose conversion is a literal conversion root: its custom
/// conversion's dispatch resolution is closed.
pub const LiteralConversionCandidate = struct {
    literal: LiteralNode,
    kind: CompileTimeLiteralConversionKind,
    plan: static_dispatch.StaticDispatchPlanId,
    ty: CheckedTypeId,
    evidence: static_dispatch.EvidenceNodeId,
};

/// The conversion root the literal at `raw_node` has, or null. Literal roots
/// have no lexical evidence parameters, so a literal has one only where its
/// module's dispatch resolution proved the complete conversion closed. A
/// concrete receiver alone does not prove this: nested codec requirements can
/// still belong to the enclosing scheme. Those literals stay in that scheme
/// and are hoisted by its specialization.
pub fn literalConversionCandidate(bodies: CheckedBodies, dispatch: CheckedDispatch, raw_node: u32) Allocator.Error!?LiteralConversionCandidate {
    const literal = bodies.env.store.literalDispatchPlanForNode(@fromBackingInt(raw_node)) orelse return null;
    switch (literal.dispatchResolution()) {
        .builtin_direct, .specialization_dispatch, .checked_error => return null,
        .custom_dispatch => {},
        .unresolved => checkedArtifactInvariant("an unresolved literal reached literal root selection", .{}),
    }
    const literal_node: LiteralNode = switch (bodies.index().nodeKind(raw_node)) {
        .expr => switch (bodies.exprData(@fromBackingInt(raw_node))) {
            .numeral => .{ .expr = @fromBackingInt(raw_node) },
            .str => if (bodies.quoteIsCustom(raw_node)) .{ .expr = @fromBackingInt(raw_node) } else return null,
            // Diagnostic recovery retired the conversion.
            .runtime_error => return null,
            .str_segment, .bytes_literal, .lookup_local, .lookup_external, .lookup_required, .list, .empty_list, .tuple, .match_, .if_, .call, .record, .empty_record, .block, .tag, .nominal, .zero_argument_tag, .closure, .lambda, .binop, .unary_minus, .field_access, .dispatch_call, .interpolation, .structural_eq, .structural_hash, .method_eq, .type_dispatch_call, .tuple_access, .crash, .dbg, .expect_err, .expect, .ellipsis, .anno_only, .break_, .return_, .for_, .hosted_lambda, .run_low_level => return null,
        },
        .pattern => if (bodies.literalPatternGuard(@fromBackingInt(raw_node)) == null) return null else .{ .pattern = @fromBackingInt(raw_node) },
        .statement, .unreached => return null,
    };
    const conversion = bodies.literalConversion(raw_node);
    const plan_id = conversion.plan orelse checkedArtifactInvariant("a custom literal had no conversion plan", .{});
    const plan = try dispatch.plan(plan_id);
    const evidence = switch (plan.resolution) {
        .direct_closed => |direct| direct.evidence,
        .direct_parametric, .evidence_dependent, .checked_error, .@"unreachable" => return null,
        .direct_pending, .structural => checkedArtifactInvariant("a literal conversion had no finalized callable dispatch", .{}),
    };
    return .{
        .literal = literal_node,
        .kind = if (literal.dispatchKind() == .numeral) .numeral else .quote,
        .plan = plan_id,
        .ty = conversion.ty,
        .evidence = evidence,
    };
}

/// A literal root of a module with its entry wrapper: the wrapper's function
/// type and scheme, created by the slot that holds the root, and the relation
/// of the wrapper's body to its specialization.
pub const LiteralRootRecord = struct {
    root: CompileTimeRoot,
    checked_fn_root: CheckedTypeId,
    checked_fn_scheme: CheckedTypeSchemeId,
    /// The conversion plan a literal conversion root's wrapper runs; null for
    /// a literal argument root.
    plan: ?static_dispatch.StaticDispatchPlanId,
    relation: [1]SpecializationInterfaceRelation,
};

/// The literal conversion roots of one top-level unit's literals, by node
/// (`ModuleAnalyses.unitLiteralConversions`).
pub const UnitLiteralConversions = struct {
    nodes: []const u32,
    records: []const LiteralRootRecord,

    pub fn record(self: *const UnitLiteralConversions, raw_node: u32) ?*const LiteralRootRecord {
        const index = std.sort.binarySearch(u32, self.nodes, raw_node, struct {
            fn order(key: u32, item: u32) std.math.Order {
                return std.math.order(key, item);
            }
        }.order) orelse return null;
        return &self.records[index];
    }

    pub fn destroy(self: *UnitLiteralConversions, allocator: Allocator) void {
        allocator.free(self.nodes);
        allocator.free(self.records);
        allocator.destroy(self);
    }
};

/// The import views a module's dispatch resolution reads.
fn dispatchImportViews(dispatch: CheckedDispatch) CheckedImportViews {
    return .{ .current_owner = dispatch.source.key.digest(), .direct = &.{}, .available = dispatch.source.analyses.dispatch_imports };
}

/// Demand, holding no claim, the interface capabilities of the module `dispatch`
/// reads and of `modules`, whose types a creation in the module's store reads.
fn demandLiteralCapabilities(dispatch: CheckedDispatch, modules: []const ModuleId) Allocator.Error!void {
    const import_views = dispatchImportViews(dispatch);
    const store = dispatch.source.types.store;
    if (store.capability_source != null) _ = try store.view().interfaceCapabilities(import_views.resolver());
    for (modules) |module| {
        if (module.eql(dispatch.source.key.digest())) continue;
        const view = import_views.viewForKey(module) orelse checkedArtifactInvariant("a literal analysis read a module its dispatch resolution does not read", .{});
        _ = try view.checked_types.interfaceCapabilities(import_views.resolver());
    }
}

/// The relation of a literal root's entry wrapper to its specialization: the
/// wrapper's body delivers the root's type.
fn literalRootWrapperRelation(checked_fn_root: CheckedTypeId, root_ty: CheckedTypeId) [1]SpecializationInterfaceRelation {
    return .{.{
        .scope = .root,
        .data = .{ .procedure = .{
            .fn_ty = checked_fn_root,
            .body_ret_ty = root_ty,
            .owns_scope = true,
        } },
    }};
}

/// The literal conversion roots of unit `unit`'s literals: each root, its
/// request eligibility, and its entry wrapper's function type and scheme,
/// created here under the store's creation lock after every slot it reads.
pub fn computeUnitLiteralConversions(allocator: Allocator, dispatch: CheckedDispatch, unit: body_analyses.UnitId) Allocator.Error!*UnitLiteralConversions {
    const source = dispatch.source;
    const bodies = dispatchSourceBodies(source);
    var candidates: std.ArrayList(LiteralConversionCandidate) = .empty;
    defer candidates.deinit(allocator);
    for (bodies.index().unitNodeSlice(unit)) |raw_node| {
        if (try literalConversionCandidate(bodies, dispatch, raw_node)) |candidate| try candidates.append(allocator, candidate);
    }
    std.mem.sort(LiteralConversionCandidate, candidates.items, {}, struct {
        fn lessThan(_: void, a: LiteralConversionCandidate, b: LiteralConversionCandidate) bool {
            return a.literal.node() < b.literal.node();
        }
    }.lessThan);
    const nodes = try allocator.alloc(u32, candidates.items.len);
    errdefer allocator.free(nodes);
    const records = try allocator.alloc(LiteralRootRecord, candidates.items.len);
    errdefer allocator.free(records);
    const import_views = dispatchImportViews(dispatch);
    const store = source.types.store;
    try demandLiteralCapabilities(dispatch, &.{});
    for (candidates.items, nodes, records) |candidate, *node, *record| {
        node.* = candidate.literal.node();
        const eligible = try checkedTypeIsContextFreeCompileTimeRoot(allocator, source.key.digest(), store.view(), import_views.resolver(), false, candidate.ty);
        record.* = .{
            .root = .{
                .id = literalConversionRootId(candidate.literal),
                .module_idx = source.module_idx,
                .kind = switch (candidate.kind) {
                    .numeral => .numeral_conversion,
                    .quote => .quote_conversion,
                },
                .source = .{ .literal = candidate.literal },
                .pattern = null,
                .expr = null,
                .checked_type = candidate.ty,
                .request_eligibility = if (eligible) .eligible else .ineligible,
                .payload = .pending,
            },
            .checked_fn_root = undefined, // Created below, under the creation lock.
            .checked_fn_scheme = undefined, // Created below, under the creation lock.
            .plan = candidate.plan,
            .relation = undefined, // Set below from the created function type.
        };
    }
    {
        store.beginCreation(source.analyses.io);
        defer store.endCreation(source.analyses.io);
        for (records) |*record| {
            record.checked_fn_root = try store.appendSyntheticFunctionRoot(allocator, .pure, &.{}, record.root.checked_type);
            record.checked_fn_scheme = try store.ensureSchemeForRoot(allocator, record.checked_fn_root);
        }
    }
    for (records) |*record| record.relation = literalRootWrapperRelation(record.checked_fn_root, record.root.checked_type);
    const result = try allocator.create(UnitLiteralConversions);
    result.* = .{ .nodes = nodes, .records = records };
    return result;
}

/// A scheme of a module: a template's own (`scope == null`) or a generalized
/// local scope's. A scope inside a defaulted field expression has no
/// template.
pub const LiteralScopeKey = struct { template: ?u32, scope: ?u32 };

fn literalScopeKeyOf(template: ?u32, scope: DispatchScope) LiteralScopeKey {
    return switch (scope) {
        .root => .{ .template = template, .scope = null },
        .generalized => |id| .{ .template = template, .scope = @backingInt(id) },
    };
}

/// The scheme an edge instantiates: a procedure template's, or a generalized
/// local function's.
pub const LiteralCallee = union(enum) {
    template: canonical.ProcedureTemplateRef,
    scope: DispatchScopeId,
};

/// Where an edge's substitution comes from.
pub const LiteralEdgeSubst = union(enum) {
    /// A dispatch edge's own instantiation of its target's scheme.
    evidence: static_dispatch.EvidenceSpan,
    /// A use's instantiation of the scheme it reads.
    site: CIR.Expr.Idx,
    /// A dispatch edge to a method bound to an exact procedure alias: the
    /// instantiation of the alias's scheme, composed through the alias
    /// chain's forwarded lookups.
    alias_chain: static_dispatch.EvidenceNodeId,
};

/// One instantiation edge of the module's bodies (`LiteralGraph`).
pub const LiteralGraphEdge = struct {
    key: LiteralEdge,
    /// The graph node whose body holds the edge first, in node order, which
    /// computes the edge's literal arguments.
    holder: u32,
    callee: LiteralCallee,
    /// The scope the edge is in; null inside a defaulted field expression.
    scope: ?LiteralScopeKey,
    owner_expr: CIR.Expr.Idx,
    subst: LiteralEdgeSubst,
};

/// A literal of a scheme's own body whose conversion plan is open: a literal
/// requirement of the innermost scheme around it.
pub const LiteralOwnSite = struct {
    scope: LiteralScopeKey,
    site: LiteralSite,
    ty: CheckedTypeId,
};

/// An edge of a module's literal graph, by its key.
pub const LiteralEdgeIndex = struct {
    key: u64,
    edge: u32,

    fn lessThan(_: void, a: LiteralEdgeIndex, b: LiteralEdgeIndex) bool {
        return a.key < b.key;
    }

    fn order(key: u64, item: LiteralEdgeIndex) std.math.Order {
        return std.math.order(key, item.key);
    }
};

/// The strongly connected components of a call graph over dense nodes,
/// numbered as they complete (callees first).
pub const CallGraphComponents = struct {
    component_of: []const u32,
    member_index: []const u32,
    /// Component `c`'s nodes, ascending: `members[member_starts[c]..member_starts[c + 1]]`.
    member_starts: []const u32,
    members: []const u32,
    /// Component `c`'s callee components other than itself, each once.
    callee_starts: []const u32,
    callees: []const u32,

    pub fn count(self: *const CallGraphComponents) usize {
        return self.member_starts.len - 1;
    }

    pub fn componentMembers(self: *const CallGraphComponents, component: u32) []const u32 {
        return self.members[self.member_starts[component]..self.member_starts[component + 1]];
    }

    pub fn componentCallees(self: *const CallGraphComponents, component: u32) []const u32 {
        return self.callees[self.callee_starts[component]..self.callee_starts[component + 1]];
    }

    pub fn deinit(self: *CallGraphComponents, allocator: Allocator) void {
        allocator.free(self.component_of);
        allocator.free(self.member_index);
        allocator.free(self.member_starts);
        allocator.free(self.members);
        allocator.free(self.callee_starts);
        allocator.free(self.callees);
    }
};

/// The strongly connected components of the graph whose node `n`'s callees
/// are `successors[successor_starts[n]..successor_starts[n + 1]]` (Tarjan's
/// algorithm, iteratively), numbered as they complete, so every component's
/// callee components precede it.
pub fn callGraphComponents(allocator: Allocator, successor_starts: []const u32, successors: []const u32) Allocator.Error!CallGraphComponents {
    const count = successor_starts.len - 1;
    const unvisited = std.math.maxInt(u32);
    const order = try allocator.alloc(u32, count);
    defer allocator.free(order);
    @memset(order, unvisited);
    const low = try allocator.alloc(u32, count);
    defer allocator.free(low);
    var on_stack = try std.DynamicBitSetUnmanaged.initEmpty(allocator, count);
    defer on_stack.deinit(allocator);
    var stack: std.ArrayList(u32) = .empty;
    defer stack.deinit(allocator);
    const Frame = struct { node: u32, next: u32 };
    var frames: std.ArrayList(Frame) = .empty;
    defer frames.deinit(allocator);

    const component_of = try allocator.alloc(u32, count);
    errdefer allocator.free(component_of);
    var members: std.ArrayList(u32) = .empty;
    defer members.deinit(allocator);
    var member_starts: std.ArrayList(u32) = .empty;
    defer member_starts.deinit(allocator);
    try member_starts.append(allocator, 0);
    var next_order: u32 = 0;

    for (0..count) |start| {
        if (order[start] != unvisited) continue;
        order[start] = next_order;
        low[start] = next_order;
        next_order += 1;
        try stack.append(allocator, @intCast(start));
        on_stack.set(start);
        try frames.append(allocator, .{ .node = @intCast(start), .next = successor_starts[start] });
        while (frames.items.len != 0) {
            const frame = &frames.items[frames.items.len - 1];
            const node = frame.node;
            if (frame.next < successor_starts[node + 1]) {
                const callee = successors[frame.next];
                frame.next += 1;
                if (order[callee] == unvisited) {
                    order[callee] = next_order;
                    low[callee] = next_order;
                    next_order += 1;
                    try stack.append(allocator, callee);
                    on_stack.set(callee);
                    try frames.append(allocator, .{ .node = callee, .next = successor_starts[callee] });
                } else if (on_stack.isSet(callee)) {
                    low[node] = @min(low[node], order[callee]);
                }
                continue;
            }
            _ = frames.pop();
            if (frames.items.len != 0) {
                const parent = frames.items[frames.items.len - 1].node;
                low[parent] = @min(low[parent], low[node]);
            }
            if (low[node] != order[node]) continue;
            const component: u32 = @intCast(member_starts.items.len - 1);
            const first = members.items.len;
            while (stack.pop()) |member| {
                on_stack.unset(member);
                component_of[member] = component;
                try members.append(allocator, member);
                if (member == node) break;
            }
            std.mem.sort(u32, members.items[first..], {}, std.sort.asc(u32));
            try member_starts.append(allocator, @intCast(members.items.len));
        }
    }

    const component_count = member_starts.items.len - 1;
    const member_index = try allocator.alloc(u32, count);
    errdefer allocator.free(member_index);
    for (0..component_count) |component| {
        for (members.items[member_starts.items[component]..member_starts.items[component + 1]], 0..) |member, index| member_index[member] = @intCast(index);
    }
    var callees: std.ArrayList(u32) = .empty;
    defer callees.deinit(allocator);
    var callee_starts: std.ArrayList(u32) = .empty;
    defer callee_starts.deinit(allocator);
    try callee_starts.append(allocator, 0);
    for (0..component_count) |component| {
        const first = callees.items.len;
        for (members.items[member_starts.items[component]..member_starts.items[component + 1]]) |member| {
            for (successors[successor_starts[member]..successor_starts[member + 1]]) |callee| {
                if (component_of[callee] != component) try callees.append(allocator, component_of[callee]);
            }
        }
        const added = callees.items[first..];
        std.mem.sort(u32, added, {}, std.sort.asc(u32));
        var kept: usize = 0;
        for (added, 0..) |callee, index| {
            if (index != 0 and added[index - 1] == callee) continue;
            added[kept] = callee;
            kept += 1;
        }
        callees.shrinkRetainingCapacity(first + kept);
        try callee_starts.append(allocator, @intCast(callees.items.len));
    }

    const owned_members = try members.toOwnedSlice(allocator);
    errdefer allocator.free(owned_members);
    const owned_member_starts = try member_starts.toOwnedSlice(allocator);
    errdefer allocator.free(owned_member_starts);
    const owned_callees = try callees.toOwnedSlice(allocator);
    errdefer allocator.free(owned_callees);
    return .{
        .component_of = component_of,
        .member_index = member_index,
        .member_starts = owned_member_starts,
        .members = owned_members,
        .callee_starts = try callee_starts.toOwnedSlice(allocator),
        .callees = owned_callees,
    };
}

/// The slot holding one literal component's results.
pub const LiteralComponentSlot = collections.OnceSlot(*LiteralComponent, .module_literal_component);
/// The slot holding the literal argument roots one template's edges read.
pub const LiteralDemandSlot = collections.OnceSlot(*LiteralArgumentDemand, .module_literal_demand);

/// A module's literal call graph (`ModuleAnalyses.literalGraph`): every
/// instantiation edge its bodies hold, each scheme's own open literals, and
/// the strongly connected components the edges between the templates whose
/// bodies hold them form, numbered callees first. Nodes are the module's
/// templates in template order, then the defaulted-field expressions as one
/// node. Each component's literal requirements, edge arguments and literal
/// argument roots are a slot of their own (`LiteralComponent`).
pub const LiteralGraph = struct {
    template_count: u32,
    /// The template whose body owns each generalized local scope.
    scope_owners: []const ?u32,
    /// Every edge, in the order the nodes' bodies first hold them, so node
    /// `n`'s edges are `edges[edge_starts[n]..edge_starts[n + 1]]`.
    edges: []const LiteralGraphEdge,
    edge_starts: []const u32,
    node_edges: []const LiteralEdgeIndex,
    use_edges: []const LiteralEdgeIndex,
    /// The edges template `t`'s body holds, its own first:
    /// `held[held_starts[t]..held_starts[t + 1]]`.
    held_starts: []const u32,
    held: []const u32,
    /// Node `n`'s own open literals: `own_sites[own_starts[n]..own_starts[n + 1]]`.
    own_starts: []const u32,
    own_sites: []const LiteralOwnSite,
    components: CallGraphComponents,
    component_slots: []LiteralComponentSlot,
    demand_slots: []LiteralDemandSlot,

    pub fn defaultsNode(self: *const LiteralGraph) u32 {
        return self.template_count;
    }

    /// The graph node a scope key's scheme belongs to.
    pub fn nodeOfScope(self: *const LiteralGraph, key: LiteralScopeKey) u32 {
        return key.template orelse self.defaultsNode();
    }

    /// The graph node an edge's callee scheme belongs to, or null for a
    /// scheme of another module.
    pub fn calleeNode(self: *const LiteralGraph, owner: canonical.ArtifactRef, callee: LiteralCallee) ?u32 {
        return switch (callee) {
            .template => |template| if (template.artifact.eql(owner)) template.template.index() else null,
            .scope => |scope| self.scope_owners[@backingInt(scope)] orelse self.defaultsNode(),
        };
    }

    pub fn nodeEdges(self: *const LiteralGraph, node: u32) []const LiteralGraphEdge {
        return self.edges[self.edge_starts[node]..self.edge_starts[node + 1]];
    }

    /// The index of edge `edge`, or null when no body holds it.
    pub fn edgeIndex(self: *const LiteralGraph, edge: LiteralEdge) ?u32 {
        const entries: []const LiteralEdgeIndex, const key: u64 = switch (edge) {
            .node => |id| .{ self.node_edges, @bitCast(id) },
            .use => |expr| .{ self.use_edges, @backingInt(expr) },
            .literal => return null,
        };
        const found = std.sort.binarySearch(LiteralEdgeIndex, entries, key, LiteralEdgeIndex.order) orelse return null;
        return entries[found].edge;
    }

    pub fn destroy(self: *LiteralGraph, allocator: Allocator) void {
        for (self.component_slots) |*slot| if (slot.peek()) |result| result.destroy(allocator);
        for (self.demand_slots) |*slot| if (slot.peek()) |result| result.destroy(allocator);
        allocator.free(self.component_slots);
        allocator.free(self.demand_slots);
        allocator.free(self.scope_owners);
        allocator.free(self.edges);
        allocator.free(self.edge_starts);
        allocator.free(self.node_edges);
        allocator.free(self.use_edges);
        allocator.free(self.held_starts);
        allocator.free(self.held);
        allocator.free(self.own_starts);
        allocator.free(self.own_sites);
        self.components.deinit(allocator);
        allocator.destroy(self);
    }
};

/// The literal kind of a plan with a generated literal operand.
fn literalKindOfPlan(table: *const static_dispatch.StaticDispatchPlanTable, plan: static_dispatch.StaticDispatchCallPlan) ?LiteralArgumentKind {
    for (plan.argsSlice(table)) |operand| switch (operand) {
        .generated_numeral => return .numeral,
        .generated_quote => return .quote,
        .generated_interpolation_segments => return .interpolation,
        .checked_expr, .literal_pattern_value, .literal_pattern_conversion => {},
    };
    return null;
}

/// Walks the evidence a body's dispatch reaches and reports every edge it
/// holds: each procedure target the evidence names, through nested
/// evidence, alias scopes and generated codecs.
const LiteralEdgeWalker = struct {
    allocator: Allocator,
    dispatch: CheckedDispatch,
    stack: std.ArrayListUnmanaged(static_dispatch.EvidenceNodeId) = .empty,
    visited_derivations: collections.DenseMapUnmanaged(static_dispatch.GeneratedCodecDerivationId, void) = .empty,

    const Found = struct {
        id: static_dispatch.EvidenceNodeId,
        template: canonical.ProcedureTemplateRef,
        alias: bool,
    };

    fn deinit(self: *LiteralEdgeWalker) void {
        self.stack.deinit(self.allocator);
        self.visited_derivations.deinit(self.allocator);
    }

    /// Every edge of `node_id` and of the nodes its evidence reaches, and of
    /// the nodes already queued.
    fn nodes(self: *LiteralEdgeWalker, node_id: static_dispatch.EvidenceNodeId, out: *std.ArrayListUnmanaged(Found)) Allocator.Error!void {
        try self.stack.append(self.allocator, node_id);
        try self.drain(out);
    }

    fn drain(self: *LiteralEdgeWalker, out: *std.ArrayListUnmanaged(Found)) Allocator.Error!void {
        while (self.stack.pop()) |id| {
            const node = try self.dispatch.evidenceNode(id);
            switch (node.target.kind) {
                .procedure => |procedure| try out.append(self.allocator, .{ .id = id, .template = procedure.template, .alias = node.instantiation == .alias }),
                // A method declared in a function body is called through
                // its function value, whose scheme its construction or use
                // instantiates.
                .local_proc, .structural => {},
            }
            switch (node.nested) {
                .resolved => try self.entries(try self.dispatch.nestedEvidence(node)),
                .through_alias => try self.entries(try self.dispatch.aliasScopeEvidence(node)),
                .from_callable => {},
            }
        }
    }

    fn entries(self: *LiteralEdgeWalker, evidence: []const static_dispatch.CheckedEvidence) Allocator.Error!void {
        for (evidence) |entry| {
            switch (entry.resolution) {
                .direct => |nested| try self.stack.append(self.allocator, nested),
                .structural => |structural| if (structural.generated_codec_derivation) |id| try self.derivationNodes(id),
                .constraint, .from_callable, .from_scheme, .checked_error, .unreachable_value => {},
            }
            for (try self.dispatch.evidenceEntries(entry.callable_contracts)) |contract| switch (contract.resolution) {
                .direct => |nested| try self.stack.append(self.allocator, nested),
                .structural => |structural| if (structural.generated_codec_derivation) |id| try self.derivationNodes(id),
                .constraint, .from_callable, .from_scheme, .checked_error, .unreachable_value => {},
            };
        }
    }

    /// Queue the method calls a generated codec's body makes, through the
    /// codecs it nests.
    fn derivationNodes(self: *LiteralEdgeWalker, first: static_dispatch.GeneratedCodecDerivationId) Allocator.Error!void {
        var pending: std.ArrayListUnmanaged(static_dispatch.GeneratedCodecDerivationId) = .empty;
        defer pending.deinit(self.allocator);
        try pending.append(self.allocator, first);
        while (pending.pop()) |id| {
            if ((try self.visited_derivations.getOrPut(self.allocator, id)).found_existing) continue;
            const codecs = try self.dispatch.generatedCodecs();
            const derivation = codecs.generated_codec_derivations[@backingInt(id)];
            for (derivation.callsSlice(&codecs)) |call| switch (call.resolution) {
                .callable => |node| try self.stack.append(self.allocator, node),
                .structural => |nested| try pending.append(self.allocator, nested),
                .pending, .checked_error => {},
            };
        }
    }

    /// Every edge the evidence recorded at use site `expr` reaches.
    fn site(self: *LiteralEdgeWalker, expr: CIR.Expr.Idx, out: *std.ArrayListUnmanaged(Found)) Allocator.Error!void {
        const evidence = (try self.dispatch.siteEvidence(expr)) orelse return;
        try self.entries(evidence);
        try self.drain(out);
    }

    /// Every edge a plan's resolution reaches.
    fn plan(self: *LiteralEdgeWalker, plan_value: static_dispatch.StaticDispatchCallPlan, out: *std.ArrayListUnmanaged(Found)) Allocator.Error!void {
        switch (plan_value.resolution) {
            .direct_closed, .direct_parametric => |direct| try self.nodes(direct.evidence, out),
            // A generated codec's calls are edges of the scope that reaches
            // the codec.
            .structural => if (plan_value.generated_codec_derivation) |id| {
                try self.derivationNodes(id);
                try self.drain(out);
            },
            .evidence_dependent, .checked_error, .@"unreachable", .direct_pending => {},
        }
    }
};

/// The template a procedure value reference instantiates the scheme of: the
/// procedure's, or an exact procedure alias's entry wrapper, whose scheme is
/// the alias's. A use of a computed callable instantiates nothing.
fn literalTemplateOfValueRef(dispatch: CheckedDispatch, ref: ResolvedValueRef) ?canonical.ProcedureTemplateRef {
    const source = dispatch.source;
    const owner = source.key.digest();
    const import_views = dispatchImportViews(dispatch);
    const use: ProcedureUseTemplate = switch (ref) {
        .top_level_proc, .imported_proc, .promoted_top_level_proc => |use| use,
        .platform_required_proc => |required| required.procedure,
        .hosted_proc, .top_level_const, .imported_const, .selected_hoisted_const, .platform_required_const, .local_param, .local_value, .local_mutable_version, .pattern_binder, .local_proc, .platform_required_declaration, .platform_required_checked_error => return null,
    };
    var alias_view: ?ImportedModuleView = null;
    const body: ProcedureBindingBody = switch (use.binding) {
        .top_level => |top_level| blk: {
            if (!top_level.artifact.eql(owner)) return null;
            break :blk source.top_level_procedure_bindings.get(top_level.binding).body;
        },
        .imported => |imported| blk: {
            const view = import_views.viewForKey(imported.artifact) orelse return null;
            alias_view = view;
            const binding = importedProcedureBindingForDef(view, imported.def) orelse return null;
            break :blk binding.body;
        },
        .hosted, .platform_required => return null,
    };
    return switch (body) {
        .direct_template => |direct| switch (direct.template) {
            .checked => |template| template,
            .lifted, .synthetic => null,
        },
        .callable_eval_template => |template_id| blk: {
            const eval_templates: CallableEvalTemplateTableView = if (alias_view) |view| view.callable_eval_templates else source.callable_eval_templates;
            const template = eval_templates.templates[@backingInt(template_id)];
            if (template.forwarded_lookup == null) break :blk null;
            const wrapper_table: *const EntryWrapperTable = if (alias_view) |view| view.entry_wrappers else source.entry_wrappers;
            const wrapper = wrapper_table.lookupByRoot(template.root) orelse
                checkedArtifactInvariant("a callable-eval template's root has no entry wrapper", .{});
            break :blk wrapper.template;
        },
        .checked_error => null,
    };
}

/// The module's literal call graph: every template's and the defaulted
/// fields' edges and own open literals, and the components of the edges
/// between templates.
pub fn computeLiteralGraph(allocator: Allocator, dispatch: CheckedDispatch) Allocator.Error!*LiteralGraph {
    const source = dispatch.source;
    const owner = source.key.digest();
    const templates = source.templates;
    const plans = source.plans;
    const refs = source.refs;
    const sites = &templates.dispatch_sites;
    const scopes = templates.dispatch_scopes;
    const template_count: u32 = @intCast(templates.templates.items.len);
    const node_count = template_count + 1;
    const bodies = dispatchSourceBodies(source);

    const scope_owners = try allocator.alloc(?u32, scopes.len);
    errdefer allocator.free(scope_owners);
    @memset(scope_owners, null);
    for (sites.scope_site_spans[0..sites.walkedTemplateCount()], 0..) |span, template_index| {
        for (sites.scope_sites[span.start..][0..span.len]) |scope_site| {
            var current: ?DispatchScopeId = scope_site.scope;
            while (current) |id| {
                scope_owners[@backingInt(id)] = @intCast(template_index);
                current = scopes[@backingInt(id)].parent;
            }
        }
    }

    // Own sites: each open literal conversion plan is a literal requirement
    // of the innermost scheme around it.
    var own_sites: std.ArrayList(LiteralOwnSite) = .empty;
    defer own_sites.deinit(allocator);
    const own_starts = try allocator.alloc(u32, node_count + 1);
    errdefer allocator.free(own_starts);
    for (templates.templates.items, 0..) |template, template_index| {
        own_starts[template_index] = @intCast(own_sites.items.len);
        const start = template.static_dispatch_plans.start;
        for (templates.dispatch_plan_refs[start..][0..template.static_dispatch_plans.len], 0..) |plan_id, i| {
            const plan = try dispatch.plan(plan_id);
            const kind = literalKindOfPlan(plans, plan) orelse continue;
            switch (plan.resolution) {
                .evidence_dependent, .direct_parametric => {},
                .direct_closed, .checked_error, .@"unreachable", .structural => continue,
                .direct_pending => checkedArtifactInvariant("a literal conversion plan was left pending at literal argument analysis", .{}),
            }
            // The literal requirement's type is the converted value's: the
            // literal's own for a numeral or a quote, the assembler's for an
            // interpolation.
            const ty = switch (kind) {
                .interpolation => blk: {
                    const expr: CIR.Expr.Idx = @fromBackingInt(@intCast(plan.node));
                    if (bodies.exprData(expr) != .interpolation) checkedArtifactInvariant("a literal conversion plan's expression is not a literal", .{});
                    break :blk bodies.interpolationAssemblerType(expr);
                },
                .numeral, .quote => bodies.literalConversion(plan.node).ty,
            };
            try own_sites.append(allocator, .{
                .scope = literalScopeKeyOf(@intCast(template_index), templates.dispatch_ref_scopes[start + i]),
                .site = .{ .module = owner, .node = plan.node, .kind = kind },
                .ty = ty,
            });
        }
    }
    own_starts[template_count] = @intCast(own_sites.items.len);
    {
        const span = sites.defaultRefs(TemplateDispatchSites.default_plan_refs);
        for (templates.dispatch_plan_refs[span.start..][0..span.len]) |plan_id| {
            const plan = try dispatch.plan(plan_id);
            if (literalKindOfPlan(plans, plan) == null) continue;
            switch (plan.resolution) {
                .evidence_dependent, .direct_parametric => checkedArtifactInvariant("a defaulted field expression's literal has no scheme to carry its obligation", .{}),
                .direct_closed, .checked_error, .@"unreachable", .structural => {},
                .direct_pending => checkedArtifactInvariant("a literal conversion plan was left pending at literal argument analysis", .{}),
            }
        }
    }
    own_starts[node_count] = @intCast(own_sites.items.len);

    // The edges: every instantiation of a scheme inside this module, held
    // first by the node whose body reaches it first.
    var edges: std.ArrayList(LiteralGraphEdge) = .empty;
    defer edges.deinit(allocator);
    var edge_keys = std.AutoHashMapUnmanaged(LiteralEdge, u32).empty;
    defer edge_keys.deinit(allocator);
    const edge_starts = try allocator.alloc(u32, node_count + 1);
    errdefer allocator.free(edge_starts);
    const held_starts = try allocator.alloc(u32, template_count + 1);
    errdefer allocator.free(held_starts);
    var held: std.ArrayList(u32) = .empty;
    defer held.deinit(allocator);
    var walker: LiteralEdgeWalker = .{ .allocator = allocator, .dispatch = dispatch };
    defer walker.deinit();
    var found: std.ArrayListUnmanaged(LiteralEdgeWalker.Found) = .empty;
    defer found.deinit(allocator);

    const Builder = struct {
        allocator: Allocator,
        dispatch: CheckedDispatch,
        owner: canonical.ArtifactRef,
        edges: *std.ArrayList(LiteralGraphEdge),
        keys: *std.AutoHashMapUnmanaged(LiteralEdge, u32),
        held: *std.ArrayList(u32),
        held_start: usize = 0,
        node: u32 = 0,
        holds: bool = false,

        fn add(self: *@This(), edge: LiteralGraphEdge) Allocator.Error!void {
            const seen = try self.keys.getOrPut(self.allocator, edge.key);
            if (!seen.found_existing) {
                seen.value_ptr.* = @intCast(self.edges.items.len);
                var placed = edge;
                placed.holder = self.node;
                try self.edges.append(self.allocator, placed);
            }
            if (!self.holds) return;
            for (self.held.items[self.held_start..]) |existing| if (existing == seen.value_ptr.*) return;
            try self.held.append(self.allocator, seen.value_ptr.*);
        }

        fn evidence(self: *@This(), items: []const LiteralEdgeWalker.Found, scope: ?LiteralScopeKey, owner_expr: CIR.Expr.Idx) Allocator.Error!void {
            for (items) |item| {
                // An alias chain that leaves this module is instantiated
                // where the chain's procedure lives.
                if (item.alias and !item.template.artifact.eql(self.owner)) continue;
                try self.add(.{
                    .key = .{ .node = item.id },
                    .holder = undefined, // Set by `add` to the node holding the edge first.
                    .callee = .{ .template = item.template },
                    .scope = scope,
                    .owner_expr = owner_expr,
                    .subst = if (item.alias) .{ .alias_chain = item.id } else .{ .evidence = (try self.dispatchNode(item.id)).subst },
                });
            }
        }

        fn dispatchNode(self: *@This(), id: static_dispatch.EvidenceNodeId) Allocator.Error!static_dispatch.EvidenceNode {
            return self.dispatch.evidenceNode(id);
        }

        fn valueRef(self: *@This(), walker_: *LiteralEdgeWalker, found_: *std.ArrayListUnmanaged(LiteralEdgeWalker.Found), record: ResolvedValueRefRecord, scope: ?LiteralScopeKey) Allocator.Error!void {
            found_.clearRetainingCapacity();
            try walker_.site(record.expr, found_);
            try self.evidence(found_.items, scope, record.expr);
            const callee: LiteralCallee = switch (record.ref) {
                .local_proc => |local| .{ .scope = local.dispatch_scope orelse return },
                .top_level_proc, .imported_proc, .promoted_top_level_proc, .platform_required_proc, .hosted_proc, .top_level_const, .imported_const, .selected_hoisted_const, .platform_required_const, .local_param, .local_value, .local_mutable_version, .pattern_binder, .platform_required_declaration, .platform_required_checked_error => .{ .template = literalTemplateOfValueRef(self.dispatch, record.ref) orelse return },
            };
            try self.add(.{
                .key = .{ .use = record.expr },
                .holder = undefined, // Set by `add` to the node holding the edge first.
                .callee = callee,
                .scope = scope,
                .owner_expr = record.expr,
                .subst = .{ .site = record.expr },
            });
        }

        fn scopeSite(self: *@This(), walker_: *LiteralEdgeWalker, found_: *std.ArrayListUnmanaged(LiteralEdgeWalker.Found), scope_site: CollectedScopeConstructionSite, scope: ?LiteralScopeKey) Allocator.Error!void {
            found_.clearRetainingCapacity();
            try walker_.site(scope_site.checked_expr, found_);
            try self.evidence(found_.items, scope, scope_site.checked_expr);
            try self.add(.{
                .key = .{ .use = scope_site.checked_expr },
                .holder = undefined, // Set by `add` to the node holding the edge first.
                .callee = .{ .scope = scope_site.scope },
                .scope = scope,
                .owner_expr = scope_site.checked_expr,
                .subst = .{ .site = scope_site.checked_expr },
            });
        }
    };
    var builder: Builder = .{ .allocator = allocator, .owner = owner, .edges = &edges, .keys = &edge_keys, .held = &held, .dispatch = dispatch };

    for (templates.templates.items, 0..) |template, template_index| {
        const t: u32 = @intCast(template_index);
        edge_starts[template_index] = @intCast(edges.items.len);
        held_starts[template_index] = @intCast(held.items.len);
        builder.node = t;
        builder.holds = true;
        builder.held_start = held.items.len;
        const plan_start = template.static_dispatch_plans.start;
        for (templates.dispatch_plan_refs[plan_start..][0..template.static_dispatch_plans.len], 0..) |plan_id, i| {
            const plan = try dispatch.plan(plan_id);
            found.clearRetainingCapacity();
            try walker.plan(plan, &found);
            try builder.evidence(found.items, literalScopeKeyOf(t, templates.dispatch_ref_scopes[plan_start + i]), @fromBackingInt(@intCast(plan.node)));
        }
        const ref_start = template.resolved_value_refs.start;
        for (refs.template_refs[ref_start..][0..template.resolved_value_refs.len], 0..) |ref_id, i| {
            try builder.valueRef(&walker, &found, refs.records[@backingInt(ref_id)], literalScopeKeyOf(t, sites.value_ref_scopes[ref_start + i]));
        }
        const site_span = sites.scopeSiteSpan(template_index);
        for (sites.scope_sites[site_span.start..][0..site_span.len]) |scope_site| {
            const parent = scopes[@backingInt(scope_site.scope)].parent;
            try builder.scopeSite(&walker, &found, scope_site, .{ .template = t, .scope = if (parent) |p| @backingInt(p) else null });
        }
    }
    edge_starts[template_count] = @intCast(edges.items.len);
    held_starts[template_count] = @intCast(held.items.len);
    {
        builder.node = template_count;
        builder.holds = false;
        const span = sites.defaultRefs(TemplateDispatchSites.default_plan_refs);
        for (templates.dispatch_plan_refs[span.start..][0..span.len]) |plan_id| {
            const plan = try dispatch.plan(plan_id);
            switch (plan.resolution) {
                .direct_closed, .direct_parametric => {
                    found.clearRetainingCapacity();
                    try walker.plan(plan, &found);
                    try builder.evidence(found.items, null, @fromBackingInt(@intCast(plan.node)));
                },
                .evidence_dependent, .checked_error, .@"unreachable", .structural, .direct_pending => {},
            }
        }
        const value_refs = sites.defaultRefs(TemplateDispatchSites.default_value_refs);
        for (refs.template_refs[value_refs.start..][0..value_refs.len]) |ref_id| {
            try builder.valueRef(&walker, &found, refs.records[@backingInt(ref_id)], null);
        }
        const default_sites = sites.scopeSiteSpan(sites.defaultsIndex());
        for (sites.scope_sites[default_sites.start..][0..default_sites.len]) |scope_site| {
            const parent = scopes[@backingInt(scope_site.scope)].parent;
            try builder.scopeSite(&walker, &found, scope_site, if (parent) |p| .{ .template = null, .scope = @backingInt(p) } else null);
        }
    }
    edge_starts[node_count] = @intCast(edges.items.len);

    // The call graph: each node to the nodes of the local schemes its
    // edges instantiate.
    const successor_starts = try allocator.alloc(u32, node_count + 1);
    defer allocator.free(successor_starts);
    var successors: std.ArrayList(u32) = .empty;
    defer successors.deinit(allocator);
    var graph: LiteralGraph = .{
        .template_count = template_count,
        .scope_owners = scope_owners,
        .edges = edges.items,
        .edge_starts = edge_starts,
        .node_edges = &.{},
        .use_edges = &.{},
        .held_starts = held_starts,
        .held = held.items,
        .own_starts = own_starts,
        .own_sites = own_sites.items,
        .components = undefined, // Computed below from the edges.
        .component_slots = &.{},
        .demand_slots = &.{},
    };
    for (0..node_count) |node| {
        successor_starts[node] = @intCast(successors.items.len);
        for (graph.nodeEdges(@intCast(node))) |edge| {
            if (graph.calleeNode(owner, edge.callee)) |callee| try successors.append(allocator, callee);
        }
    }
    successor_starts[node_count] = @intCast(successors.items.len);
    var components = try callGraphComponents(allocator, successor_starts, successors.items);
    errdefer components.deinit(allocator);

    var node_edges: std.ArrayList(LiteralEdgeIndex) = .empty;
    defer node_edges.deinit(allocator);
    var use_edges: std.ArrayList(LiteralEdgeIndex) = .empty;
    defer use_edges.deinit(allocator);
    for (edges.items, 0..) |edge, index| switch (edge.key) {
        .node => |id| try node_edges.append(allocator, .{ .key = @bitCast(id), .edge = @intCast(index) }),
        .use => |expr| try use_edges.append(allocator, .{ .key = @backingInt(expr), .edge = @intCast(index) }),
        .literal => checkedArtifactInvariant("a literal requirement's own literal was collected as an edge", .{}),
    };
    std.mem.sort(LiteralEdgeIndex, node_edges.items, {}, LiteralEdgeIndex.lessThan);
    std.mem.sort(LiteralEdgeIndex, use_edges.items, {}, LiteralEdgeIndex.lessThan);

    const component_slots = try allocator.alloc(LiteralComponentSlot, components.count());
    errdefer allocator.free(component_slots);
    @memset(component_slots, .empty);
    const demand_slots = try allocator.alloc(LiteralDemandSlot, template_count);
    errdefer allocator.free(demand_slots);
    @memset(demand_slots, .empty);
    const owned_edges = try edges.toOwnedSlice(allocator);
    errdefer allocator.free(owned_edges);
    const owned_held = try held.toOwnedSlice(allocator);
    errdefer allocator.free(owned_held);
    const owned_own_sites = try own_sites.toOwnedSlice(allocator);
    errdefer allocator.free(owned_own_sites);
    const owned_node_edges = try node_edges.toOwnedSlice(allocator);
    errdefer allocator.free(owned_node_edges);
    const owned_use_edges = try use_edges.toOwnedSlice(allocator);
    errdefer allocator.free(owned_use_edges);
    graph.edges = owned_edges;
    graph.held = owned_held;
    graph.own_sites = owned_own_sites;
    graph.node_edges = owned_node_edges;
    graph.use_edges = owned_use_edges;
    graph.components = components;
    graph.component_slots = component_slots;
    graph.demand_slots = demand_slots;
    const result = try allocator.create(LiteralGraph);
    result.* = graph;
    return result;
}

/// What makes two literal requirements of one literal the same: the type's
/// key, which names its variables only up to renaming, and the variables
/// themselves. Instantiating an open type gives a new root every time, even
/// around a recursive cycle that maps each variable back to itself.
fn literalRequirementTypeIdentity(
    store: *const CheckedTypeStore,
    orderer: *CheckedIdentityOrderer,
    ty: CheckedTypeId,
) Allocator.Error![32]u8 {
    const key = try store.view().rootKey(ty);
    if (!try store.rootContainsIdentityVariables(ty)) return key.bytes;
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    hasher.update(&key.bytes);
    for (try orderer.identityRoots(ty)) |variable| {
        const origin: u32 = @backingInt(store.identityOrigin(variable));
        hasher.update(std.mem.asBytes(&origin));
    }
    return hasher.finalResult();
}

/// Whether every variable of `ty` is quantified by the scheme `key` names
/// (a template's own, or a generalized local scope's) or by one enclosing it.
fn literalRequirementTypeIsBound(
    store: *const CheckedTypeStore,
    orderer: *CheckedIdentityOrderer,
    templates: *const CheckedProcedureTemplateTable,
    dispatch: CheckedDispatch,
    key: LiteralScopeKey,
    ty: CheckedTypeId,
) Allocator.Error!bool {
    variables: for (try orderer.identityRoots(ty)) |variable| {
        const origin = store.identityOrigin(variable);
        var current: ?u32 = key.scope;
        while (current) |id| {
            const dispatch_scope = templates.dispatch_scopes[id];
            for ((try dispatch.scopeSchema(@fromBackingInt(id))).vars) |bound| {
                if (store.identityOrigin(bound) == origin) continue :variables;
            }
            current = if (dispatch_scope.parent) |parent| @backingInt(parent) else null;
        }
        if (key.template) |template_index| {
            for (try dispatch.templateSchemeVars(.row(template_index))) |bound| {
                if (store.identityOrigin(bound) == origin) continue :variables;
            }
        }
        return false;
    }
    return true;
}

fn literalScopeKeyLessThan(_: void, a: LiteralScopeKey, b: LiteralScopeKey) bool {
    const a_template = a.template orelse std.math.maxInt(u32);
    const b_template = b.template orelse std.math.maxInt(u32);
    if (a_template != b_template) return a_template < b_template;
    const a_scope = a.scope orelse std.math.maxInt(u32);
    const b_scope = b.scope orelse std.math.maxInt(u32);
    return a_scope < b_scope;
}

fn comptimeRootIdLessThan(_: void, a: ComptimeRootId, b: ComptimeRootId) bool {
    return @backingInt(a) < @backingInt(b);
}

/// The literal requirements, edge arguments and literal argument roots of
/// one component of a module's literal graph (`ModuleAnalyses.literalComponent`).
pub const LiteralComponent = struct {
    /// The schemes of the component's nodes with literal requirements,
    /// sorted; scheme `i`'s are `requirements[scope_spans[i]]`.
    scope_keys: []const LiteralScopeKey,
    scope_spans: []const artifact_serialize.Span,
    requirements: []const LiteralRequirement,
    /// The edges the component's nodes hold first, ascending, with their
    /// literal arguments: edge `arg_edges[i]`'s are `args[arg_spans[i]]`.
    arg_edges: []const u32,
    arg_spans: []const artifact_serialize.Span,
    args: []const LiteralArgSource,
    /// The component's literal argument roots, by id.
    roots: []const LiteralRootRecord,

    pub fn requirementsOf(self: *const LiteralComponent, key: LiteralScopeKey) []const LiteralRequirement {
        for (self.scope_keys, self.scope_spans) |candidate, span| {
            if (std.meta.eql(candidate, key)) return self.requirements[span.start..][0..span.len];
        }
        return &.{};
    }

    pub fn edgeArgs(self: *const LiteralComponent, edge: u32) []const LiteralArgSource {
        const index = std.sort.binarySearch(u32, self.arg_edges, edge, struct {
            fn order(key: u32, item: u32) std.math.Order {
                return std.math.order(key, item);
            }
        }.order) orelse return &.{};
        const span = self.arg_spans[index];
        return self.args[span.start..][0..span.len];
    }

    pub fn root(self: *const LiteralComponent, id: ComptimeRootId) ?*const LiteralRootRecord {
        const index = std.sort.binarySearch(LiteralRootRecord, self.roots, id, struct {
            fn order(key: ComptimeRootId, item: LiteralRootRecord) std.math.Order {
                return std.math.order(@backingInt(key), @backingInt(item.root.id));
            }
        }.order) orelse return null;
        return &self.roots[index];
    }

    pub fn destroy(self: *LiteralComponent, allocator: Allocator) void {
        allocator.free(self.scope_keys);
        allocator.free(self.scope_spans);
        allocator.free(self.requirements);
        allocator.free(self.arg_edges);
        allocator.free(self.arg_spans);
        allocator.free(self.args);
        allocator.free(self.roots);
        allocator.destroy(self);
    }
};

/// The literal argument roots one template's edges read
/// (`ModuleAnalyses.templateLiteralArgumentDemand`), ascending.
pub const LiteralArgumentDemand = struct {
    roots: []const ComptimeRootId,

    pub fn destroy(self: *LiteralArgumentDemand, allocator: Allocator) void {
        allocator.free(self.roots);
        allocator.destroy(self);
    }
};

/// One step of an exact procedure alias chain: the module its lookup is in
/// (null for this module), the lookup's site substitution, and the
/// quantified variables of the scheme the lookup instantiates, which the
/// substitution is over.
const LiteralAliasStep = struct {
    module: ?ImportedModuleView,
    lookup_subst: []const CheckedTypeId,
    vars: []const CheckedTypeId,
};

/// The scheme of a top-level alias: its callable-eval template's root
/// wrapper template, whose body is the alias's forwarded lookup.
fn literalCallableEvalAliasStep(dispatch: CheckedDispatch, alias_view: ?ImportedModuleView, pattern: CIR.Pattern.Idx) Allocator.Error!struct { lookup: CIR.Expr.Idx, vars: []const CheckedTypeId } {
    const source = dispatch.source;
    const eval_templates: CallableEvalTemplateTableView = if (alias_view) |view| view.callable_eval_templates else source.callable_eval_templates;
    const template = for (eval_templates.templates) |candidate| {
        if (candidate.pattern == pattern) break candidate;
    } else checkedArtifactInvariant("a method's alias binding has no callable-eval template", .{});
    const wrapper_table: *const EntryWrapperTable = if (alias_view) |view| view.entry_wrappers else source.entry_wrappers;
    const wrapper = wrapper_table.lookupByRoot(template.root) orelse checkedArtifactInvariant("a callable-eval template's root has no entry wrapper", .{});
    const procedure_templates: *const CheckedProcedureTemplateTable = if (alias_view) |view| view.checked_procedure_templates else source.templates;
    const wrapper_template = procedure_templates.get(wrapper.template.template);
    return .{
        .lookup = template.forwarded_lookup orelse checkedArtifactInvariant("a method's alias binding is not an exact procedure alias", .{}),
        .vars = try (if (alias_view) |view| view.dispatch() else dispatch).templateSchemeVars(wrapper_template.template_id),
    };
}

/// The steps of the alias chain a dispatch edge to a method bound to an
/// exact procedure alias passes through, each step's lookup instantiating
/// the next scheme; null where the chain leaves this module, whose
/// instantiation the owning module computes. Reads only finished slots and
/// tables; the composition (`composeLiteralAliasChain`) creates the types.
fn literalAliasChainSteps(
    allocator: Allocator,
    dispatch: CheckedDispatch,
    node: static_dispatch.EvidenceNode,
    steps: *std.ArrayListUnmanaged(LiteralAliasStep),
) Allocator.Error!bool {
    const source = dispatch.source;
    const owner = source.key.digest();
    const import_views = dispatchImportViews(dispatch);
    const alias = node.target.alias orelse checkedArtifactInvariant("an alias-instantiated target has no alias binding", .{});
    // The alias binding is in the target's module, which this module is only
    // where the target's template is its own: a module index tells modules
    // of one compilation apart, not a module from the Builtin compiled
    // beside it.
    switch (node.target.kind) {
        .procedure => |procedure| if (!procedure.template.artifact.eql(owner)) return false,
        .local_proc, .structural => checkedArtifactInvariant("an alias-instantiated target is not a procedure", .{}),
    }
    var module: ?ImportedModuleView = null;
    var lookup: CIR.Expr.Idx, var vars: []const CheckedTypeId = switch (alias) {
        .top_level => |pattern| blk: {
            const step = try literalCallableEvalAliasStep(dispatch, null, pattern);
            break :blk .{ step.lookup, step.vars };
        },
        .local => |local| .{ local.lookup, if (local.dispatch_scope) |scope_id| (try dispatch.scopeSchema(scope_id)).vars else &.{} },
    };
    var actual_count = (try dispatch.substitution(node.subst)).len;
    while (true) {
        if (actual_count != vars.len) checkedArtifactInvariant("an alias edge's substitution differs from its alias's scheme", .{});
        const step_dispatch: CheckedDispatch = if (module) |view| view.dispatch() else dispatch;
        const refs: *const ResolvedValueRefTable = if (module) |view| view.resolved_value_refs else source.refs;
        const lookup_subst = (try step_dispatch.siteSubstitution(lookup)) orelse &.{};
        try steps.append(allocator, .{ .module = module, .lookup_subst = lookup_subst, .vars = vars });
        actual_count = lookup_subst.len;
        const ref_id = refs.lookupIdByExpr(lookup) orelse checkedArtifactInvariant("an alias's forwarded lookup has no resolved reference", .{});
        switch (refs.records[@backingInt(ref_id)].ref) {
            .local_proc => |local| {
                if (!local.is_alias) return true;
                lookup = local.expr;
                vars = if (local.dispatch_scope) |scope_id| (try step_dispatch.scopeSchema(scope_id)).vars else &.{};
            },
            inline .top_level_proc, .imported_proc, .hosted_proc, .promoted_top_level_proc, .platform_required_proc => |ref, tag| {
                const use = if (tag == .platform_required_proc) ref.procedure else ref;
                switch (use.binding) {
                    .top_level => |top_level| {
                        const owner_key = top_level.artifact;
                        const local_owner = owner_key.eql(owner);
                        const bindings: *const TopLevelProcedureBindingTable = if (local_owner) source.top_level_procedure_bindings else (import_views.viewForKey(owner_key) orelse return false).top_level_procedure_bindings;
                        switch (bindings.get(top_level.binding).body) {
                            .callable_eval_template => |template_id| {
                                const view = if (local_owner) null else import_views.viewForKey(owner_key);
                                const eval_templates: CallableEvalTemplateTableView = if (view) |v| v.callable_eval_templates else source.callable_eval_templates;
                                if (eval_templates.templates[@backingInt(template_id)].forwarded_lookup == null) return true;
                                const step = try literalCallableEvalAliasStep(dispatch, view, eval_templates.templates[@backingInt(template_id)].pattern);
                                module = view;
                                lookup = step.lookup;
                                vars = step.vars;
                            },
                            .direct_template, .checked_error => return true,
                        }
                    },
                    .imported, .hosted, .platform_required => return true,
                }
            },
            .local_param, .local_value, .local_mutable_version, .pattern_binder, .selected_hoisted_const, .top_level_const, .imported_const, .platform_required_declaration, .platform_required_checked_error, .platform_required_const => checkedArtifactInvariant("a forwarded procedure alias lookup names no procedure", .{}),
        }
    }
}

/// The substitution of the procedure template an alias chain ends at, in
/// this module's store: the edge's instantiation of the first alias's scheme,
/// carried through each step's forwarded lookup. Runs under the store's
/// creation lock.
fn composeLiteralAliasChain(
    allocator: Allocator,
    store: *CheckedTypeStore,
    names: *canonical.CanonicalNameStore,
    first_actuals: []const CheckedTypeId,
    steps: []const LiteralAliasStep,
) Allocator.Error![]CheckedTypeId {
    var actuals = try allocator.dupe(CheckedTypeId, first_actuals);
    errdefer allocator.free(actuals);
    for (steps) |step| {
        var projector: ?CheckedTypeStoreImportProjector = if (step.module) |view| CheckedTypeStoreImportProjector.init(allocator, store, names, view) else null;
        defer if (projector) |*p| p.deinit();
        const formals = try allocator.alloc(CheckedTypeId, step.vars.len);
        defer allocator.free(formals);
        for (step.vars, formals) |variable, *out| out.* = if (projector) |*p| try p.project(variable) else variable;
        // The next scheme's variables, as the lookup instantiates them over
        // this scheme's variables, at this edge's types.
        const composed = try allocator.alloc(CheckedTypeId, step.lookup_subst.len);
        errdefer allocator.free(composed);
        for (step.lookup_subst, composed) |checked_ty, *out| {
            const projected = if (projector) |*p| try p.project(checked_ty) else checked_ty;
            var substitution = CheckedTypeSubstitution.init(allocator, formals, actuals);
            defer substitution.deinit();
            out.* = try store.cloneCheckedTypeRootSubstituting(allocator, projected, &substitution);
        }
        allocator.free(actuals);
        actuals = composed;
    }
    return actuals;
}

/// The literal requirements, edge arguments and literal argument roots of
/// component `component` of `graph` (design.md "Literal Arguments"). An
/// edge that instantiates a scheme instantiates each of the callee's
/// literal requirements at the edge's substitution: a closed type gets a
/// literal argument root of this module converting the literal at that
/// type, named by the edge and the requirement; an open one becomes a
/// literal requirement of the scope the edge is in, forwarded in turn.
/// Requirements are computed to a fixpoint over the component's edges.
/// Every callee component and every imported callee's requirements are done
/// before the component is claimed (`ModuleAnalyses.literalComponent`).
/// Types are created under the store's creation lock, which is held around
/// each creation only, after every slot the creation reads.
pub fn computeLiteralComponent(
    allocator: Allocator,
    dispatch: CheckedDispatch,
    graph: *const LiteralGraph,
    component: u32,
) Allocator.Error!*LiteralComponent {
    const source = dispatch.source;
    const owner = source.key.digest();
    const store = source.types.store;
    const names = source.names;
    const io = source.analyses.io;
    const templates = source.templates;
    const import_views = dispatchImportViews(dispatch);
    const members = graph.components.componentMembers(component);

    var orderer = CheckedIdentityOrderer.init(allocator, names, store);
    defer orderer.deinit();

    const ObligationKey = LiteralObligationKey;
    var states: LiteralScopeStates = .empty;
    defer {
        var it = states.valueIterator();
        while (it.next()) |state| {
            state.list.deinit(allocator);
            state.index.deinit(allocator);
        }
        states.deinit(allocator);
    }

    // The component's own open literals.
    for (members) |node| {
        for (graph.own_sites[graph.own_starts[node]..graph.own_starts[node + 1]]) |own| {
            const entry = try states.getOrPut(allocator, own.scope);
            if (!entry.found_existing) entry.value_ptr.* = .{};
            const slot = try entry.value_ptr.index.getOrPut(allocator, .{ .site = own.site, .ty = try literalRequirementTypeIdentity(store, &orderer, own.ty) });
            if (slot.found_existing) continue;
            slot.value_ptr.* = @intCast(entry.value_ptr.list.items.len);
            try entry.value_ptr.list.append(allocator, .{ .site = own.site, .ty = own.ty, .edge = .literal, .callee_requirement = 0 });
        }
    }

    const ArgBuild = union(enum) { root: ComptimeRootId, forwarded: u32, unbound };
    const EdgeState = struct {
        index: u32,
        edge: LiteralGraphEdge,
        callee: LiteralCalleeScheme,
        alias_steps: std.ArrayListUnmanaged(LiteralAliasStep) = .empty,
        /// The edge's substitution; owned when an alias chain composed it.
        subst: []const CheckedTypeId = &.{},
        owned_subst: ?[]CheckedTypeId = null,
        formals: []CheckedTypeId = &.{},
        projector: ?*CheckedTypeStoreImportProjector = null,
        substitution: ?CheckedTypeSubstitution = null,
        args: std.ArrayListUnmanaged(ArgBuild) = .empty,
    };
    var edge_states: std.ArrayListUnmanaged(EdgeState) = .empty;
    defer {
        for (edge_states.items) |*state| {
            state.alias_steps.deinit(allocator);
            if (state.owned_subst) |slice| allocator.free(slice);
            allocator.free(state.formals);
            if (state.projector) |projector| {
                projector.deinit();
                allocator.destroy(projector);
            }
            if (state.substitution) |*substitution| substitution.deinit();
            state.args.deinit(allocator);
        }
        edge_states.deinit(allocator);
    }
    var modules: std.ArrayListUnmanaged(ModuleId) = .empty;
    defer modules.deinit(allocator);
    for (members) |node| {
        for (graph.nodeEdges(node), graph.edge_starts[node]..) |edge, edge_index| {
            const callee: LiteralCalleeScheme = switch (edge.callee) {
                .template => |template| blk: {
                    if (template.artifact.eql(owner)) {
                        const key: LiteralScopeKey = .{ .template = template.template.index(), .scope = null };
                        break :blk literalLocalCallee(graph, component, key, try dispatch.templateSchemeVars(template.template));
                    }
                    const view = import_views.viewForKey(template.artifact) orelse continue;
                    try modules.append(allocator, template.artifact);
                    break :blk .{
                        .live = null,
                        .finished = try view.dispatch().templateLiteralRequirements(template.template),
                        .vars = try view.dispatch().templateSchemeVars(template.template),
                        .module = view,
                    };
                },
                .scope => |scope_id| literalLocalCallee(
                    graph,
                    component,
                    .{ .template = graph.scope_owners[@backingInt(scope_id)], .scope = @backingInt(scope_id) },
                    (try dispatch.scopeSchema(scope_id)).vars,
                ),
            };
            var state: EdgeState = .{ .index = @intCast(edge_index), .edge = edge, .callee = callee };
            switch (edge.subst) {
                .evidence => |span| state.subst = try dispatch.substitution(span),
                .site => |expr| state.subst = (try dispatch.siteSubstitution(expr)) orelse &.{},
                .alias_chain => |id| {
                    const evidence_node = try dispatch.evidenceNode(id);
                    if (!try literalAliasChainSteps(allocator, dispatch, evidence_node, &state.alias_steps)) {
                        state.alias_steps.deinit(allocator);
                        continue;
                    }
                    state.subst = try dispatch.substitution(evidence_node.subst);
                    for (state.alias_steps.items) |step| if (step.module) |view| try modules.append(allocator, view.key.digest());
                },
            }
            try edge_states.append(allocator, state);
        }
    }

    // Read the nominal representations of every module whose types the
    // creations below copy before taking the creation lock.
    try demandLiteralCapabilities(dispatch, modules.items);
    {
        store.beginCreation(io);
        defer store.endCreation(io);
        for (edge_states.items) |*state| {
            if (state.alias_steps.items.len != 0) {
                const composed = try composeLiteralAliasChain(allocator, store, names, state.subst, state.alias_steps.items);
                state.owned_subst = composed;
                state.subst = composed;
            }
            state.formals = try allocator.alloc(CheckedTypeId, state.callee.vars.len);
            if (state.callee.module) |view| {
                const projector = try allocator.create(CheckedTypeStoreImportProjector);
                projector.* = CheckedTypeStoreImportProjector.init(allocator, store, names, view);
                state.projector = projector;
                for (state.callee.vars, state.formals) |variable, *out| out.* = try projector.project(variable);
            } else @memcpy(state.formals, state.callee.vars);
            if (state.subst.len != 0) {
                if (state.subst.len != state.formals.len) checkedArtifactInvariant("an edge's substitution differs from its callee's scheme", .{});
                state.substitution = CheckedTypeSubstitution.init(allocator, state.formals, state.subst);
            }
        }
    }

    const NewRoot = struct { id: ComptimeRootId, site: LiteralSite, ty: CheckedTypeId, edge: LiteralEdge, callee_requirement: u32, owner_expr: CIR.Expr.Idx };
    var new_roots: std.ArrayListUnmanaged(NewRoot) = .empty;
    defer new_roots.deinit(allocator);
    var root_index = std.AutoHashMapUnmanaged(ObligationKey, ComptimeRootId).empty;
    defer root_index.deinit(allocator);
    while (true) {
        var changed = false;
        for (edge_states.items) |*state| {
            const callee = state.callee;
            // A use with no recorded instantiation of a scheme with
            // variables instantiates nothing.
            if (callee.vars.len != 0 and state.subst.len == 0) continue;
            var j: u32 = @intCast(state.args.items.len);
            // A self-recursive edge appends to the list it instantiates.
            while (j < literalCalleeRequirements(callee, &states).len) : (j += 1) {
                const obligation = literalCalleeRequirements(callee, &states)[j];
                const ty = created: {
                    store.beginCreation(io);
                    defer store.endCreation(io);
                    const projected = if (state.projector) |projector| try projector.project(obligation.ty) else obligation.ty;
                    break :created if (state.substitution) |*substitution| try store.cloneCheckedTypeRootSubstituting(allocator, projected, substitution) else projected;
                };
                const key: ObligationKey = .{ .site = obligation.site, .ty = try literalRequirementTypeIdentity(store, &orderer, ty) };
                if (!try store.rootContainsIdentityVariables(ty)) {
                    const slot = try root_index.getOrPut(allocator, key);
                    if (!slot.found_existing) {
                        const id = literalArgumentRootId(state.edge.key, j);
                        slot.value_ptr.* = id;
                        try new_roots.append(allocator, .{
                            .id = id,
                            .site = obligation.site,
                            .ty = ty,
                            .edge = state.edge.key,
                            .callee_requirement = j,
                            .owner_expr = state.edge.owner_expr,
                        });
                    }
                    try state.args.append(allocator, .{ .root = slot.value_ptr.* });
                } else if (state.edge.scope != null and !try literalRequirementTypeIsBound(store, &orderer, templates, dispatch, state.edge.scope.?, ty)) {
                    // No use fixes a variable no scheme around the edge
                    // quantifies, so nothing converts this literal.
                    try state.args.append(allocator, .unbound);
                } else {
                    const scope_key = state.edge.scope orelse checkedArtifactInvariant("a defaulted field expression instantiates a literal obligation at an open type", .{});
                    const entry = try states.getOrPut(allocator, scope_key);
                    if (!entry.found_existing) entry.value_ptr.* = .{};
                    const slot = try entry.value_ptr.index.getOrPut(allocator, key);
                    if (!slot.found_existing) {
                        slot.value_ptr.* = @intCast(entry.value_ptr.list.items.len);
                        try entry.value_ptr.list.append(allocator, .{ .site = obligation.site, .ty = ty, .edge = state.edge.key, .callee_requirement = j });
                    }
                    try state.args.append(allocator, .{ .forwarded = slot.value_ptr.* });
                }
                changed = true;
            }
        }
        if (!changed) break;
    }

    // The requirement lists.
    var scope_keys: std.ArrayListUnmanaged(LiteralScopeKey) = .empty;
    defer scope_keys.deinit(allocator);
    {
        var it = states.keyIterator();
        while (it.next()) |key| try scope_keys.append(allocator, key.*);
    }
    std.mem.sort(LiteralScopeKey, scope_keys.items, {}, literalScopeKeyLessThan);
    const scope_spans = try allocator.alloc(artifact_serialize.Span, scope_keys.items.len);
    errdefer allocator.free(scope_spans);
    var requirements: std.ArrayListUnmanaged(LiteralRequirement) = .empty;
    defer requirements.deinit(allocator);
    for (scope_keys.items, scope_spans) |key, *span| {
        const list = states.getPtr(key).?.list.items;
        span.* = .{ .start = @intCast(requirements.items.len), .len = @intCast(list.len) };
        try requirements.appendSlice(allocator, list);
    }

    // The edges' literal arguments.
    var arg_edges: std.ArrayListUnmanaged(u32) = .empty;
    defer arg_edges.deinit(allocator);
    var arg_spans: std.ArrayListUnmanaged(artifact_serialize.Span) = .empty;
    defer arg_spans.deinit(allocator);
    var args: std.ArrayListUnmanaged(LiteralArgSource) = .empty;
    defer args.deinit(allocator);
    for (edge_states.items) |state| {
        if (state.args.items.len == 0) continue;
        try arg_edges.append(allocator, state.index);
        try arg_spans.append(allocator, .{ .start = @intCast(args.items.len), .len = @intCast(state.args.items.len) });
        for (state.args.items) |arg| try args.append(allocator, switch (arg) {
            .root => |id| .{ .root = id },
            .forwarded => |index| .{ .forwarded = index },
            .unbound => .unbound,
        });
    }

    // The roots, each with its entry wrapper.
    std.mem.sort(NewRoot, new_roots.items, {}, struct {
        fn lessThan(_: void, a: NewRoot, b: NewRoot) bool {
            return @backingInt(a.id) < @backingInt(b.id);
        }
    }.lessThan);
    const roots = try allocator.alloc(LiteralRootRecord, new_roots.items.len);
    errdefer allocator.free(roots);
    for (new_roots.items, roots) |new_root, *record| {
        const validate_only = !new_root.site.carriesValue() or try checkedTypeHoldsFunction(allocator, store.view(), owner, import_views, new_root.ty);
        const eligible = try checkedTypeIsContextFreeCompileTimeRoot(allocator, owner, store.view(), import_views.resolver(), false, new_root.ty);
        record.* = .{
            .root = .{
                .id = new_root.id,
                .module_idx = source.module_idx,
                .kind = .literal_argument,
                .source = .{ .expr = new_root.owner_expr },
                .pattern = null,
                .expr = new_root.owner_expr,
                .checked_type = new_root.ty,
                .request_eligibility = if (eligible) .eligible else .ineligible,
                .payload = .pending,
                .literal_argument = .{
                    .site = new_root.site,
                    .ty = new_root.ty,
                    .edge = new_root.edge,
                    .callee_requirement = new_root.callee_requirement,
                    .validate_only = validate_only,
                },
            },
            .checked_fn_root = undefined, // Created below, under the creation lock.
            .checked_fn_scheme = undefined, // Created below, under the creation lock.
            .plan = null,
            .relation = undefined, // Set below from the created function type.
        };
    }
    {
        store.beginCreation(io);
        defer store.endCreation(io);
        for (roots) |*record| {
            record.checked_fn_root = try store.appendSyntheticFunctionRoot(allocator, .pure, &.{}, record.root.checked_type);
            record.checked_fn_scheme = try store.ensureSchemeForRoot(allocator, record.checked_fn_root);
        }
    }
    for (roots) |*record| record.relation = literalRootWrapperRelation(record.checked_fn_root, record.root.checked_type);

    const owned_scope_keys = try scope_keys.toOwnedSlice(allocator);
    errdefer allocator.free(owned_scope_keys);
    const owned_requirements = try requirements.toOwnedSlice(allocator);
    errdefer allocator.free(owned_requirements);
    const owned_arg_edges = try arg_edges.toOwnedSlice(allocator);
    errdefer allocator.free(owned_arg_edges);
    const owned_arg_spans = try arg_spans.toOwnedSlice(allocator);
    errdefer allocator.free(owned_arg_spans);
    const owned_args = try args.toOwnedSlice(allocator);
    errdefer allocator.free(owned_args);
    const result = try allocator.create(LiteralComponent);
    result.* = .{
        .scope_keys = owned_scope_keys,
        .scope_spans = scope_spans,
        .requirements = owned_requirements,
        .arg_edges = owned_arg_edges,
        .arg_spans = owned_arg_spans,
        .args = owned_args,
        .roots = roots,
    };
    return result;
}

/// The literal argument roots template `template`'s edges read: every
/// evaluation of the template reads their values. Every component holding
/// one of the template's edges is done before the template's slot is
/// claimed (`ModuleAnalyses.templateLiteralArgumentDemand`).
pub fn computeLiteralArgumentDemand(allocator: Allocator, graph: *const LiteralGraph, template: u32) Allocator.Error!*LiteralArgumentDemand {
    var roots: std.ArrayList(ComptimeRootId) = .empty;
    defer roots.deinit(allocator);
    for (graph.held[graph.held_starts[template]..graph.held_starts[template + 1]]) |edge| {
        const component = graph.component_slots[graph.components.component_of[graph.edges[edge].holder]].peek() orelse
            checkedArtifactInvariant("a template's literal demand was computed before the component of an edge it holds", .{});
        for (component.edgeArgs(edge)) |arg| switch (arg) {
            .root => |id| try roots.append(allocator, id),
            .forwarded, .unbound => {},
        };
    }
    std.mem.sort(ComptimeRootId, roots.items, {}, comptimeRootIdLessThan);
    var kept: usize = 0;
    for (roots.items, 0..) |id, index| {
        if (index != 0 and roots.items[index - 1] == id) continue;
        roots.items[kept] = id;
        kept += 1;
    }
    roots.shrinkRetainingCapacity(kept);
    const result = try allocator.create(LiteralArgumentDemand);
    errdefer allocator.destroy(result);
    result.* = .{ .roots = try roots.toOwnedSlice(allocator) };
    return result;
}

const LiteralObligationKey = struct { site: LiteralSite, ty: [32]u8 };

/// One scheme's literal requirements while its component is computed, with
/// the index that keeps each requirement once.
const LiteralScopeState = struct {
    list: std.ArrayListUnmanaged(LiteralRequirement) = .empty,
    index: std.AutoHashMapUnmanaged(LiteralObligationKey, u32) = .empty,
};

const LiteralScopeStates = std.AutoHashMapUnmanaged(LiteralScopeKey, LiteralScopeState);

/// An edge's callee scheme: its literal requirements (a live list for a
/// scheme of the component being computed) and its quantified variables, in
/// the scheme's module.
const LiteralCalleeScheme = struct {
    live: ?LiteralScopeKey,
    finished: []const LiteralRequirement,
    vars: []const CheckedTypeId,
    module: ?ImportedModuleView,
};

fn literalCalleeRequirements(callee: LiteralCalleeScheme, states: *const LiteralScopeStates) []const LiteralRequirement {
    const key = callee.live orelse return callee.finished;
    return if (states.getPtr(key)) |state| state.list.items else &.{};
}

/// A callee scheme of this module: live while its component is the one being
/// computed, otherwise the finished requirements of its component.
fn literalLocalCallee(graph: *const LiteralGraph, component: u32, key: LiteralScopeKey, vars: []const CheckedTypeId) LiteralCalleeScheme {
    const node = graph.nodeOfScope(key);
    const callee_component = graph.components.component_of[node];
    if (callee_component == component) return .{ .live = key, .finished = &.{}, .vars = vars, .module = null };
    const done = graph.component_slots[callee_component].peek() orelse
        checkedArtifactInvariant("a literal component was computed before its callee component", .{});
    return .{ .live = null, .finished = done.requirementsOf(key), .vars = vars, .module = null };
}

/// Whether a value of the closed type `ty` holds a function: a function
/// type anywhere in it, through aliases, nominal backings, and the builtin
/// encodings that hold callables.
fn checkedTypeHoldsFunction(
    allocator: Allocator,
    own_types: CheckedTypeStoreView,
    own_key: CheckedModuleDigest,
    import_views: CheckedImportViews,
    ty: CheckedTypeId,
) Allocator.Error!bool {
    const Pending = struct { key: [32]u8, types: CheckedTypeStoreView, ty: CheckedTypeId };
    const Seen = struct { key: [32]u8, ty: CheckedTypeId };
    var seen = std.AutoHashMapUnmanaged(Seen, void).empty;
    defer seen.deinit(allocator);
    var pending = std.ArrayListUnmanaged(Pending).empty;
    defer pending.deinit(allocator);
    try pending.append(allocator, .{ .key = own_key.bytes, .types = own_types, .ty = ty });
    while (pending.pop()) |item| {
        const seen_entry = try seen.getOrPut(allocator, .{ .key = item.key, .ty = item.ty });
        if (seen_entry.found_existing) continue;
        switch (item.types.payload(item.ty)) {
            .function => return true,
            .pending, .field_kind, .err, .flex, .rigid, .empty_record, .empty_tag_union => {},
            .alias => |alias| {
                try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = alias.backing });
                for (alias.args) |arg| try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = arg });
            },
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = field.ty });
                }
                try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = record.ext });
            },
            .tuple => |items| for (items) |elem| try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = elem }),
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    for (tag.args) |arg| try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = arg });
                }
                try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = tag_union.ext });
            },
            .nominal => |nominal| {
                for (nominal.args) |arg| try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = arg });
                switch (nominal.representation) {
                    .builtin => |builtin_nominal| switch (builtinRuntimeEncoding(builtin_nominal)) {
                        .parse_tag_union_spec => return true,
                        .primitive, .bool_tag_union, .try_nominal, .list, .box, .dict, .set, .fields, .field, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher => {},
                        .iterator => {
                            const owner = nominal.owner_module.*;
                            const declaring: CheckedTypeStoreView = if (owner.eql(own_key))
                                own_types
                            else
                                (import_views.viewForKey(owner) orelse checkedArtifactInvariant("a nominal type's declaring module is not available", .{})).checked_types;
                            const declaration = declaring.builtinNominalDeclaration(builtin_nominal) orelse
                                checkedArtifactInvariant("the Builtin module has no declaration for the builtin iterator", .{});
                            try pending.append(allocator, .{ .key = owner.bytes, .types = declaring, .ty = declaration.backing });
                        },
                    },
                    .local_declaration => |declaration_id| try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = item.types.nominalDeclarationById(declaration_id).backing }),
                    .imported_declaration => |imported| {
                        const declaring: CheckedTypeStoreView = if (imported.artifact.eql(own_key))
                            own_types
                        else
                            (import_views.viewForKey(imported.artifact) orelse checkedArtifactInvariant("a nominal type's declaring module is not available", .{})).checked_types;
                        try pending.append(allocator, .{ .key = imported.artifact.bytes, .types = declaring, .ty = declaring.nominalDeclarationById(imported.declaration).backing });
                    },
                    // A nominal published as a box payload capability is
                    // declared in its module like any other.
                    .local_box_payload_capability => {
                        const declaration = item.types.nominalDeclarationForPayload(nominal) orelse
                            checkedArtifactInvariant("a box payload capability names a nominal its module does not declare", .{});
                        try pending.append(allocator, .{ .key = item.key, .types = item.types, .ty = declaration.backing });
                    },
                    // The capability names its nominal in the declaring
                    // module's own names.
                    .imported_box_payload_capability => |imported| {
                        if (imported.artifact.eql(own_key)) {
                            const declaration = own_types.nominalDeclarationForPayload(nominal) orelse
                                checkedArtifactInvariant("a box payload capability names a nominal its module does not declare", .{});
                            try pending.append(allocator, .{ .key = imported.artifact.bytes, .types = own_types, .ty = declaration.backing });
                        } else {
                            const declaring = import_views.viewForKey(imported.artifact) orelse checkedArtifactInvariant("a nominal type's declaring module is not available", .{});
                            const capability = (try declaring.checked_types.interfaceCapabilities(import_views.resolver())).boxPayloadCapability(imported.capability);
                            const declaration = declaring.checked_types.nominalDeclaration(capability.nominal) orelse
                                checkedArtifactInvariant("a box payload capability names a nominal its module does not declare", .{});
                            try pending.append(allocator, .{ .key = imported.artifact.bytes, .types = declaring.checked_types, .ty = declaration.backing });
                        }
                    },
                    .opaque_without_backing => {},
                }
            },
        }
    }
    return false;
}

fn checkedDispatchPlanNeedsRelation(
    dispatch: CheckedDispatch,
    plan: static_dispatch.StaticDispatchCallPlan,
) Allocator.Error!bool {
    return switch (plan.resolution) {
        .direct_closed, .direct_parametric => |direct| switch ((try dispatch.evidenceNode(direct.evidence)).target.kind) {
            .procedure => |procedure| switch (procedure.runtime_target) {
                .graph_participating, .intrinsic => true,
                .procedure, .low_level => false,
            },
            .local_proc => false,
            .structural => checkedArtifactInvariant("direct checked call targeted a structural derivation", .{}),
        },
        .direct_pending => checkedArtifactInvariant("unfinalized direct call reached template classification", .{}),
        .evidence_dependent, .structural, .@"unreachable", .checked_error => true,
    };
}

const ResolvedDispatchCallablePair = struct {
    target: CheckedTypeId,
    plan: CheckedTypeId,
};

/// The store a dispatch specialization relates and creates types in: the
/// types of module `module`, whose nominal types' declarations of other
/// modules `resolver` resolves.
const DispatchSubstitutionTypes = struct {
    store: *CheckedTypeStore,
    names: *canonical.CanonicalNameStore,
    module: ModuleId,
    resolver: ModuleResolver,
};

fn instantiateResolvedDispatchTargetCallableMemoized(
    allocator: Allocator,
    dispatch_types: DispatchSubstitutionTypes,
    target_callable: CheckedTypeId,
    plan_callable: CheckedTypeId,
    memo: *std.AutoHashMapUnmanaged(ResolvedDispatchCallablePair, CheckedTypeId),
) Allocator.Error!CheckedTypeId {
    const key = ResolvedDispatchCallablePair{
        .target = target_callable,
        .plan = plan_callable,
    };
    if (memo.get(key)) |existing| return existing;

    const instantiated = try instantiateResolvedDispatchTargetCallable(
        allocator,
        dispatch_types,
        target_callable,
        plan_callable,
    );
    try memo.put(allocator, key, instantiated);
    return instantiated;
}

fn projectResolvedDispatchTargetCallable(
    allocator: Allocator,
    names: *canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    owner: ModuleId,
    imports: CheckedImportViews,
    target: static_dispatch.MethodTarget,
) Allocator.Error!CheckedTypeId {
    const target_key = switch (target.kind) {
        .local_proc => return target.callable_ty,
        .structural => checkedArtifactInvariant("structural method registry result was published as a direct callable target", .{}),
        .procedure => |procedure| procedure.template.artifact,
    };
    if (target_key.eql(owner)) return target.callable_ty;

    const imported = imports.viewForKey(target_key) orelse
        checkedArtifactInvariant("resolved dispatch target module was not among the modules dispatch resolution reads", .{});
    var projector = CheckedTypeStoreImportProjector.init(allocator, store, names, imported);
    defer projector.deinit();
    return try projector.project(target.callable_ty);
}

fn instantiateResolvedDispatchTargetCallable(
    allocator: Allocator,
    dispatch_types: DispatchSubstitutionTypes,
    target_callable: CheckedTypeId,
    plan_callable: CheckedTypeId,
) Allocator.Error!CheckedTypeId {
    const store = dispatch_types.store;
    const target_fn = checkedFunctionPayload(store, target_callable, "resolved dispatch target callable");
    const plan_fn = checkedFunctionPayload(store, plan_callable, "resolved dispatch plan callable");
    if (target_fn.args.len != plan_fn.args.len) {
        checkedArtifactInvariant("resolved dispatch target arity differed from plan arity", .{});
    }
    const target_args = try allocator.dupe(CheckedTypeId, target_fn.args);
    defer allocator.free(target_args);
    const plan_args = try allocator.dupe(CheckedTypeId, plan_fn.args);
    defer allocator.free(plan_args);
    const plan_ret = plan_fn.ret;

    var target_formals = std.ArrayList(CheckedTypeId).empty;
    defer target_formals.deinit(allocator);
    var target_actuals = std.ArrayList(CheckedTypeId).empty;
    defer target_actuals.deinit(allocator);
    var active = std.AutoHashMap(PlatformRequirementTypePair, void).init(allocator);
    defer active.deinit();
    var target_conflicts = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer target_conflicts.deinit();

    for (target_args, plan_args) |target_arg, plan_arg| {
        try collectResolvedDispatchTargetSubstitutions(
            allocator,
            dispatch_types,
            target_arg,
            plan_arg,
            &target_formals,
            &target_actuals,
            &active,
            &target_conflicts,
        );
    }

    var target_substitution = CheckedTypeSubstitution.init(allocator, target_formals.items, target_actuals.items);
    defer target_substitution.deinit();
    const instantiated_target = try store.cloneCheckedTypeRootSubstituting(allocator, target_callable, &target_substitution);
    const target_instantiated_fn = checkedFunctionPayload(store, instantiated_target, "instantiated resolved dispatch target callable");
    const target_instantiated_args = try allocator.dupe(CheckedTypeId, target_instantiated_fn.args);
    defer allocator.free(target_instantiated_args);
    const target_instantiated_ret = target_instantiated_fn.ret;

    var plan_formals = std.ArrayList(CheckedTypeId).empty;
    defer plan_formals.deinit(allocator);
    var plan_actuals = std.ArrayList(CheckedTypeId).empty;
    defer plan_actuals.deinit(allocator);

    active.clearRetainingCapacity();
    for (target_instantiated_args, plan_args) |target_arg, plan_arg| {
        try collectDispatchPlanIdentitySubstitutions(
            allocator,
            dispatch_types,
            target_arg,
            plan_arg,
            &plan_formals,
            &plan_actuals,
            &active,
        );
    }
    active.clearRetainingCapacity();
    try collectDispatchPlanIdentitySubstitutions(
        allocator,
        dispatch_types,
        target_instantiated_ret,
        plan_ret,
        &plan_formals,
        &plan_actuals,
        &active,
    );

    var plan_substitution = CheckedTypeSubstitution.init(allocator, plan_formals.items, plan_actuals.items);
    defer plan_substitution.deinit();
    return try store.cloneCheckedTypeRootSubstituting(allocator, plan_callable, &plan_substitution);
}

/// The function payload a checked type resolves to through its alias chain.
/// Any other payload, or a cyclic chain, is an invariant violation naming
/// `context`.
pub fn checkedFunctionPayload(
    store: anytype,
    root: CheckedTypeId,
    comptime context: []const u8,
) CheckedFunctionType {
    var current = root;
    var remaining = store.typeCount();
    while (true) {
        const payload = store.payload(current);
        if (payload == .alias) {
            current = payload.alias.backing;
        } else if (payload == .function) {
            return payload.function;
        } else {
            checkedArtifactInvariant(context ++ " was not a function", .{});
        }
        if (remaining == 0) {
            checkedArtifactInvariant(context ++ " alias chain was cyclic", .{});
        }
        remaining -= 1;
    }
}

fn collectResolvedDispatchTargetSubstitutions(
    allocator: Allocator,
    dispatch_types: DispatchSubstitutionTypes,
    target: CheckedTypeId,
    plan: CheckedTypeId,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
    conflicts: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!void {
    try walkDispatchSubstitutions(.resolved_target, allocator, dispatch_types, target, plan, formals, actuals, active, conflicts);
}

fn collectDispatchPlanIdentitySubstitutions(
    allocator: Allocator,
    dispatch_types: DispatchSubstitutionTypes,
    target: CheckedTypeId,
    plan: CheckedTypeId,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
) Allocator.Error!void {
    try walkDispatchSubstitutions(.plan_identity, allocator, dispatch_types, target, plan, formals, actuals, active, {});
}

/// `resolved_target` relates a resolved target's identities to the plan's
/// types, keeping only consistent ones; `plan_identity` relates the plan's
/// identities to the target's structure.
const DispatchSubstitutionMode = enum { resolved_target, plan_identity };

const DispatchSubstitutionItem = union(enum) {
    pair: struct { target: CheckedTypeId, plan: CheckedTypeId },
    /// Every pair below this one's has been related, so it leaves the
    /// active path.
    exit: PlatformRequirementTypePair,
};

/// Relate `target` to `plan` position by position. Pairs are related in
/// source order from an explicit work list; a pair already on the current
/// path is skipped, which is what closes cycles.
fn walkDispatchSubstitutions(
    comptime mode: DispatchSubstitutionMode,
    allocator: Allocator,
    dispatch_types: DispatchSubstitutionTypes,
    target: CheckedTypeId,
    plan: CheckedTypeId,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
    conflicts: switch (mode) {
        .resolved_target => *collections.DenseMap(CheckedTypeId, void),
        .plan_identity => void,
    },
) Allocator.Error!void {
    var pending: std.ArrayListUnmanaged(DispatchSubstitutionItem) = .empty;
    defer pending.deinit(allocator);
    try pending.append(allocator, .{ .pair = .{ .target = target, .plan = plan } });
    while (pending.pop()) |item| switch (item) {
        .exit => |pair| _ = active.remove(pair),
        .pair => |pair| try dispatchSubstitutionStep(mode, allocator, dispatch_types, pair.target, pair.plan, formals, actuals, active, conflicts, &pending),
    };
}

/// Relate one pair: record a substitution, or queue the child pairs that
/// relate its structure.
fn dispatchSubstitutionStep(
    comptime mode: DispatchSubstitutionMode,
    allocator: Allocator,
    dispatch_types: DispatchSubstitutionTypes,
    target: CheckedTypeId,
    plan: CheckedTypeId,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
    conflicts: switch (mode) {
        .resolved_target => *collections.DenseMap(CheckedTypeId, void),
        .plan_identity => void,
    },
    pending: *std.ArrayListUnmanaged(DispatchSubstitutionItem),
) Allocator.Error!void {
    const names = dispatch_types.names;
    const store = dispatch_types.store;
    if (target == plan) return;

    const pair = PlatformRequirementTypePair{
        .expected = @backingInt(target),
        .actual = @backingInt(plan),
    };
    if (active.contains(pair)) return;
    try active.put(pair, {});
    try pending.append(allocator, .{ .exit = pair });
    const start = pending.items.len;
    defer std.mem.reverse(DispatchSubstitutionItem, pending.items[start..]);

    const target_payload = store.payload(target);
    const plan_payload = store.payload(plan);

    switch (mode) {
        .resolved_target => {
            if (checkedTypePayloadIsIdentity(target_payload)) {
                try appendConsistentDispatchTargetSubstitution(formals, actuals, conflicts, allocator, target, plan);
                return;
            }
            if (checkedTypePayloadIsIdentity(plan_payload)) return;
        },
        .plan_identity => {
            if (checkedTypePayloadIsIdentity(plan_payload)) {
                if (!checkedTypePayloadIsIdentity(target_payload)) {
                    try appendUniqueCheckedTypeSubstitution(formals, actuals, allocator, store, plan, target);
                }
                return;
            }
            if (checkedTypePayloadIsIdentity(target_payload)) return;
        },
    }

    if (target_payload == .alias) {
        return try pending.append(allocator, .{ .pair = .{ .target = target_payload.alias.backing, .plan = plan } });
    }
    if (plan_payload == .alias) {
        return try pending.append(allocator, .{ .pair = .{ .target = target, .plan = plan_payload.alias.backing } });
    }

    switch (target_payload) {
        .function => |target_fn| {
            const plan_fn = switch (plan_payload) {
                .function => |function| function,
                .pending,
                .field_kind,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .tuple,
                .nominal,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => return,
            };
            if (target_fn.args.len != plan_fn.args.len) return;
            try appendDispatchSubstitutionPairs(allocator, pending, target_fn.args, plan_fn.args);
            if (mode == .plan_identity) {
                try pending.append(allocator, .{ .pair = .{ .target = target_fn.ret, .plan = plan_fn.ret } });
            }
        },
        .nominal => |target_nominal| {
            const plan_nominal = switch (plan_payload) {
                .nominal => |nominal| nominal,
                .pending,
                .field_kind,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .tuple,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => {
                    if (!target_nominal.is_opaque) {
                        const target_backing = (try store.ensureInstantiatedNominalBackingRootForPayload(
                            allocator,
                            dispatch_types.names,
                            dispatch_types.module,
                            dispatch_types.resolver,
                            target_nominal,
                        )) orelse return;
                        try pending.append(allocator, .{ .pair = .{ .target = target_backing, .plan = plan } });
                    }
                    return;
                },
            };
            if (target_nominal.name != plan_nominal.name or
                target_nominal.origin_module != plan_nominal.origin_module or
                !target_nominal.owner_module.*.eql(plan_nominal.owner_module.*) or
                target_nominal.source_decl != plan_nominal.source_decl or
                target_nominal.builtin != plan_nominal.builtin or
                target_nominal.args.len != plan_nominal.args.len)
            {
                return;
            }
            // Matching nominal applications are completely related by their
            // arguments. Their shared declaration backing is representation
            // data and is opened only for nominal-versus-structural relations.
            try appendDispatchSubstitutionPairs(allocator, pending, target_nominal.args, plan_nominal.args);
        },
        .tuple => |target_items| {
            const plan_items = switch (plan_payload) {
                .tuple => |items| items,
                .pending,
                .field_kind,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .nominal,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => return,
            };
            if (target_items.len != plan_items.len) return;
            try appendDispatchSubstitutionPairs(allocator, pending, target_items, plan_items);
        },
        .empty_record,
        .record,
        => {
            const target_parts = recordParts(target_payload) orelse return;
            const plan_parts = recordParts(plan_payload) orelse return;
            const target_row = try flattenPlatformRequirementRecordRow(allocator, store, target_parts.fields, target_parts.ext);
            defer target_row.deinit(allocator);
            const plan_row = try flattenPlatformRequirementRecordRow(allocator, store, plan_parts.fields, plan_parts.ext);
            defer plan_row.deinit(allocator);

            for (target_row.fields) |target_field| {
                const plan_field = findRecordField(names, plan_row.fields, target_field.name) orelse continue;
                try pending.append(allocator, .{ .pair = .{ .target = target_field.ty, .plan = plan_field.ty } });
            }
            if (target_row.tail) |target_tail| {
                if (plan_row.tail) |plan_tail| {
                    try pending.append(allocator, .{ .pair = .{ .target = target_tail, .plan = plan_tail } });
                }
            }
        },
        .empty_tag_union,
        .tag_union,
        => {
            const target_union = tagUnionParts(target_payload) orelse return;
            const plan_union = tagUnionParts(plan_payload) orelse return;
            const target_row = try flattenPlatformRequirementTagRow(allocator, store, target_union.tags, target_union.ext);
            defer target_row.deinit(allocator);
            const plan_row = try flattenPlatformRequirementTagRow(allocator, store, plan_union.tags, plan_union.ext);
            defer plan_row.deinit(allocator);

            for (target_row.tags) |target_tag| {
                const plan_tag = findTag(names, plan_row.tags, target_tag.name) orelse continue;
                const target_args = target_tag.args;
                const plan_args = plan_tag.args;
                if (target_args.len != plan_args.len) continue;
                try appendDispatchSubstitutionPairs(allocator, pending, target_args, plan_args);
            }
            if (target_row.tail) |target_tail| {
                if (plan_row.tail) |plan_tail| {
                    try pending.append(allocator, .{ .pair = .{ .target = target_tail, .plan = plan_tail } });
                }
            }
        },
        .pending, .field_kind, .err, .flex, .rigid, .alias => {},
    }
}

fn appendDispatchSubstitutionPairs(
    allocator: Allocator,
    pending: *std.ArrayListUnmanaged(DispatchSubstitutionItem),
    targets: []const CheckedTypeId,
    plans: []const CheckedTypeId,
) Allocator.Error!void {
    for (targets, plans) |target, plan| {
        try pending.append(allocator, .{ .pair = .{ .target = target, .plan = plan } });
    }
}

fn appendConsistentDispatchTargetSubstitution(
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    conflicts: *collections.DenseMap(CheckedTypeId, void),
    allocator: Allocator,
    formal: CheckedTypeId,
    actual: CheckedTypeId,
) Allocator.Error!void {
    if (conflicts.contains(formal)) return;

    for (formals.items, actuals.items, 0..) |existing_formal, existing_actual, i| {
        if (existing_formal != formal) continue;
        if (existing_actual == actual) return;

        try conflicts.put(formal, {});
        _ = formals.orderedRemove(i);
        _ = actuals.orderedRemove(i);
        return;
    }

    try formals.append(allocator, formal);
    try actuals.append(allocator, actual);
}

fn appendUniqueCheckedTypeSubstitution(
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    allocator: Allocator,
    store: *const CheckedTypeStore,
    formal: CheckedTypeId,
    actual: CheckedTypeId,
) Allocator.Error!void {
    for (formals.items, actuals.items) |existing_formal, existing_actual| {
        if (existing_formal != formal) continue;
        // A store can hold two roots for one type, so a partially rebuilt
        // instantiation can reference one root in one position and another
        // in another. Two ids for one type are one actual, not a conflict;
        // the first is kept. Debug builds check that the two are one type
        // by structure, which reads no key slot: the caller may hold the
        // store's creation lock.
        if (builtin.mode == .debug and existing_actual != actual) {
            var scratch = CheckedTypeStoreView.EqualityScratch.init(allocator);
            defer scratch.deinit();
            if (!try checkedTypeRootSliceEql(.alpha, .named, store.view(), &.{existing_actual}, &.{actual}, &scratch)) {
                checkedArtifactInvariant("checked type substitution mapped one formal to multiple actuals", .{});
            }
        }
        return;
    }
    try formals.append(allocator, formal);
    try actuals.append(allocator, actual);
}

fn validatePlatformBindingRelation(
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    value_use_kind: PlatformRequiredValueUseKind,
    relation: PlatformRequirementRelation,
    binding_index: usize,
) void {
    if (relation.declaration != declaration or relation.requires_idx != requires_idx) {
        base.invariant(
            "checked artifact invariant violated: platform/app binding {d} points at a checked relation for a different requirement",
            .{binding_index},
        );
    }
    if (!std.meta.eql(relation.app_value.artifact.bytes, app_value.artifact.bytes) or
        relation.app_value.pattern != app_value.pattern)
    {
        base.invariant(
            "checked artifact invariant violated: platform/app binding {d} points at a checked relation for a different app value",
            .{binding_index},
        );
    }
    switch (value_use_kind) {
        .const_value => if (relation.value_kind != .const_value) {
            base.invariant(
                "checked artifact invariant violated: platform/app binding {d} has const value use but procedure checked relation",
                .{binding_index},
            );
        },
        .procedure_value => if (relation.value_kind != .procedure_value) {
            base.invariant(
                "checked artifact invariant violated: platform/app binding {d} has procedure value use but const checked relation",
                .{binding_index},
            );
        },
    }
}

fn platformRequiredValueUseWithRelation(
    value_use: PlatformRequiredValueUse,
    relation: PlatformRequirementRelation,
) PlatformRequiredValueUse {
    return switch (value_use) {
        .const_value => |const_use| .{ .const_value = .{
            .const_use = .{
                .const_ref = const_use.const_use.const_ref,
                .requested_source_ty_payload = relation.requested_source_ty_payload,
            },
            .relation_template_closure = const_use.relation_template_closure,
        } },
        .procedure_value => |proc_use| .{ .procedure_value = .{
            .procedure = .{
                .binding = proc_use.procedure.binding,
                .source_fn_ty_payload = relation.requested_source_ty_payload,
                .intrinsic = proc_use.procedure.intrinsic,
                .iterator_procedure = proc_use.procedure.iterator_procedure,
                .runtime_result_provenance = proc_use.procedure.runtime_result_provenance,
            },
            .root_evidence = .{
                .checked_module = relation.app_value.artifact,
                .span = relation.root_evidence,
            },
            .relation_template_closure = proc_use.relation_template_closure,
        } },
    };
}

/// Copy borrowed closure slices directly into the final publication's pool.
fn copyPlatformRequiredValueUse(
    pool: *ClosurePool,
    allocator: Allocator,
    value_use: PlatformRequiredValueUse,
) Allocator.Error!StoredPlatformRequiredValueUse {
    return switch (value_use) {
        .const_value => |const_use| .{
            .const_value = .{
                .const_use = const_use.const_use,
                .relation_template_closure = try pool.appendBorrowed(allocator, const_use.relation_template_closure),
            },
        },
        .procedure_value => |proc_use| .{
            .procedure_value = .{
                .procedure = proc_use.procedure,
                .root_evidence = proc_use.root_evidence,
                .relation_template_closure = try pool.appendBorrowed(allocator, proc_use.relation_template_closure),
            },
        },
    };
}

/// Public `platformRequirementContextKey` function.
pub fn platformRequirementContextKey(artifact: *const CheckedModuleArtifact) Allocator.Error!PlatformRequirementContextKey {
    return PlatformRequirementContextKey.compute(
        artifact.module_identity,
        try artifact.platform_required_declarations.identityHash(&artifact.canonical_names, artifact.typesView()),
    );
}

fn buildPlatformAppRelationFromDeclarations(
    allocator: Allocator,
    module_idx: u32,
    requirement_context: PlatformRequirementContextKey,
    declarations: []const PlatformRequiredDeclaration,
    app_artifact: *const CheckedModuleArtifact,
    resolver: ModuleResolver,
) Allocator.Error!PlatformAppRelation {
    // The relation borrows the app's export closures, which live as long
    // as the app.
    const app_closures = try importedView(app_artifact).exportClosures(resolver);
    // The one read of an app's analyses from its platform: the root
    // evidence of each requirement the app solves.
    const app_root_evidence = try importedView(app_artifact).dispatch().analyses().platformRequirementRootEvidence(importedView(app_artifact).dispatch());
    var relations = std.ArrayList(PlatformRequirementRelationInput).empty;
    errdefer relations.deinit(allocator);
    var bindings = std.ArrayList(PlatformRequiredBindingInput).empty;
    errdefer bindings.deinit(allocator);
    var checked_error_requires = std.ArrayList(u32).empty;
    errdefer checked_error_requires.deinit(allocator);

    const relation_key = PlatformAppRelationKey.compute(app_artifact.key.digest(), requirement_context);

    for (declarations) |declaration| {
        // The checker records successful solutions as exact app value/type
        // facts. A missing row is recorded explicitly as a checked-error
        // requirement so publication stays total without inventing a binding.
        const solution = app_artifact.platform_requirement_solutions.lookupByRequiredIndex(declaration.requires_idx) orelse {
            try checked_error_requires.append(allocator, declaration.requires_idx);
            continue;
        };

        const app_value_ref = TopLevelValueRef{
            .artifact = app_artifact.key.digest(),
            .pattern = solution.pattern,
        };

        const value_kind = solution.value_kind;

        const top_level = app_artifact.top_level_values.lookupByDef(solution.def) orelse {
            checkedArtifactInvariant("platform requirement solution references a def with no published top-level value", .{});
        };
        if (builtin.mode == .debug) {
            std.debug.assert(top_level.pattern == solution.pattern);
        }

        const relation_id: PlatformRequirementRelationId = @fromBackingInt(@intCast(@as(u32, @intCast(relations.items.len))));
        try relations.append(allocator, .{
            .id = relation_id,
            .declaration = declaration.id,
            .requires_idx = declaration.requires_idx,
            .app_value = app_value_ref,
            .value_kind = value_kind,
            .solved_root_app = solution.solved_root,
            .root_evidence = app_root_evidence.spans[solution.source_solution],
            .identity_start = solution.identity_start,
            .identity_len = solution.identity_len,
        });

        try bindings.append(allocator, .{
            .declaration = declaration.id,
            .requires_idx = declaration.requires_idx,
            .app_value = app_value_ref,
            .checked_relation = relation_id,
            .value_use = if (value_kind == .procedure_value) blk: {
                const procedure_binding = switch (top_level.value) {
                    .procedure_binding => |binding| binding,
                    .const_ref => checkedArtifactInvariant("platform requirement solution needs a procedure but the app value is a const", .{}),
                };
                _ = app_artifact.top_level_procedure_bindings.get(procedure_binding);
                const exported_index = exportedProcedureBindingForAppValue(
                    app_artifact.exported_procedure_bindings.view(),
                    top_level,
                );
                const exported_binding = app_artifact.exported_procedure_bindings.bindings[exported_index];
                const template_closure = exportedProcedureBindingClosureForAppValue(app_artifact, app_closures, exported_index);

                break :blk .{ .procedure_value = .{
                    .procedure = platformRequiredProcedureUse(
                        app_artifact.key,
                        app_value_ref,
                        procedure_binding,
                        exported_binding,
                    ),
                    .root_evidence = .{
                        .checked_module = app_artifact.key.digest(),
                        .span = app_root_evidence.spans[solution.source_solution],
                    },
                    .relation_template_closure = template_closure,
                } };
            } else blk: {
                const const_ref = switch (top_level.value) {
                    .const_ref => |ref| ref,
                    .procedure_binding => checkedArtifactInvariant("platform requirement solution needs a const but the app value is a procedure", .{}),
                };
                const template_closure = exportedConstTemplateClosureForAppValue(app_artifact, app_closures, app_value_ref, const_ref);

                break :blk .{ .const_value = .{
                    .const_use = .{
                        .const_ref = const_ref,
                        .requested_source_ty_payload = null,
                    },
                    .relation_template_closure = template_closure,
                } };
            },
        });
    }

    const owned_relations = try relations.toOwnedSlice(allocator);
    errdefer allocator.free(owned_relations);
    const owned_bindings = try bindings.toOwnedSlice(allocator);
    errdefer allocator.free(owned_bindings);
    const owned_checked_errors = try checked_error_requires.toOwnedSlice(allocator);
    errdefer allocator.free(owned_checked_errors);

    return .{
        .key = relation_key,
        .requirement_context = requirement_context,
        .platform_module_idx = module_idx,
        .app_artifact = app_artifact.key.digest(),
        .relations = owned_relations,
        .bindings = owned_bindings,
        .checked_error_requires = owned_checked_errors,
        .identity_solutions_app = app_artifact.platform_requirement_solutions.identity_solutions,
    };
}

/// Copy a pairing session's changed columns. Unchanged columns stay in their
/// immutable module. This allocator must be the session's arena.
fn copyPairingColumns(comptime T: type, source: T, allocator: Allocator) Allocator.Error!T {
    if (comptime @typeInfo(T) == .pointer) {
        const pointer = @typeInfo(T).pointer;
        comptime std.debug.assert(pointer.size == .slice);
        artifact_serialize.assertRelocatablePod(pointer.child);
        const result = try allocator.alignedAlloc(pointer.child, .fromByteUnits(pointer.attrs.@"align" orelse @alignOf(pointer.child)), source.len);
        @memcpy(result, source);
        return result;
    } else if (comptime @typeInfo(T) == .@"struct") {
        if (comptime @hasField(T, "items") and @hasField(T, "capacity")) {
            var result = source;
            result.items = try copyPairingColumns(@TypeOf(source.items), source.items, allocator);
            result.capacity = result.items.len;
            return result;
        } else if (comptime @hasDecl(T, "Serialized")) {
            var result: T = source;
            inline for (@typeInfo(T).@"struct".field_names, @typeInfo(T).@"struct".field_types, @typeInfo(T).@"struct".field_attrs) |field_name, field_type, field_attrs| {
                const transient = comptime blk: {
                    if (@hasDecl(T, "serde_transient_fields")) for (T.serde_transient_fields) |name| {
                        if (pairingFieldNameEql(name, field_name)) break :blk true;
                    };
                    break :blk false;
                };
                if (comptime transient) {
                    @field(result, field_name) = if (field_attrs.defaultValue(field_type)) |value| value else field_type.init(allocator);
                } else if (comptime field_type == Allocator) {
                    @field(result, field_name) = allocator;
                } else if (comptime pairingFieldNameEql(field_name, "serialized")) {
                    @field(result, field_name) = false;
                } else if (comptime pairingFieldNameEql(field_name, "supports_inserts")) {
                    @field(result, field_name) = true;
                } else {
                    @field(result, field_name) = try copyPairingColumns(field_type, @field(source, field_name), allocator);
                }
            }
            return result;
        } else {
            artifact_serialize.assertRelocatablePod(T);
            return source;
        }
    } else {
        artifact_serialize.assertRelocatablePod(T);
        return source;
    }
}

fn pairingFieldNameEql(comptime a: []const u8, comptime b: []const u8) bool {
    if (a.len != b.len) return false;
    for (a, b) |x, y| if (x != y) return false;
    return true;
}

/// Persisted app-specific checked columns. This is an overlay of two exact
/// immutable artifacts, never a replacement for either module's cache entry.
/// Source environments, declarations, and unchanged body and type columns stay
/// owned by the platform. A hit installs the finished view without evaluation.
pub const PlatformPairing = struct {
    /// Comptime fingerprint of `Serialized`'s layout. The compiler's cache
    /// versioning folds it into the platform-pairing cache entry's admission hash.
    // Bump the version for changes to the borrowed-column mask interpretation as
    // well as other semantics not visible in the serialized layout fingerprint.
    pub const SERIALIZED_VERSION_HASH: [32]u8 = artifact_serialize.rootLayoutVersionHash(Serialized, 6);

    pub const Serialized = extern struct {
        relation: [32]u8,
        borrowed_types: u32,
        has_dependent_evaluation: bool,
        checked_types: CheckedTypeStore.Serialized,
        templates: SerializedSlice(CheckedProcedureTemplate),
        pairing_types: PairingTypeColumn.Serialized,
        canonical_names: canonical.CanonicalNameStore.Serialized,
        platform_requirement_relations: PlatformRequirementRelationTable.Serialized,
        platform_required_bindings: PlatformRequiredBindingTable.Serialized,
        resolved_value_refs: ResolvedValueRefTable.Serialized,
        provided_exports: ProvidedExportTable.Serialized,
        entry_wrappers: EntryWrapperTable.Serialized,
        intrinsic_wrappers: IntrinsicWrapperTable.Serialized,
        compile_time_roots: CompileTimeRootTable.Serialized,
        literal_root_payloads: LiteralRootPayloadTable.Serialized,
        const_templates: ConstTemplateTable.Serialized,
        const_store: ConstStore.Serialized,
        exported_const_templates: ExportedConstTemplateTable.Serialized,
        compile_time_debug: CompileTimeDebugStore.Serialized,
        compile_time_root_reads: CompileTimeRootReadTable.Serialized,

        /// Every artifact column is either persisted here, carrying the app
        /// substitution or the composition's evaluation results, or borrowed
        /// unchanged from the exact platform the cache key names.
        pub const root_contract: collections.serde_validation.RootContract = .{
            .Owner = CheckedModuleArtifact,
            .owner_only_fields = &.{
                // Platform identity and source: borrowed from the platform.
                "key",
                "source_hash",
                "module_identity",
                "direct_import_module_keys",
                "dispatch_view_keys",
                "module_env",
                "exports",
                "provides_requires",
                // Recorded as `relation`; the rest is borrowed from the platform.
                "checking_context_identity",
                // Persisted as `templates`; the rest is borrowed.
                "checked_procedure_templates",
                // Pairing-independent checked metadata: borrowed from the platform.
                "evaluation_diagnostics",
                "checked_const_bodies",
                "exported_procedure_templates",
                "exported_procedure_bindings",
                "method_registry",
                "static_dispatch_plans",
                "top_level_procedure_bindings",
                "callable_eval_templates",
                "hosted_procs",
                "hosted_bindings",
                "platform_required_declarations",
                "platform_type_inputs",
                "platform_requirement_solutions",
                "top_level_values",
                "hoisted_constants",
                // Runtime ownership and preparation state, not checked data.
                "evaluation_state",
                "serialized_backing",
                "serialized_backing_is_static",
                "pairing_arena",
                "reopened_arena",
                // Never serialized: each artifact computes its body facts
                // and module analyses on first demand.
                "body_analyses",
                "module_analyses",
            },
            .serialized_only_fields = &.{
                "relation", // `checking_context_identity.platform_app_relation`.
                "borrowed_types", // Which `checked_types` columns are borrowed.
                "has_dependent_evaluation", // Whether the evaluation columns are persisted.
                "templates", // `checked_procedure_templates.templates`.
            },
        };

        pub fn serialize(self: *Serialized, artifact: *const CheckedModuleArtifact, gpa: Allocator, writer: *CompactWriter) Allocator.Error!void {
            std.debug.assert(artifact.pairing_arena != null and artifact.evaluation_state == .finalized);
            self.relation = artifact.checking_context_identity.platform_app_relation.?.bytes;
            self.borrowed_types = artifact.checked_types.borrowed_columns.bits.mask;
            self.has_dependent_evaluation = (try artifact.rootRequests()).compile_time_requests.len != 0;
            var delta = artifact.checked_types;
            const empty_types = CheckedTypeStore{};
            inline for (@typeInfo(CheckedTypeStore.BorrowedColumn).@"enum".field_names) |field_name| {
                const column = @field(CheckedTypeStore.BorrowedColumn, field_name);
                if (artifact.checked_types.borrowed_columns.contains(column)) {
                    @field(delta, field_name) = @field(empty_types, field_name);
                    if (delta.published_counts) |*counts| counts[@backingInt(@field(CheckedTypeStore.BorrowedColumn, field_name))] = 0;
                }
            }
            try self.checked_types.serialize(&delta, gpa, writer);
            try self.templates.serialize(artifact.checked_procedure_templates.templates.items, gpa, writer);
            try self.pairing_types.serialize(&artifact.pairing_types, gpa, writer);
            try self.canonical_names.serialize(&artifact.canonical_names, gpa, writer);
            try self.platform_requirement_relations.serialize(&artifact.platform_requirement_relations, gpa, writer);
            try self.platform_required_bindings.serialize(&artifact.platform_required_bindings, gpa, writer);
            try self.resolved_value_refs.serialize(&artifact.resolved_value_refs, gpa, writer);
            try self.provided_exports.serialize(&artifact.provided_exports, gpa, writer);
            try self.entry_wrappers.serialize(&artifact.entry_wrappers, gpa, writer);
            try self.intrinsic_wrappers.serialize(&artifact.intrinsic_wrappers, gpa, writer);
            const compile_time_roots_empty: CompileTimeRootTable = .{};
            try self.compile_time_roots.serialize(if (self.has_dependent_evaluation) &artifact.compile_time_roots else &compile_time_roots_empty, gpa, writer);
            const literal_root_payloads_empty: LiteralRootPayloadTable = .{};
            try self.literal_root_payloads.serialize(if (self.has_dependent_evaluation) &artifact.literal_root_payloads else &literal_root_payloads_empty, gpa, writer);
            const const_templates_empty: ConstTemplateTable = .{};
            try self.const_templates.serialize(if (self.has_dependent_evaluation) &artifact.const_templates else &const_templates_empty, gpa, writer);
            const const_store_empty = ConstStore.init(gpa);
            try self.const_store.serialize(if (self.has_dependent_evaluation) &artifact.const_store else &const_store_empty, gpa, writer);
            const exported_const_templates_empty: ExportedConstTemplateTable = .{};
            try self.exported_const_templates.serialize(if (self.has_dependent_evaluation) &artifact.exported_const_templates else &exported_const_templates_empty, gpa, writer);
            try self.compile_time_debug.serialize(&artifact.compile_time_debug, gpa, writer);
            const compile_time_root_reads_empty: CompileTimeRootReadTable = .{};
            try self.compile_time_root_reads.serialize(if (self.has_dependent_evaluation) &artifact.compile_time_root_reads else &compile_time_root_reads_empty, gpa, writer);
        }

        pub fn validate(self: *const Serialized, len: usize) error{CorruptArtifact}!void {
            if (len < @sizeOf(Serialized)) return error.CorruptArtifact;
            try artifact_serialize.validateSerialized(Serialized, self, len);
        }

        /// The number of synthesized types the pairing installed over
        /// `platform` holds, which the key slots passed to `install` must
        /// cover.
        pub fn synthesizedTypeCount(self: *const Serialized, platform: *const CheckedModuleArtifact) usize {
            const roots_bit = @backingInt(CheckedTypeStore.BorrowedColumn.roots);
            if (self.borrowed_types & (@as(u32, 1) << roots_bit) != 0) return platform.checked_types.roots.items().len;
            return @intCast(self.checked_types.roots.len);
        }

        /// The arena owns the relocated buffer; the platform outlives this
        /// view. The pairing owns `synthesized_keys`, `body_analyses`
        /// (created over the platform's module) and `module_analyses`
        /// (created over the platform) from here on.
        pub fn install(self: *const Serialized, platform: *const CheckedModuleArtifact, arena: *base.SingleThreadArena, synthesized_keys: *SynthesizedTypeKeys, analyses: *BodyAnalyses, module_analyses: *ModuleAnalyses) CheckedModuleArtifact {
            const address = @intFromPtr(self);
            const allocator = arena.allocator();
            var result = platform.*;
            result.serialized_backing = null;
            result.serialized_backing_is_static = false;
            result.pairing_arena = arena;
            result.evaluation_state = .finalized;
            result.checking_context_identity.platform_app_relation = .{ .bytes = self.relation };
            result.checked_types = self.checked_types.deserialize(address);
            inline for (@typeInfo(CheckedTypeStore.BorrowedColumn).@"enum".field_names) |field_name| {
                const bit = @backingInt(@field(CheckedTypeStore.BorrowedColumn, field_name));
                if (self.borrowed_types & (@as(u32, 1) << bit) != 0) @field(result.checked_types, field_name) = CheckedTypeStore.borrowedColumn(&platform.checked_types, @field(CheckedTypeStore.BorrowedColumn, field_name));
            }
            result.checked_types.markPublished();
            result.checked_types.sealed_env = platform.checked_types.sealed_env;
            result.checked_types.sealed_keys = platform.checked_types.sealed_keys;
            result.checked_types.synthesized_keys = null;
            result.checked_types.attachSynthesizedKeys(synthesized_keys);
            result.checked_procedure_templates.templates = artifact_serialize.arrayListFromSlice(CheckedProcedureTemplate, self.templates.deserialize(address));
            result.pairing_types = self.pairing_types.deserialize(address);
            result.body_analyses = analyses;
            result.module_analyses = module_analyses;
            result.checked_types.capability_source = platform.pairingCapabilitySource();
            result.canonical_names = self.canonical_names.deserialize(address, allocator);
            result.platform_requirement_relations = self.platform_requirement_relations.deserialize(address);
            result.platform_required_bindings = self.platform_required_bindings.deserialize(address);
            result.resolved_value_refs = self.resolved_value_refs.deserialize(address);
            result.provided_exports = self.provided_exports.deserialize(address);
            result.entry_wrappers = self.entry_wrappers.deserialize(address);
            result.intrinsic_wrappers = self.intrinsic_wrappers.deserialize(address);
            if (self.has_dependent_evaluation) result.compile_time_roots = self.compile_time_roots.deserialize(address);
            if (self.has_dependent_evaluation) result.literal_root_payloads = self.literal_root_payloads.deserialize(address);
            if (self.has_dependent_evaluation) result.const_templates = self.const_templates.deserialize(address);
            if (self.has_dependent_evaluation) result.const_store = self.const_store.deserialize(address, allocator);
            if (self.has_dependent_evaluation) result.exported_const_templates = self.exported_const_templates.deserialize(address);
            result.compile_time_debug = self.compile_time_debug.deserialize(address);
            if (self.has_dependent_evaluation) result.compile_time_root_reads = self.compile_time_root_reads.deserialize(address);
            result.finishPublication();
            return result;
        }
    };
};

/// Instantiate only pairing-owned metadata from already checked modules. Both
/// lowering strategies consume this view; neither sees a solver or source map.
pub fn pairCheckedPlatform(
    allocator: Allocator,
    platform: *const CheckedModuleArtifact,
    app: *const CheckedModuleArtifact,
    available_artifacts: []const ImportedModuleView,
) Allocator.Error!CheckedModuleArtifact {
    std.debug.assert(platform.evaluation_state == .finalized);
    std.debug.assert(platform.checking_context_identity.platform_app_relation == null);
    // The pairing reads the platform's capabilities and the types they
    // name, so they exist before the pairing borrows the platform's types.
    const capability_views = CheckedImportViews{ .current_owner = platform.key.digest(), .direct = &.{}, .available = available_artifacts };
    _ = try platform.typesView().interfaceCapabilities(capability_views.resolver());
    _ = try app.typesView().interfaceCapabilities(capability_views.resolver());
    for (available_artifacts) |available| _ = try available.checked_types.interfaceCapabilities(capability_views.resolver());
    const arena = try allocator.create(base.SingleThreadArena);
    arena.* = base.SingleThreadArena.init(allocator);
    errdefer {
        arena.deinit();
        allocator.destroy(arena);
    }
    const session = arena.allocator();
    var result = platform.*;
    result.serialized_backing = null;
    result.serialized_backing_is_static = false;
    result.pairing_arena = arena;
    result.evaluation_state = .prepared;
    result.compile_time_debug = .{};
    result.canonical_names = try platform.canonical_names.clone(session);
    result.checked_types = CheckedTypeStore.borrowForPairing(&platform.checked_types);
    const platform_keys = platform.checked_types.sealed_keys orelse checkedArtifactInvariant("a platform was paired before its key slots were attached", .{});
    result.checked_types.attachSynthesizedKeys(try SynthesizedTypeKeys.create(platform_keys.allocator, platform_keys.io, result.checked_types.roots.items().len));
    errdefer result.checked_types.synthesized_keys.?.destroy();
    // The pairing's own types name its own names while it is built here.
    result.checked_types.key_names = &result.canonical_names;
    const relations = [_]ImportedModuleView{importedView(app)};
    const pairing_views = CheckedImportViews{ .current_owner = platform.key.digest(), .direct = &.{}, .available = available_artifacts, .relations = &relations };
    const relation = try buildPlatformAppRelationFromDeclarations(session, platform.module_identity.module_idx, try platform.platformRequirementContextKey(), platform.platform_required_declarations.declarations, app, pairing_views.resolver());
    result.checking_context_identity.platform_app_relation = relation.key;
    // The pairing's own types outlive the session arena's single-threaded
    // use: consumers create more of them on demand, so they belong to the
    // owner allocator.
    var substitutions = try PlatformRelationTypeSubstitutions.fromRelation(allocator, result.module_identity, &result.canonical_names, &result.checked_types, &result.platform_required_declarations, &result.platform_type_inputs, &relations, relation);
    defer substitutions.deinit(allocator);
    result.platform_requirement_relations = try PlatformRequirementRelationTable.fromRelation(session, allocator, result.module_identity, &result.canonical_names, &result.checked_types, &result.platform_required_declarations, &relations, relation);
    result.platform_required_bindings = try PlatformRequiredBindingTable.fromRelation(session, result.module_identity, &result.canonical_names, result.checked_types.view(), &result.platform_required_declarations, &result.platform_requirement_relations, relation);
    result.resolved_value_refs.records = try session.dupe(ResolvedValueRefRecord, platform.resolved_value_refs.records);
    for (result.resolved_value_refs.records) |*record| {
        if (record.ref == .platform_required_declaration) {
            const required = platform.platform_required_declarations.lookupByDeclarationId(record.ref.platform_required_declaration).?;
            record.ref = categorizeRequiredValueRef(required.requires_idx, &result.platform_required_declarations, &result.platform_required_bindings);
        }
    }
    var type_memo = substitutions.substitutionIn(session);
    defer type_memo.deinit();
    var reaches: ?CheckedTypeSet = if (substitutions.formals.len != 0) try result.checked_types.rootsReachingAny(session, substitutions.formals) else null;
    defer if (reaches) |*set| set.deinit(session);
    if (reaches) |*set| type_memo.independent = set;

    // The pairing reads the platform's bodies with each source type the
    // app's solutions substitute replaced by its image.
    {
        var images = std.ArrayList(PairingTypeImage).empty;
        if (reaches) |*set| {
            var positions = set.bits.iterator(.{});
            while (positions.next()) |position| {
                if (position >= set.source_count) break;
                const own = set.idAt(position);
                const image = try substitutions.specializeRootWithMemo(allocator, &result.checked_types, own, &type_memo);
                if (image != own) try images.append(session, .{ .own = own, .image = image });
            }
        }
        result.pairing_types = .{ .images = try images.toOwnedSlice(session) };
    }

    // A requirement lookup whose binding the app rejected produces no value,
    // and a call of a requirement the binding classifies may become direct.
    {
        const platform_analyses = platform.body_analyses orelse checkedArtifactInvariant("a platform was paired before its body analyses were attached", .{});
        const env = platform.moduleEnvConst();
        const retired = try session.dupe(u64, platform.resolved_value_refs.retired_exprs);
        var direct_targets = std.ArrayList(CallDirectTarget).empty;
        for (platform.resolved_value_refs.call_direct_targets) |entry| try direct_targets.append(session, entry);
        for (result.resolved_value_refs.records) |record| {
            if (record.ref != .platform_required_checked_error) continue;
            if (env.store.getExpr(record.expr) != .e_lookup_required) continue;
            ResolvedValueRefTable.setRetired(retired, record.expr);
        }
        for (platform_analyses.index.node_kinds, 0..) |kind, raw| {
            if (kind != .expr) continue;
            const call_expr: CIR.Expr.Idx = @fromBackingInt(@intCast(raw));
            const data = env.store.getExpr(call_expr);
            if (data != .e_call) continue;
            const ref_id = platform.resolved_value_refs.lookupIdByExpr(data.e_call.func) orelse continue;
            if (platform.resolved_value_refs.records[@backingInt(ref_id)].ref != .platform_required_declaration) continue;
            // The binding supplies the procedure kind that an unpaired
            // requirement cannot classify. Publish the same direct-call
            // decision as a resolved module.
            const target = directProcedureTargetForCall(
                &result.resolved_value_refs,
                data.e_call.func,
                result.key,
                &result.top_level_procedure_bindings,
                &result.callable_eval_templates,
                &.{},
                available_artifacts,
                &relations,
            );
            const index = std.sort.lowerBound(CallDirectTarget, direct_targets.items, call_expr, struct {
                fn order(key: CIR.Expr.Idx, entry: CallDirectTarget) std.math.Order {
                    return std.math.order(@backingInt(key), @backingInt(entry.call));
                }
            }.order);
            const present = index < direct_targets.items.len and direct_targets.items[index].call == call_expr;
            if (target) |resolved| {
                if (present) {
                    direct_targets.items[index].target = resolved;
                } else {
                    try direct_targets.insert(session, index, .{ .call = call_expr, .target = resolved });
                }
            } else if (present) {
                _ = direct_targets.orderedRemove(index);
            }
        }
        result.resolved_value_refs.retired_exprs = retired;
        result.resolved_value_refs.call_direct_targets = try direct_targets.toOwnedSlice(session);
        result.body_analyses = try BodyAnalyses.create(platform_analyses.allocator, platform_analyses.io, env, platform.checked_procedure_templates.promoted);
    }
    errdefer result.body_analyses.?.destroy();
    result.module_analyses = try ModuleAnalyses.create(result.body_analyses.?.allocator, result.body_analyses.?.io, platform);
    errdefer result.module_analyses.?.destroy();
    result.checked_types.capability_source = platform.pairingCapabilitySource();
    result.checked_procedure_templates.templates = try copyPairingColumns(@TypeOf(platform.checked_procedure_templates.templates), platform.checked_procedure_templates.templates, session);
    var copied_entry_wrappers = false;
    var copied_intrinsic_wrappers = false;
    for (result.checked_procedure_templates.templates.items) |*template| {
        const source_root = template.checked_fn_root;
        template.checked_fn_root = try substitutions.specializeRootWithMemo(allocator, &result.checked_types, source_root, &type_memo);
        if (template.checked_fn_root != source_root) {
            template.checked_fn_scheme = try result.checked_types.ensureSchemeForRoot(allocator, template.checked_fn_root);
            switch (template.body) {
                .entry_wrapper => |id| {
                    if (!copied_entry_wrappers) {
                        result.entry_wrappers = try copyPairingColumns(EntryWrapperTable, platform.entry_wrappers, session);
                        copied_entry_wrappers = true;
                    }
                    result.entry_wrappers.wrappers.items[@backingInt(id)].checked_fn_root = template.checked_fn_root;
                },
                .intrinsic_wrapper => |id| {
                    if (!copied_intrinsic_wrappers) {
                        result.intrinsic_wrappers = try copyPairingColumns(IntrinsicWrapperTable, platform.intrinsic_wrappers, session);
                        copied_intrinsic_wrappers = true;
                    }
                    result.intrinsic_wrappers.wrappers.items[@backingInt(id)].checked_fn_root = template.checked_fn_root;
                },
                .literal_root => checkedArtifactInvariant("a literal root's entry wrapper is a row of the template table", .{}),
                .checked_body, .unimplemented => {},
            }
        }
    }
    result.provided_exports = try copyPairingColumns(ProvidedExportTable, platform.provided_exports, session);
    for (result.provided_exports.exports) |*provided| switch (provided.*) {
        inline .procedure, .data => |*value| value.checked_type = try substitutions.specializeRootWithMemo(allocator, &result.checked_types, value.checked_type, &type_memo),
    };
    // The pairing evaluates the compile-time roots its platform withheld
    // until the app binds its requirements, into evaluation columns of its
    // own.
    const pairing_evaluates = for ((try platform.rootRequests()).requests) |request| {
        if (request.abi == .compile_time and request.requires_pairing) break true;
    } else false;
    if (pairing_evaluates) {
        result.compile_time_roots = try copyPairingColumns(CompileTimeRootTable, platform.compile_time_roots, session);
        result.literal_root_payloads = try copyPairingColumns(LiteralRootPayloadTable, platform.literal_root_payloads, session);
        result.const_templates = try copyPairingColumns(ConstTemplateTable, platform.const_templates, session);
        result.exported_const_templates = try copyPairingColumns(ExportedConstTemplateTable, platform.exported_const_templates, session);
        result.const_store = try copyPairingColumns(ConstStore, platform.const_store, session);
    }
    result.checked_types.key_names = null;
    result.checked_types.markPublished();
    result.checked_types.releaseSuperseded(allocator);
    result.canonical_names.markPublished();
    result.finishPublication();
    return result;
}

const FlattenedPlatformRequirementRecordRow = struct {
    fields: []const CheckedRecordField,
    tail: ?CheckedTypeId,

    fn deinit(self: @This(), allocator: Allocator) void {
        if (self.fields.len > 0) allocator.free(self.fields);
    }
};

fn flattenPlatformRequirementRecordRow(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    head: CheckedRecordFields,
    ext: ?CheckedTypeId,
) Allocator.Error!FlattenedPlatformRequirementRecordRow {
    var fields = std.ArrayList(CheckedRecordField).empty;
    errdefer fields.deinit(allocator);
    try head.appendTo(allocator, &fields);
    var tail = ext;
    var seen = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer seen.deinit();
    while (tail) |tail_id| {
        if (seen.contains(tail_id)) {
            tail = null;
            break;
        }
        try seen.put(tail_id, {});
        switch (platformRequirementPayload(store, tail_id)) {
            .empty_record => {
                tail = null;
                break;
            },
            .record => |record| {
                try record.fields.appendTo(allocator, &fields);
                tail = record.ext;
            },
            .alias => |alias| tail = alias.backing,
            .pending,
            .field_kind,
            .err,
            .flex,
            .rigid,
            .tuple,
            .nominal,
            .function,
            .tag_union,
            .empty_tag_union,
            => break,
        }
    }
    return .{ .fields = try fields.toOwnedSlice(allocator), .tail = tail };
}

const FlattenedPlatformRequirementTagRow = struct {
    tags: []const CheckedTag,
    tail: ?CheckedTypeId,

    fn deinit(self: @This(), allocator: Allocator) void {
        if (self.tags.len > 0) allocator.free(self.tags);
    }
};

fn flattenPlatformRequirementTagRow(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    head: CheckedTags,
    ext: ?CheckedTypeId,
) Allocator.Error!FlattenedPlatformRequirementTagRow {
    var tags = std.ArrayList(CheckedTag).empty;
    errdefer tags.deinit(allocator);
    try head.appendTo(allocator, &tags);
    var tail = ext;
    var seen = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer seen.deinit();
    while (tail) |tail_id| {
        if (seen.contains(tail_id)) {
            tail = null;
            break;
        }
        try seen.put(tail_id, {});
        switch (platformRequirementPayload(store, tail_id)) {
            .empty_tag_union => {
                tail = null;
                break;
            },
            .tag_union => |tag_union| {
                try tag_union.tags.appendTo(allocator, &tags);
                tail = tag_union.ext;
            },
            .alias => |alias| tail = alias.backing,
            .pending,
            .field_kind,
            .err,
            .flex,
            .rigid,
            .record,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            => break,
        }
    }
    return .{ .tags = try tags.toOwnedSlice(allocator), .tail = tail };
}

fn platformRequirementPayload(store: *const CheckedTypeStore, root: CheckedTypeId) CheckedTypePayload {
    return store.payload(root);
}

const RelationTagUnionParts = struct {
    tags: CheckedTags,
    ext: ?CheckedTypeId,
};

fn tagUnionParts(payload: CheckedTypePayload) ?RelationTagUnionParts {
    return switch (payload) {
        .tag_union => |tag_union| .{ .tags = tag_union.tags, .ext = tag_union.ext },
        .empty_tag_union => .{ .tags = .empty, .ext = null },
        .pending,
        .field_kind,
        .err,
        .flex,
        .rigid,
        .alias,
        .record,
        .tuple,
        .nominal,
        .function,
        .empty_record,
        => null,
    };
}

/// A visited pair of checked type roots, keyed by their raw ids. Used as the
/// cycle guard while walking two structurally-parallel checked types in
/// lock-step (resolved dispatch target substitution collection).
const PlatformRequirementTypePair = struct {
    expected: u32,
    actual: u32,
};

fn checkedTypePayloadIsIdentity(payload: CheckedTypePayload) bool {
    return payload == .flex or payload == .rigid;
}

const RelationRecordParts = struct {
    fields: CheckedRecordFields,
    ext: ?CheckedTypeId,
};

fn recordParts(payload: CheckedTypePayload) ?RelationRecordParts {
    return switch (payload) {
        .record => |record| .{ .fields = record.fields, .ext = record.ext },
        .empty_record => .{ .fields = .empty, .ext = null },
        .pending,
        .field_kind,
        .err,
        .flex,
        .rigid,
        .alias,
        .tuple,
        .nominal,
        .function,
        .tag_union,
        .empty_tag_union,
        => null,
    };
}

fn findRecordField(
    names: *const canonical.CanonicalNameStore,
    fields: []const CheckedRecordField,
    name: canonical.RecordFieldLabelId,
) ?CheckedRecordField {
    for (fields) |field| {
        if (names.recordFieldLabelTextEql(field.name, name)) return field;
    }
    return null;
}

fn findTag(
    names: *const canonical.CanonicalNameStore,
    tags: []const CheckedTag,
    name: canonical.TagLabelId,
) ?CheckedTag {
    for (tags) |tag| {
        if (names.tagLabelTextEql(tag.name, name)) return tag;
    }
    return null;
}

fn exportedProcedureBindingClosureForAppValue(
    app_artifact: *const CheckedModuleArtifact,
    closures: *const ExportClosures,
    binding_index: usize,
) ImportedTemplateClosureView {
    switch (app_artifact.exported_procedure_bindings.bindings[binding_index].body) {
        .direct_template => |direct| {
            if (checkedTemplateFromCallableTemplateForClosure(direct.template)) |template_ref| {
                return exportedProcedureTemplateClosureForRef(app_artifact, closures, template_ref);
            }
        },
        .callable_eval_template, .checked_error => {},
    }
    return closures.procedureBinding(binding_index);
}

fn exportedProcedureBindingForAppValue(
    bindings: ExportedProcedureBindingView,
    app_value: TopLevelValueEntry,
) usize {
    for (bindings.bindings, 0..) |binding, index| {
        if (binding.binding.def == app_value.def and binding.binding.pattern == app_value.pattern) return index;
    }
    checkedArtifactInvariant("platform-required app procedure was not exported by the app artifact", .{});
}

fn platformRequiredProcedureUse(
    app_artifact: CheckedModuleArtifactKey,
    app_value: TopLevelValueRef,
    procedure_binding: TopLevelProcedureBindingRef,
    exported_binding: ImportedProcedureBindingView,
) ProcedureUseTemplate {
    if (!exported_binding.binding.artifact.eql(app_artifact.digest()) or
        exported_binding.binding.pattern != app_value.pattern)
    {
        checkedArtifactInvariant("platform-required app procedure use disagreed with its exported binding", .{});
    }
    return .{
        .binding = .{ .platform_required = .{
            .artifact = app_artifact.digest(),
            .app_value = app_value,
            .procedure_binding = procedure_binding,
        } },
        .source_fn_ty_payload = null,
        .intrinsic = null,
        .iterator_procedure = exported_binding.iterator_procedure,
        .runtime_result_provenance = exported_binding.runtime_result_provenance,
    };
}

fn exportedProcedureTemplateClosureForRef(
    app_artifact: *const CheckedModuleArtifact,
    closures: *const ExportClosures,
    template_ref: canonical.ProcedureTemplateRef,
) ImportedTemplateClosureView {
    for (app_artifact.exported_procedure_templates.templates, 0..) |template, index| {
        if (canonical.procedureTemplateRefEql(template.template, template_ref)) return closures.procedureTemplate(index);
    }
    checkedArtifactInvariant("platform-required app procedure template was not exported by the app artifact", .{});
}

fn exportedConstTemplateClosureForAppValue(
    app_artifact: *const CheckedModuleArtifact,
    closures: *const ExportClosures,
    app_value: TopLevelValueRef,
    const_ref: ConstRef,
) ImportedTemplateClosureView {
    for (app_artifact.exported_const_templates.templates, 0..) |template, index| {
        if (template.pattern != app_value.pattern) continue;
        if (!constRefEql(template.const_ref, const_ref)) {
            checkedArtifactInvariant("platform-required app const export disagreed with top-level const ref", .{});
        }
        return closures.constTemplate(index);
    }
    checkedArtifactInvariant("platform-required app const was not exported by the app artifact", .{});
}

fn topLevelDefSourceName(
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    def: TypedCIR.Def,
) Allocator.Error!?canonical.ExportNameId {
    const ident = topLevelDefSourceIdent(def) orelse return null;
    return try names.internExportIdent(module.identStoreConst(), ident);
}

fn topLevelDefSourceIdent(def: TypedCIR.Def) ?base.Ident.Idx {
    return if (def.pattern.data == .assign) def.pattern.data.assign.ident else null;
}

fn publishProvidesMetadata(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
) Allocator.Error![]ProvidesEntry {
    const module_env = module.moduleEnvConst();
    const source = module_env.provides_entries.items.items;
    var provides = std.ArrayList(ProvidesEntry).empty;
    errdefer provides.deinit(allocator);

    for (source) |entry| {
        const def = entry.local_def orelse continue;
        try provides.append(allocator, .{
            .source_name = try names.internExportIdent(module_env.getIdentStoreConst(), entry.ident),
            .ffi_symbol = try names.internExternalSymbolName(module_env.getString(entry.ffi_symbol)),
            .def = def,
        });
    }

    return provides.toOwnedSlice(allocator);
}

fn publishRequiresMetadata(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    publication: *const CheckedTypePublication,
) Allocator.Error![]RequiresEntry {
    const source = module.requiresTypes();
    const requires = try allocator.alloc(RequiresEntry, source.len);
    errdefer allocator.free(requires);

    for (source, 0..) |entry, i| {
        requires[i] = .{
            .platform_name = try names.internExportIdent(module.identStoreConst(), entry.ident),
            .declared_source_ty = publication.schemeForSourceVar(module, ModuleEnv.varFrom(entry.type_anno)),
        };
    }

    return requires;
}

/// Public `BoxPayloadCapabilityId` declaration.
pub const BoxPayloadCapabilityId = enum(u32) { _ };
/// Public `OpaqueAtomicProofId` declaration.
pub const OpaqueAtomicProofId = enum(u32) { _ };

/// Public `BoxPayloadCapabilityEntry` declaration.
pub const BoxPayloadCapabilityEntry = struct {
    id: BoxPayloadCapabilityId,
    nominal: canonical.NominalTypeKey,
    source_ty_payload: CheckedTypeId,
    backing_ty: CheckedTypeId,
    /// Range into `ModuleInterfaceCapabilities.padding_pool` for this instance's
    /// unnamed padding field types, instantiated with its type arguments (in
    /// declared order). Empty for nominals with no unnamed fields.
    padding_start: u32 = 0,
    padding_len: u32 = 0,
    is_opaque: bool,

    /// This entry's instantiated padding field types within `caps.padding_pool`.
    pub fn paddingFieldTys(self: BoxPayloadCapabilityEntry, caps: *const ModuleInterfaceCapabilities) []const CheckedTypeId {
        return caps.padding_pool[self.padding_start .. self.padding_start + self.padding_len];
    }
};

/// Public `OpaqueAtomicProofEntry` declaration.
pub const OpaqueAtomicProofEntry = struct {
    id: OpaqueAtomicProofId,
    nominal: canonical.NominalTypeKey,
    source_ty_payload: CheckedTypeId,
};

/// The box payload capability representation one local nominal type of the
/// module was given.
pub const CapabilityRepresentationRow = struct {
    ty: CheckedTypeId,
    representation: CheckedNominalRepresentationRef,

    fn lessThan(_: void, left: CapabilityRepresentationRow, right: CapabilityRepresentationRow) bool {
        return @backingInt(left.ty) < @backingInt(right.ty);
    }
};

/// The box payload capabilities of one module's local nominal types: every
/// local nominal source type checking reached and every local nominal
/// synthesized type the module held when it was published. Computed on first
/// demand into a slot of the module's analyses (`ModuleAnalyses`); a
/// consumer that reads nominal representations of a module's types demands
/// them first (`CheckedTypeStoreView.interfaceCapabilities`), and reads of
/// those types then carry them.
pub const ModuleInterfaceCapabilities = struct {
    boxed_payload_templates: []const BoxPayloadCapabilityEntry = &.{},
    opaque_atomic_proofs: []const OpaqueAtomicProofEntry = &.{},
    /// Shared flat pool of instantiated padding field types referenced by box
    /// entries' `(padding_start, padding_len)` ranges.
    padding_pool: []const CheckedTypeId = &.{},
    /// Sorted by type id.
    representations: []const CapabilityRepresentationRow = &.{},

    /// Compute the capabilities of `store`'s local nominal types, creating
    /// the instantiated backing and padding types they name. The caller
    /// holds the store's creation (`CheckedTypeStore.beginCreation`) when
    /// other threads may read it.
    pub fn compute(
        allocator: Allocator,
        checked_types: *CheckedTypeStore,
        current_module: canonical.ModuleIdentityId,
        module: ModuleId,
        resolver: ModuleResolver,
    ) Allocator.Error!ModuleInterfaceCapabilities {
        var boxed_payload_templates = std.ArrayList(BoxPayloadCapabilityEntry).empty;
        errdefer boxed_payload_templates.deinit(allocator);
        var opaque_atomic_proofs = std.ArrayList(OpaqueAtomicProofEntry).empty;
        errdefer opaque_atomic_proofs.deinit(allocator);
        // Shared pool of instantiated padding field types; box entries reference ranges.
        var padding_pool = std.ArrayList(CheckedTypeId).empty;
        errdefer padding_pool.deinit(allocator);
        var representations = std.ArrayList(CapabilityRepresentationRow).empty;
        errdefer representations.deinit(allocator);

        var seen_nominals = std.HashMap(NominalCapabilitySeenKey, CheckedNominalRepresentationRef, NominalCapabilitySeenKey.Context, std.hash_map.default_max_load_percentage).init(allocator);
        defer seen_nominals.deinit();
        var seen_args_arena = base.SingleThreadArena.init(allocator);
        defer seen_args_arena.deinit();
        const seen_args = seen_args_arena.allocator();

        // Every local nominal type the module held when it was published:
        // its synthesized entries, then the source types checking reached,
        // in variable order.
        const published = checked_types.published_counts orelse
            checkedArtifactInvariant("interface capabilities were computed for a store that was never published", .{});
        const synthesized_count = published[@backingInt(CheckedTypeStore.BorrowedColumn.payloads)];
        var nominal_types = std.ArrayList(CheckedTypeId).empty;
        defer nominal_types.deinit(allocator);
        for (0..synthesized_count) |index| try nominal_types.append(allocator, type_ids.fromSynthesized(index));
        for (checked_types.sealed_var_facts.items, 0..) |var_facts, raw| {
            if (var_facts.reached) try nominal_types.append(allocator, type_ids.fromVar(@fromBackingInt(@intCast(raw))));
        }

        for (nominal_types.items) |nominal_ty| {
            const payload = checked_types.payload(nominal_ty);
            if (payload != .nominal) continue;
            const nominal = payload.nominal;
            if (nominal.builtin != null) continue;
            if (nominal.origin_module != current_module) continue;
            const nominal_key = checkedNominalTypeKey(nominal);
            // nominal.args aliases type_id_pool; copy before any pool growth.
            const nominal_args = try allocator.dupe(CheckedTypeId, nominal.args);
            defer allocator.free(nominal_args);
            // Roots naming one declaration over the same argument ids are
            // one instance and share its capability; an identity-free
            // instance is one type whichever root names it, while a type
            // with variables keeps its own declaration representation.
            const seen = try seen_nominals.getOrPut(.{ .nominal = nominal_key, .args = nominal_args });
            if (seen.found_existing) {
                if (!try checked_types.rootContainsIdentityVariables(nominal_ty)) try representations.append(allocator, .{ .ty = nominal_ty, .representation = seen.value_ptr.* });
                continue;
            }
            errdefer _ = seen_nominals.remove(.{ .nominal = nominal_key, .args = nominal_args });
            seen.key_ptr.args = try seen_args.dupe(CheckedTypeId, nominal_args);

            const declaration = checked_types.nominalDeclaration(nominal_key) orelse {
                checkedArtifactInvariant("nominal representation publication could not find the checked nominal declaration", .{});
            };
            const backing_ty = try checked_types.ensureInstantiatedNominalBackingRoot(
                allocator,
                declaration,
                nominal_args,
            );
            const padding_field_tys = try checked_types.ensureInstantiatedPaddingFieldTypes(
                allocator,
                declaration,
                nominal_args,
            );
            defer allocator.free(padding_field_tys);
            const padding_start: u32 = @intCast(padding_pool.items.len);
            const padding_len: u32 = @intCast(padding_field_tys.len);
            try padding_pool.appendSlice(allocator, padding_field_tys);

            const capability_id: BoxPayloadCapabilityId = @fromBackingInt(@intCast(@as(u32, @intCast(boxed_payload_templates.items.len))));
            try boxed_payload_templates.append(allocator, .{
                .id = capability_id,
                .nominal = nominal_key,
                .source_ty_payload = nominal_ty,
                .backing_ty = backing_ty,
                .padding_start = padding_start,
                .padding_len = padding_len,
                .is_opaque = nominal.is_opaque,
            });

            const proof_id: ?OpaqueAtomicProofId = blk: {
                if (!nominal.is_opaque) break :blk null;
                if (!try checkedTypeHasNoReachableCallableSlots(allocator, module, checked_types.view(), resolver, backing_ty)) break :blk null;

                const id: OpaqueAtomicProofId = @fromBackingInt(@intCast(@as(u32, @intCast(opaque_atomic_proofs.items.len))));
                try opaque_atomic_proofs.append(allocator, .{
                    .id = id,
                    .nominal = nominal_key,
                    .source_ty_payload = nominal_ty,
                });
                break :blk id;
            };

            const representation: CheckedNominalRepresentationRef = .{ .local_box_payload_capability = .{
                .capability = capability_id,
                .opaque_atomic_proof = proof_id,
            } };
            seen.value_ptr.* = representation;
            try representations.append(allocator, .{ .ty = nominal_ty, .representation = representation });
        }
        std.mem.sort(CapabilityRepresentationRow, representations.items, {}, CapabilityRepresentationRow.lessThan);

        return .{
            .boxed_payload_templates = try boxed_payload_templates.toOwnedSlice(allocator),
            .opaque_atomic_proofs = try opaque_atomic_proofs.toOwnedSlice(allocator),
            .padding_pool = try padding_pool.toOwnedSlice(allocator),
            .representations = try representations.toOwnedSlice(allocator),
        };
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;

    pub fn boxPayloadCapability(
        self: *const ModuleInterfaceCapabilities,
        id: BoxPayloadCapabilityId,
    ) BoxPayloadCapabilityEntry {
        const index: usize = @backingInt(id);
        if (index >= self.boxed_payload_templates.len) {
            checkedArtifactInvariant("interface capability lookup referenced missing boxed payload capability", .{});
        }
        return self.boxed_payload_templates[index];
    }

    /// The box payload capability representation of the local nominal type
    /// `ty`, if it was given one.
    pub fn representationOf(self: *const ModuleInterfaceCapabilities, ty: CheckedTypeId) ?CheckedNominalRepresentationRef {
        const raw: u32 = @backingInt(ty);
        var low: usize = 0;
        var high: usize = self.representations.len;
        while (low < high) {
            const mid = low + (high - low) / 2;
            const row = self.representations[mid];
            if (@backingInt(row.ty) == raw) return row.representation;
            if (@backingInt(row.ty) < raw) low = mid + 1 else high = mid;
        }
        return null;
    }
};

/// A nominal instance by in-workspace identity: its declaration and its
/// argument ids.
const NominalCapabilitySeenKey = struct {
    nominal: canonical.NominalTypeKey,
    args: []const CheckedTypeId,

    const Context = struct {
        pub fn hash(_: Context, key: NominalCapabilitySeenKey) u64 {
            var hasher = std.hash.Wyhash.init(0);
            std.hash.autoHash(&hasher, key.nominal);
            hasher.update(std.mem.sliceAsBytes(key.args));
            return hasher.final();
        }

        pub fn eql(_: Context, left: NominalCapabilitySeenKey, right: NominalCapabilitySeenKey) bool {
            return std.meta.eql(left.nominal, right.nominal) and std.mem.eql(CheckedTypeId, left.args, right.args);
        }
    };
};

fn canonicalNominalTypeKeyEql(a: canonical.NominalTypeKey, b: canonical.NominalTypeKey) bool {
    return a.module == b.module and a.source_decl == b.source_decl;
}

/// Fill a reserved synthetic root with a variable payload and declare it a
/// fresh identity instance, as every non-clone producer of a synthetic
/// variable root must (`reserveDistinctSyntheticTypeRoot`); a test variable
/// left undeclared would trip `identityOrigin` the first time a
/// classification reaches it.
fn testFillSyntheticVariableRoot(
    allocator: Allocator,
    store: *CheckedTypeStore,
    root: CheckedTypeId,
    payload: CheckedTypePayloadBuild,
) Allocator.Error!void {
    if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this

    try store.fillSyntheticTypeRoot(allocator, root, payload);
    try store.declareIdentityInstance(allocator, root);
}

/// The types of a test store whose nominal types name no declaration of
/// another module.
fn testDispatchSubstitutionTypes(store: *CheckedTypeStore, names: *canonical.CanonicalNameStore) DispatchSubstitutionTypes {
    if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this
    const Resolver = struct {
        fn resolveNone(_: *const anyopaque, _: ModuleId) ?ImportedModuleView {
            return null;
        }
    };
    return .{
        .store = store,
        .names = names,
        .module = testCheckedModuleKey(1).digest(),
        .resolver = .{ .context = store, .resolve_fn = Resolver.resolveNone },
    };
}

fn testCheckedModuleKey(byte: u8) CheckedModuleArtifactKey {
    if (!builtin.is_test) unreachable; // test scaffolding: only test blocks call this

    var key = CheckedModuleArtifactKey{};
    key.bytes[0] = byte;
    return key;
}

/// Whether no type reachable from `root` holds a callable. The answer is the
/// conjunction of every reachable type's own verdict, so each is visited once
/// from an explicit work list.
/// A type of one module a walk over checked types has entered
/// (`WalkModules`).
const WalkItem = struct { module: u32, ty: CheckedTypeId };

/// Queues the children of one walked type, which are types of its module.
const WalkChildren = struct {
    allocator: Allocator,
    module: u32,
    pending: *std.ArrayListUnmanaged(WalkItem),

    fn add(self: *WalkChildren, ty: CheckedTypeId) Allocator.Error!void {
        try self.pending.append(self.allocator, .{ .module = self.module, .ty = ty });
    }

    fn addSlice(self: *WalkChildren, tys: []const CheckedTypeId) Allocator.Error!void {
        for (tys) |ty| try self.add(ty);
    }
};

fn checkedTypeHasNoReachableCallableSlots(
    allocator: Allocator,
    module: ModuleId,
    checked_types: CheckedTypeStoreView,
    resolver: ModuleResolver,
    root: CheckedTypeId,
) Allocator.Error!bool {
    var modules = try WalkModules.init(allocator, module, checked_types, resolver);
    defer modules.deinit(allocator);
    var visited = std.AutoHashMap(u64, void).init(allocator);
    defer visited.deinit();
    var pending: std.ArrayListUnmanaged(WalkItem) = .empty;
    defer pending.deinit(allocator);
    try pending.append(allocator, .{ .module = 0, .ty = root });
    while (pending.pop()) |item| {
        if ((try visited.getOrPut(WalkModules.key(item.module, item.ty))).found_existing) continue;
        var children = WalkChildren{ .allocator = allocator, .module = item.module, .pending = &pending };

        switch (modules.typesOf(item.module).payload(item.ty)) {
            .pending => checkedArtifactInvariant("callable-slot proof reached pending checked type", .{}),
            .field_kind, .err => {},
            .flex,
            .rigid,
            .function,
            => return false,
            .empty_record,
            .empty_tag_union,
            => {},
            .alias => |alias| try children.add(alias.backing),
            .nominal => |nominal| {
                if (nominal.builtin) |builtin_nominal| {
                    switch (builtin_nominal) {
                        .str,
                        .u8,
                        .i8,
                        .u16,
                        .i16,
                        .u32,
                        .i32,
                        .u64,
                        .i64,
                        .u128,
                        .i128,
                        .f32,
                        .f64,
                        .dec,
                        .u8x16,
                        .i8x16,
                        .u16x8,
                        .i16x8,
                        .u32x4,
                        .i32x4,
                        .u64x2,
                        .i64x2,
                        .bool,
                        .parse_tag_union_spec,
                        .fields,
                        .field,
                        .crypto_sha256_digest,
                        .crypto_sha256_hasher,
                        .crypto_blake3_digest,
                        .crypto_blake3_hasher,
                        => {},
                        .list,
                        .box,
                        => {
                            if (nominal.args.len != 1) checkedArtifactInvariant("builtin container nominal had non-unary args", .{});
                            try children.add(nominal.args[0]);
                        },
                        .try_ => {
                            if (nominal.args.len != 2) checkedArtifactInvariant("builtin Try nominal had non-binary args", .{});
                            try children.addSlice(nominal.args[0..2]);
                        },
                        .set => {
                            if (nominal.args.len != 1) checkedArtifactInvariant("builtin Set nominal had non-unary args", .{});
                            try children.add(nominal.args[0]);
                        },
                        .dict => {
                            if (nominal.args.len != 2) checkedArtifactInvariant("builtin Dict nominal had non-binary args", .{});
                            try children.addSlice(nominal.args[0..2]);
                        },
                        .iter, .stream => {
                            if (try modules.declaration(allocator, item.module, nominal)) |site| {
                                try pending.append(allocator, .{ .module = site.module, .ty = site.declaration.backing });
                            }
                        },
                    }
                    continue;
                }
                if (try modules.declaration(allocator, item.module, nominal)) |site| {
                    try pending.append(allocator, .{ .module = site.module, .ty = site.declaration.backing });
                }
            },
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    try children.add(field.ty);
                }
                try children.add(record.ext);
            },
            .tuple => |items| try children.addSlice(items),
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    try children.addSlice(tag.args);
                }
                try children.add(tag_union.ext);
            },
        }
    }
    return true;
}

/// Public `ComptimeRootId` declaration.
pub const ComptimeRootId = checked_ids.ComptimeRootId;

/// Public `CompileTimeRootKind` declaration.
pub const CompileTimeRootKind = enum {
    /// Ordinary top-level value constant.
    constant,
    /// A selected top-level-equivalent expression inside a runtime body.
    hoisted_constant,
    /// A compile-time-known refutable destructure whose successful unit result
    /// has no runtime value to archive.
    hoisted_validation,
    callable_binding,
    expect,
    /// A `from_numeral` conversion of a numeric literal whose target is a
    /// non-builtin nominal type. The root body evaluates the dispatch call's
    /// `Try` result and returns its validated `Ok` payload. `Err` becomes a
    /// literal rejection terminal, reported as a checking problem.
    numeral_conversion,
    /// A `from_quote` conversion of a string literal whose target is a
    /// non-builtin nominal type; works exactly like `numeral_conversion` with
    /// `Err(BadQuotedBytes(..))` reported as the checking problem.
    quote_conversion,
    /// One explicitly requested REPL expression body whose inspected `Str`
    /// result is evaluated during checking finalization but is not installed
    /// as a source-visible top-level constant.
    repl_expr,
    /// The conversion of a literal inside a generic function at the concrete
    /// type one of this module's instantiations fixes the literal's type to
    /// (design.md "Literal Arguments"): the first place the literal's type
    /// is concrete. The root's body is the conversion the instantiation's
    /// evidence selected, called on the literal, with its `Try` result's
    /// `Ok` payload the root's value and an `Err` the literal's rejection.
    /// `CompileTimeRoot.literal_argument` names the literal and the edge.
    literal_argument,
};

/// A literal in a generic body whose conversion depends on the body's
/// instantiation (design.md "Literal Arguments").
pub const LiteralSite = struct {
    /// The checked module holding the literal.
    module: CheckedModuleDigest,
    /// The literal's CIR node in that module: a literal expression, or a
    /// custom literal pattern whose literal converts at the pattern's type.
    node: u32,
    kind: LiteralArgumentKind,

    pub fn eql(a: LiteralSite, b: LiteralSite) bool {
        return a.module.eql(b.module) and a.node == b.node and a.kind == b.kind;
    }

    /// Whether the literal's converted value is passed at runtime: an
    /// interpolation's conversion is validated at compile time only, and the
    /// body converts it through its dictionary.
    pub fn carriesValue(self: LiteralSite) bool {
        return switch (self.kind) {
            .numeral, .quote => true,
            .interpolation => false,
        };
    }
};

/// The conversion a literal argument's literal dispatches.
pub const LiteralArgumentKind = enum(u8) {
    numeral,
    quote,
    interpolation,
};

/// One instantiation edge of a scheme inside a body: a dispatch edge (the
/// evidence node whose target the edge instantiates) or a use of a procedure
/// or of a generalized local function (the use expression; for a local
/// function whose scheme its construction fixes, the function expression).
/// `literal` marks an literal requirement's own literal: no edge, the literal is in
/// the scope's body.
pub const LiteralEdge = union(enum(u8)) {
    literal,
    node: static_dispatch.EvidenceNodeId,
    use: CIR.Expr.Idx,
};

/// One literal a scheme's instantiation must convert: a literal of the
/// scheme's own body (`edge == .literal`), or literal requirement `callee_requirement`
/// of the scheme the body's `edge` instantiates. A specialization of the
/// scheme receives each literal requirement whose literal carries a value
/// (`LiteralSite.carriesValue`) as a hidden argument, in literal requirement order
/// after its dictionaries: the address of the converted value, or null
/// where the value is not stored and the body converts through its
/// dictionary.
pub const LiteralRequirement = struct {
    site: LiteralSite,
    /// The literal's type in this scheme's module, over the scheme's
    /// variables and its enclosing scopes'.
    ty: CheckedTypeId,
    edge: LiteralEdge,
    callee_requirement: u32,
};

/// Where an edge's hidden literal argument comes from: a `literal_argument`
/// root of the edge's module (its converted value) or an literal requirement of the
/// scope the edge is in (that scope's own hidden argument).
pub const LiteralArgSource = union(enum(u8)) {
    root: ComptimeRootId,
    forwarded: u32,
    /// The instantiated literal's type mentions a variable that no scheme
    /// around the edge quantifies: a use's copy of a variable nothing relates
    /// to the program, such as `_ = local` taking a generalized local function
    /// that nothing calls. No use fixes that variable, so nothing reads the
    /// argument.
    unbound,
};

/// What a `literal_argument` root converts: the literal requirement
/// `callee_requirement` of the scheme this module's `edge` instantiates, at
/// the closed type `ty`. A validate-only root (its value is an interpolation
/// assembler, or holds a function) is evaluated for its outcome and stores
/// no value; its wrapper, called at runtime, converts the literal.
pub const LiteralArgumentRoot = struct {
    site: LiteralSite,
    ty: CheckedTypeId,
    edge: LiteralEdge,
    callee_requirement: u32,
    validate_only: bool,
};

/// The two literal-conversion root kinds, as a payload-free classification
/// (design.md "Defaulted Fields": a defaulted field's conversion literal
/// gets an ordinary conversion root in its declaring module; there is no
/// separate field-default root kind).
pub const CompileTimeLiteralConversionKind = enum(u8) {
    numeral,
    quote,
};

/// Public `CompileTimeRootPayload` declaration.
pub const CompileTimeRootPayload = union(enum) {
    pending,
    /// A requested root that no compilation finalizing this artifact demanded
    /// (design.md "Demand-Driven Compile-Time Evaluation"). Its value was
    /// never computed; a later compilation that demands it evaluates it
    /// against this same checked artifact, through the same declared root
    /// function an uncached compilation uses.
    unevaluated,
    const_node: ConstNodeId,
    fn_value: ConstFnId,
    discarded,
    expect,
    /// A guarded hoisted root whose compile-time evaluation failed. Runtime
    /// lowering evaluates its original expression and declaration in place.
    runtime,
};

/// Whether a selected compile-time root may become a root request.
pub const CompileTimeRootRequestEligibility = enum(u8) {
    pending,
    eligible,
    ineligible,
};

/// Public `CompileTimeRoot` declaration.
pub const CompileTimeRoot = struct {
    id: ComptimeRootId,
    module_idx: u32,
    kind: CompileTimeRootKind,
    source: RootSource,
    source_pattern: ?CIR.Pattern.Idx = null,
    /// A selected hoisted root's body. A pattern body is a construct
    /// lowering builds from this description: a crash for a rejected
    /// destructure binder, or a match of the base expression against the
    /// pattern that yields the bound value or unit.
    hoisted_body: ?hoist_roots.Body = null,
    pattern: ?CIR.Pattern.Idx,
    /// The root's expression: the evaluated expression or a hoisted pattern
    /// root's selected expression. A literal conversion root has none: it
    /// converts the literal its `source` names (`literalNode`).
    expr: ?CIR.Expr.Idx,
    checked_type: CheckedTypeId,
    request_eligibility: CompileTimeRootRequestEligibility,
    payload: CompileTimeRootPayload,
    /// A hoisted root reached only through a branch, guard, loop body, or
    /// expect body. Its evaluation failure is not a diagnostic; finalization
    /// records the `runtime` payload instead.
    guarded: bool = false,
    /// For a `literal_argument` root: what it converts.
    literal_argument: ?LiteralArgumentRoot = null,
    /// The value a `.boxy` compilation stored for a root holding a function
    /// value (design.md "Stored Function Values"). Only `.boxy` programs read
    /// it: to a `.lss` compilation the root stays `unevaluated`.
    boxy_value: ?StoredConstTemplate = null,

    /// The expression the root evaluates itself, or null when its entry
    /// evaluates a lowering-side construct instead: the one its
    /// `hoisted_body` describes for a hoisted pattern root (a crash for a
    /// rejected destructure binder, or a match of its base expression against
    /// its pattern), or a literal conversion root's conversion of its literal
    /// (`literalNode`).
    pub fn evaluatedExpr(self: CompileTimeRoot) ?CIR.Expr.Idx {
        if (self.literalNode() != null) return null;
        const body = self.hoisted_body orelse return self.rootExpr();
        return switch (body) {
            .expr, .valueless_binding => self.rootExpr(),
            .pattern_error, .pattern_extraction, .pattern_validation => null,
        };
    }

    /// The body nodes the root evaluates: its expression and, for a hoisted
    /// pattern root, the pattern it matches the base expression against; for
    /// a literal conversion root, the literal it converts.
    pub fn bodyParts(self: CompileTimeRoot) RootBodyParts {
        if (self.literalNode()) |literal| return .{ .literal = literal };
        const body = self.hoisted_body orelse return .{ .expr = self.rootExpr() };
        return switch (body) {
            .expr, .valueless_binding => .{ .expr = self.rootExpr() },
            .pattern_error => .{},
            .pattern_extraction => |extraction| .{ .expr = extraction.base_expr, .pattern = extraction.scrutinee_pattern },
            .pattern_validation => |validation| .{ .expr = validation.base_expr, .pattern = validation.scrutinee_pattern },
        };
    }

    /// The literal a literal conversion root converts, or null for every
    /// other root.
    pub fn literalNode(self: CompileTimeRoot) ?LiteralNode {
        return switch (self.source) {
            .literal => |literal| literal,
            .def, .expr, .statement, .required_binding, .hoisted => null,
        };
    }

    /// The expression a root other than a literal conversion root evaluates
    /// or selects.
    pub fn rootExpr(self: CompileTimeRoot) CIR.Expr.Idx {
        return self.expr orelse checkedArtifactInvariant("a literal conversion root was read as an expression root", .{});
    }

    pub fn literalConversionKind(self: CompileTimeRoot) ?CompileTimeLiteralConversionKind {
        return switch (self.kind) {
            .numeral_conversion => .numeral,
            .quote_conversion => .quote,
            .constant, .hoisted_constant, .hoisted_validation, .callable_binding, .expect, .repl_expr, .literal_argument => null,
        };
    }
};

/// The body nodes a compile-time root evaluates (`CompileTimeRoot.bodyParts`).
pub const RootBodyParts = struct {
    expr: ?CIR.Expr.Idx = null,
    pattern: ?CIR.Pattern.Idx = null,
    /// A literal conversion root's literal. The root converts the literal's
    /// value as data; it evaluates none of the literal's CIR.
    literal: ?LiteralNode = null,
};

/// Whether a compile-time root's body contains a diagnostic error.
fn rootBodyContainsDiagnosticError(diagnostics: *const body_analyses.NodeBits, root: CompileTimeRoot) bool {
    if (root.hoisted_body) |body| if (body == .pattern_error) return true;
    const parts = root.bodyParts();
    if (parts.expr) |expr| if (diagnostics.isSet(@backingInt(expr))) return true;
    if (parts.pattern) |pattern| if (diagnostics.isSet(@backingInt(pattern))) return true;
    if (parts.literal) |literal| if (diagnostics.isSet(literal.node())) return true;
    return false;
}

/// One literal root's evaluation output.
pub const LiteralRootPayload = struct {
    id: ComptimeRootId,
    payload: CompileTimeRootPayload = .pending,
    /// The value a `.boxy` evaluation stored for the root
    /// (`CompileTimeRoot.boxy_value`).
    boxy_value: ?StoredConstTemplate = null,
};

/// The evaluation output of a module's literal roots, by root id: an entry
/// for every literal root the module's root requests evaluate, made before
/// evaluation fills them (`CheckedModuleArtifact.prepareLiteralRootPayloads`).
pub const LiteralRootPayloadTable = struct {
    entries: []LiteralRootPayload = &.{},

    pub const Serialized = extern struct {
        entries: SerializedSlice(LiteralRootPayload) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(LiteralRootPayloadTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;

    fn find(self: *const LiteralRootPayloadTable, id: ComptimeRootId) ?usize {
        return std.sort.binarySearch(LiteralRootPayload, self.entries, id, struct {
            fn order(key: ComptimeRootId, item: LiteralRootPayload) std.math.Order {
                return std.math.order(@backingInt(key), @backingInt(item.id));
            }
        }.order);
    }

    pub fn get(self: *const LiteralRootPayloadTable, id: ComptimeRootId) ?LiteralRootPayload {
        const index = self.find(id) orelse return null;
        return self.entries[index];
    }

    fn entry(self: *LiteralRootPayloadTable, id: ComptimeRootId) *LiteralRootPayload {
        const index = self.find(id) orelse checkedArtifactInvariant("a literal root no root request evaluates received a payload", .{});
        return &self.entries[index];
    }
};

/// Public `CompileTimeRootTable` declaration.
///
/// This is the durable compile-time root schedule and payload table. It stores
/// root identities and selected root bodies only; it deliberately does not
/// store dependency edges, readiness state, request membership caches, or
/// per-expression/per-pattern hoistability facts. Ordinary top-level roots are
/// published first in canonical order, then sparse selected hoisted roots are
/// appended in checker-selected dependency-first order. Finalization consumes
/// the sorted request stream and validates this order with temporary scratch.
pub const CompileTimeRootTable = struct {
    roots: []CompileTimeRoot = &.{},

    pub const Serialized = extern struct {
        roots: SerializedSlice(CompileTimeRoot) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(CompileTimeRootTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        value_binding_defs: []const CIR.Def.Idx,
        selected_hoisted_roots: []const hoist_roots.SelectedHoistedRoot,
        explicit_roots: []const ExplicitRootRequestInput,
        checked_types: *CheckedTypePublication,
        module_index: *const ModuleIndex,
        procedure_templates: *const CheckedProcedureTemplateTable,
    ) Allocator.Error!CompileTimeRootTable {
        var roots = std.ArrayList(CompileTimeRoot).empty;
        errdefer {
            deinitCompileTimeRootSlice(allocator, roots.items);
            roots.deinit(allocator);
        }

        // Field defaults get no root of their own (design.md "Defaulted
        // Fields"): every construction site that omits a defaulted field
        // lowers the declaring module's archived checked expression at the
        // site's monotype—per-specialization materialization. A default
        // whose literal needs a closed custom conversion gets its ordinary
        // conversion root after dispatch evidence is finalized.
        const module_env = module.moduleEnvConst();

        for (explicit_roots) |explicit| {
            if (explicit.kind != .repl_expr) continue;
            const expr_idx = switch (explicit.source) {
                .expr => |expr| expr,
                .def, .statement, .required_binding, .hoisted, .literal => checkedArtifactInvariant(
                    "compile-time REPL root did not name its checked expression body",
                    .{},
                ),
            };
            try appendCompileTimeRoot(&roots, allocator, .{
                .module_idx = module.moduleIndex(),
                .kind = .repl_expr,
                .source = explicit.source,
                .pattern = null,
                .expr = reachedRootExpr(module_index, expr_idx),
                .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, module.exprType(expr_idx)),
                .payload = .pending,
            });
        }

        for (value_binding_defs) |def_idx| {
            const def = module.def(def_idx);
            if (def.expr.data == .e_derived_method) {
                checkedArtifactInvariant("generated method marker reached compile-time-root publication", .{});
            }
            if (topLevelDefSourceIdent(def) == null) continue;
            if (procedure_templates.lookupByDef(def_idx) != null) continue;
            // An annotation-only declaration has no value to evaluate; its
            // const template already records that the value is missing.
            if (def.expr.data == .e_anno_only) continue;

            const source_ty = module.defType(def_idx);
            if (sourceTypeIsFunction(module, source_ty)) {
                if (def.expr.data == .e_runtime_error) continue;
                try appendCompileTimeRoot(&roots, allocator, .{
                    .module_idx = module.moduleIndex(),
                    .kind = .callable_binding,
                    .source = .{ .def = def_idx },
                    .pattern = reachedRootPattern(module_index, def.pattern.idx),
                    .expr = reachedRootExpr(module_index, def.expr.idx),
                    .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, source_ty),
                    .payload = .pending,
                });
            } else {
                try appendCompileTimeRoot(&roots, allocator, .{
                    .module_idx = module.moduleIndex(),
                    .kind = .constant,
                    .source = .{ .def = def_idx },
                    .pattern = reachedRootPattern(module_index, def.pattern.idx),
                    .expr = reachedRootExpr(module_index, def.expr.idx),
                    .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, source_ty),
                    .payload = .pending,
                });
            }
        }

        for (selected_hoisted_roots, 0..) |selected, selected_index| {
            const source_ty = if (selected.pattern) |pattern|
                ModuleEnv.varFrom(pattern)
            else
                module.exprType(selected.expr);
            const source_is_function = sourceTypeIsFunction(module, source_ty);
            const kind: CompileTimeRootKind = switch (selected.value_kind) {
                .data_constant => if (source_is_function)
                    checkedArtifactInvariant("function-typed selected root was classified as a data constant", .{})
                else
                    .hoisted_constant,
                .callable_binding => if (!source_is_function)
                    checkedArtifactInvariant("non-function selected root was classified as a callable binding", .{})
                else
                    .callable_binding,
                .discarded => .hoisted_validation,
            };
            const checked_root = try selectedHoistedRootBody(allocator, module, checked_types, module_index, selected);
            const hoisted_body = try hoist_roots.cloneBody(allocator, selected.body);
            try appendCompileTimeRoot(&roots, allocator, .{
                .module_idx = module.moduleIndex(),
                .kind = kind,
                .source = .{ .hoisted = .{
                    .index = @intCast(selected_index),
                    .expr = selected.expr,
                } },
                .source_pattern = selected.pattern,
                .hoisted_body = hoisted_body,
                .pattern = checked_root.pattern,
                .expr = checked_root.expr,
                .checked_type = checked_root.checked_type,
                .payload = .pending,
                .guarded = selected.guarded,
            });
        }

        for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
            const stmt = module_env.store.getStatement(statement_idx);
            if (stmt != .s_expect) continue;
            try collectExpectRoot(
                &roots,
                allocator,
                module,
                checked_types,
                module_index,
                statement_idx,
                stmt.s_expect.body,
            );
        }

        try publishCompileTimeRootRequestEligibility(allocator, module, checked_types, roots.items);

        return .{ .roots = try roots.toOwnedSlice(allocator) };
    }

    pub fn lookupIdByPattern(self: *const CompileTimeRootTable, pattern: CIR.Pattern.Idx) ?ComptimeRootId {
        for (self.roots) |entry| {
            if (entry.kind == .hoisted_validation) continue;
            if (entry.pattern != null and entry.pattern.? == pattern) return entry.id;
        }
        return null;
    }

    pub fn validationResolvedByPattern(self: *const CompileTimeRootTable, pattern: CIR.Pattern.Idx) bool {
        for (self.roots) |entry| {
            if (entry.kind != .hoisted_validation or entry.pattern != pattern) continue;
            const body = entry.hoisted_body orelse checkedArtifactInvariant("hoisted validation root had no selected body", .{});
            if (body != .pattern_validation) checkedArtifactInvariant("hoisted validation root had a non-validation body", .{});
            if (!body.pattern_validation.erase_runtime) return false;
            return entry.payload == .discarded;
        }
        return false;
    }

    /// Look up a selected hoisted constant root by its checked source expression.
    pub fn lookupHoistedRootByExpr(self: *const CompileTimeRootTable, expr: CIR.Expr.Idx) ?CompileTimeRoot {
        for (self.roots) |entry| {
            if (entry.kind == .hoisted_constant and entry.expr == expr) return entry;
        }
        return null;
    }

    /// Row `id` of the table. A literal root is no row
    /// (`CheckedModuleArtifact.compileTimeRoot`).
    pub fn root(self: *const CompileTimeRootTable, id: ComptimeRootId) CompileTimeRoot {
        return self.roots[id.index()];
    }

    /// Record the value a `.boxy` evaluation stored for root `id`.
    pub fn fillBoxyValue(self: *CompileTimeRootTable, id: ComptimeRootId, value: StoredConstTemplate) void {
        const index = id.index();
        if (index >= self.roots.len) {
            checkedArtifactInvariant("compile-time root id is out of range", .{});
        }
        self.roots[index].boxy_value = value;
    }

    pub fn fillPayload(
        self: *CompileTimeRootTable,
        id: ComptimeRootId,
        payload: CompileTimeRootPayload,
    ) void {
        const index = id.index();
        if (index >= self.roots.len) {
            checkedArtifactInvariant("compile-time root id is out of range", .{});
        }
        verifyCompileTimeRootPayloadMatchesKind(self.roots[index], payload);
        self.roots[index].payload = payload;
    }

    pub fn deinit(self: *CompileTimeRootTable, allocator: Allocator) void {
        deinitCompileTimeRootSlice(allocator, self.roots);
        allocator.free(self.roots);
        self.* = .{};
    }

    const RootWithoutId = struct {
        module_idx: u32,
        kind: CompileTimeRootKind,
        source: RootSource,
        source_pattern: ?CIR.Pattern.Idx = null,
        hoisted_body: ?hoist_roots.Body = null,
        pattern: ?CIR.Pattern.Idx,
        expr: ?CIR.Expr.Idx,
        checked_type: CheckedTypeId,
        request_eligibility: CompileTimeRootRequestEligibility = .pending,
        payload: CompileTimeRootPayload,
        guarded: bool = false,
        literal_argument: ?LiteralArgumentRoot = null,
    };

    /// Collect one top-level `expect` as a test root. Expects evaluated inside
    /// its body remain inline and are reported by the test observation table.
    fn collectExpectRoot(
        roots: *std.ArrayList(CompileTimeRoot),
        allocator: Allocator,
        module: TypedCIR.Module,
        checked_types: *const CheckedTypePublication,
        module_index: *const ModuleIndex,
        statement_idx: CIR.Statement.Idx,
        body_expr: CIR.Expr.Idx,
    ) Allocator.Error!void {
        try appendCompileTimeRoot(roots, allocator, .{
            .module_idx = module.moduleIndex(),
            .kind = .expect,
            .source = .{ .statement = statement_idx },
            .pattern = null,
            .expr = reachedRootExpr(module_index, body_expr),
            .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, ModuleEnv.varFrom(body_expr)),
            .payload = .expect,
        });
    }

    /// The id `appendCompileTimeRoot` assigns to the next appended root.
    fn nextCompileTimeRootId(roots: []const CompileTimeRoot) ComptimeRootId {
        return @fromBackingInt(@intCast(@as(u32, @intCast(roots.len))));
    }

    fn appendCompileTimeRoot(
        roots: *std.ArrayList(CompileTimeRoot),
        allocator: Allocator,
        entry: RootWithoutId,
    ) Allocator.Error!void {
        const id = nextCompileTimeRootId(roots.items);
        roots.append(allocator, .{
            .id = id,
            .module_idx = entry.module_idx,
            .kind = entry.kind,
            .source = entry.source,
            .source_pattern = entry.source_pattern,
            .hoisted_body = entry.hoisted_body,
            .pattern = entry.pattern,
            .expr = entry.expr,
            .checked_type = entry.checked_type,
            .request_eligibility = entry.request_eligibility,
            .payload = entry.payload,
            .guarded = entry.guarded,
            .literal_argument = entry.literal_argument,
        }) catch |err| {
            if (entry.hoisted_body) |body| hoist_roots.deinitBody(allocator, body);
            return err;
        };
    }
};

/// Request eligibility from each root's solved type. Diagnostic exclusion
/// follows once the body diagnostic facts are published.
fn publishCompileTimeRootRequestEligibility(
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedTypePublication,
    roots: []CompileTimeRoot,
) Allocator.Error!void {
    for (roots) |*root| {
        const producer_callable_type_is_fixed = switch (root.kind) {
            .callable_binding => true,
            .constant => switch (root.source) {
                .def => |def_idx| module.def(def_idx).data.annotation != null,
                .expr, .statement, .hoisted, .required_binding, .literal => false,
            },
            .hoisted_constant,
            .hoisted_validation,
            .expect,
            .numeral_conversion,
            .quote_conversion,
            .repl_expr,
            .literal_argument,
            => false,
        };
        const context_free = try checkedTypeIsContextFreeCompileTimeRoot(
            allocator,
            checked_types.imports.current_owner,
            checked_types.store.view(),
            checked_types.imports.resolver(),
            producer_callable_type_is_fixed,
            root.checked_type,
        );
        root.request_eligibility = if (context_free) .eligible else .ineligible;
    }
}

/// How much of one quantified variable a procedure template's body demands
/// (design.md "Specialization By Demand"). The scale is the same one
/// `LowLevel.elementDemand` places on an operation's arguments.
pub const SchemeVarDemand = base.LowLevel.ElementDemand;

fn maxSchemeVarDemand(left: SchemeVarDemand, right: SchemeVarDemand) SchemeVarDemand {
    return if (@backingInt(left) >= @backingInt(right)) left else right;
}

/// How a checked type reaches one type variable it mentions. Each flag is
/// true when at least one path from the type to the variable has the
/// property, so the flags of several paths combine by `or`.
const TypeVarMentionFlags = packed struct(u8) {
    /// A path passes through a function's argument or result.
    under_function: bool = false,
    /// A path reaches the variable without passing through the element of a
    /// `List` or `Box`.
    outside_container: bool = false,
    /// The variable is the extension of a record or tag-union row.
    row_extension: bool = false,
    /// A path passes through an argument of a builtin nominal whose runtime
    /// representation that argument's structure decides, not just its layout:
    /// the field-name tables of `FieldNames`, `FieldName`, and
    /// `ParseTagUnionSpec`, and the iterator representation of `Iter` and
    /// `Stream`.
    decides_representation: bool = false,
    _padding: u4 = 0,

    fn merge(left: TypeVarMentionFlags, right: TypeVarMentionFlags) TypeVarMentionFlags {
        return @bitCast(@as(u8, @bitCast(left)) | @as(u8, @bitCast(right)));
    }
};

/// One type variable a checked type mentions, and how.
const TypeVarMention = struct {
    var_ty: CheckedTypeId,
    flags: TypeVarMentionFlags,
};

/// The type variables each checked type mentions, memoized by type.
const TypeVarMentions = struct {
    allocator: Allocator,
    checked_types: *const CheckedTypeStore,
    memo: collections.DenseMap(CheckedTypeId, artifact_serialize.Span),
    pool: std.ArrayList(TypeVarMention) = .empty,
    /// Walk state of one query: each (type, flags) pair is visited once, so a
    /// cyclic type terminates.
    pending: std.ArrayList(Step) = .empty,
    visited: std.AutoHashMapUnmanaged(Step, void) = .empty,
    found: collections.DenseMap(CheckedTypeId, TypeVarMentionFlags),

    const Step = struct {
        ty: CheckedTypeId,
        flags: TypeVarMentionFlags,
    };

    fn deinit(self: *TypeVarMentions) void {
        self.memo.deinit();
        self.pool.deinit(self.allocator);
        self.pending.deinit(self.allocator);
        self.visited.deinit(self.allocator);
        self.found.deinit();
    }

    /// The variables `root` mentions, in ascending type-id order.
    fn of(self: *TypeVarMentions, root: CheckedTypeId) Allocator.Error![]const TypeVarMention {
        if (self.memo.get(root)) |span| return self.pool.items[span.start .. span.start + span.len];
        self.pending.clearRetainingCapacity();
        self.visited.clearRetainingCapacity();
        self.found.clearRetainingCapacity();
        try self.push(root, .{ .outside_container = true });
        while (self.pending.pop()) |step| try expandStep(self.checked_types, step, self);
        const lessThan = struct {
            fn lessThan(_: void, left: TypeVarMention, right: TypeVarMention) bool {
                return @backingInt(left.var_ty) < @backingInt(right.var_ty);
            }
        }.lessThan;
        const start = self.pool.items.len;
        try self.pool.ensureUnusedCapacity(self.allocator, self.found.count());
        var it = self.found.iterator();
        while (it.next()) |entry| self.pool.appendAssumeCapacity(.{ .var_ty = entry.key_ptr.*, .flags = entry.value_ptr.* });
        const mentions = self.pool.items[start..];
        std.mem.sort(TypeVarMention, mentions, {}, lessThan);
        try self.memo.put(root, .{ .start = @intCast(start), .len = @intCast(mentions.len) });
        return mentions;
    }

    /// Visit one step of a walk from a type to the variables it mentions:
    /// note the variable it reaches, or push each component with the flags of
    /// the path through it. `sink` provides `push(ty, flags)` and
    /// `noteMention(var_ty, flags)`.
    fn expandStep(checked_types: *const CheckedTypeStore, step: Step, sink: anytype) Allocator.Error!void {
        switch (checked_types.payload(step.ty)) {
            .flex, .rigid => try sink.noteMention(step.ty, step.flags),
            .alias => |alias| try sink.push(alias.backing, step.flags),
            .record => |record| {
                for (0..record.fields.len()) |field_index| {
                    const field = record.fields.get(field_index);
                    try sink.push(field.ty, step.flags);
                }
                try expandRowExtension(checked_types, record.ext, step.flags, sink);
            },
            .tuple => |elems| for (elems) |elem| try sink.push(elem, step.flags),
            .nominal => |nominal| {
                var arg_flags = step.flags;
                if (nominal.builtin) |builtin_nominal| switch (builtin_nominal) {
                    .list, .box => arg_flags.outside_container = false,
                    .fields, .field, .parse_tag_union_spec, .iter, .stream => arg_flags.decides_representation = true,
                    .bool, .try_, .str, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .dict, .set, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher => {},
                };
                for (nominal.args) |arg| try sink.push(arg, arg_flags);
                for (nominal.padding_field_types) |padding| try sink.push(padding, step.flags);
            },
            .function => |function| {
                var inner = step.flags;
                inner.under_function = true;
                for (function.args) |arg| try sink.push(arg, inner);
                try sink.push(function.ret, inner);
            },
            .tag_union => |tag_union| {
                for (0..tag_union.tags.len()) |tag_index| {
                    const tag = tag_union.tags.get(tag_index);
                    for (tag.args) |arg| try sink.push(arg, step.flags);
                }
                try expandRowExtension(checked_types, tag_union.ext, step.flags, sink);
            },
            .empty_record, .empty_tag_union, .field_kind, .err, .pending => {},
        }
    }

    fn expandRowExtension(checked_types: *const CheckedTypeStore, ext: CheckedTypeId, flags: TypeVarMentionFlags, sink: anytype) Allocator.Error!void {
        switch (checked_types.payload(ext)) {
            .flex, .rigid => {
                var ext_flags = flags;
                ext_flags.row_extension = true;
                try sink.noteMention(ext, ext_flags);
            },
            .pending, .field_kind, .err, .alias, .record, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => try sink.push(ext, flags),
        }
    }

    fn push(self: *TypeVarMentions, ty: CheckedTypeId, flags: TypeVarMentionFlags) Allocator.Error!void {
        const step: Step = .{ .ty = ty, .flags = flags };
        const entry = try self.visited.getOrPut(self.allocator, step);
        if (entry.found_existing) return;
        try self.pending.append(self.allocator, step);
    }

    fn noteMention(self: *TypeVarMentions, var_ty: CheckedTypeId, flags: TypeVarMentionFlags) Allocator.Error!void {
        const entry = try self.found.getOrPut(var_ty);
        entry.value_ptr.* = if (entry.found_existing) entry.value_ptr.merge(flags) else flags;
    }
};

/// The demand of a caller's `caller_slot` is at least that of `callee_slot`
/// of the template `callee` names.
pub const TemplateDemandEdge = struct {
    caller_slot: u32,
    callee: TemplateDemandCallee,
    callee_slot: u32,
};

/// The callee of a demand edge: a template of the module itself (its raw
/// template id), or a template of a module dispatch resolution reads.
pub const TemplateDemandCallee = union(enum) {
    local: u32,
    imported: canonical.ProcedureTemplateRef,
};

/// One strongly connected component's demand vectors, in the component's
/// member order (`TemplateDemandGraph.componentMembers`).
pub const TemplateDemandComponent = struct {
    starts: []const u32,
    demands: []const SchemeVarDemand,

    pub fn member(self: *const TemplateDemandComponent, index: u32) []const SchemeVarDemand {
        return self.demands[self.starts[index]..self.starts[index + 1]];
    }

    pub fn destroy(self: *TemplateDemandComponent, allocator: Allocator) void {
        allocator.free(self.starts);
        allocator.free(self.demands);
        allocator.destroy(self);
    }
};

/// The slot holding one component's demand vectors.
pub const TemplateDemandComponentSlot = collections.OnceSlot(*TemplateDemandComponent, .module_template_demand);

/// A module's demand call graph (`ModuleAnalyses.templateDemandGraph`):
/// every template's demand vector as its own body sets it, the edges along
/// which its callees' demands raise it, and the strongly connected
/// components of the graph the local edges form, numbered callees first.
/// Each component's vectors are a slot of their own.
pub const TemplateDemandGraph = struct {
    /// Template `t`'s vector before propagation:
    /// `bases[base_starts[t]..base_starts[t + 1]]`.
    base_starts: []const u32,
    bases: []const SchemeVarDemand,
    /// Template `t`'s edges: `edges[edge_starts[t]..edge_starts[t + 1]]`.
    edge_starts: []const u32,
    edges: []const TemplateDemandEdge,
    /// Each template's component and its index among the component's members.
    component_of: []const u32,
    member_index: []const u32,
    /// Component `c`'s templates, ascending:
    /// `members[member_starts[c]..member_starts[c + 1]]`.
    member_starts: []const u32,
    members: []const u32,
    /// Component `c`'s local callee components other than itself, each once:
    /// `callees[callee_starts[c]..callee_starts[c + 1]]`.
    callee_starts: []const u32,
    callees: []const u32,
    component_slots: []TemplateDemandComponentSlot,

    pub fn base(self: *const TemplateDemandGraph, template: u32) []const SchemeVarDemand {
        return self.bases[self.base_starts[template]..self.base_starts[template + 1]];
    }

    pub fn templateEdges(self: *const TemplateDemandGraph, template: u32) []const TemplateDemandEdge {
        return self.edges[self.edge_starts[template]..self.edge_starts[template + 1]];
    }

    pub fn componentMembers(self: *const TemplateDemandGraph, component: u32) []const u32 {
        return self.members[self.member_starts[component]..self.member_starts[component + 1]];
    }

    pub fn componentCallees(self: *const TemplateDemandGraph, component: u32) []const u32 {
        return self.callees[self.callee_starts[component]..self.callee_starts[component + 1]];
    }

    pub fn destroy(self: *TemplateDemandGraph, allocator: Allocator) void {
        for (self.component_slots) |*slot| if (slot.peek()) |result| result.destroy(allocator);
        allocator.free(self.component_slots);
        allocator.free(self.base_starts);
        allocator.free(self.bases);
        allocator.free(self.edge_starts);
        allocator.free(self.edges);
        allocator.free(self.component_of);
        allocator.free(self.member_index);
        allocator.free(self.member_starts);
        allocator.free(self.members);
        allocator.free(self.callee_starts);
        allocator.free(self.callees);
        allocator.destroy(self);
    }
};

/// The reader over a module's bodies that its dispatch source describes.
fn dispatchSourceBodies(source: DispatchSource) CheckedBodies {
    var types_view = source.types.store.view();
    types_view.names = source.names;
    return .{
        .env = source.env,
        .names = source.names,
        .types = types_view,
        .analyses = source.body_analyses,
        .tables = .{
            .module = source.key.digest(),
            .plans = source.plans,
            .refs = source.refs,
            .roots = source.compile_time_roots,
            .pairing_types = source.types.pairing,
            .dispatch = .{ .source = source },
        },
    };
}

/// The module's demand call graph: each template's body walked once into
/// its own demand vector and the edges to the templates it calls.
pub fn computeTemplateDemandGraph(allocator: Allocator, dispatch: CheckedDispatch) Allocator.Error!*TemplateDemandGraph {
    const source = dispatch.source;
    var pass = TemplateDemandWalk{
        .allocator = allocator,
        .artifact_key = source.key,
        .checked_types = source.types.store,
        .bodies = dispatchSourceBodies(source),
        .templates = source.templates,
        .resolved_value_refs = source.refs,
        .top_level_procedure_bindings = source.top_level_procedure_bindings,
        .static_dispatch_plans = source.plans,
        .dispatch = dispatch,
        .current_slots = collections.DenseMap(CheckedTypeId, u32).init(allocator),
        .mentions = .{
            .allocator = allocator,
            .checked_types = source.types.store,
            .memo = collections.DenseMap(CheckedTypeId, artifact_serialize.Span).init(allocator),
            .found = collections.DenseMap(CheckedTypeId, TypeVarMentionFlags).init(allocator),
        },
    };
    defer pass.deinit();
    return pass.graph();
}

/// The demand vectors of the templates of component `component` of
/// `graph`: their own vectors raised along their edges to a fixed point.
/// Every callee component and every imported callee's vector is done
/// before the component is claimed (`ModuleAnalyses.templateDemandComponent`).
pub fn computeTemplateDemandComponent(
    allocator: Allocator,
    dispatch: CheckedDispatch,
    graph: *const TemplateDemandGraph,
    component: u32,
) Allocator.Error!*TemplateDemandComponent {
    const members = graph.componentMembers(component);
    const starts = try allocator.alloc(u32, members.len + 1);
    errdefer allocator.free(starts);
    starts[0] = 0;
    for (members, 0..) |template, index| starts[index + 1] = starts[index] + @as(u32, @intCast(graph.base(template).len));
    const demands = try allocator.alloc(SchemeVarDemand, starts[members.len]);
    errdefer allocator.free(demands);
    for (members, 0..) |template, index| @memcpy(demands[starts[index]..starts[index + 1]], graph.base(template));

    // The edges between members, grouped by callee, so a changed member
    // revisits only its callers.
    const by_callee_starts = try allocator.alloc(u32, members.len + 1);
    defer allocator.free(by_callee_starts);
    @memset(by_callee_starts, 0);
    for (members) |template| for (graph.templateEdges(template)) |edge| switch (edge.callee) {
        .local => |callee| if (graph.component_of[callee] == component) {
            by_callee_starts[graph.member_index[callee] + 1] += 1;
        },
        .imported => {},
    };
    for (1..by_callee_starts.len) |index| by_callee_starts[index] += by_callee_starts[index - 1];
    const InnerEdge = struct { caller: u32, edge: TemplateDemandEdge };
    const by_callee = try allocator.alloc(InnerEdge, by_callee_starts[members.len]);
    defer allocator.free(by_callee);
    const cursor = try allocator.dupe(u32, by_callee_starts[0..members.len]);
    defer allocator.free(cursor);

    // Edges to templates outside the component read final vectors; raise
    // along them once.
    for (members, 0..) |template, index| {
        const vector = demands[starts[index]..starts[index + 1]];
        for (graph.templateEdges(template)) |edge| {
            const callee_demand = switch (edge.callee) {
                .local => |callee| blk: {
                    const callee_component = graph.component_of[callee];
                    if (callee_component == component) {
                        const member = graph.member_index[callee];
                        by_callee[cursor[member]] = .{ .caller = @intCast(index), .edge = edge };
                        cursor[member] += 1;
                        continue;
                    }
                    const done = graph.component_slots[callee_component].peek() orelse
                        checkedArtifactInvariant("a demand component was computed before its callee component", .{});
                    break :blk done.member(graph.member_index[callee])[edge.callee_slot];
                },
                .imported => |callee| (try importedTemplateDemands(dispatch, callee))[edge.callee_slot],
            };
            vector[edge.caller_slot] = maxSchemeVarDemand(vector[edge.caller_slot], callee_demand);
        }
    }

    // Edges between members, to a fixed point. Demands only rise and each
    // has three values, so every caller slot changes at most twice.
    var queued = try std.DynamicBitSetUnmanaged.initFull(allocator, members.len);
    defer queued.deinit(allocator);
    var pending: std.ArrayList(u32) = .empty;
    defer pending.deinit(allocator);
    try pending.ensureTotalCapacity(allocator, members.len);
    for (0..members.len) |index| pending.appendAssumeCapacity(@intCast(members.len - 1 - index));
    while (pending.pop()) |callee| {
        queued.unset(callee);
        for (by_callee[by_callee_starts[callee]..by_callee_starts[callee + 1]]) |inner| {
            const demand = demands[starts[callee] + inner.edge.callee_slot];
            const caller_demand = &demands[starts[inner.caller] + inner.edge.caller_slot];
            const raised = maxSchemeVarDemand(caller_demand.*, demand);
            if (raised == caller_demand.*) continue;
            caller_demand.* = raised;
            if (!queued.isSet(inner.caller)) {
                queued.set(inner.caller);
                try pending.append(allocator, inner.caller);
            }
        }
    }

    const result = try allocator.create(TemplateDemandComponent);
    result.* = .{ .starts = starts, .demands = demands };
    return result;
}

/// The demand vector of a template of a module dispatch resolution reads.
pub fn importedTemplateDemands(dispatch: CheckedDispatch, callee: canonical.ProcedureTemplateRef) Allocator.Error![]const SchemeVarDemand {
    const view = dispatch.importedView(callee.artifact) orelse
        checkedArtifactInvariant("a demand edge named a module dispatch resolution does not read", .{});
    return view.dispatch().templateDemands(callee.template);
}

/// Walks every local procedure template's body into its own demand vector
/// (for each quantified variable of its scheme, the most its body asks of
/// the type a specialization substitutes for it; design.md "Specialization
/// By Demand") and the edges to the templates it calls
/// (`TemplateDemandGraph`).
const TemplateDemandWalk = struct {
    allocator: Allocator,
    artifact_key: CheckedModuleArtifactKey,
    checked_types: *const CheckedTypeStore,
    bodies: CheckedBodies,
    templates: *const CheckedProcedureTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
    dispatch: CheckedDispatch,

    mentions: TypeVarMentions,
    /// Every template's own vector, at `base_starts`.
    demands: std.ArrayList(SchemeVarDemand) = .empty,
    base_starts: std.ArrayList(u32) = .empty,
    edges: std.ArrayList(TemplateDemandEdge) = .empty,
    edge_starts: std.ArrayList(u32) = .empty,
    work: std.ArrayList(Work) = .empty,
    imported_templates: std.AutoHashMapUnmanaged(ImportedDefKey, ?canonical.ProcedureTemplateRef) = .empty,

    /// Every step a raise has walked in the current template, at the demand
    /// it raised. A raise's effect is a function of its step and demand, and
    /// demands only rise, so a step walked once at a demand never needs
    /// walking again at that demand within the template.
    raised: std.AutoHashMapUnmanaged(RaiseStep, void) = .empty,
    raise_pending: std.ArrayList(RaiseStep) = .empty,

    // The template being walked.
    current: canonical.CheckedProcedureTemplateId = undefined,
    current_vars: []const CheckedTypeId = &.{},
    /// Each quantified variable's slot in `current_vars`.
    current_slots: collections.DenseMap(CheckedTypeId, u32),
    current_demands: []SchemeVarDemand = &.{},

    const ImportedDefKey = struct {
        artifact: ModuleId,
        def: CIR.Def.Idx,
    };

    /// One step of a raise walk: a type reached along a path with `flags`,
    /// raising the variables it mentions to `demand` (and exact mentions to
    /// `full`).
    const RaiseStep = struct {
        step: TypeVarMentions.Step,
        demand: SchemeVarDemand,
    };

    /// The sink `TypeVarMentions.expandStep` drives during a raise walk.
    const RaiseSink = struct {
        pass: *TemplateDemandWalk,
        demand: SchemeVarDemand,

        pub fn push(sink: RaiseSink, ty: CheckedTypeId, flags: TypeVarMentionFlags) Allocator.Error!void {
            try sink.pass.pushRaise(.{ .step = .{ .ty = ty, .flags = flags }, .demand = sink.demand });
        }

        pub fn noteMention(sink: RaiseSink, var_ty: CheckedTypeId, flags: TypeVarMentionFlags) Allocator.Error!void {
            const slot = sink.pass.slotOf(var_ty) orelse return;
            sink.pass.raiseSlot(slot, if (exactMention(flags)) .full else sink.demand);
        }
    };

    /// Where an expression stands relative to the operation that consumes it.
    const ExprRole = enum {
        /// Its value is materialized: held in a local, stored, returned, or
        /// matched on.
        value,
        /// A direct operand of a procedure call or a low-level operation. The
        /// callee's or operation's demand covers the operand, so reading a
        /// local into this position materializes nothing.
        operand,
        /// The callee of a direct template call. The call's edges cover it.
        direct_callee,
    };

    const PatternRole = enum {
        /// A parameter of the template's own lambda. The value already exists
        /// in the caller; binding it materializes nothing.
        parameter,
        binding,
    };

    const Work = union(enum) {
        expr: struct { id: CIR.Expr.Idx, role: ExprRole },
        pattern: struct { id: CIR.Pattern.Idx, role: PatternRole },
        statement: CIR.Statement.Idx,
    };

    fn deinit(self: *TemplateDemandWalk) void {
        self.mentions.deinit();
        self.current_slots.deinit();
        self.raised.deinit(self.allocator);
        self.raise_pending.deinit(self.allocator);
        self.demands.deinit(self.allocator);
        self.base_starts.deinit(self.allocator);
        self.edges.deinit(self.allocator);
        self.edge_starts.deinit(self.allocator);
        self.work.deinit(self.allocator);
        self.imported_templates.deinit(self.allocator);
    }

    fn graph(self: *TemplateDemandWalk) Allocator.Error!*TemplateDemandGraph {
        const allocator = self.allocator;
        const templates = self.templates.templates.items;
        try self.base_starts.ensureTotalCapacity(allocator, templates.len + 1);
        for (0..templates.len) |raw| {
            self.base_starts.appendAssumeCapacity(@intCast(self.demands.items.len));
            const vars = try self.dispatch.templateSchemeVars(@fromBackingInt(@intCast(raw)));
            try self.demands.appendNTimes(allocator, .none, vars.len);
        }
        self.base_starts.appendAssumeCapacity(@intCast(self.demands.items.len));
        try self.edge_starts.ensureTotalCapacity(allocator, templates.len + 1);
        for (templates, 0..) |*template, raw| {
            self.edge_starts.appendAssumeCapacity(@intCast(self.edges.items.len));
            self.current = @fromBackingInt(@intCast(raw));
            self.current_vars = try self.dispatch.templateSchemeVars(self.current);
            self.current_slots.clearRetainingCapacity();
            for (self.current_vars, 0..) |var_ty, slot| try self.current_slots.put(var_ty, @intCast(slot));
            self.raised.clearRetainingCapacity();
            self.current_demands = self.demands.items[self.base_starts.items[raw]..self.base_starts.items[raw + 1]];
            try self.analyzeTemplate(template);
        }
        self.edge_starts.appendAssumeCapacity(@intCast(self.edges.items.len));
        return self.components();
    }

    /// The strongly connected components of the local edges (Tarjan's
    /// algorithm, iteratively), numbered as they complete, so every
    /// component's callee components precede it.
    fn components(self: *TemplateDemandWalk) Allocator.Error!*TemplateDemandGraph {
        const allocator = self.allocator;
        const count = self.edge_starts.items.len - 1;
        const unvisited = std.math.maxInt(u32);
        const order = try allocator.alloc(u32, count);
        defer allocator.free(order);
        @memset(order, unvisited);
        const low = try allocator.alloc(u32, count);
        defer allocator.free(low);
        var on_stack = try std.DynamicBitSetUnmanaged.initEmpty(allocator, count);
        defer on_stack.deinit(allocator);
        var stack: std.ArrayList(u32) = .empty;
        defer stack.deinit(allocator);
        const Frame = struct { template: u32, next_edge: u32 };
        var frames: std.ArrayList(Frame) = .empty;
        defer frames.deinit(allocator);

        const component_of = try allocator.alloc(u32, count);
        errdefer allocator.free(component_of);
        var members: std.ArrayList(u32) = .empty;
        defer members.deinit(allocator);
        var member_starts: std.ArrayList(u32) = .empty;
        defer member_starts.deinit(allocator);
        try member_starts.append(allocator, 0);
        var next_order: u32 = 0;

        for (0..count) |start| {
            if (order[start] != unvisited) continue;
            order[start] = next_order;
            low[start] = next_order;
            next_order += 1;
            try stack.append(allocator, @intCast(start));
            on_stack.set(start);
            try frames.append(allocator, .{ .template = @intCast(start), .next_edge = self.edge_starts.items[start] });
            while (frames.items.len != 0) {
                const frame = &frames.items[frames.items.len - 1];
                const template = frame.template;
                if (frame.next_edge < self.edge_starts.items[template + 1]) {
                    const edge = self.edges.items[frame.next_edge];
                    frame.next_edge += 1;
                    const callee = switch (edge.callee) {
                        .local => |callee| callee,
                        .imported => continue,
                    };
                    if (order[callee] == unvisited) {
                        order[callee] = next_order;
                        low[callee] = next_order;
                        next_order += 1;
                        try stack.append(allocator, callee);
                        on_stack.set(callee);
                        try frames.append(allocator, .{ .template = callee, .next_edge = self.edge_starts.items[callee] });
                    } else if (on_stack.isSet(callee)) {
                        low[template] = @min(low[template], order[callee]);
                    }
                    continue;
                }
                _ = frames.pop();
                if (frames.items.len != 0) {
                    const parent = frames.items[frames.items.len - 1].template;
                    low[parent] = @min(low[parent], low[template]);
                }
                if (low[template] != order[template]) continue;
                const component: u32 = @intCast(member_starts.items.len - 1);
                const first = members.items.len;
                while (stack.pop()) |member| {
                    on_stack.unset(member);
                    component_of[member] = component;
                    try members.append(allocator, member);
                    if (member == template) break;
                }
                std.mem.sort(u32, members.items[first..], {}, std.sort.asc(u32));
                try member_starts.append(allocator, @intCast(members.items.len));
            }
        }

        const component_count = member_starts.items.len - 1;
        const member_index = try allocator.alloc(u32, count);
        errdefer allocator.free(member_index);
        for (0..component_count) |component| {
            for (members.items[member_starts.items[component]..member_starts.items[component + 1]], 0..) |member, index| member_index[member] = @intCast(index);
        }
        var callees: std.ArrayList(u32) = .empty;
        defer callees.deinit(allocator);
        var callee_starts: std.ArrayList(u32) = .empty;
        defer callee_starts.deinit(allocator);
        try callee_starts.append(allocator, 0);
        for (0..component_count) |component| {
            const first = callees.items.len;
            for (members.items[member_starts.items[component]..member_starts.items[component + 1]]) |member| {
                for (self.edges.items[self.edge_starts.items[member]..self.edge_starts.items[member + 1]]) |edge| switch (edge.callee) {
                    .local => |callee| if (component_of[callee] != component) try callees.append(allocator, component_of[callee]),
                    .imported => {},
                };
            }
            const added = callees.items[first..];
            std.mem.sort(u32, added, {}, std.sort.asc(u32));
            var kept: usize = 0;
            for (added, 0..) |callee, index| {
                if (index != 0 and added[index - 1] == callee) continue;
                added[kept] = callee;
                kept += 1;
            }
            callees.shrinkRetainingCapacity(first + kept);
            try callee_starts.append(allocator, @intCast(callees.items.len));
        }

        const component_slots = try allocator.alloc(TemplateDemandComponentSlot, component_count);
        errdefer allocator.free(component_slots);
        @memset(component_slots, .empty);
        const result = try allocator.create(TemplateDemandGraph);
        errdefer allocator.destroy(result);
        const base_starts = try self.base_starts.toOwnedSlice(allocator);
        errdefer allocator.free(base_starts);
        const bases = try self.demands.toOwnedSlice(allocator);
        errdefer allocator.free(bases);
        const edge_starts = try self.edge_starts.toOwnedSlice(allocator);
        errdefer allocator.free(edge_starts);
        const edges = try self.edges.toOwnedSlice(allocator);
        errdefer allocator.free(edges);
        const owned_member_starts = try member_starts.toOwnedSlice(allocator);
        errdefer allocator.free(owned_member_starts);
        const owned_members = try members.toOwnedSlice(allocator);
        errdefer allocator.free(owned_members);
        const owned_callee_starts = try callee_starts.toOwnedSlice(allocator);
        errdefer allocator.free(owned_callee_starts);
        result.* = .{
            .base_starts = base_starts,
            .bases = bases,
            .edge_starts = edge_starts,
            .edges = edges,
            .component_of = component_of,
            .member_index = member_index,
            .member_starts = owned_member_starts,
            .members = owned_members,
            .callee_starts = owned_callee_starts,
            .callees = try callees.toOwnedSlice(allocator),
            .component_slots = component_slots,
        };
        return result;
    }

    fn analyzeTemplate(self: *TemplateDemandWalk, template: *const CheckedProcedureTemplate) Allocator.Error!void {
        if (self.current_vars.len == 0) return;
        const root_expr = switch (template.body) {
            .checked_body => |root| root,
            // An intrinsic inspects its operands, an entry wrapper marshals
            // them to the host, and an unimplemented declaration's crash
            // body still returns at its declared type.
            .intrinsic_wrapper, .entry_wrapper, .literal_root, .unimplemented => return self.raiseEverything(),
        };
        if (template.target != .roc) return self.raiseEverything();

        // A dispatch requirement inspects its dispatcher's type.
        for (try self.dispatch.evidenceParams(self.current)) |param| {
            try self.raiseMentions(param.dispatcher_ty, .full);
            try self.raiseMentions(param.callable_ty, .full);
        }
        for (self.current_vars, self.current_demands) |var_ty, *demand| {
            switch (self.checked_types.payload(var_ty)) {
                .flex, .rigid => |variable| {
                    if (variable.constraints.len() != 0 or variable.numeric_default_phase != null) demand.* = .full;
                },
                .pending, .field_kind, .err, .alias, .record, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => demand.* = .full,
            }
        }

        // A specialization substitutes each variable through the root type,
        // so a variable it never mentions is fixed only by evidence, and a row
        // extension's substitution is a row rather than a type of its own.
        // Function types carry program-specific lambda sets. A variable that
        // a parameter holds by value, rather than as a list or box element,
        // sizes the parameter itself.
        const root_fn = self.rootFunction(template.checked_fn_root) orelse return self.raiseEverything();
        const root_flags = try self.allocator.alloc(?TypeVarMentionFlags, self.current_vars.len);
        defer self.allocator.free(root_flags);
        @memset(root_flags, null);
        for (root_fn.args) |arg| try self.noteRootMentions(root_flags, arg);
        try self.noteRootMentions(root_flags, root_fn.ret);
        for (root_flags, self.current_demands) |maybe_flags, *demand| {
            const flags = maybe_flags orelse {
                demand.* = .full;
                continue;
            };
            if (flags.row_extension or flags.under_function or flags.decides_representation) {
                demand.* = .full;
            } else if (flags.outside_container) {
                demand.* = maxSchemeVarDemand(demand.*, .layout);
            }
        }

        // Walking the body only raises demands, and the edges it records only
        // raise this template's demands, so a template that already demands
        // all of every variable has nothing left to learn from its body.
        for (self.current_demands) |demand| {
            if (demand != .full) break;
        } else return;

        const root = self.bodies.exprData(root_expr);
        if (root != .lambda) return self.raiseEverything();
        const lambda = root.lambda;
        self.work.clearRetainingCapacity();
        try self.work.append(self.allocator, .{ .expr = .{ .id = lambda.body, .role = .value } });
        for (lambda.args) |arg| try self.work.append(self.allocator, .{ .pattern = .{ .id = arg, .role = .parameter } });
        while (self.work.pop()) |item| switch (item) {
            .expr => |expr| try self.visitExpr(expr.id, expr.role),
            .pattern => |pattern| try self.visitPattern(pattern.id, pattern.role),
            .statement => |statement| try self.visitStatement(statement),
        };
    }

    /// The function type a template's root names, through aliases.
    fn rootFunction(self: *const TemplateDemandWalk, root: CheckedTypeId) ?CheckedFunctionType {
        var current = root;
        var remaining = self.checked_types.typeCount();
        while (remaining != 0) : (remaining -= 1) {
            switch (self.checked_types.payload(current)) {
                .alias => |alias| current = alias.backing,
                .function => |function| return function,
                .pending, .field_kind, .err, .flex, .rigid, .record, .tuple, .nominal, .empty_record, .tag_union, .empty_tag_union => return null,
            }
        }
        checkedArtifactInvariant("procedure template root alias chain was cyclic", .{});
    }

    fn noteRootMentions(self: *TemplateDemandWalk, flags: []?TypeVarMentionFlags, ty: CheckedTypeId) Allocator.Error!void {
        for (try self.mentions.of(ty)) |mention| {
            const slot = self.slotOf(mention.var_ty) orelse continue;
            flags[slot] = if (flags[slot]) |existing| existing.merge(mention.flags) else mention.flags;
        }
    }

    fn slotOf(self: *const TemplateDemandWalk, var_ty: CheckedTypeId) ?usize {
        return if (self.current_slots.get(var_ty)) |slot| slot else null;
    }

    fn raiseSlot(self: *TemplateDemandWalk, slot: usize, demand: SchemeVarDemand) void {
        self.current_demands[slot] = maxSchemeVarDemand(self.current_demands[slot], demand);
    }

    fn raiseEverything(self: *TemplateDemandWalk) void {
        @memset(self.current_demands, .full);
    }

    /// Raise every quantified variable `ty` mentions to `demand`, and every one
    /// whose exact type it needs (see `exactMention`) to `full`. The walk
    /// skips every step an earlier raise in this template already walked at
    /// this demand, so the raises of one template cost the size of the types
    /// they reach, however many of its expressions share those types.
    fn raiseMentions(self: *TemplateDemandWalk, ty: CheckedTypeId, demand: SchemeVarDemand) Allocator.Error!void {
        try self.pushRaise(.{ .step = .{ .ty = ty, .flags = .{ .outside_container = true } }, .demand = demand });
        const sink: RaiseSink = .{ .pass = self, .demand = demand };
        while (self.raise_pending.pop()) |raise| try TypeVarMentions.expandStep(self.checked_types, raise.step, sink);
    }

    fn pushRaise(self: *TemplateDemandWalk, raise: RaiseStep) Allocator.Error!void {
        const entry = try self.raised.getOrPut(self.allocator, raise);
        if (entry.found_existing) return;
        try self.raise_pending.append(self.allocator, raise);
    }

    /// Whether a type needs the exact type of a variable it mentions this
    /// way: lambda-set solving needs the exact type of every function, and a
    /// representation-deciding builtin argument decides more than a layout.
    fn exactMention(flags: TypeVarMentionFlags) bool {
        return flags.under_function or flags.decides_representation;
    }

    /// Raise every quantified variable whose exact type `ty` needs to `full`:
    /// a raise to `none` leaves every other mention as it is.
    fn raiseFunctionMentions(self: *TemplateDemandWalk, ty: CheckedTypeId) Allocator.Error!void {
        try self.raiseMentions(ty, .none);
    }

    fn pushExpr(self: *TemplateDemandWalk, id: CIR.Expr.Idx, role: ExprRole) Allocator.Error!void {
        try self.work.append(self.allocator, .{ .expr = .{ .id = id, .role = role } });
    }

    fn pushExprs(self: *TemplateDemandWalk, ids: []const CIR.Expr.Idx, role: ExprRole) Allocator.Error!void {
        for (ids) |id| try self.pushExpr(id, role);
    }

    fn pushPattern(self: *TemplateDemandWalk, id: CIR.Pattern.Idx, role: PatternRole) Allocator.Error!void {
        try self.work.append(self.allocator, .{ .pattern = .{ .id = id, .role = role } });
    }

    fn visitExpr(self: *TemplateDemandWalk, id: CIR.Expr.Idx, role: ExprRole) Allocator.Error!void {
        const bodies = self.bodies;
        const data = bodies.exprData(id);
        const ty = bodies.exprType(id);
        // A row-coerced value reaches its parent through its coercion: the
        // parent's role demands the widened type, and the coercion holds the
        // expression's own value.
        const own_role = if (bodies.rowCoercion(id)) |wide| blk: {
            switch (role) {
                .direct_callee => {},
                .operand, .value => try self.raiseMentions(wide, .layout),
            }
            break :blk ExprRole.value;
        } else role;
        switch (own_role) {
            .direct_callee => {},
            .operand => if (data == .lookup_local)
                try self.raiseFunctionMentions(ty)
            else
                try self.raiseMentions(ty, .layout),
            .value => try self.raiseMentions(ty, .layout),
        }
        switch (data) {
            .lookup_local,
            .lookup_external,
            .lookup_required,
            .str_segment,
            .bytes_literal,
            .empty_list,
            .empty_record,
            .zero_argument_tag,
            .crash,
            .break_,
            => {},
            .ellipsis, .anno_only, .hosted_lambda => self.raiseEverything(),
            .numeral => {
                try self.raiseMentions(ty, .full);
                if (bodies.numeralPlan(@backingInt(id))) |plan| try self.visitInspectingPlan(plan);
            },
            .str => |segments| if (bodies.quoteIsCustom(@backingInt(id))) {
                try self.raiseMentions(ty, .full);
                if (bodies.quotePlan(@backingInt(id))) |plan| try self.visitInspectingPlan(plan);
            } else {
                try self.pushExprs(segments, .value);
            },
            .list, .tuple => |items| try self.pushExprs(items, .value),
            .match_ => |match| {
                try self.pushExpr(match.cond, .value);
                for (match.branches) |branch_idx| {
                    const branch = bodies.matchBranch(branch_idx);
                    for (branch.patterns) |branch_pattern| try self.pushPattern(bodies.matchBranchPattern(branch_pattern).pattern, .binding);
                    if (branch.guard) |guard| try self.pushExpr(guard, .value);
                    try self.pushExpr(branch.value, .value);
                }
            },
            .if_ => |if_| {
                for (if_.branches) |branch_idx| {
                    const branch = bodies.ifBranch(branch_idx);
                    try self.pushExpr(branch.cond, .value);
                    try self.pushExpr(branch.body, .value);
                }
                try self.pushExpr(if_.final_else, .value);
            },
            .call => |call| try self.visitCall(id, call),
            .record => |record| {
                if (record.ext) |ext| try self.pushExpr(ext, .value);
                for (record.fields) |field| try self.pushExpr(bodies.recordFieldValue(field), .value);
            },
            .block => |block| {
                for (block.statements) |statement| try self.work.append(self.allocator, .{ .statement = statement });
                try self.pushExpr(block.final_expr, .value);
            },
            .tag => |tag| try self.pushExprs(tag.args, .value),
            .nominal => |nominal| try self.pushExpr(nominal.backing_expr, .value),
            .closure => |closure| {
                // A closure's lambda set is program-specific, and so is the
                // layout of what it captures.
                try self.raiseMentions(ty, .full);
                for (closure.captures) |capture| {
                    try self.raiseMentions(bodies.patternType(bodies.capture(capture).pattern), .full);
                }
                try self.pushExpr(closure.lambda, .value);
            },
            .lambda => |lambda| {
                try self.raiseMentions(ty, .full);
                for (lambda.args) |arg| try self.pushPattern(arg, .binding);
                try self.pushExpr(lambda.body, .value);
            },
            .binop => |binop| {
                try self.raiseMentions(bodies.valueType(binop.lhs), .full);
                try self.raiseMentions(bodies.valueType(binop.rhs), .full);
                try self.pushExpr(binop.lhs, .value);
                try self.pushExpr(binop.rhs, .value);
            },
            .unary_minus => |operand| {
                try self.raiseMentions(bodies.valueType(operand), .full);
                try self.pushExpr(operand, .value);
            },
            .field_access => |field| try self.pushExpr(field.receiver, .value),
            .tuple_access => |access| try self.pushExpr(access.tuple, .value),
            .dispatch_call, .type_dispatch_call => {
                const plan = bodies.dispatchPlan(@backingInt(id)) orelse return self.raiseEverything();
                try self.visitDispatchPlan(plan);
            },
            .method_eq => {
                const plan = bodies.dispatchPlan(@backingInt(id)) orelse return self.raiseEverything();
                try self.visitInspectingPlan(plan);
            },
            .interpolation => |interpolation| if (bodies.interpolationIsBuiltinStr(id)) {
                try self.pushExpr(interpolation.first, .value);
                try self.pushExprs(interpolation.parts, .value);
            } else {
                var value_index: usize = 0;
                while (value_index < interpolation.valueCount()) : (value_index += 1) {
                    try self.raiseMentions(bodies.valueType(interpolation.value(value_index)), .full);
                }
                var segment_index: usize = 0;
                while (segment_index < interpolation.segmentCount()) : (segment_index += 1) {
                    try self.pushExpr(interpolation.segment(segment_index), .value);
                }
                value_index = 0;
                while (value_index < interpolation.valueCount()) : (value_index += 1) {
                    try self.pushExpr(interpolation.value(value_index), .value);
                }
            },
            .structural_eq => |eq| {
                try self.raiseMentions(bodies.valueType(eq.lhs), .full);
                try self.raiseMentions(bodies.valueType(eq.rhs), .full);
                try self.pushExpr(eq.lhs, .value);
                try self.pushExpr(eq.rhs, .value);
            },
            .structural_hash => |hash| {
                try self.raiseMentions(bodies.valueType(hash.value), .full);
                try self.pushExpr(hash.value, .value);
                try self.pushExpr(hash.hasher, .value);
            },
            .runtime_error => |runtime_error| try self.pushExprs(runtime_error.evaluated, .value),
            .dbg => |payload| {
                try self.raiseMentions(bodies.valueType(payload), .full);
                try self.pushExpr(payload, .value);
            },
            .expect_err => |expect_err| {
                try self.raiseMentions(bodies.valueType(expect_err.expr), .full);
                try self.pushExpr(expect_err.expr, .value);
            },
            .expect => |condition| try self.pushExpr(condition, .value),
            .return_ => |ret| try self.pushExpr(ret.expr, .value),
            .for_ => |for_| try self.visitFor(for_.pattern, for_.expr, for_.body),
            .run_low_level => |run| {
                for (run.args, 0..) |arg, index| {
                    try self.raiseMentions(bodies.valueType(arg), run.op.elementDemand(index));
                    try self.pushExpr(arg, .operand);
                }
            },
        }
    }

    fn visitFor(self: *TemplateDemandWalk, pattern: CIR.Pattern.Idx, iterable: CIR.Expr.Idx, body: CIR.Expr.Idx) Allocator.Error!void {
        // Iteration dispatches on the iterable's type.
        try self.raiseMentions(self.bodies.valueType(iterable), .full);
        try self.raiseMentions(self.bodies.patternType(pattern), .full);
        try self.pushPattern(pattern, .binding);
        try self.pushExpr(iterable, .value);
        try self.pushExpr(body, .value);
    }

    fn visitStatement(self: *TemplateDemandWalk, id: CIR.Statement.Idx) Allocator.Error!void {
        switch (self.bodies.statementData(id)) {
            .decl => |decl| {
                try self.pushPattern(decl.pattern, .binding);
                try self.pushExpr(decl.expr, .value);
            },
            .var_ => |var_| {
                try self.pushPattern(var_.pattern, .binding);
                try self.pushExpr(var_.expr, .value);
            },
            .reassign => |reassign| {
                try self.pushPattern(reassign.pattern, .binding);
                try self.pushExpr(reassign.expr, .value);
            },
            // The promoted procedure is a template of its own; its binding's
            // function type is all this body sees of it.
            .promoted_proc => |promoted| try self.pushPattern(promoted.pattern, .binding),
            .var_uninitialized => |var_| try self.pushPattern(var_.pattern, .binding),
            .dbg => |payload| {
                try self.raiseMentions(self.bodies.valueType(payload), .full);
                try self.pushExpr(payload, .value);
            },
            .expr, .expect => |expr| try self.pushExpr(expr, .value),
            .for_ => |for_| try self.visitFor(for_.pattern, for_.expr, for_.body),
            .while_, .infinite_loop, .breakable_loop => |loop| {
                try self.pushExpr(loop.cond, .value);
                try self.pushExpr(loop.body, .value);
            },
            .return_ => |ret| try self.pushExpr(ret.expr, .value),
            .crash,
            .break_,
            .rejected_method_decl,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => {},
        }
    }

    fn visitPattern(self: *TemplateDemandWalk, id: CIR.Pattern.Idx, role: PatternRole) Allocator.Error!void {
        const bodies = self.bodies;
        const pattern_ty = bodies.patternType(id);
        switch (bodies.patternData(id)) {
            .assign, .underscore => switch (role) {
                .parameter => try self.raiseFunctionMentions(pattern_ty),
                .binding => try self.raiseMentions(pattern_ty, .layout),
            },
            .as => |as| {
                try self.raiseMentions(pattern_ty, .layout);
                try self.pushPattern(as.pattern, .binding);
            },
            .applied_tag => |tag| {
                try self.raiseMentions(pattern_ty, .layout);
                for (tag.args) |arg| try self.pushPattern(arg, .binding);
            },
            .nominal => |nominal| {
                try self.raiseMentions(pattern_ty, .layout);
                try self.pushPattern(nominal.backing_pattern, .binding);
            },
            .record_destructure => |destructs| {
                try self.raiseMentions(pattern_ty, .layout);
                for (destructs) |destruct| try self.pushPattern(bodies.recordDestructPattern(destruct), .binding);
            },
            .list => |list| {
                try self.raiseMentions(pattern_ty, .layout);
                for (list.patterns) |child| try self.pushPattern(child, .binding);
                if (list.rest) |rest| if (rest.pattern) |child| try self.pushPattern(child, .binding);
            },
            .tuple => |items| {
                try self.raiseMentions(pattern_ty, .layout);
                for (items) |child| try self.pushPattern(child, .binding);
            },
            .numeral_literal, .str_literal => {
                try self.raiseMentions(pattern_ty, .full);
                if (bodies.literalPatternGuard(id)) |guard| try self.visitLiteralPatternGuard(guard);
            },
            .str_interpolation => |str| {
                try self.raiseMentions(pattern_ty, .full);
                var offset: u32 = 0;
                while (offset < str.steps.span.len) : (offset += 1) {
                    if (bodies.strPatternStep(str.steps, offset).capture) |capture| try self.pushPattern(capture, .binding);
                }
            },
            .runtime_error => {},
        }
    }

    /// A custom literal pattern compares the matched value with its literal
    /// converted at the pattern's type: both inspect their dispatchers.
    fn visitLiteralPatternGuard(self: *TemplateDemandWalk, guard: checked_bodies_mod.LiteralPatternGuard) Allocator.Error!void {
        try self.raiseMentions(guard.equality_ty, .layout);
        try self.visitInspectingPlan(guard.equality_plan orelse return self.raiseEverything());
        if (guard.conversion.plan) |plan| try self.visitInspectingPlan(plan);
    }

    fn visitCall(self: *TemplateDemandWalk, call_expr: CIR.Expr.Idx, call: anytype) Allocator.Error!void {
        if (self.bodies.callDirectTarget(call_expr)) |target| {
            if (try self.directCallTemplate(target)) |callee| {
                if (try self.dispatch.siteSubstitution(call.func)) |subst| {
                    if (try self.relateCall(callee, subst)) {
                        try self.pushExpr(call.func, .direct_callee);
                        try self.pushExprs(call.args, .operand);
                        return;
                    }
                }
            }
        }
        // Any other callee is a function value whose lambda set the program
        // decides; its type mentions every variable its operands do.
        try self.raiseMentions(self.bodies.valueType(call.func), .full);
        try self.pushExpr(call.func, .value);
        try self.pushExprs(call.args, .operand);
    }

    /// A dispatch whose checked resolution selected one procedure template
    /// behaves like a direct call to it; any other dispatch inspects its
    /// dispatcher.
    fn visitDispatchPlan(self: *TemplateDemandWalk, plan_id: static_dispatch.StaticDispatchPlanId) Allocator.Error!void {
        const plan = try self.dispatch.plan(plan_id);
        if (try self.dispatchTemplate(plan)) |selected| {
            if (try self.relateCall(selected.template, selected.subst)) {
                try self.pushPlanOperands(plan, .operand);
                return;
            }
        }
        try self.raiseMentions(plan.dispatcher_ty, .full);
        try self.raiseMentions(plan.callable_ty, .full);
        try self.pushPlanOperands(plan, .operand);
    }

    fn visitInspectingPlan(self: *TemplateDemandWalk, plan_id: static_dispatch.StaticDispatchPlanId) Allocator.Error!void {
        const plan = try self.dispatch.plan(plan_id);
        try self.raiseMentions(plan.dispatcher_ty, .full);
        try self.raiseMentions(plan.callable_ty, .full);
        try self.pushPlanOperands(plan, .value);
    }

    fn pushPlanOperands(self: *TemplateDemandWalk, plan: static_dispatch.StaticDispatchCallPlan, role: ExprRole) Allocator.Error!void {
        for (plan.argsSlice(self.static_dispatch_plans)) |operand| switch (operand) {
            .checked_expr => |expr| try self.pushExpr(expr, role),
            .generated_interpolation_segments => |expr| try self.pushExpr(expr, .value),
            .generated_numeral, .generated_quote, .literal_pattern_value, .literal_pattern_conversion => {},
        };
    }

    const SelectedTemplate = struct {
        template: canonical.ProcedureTemplateRef,
        subst: []const CheckedTypeId,
    };

    fn dispatchTemplate(self: *TemplateDemandWalk, plan: static_dispatch.StaticDispatchCallPlan) Allocator.Error!?SelectedTemplate {
        const direct = switch (plan.resolution) {
            .direct_closed, .direct_parametric => |direct| direct,
            .direct_pending, .evidence_dependent, .structural, .checked_error, .@"unreachable" => return null,
        };
        const node = (try self.dispatch.evidenceNode(direct.evidence));
        if (node.target.alias != null) return null;
        const procedure = switch (node.target.kind) {
            .procedure => |procedure| procedure,
            .local_proc, .structural => return null,
        };
        switch (procedure.runtime_target) {
            .procedure, .low_level => {},
            .intrinsic, .graph_participating => return null,
        }
        return .{
            .template = procedure.template,
            .subst = (try self.dispatch.substitution(node.subst)),
        };
    }

    /// The checked template a direct call's target names, when it names one.
    fn directCallTemplate(self: *TemplateDemandWalk, target: ResolvedValueRefId) Allocator.Error!?canonical.ProcedureTemplateRef {
        const procedure = switch (self.resolved_value_refs.records[@backingInt(target)].ref) {
            .top_level_proc, .imported_proc, .promoted_top_level_proc => |procedure| procedure,
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            => return null,
        };
        if (procedure.intrinsic != null) return null;
        const body = switch (procedure.binding) {
            .top_level => |binding| blk: {
                if (!binding.artifact.eql(self.artifact_key.digest())) return null;
                break :blk self.top_level_procedure_bindings.get(binding.binding).body;
            },
            .imported => |imported| return try self.importedTemplate(imported),
            .hosted, .platform_required => return null,
        };
        return directProcedureBindingTemplate(body);
    }

    fn importedTemplate(self: *TemplateDemandWalk, imported: ImportedProcedureBindingRef) Allocator.Error!?canonical.ProcedureTemplateRef {
        const key: ImportedDefKey = .{ .artifact = imported.artifact, .def = imported.def };
        if (self.imported_templates.get(key)) |cached| return cached;
        const view = self.dispatch.importedView(imported.artifact) orelse return null;
        const template = if (importedProcedureBindingForDef(view, imported.def)) |binding|
            directProcedureBindingTemplate(binding.body)
        else
            null;
        try self.imported_templates.put(self.allocator, key, template);
        return template;
    }

    fn directProcedureBindingTemplate(body: ProcedureBindingBody) ?canonical.ProcedureTemplateRef {
        return switch (body) {
            .direct_template => |direct| switch (direct.template) {
                .checked => |template| template,
                .lifted, .synthetic => null,
            },
            .callable_eval_template, .checked_error => null,
        };
    }

    /// Relate a call to `callee` under `subst` (one caller type per callee
    /// quantified variable): every caller variable a slot's type mentions is
    /// demanded at least as much as the callee demands that slot, and fully
    /// where the slot needs the variable's exact type. False when the callee
    /// is not a template this module reads.
    fn relateCall(self: *TemplateDemandWalk, callee: canonical.ProcedureTemplateRef, subst: []const CheckedTypeId) Allocator.Error!bool {
        const local = callee.artifact.eql(self.artifact_key.digest());
        const callee_vars = if (local)
            try self.dispatch.templateSchemeVars(callee.template)
        else blk: {
            const view = self.dispatch.importedView(callee.artifact) orelse return false;
            break :blk try view.dispatch().templateSchemeVars(callee.template);
        };
        if (subst.len != callee_vars.len) return false;
        for (subst, 0..) |slot_ty, callee_slot| {
            for (try self.mentions.of(slot_ty)) |mention| {
                const caller_slot = self.slotOf(mention.var_ty) orelse continue;
                if (exactMention(mention.flags)) {
                    self.raiseSlot(caller_slot, .full);
                    continue;
                }
                try self.edges.append(self.allocator, .{
                    .caller_slot = @intCast(caller_slot),
                    .callee = if (local) .{ .local = callee.template.index() } else .{ .imported = callee },
                    .callee_slot = @intCast(callee_slot),
                });
            }
        }
        return true;
    }
};

fn checkedTypeIsContextFreeCompileTimeRoot(
    allocator: Allocator,
    module: ModuleId,
    checked_types: CheckedTypeStoreView,
    resolver: ModuleResolver,
    producer_callable_type_is_fixed: bool,
    root: CheckedTypeId,
) Allocator.Error!bool {
    if (!try checkedTypeIsConcreteCompileTimeRoot(allocator, module, checked_types, resolver, root)) return false;

    // A callable root or an annotated data producer fixes its callable graph at
    // the producer. An unannotated data root can instead receive callable type
    // relations from a use site, so it must not seal a context-free graph first.
    return producer_callable_type_is_fixed or
        try checkedTypeHasNoReachableCallableSlots(allocator, module, checked_types, resolver, root);
}

fn deinitCompileTimeRootSlice(allocator: Allocator, roots: []CompileTimeRoot) void {
    for (roots) |*root| {
        if (root.hoisted_body) |body| {
            hoist_roots.deinitBody(allocator, body);
            root.hoisted_body = null;
        }
    }
}

fn verifyCompileTimeRootPayloadMatchesKind(root: CompileTimeRoot, payload: CompileTimeRootPayload) void {
    const matches = switch (root.kind) {
        .constant, .hoisted_constant => switch (payload) {
            .const_node, .unevaluated => true,
            .runtime => root.guarded,
            .pending, .fn_value, .discarded, .expect => false,
        },
        // A REPL expression is the compilation's only demand.
        .repl_expr => switch (payload) {
            .const_node => true,
            .runtime => root.guarded,
            .pending, .unevaluated, .fn_value, .discarded, .expect => false,
        },
        .hoisted_validation => switch (payload) {
            .discarded, .unevaluated => true,
            .runtime => root.guarded,
            .pending, .const_node, .fn_value, .expect => false,
        },
        .callable_binding => switch (payload) {
            // A callable initializer that reaches an explicit checked error is
            // stored as a divergent ConstStore node. Monotype restores that
            // node at the callable's expected type, so execution crashes at
            // the exact invalid binding while independent roots remain usable.
            .fn_value, .const_node, .unevaluated => true,
            .pending, .discarded, .expect, .runtime => false,
        },
        .expect => switch (payload) {
            .expect => true,
            .pending, .unevaluated, .const_node, .fn_value, .discarded, .runtime => false,
        },
        .numeral_conversion, .quote_conversion => switch (payload) {
            .const_node, .unevaluated => true,
            .pending, .fn_value, .discarded, .expect, .runtime => false,
        },
        // A literal argument holding a function value (an interpolation's
        // assembler) is stored as one.
        .literal_argument => switch (payload) {
            .const_node, .fn_value, .unevaluated => true,
            .pending, .discarded, .expect, .runtime => false,
        },
    };
    if (matches) return;
    checkedArtifactInvariant("compile-time root payload does not match root kind", .{});
}

fn compileTimeRootHasConstBody(kind: CompileTimeRootKind) bool {
    return switch (kind) {
        .constant, .hoisted_constant => true,
        .hoisted_validation, .callable_binding, .expect, .numeral_conversion, .quote_conversion, .repl_expr, .literal_argument => false,
    };
}

/// The local procedure templates a module's root requests reach at runtime,
/// at compile time, and at compile time only through a further pairing.
const ExhaustivenessTemplateReachability = struct {
    allocator: Allocator,
    artifact_key: CheckedModuleArtifactKey,
    procedure_templates: *const CheckedProcedureTemplateTable,
    entry_wrappers: *const EntryWrapperTable,
    callable_eval_templates: CallableEvalTemplateTableView,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    runtime_templates: []bool,
    compile_time_templates: []bool,
    pairing_templates: []bool,
    /// Templates marked reachable whose own refs are not yet marked.
    pending_templates: std.ArrayListUnmanaged(PendingTemplate) = .empty,

    const PendingTemplate = struct { kind: ReachabilityKind, idx: usize };

    fn init(
        allocator: Allocator,
        artifact_key: CheckedModuleArtifactKey,
        procedure_templates: *const CheckedProcedureTemplateTable,
        entry_wrappers: *const EntryWrapperTable,
        callable_eval_templates: CallableEvalTemplateTableView,
        top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        resolved_value_refs: *const ResolvedValueRefTable,
    ) Allocator.Error!ExhaustivenessTemplateReachability {
        const runtime_templates = try allocator.alloc(bool, procedure_templates.templates.items.len);
        errdefer allocator.free(runtime_templates);
        const compile_time_templates = try allocator.alloc(bool, procedure_templates.templates.items.len);
        errdefer allocator.free(compile_time_templates);
        const pairing_templates = try allocator.alloc(bool, procedure_templates.templates.items.len);
        @memset(pairing_templates, false);
        @memset(runtime_templates, false);
        @memset(compile_time_templates, false);
        return .{
            .allocator = allocator,
            .artifact_key = artifact_key,
            .procedure_templates = procedure_templates,
            .entry_wrappers = entry_wrappers,
            .callable_eval_templates = callable_eval_templates,
            .top_level_procedure_bindings = top_level_procedure_bindings,
            .platform_required_bindings = platform_required_bindings,
            .resolved_value_refs = resolved_value_refs,
            .runtime_templates = runtime_templates,
            .compile_time_templates = compile_time_templates,
            .pairing_templates = pairing_templates,
        };
    }

    fn deinit(self: *ExhaustivenessTemplateReachability) void {
        self.pending_templates.deinit(self.allocator);
        self.allocator.free(self.pairing_templates);
        self.allocator.free(self.compile_time_templates);
        self.allocator.free(self.runtime_templates);
        self.* = undefined;
    }

    fn build(
        allocator: Allocator,
        artifact_key: CheckedModuleArtifactKey,
        root_requests: *const RootRequestTable,
        procedure_templates: *const CheckedProcedureTemplateTable,
        entry_wrappers: *const EntryWrapperTable,
        callable_eval_templates: CallableEvalTemplateTableView,
        top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        resolved_value_refs: *const ResolvedValueRefTable,
    ) Allocator.Error!ExhaustivenessTemplateReachability {
        var reachability = try ExhaustivenessTemplateReachability.init(
            allocator,
            artifact_key,
            procedure_templates,
            entry_wrappers,
            callable_eval_templates,
            top_level_procedure_bindings,
            platform_required_bindings,
            resolved_value_refs,
        );
        errdefer reachability.deinit();

        for (root_requests.requests) |request| {
            try reachability.markRootRequest(if (request.abi == .compile_time) .compile_time else .runtime, request);
            if (request.abi == .compile_time and request.requires_pairing) try reachability.markRootRequest(.pairing, request);
        }

        return reachability;
    }

    fn templateIsRuntimeReachable(self: *const ExhaustivenessTemplateReachability, template_ref: canonical.ProcedureTemplateRef) bool {
        const idx = self.localTemplateIndex(template_ref) orelse return false;
        return self.runtime_templates[idx];
    }

    fn templateIsCompileTimeReachable(self: *const ExhaustivenessTemplateReachability, template_ref: canonical.ProcedureTemplateRef) bool {
        const idx = self.localTemplateIndex(template_ref) orelse return false;
        return self.compile_time_templates[idx];
    }

    const ReachabilityKind = enum {
        runtime,
        compile_time,
        pairing,
    };

    fn markRootRequest(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        request: RootRequest,
    ) Allocator.Error!void {
        switch (request.source) {
            .required_binding => |binding_id| try self.markPlatformRequiredBindingClosure(kind, @fromBackingInt(@intCast(binding_id))),
            .def,
            .expr,
            .statement,
            .hoisted,
            .literal,
            => {},
        }
        if (request.procedure_template) |template_ref| {
            try self.markProcedureTemplate(kind, template_ref);
        }
        if (request.procedure_use) |procedure| {
            try self.markProcedureUse(kind, procedure);
        }
        if (request.procedure_binding) |binding| {
            try self.markTopLevelProcedureBinding(kind, .{
                .artifact = self.artifact_key.digest(),
                .binding = binding,
            });
        }
        try self.drainPendingTemplates();
    }

    /// Mark the refs of every template marked reachable, until none is left.
    fn drainPendingTemplates(self: *ExhaustivenessTemplateReachability) Allocator.Error!void {
        while (self.pending_templates.pop()) |pending| {
            const template = self.procedure_templates.templates.items[pending.idx];
            const end = template.resolved_value_refs.start + template.resolved_value_refs.len;
            if (end > self.resolved_value_refs.template_refs.len) {
                checkedArtifactInvariant("reachable procedure template resolved-ref span was outside table", .{});
            }
            for (self.resolved_value_refs.template_refs[template.resolved_value_refs.start..end]) |ref_id| {
                const raw = @backingInt(ref_id);
                if (raw >= self.resolved_value_refs.records.len) {
                    checkedArtifactInvariant("reachable procedure template resolved-ref id was outside table", .{});
                }
                try self.markResolvedValueRef(pending.kind, self.resolved_value_refs.records[raw].ref);
            }
        }
    }

    fn markProcedureTemplate(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        template_ref: canonical.ProcedureTemplateRef,
    ) Allocator.Error!void {
        const idx = self.localTemplateIndex(template_ref) orelse return;
        const seen = switch (kind) {
            .runtime => &self.runtime_templates[idx],
            .compile_time => &self.compile_time_templates[idx],
            .pairing => &self.pairing_templates[idx],
        };
        if (seen.*) return;
        seen.* = true;

        const template = self.procedure_templates.templates.items[idx];
        if (template.proc_base != template_ref.proc_base) {
            checkedArtifactInvariant("reachable procedure template ref disagreed with template row", .{});
        }
        // Its refs are marked by `drainPendingTemplates`, so a long call
        // chain never becomes native call depth.
        try self.pending_templates.append(self.allocator, .{ .kind = kind, .idx = idx });
    }

    fn markResolvedValueRef(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        ref: ResolvedValueRef,
    ) Allocator.Error!void {
        switch (ref) {
            .top_level_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |procedure| try self.markProcedureUse(kind, procedure),
            .platform_required_proc => |required| {
                try self.markProcedureUse(kind, required.procedure);
                try self.markPlatformRequiredBindingClosure(kind, required.binding);
            },
            .platform_required_const => |required| try self.markPlatformRequiredBindingClosure(kind, required.binding),
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .selected_hoisted_const,
            .local_proc,
            .top_level_const,
            .imported_const,
            .imported_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            => {},
        }
    }

    fn markProcedureUse(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        procedure: ProcedureUseTemplate,
    ) Allocator.Error!void {
        switch (procedure.binding) {
            .top_level => |top_level| try self.markTopLevelProcedureBinding(kind, top_level),
            .hosted => |hosted| try self.markProcedureTemplate(kind, hosted.template),
            .platform_required => |required| try self.markTopLevelProcedureBinding(kind, .{
                .artifact = required.artifact,
                .binding = required.procedure_binding,
            }),
            .imported => {},
        }
    }

    fn markTopLevelProcedureBinding(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        binding_ref: ArtifactTopLevelProcedureBindingRef,
    ) Allocator.Error!void {
        if (!binding_ref.artifact.eql(self.artifact_key.digest())) return;
        const binding = self.top_level_procedure_bindings.get(binding_ref.binding);
        try self.markProcedureBindingBody(kind, binding.body);
    }

    fn markProcedureBindingBody(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        body: ProcedureBindingBody,
    ) Allocator.Error!void {
        switch (body) {
            .direct_template => |direct| try self.markCallableProcedureTemplate(kind, direct.template),
            .checked_error => {},
            .callable_eval_template => |template_id| try self.markCallableEvalTemplate(kind, template_id),
        }
    }

    fn markCallableEvalTemplate(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        template_id: CallableEvalTemplateId,
    ) Allocator.Error!void {
        const raw = @backingInt(template_id);
        if (raw >= self.callable_eval_templates.templates.len) {
            checkedArtifactInvariant("reachable callable-eval template id was outside table", .{});
        }
        const template = self.callable_eval_templates.get(template_id);
        try self.markProcedureTemplate(kind, entryWrapperForRoot(self.entry_wrappers, template.root).template);
    }

    fn markPlatformRequiredBindingClosure(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        binding_id: PlatformRequiredBindingId,
    ) Allocator.Error!void {
        const binding = self.platform_required_bindings.lookupByBindingId(@backingInt(binding_id)) orelse {
            checkedArtifactInvariant("reachable platform-required binding id was outside table", .{});
        };
        const closure = self.platform_required_bindings.relationClosure(binding);
        try self.markImportedTemplateClosure(kind, closure);
    }

    fn markImportedTemplateClosure(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        closure: ImportedTemplateClosureView,
    ) Allocator.Error!void {
        for (closure.checked_procedure_templates) |template_ref| {
            try self.markProcedureTemplate(kind, template_ref);
        }
        for (closure.callable_eval_templates) |template_ref| {
            try self.markArtifactCallableEvalTemplate(kind, template_ref);
        }
    }

    fn markArtifactCallableEvalTemplate(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        template_ref: ArtifactCallableEvalTemplateRef,
    ) Allocator.Error!void {
        if (!template_ref.artifact.eql(self.artifact_key.digest())) return;
        try self.markCallableEvalTemplate(kind, template_ref.template);
    }

    fn markCallableProcedureTemplate(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        template: canonical.CallableProcedureTemplateRef,
    ) Allocator.Error!void {
        switch (template) {
            .checked => |checked| try self.markProcedureTemplate(kind, checked),
            .synthetic => |synthetic| try self.markProcedureTemplate(kind, synthetic.template),
            .lifted => checkedArtifactInvariant("reachable procedure template reached lifted procedure before post-check lowering", .{}),
        }
    }

    fn localTemplateIndex(
        self: *const ExhaustivenessTemplateReachability,
        template_ref: canonical.ProcedureTemplateRef,
    ) ?usize {
        if (!template_ref.artifact.eql(self.artifact_key.digest())) return null;
        // A literal root's entry wrapper converts a literal and reaches no
        // exhaustiveness check.
        const idx = template_ref.template.rowIndex() orelse return null;
        if (idx >= self.procedure_templates.templates.items.len) {
            checkedArtifactInvariant("reachable procedure template ref was outside table", .{});
        }
        return idx;
    }
};

/// The exhaustiveness checks a procedure template's body reaches
/// (`ModuleAnalyses.templateExhaustivenessSites`).
/// The nested procedure sites of a literal root's entry wrapper, whose body
/// constructs no procedure.
pub const empty_owner_nested_proc_sites: OwnerNestedProcSites = .{};

/// The exhaustiveness sites of a literal root's entry wrapper, whose body
/// reaches none.
pub const empty_template_exhaustiveness_sites: TemplateExhaustivenessSites = .{};

pub const TemplateExhaustivenessSites = struct {
    /// Ascending.
    sites: []const CheckedExhaustivenessSiteId = &.{},

    pub fn destroy(self: *TemplateExhaustivenessSites, allocator: Allocator) void {
        allocator.free(self.sites);
        allocator.destroy(self);
    }
};

/// The exhaustiveness checks the body of procedure template `template`
/// reaches.
pub fn computeTemplateExhaustivenessSites(
    allocator: Allocator,
    bodies: CheckedBodies,
    template: canonical.CheckedProcedureTemplateId,
) Allocator.Error!*TemplateExhaustivenessSites {
    const templates = bodies.tables.templates orelse checkedArtifactInvariant("exhaustiveness sites were collected from bodies without templates", .{});
    var found = std.ArrayList(CheckedExhaustivenessSiteId).empty;
    defer found.deinit(allocator);
    switch (templates.get(template).body) {
        .checked_body => |root| try collectExhaustivenessSites(allocator, bodies, root, &found),
        .intrinsic_wrapper, .entry_wrapper, .literal_root, .unimplemented => {},
    }
    const sites = try sortedUniqueSites(allocator, found.items);
    errdefer allocator.free(sites);
    const result = try allocator.create(TemplateExhaustivenessSites);
    result.* = .{ .sites = sites };
    return result;
}

fn sortedUniqueSites(allocator: Allocator, sites: []CheckedExhaustivenessSiteId) Allocator.Error![]CheckedExhaustivenessSiteId {
    std.mem.sortUnstable(CheckedExhaustivenessSiteId, sites, {}, struct {
        fn lessThan(_: void, left: CheckedExhaustivenessSiteId, right: CheckedExhaustivenessSiteId) bool {
            return @backingInt(left) < @backingInt(right);
        }
    }.lessThan);
    var len: usize = 0;
    for (sites) |site| {
        if (len > 0 and sites[len - 1] == site) continue;
        sites[len] = site;
        len += 1;
    }
    return allocator.dupe(CheckedExhaustivenessSiteId, sites[0..len]);
}

/// Every exhaustiveness check of `owner` (an index of
/// `ModuleEnv.exhaustiveness_obligations`) with the owner and policy that
/// decide it. A check whose source no body reaches is decided by its checking
/// mode. Otherwise the first compile-time root, in root order, whose
/// evaluation replaces the check's source owns it, else the first template,
/// in template order, whose body reaches it; a template-owned check is
/// runtime reachable or compile-time only by whether the module's root
/// requests reach its template at runtime or only at compile time, and by
/// its checking mode when they reach it at neither.
///
/// A platform/app pairing decides its platform's checks (`platform_sites`)
/// by its own root requests: a template-owned check its requests reach at
/// runtime is runtime reachable, one they reach only at compile time is
/// compile-time only, and none waits for a further pairing.
pub fn computeExhaustivenessSites(
    allocator: Allocator,
    analyses: *ModuleAnalyses,
    owner: ImportedModuleView,
    platform_sites: ?*const CheckedExhaustivenessSiteTable,
) Allocator.Error!*CheckedExhaustivenessSiteTable {
    const root_requests = try owner.rootRequests();
    var reachability = try ExhaustivenessTemplateReachability.build(
        allocator,
        owner.key,
        root_requests,
        owner.checked_procedure_templates,
        owner.entry_wrappers,
        owner.callable_eval_templates,
        owner.top_level_procedure_bindings,
        owner.platform_required_bindings,
        owner.resolved_value_refs,
    );
    defer reachability.deinit();

    const sites = if (platform_sites) |platform|
        try pairingExhaustivenessSites(allocator, platform, &reachability)
    else
        try moduleExhaustivenessSites(allocator, analyses, owner, root_requests, &reachability);
    errdefer allocator.free(sites);
    const result = try allocator.create(CheckedExhaustivenessSiteTable);
    result.* = .{ .sites = sites };
    return result;
}

fn pairingExhaustivenessSites(
    allocator: Allocator,
    platform: *const CheckedExhaustivenessSiteTable,
    reachability: *const ExhaustivenessTemplateReachability,
) Allocator.Error![]CheckedExhaustivenessSite {
    const sites = try allocator.dupe(CheckedExhaustivenessSite, platform.sites);
    for (sites) |*site| {
        site.requires_pairing = false;
        if (site.owner) |owner| switch (owner) {
            .procedure_template => |template| {
                if (reachability.templateIsRuntimeReachable(template)) site.policy = .runtime_reachable else if (reachability.templateIsCompileTimeReachable(template)) site.policy = .compile_time_only;
            },
            .root => {},
        };
    }
    return sites;
}

fn moduleExhaustivenessSites(
    allocator: Allocator,
    analyses: *ModuleAnalyses,
    owner: ImportedModuleView,
    root_requests: *const RootRequestTable,
    reachability: *const ExhaustivenessTemplateReachability,
) Allocator.Error![]CheckedExhaustivenessSite {
    const bodies = owner.checked_bodies;
    const obligations = bodies.env.exhaustiveness_obligations.items.items;
    const sites = try allocator.alloc(CheckedExhaustivenessSite, obligations.len);
    errdefer allocator.free(sites);
    if (obligations.len == 0) return sites;

    // The first template, in template order, whose body reaches each check.
    const templates = owner.checked_procedure_templates.templates.items;
    const owner_templates = try allocator.alloc(?canonical.CheckedProcedureTemplateId, obligations.len);
    defer allocator.free(owner_templates);
    @memset(owner_templates, null);
    for (0..templates.len) |raw_template| {
        const template: canonical.CheckedProcedureTemplateId = @fromBackingInt(@intCast(raw_template));
        for ((try analyses.templateExhaustivenessSites(bodies, template)).sites) |site| {
            const slot = &owner_templates[@backingInt(site)];
            if (slot.* == null) slot.* = template;
        }
    }

    // The first compile-time root, in root order, whose evaluation replaces
    // each check's source.
    const replacing_roots = try allocator.alloc(?CompileTimeRoot, obligations.len);
    defer allocator.free(replacing_roots);
    @memset(replacing_roots, null);
    var found = std.ArrayList(CheckedExhaustivenessSiteId).empty;
    defer found.deinit(allocator);
    for (owner.compile_time_roots.roots) |root| {
        if (!compileTimeRootReplacesSourceOccurrence(root.kind)) continue;
        // A literal conversion converts literal data and contains no site.
        if (root.literalConversionKind() != null) continue;
        found.clearRetainingCapacity();
        if (root.hoisted_body) |body| switch (body) {
            .pattern_extraction, .pattern_validation => {
                const base_expr, const exact_pattern = switch (body) {
                    .pattern_extraction => |extraction| .{ extraction.base_expr, extraction.scrutinee_pattern },
                    .pattern_validation => |validation| .{ validation.base_expr, validation.scrutinee_pattern },
                    .expr, .pattern_error, .valueless_binding => unreachable, // the enclosing prong matches only pattern_extraction and pattern_validation
                };
                // Pattern roots evaluate both their match of the base
                // expression against the pattern and the base expression
                // itself.
                try bodies.appendExhaustivenessSitesAt(@backingInt(exact_pattern), .destructure_pattern, allocator, &found);
                try collectExhaustivenessSites(allocator, bodies, base_expr, &found);
            },
            // A rejected destructure binder's root crashes and contains no site.
            .pattern_error => continue,
            .expr, .valueless_binding => try collectExhaustivenessSites(allocator, bodies, root.rootExpr(), &found),
        } else try collectExhaustivenessSites(allocator, bodies, root.rootExpr(), &found);
        for (found.items) |site| {
            const slot = &replacing_roots[@backingInt(site)];
            if (slot.* == null) slot.* = root;
        }
    }

    const owner_artifact = owner.key.digest();
    for (obligations, sites, owner_templates, replacing_roots, 0..) |obligation, *site, owner_template_id, replacing_root, index| {
        const id: CheckedExhaustivenessSiteId = @fromBackingInt(@intCast(index));
        const kind: CheckedComptimeSiteKind = switch (obligation.source) {
            .match_expr => .match,
            .destructure_pattern => .destructure,
        };
        const checked_expr: ?CIR.Expr.Idx = switch (obligation.source) {
            .match_expr => |source_expr| source_expr,
            .destructure_pattern => null,
        };
        const checked_pattern: ?CIR.Pattern.Idx = switch (obligation.source) {
            .match_expr => null,
            .destructure_pattern => |source_pattern| source_pattern,
        };
        const source_is_reached = switch (obligation.source) {
            .match_expr => |source_expr| bodies.index().reachesExpr(source_expr),
            .destructure_pattern => |source_pattern| bodies.index().reachesPattern(source_pattern),
        };
        if (!source_is_reached) {
            // Checking may replace an erroneous enclosing expression with a
            // runtime-error node. Its child source occurrences are then
            // intentionally absent from the checked body graph, so no
            // evaluation reaches the site and its checking mode decides it.
            site.* = .{
                .id = id,
                .kind = kind,
                .region = obligation.region,
                .checked_expr = checked_expr,
                .checked_pattern = checked_pattern,
                .policy = .not_pending,
            };
            continue;
        }

        const owner_template: ?canonical.ProcedureTemplateRef = if (owner_template_id) |template_id| .{
            .artifact = owner_artifact,
            .proc_base = templates[template_id.index()].proc_base,
            .template = template_id,
        } else null;
        const policy: ExhaustivenessResolutionPolicy = if (replacing_root) |root|
            .{ .compile_time_replaced_by_root = root.id }
        else if (owner_template) |template_ref|
            if (reachability.templateIsRuntimeReachable(template_ref))
                .runtime_reachable
            else if (reachability.templateIsCompileTimeReachable(template_ref))
                .compile_time_only
            else switch (obligation.mode) {
                .static => .runtime_reachable,
                .empirical => .compile_time_only,
            }
        else switch (obligation.mode) {
            .empirical => .compile_time_only,
            .static => .runtime_reachable,
        };
        const requires_pairing = if (replacing_root) |root| blk: {
            for (root_requests.requests) |request| {
                if (request.compile_time_root == root.id) break :blk request.requires_pairing;
            }
            break :blk false;
        } else if (owner_template) |template| blk: {
            const template_index = reachability.localTemplateIndex(template).?;
            break :blk reachability.pairing_templates[template_index] and !reachability.runtime_templates[template_index];
        } else false;
        site.* = .{
            .id = id,
            .kind = kind,
            .region = obligation.region,
            .owner = if (replacing_root) |root|
                .{ .root = root.id }
            else if (owner_template) |template_ref|
                .{ .procedure_template = template_ref }
            else
                null,
            .checked_expr = checked_expr,
            .checked_pattern = checked_pattern,
            .policy = policy,
            .requires_pairing = requires_pairing,
        };
    }
    return sites;
}

/// Append the exhaustiveness checks within the checked expression tree
/// rooted at `root` to `found`. Nested lambdas' bodies are searched;
/// promoted procedures' bodies are their own templates'. Nodes wait on an
/// explicit stack, so body nesting never becomes native call depth.
fn collectExhaustivenessSites(
    allocator: Allocator,
    bodies: CheckedBodies,
    root: CIR.Expr.Idx,
    found: *std.ArrayList(CheckedExhaustivenessSiteId),
) Allocator.Error!void {
    const Node = union(enum) {
        expr: CIR.Expr.Idx,
        statement: CIR.Statement.Idx,
        pattern: CIR.Pattern.Idx,
    };
    var pending: std.ArrayList(Node) = .empty;
    defer pending.deinit(allocator);
    try pending.append(allocator, .{ .expr = root });
    while (pending.pop()) |node| switch (node) {
        .expr => |expr_id| {
            try bodies.appendExhaustivenessSitesAt(@backingInt(expr_id), .match_expr, allocator, found);
            switch (bodies.exprData(expr_id)) {
                .str => |segments| if (!bodies.quoteIsCustom(@backingInt(expr_id))) for (segments) |segment| try pending.append(allocator, .{ .expr = segment }),
                .list, .tuple => |items| for (items) |item| try pending.append(allocator, .{ .expr = item }),
                .match_ => |match| {
                    try pending.append(allocator, .{ .expr = match.cond });
                    for (match.branches) |branch_idx| {
                        const branch = bodies.matchBranch(branch_idx);
                        for (branch.patterns) |branch_pattern| try pending.append(allocator, .{ .pattern = bodies.matchBranchPattern(branch_pattern).pattern });
                        if (branch.guard) |guard| try pending.append(allocator, .{ .expr = guard });
                        try pending.append(allocator, .{ .expr = branch.value });
                    }
                },
                .if_ => |if_| {
                    for (if_.branches) |branch_idx| {
                        const branch = bodies.ifBranch(branch_idx);
                        try pending.append(allocator, .{ .expr = branch.cond });
                        try pending.append(allocator, .{ .expr = branch.body });
                    }
                    try pending.append(allocator, .{ .expr = if_.final_else });
                },
                .call => |call| {
                    try pending.append(allocator, .{ .expr = call.func });
                    for (call.args) |arg| try pending.append(allocator, .{ .expr = arg });
                },
                .record => |record| {
                    if (record.ext) |ext| try pending.append(allocator, .{ .expr = ext });
                    for (record.fields) |field| try pending.append(allocator, .{ .expr = bodies.recordFieldValue(field) });
                },
                .block => |block| {
                    for (block.statements) |statement| try pending.append(allocator, .{ .statement = statement });
                    try pending.append(allocator, .{ .expr = block.final_expr });
                },
                .tag => |tag| for (tag.args) |arg| try pending.append(allocator, .{ .expr = arg }),
                .nominal => |nominal| try pending.append(allocator, .{ .expr = nominal.backing_expr }),
                .closure => |closure| try pending.append(allocator, .{ .expr = closure.lambda }),
                .lambda => |lambda| {
                    for (lambda.args) |arg| try pending.append(allocator, .{ .pattern = arg });
                    try pending.append(allocator, .{ .expr = lambda.body });
                },
                .binop => |binop| {
                    try pending.append(allocator, .{ .expr = binop.lhs });
                    try pending.append(allocator, .{ .expr = binop.rhs });
                },
                .unary_minus, .dbg, .expect => |child| try pending.append(allocator, .{ .expr = child }),
                .tuple_access => |access| try pending.append(allocator, .{ .expr = access.tuple }),
                .field_access => |field| try pending.append(allocator, .{ .expr = field.receiver }),
                .interpolation => |interpolation| {
                    try pending.append(allocator, .{ .expr = interpolation.first });
                    for (interpolation.parts) |part| try pending.append(allocator, .{ .expr = part });
                },
                .structural_eq => |eq| {
                    try pending.append(allocator, .{ .expr = eq.lhs });
                    try pending.append(allocator, .{ .expr = eq.rhs });
                },
                .structural_hash => |h| {
                    try pending.append(allocator, .{ .expr = h.value });
                    try pending.append(allocator, .{ .expr = h.hasher });
                },
                .expect_err => |expect_err| try pending.append(allocator, .{ .expr = expect_err.expr }),
                .return_ => |ret| try pending.append(allocator, .{ .expr = ret.expr }),
                .for_ => |for_| {
                    try pending.append(allocator, .{ .pattern = for_.pattern });
                    try pending.append(allocator, .{ .expr = for_.expr });
                    try pending.append(allocator, .{ .expr = for_.body });
                },
                .run_low_level => |run| for (run.args) |arg| try pending.append(allocator, .{ .expr = arg }),
                .hosted_lambda => |hosted| for (hosted.args) |arg| try pending.append(allocator, .{ .pattern = arg }),
                .numeral,
                .str_segment,
                .bytes_literal,
                .lookup_local,
                .lookup_external,
                .lookup_required,
                .empty_list,
                .empty_record,
                .zero_argument_tag,
                .dispatch_call,
                .method_eq,
                .type_dispatch_call,
                .runtime_error,
                .crash,
                .break_,
                .ellipsis,
                .anno_only,
                => {},
            }
        },
        .statement => |statement_id| switch (bodies.statementData(statement_id)) {
            .decl => |decl| {
                try pending.append(allocator, .{ .pattern = decl.pattern });
                try pending.append(allocator, .{ .expr = decl.expr });
            },
            // The promoted procedure's lambda is its own template's body.
            .promoted_proc => |promoted| try pending.append(allocator, .{ .pattern = promoted.pattern }),
            .var_ => |var_| {
                try pending.append(allocator, .{ .pattern = var_.pattern });
                try pending.append(allocator, .{ .expr = var_.expr });
            },
            .var_uninitialized => |var_| try pending.append(allocator, .{ .pattern = var_.pattern }),
            .reassign => |reassign| {
                try pending.append(allocator, .{ .pattern = reassign.pattern });
                try pending.append(allocator, .{ .expr = reassign.expr });
            },
            .dbg, .expr, .expect => |expr| try pending.append(allocator, .{ .expr = expr }),
            .for_ => |for_| {
                try pending.append(allocator, .{ .pattern = for_.pattern });
                try pending.append(allocator, .{ .expr = for_.expr });
                try pending.append(allocator, .{ .expr = for_.body });
            },
            .while_, .infinite_loop, .breakable_loop => |loop| {
                try pending.append(allocator, .{ .expr = loop.cond });
                try pending.append(allocator, .{ .expr = loop.body });
            },
            .return_ => |ret| try pending.append(allocator, .{ .expr = ret.expr }),
            .crash,
            .break_,
            .rejected_method_decl,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => {},
        },
        .pattern => |pattern_id| {
            try bodies.appendExhaustivenessSitesAt(@backingInt(pattern_id), .destructure_pattern, allocator, found);
            switch (bodies.patternData(pattern_id)) {
                .as => |as| try pending.append(allocator, .{ .pattern = as.pattern }),
                .applied_tag => |tag| for (tag.args) |arg| try pending.append(allocator, .{ .pattern = arg }),
                .nominal => |nominal| try pending.append(allocator, .{ .pattern = nominal.backing_pattern }),
                .record_destructure => |destructs| for (destructs) |destruct| {
                    try pending.append(allocator, .{ .pattern = bodies.recordDestructPattern(destruct) });
                },
                .list => |list| {
                    for (list.patterns) |child| try pending.append(allocator, .{ .pattern = child });
                    if (list.rest) |rest| if (rest.pattern) |rest_pattern| try pending.append(allocator, .{ .pattern = rest_pattern });
                },
                .tuple => |items| for (items) |item| try pending.append(allocator, .{ .pattern = item }),
                .str_interpolation => |str| {
                    var offset: u32 = 0;
                    while (offset < str.steps.span.len) : (offset += 1) {
                        if (bodies.strPatternStep(str.steps, offset).capture) |capture| try pending.append(allocator, .{ .pattern = capture });
                    }
                },
                .assign,
                .numeral_literal,
                .str_literal,
                .underscore,
                .runtime_error,
                => {},
            }
        },
    };
}

fn compileTimeRootReplacesSourceOccurrence(kind: CompileTimeRootKind) bool {
    return switch (kind) {
        .constant,
        .hoisted_constant,
        .hoisted_validation,
        .numeral_conversion,
        .quote_conversion,
        .repl_expr,
        .literal_argument,
        => true,
        .callable_binding,
        .expect,
        => false,
    };
}

fn reachedRootExpr(module_index: *const ModuleIndex, expr: CIR.Expr.Idx) CIR.Expr.Idx {
    if (!module_index.reachesExpr(expr)) {
        checkedArtifactInvariant("a compile-time root's expression {d} is not reached by the checked bodies", .{@backingInt(expr)});
    }
    return expr;
}

fn reachedRootPattern(module_index: *const ModuleIndex, pattern: CIR.Pattern.Idx) CIR.Pattern.Idx {
    if (!module_index.reachesPattern(pattern)) {
        checkedArtifactInvariant("a compile-time root's pattern {d} is not reached by the checked bodies", .{@backingInt(pattern)});
    }
    return pattern;
}

const SelectedHoistedRootBody = struct {
    expr: CIR.Expr.Idx,
    pattern: ?CIR.Pattern.Idx,
    checked_type: CheckedTypeId,
};

/// A selected hoisted root's expression, binding pattern, and value type. A
/// pattern root's body is the lowering-side construct its `hoisted_body`
/// describes; its expression is the selected expression it matches.
fn selectedHoistedRootBody(
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *CheckedTypePublication,
    module_index: *const ModuleIndex,
    selected: hoist_roots.SelectedHoistedRoot,
) Allocator.Error!SelectedHoistedRootBody {
    return switch (selected.body) {
        .expr => .{
            .expr = reachedRootExpr(module_index, selected.expr),
            .pattern = if (selected.pattern) |pattern| reachedRootPattern(module_index, pattern) else null,
            .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, if (selected.pattern) |pattern| ModuleEnv.varFrom(pattern) else module.exprType(selected.expr)),
        },
        .pattern_error => blk: {
            const pattern = selected.pattern orelse
                checkedArtifactInvariant("pattern-error hoisted root has no binding pattern", .{});
            break :blk .{
                .expr = selected.expr,
                .pattern = reachedRootPattern(module_index, pattern),
                .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, ModuleEnv.varFrom(pattern)),
            };
        },
        .pattern_extraction => |extraction| .{
            .expr = reachedRootExpr(module_index, extraction.base_expr),
            .pattern = reachedRootPattern(module_index, extraction.result_pattern),
            .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, ModuleEnv.varFrom(extraction.result_pattern)),
        },
        .pattern_validation => |validation| .{
            .expr = reachedRootExpr(module_index, validation.base_expr),
            .pattern = reachedRootPattern(module_index, validation.scrutinee_pattern),
            .checked_type = try checked_types.store.ensureEmptyRecordRoot(allocator),
        },
        // The right-hand side always crashes, so the root produces no value:
        // like a validation root, its discarded result is unit-valued.
        .valueless_binding => .{
            .expr = reachedRootExpr(module_index, selected.expr),
            .pattern = null,
            .checked_type = try checked_types.store.ensureEmptyRecordRoot(allocator),
        },
    };
}

/// Public `ConstRef` declaration.
pub const ConstRef = struct {
    artifact: CheckedModuleDigest,
    owner: ConstOwner,
    template: ConstTemplateId,
    source_scheme: CheckedTypeSchemeId,
};

/// Public checked constant locator declaration.
pub const ConstLocator = ConstRef;

/// Return the checked module id that owns a compile-time constant.
pub fn constModuleId(ref: ConstRef) ModuleId {
    return ref.artifact;
}

/// Public `ConstOwner` declaration.
pub const ConstOwner = union(enum(u8)) {
    top_level_binding: ConstTopLevelOwner,
    hoisted_root: ConstHoistedOwner,
};

/// Public `ConstTopLevelOwner` declaration.
pub const ConstTopLevelOwner = struct {
    module_idx: u32,
    pattern: CIR.Pattern.Idx,
};

/// Public `ConstHoistedOwner` declaration.
pub const ConstHoistedOwner = struct {
    module_idx: u32,
    /// The hoisted constant's compile-time root. Several roots can match one
    /// expression (one per binder of a destructure), so the root identifies
    /// the constant.
    root: ComptimeRootId,
};

/// Public `TopLevelValueKind` declaration.
pub const TopLevelValueKind = union(enum) {
    const_ref: ConstRef,
    procedure_binding: TopLevelProcedureBindingRef,
};

/// Public `TopLevelValueEntry` declaration.
pub const TopLevelValueEntry = struct {
    module_idx: u32,
    def: CIR.Def.Idx,
    pattern: CIR.Pattern.Idx,
    source_name: canonical.ExportNameId,
    source_scheme: CheckedTypeSchemeId,
    value: TopLevelValueKind,
};

const TopLevelValueByDefEntry = struct {
    def: CIR.Def.Idx,
    entry: u32,

    fn lessThan(_: void, lhs: TopLevelValueByDefEntry, rhs: TopLevelValueByDefEntry) bool {
        return @backingInt(lhs.def) < @backingInt(rhs.def);
    }
};

const TopLevelValueByPatternEntry = struct {
    pattern: CIR.Pattern.Idx,
    entry: u32,

    fn order(item: TopLevelValueByPatternEntry, key: CIR.Pattern.Idx) std.math.Order {
        return std.math.order(@backingInt(item.pattern), @backingInt(key));
    }

    fn lessThan(_: void, a: TopLevelValueByPatternEntry, b: TopLevelValueByPatternEntry) bool {
        return @backingInt(a.pattern) < @backingInt(b.pattern);
    }
};

/// Public `TopLevelValueTable` declaration.
pub const TopLevelValueTable = struct {
    entries: []TopLevelValueEntry = &.{},
    /// Entries by pattern, ascending.
    by_pattern: []TopLevelValueByPatternEntry = &.{},
    by_def: []TopLevelValueByDefEntry = &.{},

    pub const Serialized = extern struct {
        entries: SerializedSlice(TopLevelValueEntry) = .{},
        by_pattern: SerializedSlice(TopLevelValueByPatternEntry) = .{},
        by_def: SerializedSlice(TopLevelValueByDefEntry) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(TopLevelValueTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        value_binding_defs: []const CIR.Def.Idx,
        names: *canonical.CanonicalNameStore,
        module_index: *const ModuleIndex,
        templates: *const CheckedProcedureTemplateTable,
        callable_eval_templates: *CallableEvalTemplateTable,
        procedure_bindings: *TopLevelProcedureBindingTable,
        const_templates: *ConstTemplateTable,
        artifact_key: CheckedModuleArtifactKey,
        compile_time_roots: *const CompileTimeRootTable,
        checked_type_publication: *const CheckedTypePublication,
    ) Allocator.Error!TopLevelValueTable {
        var entries = std.ArrayList(TopLevelValueEntry).empty;
        errdefer entries.deinit(allocator);

        var by_pattern = std.ArrayList(TopLevelValueByPatternEntry).empty;
        errdefer by_pattern.deinit(allocator);

        var by_def = std.ArrayList(TopLevelValueByDefEntry).empty;
        errdefer by_def.deinit(allocator);

        for (value_binding_defs) |def_idx| {
            const def = module.def(def_idx);
            if (def.expr.data == .e_derived_method) {
                checkedArtifactInvariant("generated method marker reached top-level-value publication", .{});
            }
            const checked_pattern = reachedRootPattern(module_index, def.pattern.idx);
            const source_name = try topLevelDefSourceName(module, names, def) orelse continue;
            const source_ty = module.defType(def_idx);
            const source_scheme = checked_type_publication.schemeForSourceVar(module, source_ty);
            const value: TopLevelValueKind = if (templates.lookupByDef(def_idx)) |template| blk: {
                const binding = try procedure_bindings.appendDirect(
                    allocator,
                    source_scheme,
                    .{ .artifact = template.artifact, .proc_base = template.proc_base },
                    template,
                );
                break :blk .{ .procedure_binding = binding };
            } else if (sourceTypeIsFunction(module, source_ty)) blk: {
                if (def.expr.data == .e_runtime_error) {
                    break :blk .{ .procedure_binding = try procedure_bindings.appendCheckedError(
                        allocator,
                        source_scheme,
                        reachedRootExpr(module_index, def.expr.idx),
                    ) };
                }
                const root_id = compile_time_roots.lookupIdByPattern(checked_pattern) orelse {
                    base.invariant(
                        "checked artifact invariant violated: function-valued binding {d} has no compile-time callable root",
                        .{@backingInt(def.pattern.idx)},
                    );
                };
                const root = compile_time_roots.root(root_id);
                if (root.kind != .callable_binding) {
                    base.invariant(
                        "checked artifact invariant violated: function-valued binding {d} mapped to non-callable compile-time root",
                        .{@backingInt(def.pattern.idx)},
                    );
                }
                const checked_fn_root = root.checked_type;
                const callable_template = try callable_eval_templates.append(
                    allocator,
                    module.moduleIndex(),
                    checked_pattern,
                    root_id,
                    source_scheme,
                    checked_fn_root,
                );
                const binding = try procedure_bindings.appendCallableEval(
                    allocator,
                    source_scheme,
                    callable_template,
                );
                break :blk .{ .procedure_binding = binding };
            } else if (def.expr.data == .e_anno_only) .{ .const_ref = try const_templates.reserveUnimplementedTopLevel(
                allocator,
                artifact_key,
                module.moduleIndex(),
                checked_pattern,
                source_scheme,
                .{ .region = module.regionAt(ModuleEnv.nodeIdxFrom(def.expr.idx)) },
            ) } else .{ .const_ref = try const_templates.reserveTopLevel(
                allocator,
                artifact_key,
                module.moduleIndex(),
                checked_pattern,
                source_scheme,
            ) };

            const entry_idx: u32 = @intCast(entries.items.len);
            try entries.append(allocator, .{
                .module_idx = module.moduleIndex(),
                .def = def_idx,
                .pattern = checked_pattern,
                .source_name = source_name,
                .source_scheme = source_scheme,
                .value = value,
            });
            try by_pattern.append(allocator, .{ .pattern = checked_pattern, .entry = entry_idx });
            try by_def.append(allocator, .{
                .def = def_idx,
                .entry = entry_idx,
            });
        }

        std.mem.sort(TopLevelValueByDefEntry, by_def.items, {}, TopLevelValueByDefEntry.lessThan);
        std.mem.sort(TopLevelValueByPatternEntry, by_pattern.items, {}, TopLevelValueByPatternEntry.lessThan);
        const entry_slice = try entries.toOwnedSlice(allocator);
        errdefer allocator.free(entry_slice);
        const by_pattern_slice = try by_pattern.toOwnedSlice(allocator);
        errdefer allocator.free(by_pattern_slice);
        const by_def_slice = try by_def.toOwnedSlice(allocator);
        return .{
            .entries = entry_slice,
            .by_pattern = by_pattern_slice,
            .by_def = by_def_slice,
        };
    }

    pub fn lookupByPattern(self: *const TopLevelValueTable, pattern: CIR.Pattern.Idx) ?TopLevelValueEntry {
        const found = artifact_serialize.binarySearchByKey(TopLevelValueByPatternEntry, CIR.Pattern.Idx, self.by_pattern, pattern, TopLevelValueByPatternEntry.order) orelse return null;
        return self.entries[found.entry];
    }

    pub fn lookupByDef(self: *const TopLevelValueTable, def: CIR.Def.Idx) ?TopLevelValueEntry {
        var lo: usize = 0;
        var hi: usize = self.by_def.len;
        const target = @backingInt(def);
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const candidate = @backingInt(self.by_def[mid].def);
            if (candidate < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= self.by_def.len or self.by_def[lo].def != def) return null;
        return self.entries[self.by_def[lo].entry];
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;
};

/// Public `HoistedConstId` declaration.
pub const HoistedConstId = enum(u32) { _ };

/// Public `HoistedConstEntry` declaration.
pub const HoistedConstEntry = struct {
    id: HoistedConstId,
    module_idx: u32,
    root: ComptimeRootId,
    expr: CIR.Expr.Idx,
    pattern: ?CIR.Pattern.Idx,
    checked_type: CheckedTypeId,
    source_scheme: CheckedTypeSchemeId,
    const_ref: ConstRef,
};

const HoistedConstByExprEntry = struct {
    expr: CIR.Expr.Idx,
    entry: HoistedConstId,

    fn lessThan(_: void, lhs: HoistedConstByExprEntry, rhs: HoistedConstByExprEntry) bool {
        return @backingInt(lhs.expr) < @backingInt(rhs.expr);
    }
};

const HoistedConstByPatternEntry = struct {
    pattern: CIR.Pattern.Idx,
    entry: HoistedConstId,

    fn lessThan(_: void, lhs: HoistedConstByPatternEntry, rhs: HoistedConstByPatternEntry) bool {
        return @backingInt(lhs.pattern) < @backingInt(rhs.pattern);
    }
};

/// Public `HoistedConstTable` declaration.
///
/// Sparse index for selected hoisted constants. Every entry corresponds to a
/// published `.hoisted_constant` root. The by-expr, by-pattern, and by-root
/// indexes are lookup accelerators for later stages; there is no data here for
/// unselected expressions or patterns, and no scheduling/dependency metadata.
pub const HoistedConstTable = struct {
    entries: []HoistedConstEntry = &.{},
    by_expr: []HoistedConstByExprEntry = &.{},
    by_pattern: []HoistedConstByPatternEntry = &.{},
    by_root: []?HoistedConstId = &.{},

    pub const Serialized = extern struct {
        entries: SerializedSlice(HoistedConstEntry) = .{},
        by_expr: SerializedSlice(HoistedConstByExprEntry) = .{},
        by_pattern: SerializedSlice(HoistedConstByPatternEntry) = .{},
        by_root: SerializedSlice(?HoistedConstId) = .{},

        const Serde = artifact_serialize.SliceStoreSerde(HoistedConstTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromRoots(
        allocator: Allocator,
        module: TypedCIR.Module,
        artifact_key: CheckedModuleArtifactKey,
        checked_types: *CheckedTypeStore,
        roots: *const CompileTimeRootTable,
        const_templates: *ConstTemplateTable,
        checked_type_publication: *const CheckedTypePublication,
    ) Allocator.Error!HoistedConstTable {
        var entries = std.ArrayList(HoistedConstEntry).empty;
        errdefer entries.deinit(allocator);

        var by_expr = std.ArrayList(HoistedConstByExprEntry).empty;
        errdefer by_expr.deinit(allocator);

        var by_pattern = std.ArrayList(HoistedConstByPatternEntry).empty;
        errdefer by_pattern.deinit(allocator);

        const by_root = try allocator.alloc(?HoistedConstId, roots.roots.len);
        errdefer allocator.free(by_root);
        @memset(by_root, null);

        for (roots.roots) |root| {
            if (root.kind != .hoisted_constant) continue;
            const source_expr = switch (root.source) {
                .hoisted => |hoisted| hoisted.expr,
                .def,
                .expr,
                .statement,
                .required_binding,
                .literal,
                => checkedArtifactInvariant("hoisted constant root had non-expression source", .{}),
            };
            const source_var = if (root.source_pattern) |pattern|
                ModuleEnv.varFrom(pattern)
            else
                ModuleEnv.varFrom(source_expr);
            const source_scheme = if (root.hoisted_body) |body| switch (body) {
                .pattern_validation => try checked_types.ensureSchemeForRoot(allocator, root.checked_type),
                .expr, .pattern_extraction, .pattern_error => checked_type_publication.schemeForSourceVar(module, source_var),
                .valueless_binding => checkedArtifactInvariant("valueless binding root was published as a hoisted constant", .{}),
            } else checked_type_publication.schemeForSourceVar(module, source_var);
            const const_ref = try const_templates.reserveHoisted(
                allocator,
                artifact_key,
                module.moduleIndex(),
                root.id,
                source_scheme,
            );
            const id: HoistedConstId = @fromBackingInt(@intCast(@as(u32, @intCast(entries.items.len))));
            try entries.append(allocator, .{
                .id = id,
                .module_idx = module.moduleIndex(),
                .root = root.id,
                .expr = root.rootExpr(),
                .pattern = root.pattern,
                .checked_type = root.checked_type,
                .source_scheme = source_scheme,
                .const_ref = const_ref,
            });
            // Only a root that evaluates its expression stands for that
            // expression's occurrence.
            if (root.evaluatedExpr()) |evaluated| try by_expr.append(allocator, .{
                .expr = evaluated,
                .entry = id,
            });
            if (root.pattern) |pattern| {
                try by_pattern.append(allocator, .{
                    .pattern = pattern,
                    .entry = id,
                });
            }
            by_root[root.id.index()] = id;
        }

        std.mem.sort(HoistedConstByExprEntry, by_expr.items, {}, HoistedConstByExprEntry.lessThan);
        std.mem.sort(HoistedConstByPatternEntry, by_pattern.items, {}, HoistedConstByPatternEntry.lessThan);

        const entry_slice = try entries.toOwnedSlice(allocator);
        errdefer allocator.free(entry_slice);
        const by_expr_slice = try by_expr.toOwnedSlice(allocator);
        errdefer allocator.free(by_expr_slice);
        const by_pattern_slice = try by_pattern.toOwnedSlice(allocator);

        return .{
            .entries = entry_slice,
            .by_expr = by_expr_slice,
            .by_pattern = by_pattern_slice,
            .by_root = by_root,
        };
    }

    pub fn lookupByExpr(self: *const HoistedConstTable, expr: CIR.Expr.Idx) ?HoistedConstEntry {
        var lo: usize = 0;
        var hi: usize = self.by_expr.len;
        const target = @backingInt(expr);
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const candidate = @backingInt(self.by_expr[mid].expr);
            if (candidate < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= self.by_expr.len or self.by_expr[lo].expr != expr) return null;
        return self.entries[@backingInt(self.by_expr[lo].entry)];
    }

    pub fn lookupByPattern(self: *const HoistedConstTable, pattern: CIR.Pattern.Idx) ?HoistedConstEntry {
        var lo: usize = 0;
        var hi: usize = self.by_pattern.len;
        const target = @backingInt(pattern);
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const candidate = @backingInt(self.by_pattern[mid].pattern);
            if (candidate < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= self.by_pattern.len or self.by_pattern[lo].pattern != pattern) return null;
        return self.entries[@backingInt(self.by_pattern[lo].entry)];
    }

    pub fn lookupByRoot(self: *const HoistedConstTable, root: ComptimeRootId) ?HoistedConstEntry {
        const idx = root.rowIndex() orelse return null;
        if (idx >= self.by_root.len) return null;
        const entry_id = self.by_root[idx] orelse return null;
        return self.entries[@backingInt(entry_id)];
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;
};

/// Public `CheckedCallableBodyRef` declaration.
pub const CheckedCallableBodyRef = enum(u32) { _ };
/// Public `CheckedConstBodyRef` declaration.
pub const CheckedConstBodyRef = enum(u32) { _ };
/// Public `ConstTemplateId` declaration.
pub const ConstTemplateId = enum(u32) { _ };

/// Public `CheckedConstBody` declaration.
pub const CheckedConstBody = struct {
    id: CheckedConstBodyRef,
    root: ComptimeRootId,
    body_expr: CIR.Expr.Idx,
    checked_type: CheckedTypeId,
};

/// Public `CheckedConstBodyTable` declaration.
pub const CheckedConstBodyTable = struct {
    bodies: []CheckedConstBody = &.{},
    by_root: []?CheckedConstBodyRef = &.{},

    pub const Serialized = extern struct {
        bodies: SerializedSlice(CheckedConstBody) = .{},
        by_root: SerializedSlice(?CheckedConstBodyRef) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(CheckedConstBodyTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromRoots(
        allocator: Allocator,
        roots: *const CompileTimeRootTable,
    ) Allocator.Error!CheckedConstBodyTable {
        var bodies = std.ArrayList(CheckedConstBody).empty;
        errdefer bodies.deinit(allocator);

        const by_root = try allocator.alloc(?CheckedConstBodyRef, roots.roots.len);
        errdefer allocator.free(by_root);
        @memset(by_root, null);

        for (roots.roots) |root| {
            if (!compileTimeRootHasConstBody(root.kind)) continue;
            const id: CheckedConstBodyRef = @fromBackingInt(@intCast(@as(u32, @intCast(bodies.items.len))));
            try bodies.append(allocator, .{
                .id = id,
                .root = root.id,
                .body_expr = root.rootExpr(),
                .checked_type = root.checked_type,
            });
            by_root[root.id.index()] = id;
        }

        return .{
            .bodies = try bodies.toOwnedSlice(allocator),
            .by_root = by_root,
        };
    }

    pub fn bodyForRoot(self: *const CheckedConstBodyTable, root: ComptimeRootId) ?CheckedConstBodyRef {
        const idx = root.rowIndex() orelse return null;
        if (idx >= self.by_root.len) return null;
        return self.by_root[idx];
    }

    pub fn get(self: *const CheckedConstBodyTable, id: CheckedConstBodyRef) CheckedConstBody {
        const idx = @backingInt(id);
        if (idx >= self.bodies.len) checkedArtifactInvariant("checked const body id is out of range", .{});
        return self.bodies[idx];
    }

    pub const deinit = artifact_serialize.SliceStoreDeinit(@This()).deinit;
};

