test "mixed field-access segment labels are lowering-visible" {
    const allocator = std.testing.allocator;
    var module_env = try ModuleEnv.init(allocator, "");
    defer module_env.deinit();
    try module_env.initCIRFields("Test");

    const required_name = try module_env.insertIdent(Ident.for_text("required_field"));
    const optional_name = try module_env.insertIdent(Ident.for_text("optional_field"));
    const receiver = try module_env.addExpr(.{ .e_empty_record = .{} }, base.Region.zero());

    const path = try module_env.startFieldAccessPath(2);
    _ = module_env.appendFieldAccessPathSegmentAssumeCapacity(path, .{
        .name = optional_name,
        .mode = .optional,
    }, base.Region.zero());
    _ = module_env.appendFieldAccessPathSegmentAssumeCapacity(path, .{
        .name = required_name,
        .mode = .required,
    }, base.Region.zero());
    const segments = module_env.finishFieldAccessPath(path);
    _ = try module_env.addExpr(.{ .e_field_access = .{
        .receiver = receiver,
        .segments = segments,
    } }, base.Region.zero());

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    try internLoweringVisibleNames(&module_env, &names);

    const idents = module_env.getIdentStoreConst();
    try std.testing.expect(names.lookupRecordFieldIdent(idents, required_name) != null);
    try std.testing.expect(names.lookupRecordFieldIdent(idents, optional_name) != null);
    verifyLoweringVisibleNamesInterned(&module_env, &names);
}

/// Public `loweringView` function.
pub fn loweringView(artifact: *const CheckedModuleArtifact) Allocator.Error!LoweringModuleView {
    return .{
        .module = artifact,
        .roots = try artifact.rootRequests(),
        .relation_modules = &.{},
    };
}

/// Public `loweringViewWithRelations` function.
pub fn loweringViewWithRelations(
    artifact: *const CheckedModuleArtifact,
    relation_artifacts: []const ImportedModuleView,
) Allocator.Error!LoweringModuleView {
    return .{
        .module = artifact,
        .roots = try artifact.rootRequests(),
        .relation_modules = relation_artifacts,
    };
}

/// Inputs from imported modules and platform relation checking that participate
/// in the checked module cache identity.
pub const CheckedModuleKeyInputs = struct {
    imports: []const PublishImportArtifact = &.{},
    platform_requirement_context: ?PlatformRequirementContextKey = null,
    platform_app_relation: ?PlatformAppRelationKey = null,
    explicit_roots: []const ExplicitRootRequestInput = &.{},
    validation: can.Can.Validation = .checking,
};

/// Compute the checked module cache identity for a module environment whose
/// imports are resolved, and the checked data it depends on. The identity
/// reads only the environment's source inputs, content identity, and resolved
/// imports, so it needs no typed module graph.
pub fn checkedModuleKeyFromModuleEnv(
    allocator: Allocator,
    module_env: *const ModuleEnv,
    inputs: CheckedModuleKeyInputs,
) Allocator.Error!CheckedModuleArtifactKey {
    var checking_context_identity = try CheckingContextIdentity.fromModule(
        allocator,
        module_env,
        inputs.imports,
        inputs.platform_requirement_context,
        inputs.platform_app_relation,
        inputs.explicit_roots,
        inputs.validation,
    );
    defer checking_context_identity.deinit(allocator);

    const direct_import_module_keys = try directImportArtifactKeysFromModule(allocator, module_env, inputs.imports);
    defer allocator.free(direct_import_module_keys);

    return CheckedModuleArtifactKey.computeFromIdentityHash(
        hashModuleSourceInputs(module_env),
        computeStableModuleIdentityHash(module_env),
        checking_context_identity,
        direct_import_module_keys,
    );
}

/// Inference admission is deliberately separate from artifact identity. The
/// producer-owned checking scope supplies dependency facts and owner equality;
/// the full imported implementation keys continue to key every publication.
pub fn inferenceKeyFromModuleEnv(
    module_env: *const ModuleEnv,
    scope_hash: [32]u8,
    platform_requirement_owner: ?u32,
    explicit_roots: []const ExplicitRootRequestInput,
    validation: can.Can.Validation,
    source_pin_validation: [32]u8,
    missing_public_types: []const []const u8,
) [32]u8 {
    var hasher = base.Sha256.init(.{});
    hasher.update("roc-inference-inputs-v2");
    hasher.update(&hashModuleSourceInputs(module_env));
    hasher.update(&scope_hash);
    hashByteSlice(&hasher, module_env.module_name);
    hashByteSlice(&hasher, @tagName(module_env.module_kind));
    hashByteSlice(&hasher, @tagName(module_env.module_role));
    if (platform_requirement_owner) |owner| {
        hasher.update(&.{1});
        hashU32(&hasher, owner);
    } else hasher.update(&.{0});
    hashByteSlice(&hasher, @tagName(validation));
    hasher.update(&source_pin_validation);
    hashU32(&hasher, @intCast(explicit_roots.len));
    for (explicit_roots) |root| hashExplicitRootRequestInput(&hasher, root);
    const imports = module_env.imports.imports.items.items;
    hashU32(&hasher, @intCast(imports.len));
    for (imports, 0..) |name, i| {
        hashByteSlice(&hasher, module_env.getString(name));
        const import_idx: CIR.Import.Idx = @fromBackingInt(@as(u32, @intCast(i)));
        hashU32(&hasher, module_env.imports.getResolvedModule(import_idx) orelse std.math.maxInt(u32));
    }
    hashU32(&hasher, @intCast(missing_public_types.len));
    for (missing_public_types) |name| hashByteSlice(&hasher, name);
    return hasher.finalResult();
}

/// The reader publication passes read bodies through. Each pass builds a
/// fresh one, so its type view sees every type published so far.
fn publicationBodies(
    env: *const ModuleEnv,
    names: *const canonical.CanonicalNameStore,
    checked_type_publication: *const CheckedTypePublication,
    analyses: *BodyAnalyses,
    tables: checked_bodies_mod.Tables,
) CheckedBodies {
    return .{
        .env = env,
        .names = names,
        .types = checked_type_publication.store.view(),
        .analyses = analyses,
        .tables = tables,
    };
}

/// The images of the module's source types a platform/app relation the
/// module is published with substitutes.
fn publicationPairingTypes(allocator: Allocator, checked_type_publication: *const CheckedTypePublication) Allocator.Error!PairingTypeColumn {
    const substituted = &checked_type_publication.source_types.?.substituted;
    if (substituted.count() == 0) return .{};
    const images = try allocator.alloc(PairingTypeImage, substituted.count());
    var entries = substituted.constIterator();
    var index: usize = 0;
    while (entries.next()) |entry| : (index += 1) {
        images[index] = .{ .own = type_ids.fromVar(entry.key_ptr.*), .image = entry.value_ptr.* };
    }
    std.mem.sort(PairingTypeImage, images, {}, PairingTypeImage.lessThan);
    return .{ .images = images };
}

/// The defaulted-field expressions this module declares that its published
/// types or its record constructions name, ascending.
fn publicationDefaultExprs(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    checked_type_publication: *const CheckedTypePublication,
) Allocator.Error![]CIR.Expr.Idx {
    const module_env = module.moduleEnvConst();
    const self_origin = try names.internModuleIdentity(module_env.moduleIdentityHash(module_env.selfModuleIdentity()));
    var defaults = std.ArrayList(CIR.Expr.Idx).empty;
    errdefer defaults.deinit(allocator);
    for (checked_type_publication.store.record_field_pool.items()) |field| {
        const default = field.kind.defaultIdentity() orelse continue;
        const default_origin = default.origin() orelse
            checkedArtifactInvariant("checked defaulted field kind carried no default identity", .{});
        if (default_origin != self_origin) continue;
        try defaults.append(allocator, @fromBackingInt(@intCast(default.expr_node)));
    }
    for (module_env.record_omitted_defaults.items.items) |omitted| {
        const origin_module = try names.internModuleIdentity(module_env.moduleIdentityHash(omitted.origin_module));
        if (origin_module != self_origin) continue;
        try defaults.append(allocator, @fromBackingInt(@intCast(omitted.default_expr_node)));
    }
    std.mem.sort(CIR.Expr.Idx, defaults.items, {}, struct {
        fn lessThan(_: void, a: CIR.Expr.Idx, b: CIR.Expr.Idx) bool {
            return @backingInt(a) < @backingInt(b);
        }
    }.lessThan);
    var len: usize = 0;
    for (defaults.items) |default| {
        if (len > 0 and defaults.items[len - 1] == default) continue;
        defaults.items[len] = default;
        len += 1;
    }
    defaults.shrinkRetainingCapacity(len);
    return defaults.toOwnedSlice(allocator);
}

/// Public `publishFromTypedModule` function.
pub fn publishFromTypedModule(
    allocator: Allocator,
    modules: *const TypedCIR.Modules,
    module_idx: u32,
    inputs: PublishInputs,
) CompileTimeFinalizer.Error!CheckedModuleArtifact {
    const module = modules.module(module_idx);
    const module_env = module.moduleEnvConst();
    if (std.debug.runtime_safety and !module_env.types.isSealed()) {
        base.invariant("a checked artifact was published from a module whose type store checking never sealed", .{});
    }
    const idents = module.identStoreConst();

    var canonical_names = canonical.CanonicalNameStore.init(allocator);
    // The artifact owns the name store and the type store once it is formed:
    // its slots grow them from then on.
    var stores_moved = false;
    errdefer if (!stores_moved) canonical_names.deinit();
    const module_name = try canonical_names.internModuleName(module_env.module_name);
    const display_module_name = try canonical_names.internModuleIdent(idents, module_env.display_module_name_idx);
    const module_identity = ModuleIdentity{
        .stable_hash = computeStableModuleIdentityHash(module_env),
        .module_idx = module_idx,
        .module_name = module_name,
        .display_module_name = display_module_name,
        .kind = module_env.module_kind,
    };
    // Intern this module's content identity up front so later publication
    // steps (e.g. interface capability collection) can resolve it by lookup.
    _ = try canonical_names.internModuleIdentity(&module_identity.stable_hash);

    try internLoweringVisibleNames(module_env, &canonical_names);
    _ = try canonical_names.internTagLabel("#Missing");
    _ = try canonical_names.internTagLabel("#Present");

    var platform_required_declarations = try PlatformRequiredDeclarationTable.fromModule(allocator, module, &canonical_names);
    errdefer platform_required_declarations.deinit(allocator);

    var checking_context_identity = try CheckingContextIdentity.fromModule(
        allocator,
        module_env,
        inputs.imports,
        inputs.platform_requirement_context,
        if (inputs.platform_app_relation) |relation| relation.key else null,
        inputs.explicit_roots,
        inputs.validation,
    );
    errdefer checking_context_identity.deinit(allocator);

    const direct_import_module_keys = try directImportArtifactKeysFromModule(allocator, module_env, inputs.imports);
    errdefer allocator.free(direct_import_module_keys);
    const source_hash = hashModuleSourceInputs(module_env);
    const artifact_key = CheckedModuleArtifactKey.computeFromSourceHash(
        source_hash,
        module_identity,
        checking_context_identity,
        direct_import_module_keys,
    );

    const exports = try collectPublishedExportDefs(allocator, module);
    const export_binders = try collectPublishedExportBinders(allocator, module);
    defer allocator.free(export_binders);
    errdefer allocator.free(exports);

    const provides = try publishProvidesMetadata(allocator, module, &canonical_names);
    errdefer allocator.free(provides);

    const owner_artifact = artifact_key.digest();

    const promoted_local_procedures = module_env.promoted_local_procedures.items.items;
    const requirement_solutions = module_env.platform_requirement_solutions.items.items;
    const selected_hoisted_roots = try selectHoistedRoots(allocator, module_env, inputs.hoisted_roots);
    defer allocator.free(selected_hoisted_roots);
    const analyses = try BodyAnalyses.create(allocator, inputs.io, module_env, promoted_local_procedures);
    var analyses_owned = true;
    errdefer if (analyses_owned) analyses.destroy();
    const module_index = &analyses.index;
    const module_analyses = try ModuleAnalyses.create(allocator, inputs.io, null);
    var module_analyses_owned = true;
    errdefer if (module_analyses_owned) module_analyses.destroy();
    const import_views = CheckedImportViews{ .current_owner = artifact_key.digest(), .direct = inputs.imports, .available = inputs.available_artifacts, .relations = inputs.relation_artifacts };
    // Publication reads the nominal representations of the types of every
    // module it imports or resolves against.
    for (inputs.imports) |import| _ = try import.view.checked_types.interfaceCapabilities(import_views.resolver());
    for (inputs.available_artifacts) |available| _ = try available.checked_types.interfaceCapabilities(import_views.resolver());
    for (inputs.relation_artifacts) |relation| _ = try relation.checked_types.interfaceCapabilities(import_views.resolver());
    const dispatch_view_keys = try dispatchViewKeys(allocator, module_analyses, import_views);
    errdefer allocator.free(dispatch_view_keys);

    // Omitted defaults name their fields and origin modules through the
    // module's names.
    for (module_env.record_omitted_defaults.items.items) |omitted| {
        _ = try canonical_names.internRecordFieldIdent(idents, omitted.field_name);
        _ = try canonical_names.internModuleIdentity(module_env.moduleIdentityHash(omitted.origin_module));
    }

    const sealed_keys = try sealed_type_keys.SealedTypeKeys.create(allocator, inputs.io, module_env);
    var sealed_keys_owned = true;
    errdefer if (sealed_keys_owned) sealed_keys.destroy();
    var checked_type_publication = try CheckedTypeStore.fromModule(allocator, module, &canonical_names, artifact_key.digest(), inputs.imports, inputs.available_artifacts, module_index, selected_hoisted_roots, promoted_local_procedures, sealed_keys);
    defer checked_type_publication.deinitIndex(allocator);
    errdefer if (!stores_moved) checked_type_publication.store.deinit(allocator);
    const checked_types = &checked_type_publication.store;
    const requires = try publishRequiresMetadata(allocator, module, &canonical_names, &checked_type_publication);
    errdefer allocator.free(requires);
    var platform_type_inputs = try PlatformTypeInputs.fromModule(allocator, module, &canonical_names, &checked_type_publication, &platform_required_declarations);
    errdefer platform_type_inputs.deinit(allocator);

    // Both relation readings consume the requirement's platform-owned
    // identity formals, so they run before the publication is resolved
    // through the relation.
    var platform_requirement_relations = try PlatformRequirementRelationTable.fromRelation(
        allocator,
        allocator,
        module_identity,
        &canonical_names,
        &checked_type_publication.store,
        &platform_required_declarations,
        inputs.relation_artifacts,
        inputs.platform_app_relation,
    );
    errdefer platform_requirement_relations.deinit(allocator);
    {
        var relation_type_substitutions = try PlatformRelationTypeSubstitutions.fromRelation(
            allocator,
            module_identity,
            &canonical_names,
            &checked_type_publication.store,
            &platform_required_declarations,
            &platform_type_inputs,
            inputs.relation_artifacts,
            inputs.platform_app_relation,
        );
        defer relation_type_substitutions.deinit(allocator);
        try relation_type_substitutions.applyToPublication(allocator, &checked_type_publication);
    }
    var pairing_types = try publicationPairingTypes(allocator, &checked_type_publication);
    errdefer pairing_types.deinit(allocator);
    const default_exprs = try publicationDefaultExprs(allocator, module, &canonical_names, &checked_type_publication);
    defer allocator.free(default_exprs);
    const body_tables = checked_bodies_mod.Tables{
        .module = owner_artifact,
        .pairing_types = if (pairing_types.images.len != 0) &pairing_types else null,
    };

    const value_binding_defs = module_env.store.sliceDefs(module_env.value_binding_defs);

    var intrinsic_wrappers = IntrinsicWrapperTable{};
    errdefer intrinsic_wrappers.deinit(allocator);

    var checked_procedure_templates = try CheckedProcedureTemplateTable.fromModule(
        allocator,
        module,
        value_binding_defs,
        &canonical_names,
        owner_artifact,
        &checked_type_publication,
        module_index,
        &intrinsic_wrappers,
    );
    errdefer checked_procedure_templates.deinit(allocator);
    try checked_procedure_templates.appendPromotedLocalProcedures(
        allocator,
        module,
        &canonical_names,
        owner_artifact,
        &checked_type_publication,
        module_index,
        promoted_local_procedures,
    );
    const template_lookup = checked_procedure_templates.asLookup(module_idx);

    var method_registry = try static_dispatch.MethodRegistry.fromModule(
        allocator,
        module,
        &canonical_names,
        &template_lookup,
        &checked_type_publication,
        module_index,
    );
    errdefer method_registry.deinit(allocator);
    checked_type_publication.finishSourceTypes();

    var static_dispatch_plans = try static_dispatch.StaticDispatchPlanTable.fromModule(
        allocator,
        module,
        &canonical_names,
        &checked_type_publication,
        publicationBodies(module_env, &canonical_names, &checked_type_publication, analyses, body_tables),
    );
    errdefer static_dispatch_plans.deinit(allocator);

    var hosted_procs = try HostedProcTable.fromModule(
        allocator,
        module,
        module_env.store.sliceDefs(module_env.hosted_defs),
        &canonical_names,
        &checked_procedure_templates,
    );
    errdefer hosted_procs.deinit(allocator);

    var hosted_bindings = try HostedBindingTable.fromModule(allocator, module, &canonical_names, inputs.imports, artifact_key, &hosted_procs);
    errdefer hosted_bindings.deinit(allocator);

    var platform_required_bindings = try PlatformRequiredBindingTable.fromRelation(
        allocator,
        module_identity,
        &canonical_names,
        checked_types.view(),
        &platform_required_declarations,
        &platform_requirement_relations,
        inputs.platform_app_relation,
    );
    errdefer platform_required_bindings.deinit(allocator);

    var compile_time_roots = try CompileTimeRootTable.fromModule(
        allocator,
        module,
        value_binding_defs,
        selected_hoisted_roots,
        inputs.explicit_roots,
        &checked_type_publication,
        module_index,
        &checked_procedure_templates,
    );
    errdefer compile_time_roots.deinit(allocator);

    var checked_const_bodies = try CheckedConstBodyTable.fromRoots(allocator, &compile_time_roots);
    errdefer checked_const_bodies.deinit(allocator);

    var entry_wrappers = EntryWrapperTable{};
    errdefer entry_wrappers.deinit(allocator);
    try checked_procedure_templates.appendEntryWrappersForRoots(
        allocator,
        module,
        &canonical_names,
        owner_artifact,
        checked_types,
        &entry_wrappers,
        compile_time_roots.roots,
    );

    var checked_const_store = ConstStore.init(allocator);
    errdefer checked_const_store.deinit();

    var top_level_procedure_bindings = TopLevelProcedureBindingTable.initEmpty();
    errdefer top_level_procedure_bindings.deinit(allocator);

    var callable_eval_templates = CallableEvalTemplateTable{};
    errdefer callable_eval_templates.deinit(allocator);

    var const_templates = ConstTemplateTable{};
    errdefer const_templates.deinit(allocator);

    var top_level_values = try TopLevelValueTable.fromModule(
        allocator,
        module,
        value_binding_defs,
        &canonical_names,
        module_index,
        &checked_procedure_templates,
        &callable_eval_templates,
        &top_level_procedure_bindings,
        &const_templates,
        artifact_key,
        &compile_time_roots,
        &checked_type_publication,
    );
    errdefer top_level_values.deinit(allocator);

    var hoisted_constants = try HoistedConstTable.fromRoots(
        allocator,
        module,
        artifact_key,
        checked_types,
        &compile_time_roots,
        &const_templates,
        &checked_type_publication,
    );
    errdefer hoisted_constants.deinit(allocator);

    var selected_hoisted_callables = try SelectedHoistedCallableTable.fromRoots(
        allocator,
        module,
        &compile_time_roots,
        &callable_eval_templates,
        &top_level_procedure_bindings,
        &checked_type_publication,
        checked_procedure_templates.promoted,
    );
    defer selected_hoisted_callables.deinit(allocator);

    var resolved_value_refs = try ResolvedValueRefTable.fromModule(
        allocator,
        modules,
        module_idx,
        artifact_key,
        inputs.imports,
        inputs.available_artifacts,
        &checked_procedure_templates,
        &hosted_procs,
        &platform_required_declarations,
        &platform_required_bindings,
        &top_level_values,
        &selected_hoisted_callables,
        &hoisted_constants,
        &checked_type_publication,
        module_index,
    );
    errdefer resolved_value_refs.deinit(allocator);
    var resolved_tables = body_tables;
    resolved_tables.refs = &resolved_value_refs;
    publishCallableEvalForwarding(
        &callable_eval_templates,
        publicationBodies(module_env, &canonical_names, &checked_type_publication, analyses, resolved_tables),
        &resolved_value_refs,
        &compile_time_roots,
        artifact_key,
        &top_level_procedure_bindings,
        inputs.imports,
        inputs.available_artifacts,
        inputs.relation_artifacts,
    );
    try publishRetiredExprs(
        allocator,
        module_env,
        module_index,
        &resolved_value_refs,
        artifact_key,
        &top_level_procedure_bindings,
        &callable_eval_templates,
        &compile_time_roots,
        inputs.imports,
        inputs.available_artifacts,
        inputs.relation_artifacts,
    );
    resolved_tables.plans = &static_dispatch_plans;
    var ordinary_diagnostics = try body_analyses.diagnosticErrors(
        allocator,
        publicationBodies(module_env, &canonical_names, &checked_type_publication, analyses, resolved_tables),
        .ordinary,
    );
    defer ordinary_diagnostics.deinit(allocator);

    try sealCheckedProcedureTemplateRefs(
        allocator,
        module,
        &checked_type_publication,
        publicationBodies(module_env, &canonical_names, &checked_type_publication, analyses, resolved_tables),
        &ordinary_diagnostics,
        default_exprs,
        &compile_time_roots,
        &entry_wrappers,
        &checked_procedure_templates,
        &static_dispatch_plans,
        &method_registry,
        &resolved_value_refs,
    );

    var provided_exports = try ProvidedExportTable.fromModule(
        allocator,
        module,
        &checked_type_publication,
        &top_level_values,
        provides,
    );
    errdefer provided_exports.deinit(allocator);

    sealConstEvalTemplatesForRoots(
        &const_templates,
        &compile_time_roots,
        &checked_const_bodies,
        &entry_wrappers,
        &checked_procedure_templates,
        &top_level_values,
        &hoisted_constants,
    );

    var evaluation_diagnostics = if (module_env.module_kind == .platform and inputs.problem_store != null)
        try EvaluationDiagnostics.fromStore(allocator, inputs.problem_store.?)
    else
        EvaluationDiagnostics{};
    errdefer evaluation_diagnostics.deinit(allocator);

    var exported_procedure_templates = try ExportedProcedureTemplateTable.fromModule(
        allocator,
        &checked_procedure_templates,
        module,
        exports,
        &canonical_names,
        &checked_type_publication,
    );
    errdefer exported_procedure_templates.deinit(allocator);

    var exported_procedure_bindings = try ExportedProcedureBindingTable.fromModule(
        allocator,
        artifact_key,
        &top_level_procedure_bindings,
        module,
        exports,
        export_binders,
        module_index,
        &selected_hoisted_callables,
        &top_level_values,
    );
    errdefer exported_procedure_bindings.deinit(allocator);

    var exported_const_templates = try ExportedConstTemplateTable.fromModule(
        allocator,
        &const_templates,
        module,
        exports,
        export_binders,
        module_index,
        &top_level_values,
        &hoisted_constants,
    );
    errdefer exported_const_templates.deinit(allocator);

    var platform_requirement_solutions = try platformRequirementSolutionTableFromInputs(
        allocator,
        module,
        checked_types,
        &top_level_values,
        &exported_procedure_bindings,
        &exported_const_templates,
        requirement_solutions,
    );
    errdefer platform_requirement_solutions.deinit(allocator);

    // All source-to-checked metadata has been consumed. Release its scratch
    // before compile-time evaluation can allocate specialization/backend data.
    checked_type_publication.deinitIndex(allocator);
    checked_types.markPublished();
    checked_types.releaseSuperseded(allocator);

    var artifact = CheckedModuleArtifact{
        .key = artifact_key,
        .source_hash = source_hash,
        .canonical_names = canonical_names,
        .module_identity = module_identity,
        .checking_context_identity = checking_context_identity,
        .direct_import_module_keys = direct_import_module_keys,
        .dispatch_view_keys = dispatch_view_keys,
        .module_env = inputs.module_env_storage,
        .exports = .{ .defs = exports },
        .checked_types = checked_types.*,
        .pairing_types = pairing_types,
        .evaluation_diagnostics = evaluation_diagnostics,
        .checked_const_bodies = checked_const_bodies,
        .exported_procedure_templates = exported_procedure_templates,
        .exported_procedure_bindings = exported_procedure_bindings,
        .exported_const_templates = exported_const_templates,
        .provides_requires = .{
            .provides = provides,
            .requires = requires,
        },
        .provided_exports = provided_exports,
        .method_registry = method_registry,
        .static_dispatch_plans = static_dispatch_plans,
        .resolved_value_refs = resolved_value_refs,
        .checked_procedure_templates = checked_procedure_templates,
        .entry_wrappers = entry_wrappers,
        .intrinsic_wrappers = intrinsic_wrappers,
        .top_level_procedure_bindings = top_level_procedure_bindings,
        .callable_eval_templates = callable_eval_templates,
        .hosted_procs = hosted_procs,
        .hosted_bindings = hosted_bindings,
        .platform_required_declarations = platform_required_declarations,
        .platform_type_inputs = platform_type_inputs,
        .platform_requirement_relations = platform_requirement_relations,
        .platform_requirement_solutions = platform_requirement_solutions,
        .platform_required_bindings = platform_required_bindings,
        .compile_time_roots = compile_time_roots,
        .top_level_values = top_level_values,
        .hoisted_constants = hoisted_constants,
        .const_templates = const_templates,
        .const_store = checked_const_store,
        .evaluation_state = .prepared,
        .body_analyses = analyses,
        .module_analyses = module_analyses,
    };
    // The artifact owns the key slots from here on, and its views name its
    // own name store (`typesView`). It owns the body analyses once it is
    // returned.
    sealed_keys_owned = false;
    artifact.checked_types.key_names = null;
    // Other threads read the module's names from here on, while its
    // analyses intern into them, exactly as they read its types.
    artifact.canonical_names.markPublished();
    artifact.attachCapabilitySource();
    stores_moved = true;
    errdefer {
        if (artifact.checked_types.sealed_keys) |keys| keys.destroy();
        artifact.checked_types.deinit(allocator);
        artifact.canonical_names.deinit();
    }
    artifact.finishPublication();
    checked_const_store = ConstStore.init(allocator);
    errdefer artifact.const_store.deinit();
    errdefer artifact.literal_root_payloads.deinit(allocator);

    if (inputs.evaluation_phase == .immediate) {
        try inputs.compile_time_finalizer.run(
            allocator,
            &artifact,
            inputs.imports,
            inputs.available_artifacts,
            inputs.relation_artifacts,
            inputs.problem_store,
        );
        artifact.evaluation_state = .finalized;
        try artifact.verifyComplete();
    }
    analyses_owned = false;
    module_analyses_owned = false;
    return artifact;
}

const ProvidedExportKindExpectation = struct {
    procedure_roots: usize,
    deferred_procedure_roots: usize = 0,
    data_exports: usize,
    procedure_exports: usize,
};

fn expectProvidedExportKind(
    source: []const u8,
    expected: ProvidedExportKindExpectation,
) (@import("test/TestEnv.zig").TestEnvError || CompileTimeFinalizer.Error || error{ CorruptArtifact, CorruptBuiltinArtifact, BuiltinArtifactVersionMismatch })!void {
    const TestEnv = @import("test/TestEnv.zig");
    const compiled_builtins = @import("compiled_builtins");
    const allocator = std.testing.allocator;

    var test_env = try TestEnv.init("PlatformDataExportTest", source);
    defer test_env.deinit();
    try test_env.assertNoErrors();

    // The baked builtin artifact is the published form of the builtin module
    // `test_env` checked against, so it serves as the real direct import.
    const blob = compiled_builtins.builtin_artifact_bin[0..];
    const serialized_bytes = try CheckedModuleArtifact.splitVersionTrailer(blob);
    const backing: []align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8 =
        @alignCast(blob[0..serialized_bytes.len]);
    const serialized: *const CheckedModuleArtifact.Serialized = @ptrCast(@alignCast(backing.ptr));
    try serialized.validate(backing.len);
    var builtin_artifact = serialized.deserializeStatic(backing, allocator, .{ .static_builtin = test_env.builtin_module.env });
    try builtin_artifact.attachSealedTypes(allocator, std.testing.io);
    defer builtin_artifact.deinitRetainingModuleEnv(allocator);

    const sources = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = test_env.builtin_module.env },
        .{ .precompiled = test_env.module_env },
    };
    var modules = try TypedCIR.Modules.init(allocator, &sources);
    defer modules.deinit();
    const imports = [_]PublishImportArtifact{.{
        .module_idx = 0,
        .key = builtin_artifact.key,
        .view = importedView(&builtin_artifact),
    }};

    const NoFinalization = struct {
        fn finalize(
            _: ?*anyopaque,
            _: Allocator,
            _: *CheckedModuleArtifact,
            _: []const PublishImportArtifact,
            _: []const ImportedModuleView,
            _: []const ImportedModuleView,
            _: ?*problem.Store,
        ) CompileTimeFinalizer.Error!void {}
    };
    // Prepared metadata is enough: the root and export tables are published
    // before any compile-time evaluation runs.
    var artifact = try publishFromTypedModule(allocator, &modules, 1, .{
        .io = std.testing.io,
        .module_env_storage = .{ .checked_source = test_env.module_env },
        .hoisted_roots = .none,
        .imports = &imports,
        .compile_time_finalizer = .{ .finalize = &NoFinalization.finalize },
        .evaluation_phase = .post_frontend,
    });
    defer artifact.deinitRetainingModuleEnv(allocator);

    var provided_runtime_roots: usize = 0;
    for ((try artifact.rootRequests()).runtime_requests) |root| {
        if (root.kind == .provided_export) provided_runtime_roots += 1;
    }
    var deferred_procedure_roots: usize = 0;
    for ((try artifact.rootRequests()).requests) |root| {
        if (root.kind == .provided_export and root.requires_pairing) deferred_procedure_roots += 1;
    }
    try std.testing.expectEqual(expected.deferred_procedure_roots, deferred_procedure_roots);

    var provided_data_exports: usize = 0;
    var provided_procedure_exports: usize = 0;
    for (artifact.provided_exports.exports) |provided| {
        switch (provided) {
            .data => provided_data_exports += 1,
            .procedure => provided_procedure_exports += 1,
        }
    }

    try std.testing.expectEqual(expected.procedure_roots, provided_runtime_roots);
    try std.testing.expectEqual(expected.data_exports, provided_data_exports);
    try std.testing.expectEqual(expected.procedure_exports, provided_procedure_exports);
}

