test "lowering visibility follows recursive public API and type-owner dependencies deterministically" {
    const gpa = std.testing.allocator;

    var env_root = try ModuleEnv.init(gpa, "");
    defer env_root.deinit();
    var env_a = try ModuleEnv.init(gpa, "");
    defer env_a.deinit();
    var env_b = try ModuleEnv.init(gpa, "");
    defer env_b.deinit();
    var env_c = try ModuleEnv.init(gpa, "");
    defer env_c.deinit();
    var env_d = try ModuleEnv.init(gpa, "");
    defer env_d.deinit();
    var env_e = try ModuleEnv.init(gpa, "");
    defer env_e.deinit();
    var env_builtin = try ModuleEnv.init(gpa, "");
    defer env_builtin.deinit();
    env_builtin.module_role = .builtin;

    const root_key = testCheckedModuleKey(0xF0);
    const key_a = testCheckedModuleKey(0x05);
    const key_b = testCheckedModuleKey(0x01);
    const key_c = testCheckedModuleKey(0x03);
    const key_d = testCheckedModuleKey(0x02);
    const key_e = testCheckedModuleKey(0x04);
    const key_builtin = testCheckedModuleKey(0x06);

    const root_public = [_]ModuleId{key_b.digest()};
    const root_type_owners = [_]ModuleId{key_c.digest()};
    const a_public = [_]ModuleId{ key_c.digest(), key_builtin.digest() };
    const a_type_owners = [_]ModuleId{key_e.digest()};
    const d_type_owners = [_]ModuleId{key_b.digest()};

    const analyses = [_]*ModuleAnalyses{
        try testPublishedModuleAnalyses(gpa, .{ .artifacts = &root_public, .type_owner_artifacts = &root_type_owners }),
        try testPublishedModuleAnalyses(gpa, .{ .artifacts = &a_public, .type_owner_artifacts = &a_type_owners }),
        try testPublishedModuleAnalyses(gpa, .{}),
        try testPublishedModuleAnalyses(gpa, .{}),
        try testPublishedModuleAnalyses(gpa, .{ .type_owner_artifacts = &d_type_owners }),
        try testPublishedModuleAnalyses(gpa, .{}),
        try testPublishedModuleAnalyses(gpa, .{}),
    };
    defer for (analyses) |module_analyses| module_analyses.destroy();

    const views = [_]ImportedModuleView{
        testVisibilityImportedView(key_a, &env_a, analyses[1]),
        testVisibilityImportedView(key_b, &env_b, analyses[2]),
        testVisibilityImportedView(key_c, &env_c, analyses[3]),
        testVisibilityImportedView(key_d, &env_d, analyses[4]),
        testVisibilityImportedView(key_e, &env_e, analyses[5]),
        testVisibilityImportedView(key_builtin, &env_builtin, analyses[6]),
    };

    const checked_types = CheckedTypeStore{};
    // The owner's root requests are empty.
    const root_requests = try gpa.create(RootRequestTable);
    root_requests.* = .{};
    std.debug.assert(analyses[0].root_requests.acquire(std.testing.io) == .claimed);
    analyses[0].root_requests.publish(std.testing.io, root_requests);
    const platform_required_bindings = PlatformRequiredBindingTable{};
    const direct_imports = [_]CheckedModuleArtifactKey{ key_d, key_a, key_a, key_builtin };
    var owner = testVisibilityImportedView(root_key, &env_root, analyses[0]);
    owner.direct_import_module_keys = &direct_imports;
    owner.checked_types = checked_types.view();
    owner.platform_required_bindings = &platform_required_bindings;
    owner.exported_procedure_templates = .{};
    owner.exported_procedure_bindings = .{};
    owner.exported_const_templates = .{};

    const resolver_views = CheckedImportViews{ .current_owner = root_key.digest(), .direct = &.{}, .available = &views };
    var visibility = try computeLoweringVisibility(gpa, owner, resolver_views.resolver());
    defer visibility.deinit(gpa);

    const expected = [_]CheckedModuleArtifactKey{ key_b, key_d, key_c, key_e, key_a };
    try std.testing.expectEqual(@as(usize, expected.len), visibility.module_ids.len);
    for (expected, visibility.module_ids) |want, got| {
        try std.testing.expectEqualSlices(u8, &want.bytes, &got.bytes);
    }
}

test "CheckingContextIdentity serialize/deserialize round-trip (slices + optionals)" {
    const gpa = std.testing.allocator;
    const imports = try gpa.alloc(ImportIdentity, 2);
    defer gpa.free(imports);
    artifact_serialize.poisonSlice(ImportIdentity, imports, 0x5A);
    artifact_serialize.zeroSlicePadding(ImportIdentity, imports);
    const roots = try gpa.alloc(ExplicitRootRequestInput, 3);
    defer gpa.free(roots);
    artifact_serialize.poisonSlice(ExplicitRootRequestInput, roots, 0x3C);
    artifact_serialize.zeroSlicePadding(ExplicitRootRequestInput, roots);

    var prc: PlatformRequirementContextKey = undefined;
    @memset(std.mem.asBytes(&prc), 0x77);
    // Canonicalize padding to match the deterministic serializer.
    collections.CompactWriter.zeroValuePadding(PlatformRequirementContextKey, @as([*]u8, @ptrCast(&prc)));

    const ident = CheckingContextIdentity{
        .imports = imports,
        .explicit_roots = roots,
        .platform_requirement_context = prc, // present
        .platform_app_relation = null, // absent
    };

    const rt = try artifact_serialize.roundTripForTest(gpa, CheckingContextIdentity, &ident);
    defer gpa.free(rt.buffer);
    try artifact_serialize.expectSlicesByteEqual(ImportIdentity, ident.imports, rt.loaded.imports);
    try artifact_serialize.expectSlicesByteEqual(ExplicitRootRequestInput, ident.explicit_roots, rt.loaded.explicit_roots);
    try std.testing.expect(rt.loaded.platform_requirement_context != null);
    try std.testing.expectEqualSlices(u8, std.mem.asBytes(&prc), std.mem.asBytes(&rt.loaded.platform_requirement_context.?));
    try std.testing.expectEqual(@as(?PlatformAppRelationKey, null), rt.loaded.platform_app_relation);
}

